/// Preset motywu UI: akcent + tła + preferowany tryb jasny/ciemny.
/// Każdy motyw ma PEŁNĄ paletę dnia i nocy (tryb nocny działa poprawnie z
/// każdym motywem, nie tylko z „jego" preferowanym) oraz własny wzór tła.
class TrainerThemeStyle {
  const TrainerThemeStyle({
    required this.id,
    required this.name,
    required this.description,
    required this.accent,
    required this.preferDark,
    this.scaffoldDark,
    this.cardDark,
    this.scaffoldLight,
    this.cardLight,
    this.secondaryAccent,
    this.backgroundStyle = 'sport',
  });

  final String id;
  final String name;
  final String description;
  final int accent;

  /// Czy motyw po wybraniu włącza tryb ciemny (użytkownik może to potem zmienić).
  final bool preferDark;

  final int? scaffoldDark;
  final int? cardDark;
  final int? scaffoldLight;
  final int? cardLight;

  /// Drugi akcent motywu (używany przez tło motywu i gradienty).
  final int? secondaryAccent;

  /// Wzór dekoracyjnego TŁA MOTYWU (patrz [TrainerThemedBackgroundPainter]).
  final String backgroundStyle;
}

