TrainerThemeStyle themeStyleById(String id) {
  for (final style in kTrainerThemeStyles) {
    if (style.id == id) return style;
  }
  return kTrainerThemeStyles.first;
}

/// Normalizuje zapisany układ kafelków do znanych wartości.
String normalizeTileLayout(String value) {
  switch (value) {
    case 'grid':
    case 'compact':
      return value;
    default:
      return 'list';
  }
}

/// Mnożnik zaokrągleń wynikający z ustawień (sharp/soft/round).
double _cornerScaleFor(String cornerStyle) {
  switch (cornerStyle) {
    case 'sharp':
      return 0.55;
    case 'round':
      return 1.3;
    default:
      return 1.0;
  }
}

/// Promień zaokrąglenia elementu z uwzględnieniem personalizacji użytkownika.
double uiCornerRadius(BuildContext context, double base) {
  final scope = context
      .getElementForInheritedWidgetOfExactType<AppScope>()
      ?.widget as AppScope?;
  final style = scope?.notifier?.settings.cornerStyle ?? 'soft';
  return base * _cornerScaleFor(style);
}

String normalizeLevel(String value) {
  final v = value.trim().toLowerCase();
  // „śred" MUSI być sprawdzone przed „zaaw": słowo „średnioza(zaaw)ansowany"
  // zawiera podciąg „zaaw", więc sprawdzenie zaawansowanego jako pierwsze
  // błędnie klasyfikowało średniozaawansowanego jako zaawansowanego (przez
  // copyWith psuło to poziom KAŻDEGO średniozaawansowanego ćwiczenia).
  if (v.contains('śred') ||
      v.contains('sred') ||
      v.contains('inter') ||
      v.contains('mid')) return 'Średniozaawansowany';
  if (v.contains('zaaw')) return 'Zaawansowany';
  return 'Początkujący';
}

String normalizeTrainingMode(String value) {
  final v = value.trim().toLowerCase();
  if (v.contains('redu')) return 'Redukcja';
  if (v.contains('masa') || v.contains('bulk')) return 'Masa';
  if (v.contains('kond') || v.contains('wydol')) return 'Kondycja';
  return 'Rekompozycja';
}

String stripHtml(String input) {
  return input
      .replaceAll(RegExp(r'<[^>]*>'), ' ')
      .replaceAll('&nbsp;', ' ')
      .replaceAll('&amp;', '&')
      .replaceAll('&quot;', '"')
      .replaceAll('&#39;', "'")
      .replaceAll(RegExp(r'\s+'), ' ')
      .trim();
}

void main() {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const FitnessApp());
}

class FitnessApp extends StatefulWidget {
  const FitnessApp({super.key});

  @override
  State<FitnessApp> createState() => _FitnessAppState();
}

class _FitnessAppState extends State<FitnessApp> with WidgetsBindingObserver {
  late final AppStore store;
  bool loaded = false;
  Timer? _autoSyncTimer;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    store = AppStore();
    // Inicjalizacja konta/chmury (Firebase) w tle — bezpieczna: brak
    // konfiguracji Firebase zostawia aplikację w trybie lokalnym.
    unawaited(trainerAccountService.init());
    store.load().then((_) {
      if (mounted) setState(() => loaded = true);
      // Automatyczna synchronizacja przy starcie (w tle, bez blokowania UI).
      unawaited(store.autoSyncHealthConnect(force: true));
      // Dzienna kopia w chmurze przy starcie — po dokończeniu inicjalizacji
      // konta (init jest memoizowany) i po wczytaniu danych. ODROCZONA o 30 s,
      // żeby budowa pełnego eksportu (jsonEncode) nie ścinała startu aplikacji.
      unawaited(
        Future<void>.delayed(const Duration(seconds: 30), () async {
          await trainerAccountService.init();
          await trainerAccountService.autoBackupDailyIfNeeded(
            () => buildFullExport(store),
          );
        }),
      );
    });
    // Okresowe odświeżanie, dopóki aplikacja jest otwarta.
    _autoSyncTimer = Timer.periodic(const Duration(minutes: 15), (_) {
      unawaited(store.autoSyncHealthConnect());
    });
  }

  @override
  void dispose() {
    _autoSyncTimer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // Aplikacja schodzi z pierwszego planu → zatrzymaj trening (czasu w tle NIE
    // liczymy jako aktywny wysiłek). Wywołanie synchroniczne mutuje stan i
    // utrwala go — nawet gdy proces zostanie potem zabity.
    if (loaded &&
        (state == AppLifecycleState.paused ||
            state == AppLifecycleState.inactive ||
            state == AppLifecycleState.hidden)) {
      unawaited(store.markWorkoutBackgrounded());
    }
    // Powrót aplikacji na pierwszy plan → dociągnij świeże dane zdrowia.
    if (state == AppLifecycleState.resumed && loaded) {
      unawaited(store.markWorkoutForegrounded());
      unawaited(store.autoSyncHealthConnect());
      // Dzienna kopia w chmurze przy powrocie do aplikacji (raz na dobę).
      // Z opóźnieniem — nie ścinamy animacji powrotu na pierwszy plan.
      unawaited(
        Future<void>.delayed(
          const Duration(seconds: 10),
          () => trainerAccountService.autoBackupDailyIfNeeded(
            () => buildFullExport(store),
          ),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    if (!loaded) {
      // Splash tylko na czas realnego wczytywania danych (AppStore.load) —
      // znika automatycznie, bez sztucznego opóźniania startu.
      return MaterialApp(
        debugShowCheckedModeBanner: false,
        theme: buildTheme(Colors.teal, false),
        darkTheme: buildTheme(Colors.teal, true),
        home: const TrainerSplashScreen(),
      );
    }

    return AppScope(
      store: store,
      child: AnimatedBuilder(
        animation: store,
        builder: (context, _) {
          final accent = Color(store.settings.accentColorValue);
          return MaterialApp(
            debugShowCheckedModeBanner: false,
            title: kAppName,
            theme: buildTheme(accent, false, settings: store.settings),
            darkTheme: buildTheme(accent, true, settings: store.settings),
            themeMode:
                store.settings.darkMode ? ThemeMode.dark : ThemeMode.light,
            builder: (context, child) {
              if (child == null) return const SizedBox.shrink();
              // Tło całej aplikacji (za wszystkimi ekranami). Priorytet:
              // własne zdjęcie → TŁO MOTYWU (wzór z palety) → gradient.
              final Widget? bgImage =
                  trainerBackgroundImageLayer(store.settings);
              if (bgImage != null) {
                return Stack(
                  fit: StackFit.expand,
                  children: [bgImage, child],
                );
              }
              final Widget? themedBg = trainerThemedBackgroundLayer(
                store.settings,
                store.settings.darkMode,
              );
              if (themedBg != null) {
                return Stack(
                  fit: StackFit.expand,
                  children: [themedBg, child],
                );
              }
              if (!store.settings.backgroundGradient) return child;
              return DecoratedBox(
                decoration: BoxDecoration(
                  gradient: trainerScaffoldGradient(
                    store.settings,
                    store.settings.darkMode,
                  ),
                ),
                child: child,
              );
            },
            home: const TrainerAuthGate(),
          );
        },
      ),
    );
  }
}

double _trainerGradientStrength(String strength) {
  switch (strength) {
    case 'subtle':
      return 0.75;
    case 'strong':
      return 2.4;
    case 'max':
      return 3.6;
    default:
      return 1.4;
  }
}

Gradient _trainerGradientForStyle(
  String style,
  List<Color> colors, {
  List<double>? stops,
}) {
  switch (style) {
    case 'vertical':
      return LinearGradient(
        colors: colors,
        stops: stops,
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
      );
    case 'radial':
      return RadialGradient(
        colors: colors,
        stops: stops,
        center: const Alignment(-0.2, -0.6),
        radius: 1.25,
      );
    default:
      return LinearGradient(
        colors: colors,
        stops: stops,
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
      );
  }
}

/// Gradient tła całej aplikacji Trainera (gdy włączone „gradientowe tło").
/// Delikatnie tonuje kolor tła akcentem; siła i kierunek z personalizacji.
Gradient trainerScaffoldGradient(AppSettings settings, bool dark) {
  final style = themeStyleById(settings.themeStyleId);
  final Color base = dark
      ? Color(style.scaffoldDark ?? 0xFF0D1117)
      : Color(style.scaffoldLight ?? 0xFFF6F8FA);
  final Color accent = Color(settings.accentColorValue);
  final double k = _trainerGradientStrength(settings.gradientStrength);
  final Color top =
      Color.lerp(base, accent, ((dark ? 0.20 : 0.12) * k).clamp(0.0, 0.72)) ??
          base;
  final Color bottom =
      Color.lerp(base, accent, ((dark ? 0.09 : 0.05) * k).clamp(0.0, 0.55)) ??
          base;
  return _trainerGradientForStyle(
    settings.gradientStyle,
    <Color>[top, base, bottom],
    stops: const <double>[0.0, 0.55, 1.0],
  );
}

/// Warstwa TŁA MOTYWU: dekoracyjny, proceduralny wzór rysowany z kolorów
/// aktualnego motywu (odpowiednik „zdjęcia jako tła", ale bez pliku —
/// automatycznie dopasowuje się do trybu dnia/nocy). Zwraca null, gdy tło
/// motywu jest wyłączone albo użytkownik wybrał własne zdjęcie.
Widget? trainerThemedBackgroundLayer(AppSettings settings, bool dark) {
  if (!settings.themedBackground) return null;
  if (settings.backgroundImagePath.trim().isNotEmpty) return null;
  final style = themeStyleById(settings.themeStyleId);
  final Color base = dark
      ? Color(style.scaffoldDark ?? 0xFF0D1117)
      : Color(style.scaffoldLight ?? 0xFFF6F8FA);
  return RepaintBoundary(
    child: CustomPaint(
      painter: TrainerThemedBackgroundPainter(
        styleId: style.backgroundStyle,
        background: base,
        primary: Color(settings.accentColorValue),
        secondary: Color(style.secondaryAccent ?? style.accent),
        strength: _trainerGradientStrength(settings.gradientStrength)
            .clamp(0.75, 2.4),
      ),
      size: Size.infinite,
    ),
  );
}

/// Maluje tło motywu: poświaty, fale, linie, siatkę albo „gwiazdy" w kolorach
/// palety. Deterministyczne i tanie (kilka gradientów pod RepaintBoundary).
class TrainerThemedBackgroundPainter extends CustomPainter {
  const TrainerThemedBackgroundPainter({
    required this.styleId,
    required this.background,
    required this.primary,
    required this.secondary,
    required this.strength,
  });

  final String styleId;
  final Color background;
  final Color primary;
  final Color secondary;
  final double strength;

  bool get _dark => background.computeLuminance() < 0.47;

  double _alpha(double base) =>
      (base * strength * (_dark ? 1.0 : 0.62)).clamp(0.0, 0.55);

  void _glow(
      Canvas canvas, Offset center, double radius, Color color, double alpha) {
    final paint = Paint()
      ..shader = RadialGradient(
        colors: [
          color.withValues(alpha: _alpha(alpha)),
          color.withValues(alpha: 0)
        ],
      ).createShader(Rect.fromCircle(center: center, radius: radius));
    canvas.drawCircle(center, radius, paint);
  }

  void _ring(Canvas canvas, Offset center, double radius, Color color,
      double alpha, double width) {
    canvas.drawCircle(
      center,
      radius,
      Paint()
        ..style = PaintingStyle.stroke
        ..strokeWidth = width
        ..color = color.withValues(alpha: _alpha(alpha)),
    );
  }

  void _diagonalLines(Canvas canvas, Size size, Color color, double alpha,
      {double gap = 120, double width = 28, double slope = 0.55}) {
    final paint = Paint()
      ..strokeWidth = width
      ..strokeCap = StrokeCap.round
      ..color = color.withValues(alpha: _alpha(alpha));
    for (double x = -size.height * slope; x < size.width + gap; x += gap) {
      canvas.drawLine(
        Offset(x, size.height + 40),
        Offset(x + size.height * slope, -40),
        paint,
      );
    }
  }

  void _wave(Canvas canvas, Size size, double yBase, double amplitude,
      Color color, double alpha) {
    final path = Path()..moveTo(-20, yBase);
    final waveLength = size.width / 1.6;
    for (double x = -20; x <= size.width + 40; x += 8) {
      path.lineTo(
          x, yBase + amplitude * math.sin((x / waveLength) * 2 * math.pi));
    }
    path
      ..lineTo(size.width + 40, size.height + 40)
      ..lineTo(-20, size.height + 40)
      ..close();
    canvas.drawPath(
        path, Paint()..color = color.withValues(alpha: _alpha(alpha)));
  }

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Offset.zero & size, Paint()..color = background);
    final w = size.width;
    final h = size.height;
    switch (styleId) {
      case 'sport':
        _diagonalLines(canvas, size, primary, 0.045, gap: 130, width: 30);
        _glow(canvas, Offset(w * 0.12, h * 0.10), w * 0.72, primary, 0.24);
        _glow(canvas, Offset(w * 0.95, h * 0.92), w * 0.66, secondary, 0.17);
        break;
      case 'bokeh':
        _glow(canvas, Offset(w * 0.18, h * 0.16), w * 0.34, primary, 0.26);
        _glow(canvas, Offset(w * 0.85, h * 0.30), w * 0.26, secondary, 0.22);
        _glow(canvas, Offset(w * 0.30, h * 0.78), w * 0.30, secondary, 0.18);
        _glow(canvas, Offset(w * 0.90, h * 0.90), w * 0.24, primary, 0.20);
        _ring(canvas, Offset(w * 0.72, h * 0.62), w * 0.16, primary, 0.12, 1.8);
        break;
      case 'grid':
        final grid = Paint()
          ..strokeWidth = 1.1
          ..color = primary.withValues(alpha: _alpha(0.10));
        for (double x = 0; x <= w; x += 44) {
          canvas.drawLine(Offset(x, 0), Offset(x, h), grid);
        }
        for (double y = 0; y <= h; y += 44) {
          canvas.drawLine(Offset(0, y), Offset(w, y), grid);
        }
        _glow(canvas, Offset(w * 0.5, 0), w * 0.8, secondary, 0.10);
        break;
      case 'nebula':
        _glow(canvas, Offset(w * 0.20, h * 0.18), w * 0.55, primary, 0.20);
        _glow(canvas, Offset(w * 0.85, h * 0.55), w * 0.50, secondary, 0.16);
        _glow(canvas, Offset(w * 0.40, h * 0.95), w * 0.45, primary, 0.12);
        final star = Paint()
          ..color = Colors.white.withValues(alpha: _alpha(0.30));
        for (var i = 0; i < 40; i++) {
          final sx = ((i * 73) % 97) / 97 * w;
          final sy = ((i * 131) % 89) / 89 * h;
          canvas.drawCircle(Offset(sx, sy), (i % 3 == 0) ? 1.6 : 1.0, star);
        }
        break;
      case 'petals':
        for (final (dx, dy, r, a) in const [
          (0.15, 0.12, 0.16, 0.24),
          (0.82, 0.20, 0.12, 0.20),
          (0.30, 0.45, 0.09, 0.16),
          (0.70, 0.55, 0.14, 0.18),
          (0.20, 0.85, 0.12, 0.20),
          (0.88, 0.86, 0.16, 0.22),
        ]) {
          _glow(canvas, Offset(w * dx, h * dy), w * r, primary, a);
        }
        _glow(canvas, Offset(w * 0.5, h * 0.5), w * 0.7, secondary, 0.07);
        break;
      case 'aurum':
        _ring(
            canvas, Offset(w * 1.02, h * -0.02), w * 0.35, primary, 0.22, 2.4);
        _ring(
            canvas, Offset(w * 1.02, h * -0.02), w * 0.52, primary, 0.15, 2.2);
        _ring(
            canvas, Offset(w * 1.02, h * -0.02), w * 0.70, primary, 0.10, 2.0);
        _glow(canvas, Offset(w * 0.05, h * 0.95), w * 0.55, secondary, 0.16);
        break;
      case 'waves':
        _wave(canvas, size, h * 0.80, 26, primary, 0.10);
        _wave(canvas, size, h * 0.88, 32, secondary, 0.08);
        _glow(canvas, Offset(w * 0.85, h * 0.10), w * 0.5, primary, 0.14);
        break;
      case 'plates':
        _diagonalLines(canvas, size, primary, 0.06,
            gap: 90, width: 18, slope: 0.35);
        _glow(canvas, Offset(w * 0.9, h * 0.08), w * 0.5, secondary, 0.12);
        break;
      case 'depth':
        _wave(canvas, size, h * 0.30, 20, secondary, 0.07);
        _wave(canvas, size, h * 0.55, 26, primary, 0.08);
        _wave(canvas, size, h * 0.78, 32, secondary, 0.10);
        _glow(canvas, Offset(w * 0.5, h * -0.05), w * 0.7, primary, 0.16);
        break;
      case 'sunset':
        _glow(canvas, Offset(w * 0.5, h * 1.02), w * 1.0, secondary, 0.30);
        _glow(canvas, Offset(w * 0.5, h * 1.02), w * 0.6, primary, 0.22);
        _glow(canvas, Offset(w * 0.15, h * 0.10), w * 0.4, secondary, 0.12);
        _wave(canvas, size, h * 0.90, 18, primary, 0.10);
        break;
      case 'leaves':
        for (final (dx, dy, r, rot) in const [
          (0.12, 0.14, 0.11, 0.5),
          (0.85, 0.22, 0.13, 2.2),
          (0.25, 0.55, 0.09, 4.0),
          (0.78, 0.70, 0.12, 1.2),
          (0.15, 0.88, 0.10, 3.1),
        ]) {
          canvas.save();
          canvas.translate(w * dx, h * dy);
          canvas.rotate(rot);
          canvas.drawOval(
            Rect.fromCenter(
                center: Offset.zero, width: w * r, height: w * r * 1.9),
            Paint()..color = primary.withValues(alpha: _alpha(0.12)),
          );
          canvas.restore();
        }
        _glow(canvas, Offset(w * 0.9, h * 0.05), w * 0.5, secondary, 0.12);
        break;
      case 'aurora':
        // Zorza: szerokie, rozmyte łuki światła w górnej części ekranu.
        for (final (dy, color, alpha) in [
          (0.05, primary, 0.22),
          (0.14, secondary, 0.16),
          (0.24, primary, 0.10),
        ]) {
          final path = Path()..moveTo(-40, h * (dy + 0.10));
          for (double x = -40; x <= w + 60; x += 12) {
            path.lineTo(
              x,
              h * dy + math.sin((x / w) * math.pi * 1.6) * h * 0.05,
            );
          }
          path
            ..lineTo(w + 60, h * (dy + 0.16))
            ..close();
          canvas.drawPath(
            path,
            Paint()
              ..color = color.withValues(alpha: _alpha(alpha))
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 22),
          );
        }
        _glow(canvas, Offset(w * 0.8, h * 0.9), w * 0.5, secondary, 0.10);
        break;
      case 'dots':
        // Siatka delikatnych kropek (wzór techniczny) + poświata narożna.
        final dot = Paint()..color = primary.withValues(alpha: _alpha(0.14));
        for (double y = 24; y < h; y += 42) {
          for (double x = 24; x < w; x += 42) {
            canvas.drawCircle(Offset(x, y), 1.6, dot);
          }
        }
        _glow(canvas, Offset(w * 0.1, h * 0.08), w * 0.55, primary, 0.14);
        _glow(canvas, Offset(w * 0.95, h * 0.95), w * 0.5, secondary, 0.12);
        break;
      default:
        _glow(canvas, Offset(w * 0.15, h * 0.10), w * 0.6, primary, 0.18);
        _glow(canvas, Offset(w * 0.9, h * 0.9), w * 0.55, secondary, 0.14);
    }
  }

  @override
  bool shouldRepaint(TrainerThemedBackgroundPainter oldDelegate) =>
      styleId != oldDelegate.styleId ||
      background != oldDelegate.background ||
      primary != oldDelegate.primary ||
      secondary != oldDelegate.secondary ||
      strength != oldDelegate.strength;
}

// Cache File.existsSync() dla zdjęcia tła — builder MaterialApp przebudowuje
// się przy każdej notyfikacji store, a synchroniczny odczyt dysku by ścinał.
final Map<String, bool> _trainerBgExistsCache = <String, bool>{};

/// Warstwa własnego zdjęcia jako tła aplikacji (pełny ekran, rozmycie i
/// przyciemnienie z personalizacji). null = brak zdjęcia albo plik zniknął —
/// wtedy tło wraca do koloru/gradientu motywu.
Widget? trainerBackgroundImageLayer(AppSettings settings) {
  final String path = settings.backgroundImagePath.trim();
  if (path.isEmpty) return null;
  final bool exists =
      _trainerBgExistsCache.putIfAbsent(path, () => File(path).existsSync());
  if (!exists) return null;
  Widget image = Image.file(
    File(path),
    fit: BoxFit.cover,
    // Ogranicza dekodowanie do sensownej rozdzielczości (pamięć + start).
    cacheWidth: 1440,
  );
  final double blur = settings.backgroundImageBlur.clamp(0.0, 40.0);
  if (blur > 0.5) {
    image = ImageFiltered(
      imageFilter: ui.ImageFilter.blur(sigmaX: blur, sigmaY: blur),
      child: image,
    );
  }
  final double darken = settings.backgroundImageDarken.clamp(0.0, 0.8);
  return Stack(
    fit: StackFit.expand,
    children: [
      image,
      if (darken > 0.01)
        ColoredBox(color: Colors.black.withValues(alpha: darken)),
    ],
  );
}

/// Buduje motyw aplikacji. [settings] (opcjonalne — testy wołają bez nich)
/// wnosi personalizację: motyw UI, zaokrąglenia, styl kart i gęstość.
ThemeData buildTheme(Color accent, bool dark, {AppSettings? settings}) {
  final seed = accent;
  final style = themeStyleById(settings?.themeStyleId ?? 'classic_sport');
  final cornerScale = _cornerScaleFor(settings?.cornerStyle ?? 'soft');
  final cardStyle = settings?.cardStyle ?? 'flat';
  final density = settings?.uiDensity ?? 'normal';

  final scheme = ColorScheme.fromSeed(
    seedColor: seed,
    brightness: dark ? Brightness.dark : Brightness.light,
  );

  final scaffoldColor = dark
      ? Color(style.scaffoldDark ?? 0xFF0D1117)
      : Color(style.scaffoldLight ?? 0xFFF6F8FA);
  // Przezroczystość kart z personalizacji (1.0 = pełne krycie).
  final cardOpacity = (settings?.cardOpacity ?? 1.0).clamp(0.55, 1.0);
  final baseCardColor = dark
      ? Color(style.cardDark ?? 0xFF151B23)
      : Color(style.cardLight ?? 0xFFFFFFFF);
  final cardColor = cardOpacity >= 1.0
      ? baseCardColor
      : baseCardColor.withValues(alpha: cardOpacity);

  final visualDensity = switch (density) {
    'compact' => VisualDensity.compact,
    'large' => VisualDensity.comfortable,
    _ => VisualDensity.standard,
  };

  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    visualDensity: visualDensity,
    scaffoldBackgroundColor: ((settings?.backgroundGradient ?? false) ||
            (settings?.themedBackground ?? false) ||
            (settings?.backgroundImagePath.trim().isNotEmpty ?? false))
        ? Colors.transparent
        : scaffoldColor,
    cardTheme: CardThemeData(
      elevation: cardStyle == 'elevated' ? 2 : 0,
      shadowColor: cardStyle == 'elevated'
          ? Colors.black.withValues(alpha: dark ? 0.5 : 0.25)
          : null,
      color: cardColor,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(24 * cornerScale),
        side: cardStyle == 'outlined'
            ? BorderSide(
                color:
                    scheme.outlineVariant.withValues(alpha: dark ? 0.6 : 0.9))
            : BorderSide.none,
      ),
    ),
    inputDecorationTheme: InputDecorationTheme(
      filled: true,
      fillColor: dark ? scaffoldColor : const Color(0xFFF1F5F9),
      border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(18 * cornerScale),
          borderSide: BorderSide.none),
    ),
    // Sportowy, spójny wygląd przycisków i chipów (zaokrąglenia + mocniejszy tekst).
    filledButtonTheme: FilledButtonThemeData(
      style: FilledButton.styleFrom(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16 * cornerScale)),
        textStyle: const TextStyle(fontWeight: FontWeight.w800),
        padding: EdgeInsets.symmetric(
            horizontal: 18,
            vertical:
                density == 'compact' ? 11 : (density == 'large' ? 15 : 13)),
      ),
    ),
    outlinedButtonTheme: OutlinedButtonThemeData(
      style: OutlinedButton.styleFrom(
        shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16 * cornerScale)),
        textStyle: const TextStyle(fontWeight: FontWeight.w700),
        padding: EdgeInsets.symmetric(
            horizontal: 16,
            vertical:
                density == 'compact' ? 10 : (density == 'large' ? 14 : 12)),
      ),
    ),
    chipTheme: ChipThemeData(
      shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(12 * cornerScale)),
      labelStyle:
          TextStyle(fontWeight: FontWeight.w700, color: scheme.onSurface),
    ),
    navigationBarTheme: NavigationBarThemeData(
      indicatorColor: scheme.primary.withValues(alpha: 0.2),
      indicatorShape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(16 * cornerScale)),
      labelTextStyle: WidgetStateProperty.resolveWith(
        (states) => TextStyle(
          fontWeight: states.contains(WidgetState.selected)
              ? FontWeight.w900
              : FontWeight.w600,
          fontSize: 12,
          color: states.contains(WidgetState.selected)
              ? scheme.primary
              : scheme.onSurfaceVariant,
        ),
      ),
      iconTheme: WidgetStateProperty.resolveWith(
        (states) => IconThemeData(
          color: states.contains(WidgetState.selected)
              ? scheme.primary
              : scheme.onSurfaceVariant,
        ),
      ),
    ),
  );
}

class AppScope extends InheritedNotifier<AppStore> {
  const AppScope({super.key, required AppStore store, required Widget child})
      : super(notifier: store, child: child);

  static AppStore of(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<AppScope>();
    assert(scope != null, 'AppScope not found');
    return scope!.notifier!;
  }

  static AppStore read(BuildContext context) {
    final element = context.getElementForInheritedWidgetOfExactType<AppScope>();
    final scope = element?.widget as AppScope?;
    assert(scope != null, 'AppScope not found');
    return scope!.notifier!;
  }
}

class AppStore extends ChangeNotifier {
  AppStore({
    TrainerLocalRepository? trainerRepository,
    TrainerCalorieLocalAdapter? calorieAdapter,
    TrainerHealthConnectService? healthConnectService,
  })  : _trainerRepository = trainerRepository ?? TrainerLocalRepository(),
        _calorieAdapter = calorieAdapter ?? const TrainerCalorieLocalAdapter(),
        _healthConnectService =
            healthConnectService ?? createTrainerHealthConnectService();

  final TrainerLocalRepository _trainerRepository;
  final TrainerCalorieLocalAdapter _calorieAdapter;
  final TrainerHealthConnectService _healthConnectService;
  final List<WorkoutLog> logs = [];
  final List<WorkoutPlan> plans = [];
  final List<Exercise> customExercises = [];
  final List<BodyMeasurement> bodyMeasurements = [];
  final List<BodyAnalysisResult> bodyAnalyses = [];

  /// Robocze zdjęcia sylwetki do analizy: 'front' / 'side' / 'back' → ścieżka.
  final Map<String, String> progressPhotoDrafts = {};
  bool bodyAnalysisBusy = false;

  /// Centralny profil celu użytkownika — JEDNO źródło prawdy dla docelowej
  /// sylwetki, aktualnej strategii składu ciała i priorytetu treningowego.
  /// null = użytkownik jeszcze nie skonfigurował celu (i nie miał starej
  /// docelowej sylwetki do zmigrowania) — most nie publikuje wtedy celów.
  UserBodyGoalProfile? bodyGoalProfile;

  /// Historia etapów celu (redukcja → utrzymanie → masa…). Poprzedni etap
  /// nigdy nie jest nadpisywany — zamykamy go i dodajemy nowy.
  final List<GoalPhase> goalPhases = [];
  final List<TrainingImpact> trainingImpacts = [];
  final List<TrainerActivityEntry> activityEntries = [];
  final List<TrainerHealthConnectSnapshot> healthConnectSnapshots = [];
  ExerciseLibraryPreferences exerciseLibraryPreferences =
      const ExerciseLibraryPreferences();
  ActiveWorkoutSession? activeWorkoutSession;

  /// Czy pokazać okno wznowienia treningu (po powrocie z tła albo po restarcie
  /// aplikacji z niedokończonym treningiem). UI czyści flagę po decyzji.
  bool workoutResumePromptPending = false;

  /// Czy propozycja wznowienia pochodzi z zimnego startu (inny tekst dialogu).
  bool workoutResumeColdStart = false;
  AppSettings settings = AppSettings.defaults();
  DateTime selectedDate = DateTime.now();
  String? lastAiMessage;
  bool aiBusy = false;
  bool healthConnectBusy = false;
  final List<AiChatMessage> aiChatHistory = [];
  bool aiChatBusy = false;

  static const _settingsKey = 'workout_settings_v1';
  static const _bodyGoalProfileKey = 'user_body_goal_profile_v1';
  static const _goalPhasesKey = 'goal_phases_v1';
  static const _aiChatKey = 'ai_chat_history_v1';
  static const _workoutAiAnalysesKey = 'workout_ai_analyses_v1';
  static const _progressPhotoDraftsKey = 'progress_photo_drafts_v1';
  static const _activityIconSeenKey = 'activity_icon_news_seen_v1';
  static const _warmupCompletionsKey = 'warmup_completions_v1';
  static const _plansWarmupMigrationKey = 'plans_warmup_migration_v1';

  /// Ukończone programy rozgrzewkowe: id rozgrzewki → moment ukończenia.
  /// Bramka ciężkiego dnia honoruje wpis tylko przez [kWarmupFreshness].
  final Map<String, DateTime> warmupCompletions = {};

  /// Zdarzenia „odhaczone" per ikona paska Dzisiaj (jak przeczytane wiadomości).
  final Map<String, List<String>> _activityIconSeenNews = {};

  final Map<String, WorkoutAiAnalysis> _workoutAiAnalyses = {};

  Future<void> load() async {
    final trainerData = await _trainerRepository.load();
    logs
      ..clear()
      ..addAll(trainerData.sessions);
    plans
      ..clear()
      ..addAll(trainerData.plans);
    customExercises
      ..clear()
      ..addAll(trainerData.customExercises);
    bodyMeasurements
      ..clear()
      ..addAll(trainerData.bodyMeasurements);
    bodyMeasurements.sort((left, right) => right.date.compareTo(left.date));
    bodyAnalyses
      ..clear()
      ..addAll(trainerData.bodyAnalyses);
    bodyAnalyses.sort((left, right) => right.date.compareTo(left.date));
    trainingImpacts
      ..clear()
      ..addAll(trainerData.trainingImpacts);
    trainingImpacts.sort((left, right) => right.date.compareTo(left.date));
    activityEntries
      ..clear()
      ..addAll(trainerData.activityEntries);
    activityEntries.sort((left, right) => right.date.compareTo(left.date));
    healthConnectSnapshots
      ..clear()
      ..addAll(trainerData.healthConnectSnapshots);
    healthConnectSnapshots
        .sort((left, right) => right.checkedAt.compareTo(left.checkedAt));
    exerciseLibraryPreferences = trainerData.exerciseLibraryPreferences;
    activeWorkoutSession = trainerData.activeWorkoutSession;
    if (activeWorkoutSession?.exercises.isEmpty ?? false) {
      activeWorkoutSession = null;
      await saveActiveWorkoutSession();
    }
    // Restart aplikacji z niedokończonym treningiem: zamrażamy czas (nie licząc
    // nieznanej luki jako aktywnej) i proponujemy wznowienie — postęp serii
    // pozostaje nietknięty.
    final restored = activeWorkoutSession;
    if (restored != null && restored.completedSetCount >= 0) {
      activeWorkoutSession = restored.frozenOnRestart();
      workoutResumePromptPending = true;
      workoutResumeColdStart = true;
      await saveActiveWorkoutSession();
    }

    final prefs = await SharedPreferences.getInstance();
    final hasStoredPlans = prefs.containsKey(TrainerLocalRepository.plansKey);
    final rawSettings = prefs.getString(_settingsKey);
    if (rawSettings != null && rawSettings.isNotEmpty) {
      try {
        settings = AppSettings.fromJson(
            Map<String, dynamic>.from(jsonDecode(rawSettings)));
      } catch (_) {}
    }

    // Deload: zakotwicz cykl RAZ na „dziś", żeby harmonogram nie przesuwał się
    // każdego dnia — kalendarz musi być stabilny na tygodnie w przód.
    if (settings.deloadCycle.enabled && settings.deloadCycle.anchor == null) {
      final now = DateTime.now();
      settings = settings.copyWith(
        deloadCycle: settings.deloadCycle
            .copyWith(anchor: DateTime(now.year, now.month, now.day)),
      );
      await prefs.setString(_settingsKey, jsonEncode(settings.toJson()));
    }

    // Rozkład treningu: zakotwicz RAZ, żeby tydzień był stały między
    // uruchomieniami i dał się policzyć na dowolną datę w przód.
    if (settings.trainingSchedule.enabled &&
        settings.trainingSchedule.anchor == null) {
      final now = DateTime.now();
      settings = settings.copyWith(
        trainingSchedule: settings.trainingSchedule
            .copyWith(anchor: DateTime(now.year, now.month, now.day)),
      );
      await prefs.setString(_settingsKey, jsonEncode(settings.toJson()));
    }

    // Jednorazowy zasiew: użytkownik zgłosił deload od 20.07.2026 — ustaw cykl
    // tak, by ten dzień był 1. dniem deloadu (kolejne cykle liczą się dalej,
    // periodycznie). Odpala się dokładnie raz; pomijane w testach, żeby stan
    // zestawu testów pozostał deterministyczny.
    const deloadSeedKey = 'deload_seed_20260720_v1';
    if (!Platform.environment.containsKey('FLUTTER_TEST') &&
        !(prefs.getBool(deloadSeedKey) ?? false)) {
      final seedStart = DateTime(2026, 7, 20);
      // Zasiew SAM WYGASA: gdyby aplikacja ruszyła dopiero po miesiącach,
      // cofanie cyklu do starej daty nie ma sensu — wtedy tylko zużywamy flagę.
      if (DateTime.now().difference(seedStart).inDays.abs() <= 60) {
        settings = settings.copyWith(
          deloadCycle: reanchorDeloadStart(
            settings.deloadCycle.copyWith(enabled: true),
            seedStart,
          ),
        );
        await prefs.setString(_settingsKey, jsonEncode(settings.toJson()));
      }
      await prefs.setBool(deloadSeedKey, true);
    }

    // --- Centralny profil celu: wczytanie + jednorazowa migracja. ---
    // Migracja NIE dotyka planów, postępów programów ani celu kalorii —
    // buduje wyłącznie nowy profil ze starych pól (trainingMode,
    // targetSilhouette, targetWeightKg). Stare pola zostają nietknięte.
    final rawGoalProfile = prefs.getString(_bodyGoalProfileKey);
    if (rawGoalProfile != null && rawGoalProfile.isNotEmpty) {
      try {
        bodyGoalProfile = UserBodyGoalProfile.fromJson(
          Map<String, dynamic>.from(jsonDecode(rawGoalProfile)),
        );
      } catch (_) {}
    }
    if (bodyGoalProfile == null &&
        settings.targetSilhouette.trim().isNotEmpty) {
      bodyGoalProfile = migrateLegacyGoalProfile(
        legacyTrainingMode: settings.trainingMode,
        legacyTargetSilhouette: settings.targetSilhouette,
        legacyTargetWeightKg: settings.targetWeightKg,
      );
      await prefs.setString(
        _bodyGoalProfileKey,
        jsonEncode(bodyGoalProfile!.toJson()),
      );
    }
    final rawGoalPhases = prefs.getString(_goalPhasesKey);
    if (rawGoalPhases != null && rawGoalPhases.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawGoalPhases);
        if (decoded is List) {
          goalPhases
            ..clear()
            ..addAll(decoded
                .whereType<Map>()
                .map((e) => GoalPhase.fromJson(Map<String, dynamic>.from(e))));
        }
      } catch (_) {}
    }
    // Pierwszy etap historii — otwarty od momentu migracji/konfiguracji.
    if (bodyGoalProfile != null && goalPhases.isEmpty) {
      goalPhases.add(GoalPhase(
        strategy: bodyGoalProfile!.bodyCompositionStrategy,
        startDate: bodyGoalProfile!.updatedAt,
        startWeightKg: settings.bodyWeightKg > 0 ? settings.bodyWeightKg : null,
        reason: 'Start historii etapów (migracja ustawień)',
      ));
      await prefs.setString(
        _goalPhasesKey,
        jsonEncode([for (final phase in goalPhases) phase.toJson()]),
      );
    }

    final rawPhotoDrafts = prefs.getString(_progressPhotoDraftsKey);
    if (rawPhotoDrafts != null && rawPhotoDrafts.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawPhotoDrafts);
        if (decoded is Map) {
          progressPhotoDrafts
            ..clear()
            ..addAll(decoded.map(
                (key, value) => MapEntry(key.toString(), value.toString())));
        }
      } catch (_) {}
    }

    final rawWarmupCompletions = prefs.getString(_warmupCompletionsKey);
    if (rawWarmupCompletions != null && rawWarmupCompletions.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawWarmupCompletions);
        if (decoded is Map) {
          warmupCompletions.clear();
          decoded.forEach((key, value) {
            final at = DateTime.tryParse(value.toString());
            if (at != null) warmupCompletions[key.toString()] = at;
          });
        }
      } catch (_) {}
    }

    final rawIconSeen = prefs.getString(_activityIconSeenKey);
    if (rawIconSeen != null && rawIconSeen.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawIconSeen);
        if (decoded is Map) {
          _activityIconSeenNews.clear();
          decoded.forEach((key, value) {
            if (value is List) {
              _activityIconSeenNews[key.toString()] =
                  value.map((item) => item.toString()).toList();
            }
          });
        }
      } catch (_) {}
    }

    final rawAnalyses = prefs.getString(_workoutAiAnalysesKey);
    if (rawAnalyses != null && rawAnalyses.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawAnalyses);
        if (decoded is Map) {
          _workoutAiAnalyses
            ..clear()
            ..addAll(
              decoded.map((k, v) => MapEntry(
                  k.toString(),
                  WorkoutAiAnalysis.fromJson(
                      Map<String, dynamic>.from(v as Map)))),
            );
        }
      } catch (_) {}
    }

    final rawBackupAt = prefs.getString(_backupAtKey);
    if (rawBackupAt != null && rawBackupAt.isNotEmpty) {
      lastBackupAt = DateTime.tryParse(rawBackupAt);
    }

    final rawChat = prefs.getString(_aiChatKey);
    if (rawChat != null && rawChat.isNotEmpty) {
      try {
        final decoded = jsonDecode(rawChat);
        if (decoded is List) {
          aiChatHistory
            ..clear()
            ..addAll(decoded.whereType<Map>().map(
                (e) => AiChatMessage.fromJson(Map<String, dynamic>.from(e))));
        }
      } catch (_) {}
    }

    final rawAdjustmentsSignature = prefs.getString(_adjustmentsSignatureKey);
    if (rawAdjustmentsSignature != null && rawAdjustmentsSignature.isNotEmpty) {
      _publishedAdjustmentsSignature = rawAdjustmentsSignature;
    }
    lastDailyAdjustmentsPublishAt =
        await _calorieAdapter.lastDailyAdjustmentsPublishedAt();
    // Dosyłamy pakiety korekty dnia, jeśli most nie odpowiada bieżącym danym
    // (np. pierwsza publikacja po aktualizacji aplikacji).
    if (!dailyAdjustmentsSynced) {
      await publishDailyAdjustmentsBridge(notify: false);
    }

    if (plans.isEmpty && !hasStoredPlans) {
      plans.add(createLocalWorkoutPlan(settings));
      await savePlans();
    } else if (plans.isNotEmpty) {
      final activeIndexes = <int>[
        for (var index = 0; index < plans.length; index++)
          if (plans[index].isActive) index,
      ];
      if (activeIndexes.length != 1) {
        final activeIndex = activeIndexes.isEmpty ? 0 : activeIndexes.first;
        for (var index = 0; index < plans.length; index++) {
          plans[index] = plans[index].copyWith(isActive: index == activeIndex);
        }
        await savePlans();
      }
    }

    // Jednorazowa migracja zapisanych planów pod bramkę rozgrzewki: starsze
    // zapisy mają kind: unknown (omijają bramkę) i ogólną rozgrzewkę inline
    // także w dni ciężkie. Uzupełniamy charakter dni z rytmu generatora,
    // ciężkim dniom zdejmujemy rozgrzewkę inline (dostarcza ją bramka),
    // lekkim podmieniamy stare id na pulę partii. Postęp i warianty nietknięte.
    if (!(prefs.getBool(_plansWarmupMigrationKey) ?? false)) {
      var migrated = false;
      for (var index = 0; index < plans.length; index++) {
        final updated = migratePlanForWarmupGate(
          plans[index],
          resolveExercise: (id) => ExerciseRepo.byId(id, customExercises),
        );
        if (updated != null) {
          plans[index] = updated;
          migrated = true;
        }
      }
      if (migrated) await savePlans();
      await prefs.setBool(_plansWarmupMigrationKey, true);
    }
  }

  Future<void> saveAll() async {
    await saveLogs();
    await savePlans();
    await saveSettings();
    await saveCustomExercises();
    await saveExerciseLibraryPreferences();
    await saveActiveWorkoutSession();
    await saveBodyMeasurements();
    await saveBodyAnalyses();
    await saveTrainingImpacts();
    await saveActivityEntries();
    await saveHealthConnectSnapshots();
  }

  Future<void> saveLogs() async {
    _recoveryCache = null; // każda zmiana logów unieważnia mapę regeneracji
    await _trainerRepository.saveSessions(logs);
  }

  Future<void> savePlans() async {
    await _trainerRepository.savePlans(plans);
  }

  WorkoutPlan? get activeWorkoutPlan {
    for (final plan in plans) {
      if (plan.isActive) return plan;
    }
    return plans.isEmpty ? null : plans.first;
  }

  /// Czy AKTYWNY program z katalogu ma inny poziom niż profil użytkownika.
  ///
  /// Skutek uboczny naprawionego błędu normalizacji poziomu: „Średniozaawansowany"
  /// zawiera podciąg „zaaw", więc plany zapisane wcześniej mogły utrwalić poziom
  /// „Zaawansowany" mimo innego ustawienia w profilu.
  bool get activePlanLevelMismatch {
    final plan = activeWorkoutPlan;
    if (plan == null || plan.level.trim().isEmpty) return false;
    if (catalogProgramIdForPlan(plan.id) == null) return false;
    return normalizeTrainingLevel(plan.level) !=
        normalizeTrainingLevel(settings.level);
  }

  // ── Trwały rozkład treningu ─────────────────────────────────────────────────

  /// Konfiguracja rozkładu; dni treningowe zawsze biorą się z ustawień profilu.
  TrainingScheduleConfig get trainingScheduleConfig => settings.trainingSchedule
      .copyWith(trainingWeekdays: settings.trainingWeekdays);

  /// Rozkład na kolejne [days] dni od [from] (domyślnie od dziś).
  ///
  /// Deterministyczny: nie zależy od tego, który zestaw ostatnio otworzyłeś.
  /// Regeneracja może PRZESTAWIĆ dni (z adnotacją), a dni deloadu są oznaczone.
  List<ScheduledDay> trainingScheduleFor({DateTime? from, int days = 28}) {
    final now = DateTime.now();
    final start = from ?? DateTime(now.year, now.month, now.day);
    final base = buildSchedule(trainingScheduleConfig, start, days);
    if (base.isEmpty) return base;
    final recovery = muscleRecoveryMap(now);
    final resolved = resolveScheduleWithRecovery(
      base,
      (area, date) => scheduleReadiness(area, date, now, recovery),
    );
    return [
      for (final day in resolved)
        isDeloadDate(day.date) ? day.copyWith(isDeload: true) : day,
    ];
  }

  /// Dzień rozkładu przypadający na DZIŚ (obszar, deload, ewentualne
  /// przestawienie). To on decyduje, co pokazujemy jako „dzisiejszy trening" —
  /// nie ostatnio kliknięty zestaw.
  ScheduledDay? get todayScheduled {
    final today = trainingScheduleFor(days: 1);
    return today.isEmpty ? null : today.first;
  }

  /// Rozkład tygodnia w postaci przekazywanej planerowi (7 dni od dziś).
  List<ScheduledFocusDay> weeklyFocusSchedule([DateTime? from]) => [
        for (final day in trainingScheduleFor(from: from, days: 7))
          day.toFocusDay(),
      ];

  /// Program 30-dniowy odpowiadający danemu obszarowi — o ile użytkownik
  /// faktycznie taki program ma. `null` = zestaw trzeba złożyć dynamicznie.
  WorkoutPlan? planForArea(TrainingFocusArea? area) {
    final programId = programIdForArea(area);
    if (programId == null) return null;
    for (final plan in plans) {
      if (catalogProgramIdForPlan(plan.id) == programId) return plan;
    }
    return null;
  }

  /// Plan realizujący dany obszar rozkładu.
  ///
  /// Kiedyś dzień brał się po prostu z [activeWorkoutPlan] — czyli z zestawu
  /// ostatnio otwartego, przez co obejrzenie programu barków zamieniało
  /// zaplanowany dzień nóg w dzień barków. Teraz:
  ///  1. program katalogowy tej partii, jeśli użytkownik go ma,
  ///  2. plan WŁASNY / z AI — on nie jest przypisany do partii, tylko sam
  ///     rozpisuje cały tydzień, więc zostaje planem dnia,
  ///  3. `null` → dzień składa Planer z ćwiczeń pod zaplanowaną partię.
  ///
  /// Program katalogowy INNEJ partii nigdy nie przejmuje dnia — to była
  /// dokładnie ta podmiana, która rozjeżdżała rozkład („zestaw, który ostatnio
  /// przeglądałem" zamiast tego z rotacji).
  WorkoutPlan? scheduledPlanForArea(TrainingFocusArea? area) {
    final matching = planForArea(area);
    if (matching != null) return matching;
    final active = activeWorkoutPlan;
    if (active == null || catalogProgramIdForPlan(active.id) != null) {
      return null;
    }
    return active;
  }

  /// Plan, z którego bierze się DZISIEJSZY trening (wg rozkładu).
  WorkoutPlan? get planForToday {
    final scheduled = todayScheduled;
    if (scheduled == null) return activeWorkoutPlan; // brak rozkładu
    if (scheduled.isRest) return null;
    return scheduledPlanForArea(scheduled.area);
  }

  /// Zapisuje nową konfigurację rozkładu (np. inna rotacja).
  Future<void> updateTrainingSchedule(TrainingScheduleConfig config) async {
    settings = settings.copyWith(trainingSchedule: config);
    await saveSettings();
    notifyListeners();
  }

  /// Ustawia plan JEDNEGO dnia tygodnia (partia główna + dodatek).
  ///
  /// Dzień bez żadnej partii to dzień wolny — dni treningowe profilu są
  /// aktualizowane razem z planem, żeby nie rozjechały się dwa źródła prawdy.
  Future<void> setWeekdayPlan(int weekday, TrainingDayPlan plan) async {
    final plans = weekPlanWithDay(trainingScheduleConfig, weekday, plan);
    final active = [
      for (var day = 1; day <= 7; day++)
        if (!(plans[day] ?? TrainingDayPlan.rest).isRest) day,
    ];
    settings = settings.copyWith(
      trainingSchedule: settings.trainingSchedule.copyWith(weekdayPlans: plans),
      // Pusty tydzień zostawia dni z profilu — reszta aplikacji (regeneracja,
      // długość programów) liczy na to, że jakieś dni treningowe są.
      trainingWeekdays: active.isEmpty ? null : active,
    );
    await saveSettings();
    notifyListeners();
  }

  /// Przywraca domyślny plan tygodnia dla bieżących dni treningowych.
  Future<void> resetWeekPlan() async {
    await updateTrainingSchedule(settings.trainingSchedule.copyWith(
      weekdayPlans: defaultWeekPlan(settings.trainingWeekdays),
      rotationKeys: const <String>[],
    ));
  }

  // ── Deload (cykliczne odciążenie) ───────────────────────────────────────────

  /// Konfiguracja deloadu (kotwica jest inicjowana raz w [load]).
  DeloadCycle get deloadCycle => settings.deloadCycle;

  /// Status deloadu dla podanej daty (domyślnie dziś).
  DeloadStatus deloadStatusOn([DateTime? date]) =>
      deloadStatusForDate(settings.deloadCycle, date ?? DateTime.now());

  /// Status deloadu na dziś (skrót używany przez czołówkę „Trening").
  DeloadStatus get deloadStatusToday => deloadStatusOn();

  /// Czy [date] wypada w deloadzie (do kolorowania kalendarza).
  bool isDeloadDate(DateTime date) => isDeloadDay(settings.deloadCycle, date);

  /// Czy zmęczenie sugeruje deload WCZEŚNIEJ niż zaplanowany (adaptacyjnie).
  /// Łączy periodyczny cykl z reaktywną oceną zmęczenia z historii (Planer).
  bool get deloadRecommendedEarly {
    final cycle = settings.deloadCycle;
    if (!cycle.isConfigured || !cycle.adaptive) return false;
    final status = deloadStatusOn();
    if (!status.isTraining) return false;
    // Sens ma tylko gdy jesteśmy już głębiej w bloku (≥2 tyg.), a deload nie jest
    // tuż-tuż (inaczej rekomendacja niczego nie zmienia).
    final daysIntoBlock = cycle.trainingDays - status.daysUntilDeload;
    if (daysIntoBlock < 14 || status.daysUntilDeload <= 3) return false;
    return plannedWorkoutForToday().deload.recommended;
  }

  /// Zapisuje nową konfigurację deloadu.
  Future<void> updateDeloadCycle(DeloadCycle cycle) async {
    settings = settings.copyWith(deloadCycle: cycle);
    await saveSettings();
    notifyListeners();
  }

  /// Włącza/wyłącza deload; przy włączeniu zakotwicza cykl na dziś, jeśli trzeba.
  Future<void> setDeloadEnabled(bool enabled) async {
    var cycle = settings.deloadCycle.copyWith(enabled: enabled);
    if (enabled && cycle.anchor == null) {
      final now = DateTime.now();
      cycle = cycle.copyWith(anchor: DateTime(now.year, now.month, now.day));
    }
    await updateDeloadCycle(cycle);
  }

  /// Adaptacyjnie „przyciąga" deload — zaczyna go od dziś (kolejne cykle liczą
  /// się dalej periodycznie od tego momentu).
  Future<void> startDeloadNow() async {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    var cycle = settings.deloadCycle.copyWith(enabled: true);
    if (cycle.anchor == null) cycle = cycle.copyWith(anchor: today);
    await updateDeloadCycle(reanchorDeloadStart(cycle, today));
  }

  /// Zwraca dzień planu przekształcony pod deload, jeśli [date] wypada w oknie
  /// deloadu; w przeciwnym razie zwraca dzień bez zmian.
  WorkoutDay deloadAdjustedDay(WorkoutDay day, [DateTime? date]) {
    return deloadStatusOn(date).isDeload ? deloadWorkoutDay(day) : day;
  }

  /// Suma ręcznej korekty PROGRAMU i korekty konkretnego DNIA (przycięta).
  /// Obie gałki (program i dzień) mają po ±[kMaxIntensitySteps], więc razem
  /// sięgają ±[kMaxCombinedIntensitySteps] — dzień da się podkręcić PONAD
  /// ustawienie całego programu.
  int effectiveIntensitySteps(WorkoutPlan plan, WorkoutDay day) =>
      (plan.intensitySteps + day.intensitySteps)
          .clamp(-kMaxCombinedIntensitySteps, kMaxCombinedIntensitySteps);

  /// Korekta obowiązująca dla bieżącego dnia aktywnego programu.
  int get activeEffectiveIntensitySteps {
    final plan = activeWorkoutPlan;
    if (plan == null || plan.days.isEmpty) return 0;
    final index = plan.currentDayIndex.clamp(0, plan.days.length - 1);
    return effectiveIntensitySteps(plan, plan.days[index]);
  }

  /// Dzień gotowy do pokazania i startu: najpierw RĘCZNA korekta intensywności
  /// (program + dzień), potem ewentualne odciążenie deloadu.
  WorkoutDay presentedDay(WorkoutPlan plan, WorkoutDay day, [DateTime? date]) {
    return deloadAdjustedDay(
        applyIntensityStep(day, effectiveIntensitySteps(plan, day)), date);
  }

  /// Ustawia ręczną korektę intensywności CAŁEGO programu (−3..+3).
  Future<void> setPlanIntensitySteps(String planId, int steps) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final clamped = steps.clamp(-kMaxIntensitySteps, kMaxIntensitySteps);
    if (plans[index].intensitySteps == clamped) return;
    plans[index] = plans[index].copyWith(intensitySteps: clamped);
    await savePlans();
    notifyListeners();
  }

  /// Ustawia ręczną korektę intensywności POJEDYNCZEGO dnia (−3..+3).
  Future<void> setPlanDayIntensitySteps(
      String planId, int dayIndex, int steps) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final plan = plans[index];
    if (dayIndex < 0 || dayIndex >= plan.days.length) return;
    final clamped = steps.clamp(-kMaxIntensitySteps, kMaxIntensitySteps);
    if (plan.days[dayIndex].intensitySteps == clamped) return;
    final days = [...plan.days];
    days[dayIndex] = days[dayIndex].copyWith(intensitySteps: clamped);
    plans[index] = plan.copyWith(days: days);
    await savePlans();
    notifyListeners();
  }

  /// Rzutuje, który dzień programu wypada (albo wypadał) w [date].
  ///
  /// Z ROZKŁADEM: dzień bierze się z partii zaplanowanej na tę datę — program
  /// klatki posuwa się o jeden dzień za każdym razem, gdy w rozkładzie wypada
  /// klatka. Dzięki temu kalendarz na kolejne tygodnie pokazuje ROTACJĘ,
  /// a nie kolejne dni jednego, ostatnio otwartego zestawu.
  ///
  /// BEZ ROZKŁADU (stary tryb): program jest liniowy i dni układają się na
  /// kolejnych dniach treningowych z ustawień.
  ///
  /// Zwraca `null`, gdy nie ma pasującego programu, [date] jest dniem wolnym,
  /// wypada poza zakresem programu albo jest zbyt odległa.
  ({WorkoutDay day, int index})? projectedProgramDayForDate(DateTime date) {
    final target = DateTime(date.year, date.month, date.day);
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    if (target.difference(today).inDays.abs() > 400) return null;

    final config = trainingScheduleConfig;
    // Rzutowanie po ROTACJI ma sens tylko dla programu partii: jego kolejne dni
    // wypadają wtedy, gdy w rozkładzie wraca ta partia. Plan własny rozpisuje
    // sobie cały tydzień sam, więc dla niego zostaje projekcja liniowa niżej.
    final area = config.isConfigured
        ? config.planForWeekday(target.weekday).primary
        : null;
    final areaProgram = area == null ? null : planForArea(area);
    if (config.isConfigured && areaProgram != null) {
      final scheduledPlan = areaProgram;
      if (scheduledPlan.days.isEmpty) return null;

      // Ile razy TA SAMA partia wypada między dziś a datą docelową.
      var steps = 0;
      if (!target.isBefore(today)) {
        for (var d = today;
            d.isBefore(target);
            d = d.add(const Duration(days: 1))) {
          if (config.planForWeekday(d.weekday).primary == area) steps++;
        }
      } else {
        for (var d = target;
            d.isBefore(today);
            d = d.add(const Duration(days: 1))) {
          if (config.planForWeekday(d.weekday).primary == area) steps--;
        }
      }
      final scheduledIndex = scheduledPlan.currentDayIndex
              .clamp(0, scheduledPlan.days.length - 1) +
          steps;
      if (scheduledIndex < 0 || scheduledIndex >= scheduledPlan.days.length) {
        return null;
      }
      return (day: scheduledPlan.days[scheduledIndex], index: scheduledIndex);
    }

    // Dzień wolny w rozkładzie nie ma zestawu, choćby plan własny coś na niego
    // przewidywał.
    if (config.isConfigured && config.planForWeekday(target.weekday).isRest) {
      return null;
    }

    final plan = scheduledPlanForArea(area);
    if (plan == null || plan.days.isEmpty) return null;
    final weekdays = config.isConfigured
        ? config.activeWeekdays.toSet()
        : settings.trainingWeekdays.toSet();
    if (weekdays.isEmpty) return null;
    if (!weekdays.contains(target.weekday)) return null;

    final startIndex = plan.currentDayIndex.clamp(0, plan.days.length - 1);

    // Pierwszy dzień treningowy od dziś (włącznie) odpowiada bieżącemu dniowi.
    var anchorDay = today;
    for (var guard = 0;
        guard < 14 && !weekdays.contains(anchorDay.weekday);
        guard++) {
      anchorDay = anchorDay.add(const Duration(days: 1));
    }

    int trainingDaysBetween(DateTime from, DateTime to) {
      var count = 0;
      for (var d = from; !d.isAfter(to); d = d.add(const Duration(days: 1))) {
        if (weekdays.contains(d.weekday)) count++;
      }
      return count;
    }

    final int index;
    if (!target.isBefore(anchorDay)) {
      index = startIndex + trainingDaysBetween(anchorDay, target) - 1;
    } else {
      index = startIndex -
          trainingDaysBetween(
              target, anchorDay.subtract(const Duration(days: 1)));
    }
    if (index < 0 || index >= plan.days.length) return null;
    return (day: plan.days[index], index: index);
  }

  Future<void> addWorkoutPlan(WorkoutPlan plan) async {
    final shouldActivate = plans.isEmpty || plan.isActive;
    if (shouldActivate) {
      for (var index = 0; index < plans.length; index++) {
        plans[index] = plans[index].copyWith(isActive: false);
      }
    }
    plans.add(plan.copyWith(isActive: shouldActivate));
    await savePlans();
    notifyListeners();
  }

  Future<void> updateWorkoutPlan(WorkoutPlan updatedPlan) async {
    final index = plans.indexWhere((plan) => plan.id == updatedPlan.id);
    if (index < 0) return;
    if (updatedPlan.isActive) {
      for (var planIndex = 0; planIndex < plans.length; planIndex++) {
        plans[planIndex] = plans[planIndex].copyWith(isActive: false);
      }
    }
    plans[index] = updatedPlan;
    if (plans.isNotEmpty && !plans.any((plan) => plan.isActive)) {
      plans[index] = plans[index].copyWith(isActive: true);
    }
    await savePlans();
    notifyListeners();
  }

  Future<void> deleteWorkoutPlan(String planId) async {
    final removedWasActive =
        plans.any((plan) => plan.id == planId && plan.isActive);
    plans.removeWhere((plan) => plan.id == planId);
    if (removedWasActive && plans.isNotEmpty) {
      plans[0] = plans[0].copyWith(isActive: true);
    }
    await savePlans();
    notifyListeners();
  }

  Future<void> setActiveWorkoutPlan(String planId) async {
    final activeIndex = plans.indexWhere((plan) => plan.id == planId);
    if (activeIndex < 0) return;
    for (var index = 0; index < plans.length; index++) {
      plans[index] = plans[index].copyWith(isActive: index == activeIndex);
    }
    await savePlans();
    notifyListeners();
  }

  Future<WorkoutPlan?> duplicateWorkoutPlan(String planId) async {
    final source = plans.where((plan) => plan.id == planId);
    if (source.isEmpty) return null;
    final original = source.first;
    final copy = original.copyWith(
      id: 'plan_${idNow()}',
      name: '${original.name} — kopia',
      days: original.days
          .map(
            (day) => day.copyWith(
              items: day.items.map((item) => item.copyWith()).toList(),
            ),
          )
          .toList(),
      isActive: false,
    );
    plans.add(copy);
    await savePlans();
    notifyListeners();
    return copy;
  }

  Future<bool> copyWorkoutDay({
    required String planId,
    required int sourceWeekday,
    required int targetWeekday,
  }) async {
    final planIndex = plans.indexWhere((plan) => plan.id == planId);
    if (planIndex < 0 || sourceWeekday == targetWeekday) return false;
    final plan = plans[planIndex];
    final sourceDays = plan.days.where((day) => day.weekday == sourceWeekday);
    if (sourceDays.isEmpty) return false;
    final source = sourceDays.first;
    final copiedDay = source.copyWith(
      weekday: targetWeekday,
      title: '${source.title} — kopia',
      items: source.items.map((item) => item.copyWith()).toList(),
    );
    final updatedDays = [...plan.days];
    final targetIndex =
        updatedDays.indexWhere((day) => day.weekday == targetWeekday);
    if (targetIndex >= 0) {
      updatedDays[targetIndex] = copiedDay;
    } else {
      updatedDays.add(copiedDay);
    }
    updatedDays.sort((left, right) => left.weekday.compareTo(right.weekday));
    plans[planIndex] = plan.copyWith(days: updatedDays);
    await savePlans();
    notifyListeners();
    return true;
  }

  Future<void> upsertPlanItem({
    required String planId,
    required int weekday,
    required PlanItem item,
  }) async {
    final planIndex = plans.indexWhere((plan) => plan.id == planId);
    if (planIndex < 0) return;
    final plan = plans[planIndex];
    final dayIndex = plan.days.indexWhere((day) => day.weekday == weekday);
    if (dayIndex < 0) return;
    final day = plan.days[dayIndex];
    final items = [...day.items];
    final itemIndex =
        items.indexWhere((entry) => entry.exerciseId == item.exerciseId);
    if (itemIndex >= 0) {
      items[itemIndex] = item;
    } else {
      items.add(item);
    }
    final days = [...plan.days];
    days[dayIndex] = day.copyWith(items: items);
    plans[planIndex] = plan.copyWith(days: days);
    await savePlans();
    notifyListeners();
  }

  Future<void> removePlanItem({
    required String planId,
    required int weekday,
    required String exerciseId,
  }) async {
    final planIndex = plans.indexWhere((plan) => plan.id == planId);
    if (planIndex < 0) return;
    final plan = plans[planIndex];
    final dayIndex = plan.days.indexWhere((day) => day.weekday == weekday);
    if (dayIndex < 0) return;
    final day = plan.days[dayIndex];
    final days = [...plan.days];
    days[dayIndex] = day.copyWith(
      items: day.items.where((item) => item.exerciseId != exerciseId).toList(),
    );
    plans[planIndex] = plan.copyWith(days: days);
    await savePlans();
    notifyListeners();
  }

  // ===== Etap 28: postęp programu treningowego =====

  /// Oznacza/odznacza dzień programu jako ukończony i zapisuje postęp.
  Future<void> setPlanDayCompleted(
    String planId,
    int dayIndex, {
    bool completed = true,
  }) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final plan = plans[index];
    if (dayIndex < 0 || dayIndex >= plan.days.length) return;
    final updated = {...plan.completedDays};
    if (completed) {
      updated.add(dayIndex);
    } else {
      updated.remove(dayIndex);
    }
    plans[index] = plan.copyWith(completedDays: updated);
    await savePlans();
    notifyListeners();
  }

  /// Czyści cały postęp programu (wszystkie dni stają się ponownie do zrobienia).
  Future<void> resetPlanProgress(String planId) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    plans[index] = plans[index].copyWith(completedDays: const <int>{});
    await savePlans();
    notifyListeners();
  }

  /// Ustawia poziom programu (metadana nagłówka).
  Future<void> setPlanLevel(String planId, String level) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    plans[index] = plans[index].copyWith(level: level);
    await savePlans();
    notifyListeners();
  }

  /// Włącza/wyłącza tryb „pozwól trenować dowolny dzień" (wyłącza blokowanie).
  Future<void> setPlanAllowAnyDay(String planId, bool value) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    plans[index] = plans[index].copyWith(allowAnyDay: value);
    await savePlans();
    notifyListeners();
  }

  /// Podmienia listę ćwiczeń konkretnego dnia (po indeksie — bezpieczne dla
  /// programów liniowych, gdzie dni mogą powtarzać dzień tygodnia). Etap 29.
  Future<void> updatePlanDayItems(
    String planId,
    int dayIndex,
    List<PlanItem> items,
  ) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final plan = plans[index];
    if (dayIndex < 0 || dayIndex >= plan.days.length) return;
    final days = [...plan.days];
    days[dayIndex] = days[dayIndex].copyWith(items: items);
    plans[index] = plan.copyWith(days: days);
    await savePlans();
    notifyListeners();
  }

  // ===== Warianty programów 30-dniowych + okładka programu =====

  /// Nakłada wariant na program OD KOLEJNEGO (pierwszego nieukończonego) dnia.
  ///
  /// Ochrona postępu (sekcja 38/39 specyfikacji):
  ///  - `completedDays`, historia serii/RPE i identyfikator programu są
  ///    nietknięte,
  ///  - dni wcześniejsze niż dzień startu nie są przeliczane wstecz,
  ///  - moment zmiany wariantu zapisuje się w historii programu.
  Future<void> applyVariantToPlan(String planId, ProgramVariant variant) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final plan = plans[index];
    final fromDay = plan.currentDayIndex.clamp(0, plan.days.length);
    final updated = applyProgramVariant(plan, variant, fromDayIndex: fromDay);
    plans[index] = updated.copyWith(
      activeVariantId: variant.id,
      variantHistory: [
        ...plan.variantHistory,
        ProgramVariantChange(
          variantId: variant.id,
          variantName: variant.name,
          fromDayIndex: fromDay,
          date: DateTime.now(),
        ),
      ],
    );
    await savePlans();
    notifyListeners();
  }

  /// Ustawia multimedia programu (okładka). Osobne pole — obrazy poszczególnych
  /// ćwiczeń pozostają nietknięte. null = usuń okładkę.
  Future<void> setPlanMedia(String planId, ProgramMedia? media) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    plans[index] =
        plans[index].copyWith(media: media, clearMedia: media == null);
    await savePlans();
    notifyListeners();
  }

  /// Generuje okładkę programu przez AI (ta sama ścieżka co obrazy ćwiczeń).
  /// Nowa okładka trafia do poczekalni (`pendingLocalPath`) — stara zostaje
  /// aktywna do czasu zatwierdzenia. Błąd generowania nie blokuje programu.
  Future<void> generateProgramCoverWithAi(String planId) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final plan = plans[index];
    final apiKey = settings.openAiApiKey.trim();
    if (apiKey.isEmpty) {
      throw Exception(
          'Brak klucza API OpenAI. Dodaj go w Więcej → Integracje.');
    }
    WorkoutProgramMeta? meta;
    for (final item in kWorkoutProgramCatalog) {
      if (plan.id.startsWith(item.id)) {
        meta = item;
        break;
      }
    }
    final prompt = buildProgramCoverPrompt(
      programName: plan.name,
      physiqueLabel: bodyGoalProfile?.desiredPhysique.label ?? '',
      strategyLabel: bodyGoalProfile?.bodyCompositionStrategy.label ?? '',
      trainingFocusLabel: bodyGoalProfile?.trainingFocus.label ?? '',
      difficultyLabel: plan.level,
      mainMuscles: meta?.mainMuscles ?? const [],
      equipment: meta?.equipment ?? const [],
    );
    final bytes =
        await OpenAiImageService(apiKey).generateImageFromPrompt(prompt);
    if (bytes.isEmpty) {
      throw Exception('Generator zwrócił pusty obraz — spróbuj ponownie.');
    }
    final documents = await getApplicationDocumentsDirectory();
    final coversDir = Directory('${documents.path}/program_covers');
    if (!await coversDir.exists()) await coversDir.create(recursive: true);
    final file = File('${coversDir.path}/${plan.id}_${idNow()}.png');
    await file.writeAsBytes(bytes, flush: true);
    final media = (plan.media ?? const ProgramMedia()).copyWith(
      pendingLocalPath: file.path,
      generatedPrompt: prompt,
      generationProvider: 'openai',
      generatedAt: DateTime.now(),
      isAiGenerated: true,
    );
    await setPlanMedia(planId, media);
  }

  /// Zatwierdza oczekującą okładkę (dopiero teraz stara jest zastępowana).
  Future<void> approvePlanCover(String planId) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final media = plans[index].media;
    if (media == null || !media.hasPending) return;
    await setPlanMedia(planId, media.approvePending());
  }

  /// Odrzuca oczekującą okładkę — aktywna zostaje bez zmian.
  Future<void> rejectPlanCover(String planId) async {
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) return;
    final media = plans[index].media;
    if (media == null || !media.hasPending) return;
    await setPlanMedia(planId, media.rejectPending());
  }

  /// Generuje wariant programu przez AI na bazie centralnego profilu celu.
  ///
  /// NIE zapisuje niczego i NIE zastępuje aktywnego programu — zwraca wariant
  /// do podglądu; zapis następuje dopiero po zatwierdzeniu przez użytkownika
  /// ([applyVariantToPlan]). Wynik przechodzi walidację (istniejące ćwiczenia,
  /// realna liczba serii, dni regeneracyjne, brak dublowania partii dzień po
  /// dniu) — problemy przerywają operację czytelnym błędem.
  Future<ProgramVariant> generateProgramVariantWithAi(String planId) async {
    final apiKey = settings.geminiApiKey.trim();
    if (apiKey.isEmpty) {
      throw Exception(
          'Brak klucza API Gemini. Dodaj go w Więcej → Integracje.');
    }
    final index = plans.indexWhere((plan) => plan.id == planId);
    if (index < 0) throw Exception('Nie znaleziono programu.');
    final plan = plans[index];
    // Dozwolone ćwiczenia = te już użyte w programie (na pewno istnieją,
    // pasują do sprzętu i poziomu wygenerowanego szablonu).
    final allowed = <String>{
      for (final day in plan.days)
        for (final item in day.items) item.exerciseId,
    }..removeWhere((id) => id.trim().isEmpty);
    if (allowed.isEmpty) {
      throw Exception('Program nie zawiera ćwiczeń do przebudowy.');
    }
    final profile = bodyGoalProfile;
    final prompt = 'Jesteś trenerem układającym 30-dniowe programy. Przebuduj '
        'program "${plan.name}" (${plan.days.length} dni) pod profil użytkownika.\n'
        'PROFIL: poziom ${settings.level}; strategia składu ciała: '
        '${profile?.bodyCompositionStrategy.label ?? settings.trainingMode}; '
        'docelowa sylwetka: ${profile?.desiredPhysique.label ?? '-'}; '
        'priorytet treningowy: ${profile?.trainingFocus.label ?? '-'}; '
        'priorytetowe partie: ${profile?.physiquePriorities.map((p) => p.label).join(', ') ?? '-'}; '
        'dni treningowe w tygodniu: ${settings.trainingWeekdays.length}; '
        'ograniczenia: ${settings.limitations.isEmpty ? 'brak' : settings.limitations}.\n'
        'DOZWOLONE ĆWICZENIA (używaj WYŁĄCZNIE tych identyfikatorów): '
        '${allowed.join(', ')}.\n'
        'ZASADY: zachowaj ${plan.days.length} dni; dni odpoczynku/mobilności '
        'zostaw lżejsze (mało pozycji albo puste items); nie obciążaj tej samej '
        'partii dzień po dniu; serie 1-6; powtórzenia 4-30 ALBO durationSec dla '
        'ćwiczeń czasowych; restSeconds 10-180; bez duplikatów ćwiczeń w dniu.\n'
        'Zwróć WYŁĄCZNIE JSON: {"days": [{"title": string, "items": '
        '[{"exerciseId": string, "sets": number, "reps": number, '
        '"durationSec": number, "restSeconds": number}]}]}';
    final decoded = await _geminiJsonRequest(apiKey, prompt);
    final rawDays = decoded['days'];
    if (rawDays is! List || rawDays.isEmpty) {
      throw Exception('AI nie zwróciło rozkładu dni.');
    }
    final days = <WorkoutDay>[];
    for (var dayIndex = 0; dayIndex < plan.days.length; dayIndex++) {
      final base = plan.days[dayIndex];
      if (dayIndex >= rawDays.length || rawDays[dayIndex] is! Map) {
        days.add(base);
        continue;
      }
      final rawDay = Map<String, dynamic>.from(rawDays[dayIndex] as Map);
      final rawItems = rawDay['items'];
      final items = <PlanItem>[];
      if (rawItems is List) {
        for (final rawItem in rawItems.whereType<Map>()) {
          final id = rawItem['exerciseId']?.toString() ?? '';
          if (!allowed.contains(id)) continue;
          final sets = ((rawItem['sets'] as num?)?.toInt() ?? 3).clamp(1, 6);
          final reps = ((rawItem['reps'] as num?)?.toInt() ?? 0).clamp(0, 30);
          final duration =
              ((rawItem['durationSec'] as num?)?.toInt() ?? 0).clamp(0, 3600);
          final rest =
              ((rawItem['restSeconds'] as num?)?.toInt() ?? 60).clamp(10, 180);
          if (reps <= 0 && duration <= 0) continue;
          items.add(PlanItem(
            exerciseId: id,
            sets: sets,
            reps: duration > 0 ? 0 : (reps < 4 ? 4 : reps),
            durationSec: duration,
            note: 'Wariant AI',
            restSeconds: rest,
          ));
        }
      }
      days.add(base.copyWith(
        title: rawDay['title']?.toString().trim().isNotEmpty == true
            ? rawDay['title'].toString().trim()
            : base.title,
        items: items.isEmpty ? base.items : _dedupPlanItems(items),
      ));
    }
    final variant = ProgramVariant(
      id: 'variant_ai_${idNow()}',
      programId: plan.id,
      name:
          'Wariant AI (${profile?.bodyCompositionStrategy.label ?? 'profil'})',
      difficulty: ProgramDifficulty.fromLevelLabel(plan.level),
      goalAdaptation: ProgramGoalAdaptation.custom,
      description: 'Wygenerowany przez AI pod aktualny profil celu.',
      explicitDays: days,
      isAiGenerated: true,
      createdAt: DateTime.now(),
    );
    final problems = validateProgramVariant(
      variant,
      exerciseExists: allowed.contains,
      maxSetsPerItem: 6,
      minRestSeconds: 10,
    );
    if (problems.isNotEmpty) {
      throw Exception(
          'Wariant AI nie przeszedł walidacji:\n${problems.take(5).join('\n')}');
    }
    return variant;
  }

  List<PlanItem> _dedupPlanItems(List<PlanItem> items) {
    final seen = <String>{};
    return [
      for (final item in items)
        if (seen.add(item.exerciseId)) item,
    ];
  }

  /// Proste zapytanie JSON do Gemini z fallbackiem modeli (jak analiza zdjęć).
  Future<Map<String, dynamic>> _geminiJsonRequest(
      String apiKey, String prompt) async {
    Object? lastError;
    for (final model in const [
      'gemini-2.5-flash',
      'gemini-2.0-flash',
      'gemini-1.5-flash'
    ]) {
      try {
        final uri = Uri.parse(
          'https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent',
        ).replace(queryParameters: {'key': apiKey});
        final response = await http
            .post(
              uri,
              headers: {'Content-Type': 'application/json'},
              body: jsonEncode({
                'contents': [
                  {
                    'role': 'user',
                    'parts': [
                      {'text': prompt},
                    ],
                  },
                ],
                'generationConfig': {
                  'temperature': 0.5,
                  'responseMimeType': 'application/json',
                },
              }),
            )
            .timeout(const Duration(seconds: 120));
        if (response.statusCode < 200 || response.statusCode >= 300) {
          throw Exception('Gemini HTTP ${response.statusCode}');
        }
        final data = jsonDecode(utf8.decode(response.bodyBytes));
        final candidates = data is Map ? data['candidates'] : null;
        if (candidates is! List || candidates.isEmpty) {
          throw Exception('Gemini: pusta odpowiedź.');
        }
        final content = (candidates.first as Map)['content'];
        final parts = content is Map ? content['parts'] : null;
        final buffer = StringBuffer();
        if (parts is List) {
          for (final part in parts) {
            if (part is Map && part['text'] != null) buffer.write(part['text']);
          }
        }
        final text = buffer.toString().trim();
        final decoded = jsonDecode(
          text.startsWith('```')
              ? text
                  .replaceAll(RegExp(r'^```[a-z]*|```$', multiLine: true), '')
                  .trim()
              : text,
        );
        if (decoded is Map) return Map<String, dynamic>.from(decoded);
        throw Exception('Gemini: odpowiedź nie jest obiektem JSON.');
      } catch (error) {
        lastError = error;
        final text = error.toString().toLowerCase();
        final modelIssue = text.contains('not found') ||
            text.contains('404') ||
            text.contains('unsupported') ||
            text.contains('permission');
        if (modelIssue) continue;
        rethrow;
      }
    }
    throw Exception('Gemini: $lastError');
  }

  Future<void> saveSettings() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(_settingsKey, jsonEncode(settings.toJson()));
  }

  Future<void> saveCustomExercises() async {
    await _trainerRepository.saveCustomExercises(customExercises);
  }

  Future<void> saveBodyMeasurements() async {
    await _trainerRepository.saveBodyMeasurements(bodyMeasurements);
  }

  Future<void> saveTrainingImpacts() async {
    await _trainerRepository.saveTrainingImpacts(trainingImpacts);
    await _calorieAdapter.publishTrainingImpacts(trainingImpacts);
    await publishDailyAdjustmentsBridge(notify: false);
  }

  /// Ponownie publikuje most kalorii dla Licznika Kalorii (spalone kcal
  /// z treningów + pakiety korekty dnia).
  Future<void> publishCalorieBridge() async {
