  // --- Korekta dnia: Trainer jako centrum aktywności dla Licznika Kalorii ---

  static const _adjustmentsSignatureKey =
      'trainer_daily_adjustments_signature_v1';

  /// Moment ostatniej publikacji pakietów korekty dnia dla Licznika Kalorii.
  DateTime? lastDailyAdjustmentsPublishAt;

  /// Sygnatura ostatnio opublikowanych pakietów — porównanie z bieżącym
  /// stanem mówi, czy dane w moście są aktualne ("Zsynchronizowano").
  String? _publishedAdjustmentsSignature;

  /// Buduje korektę dnia dla wskazanej daty z aktualnych danych
  /// (kredyty aktywności po deduplikacji + snapshot Health Connect).
  TrainerDailyAdjustment dailyAdjustmentForDay(DateTime day) {
    return buildTrainerDailyAdjustment(
      day: day,
      decisions: activityCreditDecisionsForDay(day),
      impactsForDay:
          trainingImpacts.where((impact) => sameDay(impact.date, day)).toList(),
      snapshot: healthConnectSnapshotForDay(day),
      bodyWeightKg: settings.bodyWeightKg,
      workIntensity: settings.workIntensity,
      workHoursPerDay: settings.workHoursPerDay,
      workWeekdays: settings.workWeekdays,
    );
  }

  /// Czy pakiet korekty dnia w moście odpowiada bieżącym danym Trainera.
  bool get dailyAdjustmentsSynced {
    final published = _publishedAdjustmentsSignature;
    if (published == null || published.isEmpty) return false;
    return published == _adjustmentsSignature(_buildRecentDailyAdjustments());
  }

  /// Pakiety korekty dla ostatnich dni (dzisiaj + 13 wstecz) oraz dni,
  /// które mają zapisane aktywności/treningi w ostatnich 30 dniach.
  List<TrainerDailyAdjustment> _buildRecentDailyAdjustments() {
    final today = DateTime.now();
    final days = <String, DateTime>{};
    void addDay(DateTime value) {
      final normalized = DateTime(value.year, value.month, value.day);
      String two(int v) => v.toString().padLeft(2, '0');
      days['${normalized.year}-${two(normalized.month)}-${two(normalized.day)}'] =
          normalized;
    }

    for (var offset = 0; offset < 14; offset++) {
      addDay(today.subtract(Duration(days: offset)));
    }
    final horizon = today.subtract(const Duration(days: 30));
    for (final impact in trainingImpacts) {
      if (impact.date.isAfter(horizon)) addDay(impact.date);
    }
    for (final entry in activityEntries) {
      if (entry.date.isAfter(horizon)) addDay(entry.date);
    }

    final adjustments = days.values
        .map(dailyAdjustmentForDay)
        .where((adjustment) => adjustment.hasAnyData)
        .toList()
      ..sort((left, right) => right.date.compareTo(left.date));
    return adjustments;
  }

  /// Sygnatura niezależna od createdAt/updatedAt (te zmieniają się przy
  /// każdym przeliczeniu) — tylko wartości, które widzi Licznik Kalorii.
  String _adjustmentsSignature(List<TrainerDailyAdjustment> adjustments) {
    final base = adjustments
        .map((a) =>
            '${a.dateKey}:${a.totalAdjustmentKcal}:${a.workoutKcal}:${a.stepsKcal}:${a.runKcal}'
            ':${a.walkKcal}:${a.otherKcal}:${a.extraWaterMl}:${a.extraCarbsG}:${a.extraProteinG}'
            ':${a.workoutExtraWaterMl}:${a.workoutExtraCarbsG}:${a.workoutExtraProteinG}:${a.dataStatus}')
        .join('|');
    // Zmiana celów żywieniowych (profil celu) też wymaga ponownej publikacji.
    final targets = goalNutritionTargets;
    return targets == null ? base : '$base#${targets.signature}';
  }

  /// Aktualna masa ciała: najnowszy pomiar z wagą, inaczej profil.
  double get currentBodyWeightKg {
    for (final measurement in bodyMeasurements) {
      if (measurement.weightKg > 0) return measurement.weightKg;
    }
    return settings.bodyWeightKg;
  }

  /// Najnowsza wiarygodna analiza sylwetki (pomija oznaczone jako
  /// „niska wiarygodność").
  BodyAnalysisResult? get latestReliableBodyAnalysis {
    for (final analysis in bodyAnalyses) {
      if (!analysis.lowReliability && analysis.composition.bodyFatPercent > 0) {
        return analysis;
      }
    }
    return null;
  }

  /// FFM z najnowszej wiarygodnej analizy, przeliczona na AKTUALNĄ masę
  /// ciała (0 = brak danych).
  double get currentFatFreeMassKg {
    final analysis = latestReliableBodyAnalysis;
    if (analysis == null) return 0;
    final breakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: currentBodyWeightKg,
      bodyFatPercent: analysis.composition.bodyFatPercent,
    );
    return breakdown?.fatFreeMassKg ?? 0;
  }

  /// Dzienne cele żywieniowe z CENTRALNEGO PROFILU CELU. Kalorie wynikają
  /// z AKTUALNEJ STRATEGII składu ciała (redukcja/rekompozycja/masa/…),
  /// nigdy z nazwy docelowej sylwetki. null = profil nieskonfigurowany
  /// (Licznik Kalorii zostaje przy własnych celach).
  GoalNutritionTargets? get goalNutritionTargets => computeGoalNutritionTargets(
        profile: bodyGoalProfile,
        weightKg: currentBodyWeightKg,
        heightCm: settings.heightCm,
        age: settings.age,
        sex: settings.sex,
        trainingDaysPerWeek: settings.trainingWeekdays.length,
        fatFreeMassKg: currentFatFreeMassKg,
      );

  /// Publikuje pakiety korekty dnia do mostu dla Licznika Kalorii.
  /// Bezpieczne przy braku zmian (nadpisuje ten sam stan) i odporne na błędy.
  Future<void> publishDailyAdjustmentsBridge({bool notify = true}) async {
    try {
      final adjustments = _buildRecentDailyAdjustments();
      // Cele jadą mostem tylko, gdy użytkownik nie wyłączył automatycznej
      // publikacji celu do Kalorii (korekty aktywności jadą zawsze).
      final targets = (bodyGoalProfile?.autoPublishToCalories ?? true)
          ? goalNutritionTargets
          : null;
      // Cele z sylwetki muszą dojechać nawet w dzień bez aktywności —
      // dopilnuj, żeby pakiet na dziś istniał (Licznik czyta najnowszy wiersz).
      final today = DateTime.now();
      if (targets != null && !adjustments.any((a) => sameDay(a.date, today))) {
        adjustments.insert(0, dailyAdjustmentForDay(today));
      }
      lastDailyAdjustmentsPublishAt =
          await _calorieAdapter.publishDailyAdjustments(
        adjustments,
        nutritionTargets: targets?.toJson(),
      );
      _publishedAdjustmentsSignature = _adjustmentsSignature(adjustments);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
          _adjustmentsSignatureKey, _publishedAdjustmentsSignature!);
    } catch (_) {
      // Publikacja mostu nie może wywrócić zapisu danych treningowych.
    }
    if (notify) notifyListeners();
  }

  // --- Automatyczna synchronizacja Samsung Health / Health Connect / Kalorie ---

  DateTime? lastHealthAutoSyncAt;
  bool healthAutoSyncInProgress = false;

  /// Status pokazywany w UI: „Synchronizuję dane…", „Zsynchronizowano 14:35",
  /// „Brak zgody na Health Connect", „Błąd synchronizacji"…
  String healthSyncStatus = '';

  /// Dziennik synchronizacji (diagnostyka): co pobrano, co policzono
  /// fallbackiem, jakie sesje wykryto, czy dane są częściowe.
  final List<String> healthSyncLog = [];

  void _healthSyncLogAdd(String message) {
    final now = DateTime.now();
    String two(int value) => value.toString().padLeft(2, '0');
    healthSyncLog.insert(0, '${two(now.hour)}:${two(now.minute)}  $message');
    if (healthSyncLog.length > 40) {
      healthSyncLog.removeRange(40, healthSyncLog.length);
    }
  }

  /// Pełna, cicha synchronizacja: status zgód → dane dnia → sesje (dziś +
  /// 2 dni wstecz) → szacunki → publikacja pakietu do Kalorii. Wywoływana
  /// automatycznie (start / powrót do aplikacji / co 15 min / po treningu),
  /// bez blokowania UI. Przy braku zgód kończy się czytelnym statusem.
  Future<void> autoSyncHealthConnect({bool force = false}) async {
    if (healthAutoSyncInProgress) return;
    final now = DateTime.now();
    if (!force &&
        lastHealthAutoSyncAt != null &&
        now.difference(lastHealthAutoSyncAt!) < const Duration(minutes: 5)) {
      return;
    }
    healthAutoSyncInProgress = true;
    healthSyncStatus = 'Synchronizuję dane…';
    notifyListeners();
    String two(int value) => value.toString().padLeft(2, '0');
    try {
      final status = await _healthConnectService.checkStatus(date: now);
      if (!status.isAvailable) {
        healthSyncStatus = 'Health Connect niedostępny';
        _healthSyncLogAdd(
            'Sync przerwany: Health Connect niedostępny (${status.sdkStatus}).');
        return;
      }
      if (status.grantedPermissions.isEmpty) {
        healthSyncStatus = 'Brak zgody na Health Connect';
        _healthSyncLogAdd('Sync przerwany: brak zgód Health Connect.');
        return;
      }
      final snapshot = await _healthConnectService.readDailyData(date: now);
      await upsertHealthConnectSnapshot(snapshot, notify: false);
      _healthSyncLogAdd(
        'Dzień z HC: ${snapshot.steps} kroków, ${snapshot.distanceKm.toStringAsFixed(2)} km, '
        '${snapshot.activeKcal.round()} kcal, sesje: ${snapshot.workoutSessions}.',
      );
      for (var offset = 0; offset < 3; offset++) {
        await _importHealthConnectWorkoutSessions(
            DateTime(now.year, now.month, now.day)
                .subtract(Duration(days: offset)));
      }
      await _enrichHealthConnectSnapshotForDay(now);
      await publishDailyAdjustmentsBridge(notify: false);
      lastHealthAutoSyncAt = now;
      final partial =
          snapshot.missingData.isNotEmpty || !snapshot.permissionsGranted;
      healthSyncStatus =
          'Zsynchronizowano ${two(now.hour)}:${two(now.minute)}${partial ? ' · dane częściowe' : ''}';
      _healthSyncLogAdd(
          'Sync OK${partial ? ' (dane częściowe)' : ''}; pakiet korekty wysłany do Kalorii.');
    } catch (error) {
      healthSyncStatus = 'Błąd synchronizacji';
      final text = error.toString().replaceAll(RegExp(r'\s+'), ' ');
      _healthSyncLogAdd(
          'Błąd synchronizacji: ${text.length > 90 ? text.substring(0, 90) : text}');
    } finally {
      healthAutoSyncInProgress = false;
      notifyListeners();
    }
  }

