  /// Generuje obraz ćwiczenia przez OpenAI (klucz z ustawień), zapisuje PNG
  /// w katalogu dokumentów aplikacji i przypisuje go do ćwiczenia jako
  /// [Exercise.imagePath]. Dla ćwiczeń wbudowanych tworzona jest lokalna
  /// nadpisująca kopia (mechanizm customExercises — [ExerciseRepo.byId]
  /// preferuje wersję użytkownika). Zwraca zaktualizowane ćwiczenie.
  Future<Exercise> generateExerciseImageWithAi(Exercise exercise) async {
    final apiKey = settings.openAiApiKey.trim();
    if (apiKey.isEmpty) {
      throw Exception(
          'Brak klucza API OpenAI. Dodaj go w Więcej → Integracje.');
    }
    final bytes =
        await OpenAiImageService(apiKey).generateExerciseImage(exercise);
    final documents = await getApplicationDocumentsDirectory();
    final imagesDir = Directory('${documents.path}/exercise_images');
    if (!await imagesDir.exists()) await imagesDir.create(recursive: true);
    final file = File('${imagesDir.path}/${exercise.id}_${idNow()}.png');
    await file.writeAsBytes(bytes, flush: true);
    final updated = exercise.copyWith(
      imagePath: file.path,
      source: exercise.source == 'local' ? 'custom' : exercise.source,
    );
    await addCustomExercise(updated);
    return updated;
  }

  /// Generuje ustrukturyzowany opis ćwiczenia przez Gemini. NIE zapisuje nic —
  /// zwraca podgląd do zatwierdzenia/edycji przez użytkownika. Zabezpiecza przed
  /// brakiem klucza i pustą odpowiedzią AI.
  Future<GeneratedExerciseInfo> generateExerciseDescriptionWithGemini(
      Exercise exercise) async {
    final apiKey = settings.geminiApiKey.trim();
    if (apiKey.isEmpty) {
      throw Exception(
          'Brak klucza API Gemini. Dodaj go w Więcej → Integracje.');
    }
    final info = await GeminiExerciseService(apiKey).generate(exercise);
    if (info.isEmpty) {
      throw Exception('Gemini zwrócił pustą odpowiedź. Spróbuj ponownie.');
    }
    return info;
  }

  /// Scala zatwierdzony opis AI z ćwiczeniem i zapisuje je jako własne/edytowane.
  /// Nadpisywane są tylko pola przekazane w [info] (puste pola nie kasują danych).
  Future<Exercise> applyGeneratedExerciseInfo(
    Exercise exercise,
    GeneratedExerciseInfo info,
  ) async {
    final muscles = <String>[
      ...info.primaryMuscles,
      ...info.secondaryMuscles,
    ].where((m) => m.trim().isNotEmpty).toList();
    final updated = exercise.copyWith(
      description: info.description.trim().isEmpty
          ? exercise.description
          : info.description.trim(),
      executionSteps: info.executionSteps.isEmpty
          ? exercise.executionSteps
          : info.executionSteps,
      tips: info.tips.isEmpty ? exercise.tips : info.tips,
      commonMistakes: info.commonMistakes.isEmpty
          ? exercise.commonMistakes
          : info.commonMistakes,
      muscles: muscles.isEmpty ? exercise.muscles : muscles,
      equipment: info.equipment.trim().isEmpty
          ? exercise.equipment
          : info.equipment.trim(),
      level: info.level.trim().isEmpty
          ? exercise.level
          : normalizeTrainingLevel(info.level),
      avoidWhen:
          info.safetyNotes.isEmpty ? exercise.avoidWhen : info.safetyNotes,
      source: exercise.source == 'local' ? 'edited' : exercise.source,
    );
    await addCustomExercise(updated);
    return updated;
  }

  Future<void> addCustomExercise(Exercise exercise) async {
    final cleaned = exercise.copyWith(
        source: exercise.source.isEmpty ? 'wger' : exercise.source);
    final index = customExercises.indexWhere((e) => e.id == cleaned.id);
    if (index >= 0) {
      customExercises[index] = cleaned;
    } else {
      customExercises.insert(0, cleaned);
    }
    await saveCustomExercises();
    notifyListeners();
  }

  Future<void> deleteCustomExercise(String id) async {
    customExercises.removeWhere((e) => e.id == id);
    await saveCustomExercises();
    notifyListeners();
  }

  Future<void> addBodyMeasurement(BodyMeasurement measurement) async {
    if (!measurement.hasAnyMeasurement && measurement.note.trim().isEmpty) {
      return;
    }
    bodyMeasurements.insert(0, measurement);
    bodyMeasurements.sort((left, right) => right.date.compareTo(left.date));
    await saveBodyMeasurements();
    notifyListeners();
  }

