  /// Kontekst danych do analizy sylwetki — „wszystko, co ma wpływ":
  /// profil, pomiary (z trendem), treningi 30 dni, regeneracja, aktywność
  /// i kalorie z mostu do Licznika. Zwraca też listę etykiet użytych danych.
  ({Map<String, dynamic> json, List<String> used}) buildBodyAnalysisContext(
      [DateTime? now]) {
    final reference = now ?? DateTime.now();
    final used = <String>['profil (wzrost, masa, wiek, cel)'];
    final context = <String, dynamic>{'profile': settings.toAiProfile()};

    // Pomiary: najnowszy + poprzedni (trend).
    final sortedMeasurements = [...bodyMeasurements]
      ..sort((a, b) => b.date.compareTo(a.date));
    if (sortedMeasurements.isNotEmpty) {
      Map<String, dynamic> measurementJson(BodyMeasurement m) => {
            'date': '${m.date.year}-${m.date.month}-${m.date.day}',
            if (m.weightKg > 0) 'weightKg': m.weightKg,
            if (m.waistCm > 0) 'waistCm': m.waistCm,
            if (m.chestCm > 0) 'chestCm': m.chestCm,
            if (m.armCm > 0) 'armCm': m.armCm,
            if (m.thighCm > 0) 'thighCm': m.thighCm,
            if (m.hipsCm > 0) 'hipsCm': m.hipsCm,
            if (m.calfCm > 0) 'calfCm': m.calfCm,
            if (m.shouldersCm > 0) 'shouldersCm': m.shouldersCm,
            if (m.neckCm > 0) 'neckCm': m.neckCm,
          };
      context['latestMeasurement'] = measurementJson(sortedMeasurements.first);
      if (sortedMeasurements.length > 1) {
        context['previousMeasurement'] = measurementJson(sortedMeasurements[1]);
      }
      used.add('pomiary sylwetki (${sortedMeasurements.length})');
    }

    // Treningi ostatnich 30 dni: objętość, sesje, najczęstsze partie.
    final monthAgo = reference.subtract(const Duration(days: 30));
    final recentLogs = logsBetween(monthAgo, reference);
    if (recentLogs.isNotEmpty) {
      final muscleCounts = <String, int>{};
      var volume = 0.0;
      for (final log in recentLogs) {
        volume += log.volume.isFinite ? log.volume : 0;
        final exercise = ExerciseRepo.byId(log.exerciseId, customExercises);
        for (final impact in exercise.effectiveMuscleImpacts) {
          if (impact.role == MuscleRole.primary) {
            muscleCounts[impact.muscleGroup.label] =
                (muscleCounts[impact.muscleGroup.label] ?? 0) + 1;
          }
        }
      }
      final topMuscles = muscleCounts.entries.toList()
        ..sort((a, b) => b.value.compareTo(a.value));
      context['training30Days'] = {
        'workoutEntries': recentLogs.length,
        'totalVolumeKg': volume.round(),
        'topTrainedMuscles': [
          for (final entry in topMuscles.take(6)) entry.key
        ],
      };
      used.add('treningi 30 dni (${recentLogs.length} wpisów)');
    }

    // Regeneracja: partie zmęczone teraz.
    final recovery = muscleRecoveryMap(reference);
    final tired = <String>[];
    recovery.forEach((muscle, state) {
      final percent = state.recoveryPercent;
      if (state.hasData && percent != null && percent < 70) {
        tired.add('${muscle.label} (${percent.round()}%)');
      }
    });
    if (tired.isNotEmpty) {
      context['musclesInRecovery'] = tired;
      used.add('mapa regeneracji');
    }

    // Aktywność i kalorie (most do Licznika Kalorii + Health Connect).
    final weekAgo = reference.subtract(const Duration(days: 7));
    var burned7 = 0;
    for (final impact in trainingImpacts) {
      if (!impact.date.isBefore(weekAgo)) burned7 += impact.estimatedBurnedKcal;
    }
    final adjustment = dailyAdjustmentForDay(reference);
    final health = healthConnectSnapshotForDay(reference);
    context['activityAndCalories'] = {
      'burnedKcalLast7Days': burned7,
      'todayAdjustmentKcal': adjustment.totalAdjustmentKcal,
      if (adjustment.extraProteinG > 0)
        'todayExtraProteinG': adjustment.extraProteinG,
      if (adjustment.extraWaterMl > 0)
        'todayExtraWaterMl': adjustment.extraWaterMl,
      if (health != null && health.steps > 0) 'todaySteps': health.steps,
      if (health != null && health.activeKcal > 0)
        'todayActiveKcal': health.activeKcal,
    };
    used.add('kalorie i aktywność (most do Licznika)');

    final target = SilhouetteGoal.fromId(settings.targetSilhouette);
    if (target != null) context['targetSilhouette'] = target.label;
    return (json: context, used: used);
  }

  /// Lokalny szacunek składu ciała z aktualnych danych (bez zdjęć i AI):
  /// wzory antropometryczne na bazie profilu + najnowszego pomiaru.
  BodyCompositionEstimate localBodyCompositionEstimate() {
    final latest = bodyMeasurements.isEmpty ? null : bodyMeasurements.first;
    return estimateBodyCompositionLocally(
      weightKg: (latest?.weightKg ?? 0) > 0
          ? latest!.weightKg
          : settings.bodyWeightKg,
      heightCm: settings.heightCm,
      age: settings.age,
      sex: settings.sex,
      waistCm: latest?.waistCm ?? 0,
      neckCm: latest?.neckCm ?? 0,
      hipsCm: latest?.hipsCm ?? 0,
    );
  }

  /// Pełna analiza sylwetki. Zdjęcia robocze (przód/bok/tył) analizowane są
  /// w JEDNYM zapytaniu AI (Gemini → OpenAI). Bez zdjęć albo bez klucza API
  /// powstaje szacunek lokalny ze wzorów. Wynik trafia do historii analiz.
  Future<BodyAnalysisResult> analyzeBodyPhotos() async {
    bodyAnalysisBusy = true;
    notifyListeners();
    try {
      final photos = <BodyPhotoInput>[];
      for (final view in const ['front', 'side', 'back']) {
        final path = progressPhotoDrafts[view] ?? '';
        if (path.isEmpty) continue;
        final file = File(path);
        if (!await file.exists()) continue;
        photos.add(BodyPhotoInput(view: view, bytes: await file.readAsBytes()));
      }
      final target = SilhouetteGoal.fromId(settings.targetSilhouette);
      final contextData = buildBodyAnalysisContext();
      final service = BodyPhotoAnalysisService(
        geminiApiKey: settings.geminiApiKey,
        openAiApiKey: settings.openAiApiKey,
      );

      BodyAnalysisResult result;
      if (photos.isNotEmpty && service.hasAnyKey) {
        final response = await service.analyze(
          photos: photos,
          context: contextData.json,
          targetGoal: target,
        );
        result = BodyAnalysisResult.fromAiJson(
          response.json,
          id: 'analysis_${idNow()}',
          date: DateTime.now(),
          source: response.source,
          photoFrontPath: progressPhotoDrafts['front'] ?? '',
          photoSidePath: progressPhotoDrafts['side'] ?? '',
          photoBackPath: progressPhotoDrafts['back'] ?? '',
          targetSilhouetteId: settings.targetSilhouette,
          contextUsed: contextData.used,
          modelVersion: response.model,
          // Surowa odpowiedź AI zostaje do diagnostyki — nie jest pokazywana
          // jako zweryfikowany wynik.
          rawAiJson: jsonEncode(response.json),
        );
        // AI nie zwróciło składu ciała → uzupełnij wzorami lokalnymi.
        if (!result.composition.hasData) {
          result = BodyAnalysisResult.fromJson(result.toJson()
            ..['composition'] = localBodyCompositionEstimate().toJson());
        }
      } else {
        final composition = localBodyCompositionEstimate();
        if (!composition.hasData) {
          throw Exception(
              'Uzupełnij profil (masa, wzrost) albo dodaj pomiar, żeby policzyć szacunek lokalny.');
        }
        result = BodyAnalysisResult(
          id: 'analysis_${idNow()}',
          date: DateTime.now(),
          photoFrontPath: progressPhotoDrafts['front'] ?? '',
          photoSidePath: progressPhotoDrafts['side'] ?? '',
          photoBackPath: progressPhotoDrafts['back'] ?? '',
          composition: composition,
          currentSilhouette: 'Szacunek lokalny (wzory antropometryczne)',
          targetSilhouetteId: settings.targetSilhouette,
          summary: photos.isEmpty
              ? 'Analiza policzona lokalnie ze wzorów (US Navy / Deurenberg, Watson, Lee) na bazie profilu i pomiarów. '
                  'Dodaj zdjęcia przód/bok/tył oraz klucz API Gemini lub OpenAI w Więcej → Integracje, żeby uzyskać pełną analizę wizualną.'
              : 'Brak klucza API Gemini/OpenAI — zdjęcia nie zostały przeanalizowane, skład ciała policzono lokalnie ze wzorów. '
                  'Dodaj klucz w Więcej → Integracje, żeby uzyskać pełną analizę wizualną.',
          trainingRecommendations:
              target == null ? const [] : [target.strategy],
          risks: const [
            'Szacunek matematyczny — dokładność niższa niż analiza zdjęć albo badanie składu ciała.'
          ],
          confidencePercent: 40,
          source: 'local',
          contextUsed: contextData.used,
        );
      }

      // --- Wzbogacenie i walidacja biologiczna PRZED zapisem. ---
      // Masa/talia z dnia analizy + zakres BF + migawka celu; wynik, który
      // nie przechodzi walidacji, jest oznaczany jako „niska wiarygodność"
      // (nie zapisujemy podejrzanej wartości jako pewnego faktu).
      final weightAtAnalysis = weightForAnalysis(result);
      double waistAtAnalysis = 0;
      for (final measurement in bodyMeasurements) {
        if (measurement.waistCm > 0 && !measurement.date.isAfter(result.date)) {
          waistAtAnalysis = measurement.waistCm;
          break;
        }
      }
      final validation = validateBodyComposition(
        bodyWeightKg: weightAtAnalysis,
        bodyFatPercent: result.composition.bodyFatPercent,
        musclePercent: result.composition.musclePercent,
        waterPercent: result.composition.waterPercent,
        bonePercent: result.composition.bonePercent,
      );
      var rangeMin = result.bodyFatRangeMinPercent;
      var rangeMax = result.bodyFatRangeMaxPercent;
      if (rangeMin <= 0 || rangeMax <= 0 || rangeMin > rangeMax) {
        final range = bodyFatRangeForConfidence(
          bodyFatPercent: result.composition.bodyFatPercent,
          confidencePercent: result.confidencePercent,
        );
        rangeMin = range.min;
        rangeMax = range.max;
      }
      result = result.copyWith(
        schemaVersion: 2,
        bodyWeightKgAtAnalysis: weightAtAnalysis,
        waistCmAtAnalysis: waistAtAnalysis,
        bodyFatRangeMinPercent: rangeMin,
        bodyFatRangeMaxPercent: rangeMax,
        validationIssues: validation.messages,
        lowReliability: !validation.isReliable,
        confidencePercent: validation.isReliable
            ? result.confidencePercent
            : math.min(result.confidencePercent, 35),
        strategyIdAtAnalysis: bodyGoalProfile?.bodyCompositionStrategy.id ?? '',
        physiqueIdAtAnalysis: bodyGoalProfile?.desiredPhysique.id ?? '',
      );

      bodyAnalyses.insert(0, result);
      bodyAnalyses.sort((left, right) => right.date.compareTo(left.date));
      await saveBodyAnalyses();
      return result;
    } finally {
      bodyAnalysisBusy = false;
      notifyListeners();
    }
  }

  Future<void> deleteBodyAnalysis(String id) async {
    bodyAnalyses.removeWhere((analysis) => analysis.id == id);
    await saveBodyAnalyses();
    notifyListeners();
  }

  /// Masa ciała obowiązująca w dniu analizy — najbliższy pomiar z wagą
  /// sprzed/z dnia analizy, inaczej najnowszy pomiar, inaczej profil.
  double weightForAnalysis(BodyAnalysisResult analysis) {
    BodyMeasurement? bestBefore;
    BodyMeasurement? newestAny;
    for (final measurement in bodyMeasurements) {
      if (measurement.weightKg <= 0) continue;
      newestAny ??= measurement; // lista jest sortowana malejąco po dacie
      if (!measurement.date.isAfter(analysis.date) &&
          (bestBefore == null || measurement.date.isAfter(bestBefore.date))) {
        bestBefore = measurement;
      }
    }
    return bestBefore?.weightKg ?? newestAny?.weightKg ?? settings.bodyWeightKg;
  }

  // --- Plakietki powiadomień na ikonach paska „Dzisiaj" ---
  //
  // Działają jak nieprzeczytane wiadomości: każda ikona ma listę „nowości"
  // dnia (identyfikatory ważnych zdarzeń); wejście w ikonę odhacza aktualny
  // stan, a plakietka pokazuje tylko to, czego użytkownik jeszcze nie widział.

  /// Identyfikatory ważnych zdarzeń dla ikony paska Dzisiaj
  /// ('run' / 'walk' / 'training' / 'sleep' / 'heart').
  List<String> activityIconNews(String iconKey, [DateTime? now]) {
    final reference = now ?? DateTime.now();
    final news = <String>[];
    switch (iconKey) {
      case 'run':
        for (final entry in activityEntries) {
          if (!sameDay(entry.date, reference)) continue;
          if (entry.type == TrainerActivityType.run ||
              entry.type == TrainerActivityType.bike) {
            news.add('run_${entry.id}');
          }
        }
      case 'walk':
        for (final entry in activityEntries) {
          if (!sameDay(entry.date, reference)) continue;
          if (entry.type == TrainerActivityType.measuredWalk ||
              entry.type == TrainerActivityType.ordinaryStepsWalk) {
            news.add('walk_${entry.id}');
          }
        }
        // Kamienie milowe kroków dnia — osiągnięcie progu to „coś ważnego".
        final snapshot = healthConnectSnapshotForDay(reference);
        if (snapshot != null) {
          for (final milestone in const [5000, 10000, 15000, 20000]) {
            if (snapshot.steps >= milestone)
              news.add('steps_${snapshot.dateKey}_$milestone');
          }
        }
      case 'training':
        final active = activeWorkoutSession;
        if (active != null) news.add('active_${active.id}');
        final seenSessions = <String>{};
        for (final log in logs) {
          if (!sameDay(log.date, reference)) continue;
          final key = log.sessionId.isEmpty ? log.id : log.sessionId;
          if (seenSessions.add(key)) news.add('workout_$key');
        }
        final analysis = latestBodyAnalysis;
        if (analysis != null && sameDay(analysis.date, reference)) {
          news.add('analysis_${analysis.id}');
        }
      case 'sleep':
        final snapshot = healthConnectSnapshotForDay(reference);
        if (snapshot != null && snapshot.sleepMinutes > 0) {
          news.add('sleep_${snapshot.dateKey}_${snapshot.sleepMinutes}');
        }
      case 'heart':
        final snapshot = healthConnectSnapshotForDay(reference);
        if (snapshot != null && snapshot.averageHeartRate > 0) {
          // Kubełki co 5 bpm — drobne wahania średniej nie budzą plakietki.
          final bucket = (snapshot.averageHeartRate / 5).round() * 5;
          news.add('heart_${snapshot.dateKey}_$bucket');
        }
    }
    return news;
  }

  /// Liczba nieodhaczonych nowości dla ikony (0 = bez plakietki).
  int activityIconBadgeCount(String iconKey, [DateTime? now]) {
    final seen = (_activityIconSeenNews[iconKey] ?? const []).toSet();
    return activityIconNews(iconKey, now)
        .where((id) => !seen.contains(id))
        .length;
  }

  /// Odhacza aktualne nowości ikony (wejście w ikonę = „przeczytane").
  Future<void> markActivityIconSeen(String iconKey, [DateTime? now]) async {
    final current = activityIconNews(iconKey, now);
    final existing = _activityIconSeenNews[iconKey] ?? const [];
    final merged = {...existing, ...current}.toList();
    // Ogranicz rozmiar — stare identyfikatory (sprzed kilku dni) są bezużyteczne.
    if (merged.length > 40) merged.removeRange(0, merged.length - 40);
    _activityIconSeenNews[iconKey] = merged;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(
        _activityIconSeenKey, jsonEncode(_activityIconSeenNews));
    notifyListeners();
  }

  /// Zapisuje wymiary odczytane z analizy jako normalny pomiar sylwetki —
  /// zamiast ręcznego wpisywania obwodów.
  Future<BodyMeasurement?> saveAnalysisAsMeasurement(
      BodyAnalysisResult analysis) async {
    final cm = analysis.estimatedMeasurementsCm;
    if (cm.isEmpty) return null;
    final latestWeight =
        bodyMeasurements.isEmpty ? 0.0 : bodyMeasurements.first.weightKg;
    final measurement = BodyMeasurement(
      id: 'measurement_${idNow()}',
      date: analysis.date,
      weightKg: latestWeight > 0 ? latestWeight : settings.bodyWeightKg,
      waistCm: cm['waist'] ?? 0,
      chestCm: cm['chest'] ?? 0,
      armCm: cm['arm'] ?? 0,
      thighCm: cm['thigh'] ?? 0,
      hipsCm: cm['hips'] ?? 0,
      calfCm: cm['calf'] ?? 0,
      shouldersCm: cm['shoulders'] ?? 0,
      neckCm: cm['neck'] ?? 0,
      note: 'Wymiary z analizy sylwetki AI (szacunek ze zdjęć)',
      progressPhotoPaths: [
        if (analysis.photoFrontPath.isNotEmpty) analysis.photoFrontPath,
        if (analysis.photoSidePath.isNotEmpty) analysis.photoSidePath,
        if (analysis.photoBackPath.isNotEmpty) analysis.photoBackPath,
      ],
    );
    await addBodyMeasurement(measurement);
    return measurement;
  }

  Future<void> upsertTrainingImpact(TrainingImpact impact) async {
    final index = trainingImpacts.indexWhere((item) =>
        item.deduplicationKey == impact.deduplicationKey ||
        item.sessionId == impact.sessionId);
    if (index >= 0) {
      trainingImpacts[index] = impact;
    } else {
      trainingImpacts.insert(0, impact);
    }
    trainingImpacts.sort((left, right) => right.date.compareTo(left.date));
    await saveTrainingImpacts();
  }

  Future<void> upsertActivityEntry(TrainerActivityEntry entry) async {
    final index = activityEntries.indexWhere((item) =>
        item.id == entry.id ||
        item.stableActivityKey == entry.stableActivityKey);
    if (index >= 0) {
      activityEntries[index] = entry;
    } else {
      activityEntries.insert(0, entry);
    }
    activityEntries.sort((left, right) => right.date.compareTo(left.date));
    await saveActivityEntries();
    notifyListeners();
  }

  // --- Etap 20: backup, import i diagnostyka ---

  static const _backupKey = 'trainer_local_backup_v1';
  static const _backupAtKey = 'trainer_local_backup_at_v1';

  DateTime? lastBackupAt;

  /// Najnowszy moment zmiany danych w aplikacji — przybliżenie „ostatniego
  /// zapisu" bez ingerencji w pojedyncze metody save.
  DateTime? get lastDataActivityAt {
    final candidates = <DateTime>[
      for (final log in logs) log.date,
      for (final measurement in bodyMeasurements) measurement.date,
      for (final impact in trainingImpacts) impact.date,
      for (final snapshot in healthConnectSnapshots) snapshot.checkedAt,
      if (lastBackupAt != null) lastBackupAt!,
    ];
    if (candidates.isEmpty) return null;
    candidates.sort((a, b) => b.compareTo(a));
    return candidates.first;
  }

  /// Usuwa pojedynczą zarejestrowaną aktywność (np. błędny wpis kroków/biegu).
  Future<bool> removeActivityEntry(String id) async {
    final before = activityEntries.length;
    activityEntries.removeWhere((entry) => entry.id == id);
    if (activityEntries.length == before) return false;
    await saveActivityEntries();
    notifyListeners();
    return true;
  }

  /// Zwraca aktywności, które wyglądają na błędne (do ręcznej weryfikacji).
  /// Nic nie usuwa — tylko wykrywa podejrzane wpisy.
  List<TrainerActivityEntry> suspiciousActivityEntries() {
    final result = <TrainerActivityEntry>[];
    for (final entry in activityEntries) {
      final tooManyKcal = entry.estimatedKcal > 3000;
      final negative =
          entry.estimatedKcal < 0 || entry.steps < 0 || entry.distanceKm < 0;
      final absurdSteps = entry.steps > 80000;
      final absurdDistance = entry.distanceKm > 200;
      final stepsWithoutKcal = entry.steps > 5000 && entry.estimatedKcal == 0;
      if (tooManyKcal ||
          negative ||
          absurdSteps ||
          absurdDistance ||
          stepsWithoutKcal) {
        result.add(entry);
      }
    }
    return result;
  }

  /// Tworzy lokalną kopię wszystkich danych Trainera w SharedPreferences.
  Future<DateTime> createLocalBackup() async {
    final prefs = await SharedPreferences.getInstance();
    final now = DateTime.now();
    final payload = {
      'createdAt': now.toIso8601String(),
      'version': 1,
      'data': buildFullExport(this),
    };
    await prefs.setString(_backupKey, jsonEncode(payload));
    await prefs.setString(_backupAtKey, now.toIso8601String());
    lastBackupAt = now;
    notifyListeners();
    return now;
  }

  /// Czy istnieje zapisana lokalna kopia.
  Future<bool> hasLocalBackup() async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_backupKey);
    return raw != null && raw.isNotEmpty;
  }

  /// Przywraca dane z lokalnej kopii. Zwraca false, gdy kopii brak lub jest błędna.
  Future<bool> restoreLocalBackup() async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_backupKey);
    if (raw == null || raw.isEmpty) return false;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return false;
      final data = decoded['data'];
      if (data is! Map) return false;
      return importFullData(Map<String, dynamic>.from(data));
    } catch (_) {
      return false;
    }
  }

  /// Importuje pełen zestaw danych Trainera z mapy JSON (np. z eksportu).
  /// Zwraca true, gdy import się powiódł. Nie usuwa danych przy błędzie.
  Future<bool> importFullData(Map<String, dynamic> data) async {
    try {
      // Parsujemy do tymczasowych list — jeśli coś jest błędne, nie ruszamy stanu.
      List<T> parseList<T>(
          String key, T Function(Map<String, dynamic>) fromJson) {
        final raw = data[key];
        if (raw is! List) return <T>[];
        final out = <T>[];
        for (final item in raw.whereType<Map>()) {
          try {
            out.add(fromJson(Map<String, dynamic>.from(item)));
          } catch (_) {}
        }
        return out;
      }

      final newSettings = data['settings'] is Map
          ? AppSettings.fromJson(
              Map<String, dynamic>.from(data['settings'] as Map))
          : null;
      final newLogs = parseList('logs', WorkoutLog.fromJson);
      final newPlans = parseList('plans', WorkoutPlan.fromJson);
      final newExercises = parseList('customExercises', Exercise.fromJson);
      final newMeasurements =
          parseList('bodyMeasurements', BodyMeasurement.fromJson);
      final newAnalyses =
          parseList('bodyAnalyses', BodyAnalysisResult.fromJson);
      final newImpacts = parseList('trainingImpacts', TrainingImpact.fromJson);
      final newActivities =
          parseList('activityEntries', TrainerActivityEntry.fromJson);
      final newSnapshots = parseList(
          'healthConnectSnapshots', TrainerHealthConnectSnapshot.fromJson);

      // Brak jakichkolwiek danych = nie ma czego importować.
      final hasAnything = newSettings != null ||
          newLogs.isNotEmpty ||
          newPlans.isNotEmpty ||
          newExercises.isNotEmpty ||
          newMeasurements.isNotEmpty;
      if (!hasAnything) return false;

      if (newSettings != null) settings = newSettings;
      logs
        ..clear()
        ..addAll(newLogs);
      if (newPlans.isNotEmpty) {
        plans
          ..clear()
          ..addAll(newPlans);
        if (!plans.any((p) => p.isActive)) {
          plans[0] = plans[0].copyWith(isActive: true);
        }
      }
      customExercises
        ..clear()
        ..addAll(newExercises);
      bodyMeasurements
        ..clear()
        ..addAll(newMeasurements)
        ..sort((a, b) => b.date.compareTo(a.date));
      if (newAnalyses.isNotEmpty) {
        bodyAnalyses
          ..clear()
          ..addAll(newAnalyses)
          ..sort((a, b) => b.date.compareTo(a.date));
      }
      trainingImpacts
        ..clear()
        ..addAll(newImpacts)
        ..sort((a, b) => b.date.compareTo(a.date));
      activityEntries
        ..clear()
        ..addAll(newActivities)
        ..sort((a, b) => b.date.compareTo(a.date));
      healthConnectSnapshots
        ..clear()
        ..addAll(newSnapshots)
        ..sort((a, b) => b.checkedAt.compareTo(a.checkedAt));

      await saveAll();
      notifyListeners();
      return true;
    } catch (_) {
      return false;
    }
  }

  /// Scala dane z mapy JSON (np. pobrane z chmury) z lokalnymi BEZ duplikowania
  /// historii. Listy łączone po `id` — istniejące wpisy zostają nietknięte,
  /// dochodzą tylko brakujące. Ustawienia lokalne NIE są nadpisywane. Zwraca
  /// liczbę dodanych rekordów w rozbiciu na kategorie (do pokazania w UI).
  Future<Map<String, int>> mergeFullData(Map<String, dynamic> data) async {
    final added = <String, int>{};

    int mergeList<T>(
      String key,
      List<T> target,
      T Function(Map<String, dynamic>) fromJson,
      String Function(T) idOf,
    ) {
      final raw = data[key];
      if (raw is! List) return 0;
      final existing = target.map(idOf).where((id) => id.isNotEmpty).toSet();
      var count = 0;
      for (final item in raw.whereType<Map>()) {
        try {
          final parsed = fromJson(Map<String, dynamic>.from(item));
          final id = idOf(parsed);
          if (id.isEmpty || existing.contains(id)) continue;
          target.add(parsed);
          existing.add(id);
          count++;
        } catch (_) {}
      }
      return count;
    }

    added['logs'] = mergeList('logs', logs, WorkoutLog.fromJson, (e) => e.id);
    added['plans'] =
        mergeList('plans', plans, WorkoutPlan.fromJson, (e) => e.id);
    added['customExercises'] = mergeList(
        'customExercises', customExercises, Exercise.fromJson, (e) => e.id);
    added['bodyMeasurements'] = mergeList('bodyMeasurements', bodyMeasurements,
        BodyMeasurement.fromJson, (e) => e.id);
    added['bodyAnalyses'] = mergeList(
        'bodyAnalyses', bodyAnalyses, BodyAnalysisResult.fromJson, (e) => e.id);
    added['trainingImpacts'] = mergeList('trainingImpacts', trainingImpacts,
        TrainingImpact.fromJson, (e) => e.id);
    added['activityEntries'] = mergeList('activityEntries', activityEntries,
        TrainerActivityEntry.fromJson, (e) => e.id);
    added['healthConnectSnapshots'] = mergeList(
        'healthConnectSnapshots',
        healthConnectSnapshots,
        TrainerHealthConnectSnapshot.fromJson,
        (e) => e.id);

    // Utrzymaj spójne porządki (najnowsze pierwsze) jak w innych miejscach.
    logs.sort((a, b) => b.date.compareTo(a.date));
    bodyMeasurements.sort((a, b) => b.date.compareTo(a.date));
    bodyAnalyses.sort((a, b) => b.date.compareTo(a.date));
    trainingImpacts.sort((a, b) => b.date.compareTo(a.date));
    activityEntries.sort((a, b) => b.date.compareTo(a.date));
    healthConnectSnapshots.sort((a, b) => b.checkedAt.compareTo(a.checkedAt));
    if (plans.isNotEmpty && !plans.any((p) => p.isActive)) {
      plans[0] = plans[0].copyWith(isActive: true);
    }

    await saveAll();
    notifyListeners();
    return added;
  }

  TrainerHealthConnectSnapshot? get latestHealthConnectSnapshot {
    if (healthConnectSnapshots.isEmpty) return null;
    final sorted = [...healthConnectSnapshots]
      ..sort((left, right) => right.checkedAt.compareTo(left.checkedAt));
    return sorted.first;
  }

  /// Etap 22: tylko-odczyt — snapshot Health Connect dla wskazanego dnia
  /// (np. wybranego na dashboardzie). Nie liczy nic od nowa.
  TrainerHealthConnectSnapshot? healthConnectSnapshotForDay(DateTime day) {
    TrainerHealthConnectSnapshot? best;
    for (final snapshot in healthConnectSnapshots) {
      if (sameDay(snapshot.date, day)) {
        if (best == null || snapshot.checkedAt.isAfter(best.checkedAt))
          best = snapshot;
      }
    }
    return best;
  }

  /// Etap 22: tylko-odczyt — wpływ treningu (korekta dnia) dla wskazanego dnia.
  TrainingImpact? trainingImpactForDay(DateTime day) {
    for (final impact in trainingImpacts) {
      if (sameDay(impact.date, day)) return impact;
    }
    return null;
  }

  Future<TrainerHealthConnectSnapshot> checkHealthConnectStatus() async {
    return _runHealthConnectAction(
      () => _healthConnectService.checkStatus(date: selectedDate),
    );
  }

  Future<TrainerHealthConnectSnapshot> requestHealthConnectPermissions() async {
    return _runHealthConnectAction(
      () => _healthConnectService.requestPermissions(date: selectedDate),
    );
  }

  Future<TrainerHealthConnectSnapshot> readHealthConnectDailyData() async {
    final snapshot = await _runHealthConnectAction(
      () => _healthConnectService.readDailyData(date: selectedDate),
    );
    // Po odczycie dnia: rozpoznaj biegi / chód / rower z sesji Health Connect
    // i zapisz je jako aktywności z kcal (deduplikacja po uuid rekordu HC).
    // Import obejmuje też 2 dni wstecz — wczorajszy bieg nie może przepaść,
    // jeśli użytkownik otworzył aplikację dopiero dziś.
    for (var offset = 0; offset < 3; offset++) {
      await _importHealthConnectWorkoutSessions(
          selectedDate.subtract(Duration(days: offset)));
    }
    // Uzupełnij snapshot o szacunki, gdy zegarek nie oddał kcal/dystansu do HC.
    await _enrichHealthConnectSnapshotForDay(selectedDate);
    return snapshot;
  }

  /// Zegarki (np. Samsung Health) często NIE oddają do Health Connect
  /// aktywnych kcal ani dystansu poza sesjami — kroki są, reszta to zera.
  /// Ta metoda uzupełnia snapshot bezpiecznym szacunkiem:
  ///  - kcal = kcal sesji (bieg/chód/rower z HC) + zwykłe kroki × masa ciała
  ///    (kroki pokryte sesjami są odjęte — bez podwójnego liczenia),
  ///  - dystans = suma dystansów sesji, a gdy brak — kroki × długość kroku.
  /// Wartości szacowane są oznaczone flagami (UI pokazuje „≈").
  Future<void> _enrichHealthConnectSnapshotForDay(DateTime day) async {
    try {
      final snapshot = healthConnectSnapshotForDay(day);
      if (snapshot == null) return;

      final sessionEntries = activityEntries
          .where((entry) =>
              sameDay(entry.date, day) &&
              entry.source == TrainerActivitySource.healthConnect)
          .toList();
      final sessionsKcal = sessionEntries.fold<int>(
          0, (sum, entry) => sum + math.max(0, entry.estimatedKcal));
      final sessionsDistanceKm = sessionEntries.fold<double>(
          0, (sum, entry) => sum + math.max(0.0, entry.distanceKm));
      final coveredSteps = sessionEntries.fold<int>(
          0, (sum, entry) => sum + math.max(0, entry.steps));
      final weight = settings.bodyWeightKg > 0 ? settings.bodyWeightKg : 100.0;

      var enriched = snapshot;
      var changed = false;

      // Kroki dnia: agregat Health Connect bywa opóźniony względem zegarka.
      // Kroki zarejestrowane w sesjach (bieg 11 km ≈ 11 000+ kroków) są
      // twardym dolnym limitem — dzień nie może mieć mniej kroków niż sesje.
      if (coveredSteps > snapshot.steps) {
        _healthSyncLogAdd(
            'Kroki dnia podniesione do kroków sesji: ${snapshot.steps} → $coveredSteps.');
        enriched = enriched.copyWith(steps: coveredSteps);
        changed = true;
      }
      final effectiveSteps = math.max(0, enriched.steps - coveredSteps);

      // Aktywne kcal: 0 albo absurdalnie mało względem kroków → kcal sesji
      // zarejestrowane przez zegarek + szacunek ze zwykłych kroków.
      final suspiciouslyLow = enriched.activeKcal < enriched.steps * 0.015;
      if (enriched.activeKcal <= 0 || suspiciouslyLow) {
        final estimate = sessionsKcal + effectiveSteps * 0.00045 * weight;
        if (estimate > enriched.activeKcal + 1) {
          _healthSyncLogAdd(
            'Kcal dnia uzupełnione: ${enriched.activeKcal.round()} → ${estimate.round()} '
            '(sesje $sessionsKcal kcal + kroki poza sesjami $effectiveSteps).',
          );
          enriched = enriched.copyWith(
              activeKcal: estimate, activeKcalEstimated: true);
          changed = true;
        }
      }

      // Dystans: sesje, a gdy ich brak — kroki × długość kroku (wzrost × 0.415).
      if (enriched.distanceKm < sessionsDistanceKm) {
        enriched = enriched.copyWith(
            distanceKm: sessionsDistanceKm, distanceEstimated: true);
        changed = true;
      } else if (enriched.distanceKm <= 0) {
        var estimate = sessionsDistanceKm;
        if (estimate <= 0 && enriched.steps > 0) {
          final heightCm = settings.heightCm > 0 ? settings.heightCm : 175.0;
          final strideMeters = heightCm * 0.415 / 100;
          estimate = enriched.steps * strideMeters / 1000;
        }
        if (estimate > 0) {
          enriched =
              enriched.copyWith(distanceKm: estimate, distanceEstimated: true);
          changed = true;
        }
      }

      if (!changed) return;

      // Uzupełnione wartości oznacz jako dostępne w diagnostyce.
      const labels = [
        'Kroki',
        'Dystans',
        'Aktywne kcal',
        'Sesje treningowe',
        'Tętno',
        'Sen'
      ];
      final available = {...enriched.availableData};
      if (enriched.activeKcal > 0) available.add('Aktywne kcal');
      if (enriched.distanceKm > 0) available.add('Dystans');
      enriched = enriched.copyWith(
        availableData: labels.where(available.contains).toList(),
        missingData:
            labels.where((label) => !available.contains(label)).toList(),
      );
      await upsertHealthConnectSnapshot(enriched);
    } catch (_) {
      // Szacowanie nie może wywrócić odczytu Health Connect.
    }
  }

  /// Zamienia sesje treningowe z Health Connect (bieg/chód/rower) na wpisy
  /// [TrainerActivityEntry]. GŁÓWNE ŹRÓDŁO PRAWDY: dane zarejestrowane przez
  /// zegarek / Samsung Health (natywne agregaty okna sesji — kcal, dystans,
  /// kroki, tętno). Własny wzór MET jest używany TYLKO gdy zegarek nie oddał
  /// kcal (wpis oznaczony `kcalFromDevice: false`). Sesje siłowe/inne są
  /// pomijane — treningi siłowe Trainer liczy z własnych zapisów i nie wolno
  /// ich zdublować. Aktualizacja istniejącego wpisu zamiast duplikatu
  /// (stabilny klucz: uuid rekordu Health Connect).
  Future<void> _importHealthConnectWorkoutSessions(DateTime day) async {
    try {
      // Natywny odczyt (kcal/kroki/tętno zegarka); fallback: plugin `health`.
      var sessions = await TrainerRouteService.readExerciseSessions(day);
      var viaNative = true;
      if (sessions.isEmpty) {
        sessions = await _healthConnectService.readWorkoutSessions(date: day);
        viaNative = false;
      }
      if (sessions.isEmpty) return;
      // Trasy GPS sesji (uuid → punkty) — defensywnie, może być pusto.
      final routes = await TrainerRouteService.readExerciseRoutes(day);
      var changed = false;
      for (final session in sessions) {
        TrainerActivityType? type;
        if (session.isRun) {
          type = TrainerActivityType.run;
        } else if (session.isWalk) {
          type = TrainerActivityType.measuredWalk;
        } else if (session.isBike) {
          type = TrainerActivityType.bike;
        }
        if (type == null) continue;
        final minutes = session.durationMin;
        if (minutes < 3 && session.energyKcal <= 0) continue; // wpis-śmieć

        final weight =
            settings.bodyWeightKg > 0 ? settings.bodyWeightKg : 100.0;

        // PRIORYTET KCAL: 1) wartość zarejestrowana przez zegarek/Samsung
        // Health dla okna sesji, 2) dopiero własny fallback MET (oznaczony).
        final deviceKcal = session.energyKcal.round();
        final kcalFromDevice = deviceKcal > 0;
        final met = type == TrainerActivityType.run
            ? 9.8
            : type == TrainerActivityType.bike
                ? 6.8
                : 3.8;
        final estimatedKcal = kcalFromDevice
            ? deviceKcal
            // The resting 1 MET is already present in the Mifflin base, so the
            // fallback credits only net activity above rest.
            : ((met - 1.0) * 3.5 * weight / 200 * minutes).round();

        // Kroki sesji: zarejestrowane przez zegarek; szacunek tylko przy braku.
        // Służą też do odejmowania od kroków dnia — kcal biegu i kcal kroków
        // z tego samego biegu nigdy nie liczą się podwójnie.
        final steps = type == TrainerActivityType.bike
            ? 0
            : session.steps > 0
                ? session.steps
                : session.distanceKm > 0
                    ? (session.distanceKm *
                            (type == TrainerActivityType.run ? 1250 : 1350))
                        .round()
                    : minutes * (type == TrainerActivityType.run ? 160 : 110);

        final entry = TrainerActivityEntry(
          id: 'hc_${session.sourceId}',
          date: DateTime(
              session.start.year, session.start.month, session.start.day),
          source: TrainerActivitySource.healthConnect,
          type: type,
          estimatedKcal: estimatedKcal.clamp(0, 6000).toInt(),
          sourceActivityId: session.sourceId,
          startedAt: session.start,
          endedAt: session.end,
          durationMin: minutes,
          distanceKm: session.distanceKm,
          steps: steps,
          note: session.sourceName.trim().isEmpty
              ? 'Health Connect'
              : session.sourceName.trim(),
          routePoints: routes[session.sourceId] ?? const <List<double>>[],
          avgHeartRate: session.avgHeartRate,
          maxHeartRate: session.maxHeartRate,
          hrZoneMinutes: _hrZoneMinutes(session.hrSamples, minutes),
          sweatLossMl: _estimateSweatLossMl(
            minutes: minutes,
            avgHeartRate: session.avgHeartRate,
            weightKg: weight,
          ),
          kcalFromDevice: kcalFromDevice,
        );
        final index = activityEntries.indexWhere(
          (item) =>
              item.id == entry.id ||
              item.stableActivityKey == entry.stableActivityKey,
        );
        if (index >= 0) {
          activityEntries[index] = entry;
        } else {
          activityEntries.insert(0, entry);
        }
        changed = true;
        _healthSyncLogAdd(
          '${entry.type.label} ${entry.dateKey}: ${entry.estimatedKcal} kcal '
          '${kcalFromDevice ? '(zegarek)' : '(fallback MET)'} · ${entry.steps} kroków · '
          '${entry.distanceKm.toStringAsFixed(2)} km · ${viaNative ? 'natywnie' : 'plugin'}',
        );
      }
      if (changed) {
        activityEntries.sort((left, right) => right.date.compareTo(left.date));
        _recoveryCache = null; // biegi wpływają na mapę regeneracji
        await saveActivityEntries(); // publikuje też pakiet korekty dnia do Kalorii
        notifyListeners();
      }
    } catch (_) {
      // Import sesji nie może wywrócić głównego odczytu Health Connect.
    }
  }

  /// Minuty w strefach pulsu [niska, kontrola wagi, aerobowa, anaerobowa,
  /// maksymalna] z próbek tętna sesji (maks. HR = 220 − wiek).
  List<int> _hrZoneMinutes(List<int> samples, int minutes) {
    if (samples.isEmpty || minutes <= 0) return const <int>[];
    final maxHr =
        (220 - (settings.age > 0 ? settings.age : 30)).clamp(120, 210);
    final perSample = minutes / samples.length;
    final zones = List<double>.filled(5, 0);
    for (final bpm in samples) {
      final fraction = bpm / maxHr;
      final index = fraction < 0.6
          ? 0
          : fraction < 0.7
              ? 1
              : fraction < 0.8
                  ? 2
                  : fraction < 0.9
                      ? 3
                      : 4;
      zones[index] += perSample;
    }
    return zones.map((value) => value.round()).toList();
  }

  /// Szacunkowa utrata wody przez pot (ml). Health Connect nie udostępnia
  /// wartości potu z Samsung Health, więc liczymy: czas × tempo pocenia
  /// (6–18 ml/kg/h zależnie od tętna względem maksymalnego) × masa ciała.
  int _estimateSweatLossMl({
    required int minutes,
    required double avgHeartRate,
    required double weightKg,
  }) {
    if (minutes <= 0) return 0;
    final maxHr =
        (220 - (settings.age > 0 ? settings.age : 30)).clamp(120, 210);
    final fraction =
        avgHeartRate > 0 ? (avgHeartRate / maxHr).clamp(0.4, 1.1) : 0.7;
    final ratePerKgHour = fraction < 0.6
        ? 6.0
        : fraction < 0.75
            ? 10.0
            : fraction < 0.85
                ? 14.0
                : 18.0;
    return (weightKg * ratePerKgHour * minutes / 60)
        .round()
        .clamp(0, 4000)
        .toInt();
  }

  Future<TrainerHealthConnectSnapshot> _runHealthConnectAction(
    Future<TrainerHealthConnectSnapshot> Function() action,
  ) async {
    healthConnectBusy = true;
    notifyListeners();
    try {
      final snapshot = await action();
      await upsertHealthConnectSnapshot(snapshot, notify: false);
      return snapshot;
    } finally {
      healthConnectBusy = false;
      notifyListeners();
    }
  }

  Future<void> upsertHealthConnectSnapshot(
    TrainerHealthConnectSnapshot snapshot, {
    bool notify = true,
  }) async {
    final index = healthConnectSnapshots.indexWhere(
      (item) => item.id == snapshot.id || item.dateKey == snapshot.dateKey,
    );
    if (index >= 0) {
      healthConnectSnapshots[index] = snapshot;
    } else {
      healthConnectSnapshots.insert(0, snapshot);
    }
    healthConnectSnapshots
        .sort((left, right) => right.checkedAt.compareTo(left.checkedAt));
    await saveHealthConnectSnapshots();
    if (notify) notifyListeners();
  }

  List<TrainerActivityEntry> activityInputsForDay(DateTime day) {
    final externalEntries =
        activityEntries.where((entry) => sameDay(entry.date, day)).toList();
    final strengthEntries = trainingImpacts
        .where((impact) => sameDay(impact.date, day))
        .map(TrainerActivityEntry.fromTrainingImpact)
        .toList();
    return [...externalEntries, ...strengthEntries];
  }

  List<ActivityCreditDecision> activityCreditDecisionsForDay(DateTime day) {
    return resolveActivityCredits(activityInputsForDay(day));
  }

  bool isExerciseFavorite(String id) =>
      exerciseLibraryPreferences.isFavorite(id);

  bool isExerciseHidden(String id) => exerciseLibraryPreferences.isHidden(id);

  Future<void> toggleExerciseFavorite(String id) async {
    final favorites =
        Set<String>.from(exerciseLibraryPreferences.favoriteExerciseIds);
    if (!favorites.add(id)) favorites.remove(id);
    exerciseLibraryPreferences = exerciseLibraryPreferences.copyWith(
      favoriteExerciseIds: favorites,
    );
    await saveExerciseLibraryPreferences();
    notifyListeners();
  }

  Future<void> setExerciseHidden(String id, bool hidden) async {
    final hiddenIds =
        Set<String>.from(exerciseLibraryPreferences.hiddenExerciseIds);
    if (hidden) {
      hiddenIds.add(id);
    } else {
      hiddenIds.remove(id);
    }
    exerciseLibraryPreferences = exerciseLibraryPreferences.copyWith(
      hiddenExerciseIds: hiddenIds,
    );
    await saveExerciseLibraryPreferences();
    notifyListeners();
  }

  Future<bool> addExerciseToPlan({
    required String exerciseId,
    required String planId,
    required int weekday,
  }) async {
    final planIndex = plans.indexWhere((plan) => plan.id == planId);
    if (planIndex < 0) return false;
    final plan = plans[planIndex];
    final dayIndex = plan.days.indexWhere((day) => day.weekday == weekday);
    if (dayIndex < 0) return false;
    final day = plan.days[dayIndex];
    if (day.items.any((item) => item.exerciseId == exerciseId)) {
      return false;
    }

    final exercise = ExerciseRepo.byId(exerciseId, customExercises);
    final updatedDay = day.copyWith(
      items: [
        ...day.items,
        PlanItem(
          exerciseId: exercise.id,
          sets: exercise.defaultSets,
          reps: exercise.defaultReps,
          durationSec: exercise.defaultDurationSec,
          note: 'Dodano z bazy ćwiczeń',
          suggestedWeightKg: 0,
          restSeconds: 90,
        ),
      ],
    );
    final updatedDays = [...plan.days];
    updatedDays[dayIndex] = updatedDay;
    plans[planIndex] = plan.copyWith(days: updatedDays);
    await savePlans();
    notifyListeners();
    return true;
  }

  void setSelectedDate(DateTime date) {
    selectedDate = DateTime(date.year, date.month, date.day);
    notifyListeners();
  }

  Future<void> updateSettings(AppSettings next) async {
    settings = next;
    // Leniwa migracja: wybór docelowej sylwetki bez skonfigurowanego profilu
    // celu tworzy profil ze starych pól (jak migracja przy starcie).
    if (bodyGoalProfile == null && next.targetSilhouette.trim().isNotEmpty) {
      bodyGoalProfile = migrateLegacyGoalProfile(
        legacyTrainingMode: next.trainingMode,
        legacyTargetSilhouette: next.targetSilhouette,
        legacyTargetWeightKg: next.targetWeightKg,
      );
      if (goalPhases.isEmpty) {
        goalPhases.add(GoalPhase(
          strategy: bodyGoalProfile!.bodyCompositionStrategy,
          startDate: bodyGoalProfile!.updatedAt,
          startWeightKg: currentBodyWeightKg > 0 ? currentBodyWeightKg : null,
          reason: 'Start historii etapów (wybór sylwetki)',
        ));
      }
      await _saveBodyGoalProfile();
    } else if (bodyGoalProfile != null) {
      // Stare ścieżki (dropdown „Tryb treningu", stary picker sylwetki)
      // aktualizują CENTRALNY profil — nie ma dwóch konkurujących wersji celu.
      var profile = bodyGoalProfile!;
      var profileChanged = false;
      final legacyMode = normalizeTrainingMode(next.trainingMode);
      if (legacyMode !=
          legacyTrainingModeForStrategy(profile.effectiveStrategy)) {
        profile = profile.copyWith(
          bodyCompositionStrategy: strategyFromLegacyTrainingMode(legacyMode),
        );
        profileChanged = true;
      }
      final silhouetteId = next.targetSilhouette.trim();
      if (silhouetteId.isNotEmpty &&
          silhouetteId != profile.desiredPhysique.legacySilhouetteId) {
        final physique = DesiredPhysique.fromLegacySilhouetteId(silhouetteId);
        if (physique != null && physique != profile.desiredPhysique) {
          profile = profile.copyWith(desiredPhysique: physique);
          profileChanged = true;
        }
        // Stara „rekompozycja" jako sylwetka = strategia rekompozycji.
        if (silhouetteId == 'recomposition' &&
            profile.bodyCompositionStrategy !=
                BodyCompositionStrategy.recomposition) {
          profile = profile.copyWith(
            bodyCompositionStrategy: BodyCompositionStrategy.recomposition,
          );
          profileChanged = true;
        }
      }
      if (profileChanged) {
        await updateBodyGoalProfile(
          profile,
          phaseChangeReason: 'Zmiana w profilu treningowym',
        );
        return; // updateBodyGoalProfile zapisał ustawienia i opublikował most
      }
    }
    await saveSettings();
    // Sylwetka/profil zmieniają cele żywieniowe publikowane do Licznika Kalorii.
    await publishDailyAdjustmentsBridge(notify: false);
    notifyListeners();
  }

  Future<void> _saveBodyGoalProfile() async {
    final prefs = await SharedPreferences.getInstance();
    final profile = bodyGoalProfile;
    if (profile != null) {
      await prefs.setString(_bodyGoalProfileKey, jsonEncode(profile.toJson()));
    }
    await prefs.setString(
      _goalPhasesKey,
      jsonEncode([for (final phase in goalPhases) phase.toJson()]),
    );
  }

  /// Aktualizuje centralny profil celu (jedyna ścieżka zmiany celu).
  ///
  /// - podbija rewizję i nadaje nowy `changeId` TYLKO przy realnej zmianie
  ///   treści (ta sama treść nie generuje nowej wersji → most nie wysyła
  ///   wielokrotnie tej samej aktualizacji),
  /// - zmiana STRATEGII zamyka bieżący etap historii i otwiera nowy
  ///   (poprzedni etap nigdy nie jest nadpisywany),
  /// - synchronizuje stare pola ustawień (trainingMode/targetSilhouette/
  ///   targetWeightKg) dla zgodności ze starszymi ścieżkami kodu,
  /// - republikuje most do Kalorii, o ile automatyczna publikacja włączona.
  ///
  /// NIE dotyka planów treningowych ani postępów programów 30-dniowych.
  Future<void> updateBodyGoalProfile(
    UserBodyGoalProfile next, {
    String? phaseChangeReason,
    GoalSource? source,
  }) async {
    final previous = bodyGoalProfile;
    final contentChanged =
        previous == null || previous.signature != next.signature;
    final now = DateTime.now();
    final updated = contentChanged
        ? next.copyWith(
            revision: (previous?.revision ?? 0) + 1,
            changeId: 'goal_${now.microsecondsSinceEpoch}',
            updatedAt: now,
            goalSource: source ?? GoalSource.trainer,
          )
        : next;

    // Historia etapów: zmiana strategii = zamknięcie starego etapu i nowy wpis.
    final strategyChanged = previous != null &&
        previous.bodyCompositionStrategy != updated.bodyCompositionStrategy;
    if (strategyChanged || (previous == null && goalPhases.isEmpty)) {
      final latestAnalysis = latestReliableBodyAnalysis;
      final weight = currentBodyWeightKg;
      double? waist;
      for (final measurement in bodyMeasurements) {
        if (measurement.waistCm > 0) {
          waist = measurement.waistCm;
          break;
        }
      }
      if (goalPhases.isNotEmpty && goalPhases.last.isActive) {
        goalPhases[goalPhases.length - 1] = goalPhases.last.closed(
          endDate: now,
          endWeightKg: weight > 0 ? weight : null,
          endBodyFatPercent: latestAnalysis?.composition.bodyFatPercent,
          endWaistCm: waist,
        );
      }
      goalPhases.add(GoalPhase(
        strategy: updated.bodyCompositionStrategy,
        startDate: now,
        startWeightKg: weight > 0 ? weight : null,
        startBodyFatPercent: latestAnalysis?.composition.bodyFatPercent,
        startWaistCm: waist,
        reason: phaseChangeReason,
      ));
    }

    bodyGoalProfile = updated;

    // Zgodność wsteczna: stare pola podążają za profilem (rekomendacje
    // programów i AI dalej czytają trainingMode/targetSilhouette).
    final legacySilhouette = updated.desiredPhysique.legacySilhouetteId;
    settings = settings.copyWith(
      trainingMode: legacyTrainingModeForStrategy(updated.effectiveStrategy),
      targetSilhouette: legacySilhouette.isNotEmpty
          ? legacySilhouette
          : settings.targetSilhouette,
      targetWeightKg: updated.targetWeightKg ?? settings.targetWeightKg,
    );
    await saveSettings();
    await _saveBodyGoalProfile();
    if (updated.autoPublishToCalories) {
      await publishDailyAdjustmentsBridge(notify: false);
    }
    notifyListeners();
  }

  Future<void> addLog(WorkoutLog log) async {
    logs.insert(0, log);
    await saveLogs();
    notifyListeners();
  }

  Future<void> updateLog(WorkoutLog log) async {
    final i = logs.indexWhere((e) => e.id == log.id);
    if (i >= 0) {
      logs[i] = log;
      await saveLogs();
      notifyListeners();
    }
  }

  Future<void> deleteLog(String id) async {
    logs.removeWhere((e) => e.id == id);
    await saveLogs();
    notifyListeners();
  }

  Future<void> deleteLogsBySession(String sessionId) async {
    logs.removeWhere((log) => log.sessionId == sessionId);
    await saveLogs();
    notifyListeners();
  }

  Future<void> deleteHistoryEntry(String entryKey) async {
    if (entryKey.startsWith('session_')) {
      await deleteLogsBySession(entryKey.substring('session_'.length));
      return;
    }
    if (entryKey.startsWith('log_')) {
      await deleteLog(entryKey.substring('log_'.length));
    }
  }

  Future<void> updateWorkoutLogSet({
    required String logId,
    required String setId,
    required double weightKg,
    required int repetitions,
    required int rpe,
    required String note,
  }) async {
    final logIndex = logs.indexWhere((log) => log.id == logId);
    if (logIndex < 0) return;

    final log = logs[logIndex];
    if (log.workoutSets.isEmpty) {
      logs[logIndex] = log.copyWith(
        weightKg: math.max(0, weightKg).toDouble(),
        reps: math.max(0, repetitions),
        rpe: rpe.clamp(1, 10).toInt(),
        note: note.trim().isEmpty ? log.note : note.trim(),
      );
      await saveLogs();
      notifyListeners();
      return;
    }

    final setIndex = log.workoutSets.indexWhere((set) => set.id == setId);
    if (setIndex < 0) return;
    final updatedSets = [...log.workoutSets];
    updatedSets[setIndex] = updatedSets[setIndex].copyWith(
      weightKg: math.max(0, weightKg).toDouble(),
      repetitions: math.max(0, repetitions),
      rpe: rpe.clamp(1, 10).toInt(),
      note: note.trim(),
      isCompleted: true,
    );
    final completedSets = updatedSets.where((set) => set.isCompleted).toList();
    final aggregateSets = completedSets.isEmpty ? updatedSets : completedSets;
    final averageReps =
        (aggregateSets.fold<int>(0, (sum, set) => sum + set.repetitions) /
                aggregateSets.length)
            .round();
    final averageWeight =
        aggregateSets.fold<double>(0, (sum, set) => sum + set.weightKg) /
            aggregateSets.length;
    final averageRpe =
        (aggregateSets.fold<int>(0, (sum, set) => sum + set.rpe) /
                aggregateSets.length)
            .round();

    logs[logIndex] = log.copyWith(
      workoutSets: updatedSets,
      sets: completedSets.length,
      reps: averageReps,
      weightKg: averageWeight,
      rpe: averageRpe.clamp(1, 10).toInt(),
    );
    await saveLogs();
    notifyListeners();
  }

  Future<bool> startActiveWorkout({
    required WorkoutPlan plan,
    required WorkoutDay day,
    int? dayIndex,
  }) async {
    if (day.items.isEmpty) return false;
    // Wyznacz indeks dnia w programie (Etap 31): jawny → po tożsamości → po dniu+tytule.
    var resolvedDayIndex = dayIndex ?? -1;
    if (resolvedDayIndex < 0) {
      resolvedDayIndex = plan.days.indexWhere((entry) => identical(entry, day));
    }
    if (resolvedDayIndex < 0) {
      resolvedDayIndex = plan.days.indexWhere(
        (entry) => entry.weekday == day.weekday && entry.title == day.title,
      );
    }
    final startedAt = DateTime.now();
    activeWorkoutSession = ActiveWorkoutSession(
      id: 'workout_${idNow()}',
      planId: plan.id,
      planName: plan.name,
      weekday: day.weekday,
      dayTitle: day.title,
      dayIndex: resolvedDayIndex,
      startedAt: startedAt,
      activeSegmentStartedAt: startedAt,
      currentExerciseIndex: 0,
      // Przy starcie liczymy receptę sesji dla KAŻDEGO ćwiczenia (snapshot):
      // analiza historii → rekomendacja → efektywny plan sesji. Bazowy plan
      // zostaje w recepcie i nie jest trwale nadpisywany (spec: punkt 1).
      exercises: day.items.map((item) {
        final def = ExerciseRepo.byId(item.exerciseId, customExercises);
        final entryType = def.entryType;
        final rx = buildSessionPrescription(
          def,
          baseSets: item.sets,
          baseReps: item.reps,
          baseWeightKg: item.suggestedWeightKg,
          baseRestSeconds: item.restSeconds,
          baseDurationSec: item.durationSec,
        );
        final eff = rx.effective;
        return ActiveWorkoutExercise(
          exerciseId: item.exerciseId,
          plannedSets: eff.sets > 0 ? eff.sets : item.sets,
          plannedReps:
              entryType.showsReps && eff.reps > 0 ? eff.reps : item.reps,
          suggestedWeightKg:
              entryType.showsWeight ? eff.weightKg : item.suggestedWeightKg,
          restSeconds: eff.restSeconds > 0 ? eff.restSeconds : item.restSeconds,
          note: item.note,
          prescription: rx,
        );
      }).toList(),
    );
    await saveActiveWorkoutSession();
    notifyListeners();
    return true;
  }

  Future<void> selectActiveWorkoutExercise(int index) async {
    final session = activeWorkoutSession;
    if (session == null || session.exercises.isEmpty) return;
    activeWorkoutSession = session.copyWith(
      currentExerciseIndex: index.clamp(0, session.exercises.length - 1),
    );
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<bool> saveActiveWorkoutSet({
    required double weightKg,
    required int repetitions,
    required int rpe,
    int durationSec = 0,
    double distanceMeters = 0,
    bool isFailure = false,
    String outcome = '',
    double estimatedRpe = 0,
    double exertionConfidence = 0,
    int activeSeconds = 0,
    bool isTimeVerified = true,
    String rpeSource = '',
  }) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return false;
    if (exercise.completedSets.length >= exercise.plannedSets) return false;
    final exercises = [...session.exercises];
    final index = session.currentExerciseIndex;
    // Zgodność wsteczna: gdy nie podano ręcznego RPE, ale mamy szacowane
    // (tryb prowadzenia), zapisujemy zaokrąglone szacowane RPE w polu `rpe`,
    // żeby regeneracja/progresja/średnie RPE działały bez przeróbek.
    final effectiveRpe = rpe > 0
        ? rpe
        : (estimatedRpe > 0 ? estimatedRpe.round().clamp(1, 10) : 0);
    // Źródło RPE: jawne z wywołania → z wyniku serii (estimated) → wpis ręczny
    // (rpe>0 bez outcome) → puste. Domyślne RPE NIE jest dowodem do progresji.
    final resolvedRpeSource = rpeSource.isNotEmpty
        ? rpeSource
        : (estimatedRpe > 0 || outcome.isNotEmpty
            ? 'estimated'
            : (rpe > 0 ? 'user' : ''));
    final updatedExercise = exercise.copyWith(
      completedSets: [
        ...exercise.completedSets,
        WorkoutSet(
          id: 'set_${idNow()}',
          order: exercise.completedSets.length + 1,
          repetitions: repetitions,
          weightKg: weightKg,
          durationSec: math.max(0, durationSec),
          rpe: effectiveRpe,
          isCompleted: true,
          isFailure: isFailure,
          distanceMeters: math.max(0, distanceMeters),
          outcome: outcome,
          estimatedRpe: estimatedRpe,
          exertionConfidence: exertionConfidence,
          activeSeconds: math.max(0, activeSeconds),
          isTimeVerified: isTimeVerified,
          rpeSource: resolvedRpeSource,
        ),
      ],
      isSkipped: false,
    );
    exercises[index] = updatedExercise;
    // Gdy to była ostatnia seria ostatniego (i całego) treningu — bez timera
    // odpoczynku: nie ma następnego ćwiczenia, aplikacja przechodzi wprost
    // do podsumowania (Etap: koniec treningu bez „pustego" odpoczynku).
    if (_allActiveExercisesDone(exercises)) {
      activeWorkoutSession = session.copyWith(
        exercises: exercises,
        restTimerRemainingSeconds: 0,
        restTimerTotalSeconds: 0,
        isRestTimerPaused: false,
        clearRestTimerEndsAt: true,
      );
      await saveActiveWorkoutSession();
      notifyListeners();
      return true;
    }
    final exerciseDefinition = ExerciseRepo.byId(
      updatedExercise.exerciseId,
      customExercises,
    );
    final recommendation = workoutRestRecommendation(
      exerciseDefinition,
      updatedExercise,
    );
    activeWorkoutSession = session.copyWith(
      exercises: exercises,
      restTimerEndsAt:
          DateTime.now().add(Duration(seconds: recommendation.seconds)),
      restTimerRemainingSeconds: recommendation.seconds,
      restTimerTotalSeconds: recommendation.seconds,
      isRestTimerPaused: false,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
    return true;
  }

  // ===== Inteligentny trener: kontekst, historia, rekomendacja, logowanie =====

  /// Kontekst użytkownika dla silnika trenera (poziom, cel/strategia, antropometria).
  CoachContext coachContext() {
    final strategy = settings.trainingMode.trim().isNotEmpty
        ? settings.trainingMode
        : settings.goal;
    final cycle = deloadStatusToday;
    return CoachContext(
      level: settings.level,
      goal: strategy,
      bodyWeightKg: settings.bodyWeightKg,
      heightCm: settings.heightCm,
      age: settings.age,
      sex: settings.sex,
      // Rampa cyklu (mocno po deloadzie, łagodniej pod koniec bloku, nisko
      // w deloadzie) POMNOŻONA przez ręczną korektę programu.
      cycleIntensity: (cycle.isActive ? cycle.intensityFactor : 1.0) *
          intensityStepFactor(activeEffectiveIntensitySteps),
    );
  }

  /// Historia ćwiczenia dla trenera (najstarsze → najnowsze, do 8 sesji).
  List<CoachHistorySample> coachHistoryForExercise(String exerciseId) {
    final history = logs.where((log) => log.exerciseId == exerciseId).toList()
      ..sort((a, b) => a.date.compareTo(b.date));
    final recent =
        history.length > 8 ? history.sublist(history.length - 8) : history;
    return [for (final log in recent) _coachSampleFromLog(log)];
  }

  CoachHistorySample _coachSampleFromLog(WorkoutLog log) {
    final def = ExerciseRepo.byId(log.exerciseId, customExercises);
    final entryType = def.entryType;
    final sets = log.workoutSets;
    final completed = sets.where((s) => s.isCompleted && !s.isFailure).toList();
    double topWeight = log.weightKg;
    int topReps = log.reps;
    for (final s in completed) {
      if (s.weightKg > topWeight) topWeight = s.weightKg;
      if (s.repetitions > topReps) topReps = s.repetitions;
    }
    final anyIncomplete = sets.any((s) =>
        s.isFailure ||
        !s.isCompleted ||
        s.outcome == SetOutcome.notCompleted.key ||
        s.outcome == SetOutcome.interrupted.key);
    // RPE dla trenera: bierzemy je TYLKO gdy mamy realny sygnał — świadomy wpis
    // użytkownika albo wystarczająco pewne oszacowanie. Domyślna „7" (z
    // WorkoutSession.fromJson albo starszych zapisów) NIE udaje pomiaru:
    // sample dostaje estimatedRpe = 0 i rpeReliable = false (spec: punkt 5).
    final reliableSets = completed.where((s) => s.hasReliableRpe).toList();
    final rpeReliable = reliableSets.isNotEmpty;
    final estRpe = rpeReliable
        ? reliableSets.fold<double>(
              0,
              (sum, s) =>
                  sum +
                  (s.estimatedRpe > 0 ? s.estimatedRpe : s.rpe.toDouble()),
            ) /
            reliableSets.length
        : 0.0;

    // Pewność analizy ostatniej sesji — zasila bezpiecznik progresji. Liczymy ją
    // z serii, które ją zapisały (tryb prowadzenia). Gdy żadna nie ma oceny
    // pewności (wpis ręczny / starszy zapis), nie ma powodu do nieufności → 1.0.
    final scoredSets =
        completed.where((s) => s.exertionConfidence > 0).toList();
    final confidence = scoredSets.isEmpty
        ? 1.0
        : scoredSets.fold<double>(0, (sum, s) => sum + s.exertionConfidence) /
            scoredSets.length;

    // Czas serii dla trenera bierzemy WYŁĄCZNIE z realnych serii ćwiczeń
    // czasowych — NIGDY z zagregowanego log.durationSec (to udział czasu sesji
    // podzielony przez liczbę ćwiczeń i bywa sztuczny: to on dawał deski „308 s"
    // i identyczne czasy dla różnych ćwiczeń). Ćwiczenia powtórzeniowe → 0.
    var perSetDuration = 0;
    var timeVerifiedForCoach =
        sets.isEmpty || sets.every((s) => s.isTimeVerified);
    if (entryType.showsDuration && !entryType.showsReps) {
      final base = def.defaultDurationSec > 0 ? def.defaultDurationSec : 45;
      // Najdłuższa WIARYGODNA seria (najlepszy wynik), po walidacji zakresu.
      final durations = <int>[
        for (final s in completed)
          if (s.isTimeVerified && s.activeSeconds > 0)
            s.activeSeconds
          else if (s.durationSec > 0)
            s.durationSec,
      ]..sort();
      for (final d in durations.reversed) {
        if (isPlausibleHistoricalDuration(base, d)) {
          perSetDuration = d;
          break;
        }
      }
      // Bez wiarygodnego czasu z serii — oznacz jako niezweryfikowany, żeby
      // progresja czasu nie ruszała na podstawie podejrzanych danych.
      if (perSetDuration == 0) timeVerifiedForCoach = false;
    }

    return CoachHistorySample(
      date: log.date,
      weightKg: topWeight,
      reps: topReps,
      durationSec: perSetDuration,
      plannedReps: topReps,
      allSetsCompleted: sets.isEmpty ? true : !anyIncomplete,
      estimatedRpe: estRpe,
      timeVerified: timeVerifiedForCoach,
      rpeReliable: rpeReliable,
      confidence: confidence,
    );
  }

  /// Regeneracja (%) najsłabiej zregenerowanej głównej partii ćwiczenia.
  double recoveryPercentForExercise(Exercise exercise) {
    final map = muscleRecoveryMap();
    var worst = 100.0;
    for (final impact in exercise.effectiveMuscleImpacts) {
      if (impact.role != MuscleRole.primary) continue;
      final state = map[impact.muscleGroup];
      final percent = state?.recoveryPercent;
      if (percent != null && percent < worst) worst = percent;
    }
    return worst;
  }

  /// Buduje receptę sesji dla ćwiczenia: bazowy plan + rekomendacja Trainera na
  /// tę sesję (snapshot). Liczona RAZ przy starcie treningu — nie jest losowo
  /// przeliczana w trakcie. Gdy brak/nieprawidłowa historia — rekomendacja
  /// spada do wartości bazowych programu (spec: punkty 1 i 12).
  SessionPrescription buildSessionPrescription(
    Exercise def, {
    required int baseSets,
    required int baseReps,
    required double baseWeightKg,
    required int baseRestSeconds,
    int baseDurationSec = 0,
  }) {
    final entryType = def.entryType;
    // Plan bazowy czasu bierzemy z programu, a dopiero w braku wartości —
    // z domyślnego czasu ćwiczenia.
    final baseDuration = entryType.showsDuration
        ? (baseDurationSec > 0 ? baseDurationSec : def.defaultDurationSec)
        : 0;
    final history = coachHistoryForExercise(def.id);
    final recovery = recoveryPercentForExercise(def);
    final rec = recommendSet(
      exercise: def,
      plannedSets: baseSets,
      plannedReps: baseReps,
      plannedWeightKg: baseWeightKg,
      plannedDurationSec: baseDuration,
      plannedRestSeconds: baseRestSeconds,
      ctx: coachContext(),
      history: history,
      recoveryPercent: recovery,
    );
    // Przerwa bazowa = jawnie ustawiona w programie albo dobrana do typu
    // ćwiczenia. Dzięki temu „zmiana przerwy" w recepcie oznacza wyłącznie
    // korektę regeneracyjną, a nie sam dobór domyślnej wartości.
    final baseRest = baseRestFor(
      def,
      plannedReps: baseReps,
      plannedRestSeconds: baseRestSeconds,
    ).seconds;
    final base = Prescription(
      sets: baseSets < 1 ? 1 : baseSets,
      reps: entryType.showsReps ? baseReps : 0,
      weightKg: entryType.showsWeight ? baseWeightKg : 0,
      durationSec: baseDuration,
      restSeconds: baseRest,
    );
    final recommended = Prescription(
      sets: rec.sets < 1 ? 1 : rec.sets,
      reps: rec.reps,
      weightKg: rec.weightKg,
      durationSec: rec.durationSec,
      restSeconds: rec.restSeconds,
    );
    return SessionPrescription(
      base: base,
      recommended: recommended,
      reason: rec.reasons.join(' '),
      dataSource: rec.isCalibrating
          ? 'calibration'
          : (history.isNotEmpty ? 'history' : 'base'),
      hasEnoughHistory: history.isNotEmpty && !rec.isCalibrating,
      isCalibrating: rec.isCalibrating,
      generatedAtIso: DateTime.now().toIso8601String(),
    );
  }

  /// Rekomendacja parametrów dla bieżącego ćwiczenia aktywnego treningu.
  /// Preferuje receptę sesji (snapshot ze startu treningu) — stabilną w obrębie
  /// całej sesji. Dla starszych/ad-hoc sesji bez recepty liczy na żywo.
  SetRecommendation? recommendationForActiveExercise() {
    final active = activeWorkoutSession?.currentExercise;
    if (active == null) return null;
    final rx = active.prescription;
    if (rx != null) {
      final eff = rx.effective;
      return SetRecommendation(
        sets: eff.sets,
        reps: eff.reps,
        weightKg: eff.weightKg,
        durationSec: eff.durationSec,
        restSeconds: eff.restSeconds,
        reasons: rx.reason.trim().isEmpty ? const [] : [rx.reason.trim()],
        isCalibrating: rx.isCalibrating,
        calibrationNote: rx.isCalibrating ? kCalibrationMessage : '',
      );
    }
    final def = ExerciseRepo.byId(active.exerciseId, customExercises);
    return recommendSet(
      exercise: def,
      plannedSets: active.plannedSets,
      plannedReps: active.plannedReps,
      plannedWeightKg: active.suggestedWeightKg,
      plannedDurationSec: def.defaultDurationSec,
      plannedRestSeconds: active.restSeconds,
      ctx: coachContext(),
      history: coachHistoryForExercise(active.exerciseId),
      recoveryPercent: recoveryPercentForExercise(def),
    );
  }

  /// Zapisuje serię na podstawie prostego wyniku ([SetOutcome]) — bez ręcznego
  /// wpisywania RPE. Trainer sam dobiera parametry (z rekomendacji) i szacuje
  /// wysiłek (ukryte RPE) z pewnością. Zwraca false, gdy brak aktywnej serii.
  Future<bool> logGuidedSet({
    required SetOutcome outcome,
    int activeSeconds = 0,
    bool isTimeVerified = true,
    int? heartRateBpm,
  }) async {
    final active = activeWorkoutSession?.currentExercise;
    final rec = recommendationForActiveExercise();
    if (active == null || rec == null) return false;
    final def = ExerciseRepo.byId(active.exerciseId, customExercises);
    final entryType = def.entryType;
    final firstSetReps = active.completedSets.isEmpty
        ? rec.reps
        : active.completedSets.first.repetitions;

    var reps = rec.reps;
    var duration = rec.durationSec;
    var timeVerified = isTimeVerified;
    switch (outcome) {
      case SetOutcome.asPlanned:
        break;
      case SetOutcome.notCompleted:
        reps = (rec.reps * 0.6).round().clamp(1, rec.reps < 1 ? 1 : rec.reps);
        break;
      case SetOutcome.interrupted:
        reps = (rec.reps * 0.4).round().clamp(1, rec.reps < 1 ? 1 : rec.reps);
        duration = 0; // przerwana — nie ufamy czasowi
        timeVerified = false;
        break;
      case SetOutcome.didDifferently:
        break;
    }

    final exertion = estimateExertion(
      outcome: outcome,
      exercise: def,
      plannedReps: rec.reps,
      actualReps: entryType.showsReps ? reps : 0,
      weightKg: rec.weightKg,
      activeSeconds: activeSeconds,
      timeVerified: timeVerified,
      plannedRestSeconds: active.restSeconds,
      recoveryPercent: recoveryPercentForExercise(def),
      heartRateBpm: heartRateBpm,
      age: settings.age,
      setIndex: active.completedSets.length,
      firstSetReps: firstSetReps,
    );

    return saveActiveWorkoutSet(
      weightKg: entryType.showsWeight ? rec.weightKg : 0,
      repetitions: entryType.showsReps ? reps : 1,
      rpe: 0, // 0 = użyj szacowanego RPE (effectiveRpe)
      durationSec: entryType.showsDuration ? duration : 0,
      isFailure: outcome.marksAsFailure,
      outcome: outcome.key,
      estimatedRpe: exertion.rpe,
      exertionConfidence: exertion.confidence,
      activeSeconds: activeSeconds,
      isTimeVerified: timeVerified,
      rpeSource: 'estimated',
    );
  }

  /// Zapisuje ukończoną serię ćwiczenia CZASOWEGO na podstawie RZECZYWIŚCIE
  /// wykonanego czasu ([performedSec]) z timera — nie sztywnego czasu domyślnego.
  /// Wysiłek (ukryte RPE) jest szacowany, a nie wpisywany na sztywno jako 7.
  Future<bool> logTimedSetCompleted({
    required int performedSec,
    int? heartRateBpm,
  }) async {
    final active = activeWorkoutSession?.currentExercise;
    if (active == null) return false;
    final def = ExerciseRepo.byId(active.exerciseId, customExercises);
    final entryType = def.entryType;
    final safeSeconds = math.max(0, performedSec);
    final exertion = estimateExertion(
      outcome: SetOutcome.asPlanned,
      exercise: def,
      plannedReps: 0,
      actualReps: 0,
      weightKg: 0,
      activeSeconds: safeSeconds,
      timeVerified: true,
      plannedRestSeconds: active.restSeconds,
      recoveryPercent: recoveryPercentForExercise(def),
      heartRateBpm: heartRateBpm,
      age: settings.age,
      setIndex: active.completedSets.length,
    );
    return saveActiveWorkoutSet(
      weightKg: entryType.showsWeight ? active.suggestedWeightKg : 0,
      repetitions: entryType.showsReps ? active.plannedReps : 1,
      rpe: 0,
      durationSec: entryType.showsDuration ? safeSeconds : 0,
      outcome: SetOutcome.asPlanned.key,
      estimatedRpe: exertion.rpe,
      exertionConfidence: exertion.confidence,
      activeSeconds: safeSeconds,
      isTimeVerified: true,
      rpeSource: 'estimated',
    );
  }

  /// Ręczne nadpisanie rekomendowanego czasu serii bieżącego ćwiczenia PRZED
  /// startem (spec: punkt 3). Zapisuje nowy czas w recepcie sesji jako ręczne
  /// nadpisanie; timer i panel od tego momentu używają tej wartości.
  Future<void> setActiveExerciseDuration(int seconds) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return;
    final clamped = seconds.clamp(1, 7200);
    final rx = exercise.prescription;
    final updated = exercise.copyWith(
      prescription: rx?.copyWith(manualDurationSec: clamped),
    );
    final exercises = [...session.exercises];
    exercises[session.currentExerciseIndex] = updated;
    activeWorkoutSession = session.copyWith(exercises: exercises);
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  /// Czy wszystkie ćwiczenia aktywnego treningu są zakończone (wykonane serie
  /// albo pominięte). Używane do pominięcia odpoczynku po ostatniej serii
  /// i automatycznego przejścia do podsumowania.
  bool _allActiveExercisesDone(List<ActiveWorkoutExercise> exercises) {
    if (exercises.isEmpty) return false;
    for (final exercise in exercises) {
      if (exercise.isSkipped) continue;
      if (exercise.completedSets.length < exercise.plannedSets) return false;
    }
    return true;
  }

  /// Czy aktywny trening jest w całości ukończony (wszystkie ćwiczenia wykonane
  /// lub pominięte) i ma co najmniej jedną zapisaną serię — można iść do podsumowania.
  bool get isActiveWorkoutComplete {
    final session = activeWorkoutSession;
    if (session == null) return false;
    if (session.completedSetCount == 0) return false;
    return _allActiveExercisesDone(session.exercises);
  }

  /// Edycja zapisanej serii bieżącego ćwiczenia (indeks w [completedSets]).
  /// Nie uruchamia timera odpoczynku.
  Future<bool> updateActiveWorkoutSet(
    int setIndex, {
    double? weightKg,
    int? repetitions,
    int? rpe,
    int? durationSec,
    double? distanceMeters,
    bool? isFailure,
  }) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return false;
    if (setIndex < 0 || setIndex >= exercise.completedSets.length) return false;
    final sets = [...exercise.completedSets];
    sets[setIndex] = sets[setIndex].copyWith(
      weightKg: weightKg,
      repetitions: repetitions,
      rpe: rpe,
      durationSec: durationSec,
      distanceMeters: distanceMeters,
      isFailure: isFailure,
    );
    final exercises = [...session.exercises];
    exercises[session.currentExerciseIndex] =
        exercise.copyWith(completedSets: sets);
    activeWorkoutSession = session.copyWith(exercises: exercises);
    await saveActiveWorkoutSession();
    notifyListeners();
    return true;
  }

  /// Usuwa zapisaną serię bieżącego ćwiczenia i przenumerowuje kolejność.
  Future<bool> removeActiveWorkoutSet(int setIndex) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return false;
    if (setIndex < 0 || setIndex >= exercise.completedSets.length) return false;
    final sets = [...exercise.completedSets]..removeAt(setIndex);
    for (var i = 0; i < sets.length; i++) {
      sets[i] = sets[i].copyWith(order: i + 1);
    }
    final exercises = [...session.exercises];
    exercises[session.currentExerciseIndex] =
        exercise.copyWith(completedSets: sets);
    activeWorkoutSession = session.copyWith(exercises: exercises);
    await saveActiveWorkoutSession();
    notifyListeners();
    return true;
  }

  /// „Powtórz serię": duplikuje zapisaną serię jako nową. Gdy limit
  /// zaplanowanych serii jest osiągnięty, zwiększa liczbę planowanych serii
  /// (dodatkowa seria ponad plan). Uruchamia normalny odpoczynek po serii,
  /// chyba że trening jest już w całości ukończony.
  Future<bool> duplicateActiveWorkoutSet(int setIndex) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return false;
    if (setIndex < 0 || setIndex >= exercise.completedSets.length) return false;
    final source = exercise.completedSets[setIndex];
    if (exercise.completedSets.length >= exercise.plannedSets) {
      final exercises = [...session.exercises];
      exercises[session.currentExerciseIndex] =
          exercise.copyWith(plannedSets: exercise.completedSets.length + 1);
      activeWorkoutSession = session.copyWith(exercises: exercises);
    }
    return saveActiveWorkoutSet(
      weightKg: source.weightKg,
      repetitions: source.repetitions,
      rpe: source.rpe,
      durationSec: source.durationSec,
      distanceMeters: source.distanceMeters,
    );
  }

  Future<void> pauseActiveRestTimer() async {
    final session = activeWorkoutSession;
    if (session == null || session.isRestTimerPaused) return;
    final remaining = session.restSecondsRemaining();
    activeWorkoutSession = session.copyWith(
      restTimerRemainingSeconds: remaining,
      isRestTimerPaused: true,
      clearRestTimerEndsAt: true,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> resumeActiveRestTimer() async {
    final session = activeWorkoutSession;
    if (session == null || !session.isRestTimerPaused) return;
    final remaining = session.restTimerRemainingSeconds.clamp(0, 3600);
    if (remaining == 0) {
      await skipActiveRestTimer();
      return;
    }
    activeWorkoutSession = session.copyWith(
      restTimerEndsAt: DateTime.now().add(Duration(seconds: remaining)),
      restTimerRemainingSeconds: remaining,
      isRestTimerPaused: false,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> adjustActiveRestTimer(int deltaSeconds) async {
    final session = activeWorkoutSession;
    if (session == null) return;
    final remaining =
        (session.restSecondsRemaining() + deltaSeconds).clamp(0, 3600);
    if (remaining == 0) {
      await skipActiveRestTimer();
      return;
    }
    activeWorkoutSession = session.copyWith(
      restTimerEndsAt: session.isRestTimerPaused
          ? null
          : DateTime.now().add(Duration(seconds: remaining)),
      restTimerRemainingSeconds: remaining,
      restTimerTotalSeconds: math.max(
        remaining,
        session.restTimerTotalSeconds + deltaSeconds,
      ),
      isRestTimerPaused: session.isRestTimerPaused,
      clearRestTimerEndsAt: session.isRestTimerPaused,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> skipActiveRestTimer() async {
    final session = activeWorkoutSession;
    if (session == null) return;
    activeWorkoutSession = session.copyWith(
      restTimerRemainingSeconds: 0,
      restTimerTotalSeconds: 0,
      isRestTimerPaused: false,
      clearRestTimerEndsAt: true,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> updateActiveExerciseNote(String note) async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return;
    final exercises = [...session.exercises];
    exercises[session.currentExerciseIndex] =
        exercise.copyWith(note: note.trim());
    activeWorkoutSession = session.copyWith(exercises: exercises);
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> updateActiveSessionNote(String note) async {
    final session = activeWorkoutSession;
    if (session == null) return;
    activeWorkoutSession = session.copyWith(note: note.trim());
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  Future<void> replaceActiveWorkoutExercise(Exercise replacement) async {
    final session = activeWorkoutSession;
    final current = session?.currentExercise;
    if (session == null || current == null) return;
    final exercises = [...session.exercises];
    final completedSets = current.completedSets;
    final plannedSets = math.max(replacement.defaultSets, completedSets.length);
    final plannedReps = replacement.defaultReps > 0
        ? replacement.defaultReps
        : current.plannedReps;
    // Zamiennik dostaje WŁASNĄ receptę (historia, regeneracja i typ nowego
    // ćwiczenia). Bez tego `copyWith` przeniósłby receptę POPRZEDNIego
    // ćwiczenia — z jego bazą, czasem, przerwą i uzasadnieniem.
    final rx = buildSessionPrescription(
      replacement,
      baseSets: plannedSets,
      baseReps: plannedReps,
      baseWeightKg: completedSets.isEmpty ? 0 : completedSets.last.weightKg,
      baseRestSeconds: kUnsetRestSeconds,
      baseDurationSec: replacement.defaultDurationSec,
    );
    final eff = rx.effective;
    final entryType = replacement.entryType;
    final replacementExercise = ActiveWorkoutExercise(
      exerciseId: replacement.id,
      plannedSets: eff.sets > 0 ? eff.sets : plannedSets,
      plannedReps: entryType.showsReps && eff.reps > 0 ? eff.reps : plannedReps,
      suggestedWeightKg: entryType.showsWeight
          ? eff.weightKg
          : (completedSets.isEmpty ? 0 : completedSets.last.weightKg),
      restSeconds: eff.restSeconds,
      note: current.note,
      completedSets: completedSets,
      isSkipped: false,
      prescription: rx,
    );
    exercises[session.currentExerciseIndex] = replacementExercise;
    activeWorkoutSession = session.copyWith(exercises: exercises);
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  /// Restart bieżącego ćwiczenia w aktywnym treningu („Powtórz ćwiczenie").
  /// Czyści wpisane serie TYLKO tego ćwiczenia (seria wraca na 1/1), zdejmuje
  /// oznaczenie pominięcia i zatrzymuje trwający odpoczynek. Nie dotyka innych
  /// ćwiczeń, kolejki ani historii treningów (serie żyją w sesji do momentu
  /// zakończenia treningu).
  Future<bool> restartCurrentActiveExercise() async {
    final session = activeWorkoutSession;
    final exercise = session?.currentExercise;
    if (session == null || exercise == null) return false;
    final exercises = [...session.exercises];
    exercises[session.currentExerciseIndex] = exercise.copyWith(
      completedSets: const <WorkoutSet>[],
      isSkipped: false,
    );
    activeWorkoutSession = session.copyWith(
      exercises: exercises,
      restTimerRemainingSeconds: 0,
      restTimerTotalSeconds: 0,
      isRestTimerPaused: false,
      clearRestTimerEndsAt: true,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
    return true;
  }

  Future<void> moveToNextActiveExercise({bool skipCurrent = false}) async {
    final session = activeWorkoutSession;
    if (session == null || session.exercises.isEmpty) return;
    final exercises = [...session.exercises];
    if (skipCurrent) {
      final current = exercises[session.currentExerciseIndex];
      exercises[session.currentExerciseIndex] =
          current.copyWith(isSkipped: true);
    }
    final nextIndex = math.min(
      session.currentExerciseIndex + 1,
      session.exercises.length - 1,
    );
    activeWorkoutSession = session.copyWith(
      exercises: exercises,
      currentExerciseIndex: nextIndex,
    );
    await saveActiveWorkoutSession();
    notifyListeners();
    // Kopia w chmurze po każdym ćwiczeniu (throttlowana, gdy zalogowano).
    unawaited(
        trainerAccountService.autoBackupEvent(() => buildFullExport(this)));
  }

  Future<void> discardActiveWorkout() async {
    activeWorkoutSession = null;
    workoutResumePromptPending = false;
    workoutResumeColdStart = false;
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  // ===== Cykl życia treningu: pauza / tło / wznowienie / restart =====

  bool get isWorkoutPaused => activeWorkoutSession?.isPaused ?? false;

  /// Globalna pauza treningu: zatrzymuje aktywny czas ORAZ timer odpoczynku.
  /// Czas pauzy/tła NIE jest liczony jako trening, kcal, intensywność ani RPE.
  Future<void> pauseWorkout({bool byBackground = false}) async {
    final session = activeWorkoutSession;
    if (session == null) return;
    if (session.isPaused) {
      if (byBackground && !session.pausedByBackground) {
        activeWorkoutSession = session.copyWith(pausedByBackground: true);
        await saveActiveWorkoutSession();
        notifyListeners();
      }
      return;
    }
    var next = session.pausedNow(byBackground: byBackground);
    // Timer odpoczynku też stoi w pauzie (nie liczymy przerwy w tle).
    if (next.hasActiveRestTimer && !next.isRestTimerPaused) {
      next = next.copyWith(
        restTimerRemainingSeconds: session.restSecondsRemaining(),
        isRestTimerPaused: true,
        clearRestTimerEndsAt: true,
      );
    }
    activeWorkoutSession = next;
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  /// Wznowienie treningu po pauzie/tle — wraca dokładnie do stanu sprzed pauzy.
  Future<void> resumeWorkout() async {
    final session = activeWorkoutSession;
    workoutResumePromptPending = false;
    workoutResumeColdStart = false;
    if (session == null || !session.isPaused) {
      notifyListeners();
      return;
    }
    activeWorkoutSession = session.resumedNow();
    await saveActiveWorkoutSession();
    notifyListeners();
  }

  /// Aplikacja przeszła do tła — zatrzymaj czas jako niezweryfikowany.
  Future<void> markWorkoutBackgrounded() async {
    if (activeWorkoutSession == null) return;
    await pauseWorkout(byBackground: true);
  }

  /// Powrót z tła: przy dłuższej nieobecności pokazujemy okno wznowienia,
  /// przy krótkim mrugnięciu (powiadomienie) wznawiamy bez pytania.
  Future<void> markWorkoutForegrounded() async {
    final session = activeWorkoutSession;
    if (session == null || !session.isPaused || !session.pausedByBackground) {
      return;
    }
    if (session.currentPauseSeconds() >= 60) {
      workoutResumePromptPending = true;
      workoutResumeColdStart = false;
      notifyListeners();
    } else {
      await resumeWorkout();
    }
  }

  void clearWorkoutResumePrompt() {
    if (!workoutResumePromptPending) return;
    workoutResumePromptPending = false;
    notifyListeners();
  }

  Future<void> _saveWarmupCompletions() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(
      _warmupCompletionsKey,
      jsonEncode(warmupCompletions
          .map((id, at) => MapEntry(id, at.toIso8601String()))),
    );
  }

  /// Czy rozgrzewka [warmupId] została ukończona na tyle niedawno, że bramka
  /// ciężkiego dnia może przepuścić trening (okno [kWarmupFreshness]).
  bool hasFreshWarmup(String warmupId, {DateTime? now}) {
    final completedAt = warmupCompletions[warmupId];
    if (completedAt == null) return false;
    final age = (now ?? DateTime.now()).difference(completedAt);
    return !age.isNegative && age <= kWarmupFreshness;
  }

  Future<CompletedWorkoutSummary?> finishActiveWorkout() =>
      _finishActiveWorkout(partial: false);

  /// Zakończenie treningu jako CZĘŚCIOWY — wykonane serie zostają w historii,
  /// ale dzień programu NIE jest oznaczany jako ukończony (spec: przerwany
  /// program nie liczy się jak ukończony, ale postęp serii zostaje).
  Future<CompletedWorkoutSummary?> finishActiveWorkoutAsPartial() =>
      _finishActiveWorkout(partial: true);

  Future<CompletedWorkoutSummary?> _finishActiveWorkout({
    required bool partial,
  }) async {
    final session = activeWorkoutSession;
    if (session == null || session.completedSetCount == 0) return null;
    final endedAt = DateTime.now();
    final performed = session.exercises
        .where((exercise) => exercise.completedSets.isNotEmpty)
        .toList();
    final sessionName = '${session.planName} · ${session.dayTitle}';
    final completedLogs = <WorkoutLog>[];

    for (var index = 0; index < performed.length; index++) {
      final activeExercise = performed[index];
      final exercise = ExerciseRepo.byId(
        activeExercise.exerciseId,
        customExercises,
      );
      final entryType = exercise.entryType;
      final sets = activeExercise.completedSets;
      // Serie oznaczone jako nieudane zostają w historii (workoutSets), ale
      // nie liczą się do agregatów progresu/regeneracji. Gdy wszystkie serie
      // nieudane — agregaty liczone z całości, żeby nie dzielić przez zero.
      final counted = sets.where((set) => !set.isFailure).toList();
      final statsSets = counted.isEmpty ? sets : counted;
      final averageReps =
          (statsSets.fold<int>(0, (sum, set) => sum + set.repetitions) /
                  statsSets.length)
              .round();
      final averageWeight =
          statsSets.fold<double>(0, (sum, set) => sum + set.weightKg) /
              statsSets.length;
      final averageRpe = (statsSets.fold<int>(0, (sum, set) => sum + set.rpe) /
              statsSets.length)
          .round();
      // Czas ćwiczenia liczymy z JEGO WŁASNYCH serii (praca + przerwy między
      // seriami) — NIE jako czas całej sesji podzielony przez liczbę ćwiczeń
      // (to dawało identyczne, sztuczne wartości i błąd „308 s" u trenera).
      // Ćwiczenia czasowe: realny czas serii. Powtórzeniowe: szacunek z powtórzeń.
      var workSeconds = 0;
      for (final set in statsSets) {
        if (entryType.showsDuration) {
          final perSet = set.isTimeVerified && set.activeSeconds > 0
              ? set.activeSeconds
              : (set.durationSec > 0
                  ? set.durationSec
                  : exercise.defaultDurationSec);
          workSeconds += math.max(0, perSet);
        } else {
          final reps = set.repetitions > 0 ? set.repetitions : averageReps;
          workSeconds += (reps * 3.5).round();
        }
      }
      final restBetween = activeExercise.restSeconds > 0
          ? activeExercise.restSeconds * math.max(0, statsSets.length - 1)
          : 0;
      final assignedDuration = workSeconds + restBetween;
      final minutes = assignedDuration / 60;
      completedLogs.add(
        WorkoutLog(
          id: '${session.id}_${activeExercise.exerciseId}',
          exerciseId: activeExercise.exerciseId,
          date: endedAt,
          sets: counted.isEmpty ? sets.length : counted.length,
          reps: averageReps,
          weightKg: averageWeight,
          durationSec: assignedDuration.round(),
          rpe: averageRpe,
          calories: estimateCalories(
            met: exercise.met,
            weightKg: settings.bodyWeightKg,
            minutes: minutes,
          ),
          note: activeExercise.note,
          aiConfidence: 0,
          workoutSets: sets,
          sessionId: session.id,
          sessionName: sessionName,
          sessionStartedAt: session.startedAt,
          sessionEndedAt: endedAt,
          sessionNote: session.note,
        ),
      );
    }

    logs.removeWhere((log) => log.sessionId == session.id);
    logs.insertAll(0, completedLogs);
    await saveLogs();
    final impact = buildTrainingImpactForCompletedWorkout(
      session: session,
      completedLogs: completedLogs,
      settings: settings,
      endedAt: endedAt,
    );
    await upsertTrainingImpact(impact);
    // Po zakończeniu treningu dociągnij świeże dane zdrowia i wyślij pakiet
    // do Kalorii (w tle, bez blokowania podsumowania).
    unawaited(autoSyncHealthConnect(force: true));

    // Etap 31: oznacz dzień programu jako ukończony (postęp + odblokowanie kolejnego).
    final skippedCount =
        session.exercises.where((exercise) => exercise.isSkipped).length;
    final dayIndex = session.dayIndex;
    var dayLabel = session.dayTitle;
    if (dayIndex >= 0) {
      final planIndex = plans.indexWhere((plan) => plan.id == session.planId);
      if (planIndex >= 0 && dayIndex < plans[planIndex].days.length) {
        dayLabel = 'Dzień ${dayIndex + 1}';
        // Trening częściowy NIE oznacza dnia jako ukończonego — postęp serii
        // zostaje w historii, ale dzień programu można dokończyć później.
        if (!partial) {
          final plan = plans[planIndex];
          if (!plan.completedDays.contains(dayIndex)) {
            plans[planIndex] =
                plan.copyWith(completedDays: {...plan.completedDays, dayIndex});
            await savePlans();
          }
        }
      }
    }

    // Bramka rozgrzewki: PEŁNE ukończenie programu rozgrzewkowego zapisujemy
    // z czasem — ciężki dzień honoruje rozgrzewkę tylko, póki jest świeża
    // (kWarmupFreshness). Trening częściowy = przerwana rozgrzewka, nie liczy się.
    if (!partial && isWarmupWorkoutPlan(session.planId)) {
      warmupCompletions[session.planId] = endedAt;
      await _saveWarmupCompletions();
    }

    // Łączny dystans z serii cardio (bez serii nieudanych).
    var totalDistanceMeters = 0.0;
    for (final exercise in performed) {
      for (final set in exercise.completedSets) {
        if (!set.isFailure && set.distanceMeters > 0)
          totalDistanceMeters += set.distanceMeters;
      }
    }

    final summary = CompletedWorkoutSummary(
      sessionId: session.id,
      name: sessionName,
      startedAt: session.startedAt,
      endedAt: endedAt,
      exerciseCount: session.completedExerciseCount,
      setCount: session.completedSetCount,
      volume: session.volume,
      averageRpe: session.averageRpe,
      trainingImpact: impact,
      planId: session.planId,
      dayIndex: dayIndex,
      dayLabel: dayLabel,
      skippedCount: skippedCount,
      totalDistanceMeters: totalDistanceMeters,
      netActiveSeconds: session.netActiveSeconds(endedAt),
      pauseSeconds: session.totalPauseSeconds(endedAt),
      partCount: session.partCount,
      completionStatus: partial ? 'partial' : 'completed',
    );
    activeWorkoutSession = null;
    workoutResumePromptPending = false;
    workoutResumeColdStart = false;
    await saveActiveWorkoutSession();
    notifyListeners();
    // Kopia w chmurze po zakończeniu treningu — wymuszona (bez throttla).
    unawaited(trainerAccountService.autoBackupEvent(
      () => buildFullExport(this),
      minInterval: Duration.zero,
    ));

    // Log pomocniczy po treningu: ćwiczenia, obciążone partie, wagi i % regeneracji.
    if (kDebugMode) {
      for (final log in completedLogs) {
        final exercise = ExerciseRepo.byId(log.exerciseId, customExercises);
        debugPrint(
            '[Recovery] ${exercise.name} · serie ${log.sets} × ${log.reps}, RPE ${log.rpe}');
        for (final impact in exercise.effectiveMuscleImpacts) {
          debugPrint(
              '   → ${impact.muscleGroup.label} [${impact.role.label}] waga ${impact.effectiveWeight}');
        }
      }
      muscleRecoveryMap().forEach((muscle, state) {
        debugPrint(
            '[Recovery] ${muscle.label}: ${state.recoveryPercent?.toStringAsFixed(0)}% (${state.status.name})');
      });
    }
    return summary;
  }

  /// Etap 31: dopisuje informację zwrotną (ocena / ból) do notatki sesji w historii.
  Future<void> appendWorkoutSessionNote(
      String sessionId, String addition) async {
    final trimmed = addition.trim();
    if (trimmed.isEmpty) return;
    var changed = false;
    for (var index = 0; index < logs.length; index++) {
      final log = logs[index];
      if (log.sessionId != sessionId) continue;
      final existing = log.sessionNote.trim();
      if (existing.contains(trimmed)) continue;
      final combined = existing.isEmpty ? trimmed : '$existing\n$trimmed';
      logs[index] = log.copyWith(sessionNote: combined);
      changed = true;
    }
    if (changed) {
      await saveLogs();
      notifyListeners();
    }
  }

  List<WorkoutLog> logsForDay(DateTime day) {
    final d = DateTime(day.year, day.month, day.day);
    return logs.where((e) => sameDay(e.date, d)).toList();
  }

  List<WorkoutLog> logsBetween(DateTime start, DateTime endInclusive) {
    final a = DateTime(start.year, start.month, start.day);
    final b = DateTime(
        endInclusive.year, endInclusive.month, endInclusive.day, 23, 59, 59);
    return logs
        .where((e) => !e.date.isBefore(a) && !e.date.isAfter(b))
        .toList();
  }

  DayTotals totalsForDay(DateTime day) => DayTotals.from(logsForDay(day));

  // Cache mapy regeneracji — liczenie po całej historii logów jest zbyt drogie,
  // żeby robić je w każdym buildzie / ticku timera. Odświeżany, gdy zmienią się
  // logi, profil użytkownika albo minie minuta.
  Map<BodyMuscle, MuscleRecoveryState>? _recoveryCache;
  String _recoveryCacheKey = '';

  /// Mapa regeneracji partii mięśniowych z historii treningów (Etap regeneracji).
  /// Puste, gdy brak danych — UI pokazuje wtedy wszystkie mięśnie jako szare/unknown.
  Map<BodyMuscle, MuscleRecoveryState> muscleRecoveryMap([DateTime? now]) {
    final reference = now ?? DateTime.now();
    final minuteBucket = reference.millisecondsSinceEpoch ~/ 60000;
    final key = '${logs.length}_${logs.isEmpty ? '' : logs.first.id}_'
        '${customExercises.length}_$minuteBucket'
        '_${activityEntries.length}_${activityEntries.isEmpty ? '' : activityEntries.first.id}'
        '_${settings.bodyWeightKg}_${settings.age}_${settings.sex}_${settings.level}_${settings.trainingWeekdays.length}';
    final cached = _recoveryCache;
    if (cached != null && key == _recoveryCacheKey) return cached;
    final computed =
        RecoveryCalculator(profile: settings.toRecoveryProfile()).compute(
      logs: logs,
      resolveExercise: (id) => ExerciseRepo.byId(id, customExercises),
      activities: activityEntries,
      now: reference,
    );
    _recoveryCache = computed;
    _recoveryCacheKey = key;
    return computed;
  }

  // Cache porady planera tygodnia — liczenie po historii + regeneracji jest
  // zbyt drogie na każdy build. Odświeżany przy zmianie danych albo co 5 minut.
  WeeklyTrainingAdvice? _weeklyAdviceCache;
  String _weeklyAdviceCacheKey = '';

  /// Odcisk planu tygodnia do kluczy cache — zmiana rotacji musi natychmiast
  /// przeliczyć porady, inaczej ekran pokazywałby stary rozkład.
  String _weekPlanCacheKey() {
    final plan = trainingScheduleConfig.weekPlan;
    return [
      for (var weekday = 1; weekday <= 7; weekday++)
        '${plan[weekday]?.primary?.name ?? '-'}'
            '/${plan[weekday]?.secondary?.name ?? '-'}',
    ].join(',');
  }

  /// Inteligentna porada planera tygodnia (Etap: propozycje na „Dzisiaj").
  WeeklyTrainingAdvice weeklyTrainingAdvice([DateTime? now]) {
    final reference = now ?? DateTime.now();
    final bucket = reference.millisecondsSinceEpoch ~/ 300000;
    final key = '${logs.length}_${logs.isEmpty ? '' : logs.first.id}'
        '_${activityEntries.length}_${activityEntries.isEmpty ? '' : activityEntries.first.id}'
        '_${settings.goal}_${settings.level}_${settings.trainingWeekdays.join(',')}'
        '_${_weekPlanCacheKey()}'
        '_${activeWorkoutPlan?.id ?? ''}_${activeWorkoutPlan?.completedDays.length ?? 0}'
        '_${customExercises.length}_$bucket'
        '_${deloadStatusOn(reference).intensityFactor.toStringAsFixed(2)}';
    final cached = _weeklyAdviceCache;
    if (cached != null && key == _weeklyAdviceCacheKey) return cached;
    // Nadchodzące (nieukończone) dni programu — bierzemy program ZGODNY
    // Z ROZKŁADEM na dziś, a nie ostatnio otwarty zestaw.
    final activePlan = planForToday ?? activeWorkoutPlan;
    final upcomingProgramDays = <PlannedProgramDay>[];
    if (activePlan != null) {
      for (var index = 0;
          index < activePlan.days.length && upcomingProgramDays.length < 7;
          index++) {
        if (activePlan.completedDays.contains(index)) continue;
        final day = activePlan.days[index];
        final muscles = <BodyMuscle>{};
        for (final item in day.items) {
          final exercise = ExerciseRepo.byId(item.exerciseId, customExercises);
          for (final impact in exercise.effectiveMuscleImpacts) {
            if (impact.role != MuscleRole.stabilizer)
              muscles.add(impact.muscleGroup);
          }
        }
        upcomingProgramDays.add(PlannedProgramDay(
          dayNumber: index + 1,
          title: day.title,
          muscles: muscles.toList(),
          isRest: day.items.isEmpty,
        ));
      }
    }
    final advice = buildWeeklyTrainingAdvice(
      recovery: muscleRecoveryMap(reference),
      recentLogs:
          logsBetween(reference.subtract(const Duration(days: 7)), reference),
      recentActivities: activityEntries,
      goal: settings.goal,
      level: settings.level,
      trainingWeekdays: settings.trainingWeekdays,
      activeProgramTitle: activePlan?.name ?? '',
      upcomingProgramDays: upcomingProgramDays,
      // Stały rozkład tygodnia — to on wyznacza „dzisiaj" i cały tydzień.
      fixedSchedule: weeklyFocusSchedule(reference),
      exercises: ExerciseRepo.combined(customExercises),
      // Faza cyklu decyduje, czy proponujemy ciężkie boje, czy spokojną pracę.
      intensityFactor: deloadStatusOn(reference).isActive
          ? deloadStatusOn(reference).intensityFactor *
              intensityStepFactor(activeEffectiveIntensitySteps)
          : intensityStepFactor(activeEffectiveIntensitySteps),
      now: reference,
    );
    _weeklyAdviceCache = advice;
    _weeklyAdviceCacheKey = key;
    return advice;
  }

  // === Inteligentny Planer: gotowa propozycja treningu na dziś ===
  // Składa poradę planera tygodnia + rekomendacje trenera + prognozę wysiłku
  // w jeden [PlannedWorkout]. Ciężkie liczenie jest cache'owane (jak porada
  // tygodnia), żeby nie liczyć go w każdym buildzie / ticku timera.
  PlannedWorkout? _plannedWorkoutCache;
  String _plannedWorkoutCacheKey = '';

  /// Gotowa propozycja Planera na dziś (cache). Główne wejście ekranu „Trening".
  PlannedWorkout plannedWorkoutForToday([DateTime? now]) {
    final reference = now ?? DateTime.now();
    final bucket = reference.millisecondsSinceEpoch ~/ 300000;
    final key = '${logs.length}_${logs.isEmpty ? '' : logs.first.id}'
        '_${activityEntries.length}_${activityEntries.isEmpty ? '' : activityEntries.first.id}'
        '_${settings.goal}_${settings.trainingMode}_${settings.level}'
        '_${settings.bodyWeightKg}_${settings.trainingWeekdays.join(',')}'
        '_${_weekPlanCacheKey()}'
        '_${activeWorkoutPlan?.id ?? ''}_${activeWorkoutPlan?.completedDays.length ?? 0}'
        '_${customExercises.length}_$bucket';
    final cached = _plannedWorkoutCache;
    if (cached != null && key == _plannedWorkoutCacheKey) return cached;
    final planned = _composePlannedWorkout(now: reference);
    _plannedWorkoutCache = planned;
    _plannedWorkoutCacheKey = key;
    return planned;
  }

  /// Wariant Planera do symulacji zmian („Symuluj zmianę", limit czasu, sprzęt)
  /// — liczony na żądanie, bez cache (nie zapisuje niczego w danych).
  PlannedWorkout simulatePlannedWorkout({
    DateTime? now,
    double timeCapMinutes = 0,
    String equipmentMode = '',
  }) =>
      _composePlannedWorkout(
        now: now ?? DateTime.now(),
        timeCapMinutes: timeCapMinutes,
        equipmentMode: equipmentMode,
      );

  PlannedWorkout _composePlannedWorkout({
    required DateTime now,
    double timeCapMinutes = 0,
    String equipmentMode = '',
  }) {
    final advice = weeklyTrainingAdvice(now);
    final ctx = coachContext();

    PlannerExerciseInput inputFor(
      Exercise def, {
      int? plannedSets,
      int? plannedReps,
      double? plannedWeight,
      int? plannedRest,
    }) {
      final history = coachHistoryForExercise(def.id);
      final readiness = recoveryPercentForExercise(def);
      final rec = recommendSet(
        exercise: def,
        plannedSets: plannedSets ?? def.defaultSets,
        plannedReps: plannedReps ?? def.defaultReps,
        plannedWeightKg: plannedWeight ?? 0,
        plannedDurationSec: def.defaultDurationSec,
        plannedRestSeconds: plannedRest ?? 90,
        ctx: ctx,
        history: history,
        recoveryPercent: readiness,
      );
      double? delta;
      if (history.isNotEmpty) {
        final last = history.last.weightKg;
        if (last > 0 && rec.weightKg > 0) delta = rec.weightKg - last;
      }
      return PlannerExerciseInput(
        exercise: def,
        recommendation: rec,
        readinessPercent: readiness,
        weightDeltaKg: delta,
      );
    }

    // Kontekst dnia programu 30-dniowego (kolejny nieukończony dzień).
    //
    // Program bierzemy TYLKO wtedy, gdy pasuje do partii z rozkładu na dziś.
    // Inaczej dzień nóg zamieniał się w to, co użytkownik ostatnio otworzył.
    PlannerProgramContext? program;
    final scheduledToday = todayScheduled;
    final WorkoutPlan? plan;
    if (scheduledToday == null) {
      plan = activeWorkoutPlan; // rozkład jeszcze nieustawiony
    } else if (scheduledToday.isRest) {
      plan = null;
    } else {
      plan = scheduledPlanForArea(scheduledToday.area);
    }
    if (plan != null && !plan.isProgramCompleted && plan.days.isNotEmpty) {
      final index = plan.currentDayIndex.clamp(0, plan.days.length - 1);
      // Planer liczy z dnia PO korektach (ręczna intensywność + deload) —
      // inaczej prognoza (czas, kcal, woda, makro) rozjeżdża się z treningiem.
      final day = presentedDay(plan, plan.days[index], now);
      final isRest = plan.isRestDay(day);
      final items = <PlannerExerciseInput>[];
      if (!isRest) {
        for (final item in day.items) {
          final def = ExerciseRepo.byId(item.exerciseId, customExercises);
          if (!_plannerEquipmentAllows(equipmentMode, def.equipment)) continue;
          items.add(inputFor(
            def,
            plannedSets: item.sets,
            plannedReps: item.reps,
            plannedWeight: item.suggestedWeightKg,
            plannedRest: item.restSeconds,
          ));
        }
      }
      // Dodatek dnia z toru DRUGORZĘDNEGO doklejamy na koniec zestawu. Dzień
      // „Klatka + Barki" ma realnie zawierać barki także wtedy, gdy klatkę
      // realizuje gotowy program partii — inaczej druga kolumna rozkładu była
      // tylko etykietą.
      final extra = scheduledToday?.secondaryArea;
      if (!isRest && extra != null && extra.muscles.isNotEmpty) {
        final used = {for (final item in day.items) item.exerciseId};
        var added = 0;
        for (final suggestion in advice.todayExercises) {
          if (added >= 2) break;
          if (!used.add(suggestion.exerciseId)) continue;
          final def = ExerciseRepo.byId(suggestion.exerciseId, customExercises);
          final hitsExtra = def.effectiveMuscleImpacts.any((impact) =>
              impact.role == MuscleRole.primary &&
              extra.muscles.contains(impact.muscleGroup));
          if (!hitsExtra) continue;
          if (!_plannerEquipmentAllows(equipmentMode, def.equipment)) continue;
          items.add(inputFor(def));
          added++;
        }
      }
      program = PlannerProgramContext(
        programId: plan.id,
        planName: plan.name,
        dayIndex: index,
        dayNumber: index + 1,
        totalDays: plan.days.length,
        dayTitle: extra == null || isRest
            ? day.title
            : '${day.title} + ${extra.label}',
        isRest: isRest,
        exercises: items,
      );
    }

    // Zestaw dynamiczny z propozycji planera na dziś (gdy brak dnia programu).
    final dynamicInputs = <PlannerExerciseInput>[];
    for (final suggestion in advice.todayExercises) {
      final def = ExerciseRepo.byId(suggestion.exerciseId, customExercises);
      if (!_plannerEquipmentAllows(equipmentMode, def.equipment)) continue;
      dynamicInputs.add(inputFor(def));
    }

    return buildPlannedWorkout(
      advice: advice,
      program: program,
      dynamicExercises: dynamicInputs,
      signals: _plannerSignals(now),
      bodyWeightKg: settings.bodyWeightKg,
      goal: settings.trainingMode.trim().isNotEmpty
          ? settings.trainingMode
          : settings.goal,
      timeCapMinutes: timeCapMinutes,
    );
  }

  /// Sygnały zmęczenia/obciążenia (przeciążenie + deload) liczone z historii.
  PlannerSignals _plannerSignals(DateTime now) {
    final recovery = muscleRecoveryMap(now);
    final last7 = logsBetween(now.subtract(const Duration(days: 6)), now);

    // Średnie (jawne/szacowane) RPE ostatniej doby.
    final dayAgo = now.subtract(const Duration(hours: 26));
    var rpeSum = 0.0;
    var rpeCount = 0;
    for (final log in logs) {
      if (log.date.isBefore(dayAgo)) continue;
      if (log.rpe > 0) {
        rpeSum += log.rpe.clamp(1, 10);
        rpeCount++;
      }
    }
    final avgRpe = rpeCount == 0 ? 0.0 : rpeSum / rpeCount;

    var volume = 0.0;
    for (final log in last7) {
      if (log.volume.isFinite && log.volume > 0) volume += log.volume;
    }

    final tired = recovery.values
        .where((s) => s.hasData && (s.recoveryPercent ?? 100) < 60)
        .length;

    String dateKey(DateTime d) => '${d.year}-${d.month}-${d.day}';

    // Ciężkie dni (średnie RPE dnia ≥ 8) w ostatnim tygodniu.
    final rpeByDate = <String, List<int>>{};
    for (final log in last7) {
      if (log.rpe > 0) (rpeByDate[dateKey(log.date)] ??= []).add(log.rpe);
    }
    var hardDays = 0;
    rpeByDate.forEach((_, rpes) {
      final avg = rpes.reduce((a, b) => a + b) / rpes.length;
      if (avg >= 8) hardDays++;
    });

    // Sesje siłowe ostatniego tygodnia.
    final sessions =
        last7.map((log) => log.sessionId).where((id) => id.isNotEmpty).toSet();

    // Seria nieukończonych sesji (najświeższe sesje z rzędu z nieudaną serią).
    final recent30 = logsBetween(now.subtract(const Duration(days: 30)), now);
    final sessionLatest = <String, DateTime>{};
    final sessionIncomplete = <String, bool>{};
    for (final log in recent30) {
      final id = log.sessionId.isEmpty ? log.id : log.sessionId;
      final at = sessionLatest[id];
      if (at == null || log.date.isAfter(at)) sessionLatest[id] = log.date;
      final bad = log.workoutSets.any((set) =>
          set.isFailure ||
          set.outcome == SetOutcome.notCompleted.key ||
          set.outcome == SetOutcome.interrupted.key);
      sessionIncomplete[id] = (sessionIncomplete[id] ?? false) || bad;
    }
    final orderedSessions = sessionLatest.keys.toList()
      ..sort((a, b) => sessionLatest[b]!.compareTo(sessionLatest[a]!));
    var incompleteStreak = 0;
    for (final id in orderedSessions) {
      if (sessionIncomplete[id] == true) {
        incompleteStreak++;
      } else {
        break;
      }
    }

    // Kolejne dni treningowe pod rząd + czy był lżejszy/wolny dzień w ostatnich 5.
    final trainedDates = <String>{for (final log in logs) dateKey(log.date)};
    var consecutive = 0;
    var cursor = DateTime(now.year, now.month, now.day);
    if (!trainedDates.contains(dateKey(cursor))) {
      cursor = cursor.subtract(const Duration(days: 1));
    }
    while (trainedDates.contains(dateKey(cursor))) {
      consecutive++;
      cursor = cursor.subtract(const Duration(days: 1));
    }
    var trainedLast5 = 0;
    for (var i = 0; i < 5; i++) {
      final d =
          DateTime(now.year, now.month, now.day).subtract(Duration(days: i));
      if (trainedDates.contains(dateKey(d))) trainedLast5++;
    }
    final hasLightDayLast5 = trainedLast5 < 5;

    // Biegi w ostatnich 48 h (nogi obciążone).
    final twoDaysAgo = now.subtract(const Duration(hours: 48));
    final runs = activityEntries
        .where((entry) =>
            !entry.date.isBefore(twoDaysAgo) &&
            entry.type == TrainerActivityType.run)
        .length;

    final health = healthConnectSnapshotForDay(now);

    return PlannerSignals(
      avgRecentRpe: avgRpe,
      weeklyVolumeKg: volume,
      tiredMuscleCount: tired,
      hardDaysLast7: hardDays,
      incompleteSetStreak: incompleteStreak,
      consecutiveTrainingDays: consecutive,
      recentRunCount: runs,
      strengthSessionsLast7: sessions.length,
      hasLightDayLast5: hasLightDayLast5,
      hasHealthConnectData: health?.hasAnyDailyData ?? false,
      hasRecoveryData: recovery.values.any((s) => s.hasData),
      hasHistory: logs.isNotEmpty,
    );
  }

  /// Filtr sprzętu dla symulacji „Nie mam dziś sprzętu" — proste dopasowanie
  /// słów kluczowych do pola [Exercise.equipment]. Pusty tryb = bez filtra.
  bool _plannerEquipmentAllows(String mode, String equipment) {
    if (mode.isEmpty || mode == 'full_gym') return true;
    final e = equipment.toLowerCase();
    bool has(List<String> tokens) => tokens.any(e.contains);
    const bodyweight = [
      'masa ciała',
      'masa wlasnego',
      'mata',
      'poręcz',
      'porecz'
    ];
    switch (mode) {
      case 'bodyweight':
        return has([...bodyweight, 'skakank', 'drążek', 'drazek']);
      case 'dumbbells':
        return has([
          ...bodyweight,
          'hantel',
          'hantle',
          'kettlebell',
          'guma',
          'skakank',
          'drążek',
          'drazek'
        ]);
      case 'barbell_dumbbells':
        return has([
          ...bodyweight,
          'hantel',
          'hantle',
          'kettlebell',
          'sztang',
          'guma',
          'ławk',
          'lawk',
          'skakank',
          'drążek',
          'drazek'
        ]);
      case 'outdoor':
        return has([
          ...bodyweight,
          'buty do biegania',
          'skakank',
          'drążek',
          'drazek',
          'rower'
        ]);
      default:
        return true;
    }
  }

  /// Kontekst danych aplikacji dla asystenta AI — streszczenie zamiast całej bazy.
  Map<String, dynamic> buildAiContext([DateTime? now]) {
    final reference = now ?? DateTime.now();
    return buildTrainerAiContext(
      now: reference,
      profile: settings.toAiProfile(),
      logs: logs,
      resolveExercise: (id) => ExerciseRepo.byId(id, customExercises),
      recovery: muscleRecoveryMap(reference),
      activities: activityEntries,
      plans: plans,
      healthToday: healthConnectSnapshotForDay(reference),
      adjustmentToday: dailyAdjustmentForDay(reference),
      weeklyAdvice: weeklyTrainingAdvice(reference),
    );
  }

  /// Suma dzisiaj spalonych kcal z treningów (Trainer), bez dublowania —
  /// korzysta z [trainingImpacts] z kluczem deduplikacji.
  int burnedKcalForDay(DateTime day) {
    var total = 0;
    for (final impact in trainingImpacts) {
      if (sameDay(impact.date, day)) total += impact.estimatedBurnedKcal;
    }
    return total;
  }

  /// Łączny czas treningów danego dnia (minuty), z zapisanych wpływów.
  int trainingMinutesForDay(DateTime day) {
    var total = 0;
    for (final impact in trainingImpacts) {
      if (sameDay(impact.date, day)) total += impact.durationMin;
    }
    return total;
  }

  Future<Map<String, dynamic>> analyzeWorkoutText(String text) async {
    aiBusy = true;
    lastAiMessage = null;
    notifyListeners();
    try {
      final api = AiBackendService(settings.backendUrl);
      final result = await api.analyzeWorkout({
        'description': text,
        'user': settings.toAiProfile(),
        'date': selectedDate.toIso8601String(),
      });
      lastAiMessage = prettyJson(result);
      return result;
    } catch (e) {
      lastAiMessage = 'Błąd AI: $e';
      rethrow;
    } finally {
      aiBusy = false;
      notifyListeners();
    }
  }

  Future<Map<String, dynamic>> generateAiPlan(
      {required String goal,
      required int days,
      required String equipment,
      required String limitations}) async {
    aiBusy = true;
    lastAiMessage = null;
    notifyListeners();
    try {
      final api = AiBackendService(settings.backendUrl);
      final result = await api.generatePlan({
        'goal': goal,
        'days_per_week': days,
        'equipment': equipment,
        'limitations': limitations,
        'level': settings.level,
        'training_mode': settings.trainingMode,
        'user': settings.toAiProfile(),
      });
      lastAiMessage = prettyJson(result);
      final plan = WorkoutPlanFactory.fromAi(
        json: result,
        goal: goal,
        exercises: ExerciseRepo.combined(customExercises),
        fallback: () => createLocalWorkoutPlan(settings),
      );
      plans
        ..clear()
        ..add(plan);
      await savePlans();
      return result;
    } catch (e) {
      lastAiMessage = 'Błąd AI: $e';
      rethrow;
    } finally {
      aiBusy = false;
      notifyListeners();
    }
  }

  WorkoutAiAnalysis? workoutAiAnalysisFor(String sessionId) =>
      _workoutAiAnalyses[sessionId];

  Future<void> _saveWorkoutAiAnalyses() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(
      _workoutAiAnalysesKey,
      jsonEncode(_workoutAiAnalyses.map((k, v) => MapEntry(k, v.toJson()))),
    );
  }

  /// Buduje czytelny opis treningu (PL) z danych sesji — do pola `description`
  /// wymaganego przez backend analizy AI oraz jako sensowny prompt kontekstu.
  String buildWorkoutDescription(
    CompletedWorkoutSummary summary,
    List<WorkoutLog> sessionLogs,
  ) {
    final buffer = StringBuffer()
      ..writeln('Trening: ${summary.name}.')
      ..writeln(
          'Czas ${summary.duration.inMinutes} min, ćwiczeń: ${summary.exerciseCount}, '
          'serii: ${summary.setCount}, objętość: ${summary.volume.round()} kg'
          '${summary.averageRpe > 0 ? ', średnie RPE ${summary.averageRpe.toStringAsFixed(1)}' : ''}.');
    if (sessionLogs.isNotEmpty) {
      buffer.writeln('Ćwiczenia:');
      for (final l in sessionLogs) {
        final def = ExerciseRepo.byId(l.exerciseId, customExercises);
        final parts = <String>['${l.sets} serie'];
        if (def.entryType.showsReps && l.reps > 0) parts.add('${l.reps} powt.');
        if (def.entryType.showsWeight && l.weightKg > 0) {
          parts.add('${_formatPlanWeight(l.weightKg)} kg');
        }
        if (def.entryType.showsDuration && l.durationSec > 0) {
          parts.add('${l.durationSec} s');
        }
        buffer.writeln('- ${def.name}: ${parts.join(' × ')}');
      }
    }
    return buffer.toString().trim();
  }

  Future<WorkoutAiAnalysis> analyzeCompletedWorkout(
      CompletedWorkoutSummary summary) async {
    aiBusy = true;
    notifyListeners();
    try {
      final sessionLogs =
          logs.where((l) => l.sessionId == summary.sessionId).toList();
      final exerciseDetails = sessionLogs.map((l) {
        final def = ExerciseRepo.byId(l.exerciseId, customExercises);
        return {
          'exercise_id': l.exerciseId,
          'name': def.name,
          'type': def.entryType.key,
          'sets': l.sets,
          'reps': l.reps,
          'weight_kg': l.weightKg,
          'rpe': l.rpe,
          'duration_sec': l.durationSec,
          'calories': l.calories,
        };
      }).toList();

      // Poprzednie treningi z ostatnich 7 dni jako kontekst historyczny
      final recentHistory = logsBetween(
        summary.startedAt.subtract(const Duration(days: 7)),
        summary.startedAt.subtract(const Duration(seconds: 1)),
      );
      final recentByDate = <String, List<WorkoutLog>>{};
      for (final l in recentHistory) {
        final k = l.date.toIso8601String().substring(0, 10);
        recentByDate.putIfAbsent(k, () => []).add(l);
      }

      // Backend wymaga pola `description`. Budujemy zwięzły, sensowny opis
      // treningu z danych sesji (spec: punkt 10) — bez tego request zwracał 422.
      final description = buildWorkoutDescription(summary, sessionLogs);

      final api = AiBackendService(settings.backendUrl);
      final result = await api.analyzeWorkout({
        'description': description,
        'session': {
          'id': summary.sessionId,
          'name': summary.name,
          'started_at': summary.startedAt.toIso8601String(),
          'ended_at': summary.endedAt.toIso8601String(),
          'duration_minutes': summary.duration.inMinutes,
          'exercise_count': summary.exerciseCount,
          'set_count': summary.setCount,
          'volume_kg': summary.volume,
          'average_rpe': summary.averageRpe,
        },
        'exercises': exerciseDetails,
        'recent_history': recentByDate.entries
            .map((e) => {
                  'date': e.key,
                  'exercises': e.value
                      .map((l) => {
                            'id': l.exerciseId,
                            'sets': l.sets,
                            'reps': l.reps,
                            'weight_kg': l.weightKg
                          })
                      .toList(),
                })
            .toList(),
        'user': settings.toAiProfile(),
      });

      // Backend przy wewnętrznym błędzie zwraca payload z polem `error` (HTTP 200)
      // — traktujemy to jak niepowodzenie analizy, ale bez pokazywania surowego
      // wyjątku użytkownikowi (szczegóły tylko do logów). Spec: punkty 10, 13.
      final backendError = result['error']?.toString().trim() ?? '';
      if (backendError.isNotEmpty) {
        if (kDebugMode) {
          debugPrint('[AI] Analiza treningu — błąd backendu: $backendError');
        }
        throw WorkoutAnalysisException();
      }

      final analysis =
          WorkoutAiAnalysis.fromApiResult(summary.sessionId, result);
      _workoutAiAnalyses[summary.sessionId] = analysis;
      await _saveWorkoutAiAnalyses();
      notifyListeners();
      return analysis;
    } finally {
      aiBusy = false;
      notifyListeners();
    }
  }

  Future<void> saveAiChatHistory() async {
    final prefs = await SharedPreferences.getInstance();
    // Trzymaj max 100 ostatnich wiadomości
    final toSave = aiChatHistory.length > 100
        ? aiChatHistory.sublist(aiChatHistory.length - 100)
        : aiChatHistory;
    await prefs.setString(
        _aiChatKey, jsonEncode(toSave.map((m) => m.toJson()).toList()));
  }

  Future<void> clearAiChatHistory() async {
    aiChatHistory.clear();
    await saveAiChatHistory();
    notifyListeners();
  }

  Future<void> chatWithAi(String userMessage) async {
    if (userMessage.trim().isEmpty) return;
    aiChatHistory.add(AiChatMessage(
        role: 'user', content: userMessage.trim(), timestamp: DateTime.now()));
    aiChatBusy = true;
    notifyListeners();
    try {
      final api = AiBackendService(settings.backendUrl);
      final activePlan = activeWorkoutPlan;
      // Pełny, uporządkowany kontekst danych aplikacji (Etap: rozbudowa AI):
      // profil, dzisiejsza aktywność + Health Connect, ostatnie 7 dni treningów,
      // mapa regeneracji, planer tygodnia, status mostu do Kalorii.
      final context = buildAiContext();
      final result = await api.chat({
        'message': userMessage.trim(),
        'user': settings.toAiProfile(),
        'context': context,
        'instructions': 'Odpowiadaj po polsku na podstawie danych z pola "context" '
            '(regeneracja mięśni, treningi, RPE, objętość, aktywność, Health Connect, '
            'korekta kcal/wody dla Licznika Kalorii, planer tygodnia). '
            'Jeżeli danych brakuje, powiedz wprost, jakich danych brakuje, zamiast zgadywać.',
        'active_plan': activePlan == null
            ? null
            : {
                'name': activePlan.name,
                'days': activePlan.days
                    .map((d) => {
                          'title': d.title,
                          'weekday': d.weekday,
                          'exercises': d.items.length
                        })
                    .toList(),
              },
        'history': aiChatHistory.length > 1
            ? aiChatHistory
                .sublist(math.max(0, aiChatHistory.length - 11),
                    aiChatHistory.length - 1)
                .map((m) => {'role': m.role, 'content': m.content})
                .toList()
            : [],
      });
      final reply = (result['reply'] ??
              result['message'] ??
              result['content'] ??
              result['response'] ??
              result['answer'] ??
              prettyJson(result))
          .toString()
          .trim();
      aiChatHistory.add(AiChatMessage(
          role: 'assistant', content: reply, timestamp: DateTime.now()));
    } catch (e) {
      // Backend niedostępny → spróbuj odpowiedzieć lokalnie na podstawie
      // realnych danych aplikacji (regeneracja, planer, kcal, kroki).
      final now = DateTime.now();
      final local = localTrainerAnswer(
        question: userMessage,
        recovery: muscleRecoveryMap(now),
        advice: weeklyTrainingAdvice(now),
        adjustmentToday: dailyAdjustmentForDay(now),
        healthToday: healthConnectSnapshotForDay(now),
      );
      if (local != null) {
        aiChatHistory.add(AiChatMessage(
          role: 'assistant',
          content:
              '$local\n\n(Odpowiedź lokalna na podstawie danych aplikacji — backend AI był niedostępny.)',
          timestamp: DateTime.now(),
        ));
      } else {
        aiChatHistory.add(AiChatMessage(
            role: 'error',
            content: friendlyAiErrorMessage(e),
            timestamp: DateTime.now()));
      }
    } finally {
      aiChatBusy = false;
      notifyListeners();
      await saveAiChatHistory();
    }
  }

  Future<void> generateLocalPlan() async {
    plans
      ..clear()
      ..add(createLocalWorkoutPlan(settings));
    await savePlans();
    notifyListeners();
  }
}

bool sameDay(DateTime a, DateTime b) =>
    a.year == b.year && a.month == b.month && a.day == b.day;

String idNow() => DateTime.now().microsecondsSinceEpoch.toString();

// --- Etap 18: Sugestie progresji (lokalna logika) ---

enum ProgressionAction {
  increaseWeight,
  increaseReps,
  maintain,
  decreaseWeight,
  deload,
}

class ProgressionSuggestion {
  const ProgressionSuggestion({
    required this.action,
    required this.reason,
    required this.suggestedWeightKg,
    required this.suggestedReps,
    required this.currentWeightKg,
    required this.currentReps,
    this.labelOverride = '',
    this.iconOverride,
  });

  final ProgressionAction action;
  final String reason;
  final double suggestedWeightKg;
  final int suggestedReps;
  final double currentWeightKg;
  final int currentReps;

  /// Etykieta zależna od typu ćwiczenia (np. „Dodaj 5 s", „Trudniejszy wariant",
  /// „Utrzymaj czas"). Gdy pusta — używana jest domyślna [label] wg [action].
  final String labelOverride;
  final IconData? iconOverride;

  String get label {
    if (labelOverride.isNotEmpty) return labelOverride;
    switch (action) {
      case ProgressionAction.increaseWeight:
        return 'Zwiększ ciężar';
      case ProgressionAction.increaseReps:
        return 'Zwiększ powtórzenia';
      case ProgressionAction.maintain:
        return 'Utrzymaj';
      case ProgressionAction.decreaseWeight:
        return 'Zmniejsz ciężar';
      case ProgressionAction.deload:
        return 'Zrób deload';
    }
  }

  IconData get icon {
    if (iconOverride != null) return iconOverride!;
    switch (action) {
      case ProgressionAction.increaseWeight:
        return Icons.trending_up_rounded;
      case ProgressionAction.increaseReps:
        return Icons.add_circle_outline_rounded;
      case ProgressionAction.maintain:
        return Icons.remove_rounded;
      case ProgressionAction.decreaseWeight:
        return Icons.trending_down_rounded;
      case ProgressionAction.deload:
        return Icons.battery_charging_full_rounded;
    }
  }

  /// Czy sugestia proponuje nowy CIĘŻAR/POWTÓRZENIA do zastosowania w planie.
  /// Dla progresji czasowej/wariantowej pozostaje `false` (nie pokazujemy pól
  /// „sugerowany ciężar/powt.").
  bool get hasNewValues =>
      (suggestedWeightKg != currentWeightKg || suggestedReps != currentReps) &&
      (action == ProgressionAction.increaseWeight ||
          action == ProgressionAction.decreaseWeight ||
          action == ProgressionAction.deload ||
          action == ProgressionAction.increaseReps);
}

/// Analizuje historię ćwiczenia i zwraca sugestię progresji ZALEŻNĄ OD TYPU
/// ćwiczenia oraz od wiarygodności RPE (spec: punkty 3, 5, 6, 7).
///
/// Zasady:
///  * ćwiczenia bez obsługi ciężaru NIGDY nie dostają „Dodaj 1 kg",
///  * domyślne RPE (bez realnego dowodu wysiłku) nie wystarcza do zwiększenia
///    trudności — proponujemy wtedy utrzymanie i zbieranie danych,
///  * gdy żadna sensowna progresja nie jest możliwa — zwracamy `null`.
///
/// Czysta lokalna logika — nie wywołuje AI ani sieci.
ProgressionSuggestion? progressionSuggestionForExercise({
  required String exerciseId,
  required List<WorkoutLog> allLogs,
  required int plannedReps,
  required double plannedWeightKg,
  Exercise? exercise,
  List<Exercise> customExercises = const [],
}) {
  final def = exercise ?? ExerciseRepo.byId(exerciseId, customExercises);
  final entryType = def.entryType;

  // Pobierz logi tego ćwiczenia, posortowane od najnowszego.
  final history = allLogs.where((l) => l.exerciseId == exerciseId).toList()
    ..sort((a, b) => b.date.compareTo(a.date));
  if (history.isEmpty) return null;

  final latest = history.first;
  final currentWeight = latest.weightKg > 0 ? latest.weightKg : plannedWeightKg;
  final currentReps = latest.reps > 0 ? latest.reps : plannedReps;
  final window = history.take(5).toList();

  // Wiarygodne RPE: TYLKO serie z realnym dowodem wysiłku (świadomy wpis albo
  // pewne oszacowanie). Domyślne RPE 7 NIE jest dowodem do zwiększania trudności.
  bool hasReliableEvidence(WorkoutLog log) =>
      log.workoutSets.any((s) => s.countsForProgress && s.hasReliableRpe);
  final reliableWindow = window.where(hasReliableEvidence).toList();
  final anyReliable = reliableWindow.isNotEmpty;
  final reliableAvgRpe = reliableWindow.isEmpty
      ? 0.0
      : reliableWindow.fold<double>(0, (s, l) => s + l.rpe) /
          reliableWindow.length;

  ProgressionSuggestion maintain(String reason,
          {String? label, IconData? icon}) =>
      ProgressionSuggestion(
        action: ProgressionAction.maintain,
        reason: reason,
        suggestedWeightKg: currentWeight,
        suggestedReps: currentReps,
        currentWeightKg: currentWeight,
        currentReps: currentReps,
        labelOverride: label ?? '',
        iconOverride: icon,
      );

  // === A. Mobilność / rozciąganie — jakość ruchu, nigdy ciężar. ===
  if (entryType == ExerciseEntryType.mobility) {
    if (history.length < 2) return null;
    return maintain(
      'Rozciąganie rozwija się regularnością i zakresem ruchu — utrzymaj czas i skup się na płynnym, pełnym zakresie.',
      label: 'Utrzymaj i pogłębiaj zakres',
      icon: Icons.self_improvement_rounded,
    );
  }

  // === B. Ćwiczenia czasowe / izometryczne — progres czasem. ===
  if (entryType.supportsDurationProgression) {
    // Reprezentatywny, WIARYGODNY czas z ostatniej sesji.
    final base = def.defaultDurationSec > 0 ? def.defaultDurationSec : 45;
    int lastDuration = 0;
    for (final s in latest.workoutSets) {
      if (!s.countsForProgress) continue;
      final d = s.isTimeVerified && s.activeSeconds > 0
          ? s.activeSeconds
          : s.durationSec;
      if (isPlausibleHistoricalDuration(base, d) && d > lastDuration)
        lastDuration = d;
    }
    if (lastDuration <= 0 || history.length < 2) {
      return maintain(
        'Trainer zbiera więcej danych o czasie tego ćwiczenia — utrzymaj obecny poziom.',
        label: 'Utrzymaj czas',
        icon: Icons.timer_outlined,
      );
    }
    final allHeldStable = window.take(2).every((l) =>
        l.workoutSets.isEmpty ||
        l.workoutSets.every((s) => !s.isFailure && s.isCompleted));
    if (allHeldStable) {
      final newDuration = lastDuration + 5;
      return maintain(
        'Czas utrzymany stabilnie — dołóż 5 s (do ~$newDuration s), pilnując techniki.',
        label: 'Dodaj 5 s',
        icon: Icons.more_time_rounded,
      );
    }
    return maintain(
      'Utrzymaj czas serii i kontrolę do końca — bez pośpiechu.',
      label: 'Utrzymaj czas',
      icon: Icons.timer_outlined,
    );
  }

  // === C. Cardio — czas / dystans / tempo, nigdy ciężar. ===
  if (entryType.showsDistance) {
    if (history.length < 2) return null;
    return maintain(
      'Rozwijaj cardio czasem, dystansem albo tempem — dokładaj po trochu, zależnie od samopoczucia.',
      label: 'Wydłuż lub przyspiesz',
      icon: Icons.directions_run_rounded,
    );
  }

  // === D. Masa ciała bez ciężaru zewnętrznego — powtórzenia / wariant. ===
  if (!entryType.supportsWeightProgression) {
    final allCompletedReps = window.every((l) => l.reps >= plannedReps);
    if (window.length >= 2 && allCompletedReps) {
      // Górny pułap powtórzeń → trudniejszy wariant (jeśli wspierany).
      if (entryType.supportsHarderVariation && currentReps >= plannedReps + 4) {
        return maintain(
          'Powtórzenia idą gładko — czas na trudniejszy wariant ćwiczenia.',
          label: 'Trudniejszy wariant',
          icon: Icons.upgrade_rounded,
        );
      }
      final newReps = currentReps + 1;
      return ProgressionSuggestion(
        action: ProgressionAction.increaseReps,
        reason:
            'Serie ukończone stabilnie — spróbuj dobić do $newReps powtórzeń.',
        suggestedWeightKg: currentWeight,
        suggestedReps: newReps,
        currentWeightKg: currentWeight,
        currentReps: currentReps,
      );
    }
    if (history.length < 2) return null;
    return maintain(
      'Utrwal technikę i pełen zakres ruchu — dokładaj powtórzenia stopniowo.',
      label: 'Utrzymaj i utrwalaj',
      icon: Icons.check_circle_outline_rounded,
    );
  }

  // === E. Ćwiczenia z ciężarem zewnętrznym — klasyczna progresja obciążeniem. ===
  final avgRpe = anyReliable
      ? reliableAvgRpe
      : window.fold<double>(0, (s, l) => s + l.rpe) / window.length;
  final allCompletedReps = window.every((l) => l.reps >= plannedReps);
  final anyHighRpe = reliableWindow.any((l) => l.rpe >= 9);

  bool stagnant = false;
  if (history.length >= 4) {
    final older = history.sublist(1, math.min(5, history.length));
    final olderAvgWeight =
        older.fold<double>(0, (s, l) => s + l.weightKg) / older.length;
    stagnant = currentWeight <= olderAvgWeight && window.length >= 4;
  }

  // 1. Zmęczenie / wysoki, WIARYGODNY RPE → zmniejsz ciężar.
  if (anyReliable && (avgRpe >= 9.5 || (anyHighRpe && avgRpe >= 9.0))) {
    final newWeight = (currentWeight * 0.9).roundToDouble();
    return ProgressionSuggestion(
      action: ProgressionAction.decreaseWeight,
      reason:
          'RPE ${avgRpe.toStringAsFixed(1)} — zbyt intensywnie. Zmniejsz ciężar o ok. 10%.',
      suggestedWeightKg: newWeight > 0 ? newWeight : 0,
      suggestedReps: currentReps,
      currentWeightKg: currentWeight,
      currentReps: currentReps,
    );
  }

  // 2. Deload przy stagnacji i wysokim, wiarygodnym RPE.
  if (anyReliable && stagnant && avgRpe >= 8.0 && history.length >= 6) {
    final deloadWeight = (currentWeight * 0.8).roundToDouble();
    return ProgressionSuggestion(
      action: ProgressionAction.deload,
      reason:
          'Brak progresu przy RPE ${avgRpe.toStringAsFixed(1)}. Tydzień deload (80% ciężaru) pomoże w regeneracji.',
      suggestedWeightKg: deloadWeight > 0 ? deloadWeight : 0,
      suggestedReps: math.max(6, (currentReps * 0.8).round()),
      currentWeightKg: currentWeight,
      currentReps: currentReps,
    );
  }

  // 3. Niski, WIARYGODNY RPE + pełne powtórzenia → zwiększ ciężar.
  //    Bez wiarygodnego RPE nie zwiększamy trudności na podstawie domyślnej 7.
  if (anyReliable &&
      avgRpe > 0 &&
      avgRpe <= 7.0 &&
      allCompletedReps &&
      window.length >= 2) {
    final step = currentWeight < 10
        ? 1.0
        : currentWeight < 40
            ? 2.5
            : 5.0;
    final newWeight = currentWeight + step;
    return ProgressionSuggestion(
      action: ProgressionAction.increaseWeight,
      reason:
          'RPE ${avgRpe.toStringAsFixed(1)} — jest rezerwa. Dodaj ${step.toStringAsFixed(step == step.roundToDouble() ? 0 : 1)} kg.',
      suggestedWeightKg: newWeight,
      suggestedReps: currentReps,
      currentWeightKg: currentWeight,
      currentReps: currentReps,
    );
  }

  // 4. Dobry, wiarygodny RPE, ale nie wszystkie powtórzenia → najpierw powtórzenia.
  if (anyReliable &&
      avgRpe > 0 &&
      avgRpe <= 7.5 &&
      !allCompletedReps &&
      window.length >= 2) {
    final newReps = currentReps + 1;
    return ProgressionSuggestion(
      action: ProgressionAction.increaseReps,
      reason:
          'Dobry RPE (${avgRpe.toStringAsFixed(1)}), ale nie domknięte powtórzenia. Dobij do $newReps powt. przed zwiększeniem ciężaru.',
      suggestedWeightKg: currentWeight,
      suggestedReps: newReps,
      currentWeightKg: currentWeight,
      currentReps: currentReps,
    );
  }

  // 5. Wyraźna stagnacja (obiektywna) mimo umiarkowanego RPE → delikatny krok.
  if (anyReliable && stagnant && avgRpe > 0 && avgRpe < 8.0) {
    final step = currentWeight < 20 ? 1.0 : 2.5;
    final newWeight = currentWeight + step;
    return ProgressionSuggestion(
      action: ProgressionAction.increaseWeight,
      reason: 'Stagnacja od ${window.length} sesji. Spróbuj +$step kg.',
      suggestedWeightKg: newWeight,
      suggestedReps: currentReps,
      currentWeightKg: currentWeight,
      currentReps: currentReps,
    );
  }

  // 6. Brak wiarygodnego RPE → utrzymaj i zbieraj dane (bez sztucznej progresji).
  if (!anyReliable) {
    if (history.length < 2) return null;
    return maintain(
      'Trainer zbiera dane o Twoim wysiłku w tym ćwiczeniu — oceń serie (RPE), żeby dobrać progresję ciężaru.',
      icon: Icons.hourglass_bottom_rounded,
    );
  }

  // 7. Utrzymaj — wiarygodne RPE w optymalnym zakresie.
  if (avgRpe >= 7.0 && avgRpe <= 8.5) {
    return maintain(
        'RPE ${avgRpe.toStringAsFixed(1)} — optymalny zakres. Kontynuuj z aktualnym ciężarem.');
  }

  return null;
}

// --- Etap 17: AI analiza treningu ---

class WorkoutAiAnalysis {
  const WorkoutAiAnalysis({
    required this.sessionId,
    required this.timestamp,
    required this.rating,
    required this.wentWell,
    required this.improvable,
    required this.increaseWeight,
    required this.fatigueWarning,
    required this.nextStep,
    required this.rawSummary,
  });

  final String sessionId;
  final DateTime timestamp;
  final String rating;
  final String wentWell;
  final String improvable;
  final String increaseWeight;
  final String fatigueWarning;
  final String nextStep;
  final String rawSummary;

  static WorkoutAiAnalysis fromApiResult(
      String sessionId, Map<String, dynamic> result) {
    String pick(List<String> keys) {
      for (final k in keys) {
        final v = result[k];
        if (v != null && v.toString().trim().isNotEmpty)
          return v.toString().trim();
      }
      return '';
    }

    final raw = (result['summary'] ??
            result['analysis'] ??
            result['message'] ??
            result['reply'] ??
            prettyJson(result))
        .toString()
        .trim();
    return WorkoutAiAnalysis(
      sessionId: sessionId,
      timestamp: DateTime.now(),
      rating: pick(['rating', 'ocena', 'score', 'grade']),
      wentWell: pick(
          ['went_well', 'co_poszlo_dobrze', 'positives', 'strengths', 'dobre']),
      improvable: pick([
        'improvable',
        'co_poprawic',
        'improvements',
        'weaknesses',
        'poprawic'
      ]),
      increaseWeight: pick([
        'increase_weight',
        'zwiekszac_ciezar',
        'weight_recommendation',
        'ciezar'
      ]),
      fatigueWarning:
          pick(['fatigue_warning', 'zmeczenie', 'recovery', 'regeneracja']),
      nextStep: pick(
          ['next_step', 'nastepny_krok', 'recommendation', 'next', 'sugestia']),
      rawSummary: raw,
    );
  }

  Map<String, dynamic> toJson() => {
        'sessionId': sessionId,
        'timestamp': timestamp.toIso8601String(),
        'rating': rating,
        'wentWell': wentWell,
        'improvable': improvable,
        'increaseWeight': increaseWeight,
        'fatigueWarning': fatigueWarning,
        'nextStep': nextStep,
        'rawSummary': rawSummary,
      };

  factory WorkoutAiAnalysis.fromJson(Map<String, dynamic> json) =>
      WorkoutAiAnalysis(
        sessionId: json['sessionId']?.toString() ?? '',
        timestamp: DateTime.tryParse(json['timestamp']?.toString() ?? '') ??
            DateTime.now(),
        rating: json['rating']?.toString() ?? '',
        wentWell: json['wentWell']?.toString() ?? '',
        improvable: json['improvable']?.toString() ?? '',
        increaseWeight: json['increaseWeight']?.toString() ?? '',
        fatigueWarning: json['fatigueWarning']?.toString() ?? '',
        nextStep: json['nextStep']?.toString() ?? '',
        rawSummary: json['rawSummary']?.toString() ?? '',
      );
}

/// Krótki komunikat dla użytkownika, gdy analiza AI treningu się nie powiedzie.
/// Pełne szczegóły (payload / wyjątek / stack) trafiają wyłącznie do logów
/// debugowania — nigdy do interfejsu (spec: punkty 10, 13).
const String kWorkoutAnalysisFailedMessage =
    'Nie udało się przygotować analizy treningu. Trening został zapisany '
    'i możesz ponowić analizę później.';

// --- Etap 16: AI Trainer czat ---

/// Zamienia techniczny błąd HTTP/sieci na czytelny komunikat dla użytkownika
/// AI Trainera. Obsługuje 404, 500 i timeout zgodnie z wymaganiami.
String friendlyAiErrorMessage(Object error) {
  final text = error.toString();
  final lower = text.toLowerCase();
  if (text.contains('404') || lower.contains('not found')) {
    return 'Endpoint AI Trainer nie istnieje na backendzie (404). Zaktualizuj/zdeployuj backend.';
  }
  if (text.contains('500') ||
      text.contains('502') ||
      text.contains('503') ||
      lower.contains('server error')) {
    return 'Błąd serwera AI. Spróbuj ponownie za chwilę.';
  }
  if (lower.contains('timeout') || lower.contains('timed out')) {
    return 'Backend nie odpowiada. Sprawdź połączenie i spróbuj ponownie.';
  }
  if (lower.contains('socketexception') ||
      lower.contains('failed host lookup') ||
      lower.contains('connection')) {
    return 'Brak połączenia z backendem AI. Sprawdź internet.';
  }
  return 'Błąd połączenia z AI: $text';
}

class AiChatMessage {
  const AiChatMessage(
      {required this.role, required this.content, required this.timestamp});

  final String role; // 'user' | 'assistant' | 'error'
  final String content;
  final DateTime timestamp;

  Map<String, dynamic> toJson() => {
        'role': role,
        'content': content,
        'timestamp': timestamp.toIso8601String()
      };

  factory AiChatMessage.fromJson(Map<String, dynamic> json) => AiChatMessage(
        role: json['role']?.toString() ?? 'user',
        content: json['content']?.toString() ?? '',
        timestamp: DateTime.tryParse(json['timestamp']?.toString() ?? '') ??
            DateTime.now(),
      );
}

class WorkoutRestRecommendation {
  const WorkoutRestRecommendation({
    required this.seconds,
    required this.label,
  });

  final int seconds;
  final String label;
}

/// Przerwa dla bieżącego ćwiczenia — JEDNO źródło prawdy.
///
/// Gdy sesja ma receptę, bierzemy z niej wartość EFEKTYWNĄ: dokładnie tę samą,
/// którą pokazuje plan na ekranie ćwiczenia. Wcześniej timer odpoczynku liczył
/// przerwę własną heurystyką, niezależnie od rekomendacji, więc plan mógł mówić
/// „przerwa 90 s", a odliczało się 180 s.
///
/// Dla starszych/ad-hoc sesji bez recepty zachowujemy dotychczasowe zachowanie
/// (przerwa z planu albo dobrana do typu ćwiczenia).
WorkoutRestRecommendation workoutRestRecommendation(
  Exercise exercise,
  ActiveWorkoutExercise activeExercise,
) {
  final rx = activeExercise.prescription;
  if (rx != null && rx.effective.restSeconds > 0) {
    return WorkoutRestRecommendation(
      seconds: rx.effective.restSeconds.clamp(30, 600),
      label: restLabelFor(
        exercise,
        plannedReps: activeExercise.plannedReps,
        baseRestSeconds: rx.base.restSeconds,
        effectiveRestSeconds: rx.effective.restSeconds,
      ),
    );
  }
  final base = baseRestFor(
    exercise,
    plannedReps: activeExercise.plannedReps,
    plannedRestSeconds: activeExercise.restSeconds,
  );
  return WorkoutRestRecommendation(seconds: base.seconds, label: base.label);
}

String prettyJson(Object? value) {
  const encoder = JsonEncoder.withIndent('  ');
  return encoder.convert(value);
}

Map<String, dynamic>? asJsonMap(Object? value) {
  try {
    if (value is Map<String, dynamic>) return value;
    if (value is Map) return Map<String, dynamic>.from(value);
    if (value is String && value.trim().isNotEmpty) {
      final decoded = jsonDecode(value);
      if (decoded is Map) return Map<String, dynamic>.from(decoded);
    }
  } catch (_) {}
  return null;
}

String smartValue(dynamic value, {String fallback = '-'}) {
  if (value == null) return fallback;
  if (value is num) {
    final d = value.toDouble();
    return d == d.roundToDouble() ? d.round().toString() : d.toStringAsFixed(1);
  }
  final text = value.toString().trim();
  return text.isEmpty ? fallback : text;
}

List<String> smartStringList(dynamic value) {
  if (value is List)
    return value
        .map((e) => e.toString())
        .where((e) => e.trim().isNotEmpty)
        .toList();
  if (value is String && value.trim().isNotEmpty) return [value.trim()];
  return const [];
}

String weekdayName(int weekday) {
  const names = {
    1: 'Poniedziałek',
    2: 'Wtorek',
    3: 'Środa',
    4: 'Czwartek',
    5: 'Piątek',
    6: 'Sobota',
    7: 'Niedziela',
  };
  return names[weekday] ?? 'Dzień';
}

String shortDate(DateTime d) =>
    '${d.day.toString().padLeft(2, '0')}.${d.month.toString().padLeft(2, '0')}';

class AppSettings {
  final double bodyWeightKg;
  final double heightCm;
  final int age;
  final String sex;
  final String goal;
  final String level;
  final String trainingMode;
  final String equipment;
  final String limitations;
  final String backendUrl;
  final bool darkMode;
  final int accentColorValue;
  final List<int> trainingWeekdays;

  /// General work activity used only as a fallback when the watch does not
  /// report enough active calories for the day.
  final String workIntensity;
  final double workHoursPerDay;
  final List<int> workWeekdays;

  // === Personalizacja wyglądu (Etap: wygląd) ===
  /// Id motywu UI z [kTrainerThemeStyles] (np. 'classic_sport', 'neon_fitness').
  final String themeStyleId;

  /// Gęstość UI: 'compact' | 'normal' | 'large'.
  final String uiDensity;

  /// Zaokrąglenia elementów: 'sharp' | 'soft' | 'round'.
  final String cornerStyle;

  /// Styl kart: 'flat' | 'outlined' | 'elevated'.
  final String cardStyle;

  /// Układ kafelków programów: 'list' | 'grid' | 'compact'.
  final String tileLayout;

  /// Styl dolnego menu: 'floating' | 'classic' | 'minimal'.
  final String navBarStyle;

  /// Delikatne gradienty na kafelkach i kartach hero.
  final bool useGradients;

  /// Przezroczystość kart/paneli (0.55–1.0; 1.0 = pełne krycie).
  final double cardOpacity;

  /// Przezroczystość dolnego menu (0.55–1.0; 1.0 = pełne krycie).
  final double navBarOpacity;

  /// Gradientowe tło całej aplikacji (poza jednolitym kolorem tła).
  final bool backgroundGradient;

  /// Siła przejść gradientowych (tło + karty): 'subtle' | 'medium' | 'strong'.
  final String gradientStrength;

  /// Kierunek gradientów: 'diagonal' | 'vertical' | 'radial'.
  final String gradientStyle;

  /// Efekt szkła: rozmycie tła pod dolnym menu (frosted glass). Najlepiej
  /// widoczny przy obniżonej przezroczystości menu.
  final bool glassEffect;

  /// Własne zdjęcie jako tło aplikacji ('' = brak; ma pierwszeństwo przed
  /// gradientowym tłem) + jego rozmycie (sigma 0-30) i przyciemnienie (0-0.7).
  final String backgroundImagePath;
  final double backgroundImageBlur;
  final double backgroundImageDarken;

  /// Dekoracyjne TŁO MOTYWU — każdy motyw UI ma własny, proceduralny wzór tła
  /// rysowany z jego kolorów (jak zdjęcie tła, ale bez pliku; dopasowuje się
  /// do dnia i nocy). Zdjęcie użytkownika ma zawsze pierwszeństwo.
  final bool themedBackground;

  /// Klucz API OpenAI do generowania obrazów ćwiczeń (przechowywany lokalnie
  /// na urządzeniu, nigdy nie wysyłany do backendu Trainera).
  final String openAiApiKey;

  /// Klucz API Google Gemini do generowania opisów ćwiczeń (przechowywany
  /// lokalnie na urządzeniu, wysyłany wyłącznie do Google — nigdy do backendu
  /// Trainera). Do AI opisów używamy Gemini, a nie GPT.
  final String geminiApiKey;

  /// Docelowy typ sylwetki użytkownika ([SilhouetteGoal.id]; '' = nie wybrano).
  final String targetSilhouette;

  /// Docelowa masa ciała (kg; 0 = cel nieustawiony).
  final double targetWeightKg;

  /// Tryb sprzętowy ([EquipmentMode.key]). '' = wyprowadź ze starego, wolnego
  /// pola [equipment] (zgodność wsteczna — istniejący użytkownicy nic nie tracą).
  final String equipmentModeKey;

  /// Ręcznie zaznaczony sprzęt ([EquipmentType.key]) dla trybów wybieralnych
  /// (domowy mieszany / własny zestaw).
  final List<String> ownedEquipmentKeys;

  /// Strukturalne ograniczenia treningowe ([TrainingLimitation.key]).
  final List<String> limitationFlagKeys;

  /// Tryb prowadzenia treningu ([GuidanceMode.key]): full/assisted/manual.
  /// Domyślnie „pełne prowadzenie" — Trainer sam dobiera parametry.
  final String guidanceMode;

  /// Cykliczny deload (odciążenie): zaplanowane okresy zejścia z objętości
  /// i intensywności. Kotwica ([DeloadCycle.anchor]) ustawiana jest leniwie na
  /// „dziś" przy pierwszym użyciu (patrz [AppStore.deloadCycle]).
  final DeloadCycle deloadCycle;

  /// Trwały rozkład treningu (data → obszar). Zapisany, więc tydzień nie
  /// przestawia się po kliknięciu innego zestawu.
  final TrainingScheduleConfig trainingSchedule;

  const AppSettings({
    required this.bodyWeightKg,
    required this.heightCm,
    required this.age,
    this.sex = '',
    required this.goal,
    required this.level,
    required this.trainingMode,
    required this.equipment,
    required this.limitations,
    required this.backendUrl,
    required this.darkMode,
    required this.accentColorValue,
    required this.trainingWeekdays,
    this.workIntensity = 'none',
    this.workHoursPerDay = 0,
    this.workWeekdays = const <int>[1, 2, 3, 4, 5],
    this.themeStyleId = 'classic_sport',
    this.uiDensity = 'normal',
    this.cornerStyle = 'soft',
    this.cardStyle = 'flat',
    this.tileLayout = 'list',
    this.navBarStyle = 'floating',
    this.useGradients = true,
    this.cardOpacity = 1.0,
    this.navBarOpacity = 1.0,
    this.backgroundGradient = false,
    this.gradientStrength = 'medium',
    this.gradientStyle = 'diagonal',
    this.glassEffect = false,
    this.backgroundImagePath = '',
    this.backgroundImageBlur = 14,
    this.backgroundImageDarken = 0.30,
    this.openAiApiKey = '',
    this.geminiApiKey = '',
    this.targetSilhouette = '',
    this.targetWeightKg = 0,
    this.themedBackground = true,
    this.equipmentModeKey = '',
    this.ownedEquipmentKeys = const <String>[],
    this.limitationFlagKeys = const <String>[],
    this.guidanceMode = 'full',
    this.deloadCycle = const DeloadCycle(),
    this.trainingSchedule = const TrainingScheduleConfig(),
  });

  factory AppSettings.defaults() => const AppSettings(
        bodyWeightKg: 100,
        heightCm: 185,
        age: 28,
        sex: '',
        goal: 'Rekompozycja / brzuch + masa mięśniowa',
        level: 'Średniozaawansowany',
        trainingMode: 'Rekompozycja',
        equipment: 'masa ciała, hantle, drążek, mata',
        limitations: '',
        backendUrl: kDefaultBackendUrl,
        darkMode: true,
        accentColorValue: 0xFF24D6A3,
        trainingWeekdays: [1, 2, 3, 4, 5, 6],
      );

  AppSettings copyWith({
    double? bodyWeightKg,
    double? heightCm,
    int? age,
    String? sex,
    String? goal,
    String? level,
    String? trainingMode,
    String? equipment,
    String? limitations,
    String? backendUrl,
    bool? darkMode,
    int? accentColorValue,
    List<int>? trainingWeekdays,
    String? workIntensity,
    double? workHoursPerDay,
    List<int>? workWeekdays,
    String? themeStyleId,
    String? uiDensity,
    String? cornerStyle,
    String? cardStyle,
    String? tileLayout,
    String? navBarStyle,
    bool? useGradients,
    double? cardOpacity,
    double? navBarOpacity,
    bool? backgroundGradient,
    String? gradientStrength,
    String? gradientStyle,
    bool? glassEffect,
    String? backgroundImagePath,
    double? backgroundImageBlur,
    double? backgroundImageDarken,
    String? openAiApiKey,
    String? geminiApiKey,
    String? targetSilhouette,
    double? targetWeightKg,
    bool? themedBackground,
    String? equipmentModeKey,
    List<String>? ownedEquipmentKeys,
    List<String>? limitationFlagKeys,
    String? guidanceMode,
    DeloadCycle? deloadCycle,
    TrainingScheduleConfig? trainingSchedule,
  }) {
    return AppSettings(
      bodyWeightKg: bodyWeightKg ?? this.bodyWeightKg,
      heightCm: heightCm ?? this.heightCm,
      age: age ?? this.age,
      sex: sex ?? this.sex,
      goal: goal ?? this.goal,
      level: level ?? this.level,
      trainingMode: trainingMode ?? this.trainingMode,
      equipment: equipment ?? this.equipment,
      limitations: limitations ?? this.limitations,
      backendUrl: backendUrl ?? this.backendUrl,
      darkMode: darkMode ?? this.darkMode,
      accentColorValue: accentColorValue ?? this.accentColorValue,
      trainingWeekdays: trainingWeekdays ?? this.trainingWeekdays,
      workIntensity: workIntensity ?? this.workIntensity,
      workHoursPerDay: workHoursPerDay ?? this.workHoursPerDay,
      workWeekdays: workWeekdays ?? this.workWeekdays,
      themeStyleId: themeStyleId ?? this.themeStyleId,
      uiDensity: uiDensity ?? this.uiDensity,
      cornerStyle: cornerStyle ?? this.cornerStyle,
      cardStyle: cardStyle ?? this.cardStyle,
      tileLayout: tileLayout ?? this.tileLayout,
      navBarStyle: navBarStyle ?? this.navBarStyle,
      useGradients: useGradients ?? this.useGradients,
      cardOpacity: cardOpacity ?? this.cardOpacity,
      navBarOpacity: navBarOpacity ?? this.navBarOpacity,
      backgroundGradient: backgroundGradient ?? this.backgroundGradient,
      gradientStrength: gradientStrength ?? this.gradientStrength,
      gradientStyle: gradientStyle ?? this.gradientStyle,
      glassEffect: glassEffect ?? this.glassEffect,
      backgroundImagePath: backgroundImagePath ?? this.backgroundImagePath,
      backgroundImageBlur: backgroundImageBlur ?? this.backgroundImageBlur,
      backgroundImageDarken:
          backgroundImageDarken ?? this.backgroundImageDarken,
      openAiApiKey: openAiApiKey ?? this.openAiApiKey,
      geminiApiKey: geminiApiKey ?? this.geminiApiKey,
      targetSilhouette: targetSilhouette ?? this.targetSilhouette,
      targetWeightKg: targetWeightKg ?? this.targetWeightKg,
      themedBackground: themedBackground ?? this.themedBackground,
      equipmentModeKey: equipmentModeKey ?? this.equipmentModeKey,
      ownedEquipmentKeys: ownedEquipmentKeys ?? this.ownedEquipmentKeys,
      limitationFlagKeys: limitationFlagKeys ?? this.limitationFlagKeys,
      guidanceMode: guidanceMode ?? this.guidanceMode,
      deloadCycle: deloadCycle ?? this.deloadCycle,
      trainingSchedule: trainingSchedule ?? this.trainingSchedule,
    );
  }

  Map<String, dynamic> toJson() => {
        'bodyWeightKg': bodyWeightKg,
        'heightCm': heightCm,
        'age': age,
        'sex': sex,
        'goal': goal,
        'level': level,
        'trainingMode': trainingMode,
        'equipment': equipment,
        'limitations': limitations,
        'backendUrl': backendUrl,
        'darkMode': darkMode,
        'accentColorValue': accentColorValue,
        'trainingWeekdays': trainingWeekdays,
        'workIntensity': workIntensity,
        'workHoursPerDay': workHoursPerDay,
        'workWeekdays': workWeekdays,
        'themeStyleId': themeStyleId,
        'uiDensity': uiDensity,
        'cornerStyle': cornerStyle,
        'cardStyle': cardStyle,
        'tileLayout': tileLayout,
        'navBarStyle': navBarStyle,
        'useGradients': useGradients,
        'cardOpacity': cardOpacity,
        'navBarOpacity': navBarOpacity,
        'backgroundGradient': backgroundGradient,
        'gradientStrength': gradientStrength,
        'gradientStyle': gradientStyle,
        'glassEffect': glassEffect,
        'backgroundImagePath': backgroundImagePath,
        'backgroundImageBlur': backgroundImageBlur,
        'backgroundImageDarken': backgroundImageDarken,
        'openAiApiKey': openAiApiKey,
        'geminiApiKey': geminiApiKey,
        'targetSilhouette': targetSilhouette,
        'targetWeightKg': targetWeightKg,
        'themedBackground': themedBackground,
        'equipmentModeKey': equipmentModeKey,
        'ownedEquipmentKeys': ownedEquipmentKeys,
        'limitationFlagKeys': limitationFlagKeys,
        'guidanceMode': guidanceMode,
        'deloadCycle': deloadCycle.toJson(),
        'trainingSchedule': trainingSchedule.toJson(),
      };

  factory AppSettings.fromJson(Map<String, dynamic> json) => AppSettings(
        bodyWeightKg: (json['bodyWeightKg'] as num?)?.toDouble() ?? 100,
        heightCm: (json['heightCm'] as num?)?.toDouble() ?? 185,
        age: (json['age'] as num?)?.toInt() ?? 28,
        sex: json['sex']?.toString() ?? '',
        goal: json['goal']?.toString() ??
            'Rekompozycja / brzuch + masa mięśniowa',
        level:
            normalizeLevel(json['level']?.toString() ?? 'Średniozaawansowany'),
        trainingMode: normalizeTrainingMode(json['trainingMode']?.toString() ??
            json['mode']?.toString() ??
            'Rekompozycja'),
        equipment:
            json['equipment']?.toString() ?? 'masa ciała, hantle, drążek, mata',
        limitations: json['limitations']?.toString() ?? '',
        backendUrl: ((json['backendUrl']?.toString() ?? '').trim().isEmpty)
            ? kDefaultBackendUrl
            : json['backendUrl'].toString(),
        darkMode: json['darkMode'] as bool? ?? true,
        accentColorValue:
            (json['accentColorValue'] as num?)?.toInt() ?? 0xFF24D6A3,
        trainingWeekdays:
            ((json['trainingWeekdays'] as List?) ?? [1, 2, 3, 4, 5, 6])
                .map((e) => (e as num).toInt())
                .toList(),
        workIntensity: json['workIntensity']?.toString() ?? 'none',
        workHoursPerDay: ((json['workHoursPerDay'] as num?)?.toDouble() ?? 0)
            .clamp(0.0, 16.0)
            .toDouble(),
        workWeekdays: ((json['workWeekdays'] as List?) ?? [1, 2, 3, 4, 5])
            .whereType<num>()
            .map((e) => e.toInt().clamp(1, 7).toInt())
            .toSet()
            .toList(),
        themeStyleId: json['themeStyleId']?.toString() ?? 'classic_sport',
        uiDensity: json['uiDensity']?.toString() ?? 'normal',
        cornerStyle: json['cornerStyle']?.toString() ?? 'soft',
        cardStyle: json['cardStyle']?.toString() ?? 'flat',
        tileLayout: json['tileLayout']?.toString() ?? 'list',
        navBarStyle: json['navBarStyle']?.toString() ?? 'floating',
        useGradients: json['useGradients'] as bool? ?? true,
        cardOpacity:
            ((json['cardOpacity'] as num?)?.toDouble() ?? 1.0).clamp(0.55, 1.0),
        navBarOpacity: ((json['navBarOpacity'] as num?)?.toDouble() ?? 1.0)
            .clamp(0.55, 1.0),
        backgroundGradient: json['backgroundGradient'] as bool? ?? false,
        gradientStrength: json['gradientStrength']?.toString() ?? 'medium',
        gradientStyle: json['gradientStyle']?.toString() ?? 'diagonal',
        glassEffect: json['glassEffect'] as bool? ?? false,
        backgroundImagePath: json['backgroundImagePath']?.toString() ?? '',
        backgroundImageBlur:
            ((json['backgroundImageBlur'] as num?)?.toDouble() ?? 14)
                .clamp(0.0, 40.0),
        backgroundImageDarken:
            ((json['backgroundImageDarken'] as num?)?.toDouble() ?? 0.30)
                .clamp(0.0, 0.8),
        openAiApiKey: json['openAiApiKey']?.toString() ?? '',
        geminiApiKey: json['geminiApiKey']?.toString() ?? '',
        targetSilhouette: json['targetSilhouette']?.toString() ?? '',
        targetWeightKg: (json['targetWeightKg'] as num?)?.toDouble() ?? 0,
        themedBackground: json['themedBackground'] as bool? ?? true,
        equipmentModeKey: json['equipmentModeKey']?.toString() ?? '',
        ownedEquipmentKeys:
            ((json['ownedEquipmentKeys'] as List?) ?? const <dynamic>[])
                .map((e) => e.toString())
                .toList(),
        limitationFlagKeys:
            ((json['limitationFlagKeys'] as List?) ?? const <dynamic>[])
                .map((e) => e.toString())
                .toList(),
        guidanceMode: json['guidanceMode']?.toString() ?? 'full',
        deloadCycle: json['deloadCycle'] is Map
            ? DeloadCycle.fromJson(
                Map<String, dynamic>.from(json['deloadCycle'] as Map))
            : const DeloadCycle(),
        trainingSchedule: json['trainingSchedule'] is Map
            ? TrainingScheduleConfig.fromJson(
                Map<String, dynamic>.from(json['trainingSchedule'] as Map))
            : const TrainingScheduleConfig(),
      );

  Map<String, dynamic> toAiProfile() => {
        'body_weight_kg': bodyWeightKg,
        'height_cm': heightCm,
        'age': age,
        'sex': sex,
        'goal': goal,
        'level': level,
        'trainingMode': trainingMode,
        'equipment': equipment,
        'limitations': limitations,
        'training_weekdays': trainingWeekdays,
        'work_intensity': workIntensity,
        'work_hours_per_day': workHoursPerDay,
        'work_weekdays': workWeekdays,
      };

  /// Profil regeneracji wyprowadzony z ustawień użytkownika.
  RecoveryProfile toRecoveryProfile() => RecoveryProfile(
        bodyWeightKg: bodyWeightKg,
        heightCm: heightCm,
        age: age,
        sex: sex,
        level: level,
        trainingDaysPerWeek: trainingWeekdays.length,
      );

  /// Profil sprzętowy — nowe pola strukturalne albo migracja ze starego
  /// pola tekstowego [equipment] (zgodność wsteczna, bez utraty konfiguracji).
  EquipmentProfile get equipmentProfile => EquipmentProfile.resolve(
        modeKey: equipmentModeKey,
        ownedKeys: ownedEquipmentKeys,
        legacyText: equipment,
      );

  /// Ograniczenia treningowe — flagi strukturalne albo migracja z wolnego
  /// tekstu [limitations].
  LimitationProfile get limitationProfile => LimitationProfile.resolve(
        flagKeys: limitationFlagKeys,
        legacyText: limitations,
      );

  /// Tryb prowadzenia jako enum ([GuidanceMode]); domyślnie pełne prowadzenie.
  GuidanceMode get guidanceModeEnum => GuidanceMode.fromKey(guidanceMode);
}

/// Instruktażowe wideo (asset) per ćwiczenie — odtwarzane w trakcie treningu.
/// Klucz = id ćwiczenia. Dodając kolejne ćwiczenia, dopisz tu plik wideo
/// (albo ustaw `videoPath` bezpośrednio w definicji ćwiczenia). Pliki leżą w
/// `assets/exercises/videos/` i są zadeklarowane w pubspec.yaml.
const Map<String, String> kExerciseVideoAssets = {
  'crunch': 'assets/exercises/videos/crunch.mp4',
  'hip_thrust': 'assets/exercises/videos/hip_thrust.mp4',
  'deadlift': 'assets/exercises/videos/deadlift.mp4',
  'pushup': 'assets/exercises/videos/pushup.mp4',
  'triceps_extension': 'assets/exercises/videos/triceps_extension.mp4',
  'bulgarian_split_squat': 'assets/exercises/videos/bulgarian_split_squat.mp4',
  'russian_twist': 'assets/exercises/videos/russian_twist.mp4',
  'lat_pulldown': 'assets/exercises/videos/lat_pulldown.mp4',
  'bicep_curl': 'assets/exercises/videos/bicep_curl.mp4',
  'lateral_raise': 'assets/exercises/videos/lateral_raise.mp4',
  'leg_raise': 'assets/exercises/videos/leg_raise.mp4',
  'row': 'assets/exercises/videos/row.mp4',
  'mountain_climber': 'assets/exercises/videos/mountain_climber.mp4',
  'shoulder_press': 'assets/exercises/videos/shoulder_press.mp4',
  'bench_press': 'assets/exercises/videos/bench_press.mp4',
  'lunge': 'assets/exercises/videos/lunge.mp4',
};

/// Wideo instruktażowe dla ćwiczenia o danym id (albo null).
String? exerciseVideoAsset(String id) => kExerciseVideoAssets[id];

