/// Awatar użytkownika w nagłówku Trainera — otwiera ekran „Konto i synchronizacja".
class TrainerUserAvatarButton extends StatelessWidget {
  const TrainerUserAvatarButton({super.key});

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    return AnimatedBuilder(
      animation: trainerAccountService,
      builder: (context, _) {
        final st = trainerAccountService.state;
        final signedIn = st.signedIn;
        final letter = (st.email ?? st.displayName ?? '').trim();
        return Tooltip(
          message: signedIn ? (st.email ?? 'Konto') : 'Konto i synchronizacja',
          child: InkWell(
            borderRadius: BorderRadius.circular(22),
            onTap: () => Navigator.of(context).push(
              MaterialPageRoute(builder: (_) => const AccountSyncPage()),
            ),
            child: Container(
              width: 40,
              height: 40,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                shape: BoxShape.circle,
                color:
                    signedIn ? scheme.primary : scheme.surfaceContainerHighest,
                border: Border.all(
                  color: scheme.primary.withValues(alpha: signedIn ? 0.0 : 0.5),
                  width: 1.2,
                ),
              ),
              child: signedIn
                  ? Text(
                      letter.isEmpty
                          ? '?'
                          : letter.substring(0, 1).toUpperCase(),
                      style: TextStyle(
                        color: scheme.onPrimary,
                        fontWeight: FontWeight.w900,
                        fontSize: 17,
                      ),
                    )
                  : Icon(Icons.person_outline_rounded,
                      color: scheme.primary, size: 22),
            ),
          ),
        );
      },
    );
  }
}

class HomeShell extends StatefulWidget {
  const HomeShell({super.key});

  @override
  State<HomeShell> createState() => _HomeShellState();
}

/// Etap 21: wspólny sposób otwierania podstron Trainera ze spójnym AppBarem.
/// Zastępuje dawny prywatny launcher z dashboardu „Start".
void openTrainerSubPage(BuildContext context, Widget page, {String? title}) {
  Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => Scaffold(
        appBar: AppBar(toolbarHeight: 48, title: Text(title ?? kAppName)),
        body: SafeArea(child: page),
      ),
    ),
  );
}

class _HomeShellState extends State<HomeShell> {
  int index = 0;

  // Start aplikacji NIE otwiera już automatycznie modelu regeneracji —
  // wchodzi się w niego świadomie (Więcej → Regeneracja albo kafelek).

  // Etap 21: uporządkowane menu główne — 5 czytelnych zakładek.
  // Każdy ekran ma jeden jasny punkt wejścia (bez dublowania nawigacji).
  static const _pages = [
    TodayPage(),
    PlanPage(),
    ExercisesPage(),
    ProgressPage(),
    MorePage(),
  ];

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final dark = theme.brightness == Brightness.dark;
    final store = AppScope.of(context);
    final navStyle = store.settings.navBarStyle;
    final cornerScale = _cornerScaleFor(store.settings.cornerStyle);

    // Sportowe ikony zakładek — „Trening" prowadzi do programów (kalendarz),
    // „Ćwiczenia" do bazy (hantle).
    final destinations = const [
      NavigationDestination(
          icon: Icon(Icons.space_dashboard_outlined),
          selectedIcon: Icon(Icons.space_dashboard_rounded),
          label: 'Dzisiaj'),
      NavigationDestination(
          icon: Icon(Icons.calendar_month_outlined),
          selectedIcon: Icon(Icons.calendar_month_rounded),
          label: 'Trening'),
      NavigationDestination(
          icon: Icon(Icons.fitness_center_outlined),
          selectedIcon: Icon(Icons.fitness_center_rounded),
          label: 'Ćwiczenia'),
      NavigationDestination(
          icon: Icon(Icons.insights_outlined),
          selectedIcon: Icon(Icons.insights_rounded),
          label: 'Postęp'),
      NavigationDestination(
          icon: Icon(Icons.grid_view_outlined),
          selectedIcon: Icon(Icons.grid_view_rounded),
          label: 'Więcej'),
    ];

    // Przezroczystość dolnego menu z personalizacji (1.0 = pełne krycie).
    // Efekt szkła wymusza lekką przezroczystość, żeby rozmycie było widoczne.
    final glass = store.settings.glassEffect;
    final navBarOpacity = glass
        ? math.min(store.settings.navBarOpacity, 0.80).clamp(0.55, 1.0)
        : store.settings.navBarOpacity.clamp(0.55, 1.0);
    final navBar = NavigationBar(
      height: navStyle == 'minimal' ? 60 : 68,
      selectedIndex: index,
      onDestinationSelected: (v) => setState(() => index = v),
      backgroundColor: (dark ? const Color(0xFF161D26) : Colors.white)
          .withValues(alpha: navBarOpacity),
      surfaceTintColor: Colors.transparent,
      indicatorColor:
          theme.colorScheme.primary.withValues(alpha: dark ? 0.28 : 0.18),
      labelBehavior: navStyle == 'minimal'
          ? NavigationDestinationLabelBehavior.onlyShowSelected
          : NavigationDestinationLabelBehavior.alwaysShow,
      destinations: destinations,
    );
    // Frosted glass: rozmycie tego, co przewija się pod menu.
    Widget navBarWithGlass() {
      if (!glass) return navBar;
      return BackdropFilter(
        filter: ui.ImageFilter.blur(sigmaX: 14, sigmaY: 14),
        child: navBar,
      );
    }

    // Styl dolnego menu z personalizacji: pływające (domyślne), klasyczne
    // (pełna szerokość) albo minimalne (niższy pasek, etykieta tylko aktywnej).
    final Widget bottomNav;
    if (navStyle == 'classic') {
      bottomNav = glass ? ClipRect(child: navBarWithGlass()) : navBar;
    } else {
      final radius = BorderRadius.circular(26 * cornerScale);
      bottomNav = SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(12, 0, 12, 10),
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: radius,
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withValues(alpha: dark ? 0.45 : 0.12),
                  blurRadius: 18,
                  offset: const Offset(0, 6),
                ),
              ],
            ),
            child: ClipRRect(
              borderRadius: radius,
              child: navBarWithGlass(),
            ),
          ),
        ),
      );
    }

    return Scaffold(
      resizeToAvoidBottomInset: true,
      body: SafeArea(
        child: Stack(
          children: [
            AnimatedSwitcher(
              duration: const Duration(milliseconds: 220),
              switchInCurve: Curves.easeOut,
              switchOutCurve: Curves.easeIn,
              transitionBuilder: (child, animation) =>
                  FadeTransition(opacity: animation, child: child),
              child: KeyedSubtree(
                key: ValueKey<int>(index),
                child: _pages[index],
              ),
            ),
            // Awatar konta w prawym górnym rogu (na każdej głównej zakładce) —
            // otwiera „Konto i synchronizacja". Nakładka nie wpływa na układ
            // podstron ani na testy (te budują pojedyncze ekrany, nie HomeShell).
            const Positioned(
              top: 6,
              right: 14,
              child: TrainerUserAvatarButton(),
            ),
          ],
        ),
      ),
      bottomNavigationBar: bottomNav,
    );
  }
}

class TrainerHomePage extends StatelessWidget {
  const TrainerHomePage({
    super.key,
    required this.onToday,
    required this.onExercises,
    required this.onHistory,
    required this.onPlans,
    required this.onProgress,
    required this.onSettings,
  });

  final VoidCallback onToday;
  final VoidCallback onExercises;
  final VoidCallback onHistory;
  final VoidCallback onPlans;
  final VoidCallback onProgress;
  final VoidCallback onSettings;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final scheme = Theme.of(context).colorScheme;
    final theme = Theme.of(context);
    final isDark = theme.brightness == Brightness.dark;
    final todayLogs = store.logsForDay(DateTime.now());
    final plan = store.activeWorkoutPlan;
    // Podtytuł kafelka bierze się z ROZKŁADU (partia główna + dodatek), a nie
    // z dnia o pasującym numerze tygodnia w ostatnio otwartym planie.
    final scheduledToday = store.todayScheduled;
    final hasActiveSession = store.activeWorkoutSession != null;
    final weekLogs = store.logsBetween(
        DateTime.now().subtract(const Duration(days: 6)), DateTime.now());
    final weekDays = weekLogs.map((l) => l.date.weekday).toSet().length;

    // Kolory akcentów per sekcja
    final mint = const Color(0xFF24D6A3);
    final blue = const Color(0xFF58A6FF);
    final amber = const Color(0xFFFFB86B);
    final purple = const Color(0xFFB388FF);
    final rose = const Color(0xFFFF6B6B);
    final cyan = const Color(0xFF26C6DA);

    final tiles = [
      TrainerHomeTileData(
        title: 'Dzisiejszy trening',
        subtitle: scheduledToday == null
            ? 'Ustaw rozkład tygodnia, aby zobaczyć plan na dziś'
            : (scheduledToday.isRest
                ? 'Dziś dzień wolny w rozkładzie'
                : 'Wg planu: ${scheduledToday.label}'),
        icon: Icons.today_rounded,
        onTap: onToday,
        accentColor: mint,
        badge: hasActiveSession
            ? 'W TOKU'
            : (todayLogs.isNotEmpty ? 'GOTOWE' : null),
      ),
      TrainerHomeTileData(
        title: 'Baza ćwiczeń',
        subtitle:
            '${ExerciseRepo.combined(store.customExercises).length} ćwiczeń dostępnych lokalnie',
        icon: Icons.fitness_center_rounded,
        onTap: onExercises,
        accentColor: blue,
      ),
      TrainerHomeTileData(
        title: 'Historia',
        subtitle: store.logs.isEmpty
            ? 'Brak zapisanych wpisów'
            : '${store.logs.length} wpisów treningowych',
        icon: Icons.history_rounded,
        onTap: onHistory,
        accentColor: amber,
      ),
      TrainerHomeTileData(
        title: 'Plany treningowe',
        subtitle: store.plans.isEmpty
            ? 'Brak planów — wygeneruj z AI'
            : '${store.plans.length} ${store.plans.length == 1 ? 'plan' : 'planów'} · ${plan?.name ?? ''}',
        icon: Icons.calendar_month_rounded,
        onTap: onPlans,
        accentColor: purple,
      ),
      TrainerHomeTileData(
        title: 'Progres',
        subtitle: 'Podsumowanie treningów i sylwetka',
        icon: Icons.trending_up_rounded,
        onTap: onProgress,
        accentColor: rose,
      ),
      TrainerHomeTileData(
        title: 'Ustawienia',
        subtitle: 'Profil, wygląd i integracje',
        icon: Icons.tune_rounded,
        onTap: onSettings,
        accentColor: cyan,
      ),
    ];

    return PageFrame(
      title: 'Trainer',
      subtitle: 'Twój trening w jednym miejscu',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Hero card — premium gradient
          Container(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: isDark
                    ? [const Color(0xFF1A2E26), const Color(0xFF0D1B2A)]
                    : [scheme.primaryContainer, scheme.secondaryContainer],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              ),
              borderRadius: BorderRadius.circular(24),
              border: Border.all(
                  color:
                      scheme.primary.withValues(alpha: isDark ? 0.25 : 0.15)),
            ),
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          hasActiveSession
                              ? 'Trening w toku ▶'
                              : todayLogs.isNotEmpty
                                  ? 'Świetna robota! 💪'
                                  : 'Gotowy na trening?',
                          style: theme.textTheme.titleLarge?.copyWith(
                            fontWeight: FontWeight.w900,
                            color: isDark
                                ? Colors.white
                                : scheme.onPrimaryContainer,
                          ),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          scheduledToday != null && !scheduledToday.isRest
                              ? 'Dziś: ${scheduledToday.label}'
                              : todayLogs.isNotEmpty
                                  ? '${todayLogs.length} ${todayLogs.length == 1 ? 'ćwiczenie' : 'ćwiczenia'} zapisane'
                                  : 'Otwórz plan lub dodaj wpis',
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: (isDark
                                    ? Colors.white
                                    : scheme.onPrimaryContainer)
                                .withValues(alpha: 0.75),
                          ),
                        ),
                        const SizedBox(height: 12),
                        // Wrap zamiast Row — odznaki łamią się na wąskich ekranach
                        // zamiast wychodzić poza kartę (overflow po prawej).
                        Wrap(
                          spacing: 8,
                          runSpacing: 8,
                          children: [
                            _HeroBadge(
                              icon: Icons.local_fire_department_outlined,
                              label: '$weekDays dni w tyg.',
                              color: const Color(0xFFFF6B6B),
                            ),
                            _HeroBadge(
                              icon: Icons.fitness_center_rounded,
                              label: '${store.logs.length} wpisów',
                              color: const Color(0xFF24D6A3),
                            ),
                          ],
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 14),
                  GestureDetector(
                    onTap: onToday,
                    child: Container(
                      width: 72,
                      height: 72,
                      decoration: BoxDecoration(
                        color: scheme.primary
                            .withValues(alpha: isDark ? 0.18 : 0.12),
                        borderRadius: BorderRadius.circular(22),
                        border: Border.all(
                            color: scheme.primary.withValues(alpha: 0.28)),
                      ),
                      child: Icon(
                        hasActiveSession
                            ? Icons.play_circle_rounded
                            : Icons.directions_run_rounded,
                        color: scheme.primary,
                        size: 38,
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 16),
          ...tiles.map((tile) => Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: TrainerHomeTile(data: tile),
              )),
        ],
      ),
    );
  }
}

