Future<bool> _confirmAndDeleteTrainerWorkoutHistoryEntry(
    BuildContext context, _TrainerWorkoutHistoryEntry entry) async {
  final store = AppScope.read(context);
  final confirmed = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('Usunąć trening?'),
      content: Text(
        entry.isPlannedSession
            ? 'Cała sesja, ćwiczenia i serie zostaną usunięte z historii.'
            : 'Ten wpis treningowy zostanie usunięty z historii.',
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext, false),
          child: const Text('Anuluj'),
        ),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, true),
          child: const Text('Usuń'),
        ),
      ],
    ),
  );
  if (confirmed != true) return false;
  await store.deleteHistoryEntry(entry.key);
  return true;
}

class WorkoutHistoryDetailsPage extends StatefulWidget {
  const WorkoutHistoryDetailsPage({super.key, required this.entryKey});

  final String entryKey;

  @override
  State<WorkoutHistoryDetailsPage> createState() =>
      _WorkoutHistoryDetailsPageState();
}

class _WorkoutHistoryDetailsPageState extends State<WorkoutHistoryDetailsPage> {
  // Rozwinięte ćwiczenia (po id logu). Na starcie widać samą listę ćwiczeń;
  // wyjątek: trening z jednym ćwiczeniem otwiera się od razu rozwinięty.
  final Set<String> _expandedLogIds = {};
  bool _appliedInitialExpansion = false;

  void _applyInitialExpansion(_TrainerWorkoutHistoryEntry entry) {
    if (_appliedInitialExpansion) return;
    _appliedInitialExpansion = true;
    if (entry.logs.length == 1) _expandedLogIds.add(entry.logs.single.id);
  }

  void _toggleExercise(String logId) {
    setState(() {
      if (!_expandedLogIds.add(logId)) _expandedLogIds.remove(logId);
    });
  }

  void _setAllExpanded(_TrainerWorkoutHistoryEntry entry, bool expanded) {
    setState(() {
      _expandedLogIds.clear();
      if (expanded) _expandedLogIds.addAll(entry.logs.map((log) => log.id));
    });
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final entry = _findTrainerWorkoutHistoryEntry(store, widget.entryKey);
    if (entry == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Szczegóły treningu')),
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text('Ten trening nie jest już dostępny w historii.'),
          ),
        ),
      );
    }

    _applyInitialExpansion(entry);
    final stats = _TrainerWorkoutHistoryStats.fromLogs(entry.logs);
    final allExpanded =
        entry.logs.every((log) => _expandedLogIds.contains(log.id));
    return Scaffold(
      appBar: AppBar(
        title: const Text('Szczegóły treningu'),
        actions: [
          IconButton(
            tooltip: 'Usuń trening',
            onPressed: () async {
              final deleted = await _confirmAndDeleteTrainerWorkoutHistoryEntry(
                  context, entry);
              if (context.mounted && deleted) Navigator.of(context).pop();
            },
            icon: const Icon(Icons.delete_outline_rounded),
          ),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
        children: [
          _TrainerWorkoutHistoryDetailsHeader(entry: entry, stats: stats),
          const SizedBox(height: 12),
          if (entry.logs.length > 1)
            Align(
              alignment: Alignment.centerRight,
              child: TextButton.icon(
                key: const Key('history_toggle_all_exercises'),
                onPressed: () => _setAllExpanded(entry, !allExpanded),
                icon: Icon(
                    allExpanded
                        ? Icons.unfold_less_rounded
                        : Icons.unfold_more_rounded,
                    size: 18),
                label:
                    Text(allExpanded ? 'Zwiń wszystkie' : 'Rozwiń wszystkie'),
              ),
            ),
          for (final log in entry.logs) ...[
            _TrainerWorkoutExerciseHistoryCard(
              key: ValueKey('history_exercise_card_${log.id}'),
              log: log,
              expanded: _expandedLogIds.contains(log.id),
              onToggle: () => _toggleExercise(log.id),
            ),
            const SizedBox(height: 12),
          ],
        ],
      ),
    );
  }
}

