class _WorkoutHistoryEntry {
  const _WorkoutHistoryEntry(this.logs);

  final List<WorkoutLog> logs;

  DateTime get date => logs.first.date;
  bool get isPlannedSession => logs.first.sessionId.isNotEmpty;
}

List<_WorkoutHistoryEntry> _groupWorkoutHistory(List<WorkoutLog> sortedLogs) {
  final groups = <String, List<WorkoutLog>>{};
  for (final log in sortedLogs) {
    final key =
        log.sessionId.isEmpty ? 'log_${log.id}' : 'session_${log.sessionId}';
    groups.putIfAbsent(key, () => <WorkoutLog>[]).add(log);
  }
  return groups.values.map(_WorkoutHistoryEntry.new).toList();
}

class WorkoutHistorySessionCard extends StatelessWidget {
  const WorkoutHistorySessionCard({super.key, required this.logs});

  final List<WorkoutLog> logs;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final first = logs.first;
    final exerciseNames = logs
        .map((log) => log.exerciseFrom(store.customExercises).name)
        .toList();
    final setCount = logs.fold<int>(0, (sum, log) => sum + log.sets);
    final volume = logs.fold<double>(0, (sum, log) => sum + log.volume);
    final rpeSets = logs
        .expand((log) => log.workoutSets)
        .where((set) => set.rpe > 0)
        .toList();
    final averageRpe = rpeSets.isEmpty
        ? 0.0
        : rpeSets.fold<int>(0, (sum, set) => sum + set.rpe) / rpeSets.length;
    final duration = first.sessionStartedAt != null &&
            first.sessionEndedAt != null
        ? first.sessionEndedAt!.difference(first.sessionStartedAt!)
        : Duration(
            seconds: logs.fold<int>(0, (sum, log) => sum + log.durationSec));
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                CircleAvatar(
                  backgroundColor: theme.colorScheme.primaryContainer,
                  child: Icon(Icons.flag_rounded,
                      color: theme.colorScheme.primary),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                          first.sessionName.isEmpty
                              ? 'Trening z planu'
                              : first.sessionName,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.titleMedium
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 4),
                      Text(exerciseNames.join(' · '),
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant)),
                      if (first.sessionNote.isNotEmpty) ...[
                        const SizedBox(height: 6),
                        Text(first.sessionNote,
                            maxLines: 3, overflow: TextOverflow.ellipsis),
                      ],
                    ],
                  ),
                ),
                PopupMenuButton<String>(
                  onSelected: (value) async {
                    if (value != 'delete') return;
                    final confirmed = await showDialog<bool>(
                      context: context,
                      builder: (dialogContext) => AlertDialog(
                        title: const Text('Usunąć sesję?'),
                        content: const Text(
                            'Wszystkie ćwiczenia i serie tego treningu zostaną usunięte z historii.'),
                        actions: [
                          TextButton(
                              onPressed: () =>
                                  Navigator.pop(dialogContext, false),
                              child: const Text('Anuluj')),
                          FilledButton(
                              onPressed: () =>
                                  Navigator.pop(dialogContext, true),
                              child: const Text('Usuń')),
                        ],
                      ),
                    );
                    if (confirmed == true)
                      await store.deleteLogsBySession(first.sessionId);
                  },
                  itemBuilder: (_) => const [
                    PopupMenuItem(value: 'delete', child: Text('Usuń sesję')),
                  ],
                ),
              ],
            ),
            const SizedBox(height: 14),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                MiniTag(text: formatWorkoutDuration(duration)),
                MiniTag(text: '${logs.length} ćwiczeń'),
                MiniTag(text: '$setCount serii'),
                MiniTag(text: '${volume.round()} kg'),
                MiniTag(
                    text: averageRpe == 0
                        ? 'RPE —'
                        : 'RPE ${averageRpe.toStringAsFixed(1)}'),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

/// Pasek tygodnia (pn–nd) na ekranie Dzisiaj: dotknięcie przełącza dzień,
/// kropka pod datą pokazuje status treningu — pełna = trening odbyty,
/// obwódka = zaplanowany dzień treningowy bez zapisanego treningu.
/// JEDEN kafelek kalendarza na Dzisiaj — połączenie dawnego paska daty
/// (strzałki usunięte) i tygodnia z kropkami. Nagłówek pokazuje wybrany
/// dzień słownie; jego dotknięcie otwiera kalendarz miesiąca z zaznaczonymi
/// dniami treningów, a dotknięcie takiego dnia prowadzi do historii treningów.
class TrainingWeekCalendarCard extends StatelessWidget {
  const TrainingWeekCalendarCard({super.key});

  static const List<String> _dayLetters = <String>[
    'Pn',
    'Wt',
    'Śr',
    'Cz',
    'Pt',
    'So',
    'Nd',
  ];

  Future<void> _openCalendar(BuildContext context, AppStore store) async {
    final picked = await showDialog<DateTime>(
      context: context,
      builder: (_) => _TrainingCalendarDialog(
          store: store, initialMonth: store.selectedDate),
    );
    if (picked == null || !context.mounted) return;
    openDayIntensityPreview(context, picked);
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final Color accent = theme.colorScheme.primary;
    final DateTime today = DateTime.now();
    final DateTime selected = store.selectedDate;
    final DateTime base = DateTime(selected.year, selected.month, selected.day);
    final DateTime monday = base.subtract(Duration(days: base.weekday - 1));

    // Rozkład tygodnia widocznego w pasku — ten sam, co w podglądzie dnia.
    final schedule = store.trainingScheduleFor(from: monday, days: 7);

    Widget dayChip(int index) {
      final DateTime day = monday.add(Duration(days: index));
      final bool isSelected = sameDay(day, base);
      final bool isToday = sameDay(day, today);
      final bool trained = store.logsForDay(day).isNotEmpty;
      final ScheduledDay? planDay =
          index < schedule.length ? schedule[index] : null;
      final bool deload = planDay?.isDeload ?? store.isDeloadDate(day);
      final bool rest = planDay?.isRest ?? false;
      // Dzień deloadu przejmuje kolor bursztynowy (spójnie z kalendarzem).
      final Color chipAccent = deload ? kDeloadColor : accent;
      final Color chipText = isSelected
          ? theme.colorScheme.onPrimary
          : theme.colorScheme.onSurface;
      return Expanded(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 2),
          child: InkWell(
            borderRadius: BorderRadius.circular(12),
            onTap: () => store.setSelectedDate(day),
            child: Container(
              padding: const EdgeInsets.symmetric(vertical: 6),
              decoration: BoxDecoration(
                color: isSelected
                    ? chipAccent
                    : (deload
                        ? kDeloadColor.withValues(alpha: 0.16)
                        : Colors.transparent),
                borderRadius: BorderRadius.circular(12),
                border: Border.all(
                  color: isSelected
                      ? chipAccent
                      : (deload
                          ? kDeloadColor.withValues(alpha: 0.6)
                          : (isToday
                              ? accent.withValues(alpha: 0.55)
                              : Colors.transparent)),
                  width: (isToday || deload) && !isSelected ? 1.4 : 1,
                ),
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    _dayLetters[index],
                    style: TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w800,
                      color: chipText.withValues(alpha: 0.75),
                    ),
                  ),
                  const SizedBox(height: 2),
                  Icon(
                    deload
                        ? Icons.self_improvement_rounded
                        : (rest
                            ? Icons.bedtime_outlined
                            : _scheduleAreaIcon(planDay?.area)),
                    size: 15,
                    color: isSelected ? chipText : chipAccent,
                  ),
                  const SizedBox(height: 2),
                  Text(
                    rest ? 'wolne' : _shortAreaLabel(planDay?.area),
                    maxLines: 1,
                    overflow: TextOverflow.clip,
                    softWrap: false,
                    style: TextStyle(
                      fontSize: 8,
                      height: 1.1,
                      // Zrobiony trening pogrubiamy — zastępuje dawną kropkę.
                      fontWeight: trained ? FontWeight.w900 : FontWeight.w600,
                      color: isSelected
                          ? chipText
                          : theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                  // Drugi zestaw dnia (tor drugorzędny) — mniejszą czcionką,
                  // żeby było widać, że dzień ma dwie partie.
                  if (!rest && planDay?.secondaryArea != null)
                    Text(
                      _secondaryChipLabel(planDay?.secondaryArea),
                      maxLines: 1,
                      overflow: TextOverflow.clip,
                      softWrap: false,
                      style: TextStyle(
                        fontSize: 7,
                        height: 1.1,
                        fontWeight: FontWeight.w600,
                        color: (isSelected ? chipText : chipAccent)
                            .withValues(alpha: 0.85),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      );
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(6, 4, 6, 8),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            InkWell(
              key: const Key('training_calendar_header'),
              borderRadius: BorderRadius.circular(14),
              onTap: () => _openCalendar(context, store),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(10, 8, 6, 8),
                child: Row(
                  children: [
                    Icon(Icons.calendar_month_rounded, color: accent, size: 20),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            weekdayName(base.weekday),
                            style: theme.textTheme.titleMedium
                                ?.copyWith(fontWeight: FontWeight.w900),
                          ),
                          Text(
                            trainerHistoryFullDate(base),
                            style: theme.textTheme.bodySmall?.copyWith(
                                color: theme.colorScheme.onSurfaceVariant),
                          ),
                        ],
                      ),
                    ),
                    if (!sameDay(base, today))
                      TextButton(
                        onPressed: () => store.setSelectedDate(DateTime.now()),
                        child: const Text('Dziś'),
                      ),
                    Icon(Icons.expand_more_rounded,
                        color: theme.colorScheme.onSurfaceVariant, size: 20),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 2),
            Row(
              children: [for (int i = 0; i < 7; i++) dayChip(i)],
            ),
          ],
        ),
      ),
    );
  }
}

/// Kalendarz miesiąca z zaznaczonymi dniami treningów. Dotknięcie dnia
