class _TrainingCalendarDialogState extends State<_TrainingCalendarDialog> {
  static const List<String> _monthNames = [
    'Styczeń',
    'Luty',
    'Marzec',
    'Kwiecień',
    'Maj',
    'Czerwiec',
    'Lipiec',
    'Sierpień',
    'Wrzesień',
    'Październik',
    'Listopad',
    'Grudzień',
  ];
  static const List<String> _dayLetters = [
    'Pn',
    'Wt',
    'Śr',
    'Cz',
    'Pt',
    'So',
    'Nd'
  ];

  late DateTime _month;

  @override
  void initState() {
    super.initState();
    _month = DateTime(widget.initialMonth.year, widget.initialMonth.month);
  }

  void _shiftMonth(int delta) {
    setState(() => _month = DateTime(_month.year, _month.month + delta));
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final accent = theme.colorScheme.primary;
    final today = DateTime.now();

    // Dni bieżącego miesiąca z zapisanym treningiem.
    final trainedDays = <int>{};
    for (final log in widget.store.logs) {
      if (log.date.year == _month.year && log.date.month == _month.month) {
        trainedDays.add(log.date.day);
      }
    }

    final daysInMonth = DateTime(_month.year, _month.month + 1, 0).day;
    final leadingBlanks = _month.weekday - 1; // poniedziałek = pierwsza kolumna

    Widget dayCell(int day) {
      final date = DateTime(_month.year, _month.month, day);
      final trained = trainedDays.contains(day);
      final isToday = sameDay(date, today);
      final deload = widget.store.isDeloadDate(date);
      final projected = widget.store.projectedProgramDayForDate(date);
      final programDay = projected == null ? null : projected.index + 1;
      // Trening ma pierwszeństwo (dotknięcie → historia). Dzień deloadu bez
      // treningu koloruje się na bursztynowo i pokazuje opis odciążenia.
      final fill = trained
          ? accent
          : (deload
              ? kDeloadColor.withValues(alpha: 0.85)
              : Colors.transparent);
      final onFill = trained || (deload && !trained);
      return InkWell(
        // Każdy dzień jest klikalny — podgląd pokazuje fazę cyklu, intensywność
        // i zestaw, także dla dat w przeszłości i w przyszłości.
        key: trained
            ? Key('calendar_trained_day_$day')
            : (deload
                ? Key('calendar_deload_day_$day')
                : Key('calendar_day_$day')),
        customBorder: const CircleBorder(),
        onTap: () => Navigator.of(context).pop(date),
        child: Container(
          margin: const EdgeInsets.all(3),
          decoration: BoxDecoration(
            shape: BoxShape.circle,
            color: fill,
            border: trained && deload
                ? Border.all(color: kDeloadColor, width: 1.6)
                : (isToday && !trained && !deload
                    ? Border.all(
                        color: accent.withValues(alpha: 0.7), width: 1.4)
                    : null),
          ),
          alignment: Alignment.center,
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                '$day',
                style: theme.textTheme.bodySmall?.copyWith(
                  fontWeight: FontWeight.w800,
                  color: onFill
                      ? theme.colorScheme.onPrimary
                      : isToday
                          ? accent
                          : theme.colorScheme.onSurfaceVariant,
                ),
              ),
              // Który dzień programu wypada tego dnia (rzutowanie po dniach
              // treningowych) — widać rytm programu bez wchodzenia w szczegóły.
              if (programDay != null)
                Text(
                  '$programDay',
                  style: TextStyle(
                    fontSize: 8,
                    height: 1.1,
                    fontWeight: FontWeight.w700,
                    color: (onFill
                            ? theme.colorScheme.onPrimary
                            : theme.colorScheme.onSurfaceVariant)
                        .withValues(alpha: 0.85),
                  ),
                ),
            ],
          ),
        ),
      );
    }

    return AlertDialog(
      contentPadding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
      content: SizedBox(
        width: 330,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                IconButton(
                  key: const Key('calendar_prev_month'),
                  tooltip: 'Poprzedni miesiąc',
                  onPressed: () => _shiftMonth(-1),
                  icon: const Icon(Icons.chevron_left_rounded),
                ),
                Expanded(
                  child: Text(
                    '${_monthNames[_month.month - 1]} ${_month.year}',
                    textAlign: TextAlign.center,
                    style: theme.textTheme.titleMedium
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
                IconButton(
                  key: const Key('calendar_next_month'),
                  tooltip: 'Następny miesiąc',
                  onPressed: () => _shiftMonth(1),
                  icon: const Icon(Icons.chevron_right_rounded),
                ),
              ],
            ),
            const SizedBox(height: 4),
            Row(
              children: [
                for (final letter in _dayLetters)
                  Expanded(
                    child: Text(
                      letter,
                      textAlign: TextAlign.center,
                      style: theme.textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.w800,
                        color: theme.colorScheme.onSurfaceVariant,
                      ),
                    ),
                  ),
              ],
            ),
            const SizedBox(height: 4),
            GridView.count(
              crossAxisCount: 7,
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              children: [
                for (var blank = 0; blank < leadingBlanks; blank++)
                  const SizedBox.shrink(),
                for (var day = 1; day <= daysInMonth; day++) dayCell(day),
              ],
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Container(
                  width: 10,
                  height: 10,
                  decoration:
                      BoxDecoration(shape: BoxShape.circle, color: accent),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Dzień z treningiem',
                    style: theme.textTheme.labelSmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Row(
              children: [
                Container(
                  width: 10,
                  height: 10,
                  decoration: const BoxDecoration(
                      shape: BoxShape.circle, color: kDeloadColor),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Deload (odciążenie)',
                    style: theme.textTheme.labelSmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(
              'Mała cyfra pod datą = który dzień programu wtedy wypada. '
              'Dotknij dowolny dzień — zobaczysz fazę cyklu, intensywność '
              'i zestaw na ten dzień.',
              style: theme.textTheme.labelSmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: const Text('Zamknij'),
        ),
      ],
    );
  }
}

/// Kolor okresu deloadu w kalendarzu i na czołówce — mocny bursztyn, żeby dni
/// odciążenia wyraźnie odróżniały się od zwykłych dni (akcent motywu).
const Color kDeloadColor = Color(0xFFF5A623);

/// Pokazuje opis deloadu dla wskazanego dnia (co to jest, kiedy trwa, który to
/// dzień okna). Wywoływane po dotknięciu dnia deloadu w kalendarzu albo banera.
Future<void> showDeloadInfoDialog(BuildContext context, DateTime date) async {
  final store = AppScope.of(context);
  final status = store.deloadStatusOn(date);
  final start = status.windowStart;
  final end = status.windowEnd;
  await showDialog<void>(
    context: context,
    builder: (ctx) {
      final theme = Theme.of(ctx);
      return AlertDialog(
        icon: const Icon(Icons.self_improvement_rounded,
            color: kDeloadColor, size: 30),
        title: const Text('Deload — tydzień odciążenia'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (start != null && end != null)
              Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: kDeloadColor.withValues(alpha: 0.14),
                  borderRadius: BorderRadius.circular(9),
                ),
                child: Text(
                  '${trainerHistoryFullDate(start)} – ${trainerHistoryFullDate(end)}',
                  style: theme.textTheme.labelLarge?.copyWith(
                      fontWeight: FontWeight.w800, color: kDeloadColor),
                ),
              ),
            const SizedBox(height: 12),
            Text(
              'W tym okresie schodzimy z objętości i intensywności: mniej serii, '
              'lżejszy ciężar, dłuższe przerwy i więcej mobilności. To zaplanowany '
              'odpoczynek, dzięki któremu mięśnie się regenerują — po deloadzie '
              'wracasz mocniej, a intensywność stopniowo znów opada aż do kolejnego '
              'odciążenia.',
              style: theme.textTheme.bodyMedium,
            ),
            const SizedBox(height: 10),
            if (status.isDeload)
              Text(
                'Dziś to dzień ${status.deloadDayNumber} z ${status.deloadTotalDays} deloadu.',
                style: theme.textTheme.bodyMedium
                    ?.copyWith(fontWeight: FontWeight.w700),
              )
            else if (status.isTraining)
              Text(
                'Do tego deloadu: ${status.daysUntilDeload} dni.',
                style: theme.textTheme.bodyMedium
                    ?.copyWith(fontWeight: FontWeight.w700),
              ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () {
              Navigator.of(ctx).pop();
              openTrainerSubPage(context, const DeloadSettingsPage(),
                  title: 'Deload');
            },
            child: const Text('Ustawienia'),
          ),
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(),
            child: const Text('Rozumiem'),
          ),
        ],
      );
    },
  );
}

/// Poziom aktywnego programu vs profil — ZAWSZE dostępna akcja przeliczenia.
///
/// Stary błąd normalizacji sprowadzał ORAZ profil, ORAZ zapisany plan do
/// „Zaawansowany", więc sam rozjazd niczego by nie wykrył (obie wartości są
/// zgodne, tylko obie mogą być złe). Dlatego przy rozjeździe pokazujemy
/// ostrzeżenie, a gdy wszystko się zgadza — kompaktowy wiersz z przyciskiem
/// „Przelicz", żeby dało się wymusić odbudowę po poprawieniu poziomu w profilu.
class ProgramLevelCard extends StatelessWidget {
  const ProgramLevelCard({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final plan = store.activeWorkoutPlan;
    // Tylko programy z katalogu da się przeliczyć na poziom — plany własne nie.
    if (plan == null || catalogProgramIdForPlan(plan.id) == null) {
      return const SizedBox.shrink();
    }
    final profileLevel = normalizeTrainingLevel(store.settings.level);
    final planLevel = plan.level.trim().isEmpty
        ? profileLevel
        : normalizeTrainingLevel(plan.level);
    final mismatch = planLevel != profileLevel;

    Future<void> repair() async {
      final ok = await repairActivePlanLevel(context);
      if (ok && context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text('Program przeliczony na poziom „$profileLevel".')),
        );
      }
    }

    if (!mismatch) {
      return Padding(
        padding: const EdgeInsets.only(bottom: 12),
        child: Row(
          key: const Key('plan_level_ok'),
          children: [
            Icon(Icons.school_outlined,
                size: 16, color: scheme.onSurfaceVariant),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                'Poziom programu: $planLevel (zgodny z profilem)',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: scheme.onSurfaceVariant),
              ),
            ),
            TextButton(
              key: const Key('plan_level_repair'),
              onPressed: repair,
              child: const Text('Przelicz'),
            ),
          ],
        ),
      );
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Container(
        key: const Key('plan_level_mismatch'),
        padding: const EdgeInsets.fromLTRB(14, 12, 12, 12),
        decoration: BoxDecoration(
          color: scheme.errorContainer.withValues(alpha: 0.35),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: scheme.error.withValues(alpha: 0.5)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.warning_amber_rounded, color: scheme.error),
                const SizedBox(width: 10),
                Expanded(
                  child: Text('Poziom programu nie zgadza się z profilem',
                      style: theme.textTheme.titleSmall
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(
              'Program jest zbudowany na poziom „$planLevel", a Twój profil to '
              '„$profileLevel". To pozostałość po naprawionym błędzie rozpoznawania '
              'poziomu — sprawdź poziom w profilu i przelicz program. Ukończone dni '
              'zostaną zachowane.',
              style: theme.textTheme.bodySmall,
            ),
            const SizedBox(height: 10),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                FilledButton.icon(
                  key: const Key('plan_level_repair'),
                  onPressed: repair,
                  icon: const Icon(Icons.refresh_rounded, size: 18),
                  label: const Text('Przelicz program'),
                ),
                TextButton(
                  onPressed: () => openTrainerSubPage(
                      context, const TrainingProfilePage(),
                      title: 'Profil treningowy'),
                  child: const Text('Sprawdź profil'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

/// Czołówka „Trening": informuje o TRWAJĄCYM albo ZBLIŻAJĄCYM się deloadzie,
/// a przy sygnałach zmęczenia proponuje wcześniejsze odciążenie (adaptacyjnie).
/// Gdy nie ma nic do pokazania — nie zajmuje miejsca.
class DeloadHeadlineBanner extends StatelessWidget {
  const DeloadHeadlineBanner({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final cycle = store.deloadCycle;
    if (!cycle.isConfigured) return const SizedBox.shrink();

    final status = store.deloadStatusToday;
    final earlyRec = store.deloadRecommendedEarly;
    final upcomingSoon = status.isTraining && status.daysUntilDeload <= 10;
    if (!status.isDeload && !upcomingSoon && !earlyRec) {
      return const SizedBox.shrink();
    }

    final theme = Theme.of(context);
    final IconData icon;
    final String title;
    final String subtitle;
    if (status.isDeload) {
      icon = Icons.self_improvement_rounded;
      title =
          'Trwa deload — dzień ${status.deloadDayNumber}/${status.deloadTotalDays}';
      subtitle =
          'Lżejszy tydzień: mniej serii, lżejszy ciężar, więcej mobilności. Odpuść ciężary i daj mięśniom odpocząć.';
    } else if (earlyRec) {
      icon = Icons.warning_amber_rounded;
      title = 'Zmęczenie rośnie — rozważ wcześniejszy deload';
      subtitle =
          'Sygnały z ostatnich dni sugerują odciążenie przed planowanym terminem (za ${status.daysUntilDeload} dni).';
    } else {
      icon = Icons.event_available_rounded;
      final start = status.windowStart;
      title = status.daysUntilDeload <= 1
          ? 'Deload już jutro'
          : 'Zbliża się deload — za ${status.daysUntilDeload} dni';
      subtitle = start == null
          ? 'Przygotuj się na lżejszy tydzień odciążenia.'
          : 'Od ${trainerHistoryFullDate(start)}. Przygotuj się na lżejszy tydzień odciążenia.';
    }

    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          key: const Key('deload_headline_banner'),
          borderRadius: BorderRadius.circular(16),
          onTap: () => showDeloadInfoDialog(context, DateTime.now()),
          child: Container(
            padding: const EdgeInsets.fromLTRB(14, 12, 12, 12),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(16),
              gradient: LinearGradient(
                colors: [
                  kDeloadColor.withValues(alpha: 0.20),
                  kDeloadColor.withValues(alpha: 0.08),
                ],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              ),
              border: Border.all(color: kDeloadColor.withValues(alpha: 0.55)),
            ),
            child: Row(
              children: [
                Container(
                  padding: const EdgeInsets.all(9),
                  decoration: BoxDecoration(
                    color: kDeloadColor.withValues(alpha: 0.20),
                    shape: BoxShape.circle,
                  ),
                  child: Icon(icon, color: kDeloadColor, size: 22),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(title,
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 2),
                      Text(subtitle,
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant)),
                      if (earlyRec && !status.isDeload) ...[
                        const SizedBox(height: 8),
                        Align(
                          alignment: Alignment.centerLeft,
                          child: FilledButton.tonalIcon(
                            key: const Key('deload_start_now'),
                            style: FilledButton.styleFrom(
                              backgroundColor:
                                  kDeloadColor.withValues(alpha: 0.22),
                              foregroundColor: kDeloadColor,
                              visualDensity: VisualDensity.compact,
                            ),
                            onPressed: () async {
                              await store.startDeloadNow();
                              if (context.mounted) {
                                ScaffoldMessenger.of(context).showSnackBar(
                                  const SnackBar(
                                      content: Text(
                                          'Deload rozpoczęty — od dziś lżejszy tydzień.')),
                                );
                              }
                            },
                            icon:
                                const Icon(Icons.play_arrow_rounded, size: 18),
                            label: const Text('Zacznij deload teraz'),
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
                Icon(Icons.chevron_right_rounded,
                    color: kDeloadColor.withValues(alpha: 0.7)),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

/// Otwiera podgląd dowolnego dnia (przeszłego lub przyszłego).
void openDayIntensityPreview(BuildContext context, DateTime date) {
  openTrainerSubPage(context, DayIntensityPreviewPage(date: date),
      title: 'Podgląd dnia');
}

/// Podgląd DOWOLNEJ daty: w jakiej fazie cyklu wypada (deload / ile dni po
/// deloadzie / ile do kolejnego), jak intensywny jest wtedy trening i jak
/// wygląda zestaw przeliczony na tę intensywność.
class DayIntensityPreviewPage extends StatelessWidget {
  const DayIntensityPreviewPage({super.key, required this.date});

  final DateTime date;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final day = DateTime(date.year, date.month, date.day);
    final status = store.deloadStatusOn(day);
    final projected = store.projectedProgramDayForDate(day);
    final logs = store.logsForDay(day);
    // Plan bierze się z ROZKŁADU na ten dzień (partia główna), a nie z ostatnio
    // otwartego zestawu — inaczej podgląd dowolnej daty pokazywał ten sam
    // program przez trzy tygodnie w przód.
    final dayPlan = store.trainingScheduleConfig.planForWeekday(day.weekday);
    final plan = store.scheduledPlanForArea(dayPlan.primary);
    final factor = status.isActive ? status.intensityFactor : 1.0;
    final percent = (factor * 100).round();
    final isPast =
        day.isBefore(DateTime.now()) && !sameDay(day, DateTime.now());

    // Faza cyklu w tym dniu.
    final String phaseTitle;
    final String phaseText;
    final IconData phaseIcon;
    if (status.isDeload) {
      phaseIcon = Icons.self_improvement_rounded;
      phaseTitle =
          'Deload — dzień ${status.deloadDayNumber}/${status.deloadTotalDays}';
      phaseText =
          'Tydzień odciążenia: mniej serii, lżejszy ciężar i dłuższe przerwy, '
          'żeby mięśnie odpoczęły.';
    } else if (status.isTraining) {
      phaseIcon = Icons.trending_up_rounded;
      phaseTitle = status.daysAfterDeload > 0 && status.daysAfterDeload <= 21
          ? '${status.daysAfterDeload}. dzień po deloadzie'
          : 'Blok treningowy';
      final until = status.daysUntilDeload;
      phaseText = 'Do kolejnego deloadu: $until ${until == 1 ? 'dzień' : 'dni'}'
          '${status.windowStart != null ? ' (od ${trainerHistoryFullDate(status.windowStart!)})' : ''}.';
    } else {
      phaseIcon = Icons.event_busy_rounded;
      phaseTitle = 'Deload wyłączony';
      phaseText = 'Włącz cykliczny deload, aby zobaczyć fazy i intensywność.';
    }

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),
      children: [
        // Data
        Text(weekdayName(day.weekday),
            style: theme.textTheme.titleLarge
                ?.copyWith(fontWeight: FontWeight.w900)),
        Text(trainerHistoryFullDate(day),
            style: theme.textTheme.bodyMedium
                ?.copyWith(color: scheme.onSurfaceVariant)),
        const SizedBox(height: 6),
        // Co wypada tego dnia wg rozkładu — oba tory naraz.
        Row(
          children: [
            Icon(_scheduleAreaIcon(dayPlan.primary),
                size: 15,
                color:
                    dayPlan.isRest ? scheme.onSurfaceVariant : scheme.primary),
            const SizedBox(width: 6),
            Expanded(
              child: Text(
                dayPlan.label,
                key: const Key('preview_day_plan'),
                style: theme.textTheme.bodyMedium?.copyWith(
                    fontWeight: FontWeight.w800,
                    color: dayPlan.isRest
                        ? scheme.onSurfaceVariant
                        : scheme.primary),
              ),
            ),
          ],
        ),
        const SizedBox(height: 6),
        // Wyjaśnienie rozkładu żyje TU, przy konkretnym dniu — nie zajmuje
        // miejsca na czołówce „Treningu".
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(Icons.info_outline_rounded,
                size: 14, color: scheme.onSurfaceVariant),
            const SizedBox(width: 6),
            Expanded(
              child: Text(
                'Rozkład tygodnia jest stały — ten sam układ wraca co tydzień. '
                'Dzień bywa przestawiony, gdy partia jeszcze się regeneruje.',
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: scheme.onSurfaceVariant, height: 1.3),
              ),
            ),
          ],
        ),
        const SizedBox(height: 12),

        // Faza cyklu
        Card(
          color: status.isDeload ? kDeloadColor.withValues(alpha: 0.12) : null,
          child: Padding(
            padding: const EdgeInsets.all(14),
            child: Row(
              children: [
                Icon(phaseIcon,
                    color: status.isDeload ? kDeloadColor : scheme.primary),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(phaseTitle,
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 2),
                      Text(phaseText, style: theme.textTheme.bodySmall),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
        const SizedBox(height: 12),

        // Intensywność
        if (status.isActive)
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                        child: Text('Intensywność treningu',
                            style: theme.textTheme.titleSmall
                                ?.copyWith(fontWeight: FontWeight.w900)),
                      ),
                      Text('$percent%',
                          key: const Key('preview_intensity_percent'),
                          style: theme.textTheme.titleMedium?.copyWith(
                              fontWeight: FontWeight.w900,
