/// Historia mezocykli: objętość i średnie RPE tydzień po tygodniu, z wyróżnionymi
/// tygodniami deloadu — widać, czy odciążenie faktycznie ścięło obciążenie.
class MesocycleHistoryCard extends StatelessWidget {
  const MesocycleHistoryCard({super.key, this.weeks = 10});

  final int weeks;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final currentWeekStart = startOfTrainingWeek(DateTime.now());

    final rows = <({DateTime start, double volume, double rpe, bool deload})>[];
    for (var i = weeks - 1; i >= 0; i--) {
      final start = currentWeekStart.subtract(Duration(days: i * 7));
      final end = start.add(const Duration(days: 6));
      final logs = store.logsBetween(start, end);
      final rpeValues = [
        for (final log in logs)
          if (log.rpe > 0) log.rpe.toDouble(),
      ];
      rows.add((
        start: start,
        volume: DayTotals.from(logs).volume,
        rpe: rpeValues.isEmpty
            ? 0
            : rpeValues.reduce((a, b) => a + b) / rpeValues.length,
        deload: List.generate(7, (d) => start.add(Duration(days: d)))
            .any(store.isDeloadDate),
      ));
    }
    final maxVolume =
        rows.fold<double>(0, (m, r) => r.volume > m ? r.volume : m);
    if (maxVolume <= 0) return const SizedBox.shrink();

    return Card(
      key: const Key('mesocycle_history'),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.calendar_view_week_rounded, color: scheme.primary),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Historia mezocykli',
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      Text(
                          'Objętość tygodniowa; tygodnie deloadu na bursztynowo',
                          style: theme.textTheme.bodySmall
                              ?.copyWith(color: scheme.onSurfaceVariant)),
                    ],
                  ),
                ),
              ],
            ),
            const SizedBox(height: 14),
            SizedBox(
              height: 100,
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  for (final row in rows)
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 2),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.end,
                          children: [
                            // Etykiety NIE mogą się zawijać — przy 10 kolumnach
                            // na wąskim ekranie druga linia rozpycha kolumnę.
                            Text(
                              row.rpe > 0 ? row.rpe.toStringAsFixed(1) : '',
                              maxLines: 1,
                              overflow: TextOverflow.clip,
                              softWrap: false,
                              style: TextStyle(
                                  fontSize: 8,
                                  fontWeight: FontWeight.w700,
                                  color: scheme.onSurfaceVariant),
                            ),
                            const SizedBox(height: 2),
                            Container(
                              height: (row.volume / maxVolume * 50)
                                  .clamp(3.0, 50.0),
                              decoration: BoxDecoration(
                                color:
                                    row.deload ? kDeloadColor : scheme.primary,
                                borderRadius: BorderRadius.circular(4),
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              '${row.start.day}.${row.start.month}',
                              maxLines: 1,
                              overflow: TextOverflow.clip,
                              softWrap: false,
                              style: TextStyle(
                                  fontSize: 8,
                                  color: scheme.onSurfaceVariant,
                                  fontWeight: row.deload
                                      ? FontWeight.w900
                                      : FontWeight.w600),
                            ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ),
            const SizedBox(height: 6),
            Text('Liczba nad słupkiem = średnie RPE tygodnia.',
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: scheme.onSurfaceVariant)),
          ],
        ),
      ),
    );
  }
}

/// Ustawienia rotacji: co wypada w który dzień tygodnia.
///
/// Edytujemy per DZIEŃ TYGODNIA (pn–nd), bo tak myśli użytkownik
/// („poniedziałek to nogi"), w DWÓCH KOLUMNACH:
///  - PIERWSZORZĘDNA — duża partia, która niesie dzień (klatka, plecy, nogi,
///    brzuch) albo „Dzień wolny",
///  - DRUGORZĘDNA — dodatek doklejany do dnia (barki, ramiona, przedramiona,
///    bieg), dzięki czemu każda partia mieści się w tygodniu dwa razy bez
///    dokładania kolejnych dni treningowych.
class TrainingRotationPage extends StatelessWidget {
  const TrainingRotationPage({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final config = store.trainingScheduleConfig;
    final weekPlan = config.weekPlan;

    Future<void> savePrimary(int weekday, TrainingFocusArea? area) {
      final current = weekPlan[weekday] ?? TrainingDayPlan.rest;
      return store.setWeekdayPlan(
        weekday,
        area == null
            // „Dzień wolny" zeruje CAŁY dzień — dodatek bez partii głównej
            // byłby treningiem-widmem w rozkładzie.
            ? TrainingDayPlan.rest
            : current.copyWith(primary: area),
      );
    }

    Future<void> saveSecondary(int weekday, TrainingFocusArea? area) {
      final current = weekPlan[weekday] ?? TrainingDayPlan.rest;
      if (current.isRest) return Future<void>.value();
      return store.setWeekdayPlan(
        weekday,
        area == null
            ? current.copyWith(clearSecondary: true)
            : current.copyWith(secondary: area),
      );
    }

    Widget dayRow(int weekday) {
      final plan = weekPlan[weekday] ?? TrainingDayPlan.rest;
      final isRest = plan.isRest;
      // Dropdown wymaga, żeby bieżąca wartość występowała na jego liście.
      // Starsze plany mogły mieć obszary zapisane w przeciwnej kolumnie.
      final selectedPrimary =
          kPrimaryFocusAreas.contains(plan.primary) ? plan.primary : null;
      final selectedSecondary =
          kSecondaryFocusAreas.contains(plan.secondary) ? plan.secondary : null;
      return Padding(
        padding: const EdgeInsets.only(bottom: 10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(weekdayName(weekday),
                style: theme.textTheme.labelLarge?.copyWith(
                    fontWeight: FontWeight.w900,
                    color:
                        isRest ? scheme.onSurfaceVariant : scheme.onSurface)),
            const SizedBox(height: 4),
            Row(
              children: [
                Expanded(
                  child: DropdownButtonFormField<TrainingFocusArea?>(
                    key: Key('rotation_day_$weekday'),
                    initialValue: selectedPrimary,
                    isExpanded: true,
                    decoration: const InputDecoration(
                      isDense: true,
                      contentPadding:
                          EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                      border: OutlineInputBorder(),
                    ),
                    items: [
                      const DropdownMenuItem<TrainingFocusArea?>(
                        value: null,
                        child: Text('Dzień wolny',
                            overflow: TextOverflow.ellipsis),
                      ),
                      for (final area in kPrimaryFocusAreas)
                        DropdownMenuItem<TrainingFocusArea?>(
                            value: area,
                            child: Text(area.label,
                                overflow: TextOverflow.ellipsis)),
                    ],
                    onChanged: (area) => savePrimary(weekday, area),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: DropdownButtonFormField<TrainingFocusArea?>(
                    key: Key('rotation_second_$weekday'),
                    initialValue: selectedSecondary,
                    isExpanded: true,
                    decoration: InputDecoration(
                      isDense: true,
                      enabled: !isRest,
                      contentPadding: const EdgeInsets.symmetric(
                          horizontal: 10, vertical: 8),
                      border: const OutlineInputBorder(),
                    ),
                    items: [
                      const DropdownMenuItem<TrainingFocusArea?>(
                        value: null,
                        child: Text('Bez dodatku',
                            overflow: TextOverflow.ellipsis),
                      ),
                      for (final area in kSecondaryFocusAreas)
                        DropdownMenuItem<TrainingFocusArea?>(
                            value: area,
                            child: Text(area.label,
                                overflow: TextOverflow.ellipsis)),
                    ],
                    onChanged:
                        isRest ? null : (area) => saveSecondary(weekday, area),
                  ),
                ),
              ],
            ),
          ],
        ),
      );
    }

    // Ile razy w tygodniu wypada każda duża partia — cel to dwa razy.
    final coverage = <TrainingFocusArea, int>{
      for (final area in kPrimaryFocusAreas) area: config.occurrencesOf(area),
    };
    final trainingDays = config.activeWeekdays.length;

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),
      children: [
        Card(
          color: scheme.primaryContainer.withValues(alpha: 0.4),
          child: const ListTile(
            leading: Icon(Icons.repeat_rounded),
            title: Text('Stały rozkład tygodnia'),
            subtitle: Text(
                'Ustal, co wypada w który dzień. Kolumna po lewej to partia '
                'główna (klatka, plecy, nogi, brzuch) albo dzień wolny, po '
                'prawej dodatek dnia (barki, ramiona, przedramiona, bieg). '
                'Rozkład jest ten sam co tydzień — także za miesiąc i po '
                'deloadzie; regeneracja może go doraźnie przestawić.'),
          ),
        ),
        const SizedBox(height: 12),
        Row(
          children: [
            Expanded(
              child: Text('PIERWSZORZĘDNE',
                  style: theme.textTheme.labelSmall?.copyWith(
                      fontWeight: FontWeight.w900,
                      letterSpacing: 0.4,
                      color: scheme.primary)),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Text('DRUGORZĘDNE',
                  style: theme.textTheme.labelSmall?.copyWith(
                      fontWeight: FontWeight.w900,
                      letterSpacing: 0.4,
                      color: scheme.tertiary)),
            ),
          ],
        ),
        const SizedBox(height: 8),
        for (var weekday = 1; weekday <= 7; weekday++) dayRow(weekday),
        const SizedBox(height: 6),
        Card(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(14, 12, 14, 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                    'Pokrycie tygodnia · $trainingDays '
                    '${trainingDays == 1 ? 'dzień' : 'dni'} treningowych',
                    style: theme.textTheme.titleSmall
                        ?.copyWith(fontWeight: FontWeight.w900)),
                const SizedBox(height: 8),
                Wrap(
