// ── Pomocnicze planera ──────────────────────────────────────────────────────

/// Ciężar bez zbędnego „.0" (25 kg zamiast 25.0 kg).
String _plannerKg(double value) {
  final rounded = (value * 10).roundToDouble() / 10;
  return rounded == rounded.roundToDouble()
      ? rounded.round().toString()
      : rounded.toStringAsFixed(1);
}

/// Kolor odznaki obciążenia tygodnia.
Color _plannerLoadColor(TrainingLoadLevel level, ColorScheme scheme) {
  switch (level) {
    case TrainingLoadLevel.low:
      return scheme.tertiary;
    case TrainingLoadLevel.optimal:
      return scheme.primary;
    case TrainingLoadLevel.high:
      return kDeloadColor;
    case TrainingLoadLevel.overload:
      return scheme.error;
  }
}

/// Otwiera analizę przed treningiem (opcjonalnie wariant z symulacji).
Future<void> openPreWorkoutAnalysis(BuildContext context,
    {PlannedWorkout? planned}) async {
  await Navigator.of(context).push(MaterialPageRoute<void>(
    builder: (_) => PreWorkoutAnalysisPage(preview: planned),
  ));
}

/// Startuje trening zaproponowany przez planer. Gdy propozycja wskazuje dzień
/// programu — startujemy właśnie ten dzień; w przeciwnym razie budujemy
/// jednorazowy dzień z zaproponowanych ćwiczeń.
Future<void> startPlannedWorkout(
    BuildContext context, PlannedWorkout planned) async {
  final store = AppScope.read(context);
  if (planned.exercises.isEmpty) {
    showError(context, 'Planer nie ma dziś czego zaproponować.');
    return;
  }

  final programId = planned.programId;
  final dayIndex = planned.dayIndex;
  if (programId != null && dayIndex != null) {
    for (final plan in store.plans) {
      if (plan.id != programId) continue;
      if (dayIndex < 0 || dayIndex >= plan.days.length) break;
      await startWorkoutForDay(context,
          plan: plan,
          day: store.presentedDay(plan, plan.days[dayIndex]),
          dayIndex: dayIndex);
      return;
    }
  }

  final day = WorkoutDay(
    weekday: DateTime.now().weekday,
    title: planned.title,
    items: [
      for (final exercise in planned.exercises)
        PlanItem(
          exerciseId: exercise.exerciseId,
          sets: exercise.sets,
          reps: exercise.reps,
          durationSec: exercise.durationSec,
          note: exercise.loadTypeLabel,
          suggestedWeightKg: exercise.weightKg,
          restSeconds: exercise.restSeconds,
        ),
    ],
  );
  final plan = WorkoutPlan(
    id: 'planner_${DateTime.now().millisecondsSinceEpoch}',
    name: 'Propozycja planera',
    note: planned.subtitle,
    allowAnyDay: true,
    days: [day],
  );
  await startWorkoutForDay(context, plan: plan, day: day);
}

