/// Ikona i kolor typu dnia planera (siła / cardio / lżejszy / wolny) —
/// wspólne dla mini paska tygodnia i pełnego ekranu planu.
IconData _plannerDayIcon(WeeklyDaySuggestion day) {
  if (day.isRest) return Icons.hotel_rounded;
  if (day.isLight) return Icons.self_improvement_rounded;
  if (day.isCardio) return Icons.directions_run_rounded;
  return Icons.fitness_center_rounded;
}

Color _plannerDayColor(WeeklyDaySuggestion day, ThemeData theme) {
  if (day.isRest) return theme.colorScheme.onSurfaceVariant;
  if (day.isLight) return const Color(0xFFE08600);
  if (day.isCardio) return theme.colorScheme.tertiary;
  return theme.colorScheme.primary;
}

/// Legenda ikon planera (siła / cardio / lżejszy / wolny) — pasek tygodnia
/// używa samych ikon, więc jedno zdanie legendy robi go czytelnym.
class _PlannerLegend extends StatelessWidget {
  const _PlannerLegend();

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    Widget item(IconData icon, String label, Color color) => Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(icon, size: 12, color: color),
            const SizedBox(width: 3),
            Text(
              label,
              style: theme.textTheme.labelSmall?.copyWith(
                fontSize: 10,
                color: theme.colorScheme.onSurfaceVariant,
                fontWeight: FontWeight.w700,
              ),
            ),
          ],
        );
    return Wrap(
      spacing: 12,
      runSpacing: 4,
      children: [
        item(Icons.fitness_center_rounded, 'siła', theme.colorScheme.primary),
        item(
            Icons.directions_run_rounded, 'cardio', theme.colorScheme.tertiary),
        item(
            Icons.self_improvement_rounded, 'lżejszy', const Color(0xFFE08600)),
        item(Icons.hotel_rounded, 'wolne', theme.colorScheme.onSurfaceVariant),
      ],
    );
  }
}

/// Kompaktowy pasek 7 dni planera: litera dnia + ikona typu (siła / cardio /
/// lżejszy / wolny). Dzisiejszy dzień ma obrys. Czysty podgląd — bez akcji.
class _PlannerWeekStrip extends StatelessWidget {
  const _PlannerWeekStrip({required this.week});

  final List<WeeklyDaySuggestion> week;

  static const _dayLetters = ['Pn', 'Wt', 'Śr', 'Cz', 'Pt', 'So', 'Nd'];

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    return Row(
      children: [
        for (var index = 0; index < week.length; index++) ...[
          if (index > 0) const SizedBox(width: 4),
          Builder(builder: (context) {
            // Pasek zaczyna się od dziś, więc i-ty kafelek to dziś + i dni.
            final date = today.add(Duration(days: index));
            final deload = store.isDeloadDate(date);
            final dayColor =
                deload ? kDeloadColor : _plannerDayColor(week[index], theme);
            return Expanded(
              child: Container(
                padding: const EdgeInsets.symmetric(vertical: 7),
                decoration: BoxDecoration(
                  color: dayColor.withValues(
                      alpha: week[index].isRest && !deload ? 0.08 : 0.16),
                  borderRadius: BorderRadius.circular(12),
                  border: index == 0 || deload
                      ? Border.all(
                          color: dayColor.withValues(alpha: 0.7),
                          width: deload ? 1.2 : 1.4)
                      : null,
                ),
                child: Column(
                  children: [
                    Text(
                      (week[index].weekday >= 1 && week[index].weekday <= 7)
                          ? _dayLetters[week[index].weekday - 1]
                          : '?',
                      style: theme.textTheme.labelSmall?.copyWith(
                        fontWeight: FontWeight.w900,
                        color: deload
                            ? kDeloadColor
                            : (week[index].isRest
                                ? theme.colorScheme.onSurfaceVariant
                                : null),
                      ),
                    ),
                    const SizedBox(height: 3),
                    Icon(
                        deload
                            ? Icons.self_improvement_rounded
                            : _plannerDayIcon(week[index]),
                        size: 15,
                        color: dayColor),
                  ],
                ),
              ),
            );
          }),
        ],
      ],
    );
  }
}

