/// Status przekazywania spalonych kcal z treningów do aplikacji Licznik Kalorii.
class CalorieBridgeStatusCard extends StatelessWidget {
  const CalorieBridgeStatusCard({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final todayBurned = store.burnedKcalForDay(store.selectedDate);
    final latest =
        store.trainingImpacts.isEmpty ? null : store.trainingImpacts.first;
    final todayAdjustment = store.dailyAdjustmentForDay(store.selectedDate);
    final publishedAt = store.lastDailyAdjustmentsPublishAt;
    Widget row(String label, String value) => Padding(
          padding: const EdgeInsets.symmetric(vertical: 3),
          child: Row(
            children: [
              Text(label,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
              const Spacer(),
              Flexible(
                  child: Text(value,
                      textAlign: TextAlign.right,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: theme.textTheme.bodySmall
                          ?.copyWith(fontWeight: FontWeight.w800))),
            ],
          ),
        );
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
