                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(entry.type.label,
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      Text(
                        [
                          if (timeLabel.isNotEmpty) timeLabel,
                          entry.note.trim().isEmpty
                              ? entry.source.label
                              : entry.note.trim(),
                        ].join(' · '),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.labelSmall
                            ?.copyWith(color: scheme.onSurfaceVariant),
                      ),
                    ],
                  ),
                ),
                Text('${entry.estimatedKcal} kcal',
                    style: theme.textTheme.titleSmall?.copyWith(
                        fontWeight: FontWeight.w900, color: scheme.primary)),
              ],
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 6,
              children: [
                if (entry.distanceKm > 0)
                  MiniTag(text: formatHealthConnectDistance(entry.distanceKm)),
                if (entry.durationMin > 0)
                  MiniTag(text: '${entry.durationMin} min'),
                if (entry.steps > 0) MiniTag(text: '${entry.steps} kroków'),
                if (entry.distanceKm > 0 && entry.durationMin > 0)
                  MiniTag(
                      text: _paceLabel(entry.durationMin, entry.distanceKm)),
              ],
            ),
            if (entry.hasRoute) ...[
              const SizedBox(height: 10),
              ClipRRect(
                borderRadius: BorderRadius.circular(12),
                child: SizedBox(
                  height: 120,
                  child: CustomPaint(
                    painter: _RoutePolylinePainter(
                      points: entry.routePoints,
                      lineColor: scheme.primary,
                      backgroundColor:
                          scheme.surfaceContainerHighest.withValues(alpha: 0.7),
                      startColor: const Color(0xFF2E7D32),
                      endColor: scheme.error,
                    ),
                    child: const SizedBox.expand(),
                  ),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }

  static String _paceLabel(int minutes, double km) {
    if (km <= 0 || minutes <= 0) return '';
    final pace = minutes / km;
    final paceMinutes = pace.floor();
    final paceSeconds = ((pace - paceMinutes) * 60).round().clamp(0, 59);
    return '$paceMinutes:${paceSeconds.toString().padLeft(2, '0')} min/km';
  }
}

/// Rysuje trasę GPS jako polilinię (bez map SDK): normalizuje współrzędne
/// do prostokąta, start = zielona kropka, meta = czerwona.
class _RoutePolylinePainter extends CustomPainter {
  const _RoutePolylinePainter({
    required this.points,
    required this.lineColor,
    required this.backgroundColor,
    required this.startColor,
    required this.endColor,
  });

  final List<List<double>> points;
  final Color lineColor;
  final Color backgroundColor;
  final Color startColor;
  final Color endColor;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Offset.zero & size, Paint()..color = backgroundColor);
    if (points.length < 2) return;

    var minLat = points.first[0], maxLat = points.first[0];
    var minLng = points.first[1], maxLng = points.first[1];
    for (final point in points) {
      if (point[0] < minLat) minLat = point[0];
      if (point[0] > maxLat) maxLat = point[0];
      if (point[1] < minLng) minLng = point[1];
      if (point[1] > maxLng) maxLng = point[1];
    }
    final latSpan = math.max(maxLat - minLat, 1e-6);
    final lngSpan = math.max(maxLng - minLng, 1e-6);

    const padding = 12.0;
    final drawWidth = size.width - padding * 2;
    final drawHeight = size.height - padding * 2;
    // Zachowaj proporcje trasy (przybliżenie: 1° lat ≈ 1° lng w małej skali).
    final scale = math.min(drawWidth / lngSpan, drawHeight / latSpan);
    final offsetX = padding + (drawWidth - lngSpan * scale) / 2;
    final offsetY = padding + (drawHeight - latSpan * scale) / 2;

    Offset project(List<double> point) => Offset(
          offsetX + (point[1] - minLng) * scale,
          // Większa szerokość geograficzna = wyżej na ekranie.
          offsetY + (maxLat - point[0]) * scale,
        );

    final path = Path()
      ..moveTo(project(points.first).dx, project(points.first).dy);
    for (final point in points.skip(1)) {
      final projected = project(point);
      path.lineTo(projected.dx, projected.dy);
    }
    canvas.drawPath(
      path,
      Paint()
        ..color = lineColor
        ..style = PaintingStyle.stroke
        ..strokeWidth = 3
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round,
    );
    canvas.drawCircle(project(points.first), 5, Paint()..color = startColor);
    canvas.drawCircle(project(points.last), 5, Paint()..color = endColor);
  }

  @override
  bool shouldRepaint(_RoutePolylinePainter oldDelegate) =>
      oldDelegate.points != points || oldDelegate.lineColor != lineColor;
}

/// Szczegóły biegu / chodu w stylu Samsung Health: dystans, czas, tempo,
/// kcal (z zegarka albo fallback), tętno, kadencja, mapa trasy, strefy pulsu,
/// szacowana utrata wody i źródło danych.
class RunDetailPage extends StatelessWidget {
  const RunDetailPage({super.key, required this.entryId});

  final String entryId;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final index =
        store.activityEntries.indexWhere((entry) => entry.id == entryId);
    if (index < 0) {
      return Scaffold(
        appBar: AppBar(title: const Text('Aktywność')),
        body: const Center(child: Text('Nie znaleziono aktywności.')),
      );
    }
    final entry = store.activityEntries[index];
    final isRun = entry.type == TrainerActivityType.run;
    String two(int value) => value.toString().padLeft(2, '0');
    final start = entry.startedAt;
    final timeRange = start == null
        ? entry.dateKey
        : '${entry.dateKey} · ${two(start.hour)}:${two(start.minute)}–${two(entry.effectiveEnd.hour)}:${two(entry.effectiveEnd.minute)}';
    final zones = entry.hrZoneMinutes;
    final zonesTotal = zones.fold<int>(0, (sum, value) => sum + value);
    const zoneLabels = [
      'Maksymalna',
      'Anaerobowa',
      'Aerobowa',
      'Kontrola wagi',
      'Niska intensywność'
    ];
    const zoneColors = [
      Color(0xFFFF5D73),
      Color(0xFFFF9E64),
      Color(0xFF24D6A3),
      Color(0xFF58A6FF),
      Color(0xFF90A4AE)
    ];

    Widget statTile(String value, String label) => Expanded(
          child: Container(
            padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 8),
            decoration: BoxDecoration(
              color: scheme.surfaceContainerHighest.withValues(alpha: 0.5),
              borderRadius: BorderRadius.circular(14),
            ),
            child: Column(
              children: [
                FittedBox(
                    fit: BoxFit.scaleDown,
                    child: Text(value,
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
                const SizedBox(height: 2),
                Text(label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.labelSmall
                        ?.copyWith(color: scheme.onSurfaceVariant)),
              ],
            ),
          ),
        );

    return Scaffold(
      appBar: AppBar(title: Text(entry.type.label)),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
          children: [
            // Nagłówek: dystans + podstawowe statystyki.
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(timeRange,
                        style: theme.textTheme.labelMedium
                            ?.copyWith(color: scheme.onSurfaceVariant)),
                    const SizedBox(height: 6),
                    Text(
                      entry.distanceKm > 0
                          ? formatHealthConnectDistance(entry.distanceKm)
                          : '${entry.durationMin} min',
                      style: theme.textTheme.displaySmall
                          ?.copyWith(fontWeight: FontWeight.w900),
                    ),
                    const SizedBox(height: 12),
                    Row(
                      children: [
                        statTile('${entry.durationMin} min', 'Czas'),
                        const SizedBox(width: 8),
                        statTile(
                          entry.distanceKm > 0 && entry.durationMin > 0
                              ? _RunWalkEntryTile._paceLabel(
                                      entry.durationMin, entry.distanceKm)
                                  .replaceAll(' min/km', '')
                              : '—',
                          'Śr. tempo /km',
                        ),
                        const SizedBox(width: 8),
                        statTile('${entry.estimatedKcal}', 'kcal'),
                      ],
                    ),
                    const SizedBox(height: 8),
                    Text(
                      entry.kcalFromDevice
                          ? 'Kalorie zarejestrowane przez zegarek / Samsung Health.'
                          : 'Kalorie oszacowane przez Trainera (zegarek nie oddał wartości).',
                      style: theme.textTheme.labelSmall
                          ?.copyWith(color: scheme.onSurfaceVariant),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 12),
            // Mapa trasy.
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Mapa',
                        style: theme.textTheme.titleSmall
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 10),
                    if (entry.hasRoute)
                      ClipRRect(
                        borderRadius: BorderRadius.circular(14),
                        child: SizedBox(
                          height: 220,
                          child: CustomPaint(
                            painter: _RoutePolylinePainter(
                              points: entry.routePoints,
                              lineColor: scheme.primary,
                              backgroundColor: scheme.surfaceContainerHighest
                                  .withValues(alpha: 0.7),
