/// Pasek szybkich wejść do kategorii aktywności (styl Samsung Health):
/// pięć okrągłych ikon w JEDNEJ linii (bez przewijania) — bieg, chód,
/// trening, sen, tętno. To jedyne miejsce z danymi tych kategorii na
/// ekranie Dzisiaj (żeby nie zawalać interfejsu kafelkami).
class ActivityIconBar extends StatelessWidget {
  const ActivityIconBar({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    Widget item(String iconKey, IconData icon, String label,
        Widget Function() pageBuilder) {
      // Plakietka jak przy nieprzeczytanych wiadomościach: liczba nowych,
      // ważnych zdarzeń tej kategorii; znika po wejściu w ikonę.
      final badgeCount = store.activityIconBadgeCount(iconKey);
      return Expanded(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Badge(
              key: Key('activity_icon_badge_$iconKey'),
              isLabelVisible: badgeCount > 0,
              label: Text(badgeCount > 9 ? '9+' : '$badgeCount'),
              offset: const Offset(-4, 2),
              child: Material(
                color: scheme.surfaceContainerHighest.withValues(alpha: 0.6),
                shape: const CircleBorder(),
                child: InkWell(
                  customBorder: const CircleBorder(),
                  onTap: () {
                    store.markActivityIconSeen(iconKey);
                    Navigator.of(context).push(
                      MaterialPageRoute<void>(builder: (_) => pageBuilder()),
                    );
                  },
                  child: SizedBox(
                    width: 52,
                    height: 52,
                    child: Icon(icon, color: scheme.primary, size: 24),
                  ),
                ),
              ),
            ),
            const SizedBox(height: 4),
            FittedBox(
              fit: BoxFit.scaleDown,
              child: Text(label,
                  maxLines: 1,
                  style: theme.textTheme.labelSmall?.copyWith(
                      color: scheme.onSurfaceVariant,
                      fontWeight: FontWeight.w700)),
            ),
          ],
        ),
      );
    }

    return Row(
      children: [
        item('run', Icons.directions_run_rounded, 'Bieg',
            () => const ActivityTypeHistoryPage(type: TrainerActivityType.run)),
        item(
            'walk',
            Icons.hiking_rounded,
            'Chód',
            () => const ActivityTypeHistoryPage(
                type: TrainerActivityType.measuredWalk)),
        item('training', Icons.fitness_center_rounded, 'Trening',
            () => const TrainingHubPage()),
        item('sleep', Icons.bedtime_rounded, 'Sen',
            () => const SleepHistoryPage()),
        item('heart', Icons.monitor_heart_rounded, 'Tętno',
            () => const HeartRateHistoryPage()),
      ],
    );
  }
}

/// Historia biegów albo chodu (wejście z paska ikon): wszystkie zarejestrowane
/// aktywności danego typu, pogrupowane datami, z wejściem w szczegóły
/// i przyciskiem rozpoczęcia własnej rejestracji (stoper).
class ActivityTypeHistoryPage extends StatelessWidget {
  const ActivityTypeHistoryPage({super.key, required this.type});

  final TrainerActivityType type;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final isRun = type == TrainerActivityType.run;
    final entries = store.activityEntries
        .where((entry) => entry.type == type)
        .toList()
      ..sort(
          (left, right) => right.effectiveStart.compareTo(left.effectiveStart));
    final byDay = <String, List<TrainerActivityEntry>>{};
    for (final entry in entries) {
      byDay.putIfAbsent(entry.dateKey, () => []).add(entry);
    }

    return Scaffold(
      appBar: AppBar(title: Text(isRun ? 'Biegi' : 'Chód')),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: () => Navigator.of(context).push(
          MaterialPageRoute<void>(builder: (_) => RunRecorderPage(type: type)),
        ),
        icon: const Icon(Icons.play_arrow_rounded),
        label: Text(isRun ? 'Zacznij bieg' : 'Zacznij marsz'),
      ),
      body: SafeArea(
        child: entries.isEmpty
            ? Padding(
                padding: const EdgeInsets.all(24),
                child: Text(
                  isRun
                      ? 'Brak zarejestrowanych biegów. Nagraj bieg zegarkiem / Samsung Health (Trainer zaimportuje go automatycznie) albo użyj przycisku „Zacznij bieg".'
                      : 'Brak zarejestrowanego chodu. Nagraj marsz zegarkiem / Samsung Health albo użyj przycisku „Zacznij marsz".',
                  style: theme.textTheme.bodyMedium?.copyWith(height: 1.5),
                ),
              )
            : ListView(
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 96),
                children: [
                  for (final dayKey in byDay.keys) ...[
                    Padding(
                      padding: const EdgeInsets.only(top: 8, bottom: 8),
                      child: Text(dayKey,
                          style: theme.textTheme.labelLarge
                              ?.copyWith(fontWeight: FontWeight.w900)),
                    ),
                    for (final entry in byDay[dayKey]!)
                      _RunWalkEntryTile(entry: entry),
                  ],
                ],
              ),
      ),
    );
  }
}

