/// Prosty rejestrator biegu / marszu w Trainerze: stoper (start / pauza /
/// zakończ), na końcu opcjonalny dystans i notatka, kcal liczone wzorem MET.
/// GPS i tętno rejestruje zegarek (Samsung Health) — Trainer i tak zaimportuje
/// taką sesję automatycznie; ten ekran służy do szybkiej ręcznej rejestracji.
class RunRecorderPage extends StatefulWidget {
  const RunRecorderPage({super.key, required this.type});

  final TrainerActivityType type;

  @override
  State<RunRecorderPage> createState() => _RunRecorderPageState();
}

class _RunRecorderPageState extends State<RunRecorderPage> {
  Timer? _ticker;
  DateTime? _startedAt;
  int _elapsedSeconds = 0;
  bool _running = false;

  bool get _isRun => widget.type == TrainerActivityType.run;

  @override
  void dispose() {
    _ticker?.cancel();
    super.dispose();
  }

  void _start() {
    _startedAt ??= DateTime.now();
    _ticker?.cancel();
    _ticker = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() => _elapsedSeconds++);
    });
    setState(() => _running = true);
  }

  void _pause() {
    _ticker?.cancel();
    setState(() => _running = false);
  }

  Future<void> _finish() async {
    _pause();
    if (_elapsedSeconds < 30) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
            content: Text('Aktywność krótsza niż 30 sekund — nie zapisano.')),
      );
      return;
    }
    final store = AppScope.read(context);
    final distanceCtrl = TextEditingController();
    final noteCtrl = TextEditingController();
    final save = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text(_isRun ? 'Zapisz bieg' : 'Zapisz marsz'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: distanceCtrl,
              keyboardType:
                  const TextInputType.numberWithOptions(decimal: true),
              decoration:
                  const InputDecoration(labelText: 'Dystans (km, opcjonalnie)'),
            ),
            const SizedBox(height: 10),
            TextField(
              controller: noteCtrl,
              decoration:
                  const InputDecoration(labelText: 'Notatka (opcjonalnie)'),
            ),
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Zapisz')),
        ],
      ),
    );
    if (save != true || !mounted) return;

    final now = DateTime.now();
    final startedAt =
        _startedAt ?? now.subtract(Duration(seconds: _elapsedSeconds));
    final minutes = math.max(1, (_elapsedSeconds / 60).round());
    final weight =
        store.settings.bodyWeightKg > 0 ? store.settings.bodyWeightKg : 100.0;
    final met = _isRun ? 9.8 : 3.8;
    final kcal = estimateCalories(
      met: met,
      weightKg: weight,
      minutes: minutes.toDouble(),
    ).round();
    final distanceKm =
        double.tryParse(distanceCtrl.text.trim().replaceAll(',', '.')) ?? 0;
    final steps = distanceKm > 0
        ? (distanceKm * (_isRun ? 1250 : 1350)).round()
        : minutes * (_isRun ? 160 : 110);
    final entry = TrainerActivityEntry(
      id: 'manual_${idNow()}',
      date: DateTime(startedAt.year, startedAt.month, startedAt.day),
      source: TrainerActivitySource.manual,
      type: widget.type,
      estimatedKcal: kcal.clamp(0, 4000).toInt(),
      startedAt: startedAt,
      endedAt: now,
      durationMin: minutes,
      distanceKm: distanceKm < 0 ? 0 : distanceKm,
      steps: steps,
      note: noteCtrl.text.trim().isEmpty
          ? 'Rejestrator Trainera'
          : noteCtrl.text.trim(),
      sweatLossMl: store._estimateSweatLossMl(
          minutes: minutes, avgHeartRate: 0, weightKg: weight),
      kcalFromDevice: false,
    );
    await store.upsertActivityEntry(entry);
    if (!mounted) return;
    Navigator.of(context).pop();
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
          content: Text(_isRun
              ? 'Bieg zapisany (+$kcal kcal).'
              : 'Marsz zapisany (+$kcal kcal).')),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    return Scaffold(
      appBar: AppBar(
          title: Text(_isRun ? 'Rejestrator biegu' : 'Rejestrator marszu')),
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Spacer(),
              Icon(_isRun ? Icons.directions_run_rounded : Icons.hiking_rounded,
                  size: 64, color: scheme.primary),
              const SizedBox(height: 16),
              Text(
                _fmtClock(_elapsedSeconds),
                textAlign: TextAlign.center,
                style: theme.textTheme.displayLarge
                    ?.copyWith(fontWeight: FontWeight.w900, fontSize: 72),
              ),
              const SizedBox(height: 8),
              Text(
                'GPS, tętno i dokładne kcal rejestruje zegarek (Samsung Health) — taką sesję Trainer zaimportuje automatycznie. Ten stoper służy do szybkiego, ręcznego zapisu.',
                textAlign: TextAlign.center,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: scheme.onSurfaceVariant, height: 1.4),
              ),
              const Spacer(),
              Row(
                children: [
                  Expanded(
                    child: FilledButton.icon(
                      onPressed: _running ? _pause : _start,
                      icon: Icon(_running
                          ? Icons.pause_rounded
                          : Icons.play_arrow_rounded),
                      label: Text(_running
                          ? 'Pauza'
                          : (_elapsedSeconds > 0 ? 'Wznów' : 'Start')),
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: _elapsedSeconds > 0 ? _finish : null,
                      icon: const Icon(Icons.flag_rounded),
                      label: const Text('Zakończ i zapisz'),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

