/// Karta "Aktywność i korekta dnia": Trainer jako centrum aktywności.
/// Pokazuje policzony pakiet dnia (kcal w rozbiciu na źródła + woda/węgle/
/// białko) oraz status synchronizacji z Licznikiem Kalorii.
class DailyAdjustmentSummaryCard extends StatelessWidget {
  const DailyAdjustmentSummaryCard({super.key, required this.day});

  final DateTime day;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final adjustment = store.dailyAdjustmentForDay(day);
    final synced = store.dailyAdjustmentsSynced;

    // Status synchronizacji pakietu z Licznikiem Kalorii.
    final String statusLabel;
    final IconData statusIcon;
    final Color statusColor;
    if (!adjustment.hasAnyData &&
        adjustment.dataStatus == TrainerDailyAdjustment.statusNone) {
      statusLabel = 'Brak danych z Health Connect';
      statusIcon = Icons.sensors_off_rounded;
      statusColor = scheme.onSurfaceVariant;
    } else if (synced) {
      statusLabel = 'Zsynchronizowano z Kaloriami';
      statusIcon = Icons.check_circle_rounded;
      statusColor = scheme.primary;
    } else {
      statusLabel = 'Czeka na synchronizację';
      statusIcon = Icons.sync_rounded;
      statusColor = scheme.tertiary;
    }

    Widget kcalRow(IconData icon, String label, int kcal) {
      if (kcal <= 0) return const SizedBox.shrink();
      return Padding(
        padding: const EdgeInsets.only(bottom: 6),
        child: Row(
          children: [
            Icon(icon, size: 18, color: scheme.primary),
            const SizedBox(width: 8),
            Expanded(
              child: Text(label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.bodyMedium
                      ?.copyWith(fontWeight: FontWeight.w600)),
            ),
            Text('+$kcal kcal',
                style: theme.textTheme.bodyMedium
                    ?.copyWith(fontWeight: FontWeight.w800)),
          ],
        ),
      );
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
