class TrainingInsightCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  final DateTime selectedDay;

  const TrainingInsightCard(
      {super.key, required this.logs, required this.selectedDay});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final start = DateTime(selectedDay.year, selectedDay.month, selectedDay.day)
        .subtract(const Duration(days: 6));
    final recent = logs.where((e) => !e.date.isBefore(start)).toList();
    final total = DayTotals.from(recent);
    final streak = _streak(logs);
    final avgRpe = recent.isEmpty
        ? 0
        : recent.fold<int>(0, (a, e) => a + e.rpe) / recent.length;
    final top = _topExercise(recent);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.insights, color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Trenerski podgląd tygodnia',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
              ],
            ),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                  child: _MiniMetric(
                      label: 'Seria dni',
                      value: '$streak',
                      icon: Icons.local_fire_department_outlined)),
              const SizedBox(width: 8),
              Expanded(
                  child: _MiniMetric(
                      label: '7 dni kcal',
                      value: '${total.calories.round()}',
                      icon: Icons.bolt)),
              const SizedBox(width: 8),
              Expanded(
                  child: _MiniMetric(
                      label: 'Śr. RPE',
                      value: avgRpe == 0 ? '-' : avgRpe.toStringAsFixed(1),
                      icon: Icons.speed)),
            ]),
            const SizedBox(height: 10),
            Text(
                top.isEmpty
                    ? 'Dodaj kilka treningów, a pokażę najczęstsze ćwiczenie i kierunek progresu.'
                    : 'Najczęściej ostatnio: $top',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
          ],
        ),
      ),
    );
  }

  int _streak(List<WorkoutLog> logs) {
    var day = DateTime.now();
    var count = 0;
    while (count < 365) {
      final has = logs.any((e) => sameDay(e.date, day));
      if (!has) break;
      count++;
      day = day.subtract(const Duration(days: 1));
    }
    return count;
  }

  String _topExercise(List<WorkoutLog> logs) {
    final counts = <String, int>{};
    for (final log in logs) {
      counts[log.exerciseId] = (counts[log.exerciseId] ?? 0) + 1;
    }
    if (counts.isEmpty) return '';
    final id = counts.entries.reduce((a, b) => a.value >= b.value ? a : b).key;
    return ExerciseRepo.byId(id).name;
  }
}

