class WorkoutTimerCard extends StatefulWidget {
  @override
  State<WorkoutTimerCard> createState() => _WorkoutTimerCardState();
}

class _WorkoutTimerCardState extends State<WorkoutTimerCard> {
  Timer? timer;
  int seconds = 90;
  int initial = 90;
  bool running = false;

  @override
  void dispose() {
    timer?.cancel();
    super.dispose();
  }

  void start() {
    timer?.cancel();
    setState(() => running = true);
    timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (seconds <= 1) {
        timer?.cancel();
        setState(() {
          seconds = 0;
          running = false;
        });
      } else {
        setState(() => seconds--);
      }
    });
  }

  void reset(int value) {
    timer?.cancel();
    setState(() {
      initial = value;
      seconds = value;
      running = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final progress = initial == 0 ? 0.0 : seconds / initial;
    final min = (seconds ~/ 60).toString().padLeft(2, '0');
    final sec = (seconds % 60).toString().padLeft(2, '0');
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Row(children: [
            Icon(Icons.timer_outlined, color: theme.colorScheme.primary),
            const SizedBox(width: 8),
            Expanded(
                child: Text('Timer odpoczynku',
                    style: theme.textTheme.titleMedium
                        ?.copyWith(fontWeight: FontWeight.w900))),
            Text('$min:$sec',
                style: theme.textTheme.titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
          ]),
          const SizedBox(height: 10),
          LinearProgressIndicator(value: progress.clamp(0, 1)),
          const SizedBox(height: 12),
          Wrap(spacing: 8, runSpacing: 8, children: [
            OutlinedButton(
                onPressed: () => reset(60), child: const Text('60 s')),
            OutlinedButton(
                onPressed: () => reset(90), child: const Text('90 s')),
            OutlinedButton(
                onPressed: () => reset(120), child: const Text('120 s')),
            FilledButton.icon(
                onPressed: running ? null : start,
                icon: const Icon(Icons.play_arrow),
                label: const Text('Start')),
          ]),
        ]),
      ),
    );
  }
}

