class AiResultPreviewCard extends StatelessWidget {
  final Map<String, dynamic> result;
  final bool expanded;

  const AiResultPreviewCard(
      {super.key, required this.result, this.expanded = false});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final summary = smartValue(
        result['summary'] ?? result['note'] ?? result['result'],
        fallback: 'Analiza gotowa.');
    final intensity = smartValue(result['intensity'] ?? result['training_type'],
        fallback: 'brak danych');
    final calories = smartValue(
        result['estimated_calories'] ?? result['calories'],
        fallback: '0');
    final minutes = smartValue(
        result['duration_min'] ??
            result['duration_minutes'] ??
            result['total_duration_min'],
        fallback: '-');
    final sets = smartValue(result['total_sets'], fallback: '-');
    final volume = smartValue(
        result['estimated_volume_kg'] ?? result['volume_kg'],
        fallback: '-');
    final muscles =
        smartStringList(result['worked_muscles'] ?? result['muscles']);
    final suggestions =
        smartStringList(result['suggestions'] ?? result['tips']);
    final exercisesRaw = result['detected_exercises'] ?? result['exercises'];
    final detected = exercisesRaw is List
        ? exercisesRaw
            .whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList()
        : <Map<String, dynamic>>[];

    Widget metric(String label, String value, IconData icon) {
      return Expanded(
        child: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: theme.colorScheme.surfaceContainerHighest.withOpacity(0.55),
            borderRadius: BorderRadius.circular(18),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Icon(icon, size: 20, color: theme.colorScheme.primary),
              const SizedBox(height: 8),
              Text(value,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.titleMedium
                      ?.copyWith(fontWeight: FontWeight.w900)),
              Text(label,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.labelSmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            ],
          ),
        ),
      );
    }

    return Card(
      margin: EdgeInsets.zero,
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                CircleAvatar(
                  backgroundColor: theme.colorScheme.primaryContainer,
                  foregroundColor: theme.colorScheme.onPrimaryContainer,
                  child: const Icon(Icons.auto_awesome),
                ),
                const SizedBox(width: 10),
                Expanded(
                    child: Text('Wynik analizy AI',
                        style: theme.textTheme.titleLarge
                            ?.copyWith(fontWeight: FontWeight.w900))),
                if (expanded)
                  IconButton(
                      onPressed: () => Navigator.of(context).maybePop(),
                      icon: const Icon(Icons.close)),
              ],
            ),
            const SizedBox(height: 12),
            Text(summary,
                style: theme.textTheme.bodyMedium?.copyWith(height: 1.35)),
            const SizedBox(height: 14),
            Row(children: [
              metric('Kalorie', '$calories kcal',
                  Icons.local_fire_department_outlined),
              const SizedBox(width: 8),
              metric('Czas', '$minutes min', Icons.timer_outlined),
            ]),
            const SizedBox(height: 8),
            Row(children: [
              metric('Serie', sets, Icons.repeat),
              const SizedBox(width: 8),
              metric('Objętość', '$volume kg', Icons.monitor_weight_outlined),
            ]),
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                MiniTag(text: 'Intensywność: $intensity'),
                ...muscles.take(8).map((m) => MiniTag(text: m)),
              ],
            ),
            if (detected.isNotEmpty) ...[
              const SizedBox(height: 14),
              Text('Wykryte ćwiczenia',
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 8),
              ...detected.take(expanded ? 10 : 3).map((e) => Container(
                    margin: const EdgeInsets.only(bottom: 8),
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: theme.colorScheme.surfaceContainerHighest
                          .withOpacity(0.40),
                      borderRadius: BorderRadius.circular(18),
                    ),
                    child: Row(
                      children: [
                        const Icon(Icons.fitness_center, size: 18),
                        const SizedBox(width: 8),
                        Expanded(
                            child: Text(smartValue(e['name']),
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                    fontWeight: FontWeight.w800))),
                        Text(
                            '${smartValue(e['sets'])}×${smartValue(e['reps'])}',
                            style: theme.textTheme.labelLarge),
                      ],
                    ),
                  )),
            ],
            if (suggestions.isNotEmpty) ...[
              const SizedBox(height: 10),
              Text('Sugestie',
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              ...suggestions.take(expanded ? 8 : 3).map((e) => Padding(
                    padding: const EdgeInsets.only(bottom: 6),
                    child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Icon(Icons.check_circle_outline,
                              size: 18, color: theme.colorScheme.primary),
                          const SizedBox(width: 8),
                          Expanded(child: Text(e)),
                        ]),
                  )),
            ],
            if (expanded) ...[
              const SizedBox(height: 12),
              ExpansionTile(
                tilePadding: EdgeInsets.zero,
                title: const Text('Surowy JSON / debug'),
                children: [
                  SelectableText(prettyJson(result),
                      style: theme.textTheme.bodySmall)
                ],
              ),
            ],
          ],
        ),
      ),
    );
  }
}

void showError(BuildContext context, String message) {
  ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), behavior: SnackBarBehavior.floating));
}

/// Buduje gotowy plan treningu brzucha (jeden dzień, ćwiczenia czasowe).
WorkoutPlan buildAbWorkoutPlan() {
  final items = <PlanItem>[
    for (final id in ExerciseRepo.abWorkoutSetIds)
      PlanItem(
        exerciseId: id,
        sets: 1,
        reps: 0,
        durationSec: ExerciseRepo.byId(id).defaultDurationSec,
        note: '',
        restSeconds: 15,
      ),
  ];
  return WorkoutPlan(
    id: 'ab_set_${idNow()}',
    name: 'Trening brzucha',
    note:
        'Gotowy zestaw na brzuch i skośne — wykonuj ćwiczenia po kolei, bez długich przerw.',
    goal: 'Sylwetka',
    level: 'Początkujący',
    isActive: true,
    days: [
      WorkoutDay(
          weekday: DateTime.now().weekday,
          title: 'Brzuch — zestaw',
          items: items),
    ],
  );
}

/// Dodaje gotowy trening brzucha jako aktywny plan i otwiera jego szczegóły dnia.
Future<void> addReadyAbWorkout(BuildContext context) async {
  final store = AppScope.read(context);
  final existing =
      store.plans.where((plan) => plan.id.startsWith('ab_set_')).toList();
  final WorkoutPlan plan;
  if (existing.isNotEmpty) {
    plan = existing.first;
    await store.setActiveWorkoutPlan(plan.id);
  } else {
    plan = buildAbWorkoutPlan();
    await store.addWorkoutPlan(plan);
  }
  if (!context.mounted) return;
  await openWorkoutDayDetails(context, plan.id, 0);
}

class ExercisesPage extends StatefulWidget {
  const ExercisesPage({super.key});

  @override
  State<ExercisesPage> createState() => _ExercisesPageState();
}

class _ExercisesPageState extends State<ExercisesPage> {
  final search = TextEditingController();
  String muscleGroup = 'Wszystkie';
  String equipmentType = 'Wszystkie';
  String level = 'Wszystkie';
  String trainingGoal = 'Wszystkie';
  bool onlyFavorites = false;
  bool showHidden = false;
  bool onlyAvailableEquipment = false;
  bool avoidLimitations = false;

  @override
  void dispose() {
    search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final filter = ExerciseLibraryFilter(
      query: search.text,
      muscleGroup: muscleGroup == 'Wszystkie'
          ? null
          : MuscleGroup.values.firstWhere((value) => value.name == muscleGroup),
      equipmentType: equipmentType == 'Wszystkie'
          ? null
          : EquipmentType.values
              .firstWhere((value) => value.name == equipmentType),
      level: level == 'Wszystkie' ? null : level,
      trainingGoal: trainingGoal == 'Wszystkie'
          ? null
          : TrainingGoal.values
              .firstWhere((value) => value.name == trainingGoal),
      onlyFavorites: onlyFavorites,
      showHidden: showHidden,
    );
    final filteredItems = filter.apply(
      exercises: ExerciseRepo.combined(store.customExercises),
      preferences: store.exerciseLibraryPreferences,
    );
    final items = filteredItems.where((exercise) {
      final equipmentOk = !onlyAvailableEquipment ||
          equipmentMatchesSettings(exercise, store.settings.equipment);
      final painOk = !avoidLimitations ||
          limitationSafe(exercise, store.settings.limitations);
      return equipmentOk && painOk;
    }).toList();
    final fullLibrary = ExerciseRepo.combined(store.customExercises);
    final recentExercises = _recentExercises(store);
    final showRecent = !_hasActiveFilters &&
        search.text.trim().isEmpty &&
        recentExercises.isNotEmpty;
    return PageFrame(
      title: 'Baza ćwiczeń',
      subtitle:
          '${items.length} ćwiczeń · technika, bezpieczeństwo i lokalne preferencje',
      actions: [
        IconButton.filledTonal(
          tooltip: 'Dodaj własne ćwiczenie',
          onPressed: () => showCreateExerciseSheet(context),
          icon: const Icon(Icons.add_rounded),
        ),
        const SizedBox(width: 8),
        IconButton.filledTonal(
          tooltip: 'Importuj ćwiczenie',
          onPressed: () => showWgerSearchSheet(context),
          icon: const Icon(Icons.cloud_download_outlined),
        ),
        const SizedBox(width: 8),
        IconButton.filledTonal(
          tooltip: 'Dodaj trening',
          onPressed: () => showAddWorkoutSheet(context),
          icon: const Icon(Icons.playlist_add_rounded),
        ),
      ],
      slivers: [
        // Leniwa lista kart ćwiczeń — budowane są tylko widoczne elementy,
        // zamiast całej bazy naraz (wcześniejsze źródło ścinek przewijania).
        if (items.isNotEmpty)
          SliverPadding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
            sliver: SliverList.builder(
              itemCount: items.length,
              itemBuilder: (context, index) {
                final exercise = items[index];
                return ExerciseCard(
                  exercise: exercise,
                  isFavorite: store.isExerciseFavorite(exercise.id),
                  isHidden: store.isExerciseHidden(exercise.id),
                  onFavorite: () => store.toggleExerciseFavorite(exercise.id),
                  onHidden: () => store.setExerciseHidden(
                    exercise.id,
                    !store.isExerciseHidden(exercise.id),
                  ),
                  onEdit: () => showCreateExerciseSheet(
                    context,
                    exercise: exercise,
                  ),
                );
              },
            ),
          ),
      ],
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          // Wyszukiwarka jako pierwszy, główny element bazy ćwiczeń.
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  TextField(
                    controller: search,
                    onChanged: (_) => setState(() {}),
                    textInputAction: TextInputAction.search,
                    decoration: InputDecoration(
                      prefixIcon: const Icon(Icons.search_rounded),
                      hintText: 'Szukaj po nazwie ćwiczenia',
                      suffixIcon: search.text.isEmpty
                          ? null
                          : IconButton(
                              tooltip: 'Wyczyść',
                              onPressed: () {
                                search.clear();
                                setState(() {});
                              },
                              icon: const Icon(Icons.close_rounded),
                            ),
                    ),
                  ),
                  const SizedBox(height: 12),
                  // Szybki wybór partii mięśniowej — bez otwierania pełnych filtrów.
                  SizedBox(
                    height: 44,
                    child: ListView.separated(
                      scrollDirection: Axis.horizontal,
                      itemCount: MuscleGroup.values.length + 1,
                      separatorBuilder: (_, __) => const SizedBox(width: 8),
                      itemBuilder: (context, i) {
                        final isAll = i == 0;
                        final group = isAll ? null : MuscleGroup.values[i - 1];
                        final value = isAll ? 'Wszystkie' : group!.name;
                        final selected = muscleGroup == value;
                        return FilterChip(
                          materialTapTargetSize:
                              MaterialTapTargetSize.shrinkWrap,
                          visualDensity: VisualDensity.compact,
                          label: Text(isAll ? 'Wszystkie' : group!.label),
                          selected: selected,
                          onSelected: (_) =>
                              setState(() => muscleGroup = value),
                        );
                      },
                    ),
                  ),
                  const SizedBox(height: 12),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: [
                      FilterChip(
                        avatar: Icon(
                          onlyFavorites
                              ? Icons.star_rounded
                              : Icons.star_border_rounded,
                          size: 18,
                        ),
                        label: const Text('Ulubione'),
                        selected: onlyFavorites,
                        onSelected: (value) =>
                            setState(() => onlyFavorites = value),
                      ),
                      FilterChip(
                        avatar:
                            const Icon(Icons.visibility_off_outlined, size: 18),
                        label: Text(
                          'Ukryte (${store.exerciseLibraryPreferences.hiddenExerciseIds.length})',
                        ),
                        selected: showHidden,
                        onSelected: (value) =>
                            setState(() => showHidden = value),
                      ),
                      FilterChip(
                        label: const Text('Tylko mój sprzęt'),
                        selected: onlyAvailableEquipment,
                        onSelected: (value) =>
                            setState(() => onlyAvailableEquipment = value),
                      ),
                      FilterChip(
                        label: const Text('Omijaj ograniczenia'),
                        selected: avoidLimitations,
                        onSelected: (value) =>
                            setState(() => avoidLimitations = value),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 12),
          // Filtry w rozwijanej sekcji — szczegóły widoczne dopiero po kliknięciu,
          // co odchudza pierwszy render zakładki.
          Card(
            clipBehavior: Clip.antiAlias,
            child: ExpansionTile(
              leading: Icon(
                Icons.tune_rounded,
                color: Theme.of(context).colorScheme.primary,
              ),
              title: Text(
                'Filtry bazy',
                style: Theme.of(context)
                    .textTheme
                    .titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900),
              ),
              subtitle: Text(
                _hasActiveFilters
                    ? 'Aktywne filtry — dotknij, aby zmienić'
                    : 'Partia, sprzęt, poziom i cel',
                style: Theme.of(context).textTheme.bodySmall,
              ),
              initiallyExpanded: _hasActiveFilters,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Align(
                        alignment: Alignment.centerRight,
                        child: TextButton(
                          onPressed: _hasActiveFilters
                              ? () {
                                  setState(() {
                                    muscleGroup = 'Wszystkie';
                                    equipmentType = 'Wszystkie';
                                    level = 'Wszystkie';
                                    trainingGoal = 'Wszystkie';
                                    onlyFavorites = false;
                                    showHidden = false;
                                    onlyAvailableEquipment = false;
                                    avoidLimitations = false;
                                  });
                                }
                              : null,
                          child: const Text('Wyczyść'),
                        ),
                      ),
                      LayoutBuilder(
                        builder: (context, constraints) {
                          final columns = constraints.maxWidth >= 620 ? 2 : 1;
                          final width = columns == 2
                              ? (constraints.maxWidth - 10) / 2
                              : constraints.maxWidth;
                          return Wrap(
                            spacing: 10,
                            runSpacing: 10,
                            children: [
                              SizedBox(
                                width: width,
                                child: _ExerciseFilterDropdown(
                                  label: 'Partia mięśniowa',
                                  value: muscleGroup,
                                  options: [
                                    const MapEntry('Wszystkie', 'Wszystkie'),
                                    ...MuscleGroup.values.map(
                                      (value) =>
                                          MapEntry(value.name, value.label),
                                    ),
                                  ],
                                  onChanged: (value) =>
                                      setState(() => muscleGroup = value),
                                ),
                              ),
                              SizedBox(
                                width: width,
                                child: _ExerciseFilterDropdown(
                                  label: 'Sprzęt',
                                  value: equipmentType,
                                  options: [
                                    const MapEntry('Wszystkie', 'Wszystkie'),
                                    ...EquipmentType.values.map(
                                      (value) =>
                                          MapEntry(value.name, value.label),
                                    ),
                                  ],
                                  onChanged: (value) =>
                                      setState(() => equipmentType = value),
                                ),
                              ),
                              SizedBox(
                                width: width,
                                child: _ExerciseFilterDropdown(
                                  label: 'Poziom trudności',
                                  value: level,
                                  options: [
                                    const MapEntry('Wszystkie', 'Wszystkie'),
                                    ...kTrainingLevels.map(
                                      (value) => MapEntry(value, value),
                                    ),
                                  ],
                                  onChanged: (value) =>
                                      setState(() => level = value),
                                ),
                              ),
                              SizedBox(
                                width: width,
                                child: _ExerciseFilterDropdown(
                                  label: 'Cel treningowy',
                                  value: trainingGoal,
                                  options: [
                                    const MapEntry('Wszystkie', 'Wszystkie'),
                                    ...TrainingGoal.values.map(
                                      (value) =>
                                          MapEntry(value.name, value.label),
                                    ),
                                  ],
                                  onChanged: (value) =>
                                      setState(() => trainingGoal = value),
                                ),
                              ),
                            ],
                          );
                        },
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
          // Etap 24: szybki dostęp do ostatnio używanych ćwiczeń (realne dane z logów).
          if (showRecent) ...[
            const SizedBox(height: 14),
            Text(
              'Ostatnio używane',
              style: Theme.of(context)
                  .textTheme
                  .titleLarge
                  ?.copyWith(fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 10),
            SizedBox(
              height: 40,
              child: ListView.separated(
                scrollDirection: Axis.horizontal,
                itemCount: recentExercises.length,
                separatorBuilder: (_, __) => const SizedBox(width: 8),
                itemBuilder: (context, index) {
                  final exercise = recentExercises[index];
                  return ActionChip(
                    avatar: Icon(ExercisePlaceholder.iconForExercise(exercise),
                        size: 18),
                    label: Text(exercise.name, overflow: TextOverflow.ellipsis),
                    onPressed: () => Navigator.of(context).push(
                      MaterialPageRoute(
                          builder: (_) =>
                              ExerciseDetailsPage(exerciseId: exercise.id)),
                    ),
                  );
                },
              ),
            ),
          ],
          const SizedBox(height: 14),
          Row(
            children: [
              Expanded(
                child: Text(
                  showHidden ? 'Ukryte ćwiczenia' : 'Wszystkie ćwiczenia',
                  style: Theme.of(context)
                      .textTheme
                      .titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900),
                ),
              ),
              Text(
                '${items.length}',
                style: Theme.of(context).textTheme.titleMedium?.copyWith(
                      color: Theme.of(context).colorScheme.primary,
                      fontWeight: FontWeight.w900,
                    ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          if (items.isEmpty)
            _ExerciseLibraryEmptyState(
              showingHidden: showHidden,
              query: search.text,
              baseEmpty: fullLibrary.isEmpty,
              onAdd: () => showCreateExerciseSheet(context),
              onClearFilters: () {
                search.clear();
                setState(() {
                  muscleGroup = 'Wszystkie';
                  equipmentType = 'Wszystkie';
                  level = 'Wszystkie';
                  trainingGoal = 'Wszystkie';
                  onlyFavorites = false;
                  showHidden = false;
                  onlyAvailableEquipment = false;
                  avoidLimitations = false;
                });
              },
            ),
        ],
      ),
    );
  }

  bool get _hasActiveFilters =>
      muscleGroup != 'Wszystkie' ||
      equipmentType != 'Wszystkie' ||
      level != 'Wszystkie' ||
      trainingGoal != 'Wszystkie' ||
      onlyFavorites ||
      showHidden ||
      onlyAvailableEquipment ||
      avoidLimitations;

  /// Etap 24: ostatnio używane ćwiczenia z historii treningów (realne dane).
  /// Zwraca maks. 8 unikalnych ćwiczeń od najnowszego wpisu.
  List<Exercise> _recentExercises(AppStore store) {
    final sortedLogs = [...store.logs]
      ..sort((a, b) => b.date.compareTo(a.date));
    final seen = <String>{};
    final result = <Exercise>[];
    for (final log in sortedLogs) {
      if (seen.add(log.exerciseId)) {
        result.add(ExerciseRepo.byId(log.exerciseId, store.customExercises));
        if (result.length >= 8) break;
      }
    }
    return result;
  }
}

class _ExerciseFilterDropdown extends StatelessWidget {
  const _ExerciseFilterDropdown({
    required this.label,
    required this.value,
    required this.options,
    required this.onChanged,
  });

  final String label;
  final String value;
  final List<MapEntry<String, String>> options;
  final ValueChanged<String> onChanged;

  @override
  Widget build(BuildContext context) {
    return DropdownButtonFormField<String>(
      key: ValueKey('$label-$value'),
      initialValue: value,
      isExpanded: true,
      decoration: InputDecoration(labelText: label),
      items: options
          .map(
            (option) => DropdownMenuItem<String>(
              value: option.key,
              child: Text(
                option.value,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ),
          )
          .toList(),
      onChanged: (next) {
        if (next != null) onChanged(next);
      },
    );
  }
}

class _ExerciseLibraryEmptyState extends StatelessWidget {
  const _ExerciseLibraryEmptyState({
    required this.showingHidden,
    required this.onAdd,
    required this.onClearFilters,
    this.query = '',
    this.baseEmpty = false,
  });

  final bool showingHidden;
  final VoidCallback onAdd;
  final VoidCallback onClearFilters;
  final String query;
  final bool baseEmpty;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final hasQuery = query.trim().isNotEmpty;

    // Dobór komunikatu zależnie od przyczyny pustej listy.
    final IconData icon;
    final String title;
    final String message;
    if (baseEmpty) {
      icon = Icons.fitness_center_rounded;
      title = 'Baza ćwiczeń jest pusta';
      message =
          'Dodaj pierwsze ćwiczenie albo zaimportuj je z zewnętrznej bazy.';
    } else if (showingHidden) {
      icon = Icons.visibility_outlined;
      title = 'Brak ukrytych ćwiczeń';
      message =
          'Ukryte pozycje pojawią się tutaj i będzie można je przywrócić.';
    } else if (hasQuery) {
      icon = Icons.search_off_rounded;
      title = 'Brak wyników dla „${query.trim()}"';
      message = 'Sprawdź pisownię, wyczyść filtry albo dodaj własne ćwiczenie.';
    } else {
      icon = Icons.search_off_rounded;
      title = 'Brak ćwiczeń dla wybranych filtrów';
      message = 'Wyczyść filtry albo dodaj własne ćwiczenie.';
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(24),
        child: Column(
          children: [
            Icon(icon, size: 46, color: theme.colorScheme.primary),
            const SizedBox(height: 12),
            Text(
              title,
              textAlign: TextAlign.center,
              style: theme.textTheme.titleMedium
                  ?.copyWith(fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 6),
            Text(
              message,
              textAlign: TextAlign.center,
              style: theme.textTheme.bodyMedium
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
            const SizedBox(height: 16),
            Wrap(
              alignment: WrapAlignment.center,
              spacing: 8,
              runSpacing: 8,
              children: [
                if (!baseEmpty)
                  OutlinedButton(
                    onPressed: onClearFilters,
                    child: const Text('Wyczyść filtry'),
                  ),
                FilledButton.icon(
                  onPressed: onAdd,
                  icon: const Icon(Icons.add_rounded),
                  label: const Text('Dodaj ćwiczenie'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

void showWgerSearchSheet(BuildContext context) {
  final store = AppScope.read(context);
  showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) =>
        WgerSearchSheetContent(store: store, hostContext: context),
  );
}

class WgerSearchSheetContent extends StatefulWidget {
  final AppStore store;
  final BuildContext hostContext;

  const WgerSearchSheetContent(
      {super.key, required this.store, required this.hostContext});

  @override
  State<WgerSearchSheetContent> createState() => _WgerSearchSheetContentState();
}

class _WgerSearchSheetContentState extends State<WgerSearchSheetContent> {
  final query = TextEditingController();
  bool busy = false;
  String message = '';
  List<Exercise> results = const [];
  List<Exercise> localResults = const [];

  @override
  void dispose() {
    query.dispose();
    super.dispose();
  }

  Future<void> runSearch() async {
    if (query.text.trim().isEmpty || busy) return;
    final text = query.text;
    // Lokalna baza zawsze przeszukiwana od razu (synonimy PL↔EN, partie, sprzęt).
    final local = searchLocalExercises(
            text, ExerciseRepo.combined(widget.store.customExercises))
        .take(8)
        .toList();
    setState(() {
      busy = true;
      message = '';
      localResults = local;
    });
    try {
      final found = await WgerService().searchExercises(text);
      if (!mounted) return;
      // Nie pokazuj duplikatów ćwiczeń, które użytkownik już ma w bazie.
      final ownedIds = ExerciseRepo.combined(widget.store.customExercises)
          .map((e) => e.id)
          .toSet();
      final fresh = found.where((e) => !ownedIds.contains(e.id)).toList();
      setState(() {
        results = fresh;
        if (fresh.isEmpty && local.isEmpty) {
          message =
              'Brak wyników. Spróbuj innej nazwy (PL lub EN), np. pompki / push up, przysiad / squat.';
        } else if (fresh.isEmpty) {
          message =
              'Wger nie zwrócił nowych wyników — poniżej dopasowania z Twojej lokalnej bazy.';
        } else {
          message =
              'Znaleziono ${fresh.length} ćwiczeń w wger. Kliknij + przy wybranym.';
        }
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        results = const [];
        message = local.isEmpty
            ? 'Błąd połączenia z wger: $e'
            : 'Wger niedostępny — pokazuję dopasowania z lokalnej bazy.';
      });
    } finally {
      if (mounted) setState(() => busy = false);
    }
  }

  Future<void> addExercise(Exercise exercise) async {
    // Przy dodawaniu z wger dociągnij pełne dane (partie, sprzęt, opis, obraz)
    // — wyszukiwarka zwraca tylko skrót. Błąd sieci → zapis wersji skróconej.
    var toAdd = exercise;
    if (exercise.source == 'wger') {
      setState(() => busy = true);
      final detailed = await WgerService().fetchExerciseDetails(exercise.id);
      if (detailed != null) {
        toAdd = detailed.copyWith(
          imageUrl: detailed.imageUrl ?? exercise.imageUrl,
          category:
              detailed.category.isEmpty ? exercise.category : detailed.category,
        );
      }
      if (!mounted) return;
      setState(() => busy = false);
    }
    await widget.store.addCustomExercise(toAdd);
    if (!mounted) return;
    Navigator.of(context).pop();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (widget.hostContext.mounted) {
        showError(widget.hostContext, 'Dodano do bazy: ${toAdd.name}');
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Padding(
      padding: EdgeInsets.fromLTRB(
        16,
        0,
        16,
        16 +
            MediaQuery.of(context).viewInsets.bottom +
            MediaQuery.of(context).viewPadding.bottom,
      ),
      child: SingleChildScrollView(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text('Szukaj ćwiczeń (lokalnie + wger)',
                style: theme.textTheme.titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 8),
            Text(
                'Działa po polsku i angielsku: pompki / push up, przysiad / squat, wyciskanie / bench press. Nowe ćwiczenia z wger trafiają do lokalnej bazy.',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            const SizedBox(height: 12),
            TextField(
              controller: query,
              decoration: const InputDecoration(
                  prefixIcon: Icon(Icons.search),
                  labelText: 'Nazwa ćwiczenia (PL / EN)'),
              textInputAction: TextInputAction.search,
              onSubmitted: (_) => runSearch(),
            ),
            const SizedBox(height: 10),
            FilledButton.icon(
              onPressed: busy ? null : runSearch,
              icon: busy
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.search),
              label: const Text('Szukaj'),
            ),
            if (message.isNotEmpty) ...[
              const SizedBox(height: 10),
              Text(message,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            ],
            if (localResults.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text('Z Twojej lokalnej bazy',
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              ...localResults.map((exercise) => Card(
                    child: ListTile(
                      leading: SizedBox(
                          width: 54,
                          height: 54,
                          child: ExerciseVisual(exercise: exercise)),
                      title: Text(exercise.name,
                          maxLines: 1, overflow: TextOverflow.ellipsis),
                      subtitle: Text(
                          '${exercise.category} · ${exercise.equipment}',
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis),
                      trailing: Icon(Icons.check_circle_outline_rounded,
                          color: theme.colorScheme.primary),
                      onTap: () {
                        Navigator.of(context).pop();
                        WidgetsBinding.instance.addPostFrameCallback((_) {
                          if (widget.hostContext.mounted) {
                            Navigator.of(widget.hostContext).push(
                              MaterialPageRoute<void>(
                                builder: (_) => ExerciseDetailsPage(
                                    exerciseId: exercise.id),
                              ),
                            );
                          }
                        });
                      },
                    ),
                  )),
            ],
            if (results.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text('Nowe z bazy wger',
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              ...results.map((exercise) => Card(
                    child: ListTile(
                      leading: SizedBox(
                          width: 54,
                          height: 54,
                          child: ExerciseVisual(exercise: exercise)),
                      title: Text(exercise.name,
                          maxLines: 1, overflow: TextOverflow.ellipsis),
                      subtitle: Text(
                          '${exercise.category} · ${exercise.equipment}',
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis),
                      trailing: IconButton.filledTonal(
                        onPressed: () => addExercise(exercise),
                        tooltip: 'Dodaj do bazy',
                        icon: const Icon(Icons.add),
                      ),
                      onTap: () => addExercise(exercise),
                    ),
                  )),
            ],
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }
}

