/// Mapa zaangażowanych mięśni ćwiczenia na sylwetce (Etap: mapa mięśni).
/// Wykorzystuje ten sam model człowieka co mapa regeneracji ([BodyMuscleMap]
/// z nadpisanymi kolorami): partie główne, pomocnicze i stabilizujące mają
/// różne kolory, a partie zaangażowane i jednocześnie zmęczone są oznaczone
/// ostrzegawczo wraz z komunikatem pod mapą.
class ExerciseMuscleMapCard extends StatefulWidget {
  const ExerciseMuscleMapCard({super.key, required this.exercise});

  final Exercise exercise;

  @override
  State<ExerciseMuscleMapCard> createState() => _ExerciseMuscleMapCardState();
}

class _ExerciseMuscleMapCardState extends State<ExerciseMuscleMapCard> {
  BodyMuscleSide? _side;

  /// Strona modelu z większą liczbą zaangażowanych partii (domyślny widok).
  BodyMuscleSide _preferredSide(List<ExerciseMuscleImpact> impacts) {
    var front = 0;
    var back = 0;
    for (final impact in impacts) {
      final weight = impact.role == MuscleRole.primary ? 2 : 1;
      if (kFrontMuscleMasks.containsKey(impact.muscleGroup)) front += weight;
      if (kBackMuscleMasks.containsKey(impact.muscleGroup)) back += weight;
    }
    return back > front ? BodyMuscleSide.back : BodyMuscleSide.front;
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final dark = theme.brightness == Brightness.dark;
    final exercise = widget.exercise;
    final impacts = exercise.effectiveMuscleImpacts;
    final recovery = store.muscleRecoveryMap();
    final side = _side ?? _preferredSide(impacts);

    // Kolory zaangażowania: główne / pomocnicze / stabilizacja. Partie
    // zaangażowane i jednocześnie zmęczone (<60% regeneracji) — ostrzegawczo.
    const warnColor = Color(0xFFE08600);
    final primaryColor = theme.colorScheme.primary;
    final secondaryColor = const Color(0xFF58A6FF);
    final overrideColors = <BodyMuscle, Color>{};
    final engagedTired = <RecoveryWarning>[];
    for (final impact in impacts) {
      final state = recovery[impact.muscleGroup];
      final percent =
          (state != null && state.hasData) ? state.recoveryPercent : null;
      final tired = percent != null && percent < 60;
      final Color base;
      switch (impact.role) {
        case MuscleRole.primary:
          base = tired ? warnColor : primaryColor;
          overrideColors[impact.muscleGroup] = base.withValues(alpha: 0.85);
          break;
        case MuscleRole.secondary:
          base = tired ? warnColor : secondaryColor;
          overrideColors[impact.muscleGroup] = base.withValues(alpha: 0.55);
          break;
        case MuscleRole.stabilizer:
          base = tired ? warnColor : secondaryColor;
          overrideColors[impact.muscleGroup] = base.withValues(alpha: 0.3);
          break;
      }
      if (percent != null && percent < 60) {
        engagedTired.add(RecoveryWarning(
          muscle: impact.muscleGroup,
          recoveryPercent: percent,
          status: state?.status ?? RecoveryStatus.unknown,
          severe: percent < 40 && impact.role == MuscleRole.primary,
        ));
      }
    }
    engagedTired.sort((a, b) => a.recoveryPercent.compareTo(b.recoveryPercent));

    Widget legendChip(Color color, String label) => Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
                width: 12,
                height: 12,
                decoration:
                    BoxDecoration(color: color, shape: BoxShape.circle)),
            const SizedBox(width: 5),
            Flexible(
              child: Text(
                label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
            ),
          ],
        );

    final primaryLabels = [
      for (final impact in impacts)
        if (impact.role == MuscleRole.primary) impact.muscleGroup.label,
    ];
    final supportingLabels = [
      for (final impact in impacts)
        if (impact.role != MuscleRole.primary) impact.muscleGroup.label,
    ];

    return Card(
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.accessibility_new_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Mapa zaangażowanych mięśni',
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.titleMedium
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
                _BodySideToggle(
                    side: side, onChanged: (s) => setState(() => _side = s)),
              ],
            ),
            const SizedBox(height: 10),
            if (impacts.isEmpty)
              Text(
                'To ćwiczenie nie ma przypisanych partii mięśniowych.',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              )
            else ...[
              SizedBox(
                height: 230,
                child: AnimatedSwitcher(
                  duration: const Duration(milliseconds: 280),
                  child: BodyMuscleMap(
                    key: ValueKey('exercise_map_$side'),
                    side: side,
                    dark: dark,
                    recovery: recovery,
                    overrideColors: overrideColors,
                    onMuscleTap: (muscle) => showMuscleRecoverySheet(
                        context, muscle, recovery[muscle]),
                    onBackgroundTap: () => setState(
                      () => _side = side == BodyMuscleSide.front
                          ? BodyMuscleSide.back
                          : BodyMuscleSide.front,
                    ),
                  ),
                ),
              ),
              const SizedBox(height: 10),
              Wrap(
                spacing: 14,
                runSpacing: 8,
                children: [
                  legendChip(primaryColor.withValues(alpha: 0.85), 'Główne'),
                  legendChip(
                      secondaryColor.withValues(alpha: 0.55), 'Pomocnicze'),
                  legendChip(warnColor.withValues(alpha: 0.85), 'Zmęczone'),
                ],
              ),
              const SizedBox(height: 8),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  for (final label in primaryLabels)
                    MiniTag(text: 'Główna: $label'),
                  for (final label in supportingLabels.take(4))
                    MiniTag(text: label),
                ],
              ),
              if (engagedTired.isNotEmpty) ...[
                const SizedBox(height: 10),
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: (engagedTired.any((w) => w.severe)
                            ? theme.colorScheme.error
                            : warnColor)
                        .withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: (engagedTired.any((w) => w.severe)
                              ? theme.colorScheme.error
                              : warnColor)
                          .withValues(alpha: 0.5),
                    ),
                  ),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Icon(
                        Icons.warning_amber_rounded,
                        size: 18,
                        color: engagedTired.any((w) => w.severe)
                            ? theme.colorScheme.error
                            : warnColor,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          engagedTired.any((w) => w.severe)
                              ? 'To ćwiczenie mocno angażuje: ${engagedTired.take(3).map((w) => '${w.muscle.label} (${w.recoveryPercent.round()}%)').join(', ')} — te partie są jeszcze w regeneracji. Dziś lepiej je odpuść albo zrób lżejszą wersję.'
                              : 'Zaangażowane partie w regeneracji: ${engagedTired.take(3).map((w) => '${w.muscle.label} (${w.recoveryPercent.round()}%)').join(', ')}. Możesz wykonać ćwiczenie, ale zalecana niższa intensywność.',
                          style:
                              theme.textTheme.bodySmall?.copyWith(height: 1.35),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ],
          ],
        ),
      ),
    );
  }
}

/// Karta „Obraz AI" na stronie ćwiczenia: generuje ilustrację ćwiczenia przez
/// OpenAI (gpt-image-1 / dall-e-3). Wymaga klucza API — przy braku prosi o
/// niego w oknie dialogowym i zapisuje w ustawieniach (tylko lokalnie).
class ExerciseAiImageCard extends StatefulWidget {
  const ExerciseAiImageCard({super.key, required this.exercise});

  final Exercise exercise;

  @override
  State<ExerciseAiImageCard> createState() => _ExerciseAiImageCardState();
}

class _ExerciseAiImageCardState extends State<ExerciseAiImageCard> {
  bool _busy = false;

  /// Prosi o klucz API OpenAI i zapisuje go w ustawieniach. Zwraca true,
  /// gdy klucz jest dostępny (istniał albo został właśnie podany).
  Future<bool> _ensureApiKey(AppStore store) async {
    if (store.settings.openAiApiKey.trim().isNotEmpty) return true;
    final controller = TextEditingController();
    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Klucz API OpenAI'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Do generowania obrazów potrzebny jest Twój klucz API OpenAI '
              '(platform.openai.com → API keys). Klucz zostaje tylko na tym '
              'urządzeniu i jest wysyłany wyłącznie do OpenAI.',
            ),
            const SizedBox(height: 12),
            TextField(
              controller: controller,
              obscureText: true,
              autofocus: true,
              decoration: const InputDecoration(labelText: 'sk-...'),
            ),
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Zapisz klucz')),
        ],
      ),
    );
    final key = controller.text.trim();
    controller.dispose();
    if (saved != true || key.isEmpty) return false;
    await store.updateSettings(store.settings.copyWith(openAiApiKey: key));
    return true;
  }

  Future<void> _generate() async {
    final store = AppScope.read(context);
    if (_busy) return;
    final hasKey = await _ensureApiKey(store);
    if (!hasKey || !mounted) return;
    setState(() => _busy = true);
    try {
      await store.generateExerciseImageWithAi(widget.exercise);
      if (!mounted) return;
      showError(context, 'Obraz wygenerowany i przypisany do ćwiczenia.');
    } catch (error) {
      if (!mounted) return;
      showError(context, 'Nie udało się wygenerować obrazu: $error');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final hasKey = store.settings.openAiApiKey.trim().isNotEmpty;
    // Aktualna wersja ćwiczenia (mogła dostać świeżo wygenerowany obraz).
    final exercise =
        ExerciseRepo.byId(widget.exercise.id, store.customExercises);
    final hasGenerated = (exercise.imagePath ?? '').contains('exercise_images');
    return Card(
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text('Obraz AI (GPT)',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(
              hasGenerated
                  ? 'To ćwiczenie ma już obraz wygenerowany przez AI. Możesz wygenerować nowy — zastąpi obecny.'
                  : 'Wygeneruj ilustrację tego ćwiczenia modelem obrazów OpenAI. '
                      '${hasKey ? 'Klucz API jest zapisany w ustawieniach.' : 'Przy pierwszym użyciu podasz swój klucz API.'}',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
            const SizedBox(height: 10),
            FilledButton.tonalIcon(
              onPressed: _busy ? null : _generate,
              icon: _busy
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.auto_awesome_rounded),
              label: Text(_busy
                  ? 'Generowanie obrazu…'
                  : hasGenerated
                      ? 'Wygeneruj nowy obraz'
                      : 'Wygeneruj obraz (AI)'),
            ),
          ],
        ),
      ),
    );
  }
}

/// Prosi o klucz API Gemini i zapisuje go w ustawieniach (tylko lokalnie).
/// Zwraca true, gdy klucz jest dostępny (istniał albo został właśnie podany).
Future<bool> ensureGeminiApiKey(BuildContext context, AppStore store) async {
  if (store.settings.geminiApiKey.trim().isNotEmpty) return true;
  final controller = TextEditingController();
  final saved = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('Klucz API Gemini'),
      content: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Do generowania opisów ćwiczeń potrzebny jest Twój klucz API Google '
            'Gemini (aistudio.google.com → API keys). Klucz zostaje tylko na tym '
            'urządzeniu i jest wysyłany wyłącznie do Google.',
          ),
          const SizedBox(height: 12),
          TextField(
            controller: controller,
            obscureText: true,
            autofocus: true,
            decoration: const InputDecoration(labelText: 'AIza...'),
          ),
        ],
      ),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: const Text('Anuluj')),
        FilledButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Zapisz klucz')),
      ],
    ),
  );
  final key = controller.text.trim();
  controller.dispose();
  if (saved != true || key.isEmpty) return false;
  await store.updateSettings(store.settings.copyWith(geminiApiKey: key));
  return true;
}

/// Pokazuje edytowalny podgląd opisu wygenerowanego przez Gemini. Zwraca
/// zatwierdzoną (i ewentualnie zmienioną) treść albo null, gdy anulowano.
Future<GeneratedExerciseInfo?> showGeminiExercisePreviewSheet(
  BuildContext context, {
  required GeneratedExerciseInfo generated,
  required String exerciseName,
  bool hasExistingContent = false,
}) {
  return showModalBottomSheet<GeneratedExerciseInfo>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => _GeminiDescriptionPreviewSheet(
      generated: generated,
      exerciseName: exerciseName,
      hasExistingContent: hasExistingContent,
    ),
  );
}

/// Karta „Opis AI (Gemini)" na stronie ćwiczenia: generuje opis, instrukcję,
/// partie mięśniowe, wskazówki i błędy przez Gemini. Wynik trafia najpierw do
/// edytowalnego podglądu — nic nie zapisuje bez potwierdzenia użytkownika.
class ExerciseGeminiDescriptionCard extends StatefulWidget {
  const ExerciseGeminiDescriptionCard({super.key, required this.exercise});

  final Exercise exercise;

  @override
  State<ExerciseGeminiDescriptionCard> createState() =>
      _ExerciseGeminiDescriptionCardState();
}

class _ExerciseGeminiDescriptionCardState
    extends State<ExerciseGeminiDescriptionCard> {
  bool _busy = false;

  Future<void> _generate() async {
    if (_busy) return;
    final store = AppScope.read(context);
    // Zawsze bierz najświeższą wersję ćwiczenia (mogła być edytowana).
    final exercise =
        ExerciseRepo.byId(widget.exercise.id, store.customExercises);
    final hasKey = await ensureGeminiApiKey(context, store);
    if (!hasKey || !mounted) return;
    setState(() => _busy = true);
    GeneratedExerciseInfo generated;
    try {
      generated = await store.generateExerciseDescriptionWithGemini(exercise);
    } catch (error) {
      if (!mounted) return;
      setState(() => _busy = false);
      showError(context,
          'Nie udało się wygenerować opisu: ${friendlyAiErrorMessage(error)}');
      return;
    }
    if (!mounted) return;
    setState(() => _busy = false);
    final hasExisting = exercise.description.trim().isNotEmpty ||
        exercise.executionSteps.isNotEmpty ||
        exercise.tips.isNotEmpty;
    final approved = await showGeminiExercisePreviewSheet(
      context,
      generated: generated,
      exerciseName: exercise.name,
      hasExistingContent: hasExisting,
    );
    if (approved == null || !mounted) return;
    try {
      await store.applyGeneratedExerciseInfo(exercise, approved);
      if (!mounted) return;
      showError(context, 'Opis zapisany dla „${exercise.name}".');
    } catch (error) {
      if (!mounted) return;
      showError(context, 'Nie udało się zapisać opisu: $error');
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final hasKey = store.settings.geminiApiKey.trim().isNotEmpty;
    final exercise =
        ExerciseRepo.byId(widget.exercise.id, store.customExercises);
    final hasDescription = exercise.description.trim().isNotEmpty;
    return Card(
      clipBehavior: Clip.antiAlias,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_motion_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text('Opis AI (Gemini)',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(
              hasDescription
                  ? 'To ćwiczenie ma już opis. Możesz wygenerować nowy przez Gemini — '
                      'zobaczysz podgląd do edycji i zatwierdzenia przed zapisem.'
                  : 'Wygeneruj opis wykonania, instrukcję krok po kroku, partie '
                      'mięśniowe, wskazówki i częste błędy przez Google Gemini. '
                      '${hasKey ? 'Klucz API jest zapisany w ustawieniach.' : 'Przy pierwszym użyciu podasz swój klucz API.'}',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
            const SizedBox(height: 10),
            FilledButton.tonalIcon(
              onPressed: _busy ? null : _generate,
              icon: _busy
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(strokeWidth: 2))
                  : const Icon(Icons.auto_awesome_motion_rounded),
              label: Text(_busy
                  ? 'Generowanie opisu…'
                  : hasDescription
                      ? 'Wygeneruj nowy opis (Gemini)'
                      : 'Uzupełnij opis z Gemini'),
            ),
          ],
        ),
      ),
    );
  }
}

/// Edytowalny podgląd opisu wygenerowanego przez Gemini (Etap 2 — AI opisy).
class _GeminiDescriptionPreviewSheet extends StatefulWidget {
  const _GeminiDescriptionPreviewSheet({
    required this.generated,
    required this.exerciseName,
    required this.hasExistingContent,
  });

  final GeneratedExerciseInfo generated;
  final String exerciseName;
  final bool hasExistingContent;

  @override
  State<_GeminiDescriptionPreviewSheet> createState() =>
      _GeminiDescriptionPreviewSheetState();
}

class _GeminiDescriptionPreviewSheetState
    extends State<_GeminiDescriptionPreviewSheet> {
  late final TextEditingController _description;
  late final TextEditingController _steps;
  late final TextEditingController _primary;
  late final TextEditingController _secondary;
  late final TextEditingController _tips;
  late final TextEditingController _mistakes;
  late final TextEditingController _type;
  late final TextEditingController _equipment;
  late final TextEditingController _level;
  late final TextEditingController _safety;

  @override
  void initState() {
    super.initState();
    final g = widget.generated;
    _description = TextEditingController(text: g.description);
    _steps = TextEditingController(text: g.executionSteps.join('\n'));
    _primary = TextEditingController(text: g.primaryMuscles.join(', '));
    _secondary = TextEditingController(text: g.secondaryMuscles.join(', '));
    _tips = TextEditingController(text: g.tips.join('\n'));
    _mistakes = TextEditingController(text: g.commonMistakes.join('\n'));
    _type = TextEditingController(text: g.type);
    _equipment = TextEditingController(text: g.equipment);
    _level = TextEditingController(text: g.level);
    _safety = TextEditingController(text: g.safetyNotes.join('\n'));
  }

  @override
  void dispose() {
    _description.dispose();
    _steps.dispose();
    _primary.dispose();
    _secondary.dispose();
    _tips.dispose();
    _mistakes.dispose();
    _type.dispose();
    _equipment.dispose();
    _level.dispose();
    _safety.dispose();
    super.dispose();
  }

  List<String> _lines(String raw) => raw
      .split('\n')
      .map((line) => line.trim())
      .where((line) => line.isNotEmpty)
      .toList();

  List<String> _commaOrLines(String raw) => raw
      .split(RegExp(r'[\n,;]'))
      .map((item) => item.trim())
      .where((item) => item.isNotEmpty)
      .toList();

  void _save() {
    final result = GeneratedExerciseInfo(
      description: _description.text.trim(),
      executionSteps: _lines(_steps.text),
      primaryMuscles: _commaOrLines(_primary.text),
      secondaryMuscles: _commaOrLines(_secondary.text),
      tips: _lines(_tips.text),
      commonMistakes: _lines(_mistakes.text),
      type: _type.text.trim(),
      equipment: _equipment.text.trim(),
      level: _level.text.trim(),
      safetyNotes: _lines(_safety.text),
    );
    Navigator.of(context).pop(result);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Padding(
      padding: EdgeInsets.only(
        left: 16,
        right: 16,
        bottom: 16 + MediaQuery.of(context).viewInsets.bottom,
      ),
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_motion_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'Podgląd opisu AI',
                    style: theme.textTheme.titleLarge
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 4),
            Text(
              'Gemini · „${widget.exerciseName}". Sprawdź i popraw treść przed zapisem.',
              style: theme.textTheme.bodySmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
            if (widget.hasExistingContent) ...[
              const SizedBox(height: 10),
              Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: theme.colorScheme.primary.withValues(alpha: 0.1),
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                      color: theme.colorScheme.primary.withValues(alpha: 0.4)),
                ),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(Icons.info_outline_rounded,
                        size: 18, color: theme.colorScheme.primary),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'To ćwiczenie ma już opis. Po zapisaniu pola uzupełnione powyżej '
                        'zastąpią dotychczasowe. Puste pola zostawią obecną treść.',
                        style:
                            theme.textTheme.bodySmall?.copyWith(height: 1.35),
                      ),
                    ),
                  ],
                ),
              ),
            ],
            const SizedBox(height: 14),
            _field(_description, 'Opis wykonania', minLines: 3, maxLines: 6),
            _field(
                _steps, 'Instrukcja krok po kroku (każdy krok w nowej linii)',
                minLines: 3, maxLines: 8),
            _field(_primary, 'Główne mięśnie (oddziel przecinkiem)',
                minLines: 1, maxLines: 2),
            _field(_secondary, 'Mięśnie pomocnicze (oddziel przecinkiem)',
                minLines: 1, maxLines: 2),
            _field(_tips, 'Wskazówki techniczne (każda w nowej linii)',
                minLines: 2, maxLines: 6),
            _field(_mistakes, 'Najczęstsze błędy (każdy w nowej linii)',
                minLines: 2, maxLines: 6),
            Row(
              children: [
                Expanded(
                    child: _field(_type, 'Typ ćwiczenia',
                        minLines: 1, maxLines: 1)),
                const SizedBox(width: 10),
                Expanded(
                    child: _field(_level, 'Poziom', minLines: 1, maxLines: 1)),
              ],
            ),
            _field(_equipment, 'Sprzęt', minLines: 1, maxLines: 2),
            _field(_safety, 'Uwagi bezpieczeństwa (każda w nowej linii)',
                minLines: 1, maxLines: 4),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton(
                    onPressed: () => Navigator.of(context).pop(),
                    child: const Text('Anuluj'),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: FilledButton.icon(
                    onPressed: _save,
                    icon: const Icon(Icons.save_outlined),
                    label: const Text('Zapisz opis'),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _field(TextEditingController controller, String label,
      {int minLines = 1, int maxLines = 4}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: controller,
        minLines: minLines,
        maxLines: maxLines,
        decoration: InputDecoration(labelText: label),
      ),
    );
  }
}

