            }
            return Row(
              children: [
                Expanded(child: favoriteButton),
                const SizedBox(width: 10),
                Expanded(child: planButton),
              ],
            );
          },
        ),
      ),
    );
  }
}

Future<void> showAddExerciseToPlanSheet(
  BuildContext context,
  Exercise exercise,
) async {
  final hostContext = context;
  final store = AppScope.read(context);
  if (store.plans.isEmpty || store.plans.every((plan) => plan.days.isEmpty)) {
    showError(context, 'Najpierw utwórz plan z przynajmniej jednym dniem.');
    return;
  }

  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => FractionallySizedBox(
      heightFactor: 0.78,
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Text(
                  'Dodaj do planu',
                  style: Theme.of(sheetContext)
                      .textTheme
                      .titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900),
                ),
                const SizedBox(height: 4),
                Text(
                  'Wybierz dzień dla: ${exercise.name}',
                  style: Theme.of(sheetContext).textTheme.bodyMedium?.copyWith(
                        color:
                            Theme.of(sheetContext).colorScheme.onSurfaceVariant,
                      ),
                ),
              ],
            ),
          ),
          Expanded(
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
              children: [
                for (final plan in store.plans) ...[
                  Padding(
                    padding: const EdgeInsets.fromLTRB(4, 12, 4, 6),
                    child: Text(
                      plan.name,
                      style: Theme.of(sheetContext)
                          .textTheme
                          .titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900),
                    ),
                  ),
                  for (final day in plan.days)
                    Card(
                      margin: const EdgeInsets.only(bottom: 8),
                      child: Builder(
                        builder: (context) {
                          final alreadyAdded = day.items.any(
                            (item) => item.exerciseId == exercise.id,
                          );
                          return ListTile(
                            leading: CircleAvatar(
                              child: Text('${day.weekday}'),
                            ),
                            title: Text(
                              weekdayName(day.weekday),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                            subtitle: Text(
                              '${day.title} · ${day.items.length} ćwiczeń',
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                            ),
                            trailing: Icon(
                              alreadyAdded
                                  ? Icons.check_circle_rounded
                                  : Icons.add_circle_outline_rounded,
                              color: alreadyAdded
                                  ? Theme.of(context).colorScheme.primary
                                  : null,
                            ),
                            onTap: alreadyAdded
                                ? null
                                : () async {
                                    final added = await store.addExerciseToPlan(
                                      exerciseId: exercise.id,
                                      planId: plan.id,
                                      weekday: day.weekday,
                                    );
                                    if (!sheetContext.mounted) return;
                                    Navigator.of(sheetContext).pop();
                                    if (hostContext.mounted) {
                                      showError(
                                        hostContext,
                                        added
                                            ? 'Dodano ${exercise.name} do planu.'
                                            : 'Ćwiczenie jest już w tym dniu.',
                                      );
                                    }
                                  },
                          );
                        },
                      ),
                    ),
                ],
              ],
            ),
          ),
        ],
      ),
    ),
  );
}

