void analyzeFormDialog(BuildContext context, Exercise exercise) {
  final note = TextEditingController();
  showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      return Padding(
        padding: EdgeInsets.fromLTRB(
            16, 0, 16, 16 + MediaQuery.of(sheetContext).viewInsets.bottom),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('Analiza techniki: ${exercise.name}',
                style: Theme.of(context)
                    .textTheme
                    .titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 10),
            TextField(
                controller: note,
                maxLines: 4,
                decoration: const InputDecoration(
                    hintText:
                        'Opisz, co czujesz albo nagraj opis: np. przy przysiadzie czuję lędźwie, kolana uciekają do środka...')),
            const SizedBox(height: 12),
            FilledButton.icon(
              onPressed: () async {
                final store = AppScope.read(context);
                try {
                  final result =
                      await AiBackendService(store.settings.backendUrl)
                          .analyzeForm({
                    'exercise': exercise.name,
                    'notes': note.text,
                    'user': store.settings.toAiProfile(),
                  });
                  if (!context.mounted) return;
                  Navigator.pop(sheetContext);
                  showAiResultDialog(context, result);
                } catch (e) {
                  if (!context.mounted) return;
                  showError(context, e.toString());
                }
              },
              icon: const Icon(Icons.auto_awesome),
              label: const Text('Sprawdź przez AI'),
            ),
          ],
        ),
      );
    },
  );
}

class TrainingPlannerHeroCard extends StatefulWidget {
  const TrainingPlannerHeroCard({super.key});

  @override
  State<TrainingPlannerHeroCard> createState() =>
      _TrainingPlannerHeroCardState();
}

class _TrainingPlannerHeroCardState extends State<TrainingPlannerHeroCard> {
  double _timeCap = 0;
  String _equipmentMode = '';

  /// Dopasowanie na dziś (czas + sprzęt) jest zwinięte — to rzadkie wyjątki,
  /// a rozłożone zajmowały pół kafelka.
  bool _adjustOpen = false;

  String get _adjustLabel {
    final parts = <String>[
      if (_timeCap > 0) '${_timeCap.round()} min',
      if (_equipmentMode.isNotEmpty) 'inny sprzęt',
    ];
    return parts.isEmpty
        ? 'Dopasuj na dziś — czas, sprzęt'
        : 'Dopasowane: ${parts.join(' · ')}';
  }

  PlannedWorkout _resolve(AppStore store) {
    if (_timeCap <= 0 && _equipmentMode.isEmpty) {
      return store.plannedWorkoutForToday();
    }
    return store.simulatePlannedWorkout(
        timeCapMinutes: _timeCap, equipmentMode: _equipmentMode);
  }

  Future<void> _pickEquipment() async {
    final choice = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) {
        final options = <(String, String, IconData)>[
          ('', 'Mój zwykły sprzęt', Icons.check_circle_outline_rounded),
          (
            'bodyweight',
            'Masa własnego ciała',
            Icons.accessibility_new_rounded
          ),
          ('dumbbells', 'Hantle', Icons.fitness_center_rounded),
          (
            'barbell_dumbbells',
            'Sztanga i hantle',
            Icons.sports_gymnastics_rounded
          ),
          ('full_gym', 'Pełna siłownia', Icons.warehouse_rounded),
          ('outdoor', 'Trening na zewnątrz', Icons.park_rounded),
        ];
        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
                child: Text('Dostępny sprzęt na dziś',
                    style: Theme.of(sheetContext)
                        .textTheme
                        .titleMedium
                        ?.copyWith(fontWeight: FontWeight.w900)),
              ),
              for (final option in options)
                ListTile(
                  leading: Icon(option.$3),
                  title: Text(option.$2),
                  trailing: _equipmentMode == option.$1
                      ? const Icon(Icons.check_rounded)
                      : null,
                  onTap: () => Navigator.pop(sheetContext, option.$1),
                ),
            ],
          ),
        );
      },
    );
    if (choice != null && mounted) setState(() => _equipmentMode = choice);
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final planned = _resolve(store);
    final radius = BorderRadius.circular(uiCornerRadius(context, 24));
    final isSimulated = _timeCap > 0 || _equipmentMode.isNotEmpty;

    return Container(
      margin: const EdgeInsets.only(bottom: 16),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            scheme.primary.withValues(
                alpha: theme.brightness == Brightness.dark ? 0.24 : 0.16),
            scheme.primary.withValues(alpha: 0.04),
          ],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: radius,
        border: Border.all(color: scheme.primary.withValues(alpha: 0.30)),
      ),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // Nagłówek: etykieta + pewność rekomendacji.
            Row(
              children: [
                Icon(Icons.psychology_alt_rounded,
                    color: scheme.primary, size: 20),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    'DZISIEJSZY TRENING',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.labelMedium?.copyWith(
                      fontWeight: FontWeight.w900,
                      color: scheme.primary,
                      letterSpacing: 0.8,
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                _PlannerConfidencePill(confidence: planned.confidence),
              ],
            ),
            const SizedBox(height: 10),
            Text(planned.title,
                style: theme.textTheme.titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 2),
            Text(
              planned.subtitle,
              style: theme.textTheme.bodySmall?.copyWith(
                  color: scheme.onSurfaceVariant, fontWeight: FontWeight.w600),
            ),
            if (isSimulated) ...[
              const SizedBox(height: 8),
              Row(
                children: [
                  Icon(Icons.science_outlined,
                      size: 14, color: scheme.tertiary),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Text(
                      'Podgląd symulacji${_timeCap > 0 ? ' · limit ${_timeCap.round()} min' : ''}${_equipmentMode.isNotEmpty ? ' · inny sprzęt' : ''}',
                      style: theme.textTheme.labelSmall?.copyWith(
                          color: scheme.tertiary, fontWeight: FontWeight.w800),
                    ),
                  ),
                  TextButton(
                    onPressed: () => setState(() {
                      _timeCap = 0;
                      _equipmentMode = '';
                    }),
                    child: const Text('Reset'),
                  ),
                ],
              ),
            ],
            const SizedBox(height: 12),
            // Meta: czas / intensywność / gotowość / obciążenie.
            Wrap(
              spacing: 10,
              runSpacing: 8,
              children: [
                if (planned.forecast.setCount > 0)
                  _MetaPill(
                      icon: Icons.timer_outlined,
                      text: planned.forecast.minutesLabel),
                _MetaPill(
                    icon: Icons.speed_rounded,
                    text: planned.forecast.intensityLabel),
                if (planned.hasRecoveryData)
                  _MetaPill(
                      icon: Icons.favorite_rounded,
                      text: 'Gotowość ${planned.readinessPercent.round()}%'),
                _PlannerLoadPill(level: planned.load.level),
              ],
            ),
            // Prognoza wartości.
            if (planned.forecast.setCount > 0) ...[
              const SizedBox(height: 12),
              _PlannerForecastBox(forecast: planned.forecast),
            ],
            // Dlaczego ten trening.
            if (planned.reasonBullets.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text('Dlaczego ten trening',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              for (final bullet in planned.reasonBullets.take(3))
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Icon(Icons.check_circle_outline_rounded,
                          size: 15, color: scheme.primary),
                      const SizedBox(width: 8),
                      Expanded(
                          child: Text(bullet,
                              style: theme.textTheme.bodySmall
                                  ?.copyWith(height: 1.3))),
                    ],
                  ),
                ),
            ],
            // Ostrzeżenia Planera.
            for (final warning in planned.warnings.take(2)) ...[
              const SizedBox(height: 8),
              _PlannerWarningRow(text: warning),
            ],
            // Deload — reaktywna sugestia z historii. Milczy w trakcie
            // ZAPLANOWANEGO deloadu, żeby nie radzić odciążenia w tygodniu,
            // który już nim jest (osobny baner mówi o nim wprost).
            if (planned.deload.recommended &&
                !AppScope.of(context).deloadStatusToday.isDeload) ...[
              const SizedBox(height: 10),
              InkWell(
                onTap: () => showPlannerDeloadDialog(context, planned.deload),
                borderRadius: BorderRadius.circular(12),
                child: Container(
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: const Color(0xFFE08600).withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                        color: const Color(0xFFE08600).withValues(alpha: 0.4)),
                  ),
                  child: Row(
                    children: [
                      const Icon(Icons.trending_down_rounded,
                          size: 18, color: Color(0xFFE08600)),
                      const SizedBox(width: 8),
                      const Expanded(
                        child: Text('Rozważ lżejszy okres (deload)',
                            style: TextStyle(
                                fontWeight: FontWeight.w800,
                                color: Color(0xFFE08600))),
                      ),
                      Icon(Icons.chevron_right_rounded,
                          color:
                              const Color(0xFFE08600).withValues(alpha: 0.8)),
                    ],
                  ),
                ),
              ),
            ],
            const SizedBox(height: 14),
            // Akcje główne. Zamiast startu „w ciemno" prowadzimy do DNIA
            // Z PLANU — tam start jest jednoznaczny (osobny przycisk START).
            if (planned.isActionable) ...[
              const _ContinueProgramTile(),
              const SizedBox(height: 8),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: () => openPreWorkoutAnalysis(context,
                          planned: isSimulated ? planned : null),
                      icon: const Icon(Icons.analytics_outlined, size: 18),
                      label: const Text('Szczegóły'),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: () =>
                          showPlannerAlternativesSheet(context, planned),
                      icon: const Icon(Icons.swap_horiz_rounded, size: 18),
                      label: const Text('Alternatywa'),
                    ),
                  ),
                ],
              ),
            ] else ...[
              FilledButton.tonalIcon(
                onPressed: () => showPlannerAlternativesSheet(context, planned),
                icon: const Icon(Icons.swap_horiz_rounded),
                label: const Text('Wybierz trening'),
              ),
            ],
            // Dopasowanie na dziś (czas + sprzęt) — domyślnie ZWINIĘTE.
            const SizedBox(height: 10),
            InkWell(
              key: const Key('planner_adjust_toggle'),
              borderRadius: BorderRadius.circular(10),
              onTap: () => setState(() => _adjustOpen = !_adjustOpen),
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 6),
                child: Row(
                  children: [
                    Icon(Icons.tune_rounded,
                        size: 16, color: scheme.onSurfaceVariant),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        _adjustLabel,
                        style: theme.textTheme.labelLarge?.copyWith(
                            fontWeight: FontWeight.w800,
                            color: scheme.onSurfaceVariant),
                      ),
                    ),
                    Icon(
                        _adjustOpen
                            ? Icons.expand_less_rounded
                            : Icons.expand_more_rounded,
                        size: 20,
                        color: scheme.onSurfaceVariant),
                  ],
                ),
              ),
            ),
            if (_adjustOpen) ...[
              const SizedBox(height: 4),
              Text('Ile masz dziś czasu?',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  for (final minutes in const [15, 30, 45, 60])
                    ChoiceChip(
                      label: Text('$minutes min'),
                      selected: _timeCap == minutes.toDouble(),
                      onSelected: (_) => setState(() => _timeCap =
                          _timeCap == minutes.toDouble()
                              ? 0
                              : minutes.toDouble()),
                    ),
                  ChoiceChip(
                    label: const Text('60+ min'),
                    selected: _timeCap == 0,
                    onSelected: (_) => setState(() => _timeCap = 0),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              // Bieganie i regeneracja to też „co dziś robię zamiast planu",
              // więc mieszkają razem z czasem i sprzętem — a nie na wierzchu.
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  ActionChip(
                    avatar: const Icon(Icons.handyman_outlined, size: 16),
                    label: Text(_equipmentMode.isEmpty
                        ? 'Nie mam dziś sprzętu'
                        : 'Sprzęt: zmieniony'),
                    onPressed: _pickEquipment,
                  ),
                  ActionChip(
                    avatar: const Icon(Icons.directions_run_rounded, size: 16),
                    label: const Text('Chcę pobiegać'),
                    onPressed: () =>
                        Navigator.of(context).push(MaterialPageRoute<void>(
                      builder: (_) =>
                          const RunRecorderPage(type: TrainerActivityType.run),
                    )),
                  ),
                  ActionChip(
                    avatar:
                        const Icon(Icons.self_improvement_rounded, size: 16),
                    label: const Text('Regeneracja'),
                    onPressed: () => openMuscleRecoveryPage(context),
                  ),
                ],
              ),
            ],
            const SizedBox(height: 10),
            // Decyzje Planera — szeroki, jaśniejszy przycisk na samym końcu.
            SizedBox(
              width: double.infinity,
              child: FilledButton.tonalIcon(
                key: const Key('planner_decisions'),
                style: FilledButton.styleFrom(
                  backgroundColor:
                      scheme.surfaceContainerHighest.withValues(alpha: 0.7),
                  foregroundColor: scheme.onSurface,
                ),
                onPressed: () => _showPlannerDecisions(context, planned),
                icon: const Icon(Icons.info_outline_rounded, size: 18),
                label: const Text('Decyzje Planera'),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _showPlannerDecisions(
      BuildContext context, PlannedWorkout planned) async {
    await showModalBottomSheet<void>(
      context: context,
      useSafeArea: true,
      showDragHandle: true,
      isScrollControlled: true,
      builder: (sheetContext) {
        final theme = Theme.of(sheetContext);
        return DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.6,
          maxChildSize: 0.9,
          builder: (_, controller) => ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
            children: [
              Text('Dlaczego Planer podjął tę decyzję?',
                  style: theme.textTheme.titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 4),
              Row(
                children: [
                  Icon(Icons.verified_rounded,
                      size: 16, color: theme.colorScheme.primary),
                  const SizedBox(width: 6),
                  Text('Pewność rekomendacji: ${planned.confidencePercent}%',
                      style: theme.textTheme.bodyMedium
                          ?.copyWith(fontWeight: FontWeight.w800)),
                ],
              ),
              const SizedBox(height: 14),
              Text('Powód',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              for (final bullet in planned.reasonBullets)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [const Text('• '), Expanded(child: Text(bullet))],
                  ),
                ),
              const SizedBox(height: 14),
              Text('Obciążenie tygodnia',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              Text(planned.load.headline, style: theme.textTheme.bodyMedium),
              for (final signal in planned.load.signals)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 2),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      const Text('• '),
                      Expanded(
                          child: Text(signal, style: theme.textTheme.bodySmall))
                    ],
                  ),
                ),
              const SizedBox(height: 14),
              Text('Użyte dane',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  for (final input in planned.confidenceInputs)
                    Chip(label: Text(input, style: theme.textTheme.bodySmall))
                ],
              ),
              if (planned.missingData.isNotEmpty) ...[
                const SizedBox(height: 14),
                Text('Braki danych',
                    style: theme.textTheme.labelLarge
                        ?.copyWith(fontWeight: FontWeight.w900)),
                const SizedBox(height: 6),
                for (final missing in planned.missingData)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 2),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Icon(Icons.help_outline_rounded,
                            size: 15,
                            color: theme.colorScheme.onSurfaceVariant),
                        const SizedBox(width: 6),
                        Expanded(
                            child: Text(missing,
                                style: theme.textTheme.bodySmall?.copyWith(
                                    color:
                                        theme.colorScheme.onSurfaceVariant))),
                      ],
                    ),
                  ),
              ],
            ],
          ),
        );
      },
    );
  }
}

class _PlannerConfidencePill extends StatelessWidget {
  const _PlannerConfidencePill({required this.confidence});
  final double confidence;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final percent = (confidence * 100).round();
    final low = confidence < 0.5;
    final color = low ? const Color(0xFFE08600) : theme.colorScheme.primary;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.14),
        borderRadius: BorderRadius.circular(99),
        border: Border.all(color: color.withValues(alpha: 0.4)),
      ),
      child: Text('Pewność $percent%',
          style: theme.textTheme.labelSmall
              ?.copyWith(color: color, fontWeight: FontWeight.w900)),
    );
  }
}

