/// Ekran „Analiza przed treningiem" — pełny podgląd zestawu przed startem.
class PreWorkoutAnalysisPage extends StatelessWidget {
  const PreWorkoutAnalysisPage({super.key, this.preview});

  /// Wariant z symulacji (np. skrócony czas). Null → propozycja z cache.
  final PlannedWorkout? preview;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final planned = preview ?? store.plannedWorkoutForToday();
    final recovery = store.muscleRecoveryMap();
    final forecast = planned.forecast;

    return Scaffold(
      appBar: AppBar(title: const Text('Analiza przed treningiem')),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
          children: [
            Text(planned.title,
                style: theme.textTheme.headlineSmall
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 2),
            Text(planned.subtitle,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(color: scheme.onSurfaceVariant)),
            const SizedBox(height: 14),
            Wrap(
              spacing: 10,
              runSpacing: 8,
              children: [
                if (forecast.setCount > 0)
                  _MetaPill(
                      icon: Icons.timer_outlined, text: forecast.minutesLabel),
                _MetaPill(
                    icon: Icons.format_list_numbered_rounded,
                    text: '${planned.exercises.length} ćwiczeń'),
                _MetaPill(
                    icon: Icons.speed_rounded,
                    text: 'Intensywność: ${forecast.intensityLabel}'),
                if (planned.hasRecoveryData)
                  _MetaPill(
                      icon: Icons.favorite_rounded,
                      text: 'Gotowość ${planned.readinessPercent.round()}%'),
              ],
            ),
            if (forecast.setCount > 0) ...[
              const SizedBox(height: 14),
              _PlannerForecastBox(forecast: forecast),
            ],
            for (final warning in planned.warnings) ...[
              const SizedBox(height: 10),
              _PlannerWarningRow(text: warning),
            ],
            if (planned.mainMuscles.isNotEmpty) ...[
              const SizedBox(height: 18),
              const SectionHeader(title: 'Zaangażowane partie'),
              const SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  for (final muscle in planned.mainMuscles)
                    Builder(builder: (context) {
                      final state = recovery[muscle];
                      final percent = state?.recoveryPercent;
                      final ready = percent == null || percent >= 60;
                      final color =
                          ready ? scheme.primary : const Color(0xFFE08600);
                      return Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 10, vertical: 6),
                        decoration: BoxDecoration(
                          color: color.withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(12),
                          border:
                              Border.all(color: color.withValues(alpha: 0.35)),
                        ),
                        child: Text(
                          percent == null
                              ? muscle.label
                              : '${muscle.label} · ${percent.round()}%',
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: color, fontWeight: FontWeight.w800),
                        ),
                      );
                    }),
                ],
              ),
            ],
            if (planned.exercises.isNotEmpty) ...[
              const SizedBox(height: 18),
              const SectionHeader(title: 'Zaplanowane ćwiczenia'),
              const SizedBox(height: 8),
              for (final exercise in planned.exercises)
                Padding(
                  padding: const EdgeInsets.only(bottom: 10),
                  child: _PlannedExerciseCard(exercise: exercise),
                ),
            ] else ...[
              const SizedBox(height: 18),
              Container(
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: scheme.surfaceContainerHighest.withValues(alpha: 0.5),
                  borderRadius: BorderRadius.circular(16),
                ),
                child: Row(
                  children: [
                    Icon(Icons.self_improvement_rounded, color: scheme.primary),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text(
                        planned.reasonBullets.isEmpty
                            ? 'Planer proponuje dziś regenerację.'
                            : planned.reasonBullets.first,
                        style: theme.textTheme.bodyMedium,
                      ),
                    ),
                  ],
                ),
              ),
            ],
            if (planned.reasonBullets.isNotEmpty) ...[
              const SizedBox(height: 18),
              const SectionHeader(title: 'Uzasadnienie Planera'),
              const SizedBox(height: 8),
              for (final bullet in planned.reasonBullets)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 3),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Icon(Icons.check_circle_outline_rounded,
                          size: 16, color: scheme.primary),
                      const SizedBox(width: 8),
                      Expanded(
                          child: Text(bullet,
                              style: theme.textTheme.bodyMedium
                                  ?.copyWith(height: 1.3))),
                    ],
                  ),
                ),
            ],
          ],
        ),
      ),
      bottomNavigationBar: planned.isActionable && planned.exercises.isNotEmpty
          ? Material(
              elevation: 8,
              color: scheme.surface,
              child: SafeArea(
                top: false,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(16, 10, 16, 10),
                  child: Row(
                    children: [
                      if (planned.isProgramDay &&
                          planned.programId != null &&
                          planned.dayIndex != null)
                        Padding(
                          padding: const EdgeInsets.only(right: 10),
                          child: OutlinedButton.icon(
                            onPressed: () => openWorkoutDayDetails(
                                context, planned.programId!, planned.dayIndex!),
                            icon: const Icon(Icons.tune_rounded, size: 18),
                            label: const Text('Dostosuj'),
                          ),
                        ),
                      Expanded(
                        child: FilledButton.icon(
                          onPressed: () =>
                              startPlannedWorkout(context, planned),
                          icon: const Icon(Icons.play_arrow_rounded),
                          label: const Text('Rozpocznij trening'),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            )
          : null,
    );
  }
}

class _PlannedExerciseCard extends StatelessWidget {
  const _PlannedExerciseCard({required this.exercise});
  final PlannedExercise exercise;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final delta = exercise.weightDeltaKg;
    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: scheme.surfaceContainerHighest.withValues(alpha: 0.4),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(exercise.name,
                    style: theme.textTheme.titleSmall
                        ?.copyWith(fontWeight: FontWeight.w900)),
              ),
              if (exercise.isCalibrating)
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                      color: scheme.tertiary.withValues(alpha: 0.15),
                      borderRadius: BorderRadius.circular(10)),
                  child: Text('Kalibracja',
                      style: theme.textTheme.labelSmall?.copyWith(
                          color: scheme.tertiary, fontWeight: FontWeight.w800)),
                ),
            ],
          ),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            runSpacing: 6,
            children: [
              _MiniTagBox(
                  text: exercise.schemeLabel, icon: Icons.repeat_rounded),
              if (exercise.weightKg > 0)
                _MiniTagBox(
                    text: '${_plannerKg(exercise.weightKg)} kg',
                    icon: Icons.fitness_center_rounded),
              _MiniTagBox(
                  text: 'Przerwa ${exercise.restSeconds}s',
                  icon: Icons.timer_outlined),
              _MiniTagBox(
                  text: exercise.loadTypeLabel, icon: Icons.category_outlined),
            ],
          ),
          if (delta != null && delta.abs() >= 0.5) ...[
            const SizedBox(height: 8),
            Row(
              children: [
                Icon(
                    delta > 0
                        ? Icons.arrow_upward_rounded
                        : Icons.arrow_downward_rounded,
                    size: 14,
                    color:
                        delta > 0 ? scheme.primary : const Color(0xFFE08600)),
                const SizedBox(width: 4),
                Text(
                  '${delta > 0 ? '+' : ''}${_plannerKg(delta)} kg względem ostatniego treningu',
                  style: theme.textTheme.labelSmall?.copyWith(
                      color:
                          delta > 0 ? scheme.primary : const Color(0xFFE08600),
                      fontWeight: FontWeight.w800),
                ),
              ],
            ),
          ],
          if (exercise.primaryMuscles.isNotEmpty ||
              exercise.secondaryMuscles.isNotEmpty) ...[
            const SizedBox(height: 8),
            Text(
              [
                if (exercise.primaryMuscles.isNotEmpty)
                  'Główne: ${exercise.primaryMuscles.join(', ')}',
                if (exercise.secondaryMuscles.isNotEmpty)
                  'Pomocnicze: ${exercise.secondaryMuscles.join(', ')}',
              ].join(' · '),
              style: theme.textTheme.labelSmall
                  ?.copyWith(color: scheme.onSurfaceVariant),
            ),
          ],
          if (exercise.reasons.isNotEmpty) ...[
            const SizedBox(height: 8),
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Icon(Icons.lightbulb_outline_rounded,
                    size: 14, color: scheme.onSurfaceVariant),
                const SizedBox(width: 6),
                Expanded(
                    child: Text(exercise.reasons.first,
                        style: theme.textTheme.labelSmall?.copyWith(
                            color: scheme.onSurfaceVariant, height: 1.3))),
              ],
            ),
          ],
        ],
      ),
    );
  }
}

