/// Smukły baner „w toku": wznowienie aktywnej sesji albo kontynuacja
/// rozpoczętego programu — bez wielkiego kafelka z rozpiską planu.
class _ActiveProgramBanner extends StatelessWidget {
  const _ActiveProgramBanner();

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final session = store.activeWorkoutSession;
    // Baner wznawia WYŁĄCZNIE trening w toku. „Kontynuuj program" żyje
    // w karcie „Dzisiejszy trening" i idzie ZA PLANEM — osobny skrót do
    // ostatnio otwartego programu tylko kusił, żeby zejść z rozkładu.
    if (session == null) return const SizedBox.shrink();

    final title = 'Trening w toku';
    final subtitle = '${session.planName} · ${session.dayTitle}';
    const icon = Icons.play_circle_rounded;
    void onTap() => openActiveWorkoutPage(context);

    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(20),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [
                  theme.colorScheme.primary.withValues(alpha: 0.22),
                  theme.colorScheme.primary.withValues(alpha: 0.08),
                ],
                begin: Alignment.centerLeft,
                end: Alignment.centerRight,
              ),
