/// Ikony kafelków programów — mapowanie kluczy z katalogu (czysty Dart) na Material Icons.
IconData iconForProgramKey(String key) {
  switch (key) {
    case 'core':
      return Icons.grid_on;
    case 'chest':
      return Icons.fitness_center_rounded;
    case 'arms':
      return Icons.sports_mma;
    case 'shoulders':
      return Icons.accessibility_new_rounded;
    case 'back':
      return Icons.rowing;
    case 'forearms':
      return Icons.front_hand;
    case 'legs':
      return Icons.directions_run_rounded;
    default:
      return Icons.calendar_month_rounded;
  }
}

/// Ikony kafelków cardio.
IconData iconForCardioKey(String key) {
  switch (key) {
    case 'beginner':
      return Icons.emoji_people;
    case 'fat_burn':
      return Icons.local_fire_department_rounded;
    case 'endurance':
      return Icons.speed_rounded;
    case 'hiit':
      return Icons.bolt_rounded;
    case 'recovery':
      return Icons.spa_rounded;
    case 'after_strength':
      return Icons.fitness_center_rounded;
    case 'running':
      return Icons.directions_run_rounded;
    case 'walking':
      return Icons.directions_walk_rounded;
    case 'cycling':
      return Icons.directions_bike_rounded;
    default:
      return Icons.favorite_rounded;
  }
}

/// Sekcja kafelków programów 30-dniowych — układ zależny od personalizacji
/// (lista / siatka 2 kolumny / kompaktowe wiersze).
class _ProgramTilesSection extends StatelessWidget {
  const _ProgramTilesSection({required this.layout});

  final String layout;

  @override
  Widget build(BuildContext context) {
    if (layout == 'grid') {
      return LayoutBuilder(
        builder: (context, constraints) {
          // Na bardzo wąskich ekranach siatka spada do jednej kolumny (bez overflow).
          final columns = constraints.maxWidth >= 340 ? 2 : 1;
          final width = columns == 2
              ? (constraints.maxWidth - 12) / 2
              : constraints.maxWidth;
          return Wrap(
            spacing: 12,
            runSpacing: 12,
            children: [
              for (final meta in kWorkoutProgramCatalog)
                SizedBox(
                    width: width,
                    child:
                        _ProgramTile(meta: meta, variant: _TileVariant.grid)),
            ],
          );
        },
      );
    }
    final variant =
        layout == 'compact' ? _TileVariant.compact : _TileVariant.list;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final meta in kWorkoutProgramCatalog)
          Padding(
            padding: EdgeInsets.only(
                bottom: variant == _TileVariant.compact ? 8 : 12),
            child: _ProgramTile(meta: meta, variant: variant),
          ),
      ],
    );
  }
}

enum _TileVariant { list, grid, compact }

/// Nowoczesny kafelek programu 30-dniowego: gradient, ikona, poziom,
/// typ treningu, partie mięśniowe i pasek postępu.
class _ProgramTile extends StatelessWidget {
  const _ProgramTile({required this.meta, required this.variant});

  final WorkoutProgramMeta meta;
  final _TileVariant variant;

  Future<void> _open(BuildContext context) async {
    final started = await startCatalogProgram(context, meta.id);
    if (!context.mounted) return;
    await openWorkoutProgram(context, started.id);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final useGradients = store.settings.useGradients;
    final accent = Color(meta.accentColor);
    final plan = findCatalogPlan(store, meta.id);
    final started = plan != null;
    final completed = plan?.completedCount ?? 0;
    final progress =
        plan == null || plan.days.isEmpty ? 0.0 : completed / plan.days.length;
    final levelLabel = plan?.level.isNotEmpty == true
        ? plan!.level
        : normalizeTrainingLevel(store.settings.level);
    final radius = BorderRadius.circular(uiCornerRadius(context, 24));
    // Dopasowanie programu do profilu treningowego (poziom/tryb/sprzęt/ograniczenia).
    final recommendation = recommendProgram(meta, programUserProfileFor(store));

    if (variant == _TileVariant.compact) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: () => _open(context),
          borderRadius: radius,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: _tileDecoration(theme, accent, radius, useGradients),
            child: Row(
              children: [
                _tileVisual(plan, accent, 38, 20),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(meta.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      Text(
                        started
                            ? '$completed/${plan.days.length} dni · $levelLabel'
                            : '${meta.durationDays} dni · ${meta.kind} · $levelLabel',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.bodySmall?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant),
                      ),
                    ],
                  ),
                ),
                if (recommendation.isRecommended) ...[
                  Icon(Icons.verified_rounded, size: 16, color: accent),
                  const SizedBox(width: 6),
                ],
                if (started)
                  Text('${(progress * 100).round()}%',
                      style: theme.textTheme.labelLarge?.copyWith(
                          color: accent, fontWeight: FontWeight.w900))
                else
                  Icon(Icons.chevron_right_rounded,
                      color: theme.colorScheme.onSurfaceVariant),
              ],
            ),
          ),
        ),
      );
    }

    final isGrid = variant == _TileVariant.grid;
    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () => _open(context),
        borderRadius: radius,
        child: Container(
          padding: EdgeInsets.all(isGrid ? 14 : 16),
          decoration: _tileDecoration(theme, accent, radius, useGradients),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  _tileVisual(plan, accent, isGrid ? 42 : 52, isGrid ? 22 : 27),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Align(
                      alignment: Alignment.centerRight,
                      child: FittedBox(
                        fit: BoxFit.scaleDown,
                        // Długość programu jest ODZNAKĄ, a nie częścią nazwy —
                        // przy rozpoczętym programie stoi zaraz za statusem.
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            if (started) ...[
                              _TileBadge(
                                  text: completed >= (plan.days.length)
                                      ? 'UKOŃCZONY'
                                      : 'W TOKU',
                                  color: accent),
                              const SizedBox(width: 6),
                            ],
                            _TileBadge(
                                text: '${meta.durationDays} DNI',
                                color: accent),
                          ],
                        ),
                      ),
                    ),
                  ),
                ],
              ),
              SizedBox(height: isGrid ? 10 : 12),
              Text(
                meta.title,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: (isGrid
                        ? theme.textTheme.titleSmall
                        : theme.textTheme.titleMedium)
                    ?.copyWith(fontWeight: FontWeight.w900),
              ),
              const SizedBox(height: 3),
              Text(
                meta.subtitle,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
              SizedBox(height: isGrid ? 8 : 10),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  if (recommendation.isRecommended)
                    _TileChip(
                        icon: Icons.verified_rounded,
                        text: 'Dla Twojego profilu',
                        color: accent),
                  _TileChip(
                      icon: Icons.workspace_premium_outlined,
                      text: levelLabel,
                      color: accent),
                  _TileChip(
                      icon: Icons.category_outlined,
                      text: meta.kind,
                      color: accent),
                  if (!isGrid)
                    _TileChip(
                        icon: Icons.fitness_center_rounded,
                        text: meta.mainMuscles.take(3).join(' · '),
                        color: accent),
                  // Powody dopasowania (bez pierwszego — poziom już jest chipem).
                  for (final reason
                      in recommendation.reasons.skip(1).take(isGrid ? 1 : 2))
                    _TileChip(
                        icon: Icons.tune_rounded, text: reason, color: accent),
                  if (recommendation.primaryCaution.isNotEmpty)
                    _TileChip(
                        icon: Icons.info_outline_rounded,
                        text: recommendation.primaryCaution,
                        color: theme.colorScheme.tertiary),
                ],
              ),
              if (started) ...[
                SizedBox(height: isGrid ? 10 : 12),
                Row(
                  children: [
                    Expanded(
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(6),
                        child: LinearProgressIndicator(
                          value: progress,
                          minHeight: 7,
                          color: accent,
                          backgroundColor: accent.withValues(alpha: 0.15),
                        ),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Text('$completed/${plan.days.length}',
                        style: theme.textTheme.labelMedium
                            ?.copyWith(fontWeight: FontWeight.w800)),
                  ],
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }

  BoxDecoration _tileDecoration(
      ThemeData theme, Color accent, BorderRadius radius, bool useGradients) {
    final isDark = theme.brightness == Brightness.dark;
    return BoxDecoration(
      gradient: useGradients
          ? LinearGradient(
              colors: [
                accent.withValues(alpha: isDark ? 0.20 : 0.14),
                accent.withValues(alpha: isDark ? 0.06 : 0.03),
              ],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            )
          : null,
      color: useGradients ? null : theme.cardTheme.color,
      borderRadius: radius,
      border: Border.all(color: accent.withValues(alpha: isDark ? 0.35 : 0.28)),
    );
  }

  Widget _tileIcon(Color accent, double size, double iconSize) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [
            accent.withValues(alpha: 0.9),
            accent.withValues(alpha: 0.55)
          ],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(size * 0.32),
      ),
      child: Icon(iconForProgramKey(meta.iconKey),
          color: Colors.white, size: iconSize),
    );
  }

  /// Wizual kafelka: OKŁADKA programu (jeśli ustawiona — AI/galeria/aparat),
  /// inaczej dotychczasowa ikona na gradiencie. Okładka nie zmienia układu —
  /// wypełnia ten sam kwadrat co ikona.
  Widget _tileVisual(
      WorkoutPlan? plan, Color accent, double size, double iconSize) {
    final coverPath = plan?.media?.effectivePath ?? '';
    if (coverPath.isEmpty) return _tileIcon(accent, size, iconSize);
    return ClipRRect(
      borderRadius: BorderRadius.circular(size * 0.32),
      child: SizedBox(
        width: size,
        height: size,
        child: buildExerciseMediaImage(
          coverPath,
          fit: BoxFit.cover,
          fallback: _tileIcon(accent, size, iconSize),
        ),
      ),
    );
  }
}

