/// Startuje kafelek cardio: buduje (lub wznawia) jednodniowy plan cardio,
/// ustawia go jako aktywny i otwiera rozpiskę dnia. Ukończony wcześniej
/// trening cardio jest zerowany, żeby dało się go powtórzyć od razu.
Future<void> startCardioWorkout(
    BuildContext context, CardioWorkoutMeta meta) async {
  final store = AppScope.read(context);
  WorkoutPlan? plan;
  for (final existing in store.plans) {
    if (existing.id == meta.id) {
      plan = existing;
      break;
    }
  }
  if (plan == null) {
    plan = buildCardioWorkout(
      meta,
      resolveExercise: (id) => ExerciseRepo.byId(id, store.customExercises),
    ).copyWith(isActive: true);
    await store.addWorkoutPlan(plan);
  } else if (plan.completedDays.isNotEmpty) {
    plan = plan.copyWith(completedDays: <int>{}, isActive: true);
    await store.updateWorkoutPlan(plan);
  } else {
    await store.setActiveWorkoutPlan(plan.id);
  }
  if (!context.mounted) return;
  await openWorkoutDayDetails(context, plan.id, 0);
}

