/// odznakę: przez [kWarmupFreshness] odblokowuje ciężkie dni tej partii.
class _WarmupTile extends StatelessWidget {
  const _WarmupTile(
      {required this.meta, required this.compact, this.stretch = false});

  /// Kafelek rozciągania startuje zestaw rozciągania zamiast rozgrzewki.
  final bool stretch;

  final WarmupWorkoutMeta meta;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final useGradients = store.settings.useGradients;
    final accent = Color(meta.accentColor);
    final isDark = theme.brightness == Brightness.dark;
    final fresh = store.hasFreshWarmup(meta.id);
    final radius = BorderRadius.circular(uiCornerRadius(context, 22));

    final decoration = BoxDecoration(
      gradient: useGradients
          ? LinearGradient(
              colors: [
                accent.withValues(alpha: isDark ? 0.22 : 0.15),
                accent.withValues(alpha: isDark ? 0.07 : 0.04),
              ],
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
            )
          : null,
      color: useGradients ? null : theme.cardTheme.color,
      borderRadius: radius,
      border: Border.all(color: accent.withValues(alpha: isDark ? 0.35 : 0.28)),
    );

    if (compact) {
      return Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: () => stretch
              ? startStretchWorkout(context, meta)
              : startWarmupWorkout(context, meta),
          borderRadius: radius,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            decoration: decoration,
            child: Row(
              children: [
                Icon(iconForProgramKey(meta.iconKey), color: accent, size: 24),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(meta.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      Text(
                        fresh
                            ? 'Ukończona — ciężki dzień odblokowany'
                            : '~${meta.estimatedMinutes} min · odblokowuje ciężki dzień',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.bodySmall?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant),
                      ),
                    ],
                  ),
                ),
                Icon(
                    fresh
                        ? Icons.check_circle_rounded
                        : Icons.play_arrow_rounded,
                    color: accent),
              ],
            ),
          ),
        ),
      );
    }

    return Material(
      color: Colors.transparent,
      child: InkWell(
        onTap: () => startWarmupWorkout(context, meta),
        borderRadius: radius,
        child: Container(
          padding: const EdgeInsets.all(14),
          decoration: decoration,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Container(
                    width: 40,
                    height: 40,
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        colors: [
                          accent.withValues(alpha: 0.9),
                          accent.withValues(alpha: 0.55)
                        ],
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                      ),
                      borderRadius: BorderRadius.circular(13),
                    ),
                    child: Icon(iconForProgramKey(meta.iconKey),
                        color: Colors.white, size: 22),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Align(
                      alignment: Alignment.centerRight,
                      child: FittedBox(
                        fit: BoxFit.scaleDown,
                        child: fresh
                            ? _TileBadge(text: 'UKOŃCZONA', color: accent)
                            : _TileBadge(
                                text: '~${meta.estimatedMinutes} MIN',
                                color: accent),
                      ),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              Text(meta.title,
                  maxLines: 2,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 3),
              Text(
                meta.subtitle,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
              const SizedBox(height: 10),
              Row(
                children: [
                  Icon(
                      fresh
                          ? Icons.check_circle_rounded
                          : Icons.schedule_rounded,
                      size: 14,
                      color: accent),
                  const SizedBox(width: 4),
                  Expanded(
                    child: Text(
                      fresh
                          ? 'Ciężki dzień odblokowany'
                          : '~${meta.estimatedMinutes} min',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: theme.textTheme.labelMedium
                          ?.copyWith(fontWeight: FontWeight.w800),
                    ),
                  ),
                  Icon(Icons.play_circle_fill_rounded, color: accent, size: 26),
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// Startuje kafelek rozgrzewki: buduje (lub wznawia) jednodniowy program
/// rozgrzewkowy dopasowany do sprzętu, ustawia go jako aktywny i otwiera
/// rozpiskę dnia. Ukończona wcześniej rozgrzewka jest zerowana — można ją
/// od razu powtórzyć (np. przed kolejnym ciężkim dniem).
/// Startuje zestaw ROZCIĄGANIA (te same tory co rozgrzewki: zapis planu,
/// zamienniki sprzętowe, wznawianie po id).
Future<void> startStretchWorkout(
        BuildContext context, WarmupWorkoutMeta meta) =>
    startWarmupWorkout(context, meta, stretch: true);

Future<void> startWarmupWorkout(BuildContext context, WarmupWorkoutMeta meta,
    {bool stretch = false}) async {
  final store = AppScope.read(context);
  WorkoutPlan? plan;
  for (final existing in store.plans) {
    if (existing.id == meta.id) {
      plan = existing;
      break;
    }
  }
  if (plan == null) {
    // Jak programy 30-dniowe: pozycje bez posiadanego sprzętu dostają zamienniki.
    final base = stretch
        ? buildStretchWorkout(meta,
            resolveExercise: _programExerciseResolver(store))
        : buildWarmupWorkout(meta,
            resolveExercise: _programExerciseResolver(store));
    plan = applyEquipmentToPlan(
      base,
      store.settings.equipmentProfile,
      store.settings.limitationProfile,
      _programExerciseResolver(store),
    ).plan.copyWith(isActive: true);
    await store.addWorkoutPlan(plan);
  } else if (plan.completedDays.isNotEmpty) {
    plan = plan.copyWith(completedDays: <int>{}, isActive: true);
    await store.updateWorkoutPlan(plan);
  } else {
    await store.setActiveWorkoutPlan(plan.id);
  }
  if (!context.mounted) return;
  await openWorkoutDayDetails(context, plan.id, 0);
}

/// Bramka rozgrzewki: CIĘŻKI dzień programu ([WorkoutDayKind.isHeavy]) można
/// zacząć tylko ze świeżo ukończonym programem rozgrzewkowym partii.
/// Zwraca true, gdy trening może wystartować. W razie blokady proponuje
/// przejście prosto do właściwej rozgrzewki.
Future<bool> ensureWarmupBeforeHeavyDay(
  BuildContext context, {
  required WorkoutPlan plan,
  required WorkoutDay day,
}) async {
  if (!day.kind.isHeavy) return true;
  final store = AppScope.read(context);
  final warmup = warmupWorkoutForPlan(plan.id);
  // Plan spoza katalogu — nie wiadomo, którą partię rozgrzewać; nie blokujemy.
  if (warmup == null) return true;
  if (store.hasFreshWarmup(warmup.id)) return true;
  // W tygodniu deloadu dzień jest odciążony, więc rozgrzewka zostaje SUGESTIĄ,
  // a nie twardą bramką — nadal ją proponujemy (odciążony dzień też jej chce),
  // ale można wejść od razu.
  final isDeload = store.deloadStatusToday.isDeload;
  final choice = await showDialog<String>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: Text(isDeload ? 'Rozgrzewka w deloadzie' : 'Najpierw rozgrzewka'),
      content: Text(
        isDeload
            ? 'To dzień deloadu — obciążenie jest zmniejszone, ale krótka '
                'rozgrzewka nadal się przyda: ${warmup.title} '
                '(~${warmup.estimatedMinutes} min).'
            : 'To ciężki dzień siłowy. Zanim zaczniesz, wykonaj: '
                '${warmup.title} (~${warmup.estimatedMinutes} min).\n\n'
                'Ukończona rozgrzewka odblokowuje ciężkie dni tej partii na '
                '${kWarmupFreshness.inHours} godz.',
      ),
      actions: [
        TextButton(
            onPressed: () => Navigator.pop(dialogContext, 'cancel'),
            child: const Text('Anuluj')),
        if (isDeload)
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, 'skip'),
              child: const Text('Zacznij mimo to')),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, 'warmup'),
          child: const Text('Rozpocznij rozgrzewkę'),
        ),
      ],
    ),
  );
  if (choice == 'skip') return true;
  if (choice == 'warmup' && context.mounted) {
    await startWarmupWorkout(context, warmup);
  }
  return false;
}

enum _ActiveWorkoutConflictAction { resume, replace }

Future<void> openActiveWorkoutPage(BuildContext context) async {
  if (AppScope.read(context).activeWorkoutSession == null) return;
  await Navigator.of(context).push(
    MaterialPageRoute<void>(
      // Etap 30: pełnoekranowy tryb „Aktywne ćwiczenie".
      builder: (_) => const ActiveExercisePlayerPage(),
    ),
  );
}

/// Etap 30: szczegółowy widok treningu (serie, ciężar, RPE, lista, rozgrzewka).
/// Dostępny z menu pełnoekranowego odtwarzacza jako „wysuwana sekcja danych siłowych".
Future<void> openDetailedWorkoutView(BuildContext context) async {
  if (AppScope.read(context).activeWorkoutSession == null) return;
  await Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => const ActiveWorkoutPage(),
    ),
  );
}

Future<void> startWorkoutFromActivePlan(
  BuildContext context,
  WorkoutPlan plan,
) async {
  final store = AppScope.read(context);
  if (store.activeWorkoutSession != null) {
    await openActiveWorkoutPage(context);
    return;
  }
  WorkoutDay? today;
  for (final day in plan.days) {
    if (day.weekday == DateTime.now().weekday && day.items.isNotEmpty) {
      today = day;
      break;
    }
  }
  if (today != null) {
    await startWorkoutForDay(context, plan: plan, day: today);
    return;
  }
  final availableDays = plan.days.where((day) => day.items.isNotEmpty).toList();
  if (availableDays.isEmpty) {
    showError(context, 'Dodaj ćwiczenia do planu przed rozpoczęciem treningu.');
    return;
  }
  final selectedDay = await showModalBottomSheet<WorkoutDay>(
    context: context,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => Padding(
      padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text('Wybierz dzień treningowy',
              style: Theme.of(sheetContext)
                  .textTheme
                  .titleLarge
                  ?.copyWith(fontWeight: FontWeight.w900)),
          const SizedBox(height: 10),
          ConstrainedBox(
            constraints: BoxConstraints(
                maxHeight: MediaQuery.sizeOf(sheetContext).height * 0.6),
            child: ListView(
              shrinkWrap: true,
              children: [
                for (final day in availableDays)
                  ListTile(
                    leading: CircleAvatar(child: Text('${day.weekday}')),
                    title: Text(weekdayName(day.weekday)),
                    subtitle:
                        Text('${day.title} · ${day.items.length} ćwiczeń'),
                    trailing: const Icon(Icons.play_arrow_rounded),
                    onTap: () => Navigator.pop(sheetContext, day),
                  ),
              ],
            ),
          ),
        ],
      ),
    ),
  );
  if (context.mounted && selectedDay != null) {
    await startWorkoutForDay(context, plan: plan, day: selectedDay);
  }
}

Future<void> startWorkoutForDay(
  BuildContext context, {
  required WorkoutPlan plan,
  required WorkoutDay day,
  int? dayIndex,
}) async {
  final store = AppScope.read(context);
  if (day.items.isEmpty) {
    showError(context, 'Ten dzień nie ma jeszcze ćwiczeń.');
    return;
  }
  // Bramka rozgrzewki: CIĘŻKI dzień programu można zacząć tylko ze świeżo
  // ukończoną rozgrzewką partii — generator nie daje mu rozgrzewki inline.
  final warmedUp =
      await ensureWarmupBeforeHeavyDay(context, plan: plan, day: day);
  if (!warmedUp || !context.mounted) return;
  final existing = store.activeWorkoutSession;
  if (existing != null) {
    final action = await showDialog<_ActiveWorkoutConflictAction>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Trening już trwa'),
        content: Text(
            'Masz zapisaną sesję „${existing.planName} · ${existing.dayTitle}”. Możesz ją wznowić albo potwierdzić rozpoczęcie nowej.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Anuluj')),
          OutlinedButton(
            onPressed: () => Navigator.pop(
                dialogContext, _ActiveWorkoutConflictAction.resume),
            child: const Text('Wznów'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(
                dialogContext, _ActiveWorkoutConflictAction.replace),
            child: const Text('Porzuć i rozpocznij'),
          ),
        ],
      ),
    );
    if (!context.mounted || action == null) return;
    if (action == _ActiveWorkoutConflictAction.resume) {
      await openActiveWorkoutPage(context);
      return;
    }
    await store.discardActiveWorkout();
  }
  if (!context.mounted) return;
  // Ostrzeżenie o regeneracji przed startem zestawu (mocno zmęczone partie → potwierdzenie).
  final dayExercises = [
    for (final item in day.items)
      ExerciseRepo.byId(item.exerciseId, store.customExercises)
  ];
  final canStart = await confirmRecoveryBeforeStart(context, dayExercises);
  if (!canStart || !context.mounted) return;
  final started =
      await store.startActiveWorkout(plan: plan, day: day, dayIndex: dayIndex);
  if (!context.mounted) return;
  if (!started) {
    showError(context, 'Nie udało się rozpocząć pustego treningu.');
    return;
  }
  await openActiveWorkoutPage(context);
}

class ActiveWorkoutPage extends StatefulWidget {
  const ActiveWorkoutPage({super.key});

  @override
  State<ActiveWorkoutPage> createState() => _ActiveWorkoutPageState();
}

class _ActiveWorkoutPageState extends State<ActiveWorkoutPage> {
  final weight = TextEditingController();
  final repetitions = TextEditingController();
  Timer? timer;
  int rpe = 7;
  String? loadedExerciseId;
  int? loadedExerciseIndex;
  bool leaving = false;

  @override
  void initState() {
    super.initState();
    timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    timer?.cancel();
    weight.dispose();
    repetitions.dispose();
    super.dispose();
  }

  void syncFields(ActiveWorkoutSession session) {
    final exercise = session.currentExercise;
    if (exercise == null) return;
    if (loadedExerciseId == exercise.exerciseId &&
        loadedExerciseIndex == session.currentExerciseIndex) return;
    loadedExerciseId = exercise.exerciseId;
    loadedExerciseIndex = session.currentExerciseIndex;
    final lastSet =
        exercise.completedSets.isEmpty ? null : exercise.completedSets.last;
    weight.text =
        _formatPlanWeight(lastSet?.weightKg ?? exercise.suggestedWeightKg);
    repetitions.text = '${lastSet?.repetitions ?? exercise.plannedReps}';
    rpe = lastSet?.rpe ?? 7;
  }

  /// Powrót do uproszczonego widoku (pełnoekranowego odtwarzacza).
  /// Nie przerywa treningu — stan sesji żyje w [AppStore] i jest zachowany.
  void backToSimpleView() {
    leaving = true;
    Navigator.of(context).pop();
  }

  Future<void> saveSet(AppStore store) async {
    final parsedWeight =
        double.tryParse(weight.text.trim().replaceAll(',', '.'));
    final parsedRepetitions = int.tryParse(repetitions.text.trim());
    if (parsedWeight == null || parsedWeight < 0 || parsedWeight > 9999) {
      showError(context, 'Podaj poprawny ciężar.');
      return;
    }
    if (parsedRepetitions == null ||
        parsedRepetitions < 1 ||
        parsedRepetitions > 999) {
      showError(context, 'Powtórzenia muszą mieścić się w zakresie 1–999.');
      return;
    }
    final saved = await store.saveActiveWorkoutSet(
      weightKg: parsedWeight,
      repetitions: parsedRepetitions,
      rpe: rpe,
    );
    if (!mounted) return;
    if (!saved) {
      showError(context, 'Wszystkie zaplanowane serie są już zapisane.');
      return;
    }
    // Ostatnia seria całego treningu zapisana w widoku szczegółowym →
    // bezpośrednio podsumowanie (bez pustego odpoczynku i bez dialogu).
    if (store.isActiveWorkoutComplete) await _finishToSummary(store);
  }

  /// Kończy trening i przechodzi do podsumowania bez dialogu potwierdzenia
  /// (używane, gdy trening został normalnie ukończony w całości).
  Future<void> _finishToSummary(AppStore store) async {
    final session = store.activeWorkoutSession;
    if (session == null) return;
    final summary = await store.finishActiveWorkout();
    if (!mounted || summary == null) return;
    leaving = true;
    await Navigator.of(context).pushReplacement(
      MaterialPageRoute<void>(
        builder: (_) => WorkoutSummaryPage(summary: summary),
      ),
    );
  }

  Future<void> finishWorkout(AppStore store) async {
    final session = store.activeWorkoutSession;
    if (session == null) return;
    if (session.completedSetCount == 0) {
      showError(context,
          'Zapisz przynajmniej jedną serię przed zakończeniem treningu.');
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Zakończyć trening?'),
        content: Text(
            'Zapiszesz ${session.completedSetCount} serii w historii treningów.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Wróć')),
          FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Zakończ')),
        ],
      ),
    );
    if (confirmed != true) return;
    final summary = await store.finishActiveWorkout();
    if (!mounted || summary == null) return;
    leaving = true;
    await Navigator.of(context).pushReplacement(
      MaterialPageRoute<void>(
        builder: (_) => WorkoutSummaryPage(summary: summary),
      ),
    );
  }

  bool _resumePromptShowing = false;

  Future<void> _togglePause(AppStore store) async {
    if (store.isWorkoutPaused) {
      await store.resumeWorkout();
    } else {
      await store.pauseWorkout();
    }
  }

  /// Okno wznowienia treningu (po wyjściu z aplikacji albo po restarcie z
  /// niedokończonym treningiem). Postęp serii ZAWSZE zostaje zachowany.
  Future<void> _handleResumePrompt(AppStore store) async {
    if (_resumePromptShowing) return;
    _resumePromptShowing = true;
    final coldStart = store.workoutResumeColdStart;
    final session = store.activeWorkoutSession;
    final setCount = session?.completedSetCount ?? 0;
    final choice = await showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder: (dialogContext) => AlertDialog(
        title: Text(coldStart
            ? 'Znaleziono niedokończony trening'
            : 'Trening wstrzymany'),
        content: Text(coldStart
            ? 'Masz zapisany niedokończony trening ($setCount serii). Wykonane serie zostają w historii — co chcesz zrobić?'
            : 'Trening został wstrzymany po wyjściu z aplikacji. Czas spędzony poza aplikacją nie został policzony jako trening.'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, 'partial'),
            child: const Text('Zakończ jako częściowy'),
          ),
          if (coldStart)
            TextButton(
              onPressed: () => Navigator.pop(dialogContext, 'discard'),
              child: const Text('Odrzuć'),
            ),
          FilledButton(
            onPressed: () => Navigator.pop(dialogContext, 'resume'),
            child: Text(coldStart ? 'Wznów od ostatniej serii' : 'Kontynuuj'),
          ),
        ],
      ),
    );
    if (!mounted) {
      _resumePromptShowing = false;
      return;
    }
    switch (choice) {
      case 'resume':
        await store.resumeWorkout();
        break;
      case 'partial':
        final summary = await store.finishActiveWorkoutAsPartial();
        if (mounted && summary != null) {
          leaving = true;
          await Navigator.of(context).pushReplacement(
            MaterialPageRoute<void>(
              builder: (_) => WorkoutSummaryPage(summary: summary),
            ),
          );
        } else {
          store.clearWorkoutResumePrompt();
        }
        break;
      case 'discard':
        final confirmed = await showDialog<bool>(
          context: context,
          builder: (dialogContext) => AlertDialog(
            title: const Text('Odrzucić trening?'),
            content: const Text(
                'Niedokończony trening i jego zapisane serie zostaną usunięte. Tej operacji nie można cofnąć.'),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dialogContext, false),
                child: const Text('Anuluj'),
              ),
              FilledButton(
                onPressed: () => Navigator.pop(dialogContext, true),
                child: const Text('Odrzuć'),
              ),
            ],
          ),
        );
        if (confirmed == true) {
          await store.discardActiveWorkout();
        } else {
          store.clearWorkoutResumePrompt();
        }
        break;
      default:
        store.clearWorkoutResumePrompt();
    }
    _resumePromptShowing = false;
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final session = store.activeWorkoutSession;
    if (store.workoutResumePromptPending && !_resumePromptShowing) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && store.workoutResumePromptPending) {
          _handleResumePrompt(store);
        }
      });
    }
    if (session == null || session.currentExercise == null) {
      // Sesja zniknęła (zakończona/odrzucona) — wróć zamiast martwego ekranu.
      if (!leaving) {
        leaving = true;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted && Navigator.of(context).canPop())
            Navigator.of(context).pop();
        });
      }
      return const Scaffold(
          body: Center(child: Text('Brak aktywnego treningu')));
    }
    syncFields(session);
    final activeExercise = session.currentExercise!;
    final exercise =
        ExerciseRepo.byId(activeExercise.exerciseId, store.customExercises);
    final elapsed = DateTime.now().difference(session.startedAt);
    final setLimitReached =
        activeExercise.completedSets.length >= activeExercise.plannedSets;
    final isLastExercise =
        session.currentExerciseIndex >= session.exercises.length - 1;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Trening — szczegóły'),
        leading: IconButton(
          tooltip: 'Wróć do widoku uproszczonego',
          onPressed: backToSimpleView,
          icon: const Icon(Icons.arrow_back_rounded),
        ),
        actions: [
          TextButton.icon(
            onPressed: backToSimpleView,
            icon: const Icon(Icons.play_circle_outline_rounded),
            label: const Text('Widok uproszczony'),
          ),
        ],
      ),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 28),
          children: [
            if (session.isPaused) ...[
              Card(
                color: Theme.of(context).colorScheme.tertiaryContainer,
                child: Padding(
                  padding: const EdgeInsets.all(12),
                  child: Row(
                    children: [
                      const Icon(Icons.pause_circle_filled_rounded),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          session.pausedByBackground
                              ? 'Trening wstrzymany (aplikacja była w tle). Czas w tle nie jest liczony jako trening.'
                              : 'Trening wstrzymany. Czas pauzy nie jest liczony jako trening.',
                          style: Theme.of(context).textTheme.bodySmall,
                        ),
                      ),
                      const SizedBox(width: 8),
                      FilledButton(
                        onPressed: () => store.resumeWorkout(),
                        child: const Text('Wznów'),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(height: 12),
            ],
            _ActiveWorkoutHeader(
              session: session,
              elapsed: elapsed,
              onEditNote: () => showActiveSessionNoteSheet(context),
            ),
            if (!session.isPaused)
              Align(
                alignment: Alignment.centerRight,
                child: TextButton.icon(
                  key: const Key('workout_pause_toggle'),
                  onPressed: () => _togglePause(store),
                  icon:
                      const Icon(Icons.pause_circle_outline_rounded, size: 18),
                  label: const Text('Wstrzymaj trening'),
                ),
              ),
            // Sekcja rozgrzewki/rozciągania przed treningiem usunięta —
            // ćwiczenia mobilizacyjne i rozciągające są już pozycjami programu
            // i nie są dublowane jako osobna sekcja (spec: punkt 8).
            const SizedBox(height: 12),
            _CurrentExerciseCard(
              exercise: exercise,
              activeExercise: activeExercise,
              position: session.currentExerciseIndex + 1,
              total: session.exercises.length,
            ),
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final replace = OutlinedButton.icon(
                  onPressed: () => showReplaceActiveExerciseSheet(context),
                  icon: const Icon(Icons.swap_horiz_rounded),
                  label: const Text('Zamień ćwiczenie'),
                );
                final note = OutlinedButton.icon(
                  onPressed: () => showActiveExerciseNoteSheet(context),
                  icon: const Icon(Icons.note_alt_outlined),
                  label: Text(activeExercise.note.isEmpty
                      ? 'Dodaj notatkę'
                      : 'Edytuj notatkę'),
                );
                if (constraints.maxWidth < 430) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [replace, const SizedBox(height: 8), note],
                  );
                }
                return Row(
                  children: [
                    Expanded(child: replace),
                    const SizedBox(width: 10),
                    Expanded(child: note),
                  ],
                );
              },
            ),
            if (activeExercise.note.isNotEmpty) ...[
              const SizedBox(height: 10),
              Card(
                child: ListTile(
                  leading: const Icon(Icons.sticky_note_2_outlined),
                  title: const Text('Notatka do ćwiczenia'),
                  subtitle: Text(activeExercise.note),
                ),
              ),
            ],
            if (session.hasActiveRestTimer) ...[
              const SizedBox(height: 12),
              _ActiveRestTimerCard(
                session: session,
                recommendation:
                    workoutRestRecommendation(exercise, activeExercise),
              ),
            ],
            const SizedBox(height: 12),
            // Etap 18: sugestia progresji dla aktywnego ćwiczenia
            ProgressionSuggestionCard(
              exerciseId: activeExercise.exerciseId,
              exerciseName: exercise.name,
              logs: store.logs,
              plannedReps: activeExercise.plannedReps,
              plannedWeightKg: activeExercise.suggestedWeightKg,
              planId: store.activeWorkoutPlan?.id,
              weekday: session.weekday,
              onApplied: () => setState(() {}),
            ),
            if (activeExercise.completedSets.isNotEmpty) ...[
              _CompletedSetsCard(sets: activeExercise.completedSets),
              const SizedBox(height: 12),
            ],
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Nowa seria',
                        style: Theme.of(context)
                            .textTheme
                            .titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 12),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: weight,
                            keyboardType: const TextInputType.numberWithOptions(
                                decimal: true),
                            decoration:
                                const InputDecoration(labelText: 'Ciężar (kg)'),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: TextField(
                            controller: repetitions,
                            keyboardType: TextInputType.number,
                            decoration:
                                const InputDecoration(labelText: 'Powtórzenia'),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    DropdownButtonFormField<int>(
                      key: ValueKey(
                          '${activeExercise.exerciseId}_${session.currentExerciseIndex}'),
                      initialValue: rpe,
                      decoration: const InputDecoration(labelText: 'RPE'),
                      items: [
                        for (var value = 1; value <= 10; value++)
                          DropdownMenuItem(
                              value: value, child: Text('$value / 10')),
                      ],
                      onChanged: (value) => setState(() => rpe = value ?? rpe),
                    ),
                    const SizedBox(height: 14),
                    FilledButton.icon(
                      onPressed: setLimitReached ? null : () => saveSet(store),
                      icon: const Icon(Icons.check_rounded),
                      label: Text(setLimitReached
                          ? 'Wszystkie serie zapisane'
                          : 'Zapisz serię'),
                    ),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 12),
            LayoutBuilder(
              builder: (context, constraints) {
                final next = FilledButton.tonalIcon(
                  onPressed: isLastExercise
                      ? null
                      : () async {
                          await store.moveToNextActiveExercise();
                          final nextSession = store.activeWorkoutSession;
                          if (nextSession != null) syncFields(nextSession);
                        },
                  icon: const Icon(Icons.arrow_forward_rounded),
                  label: const Text('Następne ćwiczenie'),
                );
                final skip = OutlinedButton.icon(
                  onPressed: activeExercise.isSkipped
                      ? null
                      : () async {
                          await store.moveToNextActiveExercise(
                              skipCurrent: true);
                          final nextSession = store.activeWorkoutSession;
                          if (nextSession != null) syncFields(nextSession);
                        },
                  icon: const Icon(Icons.skip_next_rounded),
                  label: Text(activeExercise.isSkipped
                      ? 'Ćwiczenie pominięte'
                      : 'Pomiń ćwiczenie'),
                );
                if (constraints.maxWidth < 430) {
                  return Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [next, const SizedBox(height: 8), skip],
                  );
                }
                return Row(
                  children: [
                    Expanded(child: next),
                    const SizedBox(width: 10),
                    Expanded(child: skip),
                  ],
                );
              },
            ),
            const SizedBox(height: 18),
            Text('Wszystkie ćwiczenia',
                style: Theme.of(context)
                    .textTheme
                    .titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 10),
            for (var index = 0; index < session.exercises.length; index++)
              _ActiveWorkoutExerciseTile(
                activeExercise: session.exercises[index],
                exercise: ExerciseRepo.byId(
                    session.exercises[index].exerciseId, store.customExercises),
                selected: index == session.currentExerciseIndex,
                onTap: () async {
                  await store.selectActiveWorkoutExercise(index);
                  final nextSession = store.activeWorkoutSession;
                  if (nextSession != null) syncFields(nextSession);
                },
              ),
            const SizedBox(height: 12),
            FilledButton.icon(
              style: FilledButton.styleFrom(
                backgroundColor: Theme.of(context).colorScheme.error,
                foregroundColor: Theme.of(context).colorScheme.onError,
              ),
              onPressed: () => finishWorkout(store),
              icon: const Icon(Icons.flag_rounded),
              label: const Text('Zakończ trening'),
            ),
          ],
        ),
      ),
    );
  }
}

// ============================================================================
// ETAP 30 — Pełnoekranowy tryb „Aktywne ćwiczenie".
// ============================================================================

String _fmtClock(int totalSeconds) {
  final s = totalSeconds.clamp(0, 359999);
  final m = s ~/ 60;
  final sec = s % 60;
  return '${m.toString().padLeft(2, '0')}:${sec.toString().padLeft(2, '0')}';
}

// ===== Wyróżnienie ćwiczeń rozciągających / mobilizacyjnych (spec: punkt 9) =====
//
// Rozciąganie i mobilność są normalnymi pozycjami programu — nie dublujemy ich
// jako osobnych sekcji, ale wyróżniamy wizualnie kafelki. Kolor bierzemy ZAWSZE
// z aktualnego motywu (accent = colorScheme.secondary), nigdy na sztywno.

/// Czy ćwiczenie jest rozciągające / mobilizacyjne.
bool isMobilityOrStretchExercise(Exercise exercise) =>
    exercise.entryType == ExerciseEntryType.mobility;

/// Kolor akcentu motywu używany do wyróżnienia rozciągania/mobilności.
Color mobilityAccentColor(ThemeData theme) => theme.colorScheme.secondary;

/// Subtelne obramowanie + tło w kolorze akcentu motywu dla kafelka rozciągania.
/// Kontrast tekstu zostaje bez zmian (tło jest tylko delikatnie przybarwione),
/// więc działa poprawnie w trybie jasnym i ciemnym.
({Color background, Color border}) mobilityTileColors(ThemeData theme) {
  final accent = mobilityAccentColor(theme);
  final dark = theme.brightness == Brightness.dark;
  return (
    background: accent.withValues(alpha: dark ? 0.16 : 0.09),
    border: accent.withValues(alpha: dark ? 0.55 : 0.45),
  );
}

/// Mała ikona oznaczająca ćwiczenie rozciągające / mobilizacyjne.
class MobilityBadge extends StatelessWidget {
  const MobilityBadge({super.key, this.size = 16});

  final double size;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Tooltip(
      message: 'Rozciąganie / mobilność',
      child: Icon(
        Icons.self_improvement_rounded,
        size: size,
        color: mobilityAccentColor(theme),
      ),
    );
  }
}

// ===== Rekomendacja sesji: linia planu + ikona AI + arkusz „dlaczego" =====
//
// Rekomendacja jest liczona PRZED wykonaniem (recepta sesji) i stanowi domyślny
// plan. Na ekranie ćwiczenia pokazujemy od razu wartości efektywne; gdy różnią
// się od planu bazowego — mała ikona AI (✨), po kliknięciu arkusz z bazą,
// rekomendacją, powodem i danymi, na których ją oparto.

/// Formatuje efektywny plan ćwiczenia (rekomendacja/nadpisanie) do jednej linii.
String formatSessionPlanLine(
  SessionPrescription rx,
  ExerciseEntryType entryType,
) {
  final eff = rx.effective;
  final parts = <String>[];
  if (entryType.showsDuration && !entryType.showsReps) {
    parts.add('${eff.sets} × ${rx.effectiveDurationSec} s');
  } else {
    parts.add('${eff.sets} × ${eff.reps} powt.');
    if (entryType.showsWeight && eff.weightKg > 0) {
      parts.add('${_formatPlanWeight(eff.weightKg)} kg');
    }
  }
  if (eff.restSeconds > 0) parts.add('przerwa ${eff.restSeconds} s');
  return parts.join(' · ');
}

String _prescriptionSideText(
  Prescription p,
  ExerciseEntryType entryType, {
  int? durationOverride,
}) {
  final parts = <String>[];
  if (entryType.showsDuration && !entryType.showsReps) {
    parts.add('${p.sets} × ${durationOverride ?? p.durationSec} s');
  } else {
    parts.add('${p.sets} × ${p.reps} powt.');
    if (entryType.showsWeight && p.weightKg > 0) {
      parts.add('${_formatPlanWeight(p.weightKg)} kg');
    }
  }
  if (p.restSeconds > 0) parts.add('przerwa ${p.restSeconds} s');
  return parts.join(' · ');
}

/// Otwiera arkusz wyjaśnienia rekomendacji: plan bazowy vs rekomendacja + powód
/// + dane, na których ją oparto (albo informacja o braku wystarczającej historii).
void showRecommendationExplainSheet(
  BuildContext context,
  Exercise exercise,
  SessionPrescription rx,
) {
  showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      final theme = Theme.of(sheetContext);
      final entryType = exercise.entryType;
      final scheme = theme.colorScheme;
      String dataSourceText;
      if (rx.isCalibrating) {
        dataSourceText =
            'Za mało wykonań — Trainer zbiera dane. Rekomendacja opiera się na planie bazowym i profilu.';
      } else if (rx.hasEnoughHistory) {
        dataSourceText = 'Oparto na Twojej historii tego ćwiczenia.';
      } else {
        dataSourceText =
            'Brak wystarczającej lub poprawnej historii — użyto planu bazowego programu.';
      }
      return SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(20, 4, 20, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_rounded, color: scheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text('Rekomendacja Trainera',
                      style: theme.textTheme.titleLarge
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            const SizedBox(height: 2),
            Text(exercise.name,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(color: scheme.onSurfaceVariant)),
            const SizedBox(height: 16),
            _explainRow(
                theme,
                'Wartość bazowa',
                _prescriptionSideText(rx.base, entryType),
                scheme.onSurfaceVariant),
            const SizedBox(height: 8),
            _explainRow(
                theme,
                'Rekomendacja',
                _prescriptionSideText(rx.recommended, entryType),
                scheme.primary,
                bold: true),
            if (rx.manuallyOverridden) ...[
              const SizedBox(height: 8),
              _explainRow(
                  theme,
                  'Twoja zmiana',
                  _prescriptionSideText(rx.effective, entryType,
                      durationOverride: rx.effectiveDurationSec),
                  scheme.tertiary,
                  bold: true),
            ],
            if (rx.reason.trim().isNotEmpty) ...[
              const SizedBox(height: 16),
              Text('Powód',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w800)),
              const SizedBox(height: 4),
              Text(rx.reason.trim(),
                  style: theme.textTheme.bodyMedium?.copyWith(height: 1.4)),
            ],
            const SizedBox(height: 16),
            Text('Dane rekomendacji',
                style: theme.textTheme.labelLarge
                    ?.copyWith(fontWeight: FontWeight.w800)),
            const SizedBox(height: 4),
            Text(dataSourceText,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(height: 1.4, color: scheme.onSurfaceVariant)),
            const SizedBox(height: 8),
            Text('Progresja tego ćwiczenia: ${entryType.progressionMode}.',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: scheme.onSurfaceVariant)),
          ],
        ),
      );
    },
  );
}

Widget _explainRow(
  ThemeData theme,
  String label,
  String value,
  Color valueColor, {
  bool bold = false,
}) {
  return Row(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      SizedBox(
        width: 120,
        child: Text(label,
            style: theme.textTheme.bodyMedium
                ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
      ),
      const SizedBox(width: 8),
      Expanded(
        child: Text(value,
            style: theme.textTheme.bodyMedium?.copyWith(
                color: valueColor,
                fontWeight: bold ? FontWeight.w900 : FontWeight.w600)),
      ),
    ],
  );
}

/// Kompaktowa linia planu sesji z ikoną AI (✨), gdy rekomendacja zmieniła plan
/// bazowy. Klik w ikonę/linię otwiera arkusz „dlaczego". Gdy brak recepty
/// (starsza/ad-hoc sesja) — pokazuje sam [fallbackText].
class SessionPlanLine extends StatelessWidget {
  const SessionPlanLine({
    super.key,
    required this.exercise,
    required this.prescription,
    this.fallbackText = '',
    this.emphasize = false,
    this.compact = false,
  });

  final Exercise exercise;
  final SessionPrescription? prescription;
  final String fallbackText;
  final bool emphasize;

  /// Wariant do kafelków kolejki / odpoczynku — mniejsza typografia, żeby plan
  /// nie konkurował z nazwą ćwiczenia.
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final rx = prescription;
    final entryType = exercise.entryType;
    final text =
        rx != null ? formatSessionPlanLine(rx, entryType) : fallbackText;
    if (text.isEmpty) return const SizedBox.shrink();
    final changed = rx != null && rx.recommendationApplied;
    final content = Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Flexible(
          child: Text(
            text,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: (compact
                    ? theme.textTheme.bodySmall
                    : (emphasize
                        ? theme.textTheme.titleMedium
                        : theme.textTheme.bodyLarge))
                ?.copyWith(
              fontWeight: compact ? FontWeight.w700 : FontWeight.w900,
              color: compact ? scheme.onSurfaceVariant : null,
            ),
          ),
        ),
        if (changed || rx?.manuallyOverridden == true) ...[
          SizedBox(width: compact ? 4 : 6),
          Icon(Icons.auto_awesome_rounded,
              size: compact ? 13 : 16, color: scheme.primary),
        ],
      ],
    );
    if (rx == null) return content;
    return InkWell(
      borderRadius: BorderRadius.circular(10),
      onTap: () => showRecommendationExplainSheet(context, exercise, rx),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 2),
        child: content,
      ),
    );
  }
}

/// Slide-up z danymi siłowymi (ciężar / powtórzenia / czas / RPE) bieżącego
/// ćwiczenia. Zachowuje istniejący zapis serii ([AppStore.saveActiveWorkoutSet]).
/// Kontrolery tekstu żyją w stanie widgetu (dispose dopiero po zdjęciu arkusza
/// z drzewa) — wcześniejsza wersja zwalniała je w trakcie animacji zamykania,
/// co wyrzucało błąd po zapisaniu serii. Etap 30.
Future<void> showActiveStrengthSheet(BuildContext context) async {
  final store = AppScope.read(context);
  final session = store.activeWorkoutSession;
  final active = session?.currentExercise;
  if (session == null || active == null) return;
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (_) => const ActiveStrengthSheetContent(),
  );
}

class ActiveStrengthSheetContent extends StatefulWidget {
  const ActiveStrengthSheetContent({super.key});

  @override
  State<ActiveStrengthSheetContent> createState() =>
      _ActiveStrengthSheetContentState();
}

class _ActiveStrengthSheetContentState
    extends State<ActiveStrengthSheetContent> {
  late final TextEditingController weightCtrl;
  late final TextEditingController repsCtrl;
  late final TextEditingController durationCtrl;
  late final TextEditingController distanceCtrl;
  int rpe = 7;
  bool saving = false;

  /// Użytkownik wybrał „Zrobiłem inaczej" — pokazujemy pola ręcznej korekty
  /// nawet w trybie pełnego prowadzenia.
  bool _manualOverride = false;

  /// Indeks edytowanej serii w [completedSets] albo null (nowa seria).
  int? _editingIndex;

  @override
  void initState() {
    super.initState();
    final store = AppScope.read(context);
    final active = store.activeWorkoutSession?.currentExercise;
    final exercise = active == null
        ? null
        : ExerciseRepo.byId(active.exerciseId, store.customExercises);
    final entryType = exercise?.entryType ?? ExerciseEntryType.repsWeight;
    final lastSet = (active?.completedSets.isEmpty ?? true)
        ? null
        : active!.completedSets.last;
    // Rekomendacja trenera zasila pola startowe (także w trybie z korektą/ręcznym),
    // więc „Zrobiłem inaczej" zaczyna od proponowanych wartości.
    final rec = store.recommendationForActiveExercise();
    // Dla ćwiczeń z masą ciała domyślny „dodatkowy ciężar" to 0, nie sugerowany
    // ciężar roboczy z planu.
    final defaultWeight = lastSet?.weightKg ??
        (entryType.usesBodyweight
            ? 0.0
            : (rec?.weightKg ?? active?.suggestedWeightKg ?? 0));
    weightCtrl = TextEditingController(text: _formatPlanWeight(defaultWeight));
    repsCtrl = TextEditingController(
        text:
            '${lastSet?.repetitions ?? rec?.reps ?? active?.plannedReps ?? 10}');
    final recDuration = (rec?.durationSec ?? 0) > 0 ? rec!.durationSec : 0;
    final defaultDuration = (lastSet?.durationSec ?? 0) > 0
        ? lastSet!.durationSec
        : (recDuration > 0 ? recDuration : (exercise?.defaultDurationSec ?? 0));
    durationCtrl = TextEditingController(
        text: defaultDuration > 0 ? '$defaultDuration' : '');
    final defaultDistanceKm = (lastSet?.distanceMeters ?? 0) > 0
        ? lastSet!.distanceMeters / 1000
        : 0.0;
    distanceCtrl = TextEditingController(
        text:
            defaultDistanceKm > 0 ? defaultDistanceKm.toStringAsFixed(2) : '');
    rpe = (lastSet?.rpe ?? 7).clamp(1, 10);
  }

  @override
  void dispose() {
    weightCtrl.dispose();
    repsCtrl.dispose();
    durationCtrl.dispose();
    distanceCtrl.dispose();
    super.dispose();
  }

  /// Wypełnia pola danymi istniejącej serii i włącza tryb edycji.
  void _startEditing(int index, WorkoutSet set) {
    setState(() {
      _editingIndex = index;
      weightCtrl.text = _formatPlanWeight(set.weightKg);
      repsCtrl.text = '${set.repetitions}';
      durationCtrl.text = set.durationSec > 0 ? '${set.durationSec}' : '';
      distanceCtrl.text = set.distanceMeters > 0
          ? (set.distanceMeters / 1000).toStringAsFixed(2)
          : '';
      rpe = set.rpe.clamp(1, 10);
    });
  }

  ({double weight, int reps, int duration, double distanceM})? _parseFields(
      ExerciseEntryType entryType, bool showDuration) {
    final parsedWeight = entryType.showsWeight
        ? double.tryParse(weightCtrl.text.trim().replaceAll(',', '.'))
        : 0.0;
    final parsedReps =
        entryType.showsReps ? int.tryParse(repsCtrl.text.trim()) : 1;
    final durationText = durationCtrl.text.trim();
    final parsedDuration = showDuration
        ? (durationText.isEmpty ? 0 : int.tryParse(durationText))
        : 0;
    final distanceText = distanceCtrl.text.trim().replaceAll(',', '.');
    final parsedDistanceKm = entryType.showsDistance
        ? (distanceText.isEmpty ? 0.0 : double.tryParse(distanceText))
        : 0.0;
    if (parsedWeight == null || parsedWeight < 0 || parsedWeight > 9999) {
      showError(context, 'Podaj poprawny ciężar (0–9999 kg).');
      return null;
    }
    if (parsedReps == null || parsedReps < 1 || parsedReps > 999) {
      showError(context, 'Powtórzenia muszą mieścić się w zakresie 1–999.');
      return null;
    }
    if (parsedDuration == null || parsedDuration < 0 || parsedDuration > 7200) {
      showError(context, 'Czas serii musi mieścić się w zakresie 0–7200 s.');
      return null;
    }
    if (parsedDistanceKm == null ||
        parsedDistanceKm < 0 ||
        parsedDistanceKm > 500) {
      showError(context, 'Dystans musi mieścić się w zakresie 0–500 km.');
      return null;
    }
    return (
      weight: parsedWeight,
      reps: parsedReps,
      duration: parsedDuration,
      distanceM: parsedDistanceKm * 1000,
    );
  }

  Future<void> _save(
      AppStore store, ExerciseEntryType entryType, bool showDuration) async {
    if (saving) return;
    final parsed = _parseFields(entryType, showDuration);
    if (parsed == null) return;
    setState(() => saving = true);
    final effectiveRpe = entryType.showsRpe ? rpe : 0;
    final editing = _editingIndex;
    final bool saved;
    if (editing != null) {
      saved = await store.updateActiveWorkoutSet(
        editing,
        weightKg: parsed.weight,
        repetitions: parsed.reps,
        rpe: effectiveRpe,
        durationSec: parsed.duration,
        distanceMeters: parsed.distanceM,
      );
    } else {
      saved = await store.saveActiveWorkoutSet(
        weightKg: parsed.weight,
        repetitions: parsed.reps,
        rpe: effectiveRpe,
        durationSec: parsed.duration,
        distanceMeters: parsed.distanceM,
      );
    }
    if (!mounted) return;
    if (!saved) {
      setState(() => saving = false);
      showError(
          context,
          editing != null
              ? 'Nie udało się zapisać zmian serii.'
              : 'Wszystkie zaplanowane serie są już zapisane.');
      return;
    }
    Navigator.of(context).pop();
  }

  /// „Powtórz poprzednią serię" — natychmiastowy zapis danych ostatniej serii.
  Future<void> _repeatLastSet(AppStore store, WorkoutSet lastSet) async {
    if (saving) return;
    setState(() => saving = true);
    final saved = await store.saveActiveWorkoutSet(
      weightKg: lastSet.weightKg,
      repetitions: lastSet.repetitions,
      rpe: lastSet.rpe,
      durationSec: lastSet.durationSec,
      distanceMeters: lastSet.distanceMeters,
    );
    if (!mounted) return;
    if (!saved) {
      setState(() => saving = false);
      showError(context, 'Wszystkie zaplanowane serie są już zapisane.');
      return;
    }
    Navigator.of(context).pop();
  }

  /// Tryb pełnego prowadzenia: zapis serii jednym wyborem wyniku — bez ręcznego
  /// wpisywania ciężaru/powtórzeń/RPE. Trainer sam dobiera i szacuje resztę.
  Future<void> _logOutcome(AppStore store, SetOutcome outcome) async {
    if (saving) return;
    setState(() => saving = true);
    final saved = await store.logGuidedSet(outcome: outcome);
    if (!mounted) return;
    if (!saved) {
      setState(() => saving = false);
      showError(context, 'Wszystkie zaplanowane serie są już zapisane.');
      return;
    }
    Navigator.of(context).pop();
  }

  Future<void> _handleSetAction(
      AppStore store, String action, int index, WorkoutSet set) async {
    switch (action) {
      case 'edit':
        _startEditing(index, set);
        break;
      case 'repeat':
        await store.duplicateActiveWorkoutSet(index);
        if (mounted) setState(() {});
        break;
      case 'failure':
        await store.updateActiveWorkoutSet(index, isFailure: !set.isFailure);
        if (mounted) setState(() {});
        break;
      case 'delete':
        await store.removeActiveWorkoutSet(index);
        if (mounted) {
          setState(() {
            if (_editingIndex == index) _editingIndex = null;
          });
        }
        break;
    }
  }

  String _setSummary(WorkoutSet set, ExerciseEntryType entryType) {
    final parts = <String>[];
    if (entryType.showsReps) parts.add('${set.repetitions} powt.');
    if (entryType.showsWeight &&
        (set.weightKg > 0 || !entryType.usesBodyweight)) {
      parts.add('${_formatPlanWeight(set.weightKg)} kg');
    }
    if (set.durationSec > 0) parts.add('${set.durationSec} s');
    if (set.distanceMeters > 0)
      parts.add('${(set.distanceMeters / 1000).toStringAsFixed(2)} km');
    if (set.rpe > 0) parts.add('RPE ${set.rpe}');
    return parts.isEmpty ? '${set.repetitions} powt.' : parts.join(' · ');
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final active = store.activeWorkoutSession?.currentExercise;
    if (active == null) {
      // Sesja wygasła w trakcie otwartego arkusza — zamknij bezpiecznie.
      return const SizedBox(
          height: 120, child: Center(child: Text('Brak aktywnego ćwiczenia')));
    }
    final exercise =
        ExerciseRepo.byId(active.exerciseId, store.customExercises);
    final entryType = exercise.entryType;
    // Czas pokazujemy też dla ćwiczeń z ustawionym czasem domyślnym (zgodność
    // z dotychczasowym zachowaniem ćwiczeń czasowych).
    final showDuration =
        entryType.showsDuration || exercise.defaultDurationSec > 0;
    final setLimitReached = active.completedSets.length >= active.plannedSets;
    final editing = _editingIndex;
    final editingValid =
        editing != null && editing < active.completedSets.length;
    final currentSetNumber =
        math.min(active.completedSets.length + 1, active.plannedSets);
    final lastSet =
        active.completedSets.isEmpty ? null : active.completedSets.last;
    final theme = Theme.of(context);
    // Tryb prowadzenia: pełne prowadzenie = wynik jednym przyciskiem, bez pól.
    final guidance = store.settings.guidanceModeEnum;
    final rec = store.recommendationForActiveExercise();
    final fullGuidance = guidance == GuidanceMode.full &&
        !_manualOverride &&
        !editingValid &&
        !setLimitReached &&
        rec != null;
    final showManualFields = !fullGuidance;
    return Padding(
      padding: EdgeInsets.fromLTRB(
          16,
          0,
          16,
          16 +
              MediaQuery.of(context).viewInsets.bottom +
              MediaQuery.of(context).viewPadding.bottom),
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
              editingValid
                  ? 'Edycja serii ${editing + 1}'
                  : 'Seria $currentSetNumber/${active.plannedSets}',
              style: theme.textTheme.titleLarge
                  ?.copyWith(fontWeight: FontWeight.w900),
            ),
            const SizedBox(height: 2),
            InkWell(
              onTap: () => showActiveExerciseInfoSheet(context, exercise),
              borderRadius: BorderRadius.circular(10),
              child: Padding(
                padding: const EdgeInsets.symmetric(vertical: 4),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Flexible(
                      child: Text(
                        '${exercise.name} · ${entryType.label}',
                        style: theme.textTheme.bodyMedium?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant),
                      ),
                    ),
                    const SizedBox(width: 6),
                    Icon(Icons.info_outline_rounded,
                        size: 17, color: theme.colorScheme.primary),
                  ],
                ),
              ),
            ),
            // Rekomendacja jest już zastosowana w polach wejściowych (recepta
            // sesji). Panel skupia się na rzeczywistym wykonaniu — plan i „powód"
            // pokazujemy zwięźle jako klikalną linię, bez dużego kafla.
            if (active.prescription != null && !editingValid) ...[
              const SizedBox(height: 6),
              Align(
                alignment: Alignment.centerLeft,
                child: SessionPlanLine(
                  exercise: exercise,
                  prescription: active.prescription,
                ),
              ),
            ],
            if (showManualFields) ...[
              const SizedBox(height: 14),
              // Pola dopasowane do typu wpisu ćwiczenia.
              if (entryType.showsReps || entryType.showsWeight)
                Row(
                  children: [
                    if (entryType.showsReps)
                      Expanded(
                        child: TextField(
                          controller: repsCtrl,
                          keyboardType: TextInputType.number,
                          decoration:
                              const InputDecoration(labelText: 'Powtórzenia'),
                        ),
                      ),
                    if (entryType.showsReps && entryType.showsWeight)
                      const SizedBox(width: 10),
                    if (entryType.showsWeight)
                      Expanded(
                        child: TextField(
                          controller: weightCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                              decimal: true),
                          decoration: InputDecoration(
                              labelText: entryType.weightFieldLabel),
                        ),
                      ),
                  ],
                ),
              if (showDuration) ...[
                if (entryType.showsReps || entryType.showsWeight)
                  const SizedBox(height: 10),
                TextField(
                  controller: durationCtrl,
                  keyboardType: TextInputType.number,
                  decoration:
                      const InputDecoration(labelText: 'Czas serii (s)'),
                ),
              ],
              if (entryType.showsDistance) ...[
                const SizedBox(height: 10),
                TextField(
                  controller: distanceCtrl,
                  keyboardType:
                      const TextInputType.numberWithOptions(decimal: true),
                  decoration: const InputDecoration(labelText: 'Dystans (km)'),
                ),
              ],
              if (entryType.showsRpe) ...[
                const SizedBox(height: 10),
                DropdownButtonFormField<int>(
                  initialValue: rpe,
                  decoration: const InputDecoration(labelText: 'RPE'),
                  items: [
                    for (var v = 1; v <= 10; v++)
                      DropdownMenuItem(value: v, child: Text('$v / 10'))
                  ],
                  onChanged: (value) => setState(() => rpe = value ?? rpe),
                ),
              ],
              if (entryType.helperText.isNotEmpty) ...[
                const SizedBox(height: 8),
                Text(
                  entryType.helperText,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                ),
              ],
            ],
            if (active.completedSets.isNotEmpty) ...[
              const SizedBox(height: 14),
              Text('Zapisane serie',
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 4),
              for (var i = 0; i < active.completedSets.length; i++)
                Padding(
                  padding: const EdgeInsets.only(bottom: 2),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          'Seria ${i + 1}: ${_setSummary(active.completedSets[i], entryType)}'
                          '${active.completedSets[i].isFailure ? ' · NIEUDANA' : ''}',
                          style: theme.textTheme.bodySmall?.copyWith(
                            color: active.completedSets[i].isFailure
                                ? theme.colorScheme.error
                                : theme.colorScheme.onSurfaceVariant,
                            decoration: active.completedSets[i].isFailure
                                ? TextDecoration.lineThrough
                                : null,
                          ),
                        ),
                      ),
                      PopupMenuButton<String>(
                        tooltip: 'Akcje serii',
                        padding: EdgeInsets.zero,
                        icon: Icon(Icons.more_horiz_rounded,
                            size: 18,
                            color: theme.colorScheme.onSurfaceVariant),
                        onSelected: (action) => _handleSetAction(
                            store, action, i, active.completedSets[i]),
                        itemBuilder: (menuContext) => [
                          const PopupMenuItem(
                              value: 'edit', child: Text('Edytuj serię')),
                          const PopupMenuItem(
                              value: 'repeat', child: Text('Powtórz serię')),
                          PopupMenuItem(
                            value: 'failure',
                            child: Text(active.completedSets[i].isFailure
                                ? 'Cofnij „nieudaną"'
                                : 'Oznacz jako nieudaną'),
                          ),
                          const PopupMenuItem(
                              value: 'delete', child: Text('Usuń serię')),
                        ],
                      ),
                    ],
                  ),
                ),
            ],
            const SizedBox(height: 12),
            if (editingValid) ...[
              FilledButton.icon(
                onPressed:
                    saving ? null : () => _save(store, entryType, showDuration),
                icon: const Icon(Icons.check_rounded),
                label: const Text('Zapisz zmiany'),
              ),
              const SizedBox(height: 8),
              OutlinedButton(
                onPressed:
                    saving ? null : () => setState(() => _editingIndex = null),
                child: const Text('Anuluj edycję'),
              ),
            ] else if (fullGuidance) ...[
              // Pełne prowadzenie — minimum danych od użytkownika: 1 wybór wyniku.
              FilledButton.icon(
                key: const Key('outcome_as_planned'),
                onPressed: saving
                    ? null
                    : () => _logOutcome(store, SetOutcome.asPlanned),
                icon: const Icon(Icons.check_circle_rounded),
                label: const Text('Wykonane zgodnie z planem'),
              ),
              const SizedBox(height: 8),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton(
                      onPressed: saving
                          ? null
                          : () => _logOutcome(store, SetOutcome.notCompleted),
                      child: const Text('Nie ukończyłem'),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: OutlinedButton(
                      onPressed: saving
                          ? null
                          : () => _logOutcome(store, SetOutcome.interrupted),
                      child: const Text('Przerwałem'),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 8),
              TextButton.icon(
                key: const Key('outcome_did_differently'),
                onPressed: saving
                    ? null
                    : () => setState(() => _manualOverride = true),
                icon: const Icon(Icons.tune_rounded, size: 18),
                label: const Text('Zrobiłem inaczej'),
              ),
            ] else ...[
              if (_manualOverride) ...[
                Text(
                  'Ręczna korekta — Trainer uwzględni zmianę w dalszej analizie.',
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                ),
                const SizedBox(height: 8),
              ],
              FilledButton.icon(
                onPressed: setLimitReached || saving
                    ? null
                    : () => _save(store, entryType, showDuration),
                icon: const Icon(Icons.check_rounded),
                label: Text(setLimitReached
                    ? 'Wszystkie serie zapisane'
                    : 'Zapisz serię'),
              ),
              if (lastSet != null && !setLimitReached) ...[
                const SizedBox(height: 8),
                OutlinedButton.icon(
                  onPressed:
                      saving ? null : () => _repeatLastSet(store, lastSet),
                  icon: const Icon(Icons.repeat_rounded),
                  label: Text(
                      'Powtórz poprzednią serię (${_setSummary(lastSet, entryType)})'),
                ),
              ],
            ],
          ],
        ),
      ),
    );
  }
}

/// Pop-up ze szczegółami ćwiczenia podczas aktywnego treningu (Etap 1).
///
/// Otwiera się kliknięciem w nazwę/kartę ćwiczenia albo ikonę „i". NIE zatrzymuje
/// treningu ani timera (odtwarzacz działa dalej pod spodem), daje się szybko
/// zamknąć i działa w trybie jasnym i ciemnym. Pokazuje opis wykonania, kroki,
/// partie mięśniowe (główne i pomocnicze), wskazówki, błędy, typ i sprzęt oraz
/// ostrzeżenie, gdy zaangażowana partia jest jeszcze w regeneracji.
void showActiveExerciseInfoSheet(BuildContext context, Exercise exercise) {
  showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) =>
        _ActiveExerciseInfoSheet(exerciseId: exercise.id),
  );
}

class _ActiveExerciseInfoSheet extends StatelessWidget {
  const _ActiveExerciseInfoSheet({required this.exerciseId});

  final String exerciseId;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final dark = theme.brightness == Brightness.dark;
    final exercise = ExerciseRepo.byId(exerciseId, store.customExercises);
    final impacts = exercise.effectiveMuscleImpacts;
    final entryType = exercise.entryType;
    final warnings =
        recoveryWarningsForExercises([exercise], store.muscleRecoveryMap());

    final primaryLabels = <String>{
      for (final impact in impacts)
        if (impact.role == MuscleRole.primary) impact.muscleGroup.label,
    };
    final secondaryLabels = <String>{
      for (final impact in impacts)
        if (impact.role != MuscleRole.primary) impact.muscleGroup.label,
    };
    if (primaryLabels.isEmpty && exercise.primaryMuscle.trim().isNotEmpty) {
      primaryLabels.add(exercise.primaryMuscle);
    }
    if (secondaryLabels.isEmpty)
      secondaryLabels.addAll(exercise.supportingMuscles);

    return ConstrainedBox(
      constraints: BoxConstraints(
        maxHeight: MediaQuery.of(context).size.height * 0.85,
      ),
      child: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(20, 2, 20, 24),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          mainAxisSize: MainAxisSize.min,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Text(
                    exercise.name,
                    style: theme.textTheme.headlineSmall
                        ?.copyWith(fontWeight: FontWeight.w900, height: 1.1),
                  ),
                ),
                IconButton(
                  tooltip: 'Zamknij',
                  onPressed: () => Navigator.of(context).maybePop(),
                  icon: const Icon(Icons.close_rounded),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                MiniTag(text: entryType.label),
                MiniTag(text: normalizeLevel(exercise.level)),
                if (exercise.equipment.trim().isNotEmpty)
                  MiniTag(text: exercise.equipment),
              ],
            ),
            if (warnings.isNotEmpty) ...[
              const SizedBox(height: 14),
              _ActiveExerciseRecoveryBanner(warnings: warnings, dark: dark),
            ],
            const SizedBox(height: 16),
            _infoBlock(
              theme,
              icon: Icons.groups_2_rounded,
              title: 'Główne mięśnie',
              child: Text(
                primaryLabels.isEmpty ? '—' : primaryLabels.join(', '),
                style: theme.textTheme.bodyLarge?.copyWith(height: 1.4),
              ),
            ),
            if (secondaryLabels.isNotEmpty)
              _infoBlock(
                theme,
                icon: Icons.hub_outlined,
                title: 'Pomocnicze mięśnie',
                child: Text(
                  secondaryLabels.join(', '),
                  style: theme.textTheme.bodyLarge?.copyWith(height: 1.4),
                ),
              ),
            if (exercise.description.trim().isNotEmpty)
              _infoBlock(
                theme,
                icon: Icons.menu_book_outlined,
                title: 'Jak wykonać',
                child: Text(
                  exercise.description,
                  style: theme.textTheme.bodyLarge?.copyWith(height: 1.45),
                ),
              ),
            if (exercise.executionSteps.isNotEmpty)
              _infoBlock(
                theme,
                icon: Icons.format_list_numbered_rounded,
                title: 'Krok po kroku',
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    for (var i = 0; i < exercise.executionSteps.length; i++)
                      Padding(
                        padding: const EdgeInsets.only(bottom: 8),
                        child: Row(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            CircleAvatar(
                              radius: 12,
                              backgroundColor:
                                  theme.colorScheme.primaryContainer,
                              foregroundColor:
                                  theme.colorScheme.onPrimaryContainer,
                              child: Text('${i + 1}',
                                  style: theme.textTheme.labelSmall
                                      ?.copyWith(fontWeight: FontWeight.w900)),
                            ),
                            const SizedBox(width: 10),
                            Expanded(
                              child: Padding(
                                padding: const EdgeInsets.only(top: 2),
                                child: Text(exercise.executionSteps[i],
                                    style: theme.textTheme.bodyMedium
                                        ?.copyWith(height: 1.4)),
                              ),
                            ),
                          ],
                        ),
                      ),
                  ],
                ),
              ),
            if (exercise.tips.isNotEmpty)
              _infoBlock(
                theme,
                icon: Icons.lightbulb_outline_rounded,
                title: 'Wskazówki techniczne',
                child: _bullets(theme, exercise.tips),
              ),
            if (exercise.commonMistakes.isNotEmpty)
              _infoBlock(
                theme,
                icon: Icons.warning_amber_rounded,
                title: 'Najczęstsze błędy',
                child: _bullets(theme, exercise.commonMistakes),
              ),
            const SizedBox(height: 4),
            Text(
              'Trening nie został zatrzymany — timer działa dalej.',
              style: theme.textTheme.bodySmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () {
                      final navigator = Navigator.of(context);
                      navigator.pop();
                      navigator.push(
                        MaterialPageRoute(
                            builder: (_) =>
                                ExerciseDetailsPage(exerciseId: exercise.id)),
                      );
                    },
                    icon: const Icon(Icons.open_in_new_rounded, size: 18),
                    label: const Text('Pełne szczegóły'),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: FilledButton(
                    onPressed: () => Navigator.of(context).maybePop(),
                    child: const Text('Zamknij'),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _infoBlock(ThemeData theme,
      {required IconData icon, required String title, required Widget child}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(icon, size: 18, color: theme.colorScheme.primary),
              const SizedBox(width: 8),
              Text(title,
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
            ],
          ),
          const SizedBox(height: 8),
          child,
        ],
      ),
    );
  }

  Widget _bullets(ThemeData theme, List<String> items) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        for (final item in items)
          Padding(
            padding: const EdgeInsets.only(bottom: 6),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Padding(
                  padding: const EdgeInsets.only(top: 7, right: 8),
                  child: Icon(Icons.circle,
                      size: 6, color: theme.colorScheme.primary),
                ),
                Expanded(
                    child: Text(item,
                        style:
                            theme.textTheme.bodyMedium?.copyWith(height: 1.4))),
              ],
            ),
          ),
      ],
    );
  }
}

/// Baner ostrzegawczy w pop-upie ćwiczenia: partia jeszcze w regeneracji.
class _ActiveExerciseRecoveryBanner extends StatelessWidget {
  const _ActiveExerciseRecoveryBanner(
      {required this.warnings, required this.dark});

  final List<RecoveryWarning> warnings;
  final bool dark;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final worst = warnings.first;
    final severe = warnings.any((w) => w.severe);
    final color = severe
        ? theme.colorScheme.error
        : recoveryColor(worst.recoveryPercent, dark: dark);
    final extra = warnings.length - 1;
    final message = StringBuffer(
      'Uwaga: ${worst.muscle.label} '
      '${worst.severe ? 'jest mocno zmęczony' : 'jest jeszcze w regeneracji'} '
      '${worst.recoveryPercent.round()}%.',
    );
    if (extra > 0) {
      message.write(' Zaangażowane też inne partie w regeneracji ($extra).');
    }
    message.write(severe
        ? ' Dziś lepiej odpuść tę partię albo zrób lżejszą wersję.'
        : ' Możesz ćwiczyć, ale rozważ niższą intensywność.');
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: color.withValues(alpha: 0.5)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(Icons.warning_amber_rounded, size: 18, color: color),
          const SizedBox(width: 8),
          Expanded(
            child: Text(message.toString(),
                style: theme.textTheme.bodySmall?.copyWith(height: 1.35)),
          ),
        ],
      ),
    );
  }
}

class ActiveExercisePlayerPage extends StatefulWidget {
  const ActiveExercisePlayerPage({super.key});

  @override
  State<ActiveExercisePlayerPage> createState() =>
      _ActiveExercisePlayerPageState();
}

class _ActiveExercisePlayerPageState extends State<ActiveExercisePlayerPage> {
  Timer? _ticker;
  bool _leaving = false;
  bool _muted = false;
  bool _workRunning = false;
  int _workSecondsLeft = 0;
  bool _wasResting = false;
  String? _loadedExId;
  int? _loadedExIndex;

  /// Odliczanie 3–2–1 przed startem ćwiczenia/serii czasowej (0 = brak).
  int _countdown = 0;

  /// Czy po zakończeniu odliczania automatycznie uruchomić timer pracy.
  bool _autoStartWork = false;

  @override
  void initState() {
    super.initState();
    _ticker = Timer.periodic(const Duration(seconds: 1), (_) => _onTick());
  }

  @override
  void dispose() {
    _ticker?.cancel();
    super.dispose();
  }

  void _onTick() {
    if (!mounted) return;
    final store = AppScope.read(context);
    final session = store.activeWorkoutSession;
    if (session == null) {
      setState(() {});
      return;
    }

    // Faza odliczania 3–2–1 przed startem ćwiczenia/serii czasowej.
    if (_countdown > 0) {
      _countdown--;
      if (_countdown <= 0) {
        _countdown = 0;
        if (_autoStartWork) {
          _autoStartWork = false;
          final active = session.currentExercise;
          if (active != null) {
            final ex =
                ExerciseRepo.byId(active.exerciseId, store.customExercises);
            final effDuration =
                active.effectiveDurationSec(ex.defaultDurationSec);
            if (ex.defaultDurationSec > 0 &&
                active.completedSets.length < active.plannedSets) {
              if (_workSecondsLeft <= 0 || _workSecondsLeft > effDuration) {
                _workSecondsLeft = effDuration;
              }
              _workRunning = true;
            }
          }
        }
      }
      _wasResting = session.hasActiveRestTimer;
      setState(() {});
      return;
    }

    final resting = session.hasActiveRestTimer;

    // Odpoczynek właśnie się zakończył — automatyczny przepływ dla ćwiczeń czasowych.
    if (_wasResting && !resting) {
      _wasResting = resting;
      _handleRestEnded(store, session);
      setState(() {});
      return;
    }
    _wasResting = resting;

    if (!resting && _workRunning && _workSecondsLeft > 0) {
      _workSecondsLeft--;
      if (_workSecondsLeft <= 0) {
        _workRunning = false;
        _completeTimedSet(store);
      }
    }
    setState(() {});
  }

  /// Po zakończeniu odpoczynku: odliczanie 3–2–1, a potem automatycznie kolejna
  /// seria tego samego ćwiczenia ALBO następne ćwiczenie — dla obu typów
  /// (czasowych i na powtórzenia). Ekran odpoczynku pokazuje, co będzie dalej,
  /// więc po odpoczynku aplikacja musi przejść dokładnie tam, bez dodatkowego
  /// klikania „Następne ćwiczenie". Timer pracy startuje automatycznie tylko
  /// dla ćwiczeń czasowych; przy ćwiczeniach na powtórzenia po odliczaniu
  /// użytkownik ląduje na gotowym panelu „Zapisz serię".
  void _handleRestEnded(AppStore store, ActiveWorkoutSession session) {
    final active = session.currentExercise;
    if (active == null) return;
    final ex = ExerciseRepo.byId(active.exerciseId, store.customExercises);
    final isTimed = ex.defaultDurationSec > 0;
    final hasMoreSets = active.completedSets.length < active.plannedSets;
    if (hasMoreSets) {
      // Kolejna seria tego samego ćwiczenia — odliczanie dla obu typów;
      // timer pracy uruchamia się automatycznie tylko dla ćwiczeń czasowych.
      if (isTimed) {
        _workSecondsLeft = active.effectiveDurationSec(ex.defaultDurationSec);
        _workRunning = false;
      }
      _startCountdown(autoStartWork: isTimed);
      return;
    }
    // Wszystkie serie wykonane (np. 2/2) → automatycznie następne ćwiczenie.
    final index = session.currentExerciseIndex;
    if (index >= session.exercises.length - 1) {
      // Ostatnie ćwiczenie treningu — jeśli cały zestaw jest ukończony,
      // od razu podsumowanie (bez martwego ekranu i klikania).
      unawaited(_maybeAutoFinish(store));
      return;
    }
    final nextActive = session.exercises[index + 1];
    final nextEx =
        ExerciseRepo.byId(nextActive.exerciseId, store.customExercises);
    unawaited(store.moveToNextActiveExercise());
    _loadedExId = null;
    _loadedExIndex = null;
    if (nextEx.defaultDurationSec > 0) {
      // Następne ćwiczenie czasowe → odliczanie 3–2–1 i automatyczny start pracy.
      _workSecondsLeft =
          nextActive.effectiveDurationSec(nextEx.defaultDurationSec);
      _workRunning = false;
      _startCountdown(autoStartWork: true);
    } else {
      // Następne ćwiczenie na serie/powtórzenia → odliczanie 3–2–1, po którym
      // użytkownik od razu widzi nowe ćwiczenie (bez klikania „Następne").
      _workSecondsLeft = 0;
      _workRunning = false;
      _startCountdown(autoStartWork: false);
    }
  }

  void _startCountdown({bool autoStartWork = true}) {
    _countdown = 3;
    _autoStartWork = autoStartWork;
  }

  void _syncExercise(ActiveWorkoutSession session, Exercise exercise,
      ActiveWorkoutExercise active) {
    if (_loadedExId == active.exerciseId &&
        _loadedExIndex == session.currentExerciseIndex) return;
    _loadedExId = active.exerciseId;
    _loadedExIndex = session.currentExerciseIndex;
    _workRunning = false;
    _workSecondsLeft = exercise.defaultDurationSec > 0
        ? active.effectiveDurationSec(exercise.defaultDurationSec)
        : 0;
  }

  Future<void> _completeTimedSet(AppStore store) async {
    final session = store.activeWorkoutSession;
    final active = session?.currentExercise;
    if (session == null || active == null) return;
    if (active.completedSets.length >= active.plannedSets) return;
    final exercise =
        ExerciseRepo.byId(active.exerciseId, store.customExercises);
    // Zapisujemy RZECZYWIŚCIE wykonany czas serii (z jakiego startował timer —
    // efektywny/rekomendowany albo ręcznie zmieniony), a wysiłek (RPE) jest
    // szacowany, nie wpisywany sztywno jako 7.
    final performed = active.effectiveDurationSec(exercise.defaultDurationSec);
    await store.logTimedSetCompleted(performedSec: performed);
    // Ostatnia seria czasowa ostatniego ćwiczenia → od razu podsumowanie.
    await _maybeAutoFinish(store);
  }

  /// Gdy cały trening jest ukończony (wszystkie ćwiczenia wykonane/pominięte),
  /// przechodzi bezpośrednio do podsumowania — bez ekranu odpoczynku i bez
  /// dodatkowego klikania. Etap: koniec treningu bez „pustego" odpoczynku.
  Future<void> _maybeAutoFinish(AppStore store) async {
    if (!mounted || _leaving) return;
    if (!store.isActiveWorkoutComplete) return;
    await _finishNow(store);
  }

  /// Otwiera arkusz danych serii i po zamknięciu sprawdza, czy trening
  /// właśnie się skończył (ostatnia seria ostatniego ćwiczenia).
  Future<void> _openStrengthSheet(AppStore store) async {
    await showActiveStrengthSheet(context);
    if (!mounted) return;
    await _maybeAutoFinish(store);
  }

  Future<void> _finishNow(AppStore store) async {
    final session = store.activeWorkoutSession;
    if (session == null) return;
    final summary = await store.finishActiveWorkout();
    if (!mounted || summary == null) return;
    _leaving = true;
    await Navigator.of(context).pushReplacement(
      MaterialPageRoute<void>(
        builder: (_) => WorkoutSummaryPage(summary: summary),
      ),
    );
  }

  Future<void> _handleExit() async {
    if (_leaving) return;
    final store = AppScope.read(context);
    final session = store.activeWorkoutSession;
    final hasSets = (session?.completedSetCount ?? 0) > 0;
    final action = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Czy zakończyć trening?'),
        content: Text(hasSets
            ? 'Zapisz trening w historii, odrzuć postęp albo wróć do ćwiczenia.'
            : 'Nie zapisano jeszcze żadnej serii. Możesz zachować trening do wznowienia, odrzucić go albo wrócić.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, 'cancel'),
              child: const Text('Anuluj')),
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, 'discard'),
              child: const Text('Odrzuć')),
          FilledButton(
              onPressed: () =>
                  Navigator.pop(dialogContext, hasSets ? 'save' : 'keep'),
              child: Text(hasSets ? 'Zapisz i wyjdź' : 'Zachowaj i wyjdź')),
        ],
      ),
    );
    if (!mounted || action == null || action == 'cancel') return;
    if (action == 'discard') {
      await store.discardActiveWorkout();
      if (!mounted) return;
      _leaving = true;
      Navigator.of(context).pop();
      return;
    }
    if (action == 'keep') {
      _leaving = true;
      Navigator.of(context).pop();
      return;
    }
    await _finishNow(store);
  }

  Future<void> _openMenu(AppStore store) async {
    final value = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.fitness_center_rounded),
              title: const Text('Dane siłowe (seria, ciężar, RPE)'),
              onTap: () => Navigator.pop(sheetContext, 'strength'),
            ),
            ListTile(
              leading: const Icon(Icons.swap_horiz_rounded),
              title: const Text('Zamień ćwiczenie'),
              onTap: () => Navigator.pop(sheetContext, 'swap'),
            ),
            ListTile(
              leading: const Icon(Icons.replay_rounded),
              title: const Text('Powtórz ćwiczenie od nowa'),
              onTap: () => Navigator.pop(sheetContext, 'repeat'),
            ),
            ListTile(
              leading: const Icon(Icons.note_alt_outlined),
              title: const Text('Notatka do ćwiczenia'),
              onTap: () => Navigator.pop(sheetContext, 'note'),
            ),
            ListTile(
              leading: Icon(
                  _muted ? Icons.volume_off_rounded : Icons.volume_up_rounded),
              title: Text(_muted ? 'Włącz komunikaty' : 'Wycisz komunikaty'),
              onTap: () => Navigator.pop(sheetContext, 'mute'),
            ),
            ListTile(
              leading: const Icon(Icons.view_list_rounded),
              title: const Text('Widok szczegółowy'),
              onTap: () => Navigator.pop(sheetContext, 'detailed'),
            ),
            const Divider(height: 1),
            ListTile(
              leading: Icon(Icons.flag_rounded,
                  color: Theme.of(sheetContext).colorScheme.error),
              title: Text('Zakończ trening',
                  style: TextStyle(
                      color: Theme.of(sheetContext).colorScheme.error,
                      fontWeight: FontWeight.w800)),
              onTap: () => Navigator.pop(sheetContext, 'finish'),
            ),
          ],
        ),
      ),
    );
    if (!mounted || value == null) return;
    switch (value) {
      case 'strength':
        await _openStrengthSheet(store);
        break;
      case 'swap':
        await showReplaceActiveExerciseSheet(context);
        break;
      case 'repeat':
        await _confirmRestartExercise(store);
        break;
      case 'note':
        await showActiveExerciseNoteSheet(context);
        break;
      case 'mute':
        setState(() => _muted = !_muted);
        break;
      case 'detailed':
        await openDetailedWorkoutView(context);
        break;
      case 'finish':
        await _handleExit();
        break;
    }
  }

  /// „Powtórz ćwiczenie": po potwierdzeniu czyści serie bieżącego ćwiczenia
  /// i ustawia je z powrotem na start (seria 1, timer od początku). Nie resetuje
  /// całego treningu ani kolejki następnych ćwiczeń.
  Future<void> _confirmRestartExercise(AppStore store) async {
    final session = store.activeWorkoutSession;
    final active = session?.currentExercise;
    if (session == null || active == null) return;
    final exercise =
        ExerciseRepo.byId(active.exerciseId, store.customExercises);
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Powtórzyć ćwiczenie od nowa?'),
        content: Text(
          active.completedSets.isEmpty
              ? '„${exercise.name}" zacznie się od pierwszej serii.'
              : 'Obecnie wpisane serie tego ćwiczenia (${active.completedSets.length}) zostaną wyczyszczone, a „${exercise.name}" zacznie się od serii 1/${active.plannedSets}. Reszta treningu i wcześniejsze ćwiczenia zostają bez zmian.',
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Powtórz od nowa')),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;
    final restarted = await store.restartCurrentActiveExercise();
    if (!restarted || !mounted) return;
    final refreshed = store.activeWorkoutSession?.currentExercise;
    setState(() {
      _countdown = 0;
      _autoStartWork = false;
      _workRunning = false;
      _workSecondsLeft = exercise.defaultDurationSec > 0
          ? (refreshed?.effectiveDurationSec(exercise.defaultDurationSec) ??
              exercise.defaultDurationSec)
          : 0;
      _wasResting = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final session = store.activeWorkoutSession;
    if (session == null || session.currentExercise == null) {
      // Sesja zakończona/odrzucona (np. z widoku szczegółowego) — nie zostawiaj
      // martwego ekranu, wróć do poprzedniej strony.
      if (!_leaving) {
        _leaving = true;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted && Navigator.of(context).canPop())
            Navigator.of(context).pop();
        });
      }
      return const Scaffold(
          body: Center(child: Text('Brak aktywnego treningu')));
    }
    final theme = Theme.of(context);
    final active = session.currentExercise!;
    final exercise =
        ExerciseRepo.byId(active.exerciseId, store.customExercises);
    _syncExercise(session, exercise, active);

    final total = session.exercises.length;
    final index = session.currentExerciseIndex;
    final resting = session.hasActiveRestTimer;
    final setsDone = active.completedSets.length;
    final setFrac = active.plannedSets == 0
        ? 0.0
        : (setsDone / active.plannedSets).clamp(0.0, 1.0);
    final progress =
        total == 0 ? 0.0 : ((index + setFrac) / total).clamp(0.0, 1.0);
    final elapsed = DateTime.now().difference(session.startedAt);

    return PopScope(
      canPop: _leaving,
      onPopInvokedWithResult: (didPop, _) async {
        if (!didPop) await _handleExit();
      },
      child: Scaffold(
        body: SafeArea(
          child: Stack(
            children: [
              Column(
                children: [
                  _buildTopBar(context, store, theme, index, total, elapsed),
                  LinearProgressIndicator(
                    value: progress,
                    minHeight: 5,
                    backgroundColor: theme.colorScheme.surfaceContainerHighest,
                  ),
                  Expanded(
                    child: resting
                        ? _buildRestState(
                            context, store, theme, session, index, total)
                        : _buildExerciseState(context, store, theme, session,
                            exercise, active, index, total),
                  ),
                ],
              ),
              if (_countdown > 0) _buildCountdownOverlay(theme),
            ],
          ),
        ),
      ),
    );
  }

  /// Duże, półprzezroczyste cyfry 3–2–1 na środku ekranu (odliczanie przed startem).
  Widget _buildCountdownOverlay(ThemeData theme) {
    return Positioned.fill(
      child: IgnorePointer(
        child: Container(
          color: theme.colorScheme.surface.withValues(alpha: 0.35),
          alignment: Alignment.center,
          child: AnimatedSwitcher(
            duration: const Duration(milliseconds: 250),
            transitionBuilder: (child, animation) => ScaleTransition(
              scale: Tween<double>(begin: 0.6, end: 1.0).animate(
                CurvedAnimation(parent: animation, curve: Curves.easeOutBack),
              ),
              child: FadeTransition(opacity: animation, child: child),
            ),
            child: Text(
              '$_countdown',
              key: ValueKey<int>(_countdown),
              style: theme.textTheme.displayLarge?.copyWith(
                fontSize: 220,
                fontWeight: FontWeight.w900,
                height: 1,
                color: theme.colorScheme.primary.withValues(alpha: 0.45),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildTopBar(BuildContext context, AppStore store, ThemeData theme,
      int index, int total, Duration elapsed) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(4, 4, 4, 4),
      child: Row(
        children: [
          IconButton(
            tooltip: 'Wyjdź',
            onPressed: _handleExit,
            icon: const Icon(Icons.close_rounded),
          ),
          Expanded(
            child: Text(
              'Ćwiczenie ${index + 1}/$total',
              style: theme.textTheme.titleMedium
                  ?.copyWith(fontWeight: FontWeight.w900),
            ),
          ),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
            decoration: BoxDecoration(
              color: theme.colorScheme.surfaceContainerHighest,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(Icons.timer_outlined,
                    size: 15, color: theme.colorScheme.onSurfaceVariant),
                const SizedBox(width: 4),
                Text(_fmtClock(elapsed.inSeconds),
                    style: theme.textTheme.labelLarge
                        ?.copyWith(fontWeight: FontWeight.w900)),
              ],
            ),
          ),
          IconButton(
            tooltip: 'Widok szczegółowy',
            onPressed: () => openDetailedWorkoutView(context),
            icon: const Icon(Icons.view_list_rounded),
          ),
          IconButton(
            tooltip: 'Menu',
            onPressed: () => _openMenu(store),
            icon: const Icon(Icons.more_vert_rounded),
          ),
        ],
      ),
    );
  }

  Widget _buildExerciseState(
    BuildContext context,
    AppStore store,
    ThemeData theme,
    ActiveWorkoutSession session,
    Exercise exercise,
    ActiveWorkoutExercise active,
    int index,
    int total,
  ) {
    final media = AnimatedSwitcher(
      duration: const Duration(milliseconds: 320),
      switchInCurve: Curves.easeOut,
      transitionBuilder: (child, animation) => FadeTransition(
        opacity: animation,
        child: SlideTransition(
          position:
              Tween<Offset>(begin: const Offset(0.06, 0), end: Offset.zero)
                  .animate(animation),
          child: child,
        ),
      ),
      child: _PlayerExerciseMedia(
        key: ValueKey('${active.exerciseId}_$index'),
        exercise: exercise,
        paused: !_workRunning && exercise.defaultDurationSec > 0,
      ),
    );

    final panel =
        _buildInfoPanel(context, store, theme, exercise, active, index, total);

    return LayoutBuilder(
      builder: (context, constraints) {
        final landscape = constraints.maxWidth > constraints.maxHeight;
        if (landscape) {
          return Row(
            children: [
              Expanded(
                  child:
                      Padding(padding: const EdgeInsets.all(12), child: media)),
              SizedBox(
                width: math.min(360, constraints.maxWidth * 0.46),
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(8, 8, 16, 16),
                  child: panel,
                ),
              ),
            ],
          );
        }
        return Column(
          children: [
            Expanded(
                child: Padding(
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
                    child: media)),
            Padding(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
                child: panel),
          ],
        );
      },
    );
  }

  Widget _buildInfoPanel(
    BuildContext context,
    AppStore store,
    ThemeData theme,
    Exercise exercise,
    ActiveWorkoutExercise active,
    int index,
    int total,
  ) {
    final isTimed = exercise.defaultDurationSec > 0;
    final setsDone = active.completedSets.length;
    final allSetsDone = setsDone >= active.plannedSets;
    final isLast = index >= total - 1;
    final coach = _coachMessage(exercise, active, isTimed, allSetsDone);
    final recoveryWarnings =
        recoveryWarningsForExercises([exercise], store.muscleRecoveryMap());

    Widget bigDisplay;
    if (isTimed && !allSetsDone) {
      bigDisplay = Text(
        _fmtClock(_workSecondsLeft),
        style: theme.textTheme.displayMedium
            ?.copyWith(fontWeight: FontWeight.w900, height: 1),
      );
    } else {
      bigDisplay = Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            'Seria ${math.min(setsDone + (allSetsDone ? 0 : 1), active.plannedSets)}/${active.plannedSets}',
            style: theme.textTheme.displaySmall
                ?.copyWith(fontWeight: FontWeight.w900, height: 1),
          ),
          const SizedBox(height: 4),
          Text(
            allSetsDone
                ? 'Ćwiczenie ukończone'
                : '${active.plannedReps} powt.${active.suggestedWeightKg > 0 ? ' · ${_formatPlanWeight(active.suggestedWeightKg)} kg' : ''}',
            style: theme.textTheme.titleMedium
                ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
          ),
        ],
      );
    }

    // Główny przycisk akcji (zależny od typu ćwiczenia / stanu).
    Widget primary;
    if (allSetsDone) {
      primary = FilledButton.icon(
        onPressed: () => _advance(store, index, total),
        icon: Icon(isLast ? Icons.flag_rounded : Icons.arrow_forward_rounded),
        label: Text(isLast ? 'Zakończ trening' : 'Następne ćwiczenie'),
      );
    } else if (isTimed) {
      primary = FilledButton.icon(
        onPressed: () => setState(() => _workRunning = !_workRunning),
        icon:
            Icon(_workRunning ? Icons.pause_rounded : Icons.play_arrow_rounded),
        label: Text(_workRunning
            ? 'Pauza'
            : (_workSecondsLeft >= exercise.defaultDurationSec
                ? 'Start'
                : 'Wznów')),
      );
    } else {
      primary = FilledButton.icon(
        onPressed: () => _openStrengthSheet(store),
        icon: const Icon(Icons.add_rounded),
        label: const Text('Zapisz serię'),
      );
    }

    // Szybkie „Powtórz poprzednią serię" — jeden klik, bez otwierania arkusza.
    final lastSet =
        active.completedSets.isEmpty ? null : active.completedSets.last;
    Widget? repeatQuick;
    if (!allSetsDone && !isTimed && lastSet != null) {
      repeatQuick = OutlinedButton.icon(
        onPressed: () async {
          final saved = await store.saveActiveWorkoutSet(
            weightKg: lastSet.weightKg,
            repetitions: lastSet.repetitions,
            rpe: lastSet.rpe,
            durationSec: lastSet.durationSec,
            distanceMeters: lastSet.distanceMeters,
          );
          if (!mounted || !saved) return;
          await _maybeAutoFinish(store);
        },
        icon: const Icon(Icons.repeat_rounded, size: 18),
        label: Text(
          'Powtórz poprzednią serię (${lastSet.repetitions} powt.'
          '${lastSet.weightKg > 0 ? ' · ${_formatPlanWeight(lastSet.weightKg)} kg' : ''}'
          '${lastSet.rpe > 0 ? ' · RPE ${lastSet.rpe}' : ''})',
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
        ),
      );
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        InkWell(
          onTap: () => showActiveExerciseInfoSheet(context, exercise),
          borderRadius: BorderRadius.circular(14),
          child: Padding(
            padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 8),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.center,
              children: [
                Flexible(
                  child: Text(
                    exercise.name,
                    textAlign: TextAlign.center,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.headlineSmall
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
                const SizedBox(width: 6),
                Icon(Icons.info_outline_rounded,
                    size: 20, color: theme.colorScheme.primary),
              ],
            ),
          ),
        ),
        const SizedBox(height: 4),
        // Rekomendowany plan sesji (już zastosowany) + ✨ gdy zmienił plan bazowy.
        if (active.prescription != null)
          Center(
            child: SessionPlanLine(
              exercise: exercise,
              prescription: active.prescription,
            ),
          ),
        const SizedBox(height: 6),
        if (recoveryWarnings.isNotEmpty) ...[
          Center(child: _RecoveryMiniWarning(warning: recoveryWarnings.first)),
          const SizedBox(height: 6),
        ],
        SizedBox(
          height: 22,
          child: Center(
            child: coach.isEmpty
                ? const SizedBox.shrink()
                : Text(
                    coach,
                    style: theme.textTheme.titleSmall?.copyWith(
                        color: theme.colorScheme.primary,
                        fontWeight: FontWeight.w900),
                  ),
          ),
        ),
        const SizedBox(height: 8),
        Center(child: bigDisplay),
        const SizedBox(height: 8),
        // Kropki postępu serii.
        if (active.plannedSets > 0)
          Wrap(
            alignment: WrapAlignment.center,
            spacing: 6,
            children: [
              for (var i = 0; i < active.plannedSets; i++)
                Icon(
                  i < setsDone ? Icons.circle : Icons.circle_outlined,
                  size: 12,
                  color: i < setsDone
                      ? theme.colorScheme.primary
                      : theme.colorScheme.outlineVariant,
                ),
            ],
          ),
        // Zmiana rekomendowanego czasu PRZED startem serii (spec: punkt 3).
        // Dostępna dla ćwiczeń czasowych, dopóki bieżąca seria nie wystartowała.
        if (isTimed && !allSetsDone && !_workRunning) ...[
          const SizedBox(height: 6),
          Center(
            child: TextButton.icon(
              onPressed: () => _editTimedDuration(store, exercise, active),
              icon: const Icon(Icons.timer_outlined, size: 18),
              label: Text('Zmień czas ($_workSecondsLeft s)'),
            ),
          ),
        ],
        const SizedBox(height: 14),
        primary,
        if (repeatQuick != null) ...[
          const SizedBox(height: 8),
          repeatQuick,
        ],
        const SizedBox(height: 10),
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            _RoundControl(
              icon: Icons.skip_previous_rounded,
              label: 'Poprzedni',
              onPressed: index <= 0
                  ? null
                  : () => store.selectActiveWorkoutExercise(index - 1),
            ),
            // Po ukończeniu wszystkich serii „Pomiń" traci sens — w jego miejscu
            // pojawia się „Powtórz" (wykonanie ćwiczenia od nowa).
            if (allSetsDone)
              _RoundControl(
                icon: Icons.replay_rounded,
                label: 'Powtórz',
                onPressed: () => _confirmRestartExercise(store),
              )
            else
              _RoundControl(
                icon: Icons.skip_next_rounded,
                label: 'Pomiń',
                onPressed: active.isSkipped
                    ? null
                    : () async {
                        await store.moveToNextActiveExercise(skipCurrent: true);
                        if (!mounted) return;
                        // Pominięcie ostatniego ćwiczenia przy ukończonej
                        // reszcie treningu → od razu podsumowanie.
                        await _maybeAutoFinish(store);
                      },
              ),
            if (isTimed)
              _RoundControl(
                icon: Icons.fitness_center_rounded,
                label: 'Dane',
                onPressed: () => _openStrengthSheet(store),
              ),
            _RoundControl(
              icon: isLast ? Icons.flag_rounded : Icons.arrow_forward_rounded,
              label: isLast ? 'Zakończ' : 'Następne',
              onPressed: () => _advance(store, index, total),
            ),
          ],
        ),
      ],
    );
  }

  Future<void> _advance(AppStore store, int index, int total) async {
    if (index >= total - 1) {
      // Trening normalnie ukończony → prosto do podsumowania, bez dialogu.
      if (store.isActiveWorkoutComplete) {
        await _finishNow(store);
        return;
      }
      await _handleExit();
      return;
    }
    await store.moveToNextActiveExercise();
  }

  /// Dialog zmiany rekomendowanego czasu serii ćwiczenia czasowego (przed startem).
  /// Zmiana staje się efektywnym czasem sesji (ręczne nadpisanie rekomendacji),
  /// timer startuje od nowej wartości, a rzeczywisty czas trafi do historii.
  Future<void> _editTimedDuration(
    AppStore store,
    Exercise exercise,
    ActiveWorkoutExercise active,
  ) async {
    final current = active.effectiveDurationSec(exercise.defaultDurationSec);
    final controller = TextEditingController(text: '$current');
    final result = await showDialog<int>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Czas serii (s)'),
        content: TextField(
          controller: controller,
          autofocus: true,
          keyboardType: TextInputType.number,
          decoration: const InputDecoration(
            labelText: 'Sekundy',
            helperText: 'Rekomendację zastąpi Twój czas dla tej sesji.',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Anuluj'),
          ),
          FilledButton(
            onPressed: () {
              final parsed = int.tryParse(controller.text.trim());
              Navigator.pop(dialogContext, parsed);
            },
            child: const Text('Zapisz'),
          ),
        ],
      ),
    );
    controller.dispose();
    if (result == null || result < 1 || result > 7200 || !mounted) return;
    await store.setActiveExerciseDuration(result);
    if (!mounted) return;
    setState(() {
      _workSecondsLeft = result;
      _workRunning = false;
    });
  }

  String _coachMessage(Exercise exercise, ActiveWorkoutExercise active,
      bool isTimed, bool allSetsDone) {
    if (allSetsDone) return 'Gotowe';
    if (!isTimed) return '';
    final total = exercise.defaultDurationSec;
    if (!_workRunning) return 'Przygotuj się';
    if (_workSecondsLeft <= 10) return 'Ostatnie 10 sekund';
    if (_workSecondsLeft >= total) return 'Start';
    if (_workSecondsLeft == (total / 2).round()) return 'Połowa czasu';
    return '';
  }

  Widget _buildRestState(
    BuildContext context,
    AppStore store,
    ThemeData theme,
    ActiveWorkoutSession session,
    int index,
    int total,
  ) {
    final remaining = session.restSecondsRemaining();
    final paused = session.isRestTimerPaused;

    // Co następuje po odpoczynku: kolejna seria bieżącego ćwiczenia albo
    // kolejne ćwiczenie (gdy wszystkie serie wykonane). Dokładnie ta pozycja
    // jest pierwszym, wyróżnionym kafelkiem — po odpoczynku aplikacja
    // przechodzi tam automatycznie (_handleRestEnded).
    final currentActive = session.currentExercise;
    final currentHasMoreSets = currentActive != null &&
        currentActive.completedSets.length < currentActive.plannedSets;
    ActiveWorkoutExercise? upcomingActive;
    String upcomingLabel;
    int queueStart;
    if (currentHasMoreSets) {
      upcomingActive = currentActive;
      upcomingLabel =
          'Następna seria ${currentActive.completedSets.length + 1}/${currentActive.plannedSets}';
      queueStart = index + 1;
    } else if (index < total - 1) {
      upcomingActive = session.exercises[index + 1];
      upcomingLabel = 'Następne ćwiczenie';
      queueStart = index + 2;
    } else {
      upcomingActive = null;
      upcomingLabel = '';
      queueStart = total;
    }
    final upcomingExercise = upcomingActive == null
        ? null
        : ExerciseRepo.byId(upcomingActive.exerciseId, store.customExercises);

    // Dalsza kolejka ćwiczeń w tym treningu (bez pominiętych), max 8 kafelków.
    final queue = <ActiveWorkoutExercise>[
      for (var i = queueStart; i < total; i++)
        if (!session.exercises[i].isSkipped) session.exercises[i],
    ];
    const maxQueueTiles = 8;
    final visibleQueue = queue.take(maxQueueTiles).toList();
    final hiddenCount = queue.length - visibleQueue.length;

    return Column(
      children: [
        Expanded(
          child: ListView(
            padding: const EdgeInsets.fromLTRB(20, 16, 20, 8),
            children: [
              Text(
                'ODPOCZYNEK',
                textAlign: TextAlign.center,
                style: theme.textTheme.titleMedium?.copyWith(
                    color: theme.colorScheme.primary,
                    fontWeight: FontWeight.w900,
                    letterSpacing: 2),
              ),
              const SizedBox(height: 6),
              Text(
                _fmtClock(remaining),
                textAlign: TextAlign.center,
                style: theme.textTheme.displayLarge?.copyWith(
                    fontWeight: FontWeight.w900, height: 1, fontSize: 72),
              ),
              if (paused) ...[
                const SizedBox(height: 4),
                Text(
                  'PAUZA',
                  textAlign: TextAlign.center,
                  style: theme.textTheme.labelLarge?.copyWith(
                      color: theme.colorScheme.tertiary,
                      fontWeight: FontWeight.w900,
                      letterSpacing: 2),
                ),
              ],
              const SizedBox(height: 18),
              if (upcomingExercise != null && upcomingActive != null)
                _RestQueueTile(
                  exercise: upcomingExercise,
                  caption: upcomingLabel,
                  subtitle: _restTileSubtitle(upcomingActive, upcomingExercise),
                  highlighted: true,
                  activeExercise: upcomingActive,
                )
              else
                // Ostatnia seria ostatniego ćwiczenia — po odpoczynku podsumowanie.
                Container(
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: theme.colorScheme.primaryContainer
                        .withValues(alpha: 0.45),
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(
                        color: theme.colorScheme.primary.withValues(alpha: 0.6),
                        width: 1.4),
                  ),
                  child: Row(
                    children: [
                      Icon(Icons.flag_rounded,
                          color: theme.colorScheme.primary, size: 32),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text('Koniec treningu',
                                style: theme.textTheme.labelMedium?.copyWith(
                                    color: theme.colorScheme.onSurfaceVariant,
                                    fontWeight: FontWeight.w800)),
                            Text(
                                'Ostatnie ćwiczenie za Tobą — dalej podsumowanie',
                                style: theme.textTheme.titleMedium
                                    ?.copyWith(fontWeight: FontWeight.w900)),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              if (visibleQueue.isNotEmpty) ...[
                const SizedBox(height: 12),
                for (final queued in visibleQueue) ...[
                  _RestQueueTile(
                    exercise: ExerciseRepo.byId(
                        queued.exerciseId, store.customExercises),
                    caption: 'W kolejce',
                    subtitle: _restTileSubtitle(
                        queued,
                        ExerciseRepo.byId(
                            queued.exerciseId, store.customExercises)),
                    highlighted: false,
                    activeExercise: queued,
                  ),
                  const SizedBox(height: 8),
                ],
                if (hiddenCount > 0)
                  Padding(
                    padding: const EdgeInsets.only(top: 2),
                    child: Text(
                      '+ jeszcze $hiddenCount ćwiczeń w tym treningu',
                      textAlign: TextAlign.center,
                      style: theme.textTheme.bodySmall
                          ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                    ),
                  ),
              ],
            ],
          ),
        ),
        // Stałe kontrolki odpoczynku na dole (nie przewijają się z kolejką).
        Padding(
          padding: const EdgeInsets.fromLTRB(20, 8, 20, 16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton(
                      onPressed: () => store.adjustActiveRestTimer(15),
                      child: const Text('+15 s'),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: OutlinedButton(
                      onPressed: () => store.adjustActiveRestTimer(30),
                      child: const Text('+30 s'),
                    ),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: () => paused
                          ? store.resumeActiveRestTimer()
                          : store.pauseActiveRestTimer(),
                      icon: Icon(paused
                          ? Icons.play_arrow_rounded
                          : Icons.pause_rounded),
                      label: Text(paused ? 'Wznów' : 'Pauza'),
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              FilledButton.icon(
                onPressed: () => store.skipActiveRestTimer(),
                icon: const Icon(Icons.skip_next_rounded),
                label: const Text('Pomiń odpoczynek'),
              ),
            ],
          ),
        ),
      ],
    );
  }

  /// Podpis kafelka kolejki: serie/powtórzenia albo czas ćwiczenia.
  String _restTileSubtitle(ActiveWorkoutExercise active, Exercise exercise) {
    if (exercise.defaultDurationSec > 0) {
      return '${active.plannedSets} × ${exercise.defaultDurationSec} s';
    }
    final weight = active.suggestedWeightKg > 0
        ? ' · ${_formatPlanWeight(active.suggestedWeightKg)} kg'
        : '';
    return '${active.plannedSets} × ${active.plannedReps} powt.$weight';
  }
}

/// Kafelek kolejki na ekranie odpoczynku: ikona/miniatura ćwiczenia, podpis
/// („Następne ćwiczenie" / „W kolejce") i nazwa. Pierwszy kafelek jest większy
/// i podświetlony ramką w kolorze akcentu — pokazuje dokładnie to, co
/// uruchomi się po odpoczynku.
class _RestQueueTile extends StatelessWidget {
  const _RestQueueTile({
    required this.exercise,
    required this.caption,
    required this.subtitle,
    required this.highlighted,
    this.activeExercise,
  });

  final Exercise exercise;
  final String caption;

  /// Zapasowy opis planu — używany, gdy sesja nie ma recepty (starszy zapis).
  final String subtitle;
  final bool highlighted;

  /// Pozycja sesji z receptą — pozwala pokazać plan EFEKTYWNY (rekomendowany)
  /// razem z ikoną AI, zamiast wartości bazowych.
  final ActiveWorkoutExercise? activeExercise;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final visualSize = highlighted ? 56.0 : 40.0;
    // Rozciąganie / mobilność — wyróżnienie kolorem akcentu motywu (punkt 9).
    final mobility = isMobilityOrStretchExercise(exercise);
    final accentColors = mobilityTileColors(theme);
    return Container(
      padding: EdgeInsets.all(highlighted ? 16 : 10),
      decoration: BoxDecoration(
        color: mobility
            ? accentColors.background
            : scheme.surfaceContainerHighest
                .withValues(alpha: highlighted ? 0.65 : 0.4),
        borderRadius: BorderRadius.circular(highlighted ? 18 : 14),
        border: highlighted
            ? Border.all(
                color: scheme.primary.withValues(alpha: 0.7), width: 1.4)
            : (mobility ? Border.all(color: accentColors.border) : null),
      ),
      child: Row(
        children: [
          SizedBox(
            width: visualSize,
            height: visualSize,
            child: ClipRRect(
              borderRadius: BorderRadius.circular(highlighted ? 14 : 10),
              child: ExerciseVisual(exercise: exercise),
            ),
          ),
          SizedBox(width: highlighted ? 14 : 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  caption,
                  style: theme.textTheme.labelSmall?.copyWith(
                    color:
                        highlighted ? scheme.primary : scheme.onSurfaceVariant,
                    fontWeight: FontWeight.w800,
                    letterSpacing: 0.3,
                  ),
                ),
                const SizedBox(height: 2),
                Row(
                  children: [
                    Flexible(
                      child: Text(
                        exercise.name,
                        maxLines: highlighted ? 2 : 1,
                        overflow: TextOverflow.ellipsis,
                        style: (highlighted
                                ? theme.textTheme.titleLarge
                                : theme.textTheme.titleSmall)
                            ?.copyWith(fontWeight: FontWeight.w900),
                      ),
                    ),
                    if (mobility) ...[
                      const SizedBox(width: 6),
                      MobilityBadge(size: highlighted ? 18 : 14),
                    ],
                  ],
                ),
                // Plan sesji: gdy jest recepta, pokazujemy wartości EFEKTYWNE
                // (te, od których wystartuje timer) wraz z ikoną AI i wejściem
                // w „dlaczego". Bez recepty — zapasowy opis z planu bazowego.
                if (activeExercise?.prescription != null) ...[
                  const SizedBox(height: 1),
                  SessionPlanLine(
                    exercise: exercise,
                    prescription: activeExercise!.prescription,
                    compact: true,
                  ),
                ] else if (subtitle.isNotEmpty) ...[
                  const SizedBox(height: 1),
                  Text(
                    subtitle,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: scheme.onSurfaceVariant),
                  ),
                ],
              ],
            ),
          ),
        ],
      ),
    );
  }
}

/// Duże medium ćwiczenia w trybie aktywnym: GIF (loop), zdjęcie, poster wideo
/// albo estetyczny fallback. Etap 30.
class _PlayerExerciseMedia extends StatelessWidget {
  const _PlayerExerciseMedia(
      {super.key, required this.exercise, this.paused = false});

  final Exercise exercise;
  final bool paused;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final animated = exercise.animatedMediaPath;
    final staticPath = exercise.staticMediaPath;
    final fallback = ExercisePlaceholder(exercise: exercise);

    // Etap 33: wideo instruktażowe (asset/plik) jest głównym medium w trakcie treningu.
    final videoPath = exercise.videoMediaPath;
    final videoLower = videoPath?.toLowerCase() ?? '';
    final isRemoteVideo =
        videoLower.startsWith('http://') || videoLower.startsWith('https://');
    final playableVideo = videoPath != null && !kIsWeb && !isRemoteVideo;

    Widget media;
    Widget? badge;
    if (playableVideo) {
      media =
          _LoopingVideo(source: videoPath, paused: paused, fallback: fallback);
      badge = _badge(theme, Icons.movie_outlined, 'Wideo');
    } else if (animated != null) {
      media = buildExerciseMediaImage(animated,
          fit: BoxFit.contain, fallback: fallback);
      badge = _badge(theme, Icons.gif_box_outlined, 'Animacja');
    } else if (staticPath != null) {
      media = buildExerciseMediaImage(staticPath,
          fit: BoxFit.contain, fallback: fallback);
      badge = _badge(theme, Icons.image_outlined, 'Zdjęcie');
    } else if (exercise.hasVideo) {
      // Wideo zdalne / web — pokaż poster + ikonę odtwarzania (bez wbudowanego odtwarzacza).
      final poster = exercise.thumbnailMediaPath;
      media = Stack(
        fit: StackFit.expand,
        children: [
          if (poster != null)
            buildExerciseMediaImage(poster,
                fit: BoxFit.contain, fallback: fallback)
          else
            fallback,
          Container(
            color: Colors.black.withValues(alpha: 0.25),
            alignment: Alignment.center,
            child: const Icon(Icons.play_circle_fill_rounded,
                size: 64, color: Colors.white),
          ),
        ],
      );
      badge = _badge(theme, Icons.movie_outlined, 'Wideo');
    } else {
      media = fallback;
    }

    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surfaceContainerHighest,
        borderRadius: BorderRadius.circular(24),
        border: Border.all(
            color: theme.colorScheme.outlineVariant.withValues(alpha: 0.4)),
      ),
      clipBehavior: Clip.antiAlias,
      child: Stack(
        fit: StackFit.expand,
        children: [
          Padding(padding: const EdgeInsets.all(10), child: media),
          if (badge != null) Positioned(left: 12, top: 12, child: badge),
          if (paused)
            Container(
              color: Colors.black.withValues(alpha: 0.35),
              alignment: Alignment.center,
              child: Icon(Icons.pause_circle_filled_rounded,
                  size: 72, color: Colors.white.withValues(alpha: 0.9)),
            ),
        ],
      ),
    );
  }

  Widget _badge(ThemeData theme, IconData icon, String label) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
          color: theme.colorScheme.primary,
          borderRadius: BorderRadius.circular(12)),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 14, color: theme.colorScheme.onPrimary),
          const SizedBox(width: 4),
          Text(label,
              style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  color: theme.colorScheme.onPrimary)),
        ],
      ),
    );
  }
}

/// Zapętlone, wyciszone wideo instruktażowe (asset albo plik z dysku).
/// Autoodtwarzanie z reagowaniem na pauzę treningu; błąd inicjalizacji albo brak
/// pliku → [fallback] (nigdy nie crashuje). Etap 33.
class _LoopingVideo extends StatefulWidget {
  const _LoopingVideo(
      {required this.source, required this.paused, required this.fallback});

  final String source;
  final bool paused;
  final Widget fallback;

  @override
  State<_LoopingVideo> createState() => _LoopingVideoState();
}

class _LoopingVideoState extends State<_LoopingVideo> {
  VideoPlayerController? _controller;
  bool _failed = false;

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _init() async {
    try {
      final controller = widget.source.startsWith('assets/')
          ? VideoPlayerController.asset(widget.source)
          : VideoPlayerController.file(File(widget.source));
      await controller.initialize();
      await controller.setLooping(true);
      await controller.setVolume(0);
      if (!mounted) {
        await controller.dispose();
        return;
      }
      if (!widget.paused) {
        await controller.play();
      }
      setState(() => _controller = controller);
    } catch (_) {
      if (mounted) setState(() => _failed = true);
    }
  }

  @override
  void didUpdateWidget(covariant _LoopingVideo oldWidget) {
    super.didUpdateWidget(oldWidget);
    final controller = _controller;
    if (controller == null) return;
    if (widget.paused && controller.value.isPlaying) {
      controller.pause();
    } else if (!widget.paused && !controller.value.isPlaying) {
      controller.play();
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (_failed) return widget.fallback;
    final controller = _controller;
    if (controller == null || !controller.value.isInitialized) {
      return const _MediaLoadingBox();
    }
    return FittedBox(
      fit: BoxFit.contain,
      child: SizedBox(
        width: controller.value.size.width,
        height: controller.value.size.height,
        child: VideoPlayer(controller),
      ),
    );
  }
}

/// Okrągły przycisk sterujący z etykietą (poprzedni/pomiń/następne itd.). Etap 30.
