        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.warning_amber_rounded, size: 14, color: accent),
          const SizedBox(width: 5),
          Flexible(
            child: Text(
              '${warning.muscle.label} w regeneracji · ${warning.recoveryPercent.round()}%',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: theme.textTheme.bodySmall
                  ?.copyWith(fontWeight: FontWeight.w800, color: accent),
            ),
          ),
        ],
      ),
    );
  }
}

/// Pełny ekran „Regeneracja mięśni". Etap regeneracji.
class MuscleRecoveryPage extends StatefulWidget {
  const MuscleRecoveryPage({super.key});

  @override
  State<MuscleRecoveryPage> createState() => _MuscleRecoveryPageState();
}

class _MuscleRecoveryPageState extends State<MuscleRecoveryPage> {
  BodyMuscleSide _side = BodyMuscleSide.front;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final dark = theme.brightness == Brightness.dark;
    final recovery = store.muscleRecoveryMap();
    final fatigued = recovery.values.where((state) => state.hasData).toList()
      ..sort((a, b) =>
          (a.recoveryPercent ?? 100).compareTo(b.recoveryPercent ?? 100));

    return Scaffold(
      appBar: AppBar(title: const Text('Regeneracja mięśni')),
      body: SafeArea(
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
          children: [
            const DeloadRecoveryContextCard(),
            Center(
                child: _BodySideToggle(
                    side: _side, onChanged: (s) => setState(() => _side = s))),
            const SizedBox(height: 12),
            SizedBox(
              height: 360,
              child: AnimatedSwitcher(
                duration: const Duration(milliseconds: 280),
                child: BodyMuscleMap(
                  key: ValueKey(_side),
                  side: _side,
                  dark: dark,
                  recovery: recovery,
                  onMuscleTap: (muscle) => showMuscleRecoverySheet(
                      context, muscle, recovery[muscle]),
                  onBackgroundTap: () => setState(() => _side =
                      _side == BodyMuscleSide.front
                          ? BodyMuscleSide.back
                          : BodyMuscleSide.front),
                ),
              ),
            ),
            const SizedBox(height: 12),
            const RecoveryLegend(),
            const SizedBox(height: 16),
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color:
                    theme.colorScheme.primaryContainer.withValues(alpha: 0.4),
                borderRadius: BorderRadius.circular(16),
              ),
              child: Row(
                children: [
                  Icon(Icons.tips_and_updates_outlined,
                      color: theme.colorScheme.primary),
                  const SizedBox(width: 10),
                  Expanded(
                      child: Text(overallRecoverySuggestion(recovery),
                          style: theme.textTheme.bodyMedium)),
                ],
              ),
            ),
            const SizedBox(height: 18),
            if (fatigued.isEmpty)
              Container(
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  color: theme.colorScheme.surfaceContainerHighest
                      .withValues(alpha: 0.5),
                  borderRadius: BorderRadius.circular(18),
                ),
                child: Row(
                  children: [
                    Icon(Icons.self_improvement_rounded,
                        color: theme.colorScheme.primary),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Text(
                        'Brak danych regeneracji — wykonaj trening z przypisanymi partiami mięśniowymi, aby zobaczyć mapę.',
                        style: theme.textTheme.bodyMedium?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant),
                      ),
                    ),
                  ],
                ),
              )
            else ...[
              Text('Najbardziej zmęczone partie',
                  style: theme.textTheme.titleMedium
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 10),
              for (final state in fatigued.take(6))
                _FatiguedMuscleRow(state: state),
            ],
            const SizedBox(height: 18),
            // Ocena tygodnia i rekomendacje po treningu (przeniesione z „Więcej").
            RecoveryCoachCard(
              logs: store.logsBetween(
                  DateTime.now().subtract(const Duration(days: 6)),
                  DateTime.now()),
            ),
            const SizedBox(height: 12),
            PostWorkoutRecommendationCard(
              logs: store.logsBetween(
                  DateTime.now().subtract(const Duration(days: 6)),
                  DateTime.now()),
            ),
            const SizedBox(height: 12),
            // Parametry użytkownika wpływające na obliczenia regeneracji.
            Card(
              clipBehavior: Clip.antiAlias,
              child: ListTile(
                leading:
                    Icon(Icons.tune_rounded, color: theme.colorScheme.primary),
                title: const Text('Profil regeneracji'),
                subtitle: Text(
                  'Poziom: ${store.settings.level} · ${store.settings.bodyWeightKg.round()} kg · ${store.settings.age} lat'
                  '${store.settings.sex.isEmpty ? '' : ' · ${store.settings.sex}'}'
                  ' · ${store.settings.trainingWeekdays.length} dni treningowych. Dotknij, aby doprecyzować.',
                ),
                trailing: const Icon(Icons.chevron_right_rounded),
                onTap: () => openTrainerSubPage(
                    context, const TrainingProfilePage(),
                    title: 'Profil treningowy'),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class _FatiguedMuscleRow extends StatelessWidget {
  const _FatiguedMuscleRow({required this.state});

  final MuscleRecoveryState state;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final dark = theme.brightness == Brightness.dark;
    final color = recoveryColor(state.recoveryPercent, dark: dark);
    final percent = (state.recoveryPercent ?? 0).round();
    final eta = state.estimatedHoursRemaining <= 0
        ? 'gotowe'
        : '~${state.estimatedHoursRemaining} h';
    return InkWell(
      borderRadius: BorderRadius.circular(14),
      onTap: () => showMuscleRecoverySheet(context, state.muscleGroup, state),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 8),
        child: Row(
          children: [
            Container(
                width: 14,
                height: 14,
                decoration:
                    BoxDecoration(color: color, shape: BoxShape.circle)),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Expanded(
                          child: Text(state.muscleGroup.label,
                              style: theme.textTheme.bodyLarge
                                  ?.copyWith(fontWeight: FontWeight.w800))),
                      Text('$percent%',
                          style: theme.textTheme.bodyMedium
                              ?.copyWith(fontWeight: FontWeight.w900)),
                    ],
                  ),
                  const SizedBox(height: 4),
                  ClipRRect(
                    borderRadius: BorderRadius.circular(6),
                    child: LinearProgressIndicator(
                      value: percent / 100,
                      minHeight: 6,
                      backgroundColor:
                          theme.colorScheme.surfaceContainerHighest,
                      valueColor: AlwaysStoppedAnimation<Color>(color),
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    '${state.statusLabel}${state.intensityLabel.isEmpty ? '' : ' · ${state.intensityLabel.toLowerCase()}'} · do pełnej regeneracji $eta',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// Rozgrzewka, mobilizacja i rozciąganie NIE mają już osobnego, tekstowego
// podsystemu (karty, statusy „wykonana/pominięta", biblioteka procedur).
// Ćwiczenia rozgrzewkowe i mobilizacyjne są pozycjami programów — jedynym
// źródłem prawdy — więc nie dublujemy ich instrukcjami obok programu.

class _ActiveWorkoutHeader extends StatelessWidget {
  const _ActiveWorkoutHeader({
    required this.session,
    required this.elapsed,
    required this.onEditNote,
  });

  final ActiveWorkoutSession session;
  final Duration elapsed;
  final VoidCallback onEditNote;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final plannedSets = session.exercises
        .fold<int>(0, (sum, exercise) => sum + exercise.plannedSets);
    final progress =
        plannedSets == 0 ? 0.0 : session.completedSetCount / plannedSets;
    return Card(
      color: theme.colorScheme.primaryContainer.withValues(alpha: 0.45),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: Text(session.planName,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                      style: theme.textTheme.titleLarge
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
                IconButton(
                  tooltip: 'Notatka do sesji',
                  onPressed: onEditNote,
                  icon: Icon(session.note.isEmpty
                      ? Icons.note_add_outlined
                      : Icons.sticky_note_2_rounded),
                ),
              ],
            ),
            const SizedBox(height: 4),
            Text('${weekdayName(session.weekday)} · ${session.dayTitle}',
                style: theme.textTheme.bodyMedium
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            if (session.note.isNotEmpty) ...[
              const SizedBox(height: 8),
              Text(session.note,
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.bodyMedium),
            ],
            const SizedBox(height: 14),
            Row(
              children: [
                Expanded(
                    child: Text('Czas ${formatWorkoutDuration(elapsed)}',
                        style: theme.textTheme.labelLarge
                            ?.copyWith(fontWeight: FontWeight.w800))),
                Text('${session.completedSetCount}/$plannedSets serii',
                    style: theme.textTheme.labelLarge
                        ?.copyWith(fontWeight: FontWeight.w800)),
              ],
            ),
            const SizedBox(height: 8),
            LinearProgressIndicator(value: progress.clamp(0, 1)),
          ],
        ),
      ),
    );
  }
}

class _ActiveRestTimerCard extends StatelessWidget {
  const _ActiveRestTimerCard({
    required this.session,
    required this.recommendation,
  });

  final ActiveWorkoutSession session;
  final WorkoutRestRecommendation recommendation;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final remaining = session.restSecondsRemaining();
    final total = math.max(session.restTimerTotalSeconds, 1);
    final progress = remaining / total;
    return Card(
      color: theme.colorScheme.secondaryContainer.withValues(alpha: 0.55),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.timer_outlined, color: theme.colorScheme.secondary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Przerwa między seriami',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
                Text(formatWorkoutDuration(Duration(seconds: remaining)),
                    style: theme.textTheme.headlineSmall
                        ?.copyWith(fontWeight: FontWeight.w900)),
              ],
            ),
            const SizedBox(height: 4),
            Text(recommendation.label,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            const SizedBox(height: 10),
            LinearProgressIndicator(value: progress.clamp(0, 1)),
            const SizedBox(height: 12),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                FilledButton.tonalIcon(
                  onPressed: session.isRestTimerPaused
                      ? store.resumeActiveRestTimer
                      : store.pauseActiveRestTimer,
                  icon: Icon(session.isRestTimerPaused
                      ? Icons.play_arrow_rounded
                      : Icons.pause_rounded),
                  label: Text(session.isRestTimerPaused ? 'Wznów' : 'Pauza'),
                ),
                OutlinedButton(
                  onPressed: () => store.adjustActiveRestTimer(-30),
                  child: const Text('−30 s'),
                ),
                OutlinedButton(
                  onPressed: () => store.adjustActiveRestTimer(30),
                  child: const Text('+30 s'),
                ),
                TextButton.icon(
                  onPressed: store.skipActiveRestTimer,
                  icon: const Icon(Icons.skip_next_rounded),
                  label: const Text('Pomiń'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

Future<void> showActiveExerciseNoteSheet(BuildContext context) async {
  final store = AppScope.read(context);
  var note = store.activeWorkoutSession?.currentExercise?.note ?? '';
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => Padding(
      padding: EdgeInsets.fromLTRB(
          16,
          0,
          16,
          16 +
              MediaQuery.of(sheetContext).viewInsets.bottom +
              MediaQuery.of(sheetContext).viewPadding.bottom),
