Future<void> showReplaceActiveExerciseSheet(BuildContext context) async {
  final store = AppScope.read(context);
  final session = store.activeWorkoutSession;
  final current = session?.currentExercise;
  if (current == null) return;
  final usedExerciseIds = session!.exercises
      .where((exercise) => exercise != current)
      .map((exercise) => exercise.exerciseId)
      .toSet();
  var query = '';
  final replacement = await showModalBottomSheet<Exercise>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) {
        final exercises =
            ExerciseRepo.combined(store.customExercises).where((exercise) {
          if (exercise.id == current.exerciseId ||
              usedExerciseIds.contains(exercise.id) ||
              store.isExerciseHidden(exercise.id)) return false;
          return query.isEmpty || exercise.name.toLowerCase().contains(query);
        }).toList();
        return FractionallySizedBox(
          heightFactor: 0.86,
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Zamień ćwiczenie',
                        style: Theme.of(context)
                            .textTheme
                            .titleLarge
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 4),
                    Text(
                      current.completedSets.isEmpty
                          ? 'Wybierz ćwiczenie zastępcze.'
                          : 'Zapisane serie pozostaną bez zmian i zostaną przypisane do zamiennika.',
                      style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                          color:
                              Theme.of(context).colorScheme.onSurfaceVariant),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      autofocus: true,
                      decoration: const InputDecoration(
                          prefixIcon: Icon(Icons.search_rounded),
                          labelText: 'Szukaj po nazwie'),
                      onChanged: (value) => setSheetState(
                          () => query = value.trim().toLowerCase()),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: exercises.isEmpty
                    ? const Center(child: Text('Brak pasujących ćwiczeń'))
                    : ListView.builder(
                        padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
                        itemCount: exercises.length,
                        itemBuilder: (context, index) {
                          final exercise = exercises[index];
                          return Card(
                            margin: const EdgeInsets.only(bottom: 8),
                            child: ListTile(
                              leading: SizedBox(
                                  width: 48,
                                  height: 48,
                                  child: ExerciseVisual(exercise: exercise)),
                              title: Text(exercise.name,
                                  maxLines: 2, overflow: TextOverflow.ellipsis),
                              subtitle: Text(
                                  '${exercise.primaryMuscle} · ${exercise.equipment}',
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis),
                              trailing: const Icon(Icons.swap_horiz_rounded),
                              onTap: () =>
                                  Navigator.pop(sheetContext, exercise),
                            ),
                          );
                        },
                      ),
              ),
            ],
          ),
        );
      },
    ),
  );
  if (replacement != null)
    await store.replaceActiveWorkoutExercise(replacement);
}

class _CurrentExerciseCard extends StatelessWidget {
  const _CurrentExerciseCard({
    required this.exercise,
    required this.activeExercise,
    required this.position,
    required this.total,
  });

  final Exercise exercise;
  final ActiveWorkoutExercise activeExercise;
  final int position;
  final int total;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final recommendation = workoutRestRecommendation(
      exercise,
      activeExercise,
    );
    // Rozciąganie / mobilność — wyróżnienie kolorem akcentu motywu (punkt 9).
    final mobility = isMobilityOrStretchExercise(exercise);
    final accentColors = mobilityTileColors(theme);
    return Card(
      clipBehavior: Clip.antiAlias,
      color: mobility ? accentColors.background : null,
      shape: mobility
          ? RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
              side: BorderSide(color: accentColors.border),
            )
          : null,
      child: InkWell(
        onTap: () => showActiveExerciseInfoSheet(context, exercise),
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                  width: 82,
                  height: 82,
                  child: ExerciseVisual(exercise: exercise)),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Ćwiczenie $position z $total',
                        style: theme.textTheme.labelMedium?.copyWith(
                            color: theme.colorScheme.primary,
                            fontWeight: FontWeight.w900)),
                    const SizedBox(height: 3),
                    Row(
                      children: [
                        Flexible(
                          child: Text(exercise.name,
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: theme.textTheme.titleLarge
                                  ?.copyWith(fontWeight: FontWeight.w900)),
                        ),
                        if (mobility) ...[
                          const SizedBox(width: 6),
                          const MobilityBadge(size: 18),
                        ],
                      ],
                    ),
                    const SizedBox(height: 6),
                    if (activeExercise.prescription != null)
                      SessionPlanLine(
                        exercise: exercise,
                        prescription: activeExercise.prescription,
                      )
                    else
                      Text(
                          '${activeExercise.plannedSets} serie × ${activeExercise.plannedReps} powt. · ${recommendation.seconds} s przerwy',
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant)),
                  ],
                ),
              ),
              const SizedBox(width: 6),
              Icon(Icons.info_outline_rounded,
                  size: 22, color: theme.colorScheme.primary),
            ],
          ),
        ),
      ),
    );
  }
}

