class _ActiveWorkoutExerciseTile extends StatelessWidget {
  const _ActiveWorkoutExerciseTile({
    required this.activeExercise,
    required this.exercise,
    required this.selected,
    required this.onTap,
  });

  final ActiveWorkoutExercise activeExercise;
  final Exercise exercise;
  final bool selected;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final complete =
        activeExercise.completedSets.length >= activeExercise.plannedSets;
    // Rozciąganie / mobilność wyróżniamy kolorem akcentu motywu (punkt 9).
    final mobility = isMobilityOrStretchExercise(exercise);
    final accentColors = mobilityTileColors(theme);
    return Card(
      color: selected
          ? theme.colorScheme.primaryContainer.withValues(alpha: 0.5)
          : (mobility ? accentColors.background : null),
      margin: const EdgeInsets.only(bottom: 8),
      shape: mobility
          ? RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(12),
              side: BorderSide(color: accentColors.border),
            )
          : null,
      child: ListTile(
        onTap: onTap,
        leading: Icon(
          complete
              ? Icons.check_circle_rounded
              : activeExercise.isSkipped
                  ? Icons.skip_next_rounded
                  : Icons.radio_button_unchecked_rounded,
          color: complete || selected
              ? theme.colorScheme.primary
              : theme.colorScheme.onSurfaceVariant,
        ),
        title: Row(
          children: [
            Flexible(
              child: Text(exercise.name,
                  maxLines: 2, overflow: TextOverflow.ellipsis),
            ),
            if (mobility) ...[
              const SizedBox(width: 6),
              const MobilityBadge(),
            ],
          ],
        ),
        subtitle: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
                '${activeExercise.completedSets.length}/${activeExercise.plannedSets} serii',
                maxLines: 1),
            // Plan EFEKTYWNY sesji + ikona AI, gdy rekomendacja zmieniła bazę.
            // Widoczny też w przeglądzie kolejki, nie tylko podczas wykonywania.
            if (activeExercise.prescription != null)
              SessionPlanLine(
                exercise: exercise,
                prescription: activeExercise.prescription,
                compact: true,
              ),
          ],
        ),
        trailing: selected ? const Icon(Icons.chevron_right_rounded) : null,
      ),
    );
  }
}

class WorkoutSummaryPage extends StatefulWidget {
