  /// Podpowiedź rozciągania PO ciężkim dniu. Świadomie sugestia, nie bramka —
  /// blokowanie treningu do czasu rozciągnięcia szybko zamienia się w klikanie
  /// „pomiń". Pokazuje się tylko, gdy skończony dzień był ciężki i partia ma
  /// swój zestaw rozciągania.
  Widget _buildStretchSuggestion(ThemeData theme) {
    final store = AppScope.of(context);
    final summary = widget.summary;
    if (summary.planId.isEmpty || summary.dayIndex < 0) {
      return const SizedBox.shrink();
    }
    WorkoutPlan? plan;
    for (final candidate in store.plans) {
      if (candidate.id == summary.planId) {
        plan = candidate;
        break;
      }
    }
    if (plan == null ||
        summary.dayIndex >= plan.days.length ||
        !plan.days[summary.dayIndex].kind.isHeavy) {
      return const SizedBox.shrink();
    }
    final stretch = stretchWorkoutForPlan(summary.planId);
    if (stretch == null) return const SizedBox.shrink();

    final scheme = theme.colorScheme;
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Container(
        key: const Key('post_workout_stretch'),
        padding: const EdgeInsets.fromLTRB(14, 12, 12, 12),
        decoration: BoxDecoration(
          color: scheme.primary.withValues(alpha: 0.12),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: scheme.primary.withValues(alpha: 0.45)),
        ),
        child: Row(
          children: [
            Icon(Icons.self_improvement_rounded, color: scheme.primary),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('To był ciężki dzień — rozciągnij się',
                      style: theme.textTheme.titleSmall
                          ?.copyWith(fontWeight: FontWeight.w900)),
                  const SizedBox(height: 2),
                  Text('${stretch.title} · ~${stretch.estimatedMinutes} min',
                      style: theme.textTheme.bodySmall
                          ?.copyWith(color: scheme.onSurfaceVariant)),
                ],
              ),
            ),
            const SizedBox(width: 8),
            FilledButton.tonal(
              key: const Key('post_workout_stretch_start'),
              onPressed: () => startStretchWorkout(context, stretch),
              child: const Text('Zacznij'),
            ),
          ],
        ),
      ),
    );
  }

