  /// Uruchamia (albo ponawia) analizę AI zapisanego treningu. Ponowienie NIE
  /// zapisuje treningu ponownie — korzysta z już zapisanego podsumowania.
  /// Błąd pokazujemy jako krótki komunikat; szczegóły idą wyłącznie do logów.
  Future<void> _runAiAnalysis() async {
    final store = AppScope.of(context);
    setState(() {
      _aiLoading = true;
      _aiError = null;
    });
    try {
      await store.analyzeCompletedWorkout(widget.summary);
    } catch (error, stack) {
      if (kDebugMode) {
        debugPrint('[AI] Analiza treningu nie powiodła się: $error\n$stack');
      }
      if (mounted) setState(() => _aiError = kWorkoutAnalysisFailedMessage);
    } finally {
      if (mounted) setState(() => _aiLoading = false);
    }
  }

