// ============================================================================
// ETAP 28 — Profesjonalny widok programu treningowego (nagłówek, postęp,
// sekcja „Dzisiaj", lista dni z blokowaniem i statusami).
// ============================================================================

/// Szacunek dnia treningowego: liczba ćwiczeń, czas (min) i kalorie.
// ===========================================================================
// Katalog 30-dniowych programów treningowych (Etap: programy)
// ===========================================================================

/// Resolver definicji ćwiczeń dla generatora programów.
Exercise Function(String) _programExerciseResolver(AppStore store) =>
    (id) => ExerciseRepo.byId(id, store.customExercises);

/// Znajduje w planach użytkownika program katalogu o danym [programId]
/// (dopasowanie po prefiksie id, niezależnie od poziomu).
WorkoutPlan? findCatalogPlan(AppStore store, String programId) {
  for (final plan in store.plans) {
    if (plan.id == programId || plan.id.startsWith('${programId}_'))
      return plan;
  }
  return null;
}

/// Startuje (lub wznawia) program katalogu: dodaje go do planów, jeśli go nie ma,
/// ustawia jako aktywny i zwraca plan. [level] pozwala wygenerować dany poziom
/// (początkujący / średni / zaawansowany), zachowując dotychczasowy postęp.
/// Profil użytkownika do dopasowania programów — zbudowany z ustawień
/// profilu treningowego (poziom, tryb, cel, sprzęt, ograniczenia, wiek,
/// wzrost, waga, płeć, dni treningowe).
ProgramUserProfile programUserProfileFor(AppStore store) {
  final settings = store.settings;
  return ProgramUserProfile(
    level: settings.level.isNotEmpty ? settings.level : 'Średniozaawansowany',
    trainingMode: settings.trainingMode,
    goal: settings.goal,
    equipment: settings.equipment,
    limitations: settings.limitations,
    bodyWeightKg: settings.bodyWeightKg,
    heightCm: settings.heightCm,
    age: settings.age,
    sex: settings.sex,
    trainingDaysPerWeek: settings.trainingWeekdays.length,
  );
}

Future<WorkoutPlan> startCatalogProgram(
  BuildContext context,
  String programId, {
  String? level,
}) async {
  final store = AppScope.read(context);
  var plan = findCatalogPlan(store, programId);
  final wantsLevelChange = level != null &&
      plan != null &&
      normalizeTrainingLevel(level) != normalizeTrainingLevel(plan.level);

  // Istniejące (już wystartowane) programy zostają nietknięte — profil
  // wpływa tylko na nowo budowane / przebudowywane plany.
  final settings = store.settings;
  if (plan == null) {
    plan = buildEquipmentAwareProgram(
      store,
      programId,
      level: level ??
          (settings.level.isNotEmpty ? settings.level : 'Średniozaawansowany'),
    ).copyWith(isActive: true);
    await store.addWorkoutPlan(plan);
  } else if (wantsLevelChange) {
    final rebuilt = buildEquipmentAwareProgram(
      store,
      programId,
      level: level,
    ).copyWith(id: plan.id, isActive: true, completedDays: plan.completedDays);
    await store.updateWorkoutPlan(rebuilt);
    plan = rebuilt;
  } else {
    await store.setActiveWorkoutPlan(plan.id);
  }
  return plan;
}

/// Id programu z katalogu dla zapisanego planu (`program_chest`,
/// `program_chest_Zaawansowany` → `program_chest`). null = plan spoza katalogu.
String? catalogProgramIdForPlan(String planId) {
  for (final meta in kWorkoutProgramCatalog) {
    if (planId == meta.id || planId.startsWith('${meta.id}_')) return meta.id;
  }
  return null;
}

/// Przelicza AKTYWNY program katalogu na poziom z profilu, zachowując
/// tożsamość planu i postęp (`id`, `completedDays`, wariant, okładka).
///
/// Potrzebne po naprawie błędu normalizacji poziomu: plany zapisane wcześniej
/// mogły dostać poziom „Zaawansowany", mimo że profil mówi co innego.
Future<bool> repairActivePlanLevel(BuildContext context) async {
  final store = AppScope.read(context);
  final plan = store.activeWorkoutPlan;
  if (plan == null) return false;
  final programId = catalogProgramIdForPlan(plan.id);
  if (programId == null) return false;
  final rebuilt = buildEquipmentAwareProgram(
    store,
    programId,
    level: store.settings.level,
  ).copyWith(
    id: plan.id,
    isActive: true,
    completedDays: plan.completedDays,
    activeVariantId: plan.activeVariantId,
    variantHistory: plan.variantHistory,
    media: plan.media,
  );
  await store.updateWorkoutPlan(rebuilt);
  return true;
}

/// Buduje program 30-dniowy i dopasowuje go do sprzętu oraz ograniczeń
/// użytkownika (filtr + zamienniki). Postępy nie są tu ruszane — to buduje
/// świeżą TREŚĆ planu; wywołujący zachowuje `completedDays`/`id`/`isActive`.
WorkoutPlan buildEquipmentAwareProgram(
  AppStore store,
  String programId, {
  required String level,
}) {
  final settings = store.settings;
  final resolver = _programExerciseResolver(store);
  final base = buildWorkoutProgram(
    programId,
    resolveExercise: resolver,
    level: level,
    bodyWeightKg: settings.bodyWeightKg,
    heightCm: settings.heightCm,
    age: settings.age,
  );
  final filtered = applyEquipmentToPlan(
    base,
    settings.equipmentProfile,
    settings.limitationProfile,
    resolver,
  );
  return filtered.plan;
}

/// Podsumowuje ZAPISANY plan pod kątem sprzętu (do informacji w UI): jakiego
/// sprzętu używa, ile pozycji to zamienniki oraz czy coś jeszcze nie pasuje do
/// aktualnego profilu (walidacja). Liczone z treści planu — nie przelicza go.
EquipmentPlanReport summarizeSavedPlanEquipment(
    AppStore store, WorkoutPlan plan) {
  final resolver = _programExerciseResolver(store);
  final profile = store.settings.equipmentProfile;
  final owned = profile.resolveOwned();
  final used = <EquipmentType>{};
  var substituted = 0;
  for (final day in plan.days) {
    for (final item in day.items) {
      if (item.note.contains('zamiennik za:')) substituted++;
      used.addAll(satisfiedEquipmentFor(resolver(item.exerciseId), owned));
    }
  }
  used.removeAll(kAlwaysAvailableEquipment);
  return EquipmentPlanReport(
    usedEquipment: used,
    substitutedCount: substituted,
    removedCount: 0,
    profile: profile,
    limits: store.settings.limitationProfile,
  );
}

/// Czy plan to program katalogu 30-dniowego (a nie np. jednodniowe cardio).
bool isCatalogProgramPlan(WorkoutPlan plan) => kWorkoutProgramCatalog.any(
      (m) => plan.id == m.id || plan.id.startsWith('${m.id}_'),
    );

/// Po zmianie sprzętu/ograniczeń: jeśli któryś ROZPOCZĘTY program katalogu ma
/// w POZOSTAŁYCH (nieukończonych) dniach ćwiczenia niepasujące do nowego
/// profilu, proponuje dostosowanie. Ukończone dni i postęp są ZAWSZE zachowane.
Future<void> offerEquipmentReadjustForActivePlans(BuildContext context) async {
  final store = AppScope.read(context);
  final resolver = _programExerciseResolver(store);
  final profile = store.settings.equipmentProfile;
  final limits = store.settings.limitationProfile;

  final needing = <WorkoutPlan>[];
  for (final plan in store.plans) {
    if (!isCatalogProgramPlan(plan) || plan.isProgramCompleted) continue;
    final issues = validatePlanEquipment(
      plan,
      profile,
      limits,
      resolver,
      fromDayIndex: plan.currentDayIndex,
    );
    if (issues.isNotEmpty) needing.add(plan);
  }
  if (needing.isEmpty || !context.mounted) return;

  final adjust = await showDialog<bool>(
    context: context,
    builder: (dialogContext) => AlertDialog(
      title: const Text('Zmieniono dostępny sprzęt'),
      content: const Text(
        'Czy chcesz dostosować pozostałe dni programu? Ukończone dni i '
        'dotychczasowy postęp zostaną zachowane.',
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(dialogContext, false),
          child: const Text('Zostaw bez zmian'),
        ),
        FilledButton(
          onPressed: () => Navigator.pop(dialogContext, true),
          child: const Text('Dostosuj pozostałe dni'),
        ),
      ],
    ),
  );
  if (adjust != true) return;

  var changed = 0;
  for (final plan in needing) {
    // fromDayIndex = currentDayIndex → dni ukończone (i wcześniejsze) zostają
    // bajt w bajt; podmieniane są tylko dni jeszcze do zrobienia.
    final filtered = applyEquipmentToPlan(
      plan,
      profile,
      limits,
      resolver,
      fromDayIndex: plan.currentDayIndex,
    );
    await store.updateWorkoutPlan(filtered.plan);
    changed++;
  }
  if (!context.mounted) return;
  showError(
    context,
    'Dostosowano pozostałe dni w $changed '
    '${changed == 1 ? 'programie' : 'programach'} — postęp zachowany.',
  );
}

/// Reset programu — zeruje ukończone dni (start od nowa), zachowując treść.
Future<void> resetCatalogProgram(BuildContext context, WorkoutPlan plan) async {
  final store = AppScope.read(context);
  await store
      .updateWorkoutPlan(plan.copyWith(completedDays: <int>{}, isActive: true));
}

