class _CatalogProgramCard extends StatelessWidget {
  const _CatalogProgramCard({required this.meta, this.plan});

  final WorkoutProgramMeta meta;
  final WorkoutPlan? plan;

  Future<void> _open(BuildContext context) async {
    final started = await startCatalogProgram(context, meta.id);
    if (!context.mounted) return;
    await openWorkoutProgram(context, started.id);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final accent = Color(meta.accentColor);
    final started = plan != null;
    final completed = plan?.completedCount ?? 0;
    final progress = plan == null || plan!.days.isEmpty
        ? 0.0
        : completed / plan!.days.length;
    final isDone = plan?.isProgramCompleted ?? false;
    // Dopasowanie programu do profilu treningowego użytkownika (pkt 7 spec).
    final recommendation =
        recommendProgram(meta, programUserProfileFor(AppScope.of(context)));

    // Okładka programu (AI/galeria/aparat) jako tło nagłówka kafelka —
    // ta sama, którą widać wewnątrz programu; brak okładki = gradient.
    final coverPath = plan?.media?.effectivePath ?? '';
    final headerContent = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(meta.title,
            style: theme.textTheme.titleLarge
                ?.copyWith(color: Colors.white, fontWeight: FontWeight.w900)),
        const SizedBox(height: 2),
        Text(meta.subtitle,
            style: theme.textTheme.bodyMedium
                ?.copyWith(color: Colors.white.withValues(alpha: 0.9))),
        const SizedBox(height: 12),
        Wrap(
          spacing: 8,
          runSpacing: 6,
          children: [
            if (recommendation.isRecommended)
              _catalogChip('Dla Twojego profilu', Colors.white),
            _catalogChip('30 dni', Colors.white),
            if (started)
              _catalogChip('$completed/${plan!.days.length}', Colors.white),
            if (plan?.level.isNotEmpty ?? false)
              _catalogChip(plan!.level, Colors.white),
            for (final reason in recommendation.reasons.skip(1).take(2))
              _catalogChip(reason, Colors.white),
          ],
        ),
      ],
    );

    return Card(
      clipBehavior: Clip.antiAlias,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (coverPath.isNotEmpty)
            Stack(
              children: [
                Positioned.fill(
                  child: buildExerciseMediaImage(
                    coverPath,
                    fit: BoxFit.cover,
                    fallback: DecoratedBox(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [
                            accent.withValues(alpha: 0.9),
                            accent.withValues(alpha: 0.45)
                          ],
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                        ),
                      ),
                    ),
                  ),
                ),
                // Scrim dla czytelności białych napisów na zdjęciu.
                Positioned.fill(
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topCenter,
                        end: Alignment.bottomCenter,
                        colors: [
                          Colors.black.withValues(alpha: 0.30),
                          Colors.black.withValues(alpha: 0.58),
                        ],
                      ),
                    ),
                  ),
                ),
                Padding(
                    padding: const EdgeInsets.all(16), child: headerContent),
              ],
            )
          else
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: [
                    accent.withValues(alpha: 0.9),
                    accent.withValues(alpha: 0.45)
                  ],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: headerContent,
            ),
          Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (started) ...[
                  ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: LinearProgressIndicator(
                        value: progress, minHeight: 8, color: accent),
                  ),
                  const SizedBox(height: 12),
                ],
                Wrap(
                  spacing: 6,
                  runSpacing: 6,
                  children: [
                    for (final m in meta.mainMuscles)
                      _MetaPill(icon: Icons.fitness_center_rounded, text: m),
                  ],
                ),
                const SizedBox(height: 6),
                Text('Sprzęt: ${meta.equipment.join(' · ')}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
                const SizedBox(height: 14),
                Row(
                  children: [
                    Expanded(
                      child: FilledButton.icon(
                        onPressed: () => _open(context),
                        icon: Icon(isDone
                            ? Icons.replay_rounded
                            : started
                                ? Icons.play_arrow_rounded
                                : Icons.rocket_launch_rounded),
                        label: Text(isDone
                            ? 'Ukończony — otwórz'
                            : started
                                ? 'Kontynuuj'
                                : 'Start'),
                      ),
                    ),
                    if (started) ...[
                      const SizedBox(width: 8),
                      IconButton.filledTonal(
                        tooltip: 'Reset programu',
                        onPressed: () async {
                          final ok = await showDialog<bool>(
                            context: context,
                            builder: (dc) => AlertDialog(
                              title: const Text('Zresetować program?'),
                              content: const Text(
                                  'Wyzeruje to postęp (ukończone dni). Treść programu zostaje.'),
                              actions: [
                                TextButton(
                                    onPressed: () => Navigator.pop(dc, false),
                                    child: const Text('Anuluj')),
                                FilledButton(
                                    onPressed: () => Navigator.pop(dc, true),
                                    child: const Text('Resetuj')),
                              ],
                            ),
                          );
                          if (ok == true && context.mounted) {
                            await resetCatalogProgram(context, plan!);
                          }
                        },
                        icon: const Icon(Icons.restart_alt_rounded),
                      ),
                    ],
                  ],
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _catalogChip(String label, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.22),
        borderRadius: BorderRadius.circular(20),
      ),
      child: Text(label,
          style: TextStyle(
              color: color, fontWeight: FontWeight.w800, fontSize: 12)),
    );
  }
}

class PlanDayEstimate {
  const PlanDayEstimate({
    required this.exerciseCount,
    required this.minutes,
    required this.kcal,
  });

  final int exerciseCount;
  final int minutes;
  final int kcal;
}

/// Liczy szacunkowy czas i kalorie dnia na podstawie pozycji planu.
PlanDayEstimate estimatePlanDay(
  WorkoutDay day,
  List<Exercise> customExercises,
  double bodyWeightKg,
) {
  var totalMinutes = 0.0;
  var totalKcal = 0.0;
  for (final item in day.items) {
    final exercise = item.exerciseFrom(customExercises);
    final workSeconds = item.durationSec > 0
        ? item.sets * item.durationSec
        : item.sets * item.reps * 3;
    final restSeconds = item.sets * item.restSeconds;
    final minutes = math.max(1.0, (workSeconds + restSeconds) / 60);
    totalMinutes += minutes;
    totalKcal += estimateCalories(
      met: exercise.met,
      weightKg: bodyWeightKg,
      minutes: minutes,
    );
  }
  return PlanDayEstimate(
    exerciseCount: day.items.length,
    minutes: totalMinutes.round(),
    kcal: totalKcal.round(),
  );
}

