class WorkoutProgramPage extends StatefulWidget {
  const WorkoutProgramPage({super.key, required this.planId});

  final String planId;

  @override
  State<WorkoutProgramPage> createState() => _WorkoutProgramPageState();
}

class _WorkoutProgramPageState extends State<WorkoutProgramPage> {
  bool _showCompleted = false;

  WorkoutPlan? _findPlan(AppStore store) {
    for (final plan in store.plans) {
      if (plan.id == widget.planId) return plan;
    }
    return null;
  }

  Future<void> _changeLevel(AppStore store, WorkoutPlan plan) async {
    final selected = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 4, 16, 8),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text('Poziom programu',
                    style:
                        TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
              ),
            ),
            for (final level in kTrainingLevels)
              ListTile(
                leading: Icon(
                  (plan.level.isNotEmpty && normalizeLevel(plan.level) == level)
                      ? Icons.radio_button_checked_rounded
                      : Icons.radio_button_unchecked_rounded,
                ),
                title: Text(level),
                onTap: () => Navigator.of(sheetContext).pop(level),
              ),
          ],
        ),
      ),
    );
    if (selected != null) await store.setPlanLevel(plan.id, selected);
  }

  Future<void> _confirmReset(AppStore store, WorkoutPlan plan) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Zresetować postęp?'),
        content: const Text(
            'Wszystkie dni zostaną oznaczone jako niewykonane. Tej operacji nie można cofnąć.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('Zresetuj')),
        ],
      ),
    );
    if (confirmed == true) await store.resetPlanProgress(plan.id);
  }

  void _warnLocked() {
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
          content: Text(
              'Ten dzień odblokuje się po ukończeniu poprzedniego treningu.')),
    );
  }

  /// Wybór wariantu programu: wspólny szablon + różnice (bez kopii logiki).
  /// Zmiana obowiązuje OD KOLEJNEGO dnia; ukończone dni zostają nietknięte.
  Future<void> _showVariantSheet(AppStore store, WorkoutPlan plan) async {
    String baseProgramId = plan.id;
    for (final meta in kWorkoutProgramCatalog) {
      if (plan.id.startsWith(meta.id)) {
        baseProgramId = meta.id;
        break;
      }
    }
    final variants = defaultVariantsForProgram(baseProgramId);
    final selected = await showModalBottomSheet<ProgramVariant>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (sheetContext) {
        final theme = Theme.of(sheetContext);
        return Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text('Wariant programu',
                  style: theme.textTheme.titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 4),
              Text(
                'Nowe ustawienia obowiązują od kolejnego dnia (dzień ${plan.currentDayIndex + 1}). '
                'Ukończone dni i historia serii pozostają bez zmian.',
                style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant, height: 1.3),
              ),
              const SizedBox(height: 10),
              Flexible(
                child: ListView(
                  shrinkWrap: true,
                  children: [
                    for (final variant in variants)
                      Card(
                        margin: const EdgeInsets.only(bottom: 8),
                        color: variant.id == plan.activeVariantId
                            ? theme.colorScheme.primaryContainer
                                .withValues(alpha: 0.45)
                            : null,
                        child: ListTile(
                          key: Key('program_variant_${variant.id}'),
                          title: Text(variant.name,
                              style: theme.textTheme.titleSmall
                                  ?.copyWith(fontWeight: FontWeight.w800)),
                          subtitle: Text(
                            [
                              variant.description,
                              if (variant.differenceSummary.isNotEmpty)
                                variant.differenceSummary.join(' · '),
                            ].where((t) => t.isNotEmpty).join('\n'),
                          ),
                          trailing: variant.id == plan.activeVariantId
                              ? Icon(Icons.check_circle_rounded,
                                  color: theme.colorScheme.primary)
                              : null,
                          onTap: () => Navigator.pop(sheetContext, variant),
                        ),
                      ),
                    Card(
                      margin: const EdgeInsets.only(bottom: 8),
                      child: ListTile(
                        key: const Key('program_variant_ai'),
                        leading: const Icon(Icons.auto_awesome_rounded),
                        title: const Text('Wygeneruj wariant przez AI',
                            style: TextStyle(fontWeight: FontWeight.w800)),
                        subtitle: const Text(
                            'Na bazie profilu celu (sylwetka, strategia, priorytety). Wymaga zatwierdzenia.'),
                        onTap: () => Navigator.pop(
                          sheetContext,
                          const ProgramVariant(
                            id: '__generate_ai__',
                            programId: '',
                            name: 'AI',
                            difficulty: ProgramDifficulty.intermediate,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ],
          ),
        );
      },
    );
    if (selected == null || !mounted) return;
    var variant = selected;
    if (variant.id == '__generate_ai__') {
      try {
        showDialog<void>(
          context: context,
          barrierDismissible: false,
          builder: (_) => const Center(child: CircularProgressIndicator()),
        );
        variant = await store.generateProgramVariantWithAi(plan.id);
      } catch (error) {
        if (mounted) {
          Navigator.of(context, rootNavigator: true).pop();
          showError(context, '$error');
        }
        return;
      }
      if (!mounted) return;
      Navigator.of(context, rootNavigator: true).pop();
    }
    await _confirmVariant(store, plan, variant);
  }

  /// Podgląd wariantu przed zastosowaniem: różnice, liczba dni treningowych,
  /// przewidywana objętość. Zapis dopiero po zatwierdzeniu.
  Future<void> _confirmVariant(
      AppStore store, WorkoutPlan plan, ProgramVariant variant) async {
    final fromDay = plan.currentDayIndex.clamp(0, plan.days.length);
    final preview = applyProgramVariant(plan, variant, fromDayIndex: fromDay);
    var trainingDays = 0;
    var totalSets = 0;
    for (var i = fromDay; i < preview.days.length; i++) {
      final day = preview.days[i];
      if (day.items.isEmpty || preview.isRestDay(day)) continue;
      trainingDays += 1;
      for (final item in day.items) {
        totalSets += item.sets;
      }
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('Zastosować wariant „${variant.name}"?'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('Od dnia ${fromDay + 1} (ukończone dni bez zmian).'),
              const SizedBox(height: 8),
              Text('Dni treningowe do końca programu: $trainingDays'),
              Text('Przewidywana objętość: ~$totalSets serii'),
              if (variant.differenceSummary.isNotEmpty) ...[
                const SizedBox(height: 8),
                const Text('Różnice względem szablonu:',
                    style: TextStyle(fontWeight: FontWeight.w800)),
                for (final diff in variant.differenceSummary) Text('• $diff'),
              ],
            ],
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
            key: const Key('confirm_program_variant'),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Zastosuj'),
          ),
        ],
      ),
    );
    if (confirmed == true) {
      await store.applyVariantToPlan(plan.id, variant);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
              content: Text(
                  'Wariant „${variant.name}" aktywny od dnia ${fromDay + 1}.')),
        );
      }
    }
  }

  /// Okładka programu: generowanie AI / galeria / aparat / usunięcie.
  /// Nowa okładka czeka na zatwierdzenie — stara zostaje do tego czasu.
  Future<void> _showCoverSheet(AppStore store, WorkoutPlan plan) async {
    final action = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              key: const Key('program_cover_generate'),
              leading: const Icon(Icons.auto_awesome_rounded),
              title: const Text('Wygeneruj okładkę (AI)'),
              subtitle: const Text(
                  'Styl Premium Trainer: grafit + miętowe akcenty, bez tekstu'),
              onTap: () => Navigator.pop(sheetContext, 'generate'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_library_outlined),
              title: const Text('Wybierz z galerii'),
              onTap: () => Navigator.pop(sheetContext, 'gallery'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_camera_outlined),
              title: const Text('Zrób zdjęcie'),
              onTap: () => Navigator.pop(sheetContext, 'camera'),
            ),
            if (plan.media?.hasCover ?? false)
              ListTile(
                leading: Icon(Icons.delete_outline_rounded,
                    color: Theme.of(sheetContext).colorScheme.error),
                title: const Text('Usuń okładkę'),
                onTap: () => Navigator.pop(sheetContext, 'remove'),
              ),
          ],
        ),
      ),
    );
    if (action == null || !mounted) return;
    try {
      switch (action) {
        case 'generate':
          showDialog<void>(
            context: context,
            barrierDismissible: false,
            builder: (_) => const Center(child: CircularProgressIndicator()),
          );
          try {
            await store.generateProgramCoverWithAi(plan.id);
          } finally {
            if (mounted) Navigator.of(context, rootNavigator: true).pop();
          }
          break;
        case 'gallery':
        case 'camera':
          final picked = await ImagePicker().pickImage(
            source:
                action == 'camera' ? ImageSource.camera : ImageSource.gallery,
            maxWidth: 1600,
            imageQuality: 88,
          );
          if (picked == null) return;
          final media = (plan.media ?? const ProgramMedia()).copyWith(
            pendingLocalPath: picked.path,
            isAiGenerated: false,
          );
          await store.setPlanMedia(plan.id, media);
          break;
        case 'remove':
          await store.setPlanMedia(plan.id, null);
          return;
      }
    } catch (error) {
      if (mounted) showError(context, 'Okładka: $error');
      return;
    }
    if (!mounted) return;
    // Zatwierdzenie nowej okładki (stara żyje do tej decyzji).
    final updated = _findPlan(AppScope.read(context));
    final pendingPath = updated?.media?.pendingLocalPath ?? '';
    if (pendingPath.isEmpty) return;
    final approve = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Nowa okładka programu'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ClipRRect(
              borderRadius: BorderRadius.circular(14),
              child: Image.file(
                File(pendingPath),
                height: 220,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) => const Padding(
                  padding: EdgeInsets.all(24),
                  child: Icon(Icons.broken_image_outlined),
                ),
              ),
            ),
            const SizedBox(height: 8),
            const Text(
                'Ustawić jako okładkę programu? Poprzednia okładka zostanie zastąpiona dopiero po zatwierdzeniu.'),
          ],
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Odrzuć')),
          FilledButton(
            key: const Key('approve_program_cover'),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Ustaw okładkę'),
          ),
        ],
      ),
    );
    if (approve == true) {
      await store.approvePlanCover(plan.id);
    } else {
      await store.rejectPlanCover(plan.id);
    }
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final plan = _findPlan(store);
    final theme = Theme.of(context);

    if (plan == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Program treningowy')),
        body: const _ProgramEmptyState(),
      );
    }

    final days = plan.days;
    final completedIndexes = [
      for (var i = 0; i < days.length; i++)
        if (plan.isDayCompleted(i)) i,
    ];
    final hasHiddenCompleted = !_showCompleted && completedIndexes.isNotEmpty;

    return Scaffold(
      body: ListView(
        padding: EdgeInsets.zero,
        children: [
          _ProgramHeader(
            plan: plan,
            onBack: () => Navigator.of(context).maybePop(),
            menu: _buildMenu(store, plan),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 0),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                if (plan.note.trim().isNotEmpty) ...[
                  Text(
                    plan.note,
                    style: theme.textTheme.bodyMedium?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant, height: 1.4),
                  ),
                  const SizedBox(height: 16),
                ],
                _ProgramTodayCard(plan: plan, onWarnLocked: _warnLocked),
                const SizedBox(height: 12),
                ProgramIntensityControl(plan: plan),
                if (isCatalogProgramPlan(plan)) ...[
                  const SizedBox(height: 12),
                  _ProgramEquipmentCard(
                    report: summarizeSavedPlanEquipment(store, plan),
                  ),
                ],
                const SizedBox(height: 18),
                if (days.isEmpty)
                  EmptyCard(
                    icon: Icons.event_note_rounded,
                    title: 'Brak dni w programie',
                    text: 'Dodaj dni i ćwiczenia w edytorze planu.',
                    buttonLabel: 'Edytuj program',
                    onPressed: () => showWorkoutPlanEditor(context, plan: plan),
                  )
                else ...[
                  Row(
                    children: [
                      Text('Dni programu',
                          style: theme.textTheme.titleMedium
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const Spacer(),
                      Text('${plan.completedCount}/${days.length}',
                          style: theme.textTheme.labelLarge?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant,
                              fontWeight: FontWeight.w800)),
                    ],
                  ),
                  const SizedBox(height: 10),
                  if (hasHiddenCompleted)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: TextButton.icon(
                        onPressed: () => setState(() => _showCompleted = true),
                        icon: const Icon(Icons.check_circle_outline_rounded,
                            size: 18),
                        label: Text(
                            'Pokaż ukończone dni (${completedIndexes.length})'),
                      ),
                    ),
                  for (var i = 0; i < days.length; i++)
                    if (_showCompleted || !plan.isDayCompleted(i))
                      _ProgramDayCard(
                        plan: plan,
                        index: i,
                        onWarnLocked: _warnLocked,
                      ),
                ],
                const SizedBox(height: 24),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildMenu(AppStore store, WorkoutPlan plan) {
    return PopupMenuButton<String>(
      icon: const Icon(Icons.more_vert_rounded, color: Colors.white),
      tooltip: 'Opcje programu',
      onSelected: (value) async {
        switch (value) {
          case 'edit':
            await showWorkoutPlanEditor(context, plan: plan);
            break;
          case 'reset':
            await _confirmReset(store, plan);
            break;
          case 'level':
            await _changeLevel(store, plan);
            break;
          case 'variant':
            await _showVariantSheet(store, plan);
            break;
          case 'cover':
            await _showCoverSheet(store, plan);
            break;
          case 'showAll':
            setState(() => _showCompleted = !_showCompleted);
            break;
          case 'anyDay':
            await store.setPlanAllowAnyDay(plan.id, !plan.allowAnyDay);
            break;
        }
      },
      itemBuilder: (context) => [
        const PopupMenuItem(
          value: 'edit',
          child: ListTile(
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.edit_outlined),
              title: Text('Edytuj program')),
        ),
        const PopupMenuItem(
          value: 'level',
          child: ListTile(
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.signal_cellular_alt_rounded),
              title: Text('Zmień poziom')),
        ),
        const PopupMenuItem(
          value: 'variant',
          child: ListTile(
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.tune_rounded),
              title: Text('Wariant programu')),
        ),
        const PopupMenuItem(
          value: 'cover',
          child: ListTile(
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.image_outlined),
              title: Text('Okładka programu')),
        ),
        const PopupMenuItem(
          value: 'reset',
          child: ListTile(
              contentPadding: EdgeInsets.zero,
              leading: Icon(Icons.restart_alt_rounded),
              title: Text('Zresetuj postęp')),
        ),
        CheckedPopupMenuItem(
          value: 'showAll',
          checked: _showCompleted,
          child: const Text('Pokaż wszystkie dni'),
        ),
        CheckedPopupMenuItem(
          value: 'anyDay',
          checked: plan.allowAnyDay,
          child: const Text('Trenuj dowolny dzień'),
        ),
      ],
    );
  }
}

