/// Duży nagłówek programu: obraz/gradient w tle, nazwa, poziom, postęp.
class _ProgramHeader extends StatelessWidget {
  const _ProgramHeader(
      {required this.plan, required this.onBack, required this.menu});

  final WorkoutPlan plan;
  final VoidCallback onBack;
  final Widget menu;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final level = plan.level.trim();
    return SizedBox(
      height: 292,
      child: Stack(
        fit: StackFit.expand,
        children: [
          // Tło: okładka programu (media) → obraz nagłówka → gradient marki.
          if ((plan.media?.effectivePath ?? '').isNotEmpty)
            buildExerciseMediaImage(
              plan.media!.effectivePath!,
              fit: BoxFit.cover,
              fallback: _gradient(scheme),
            )
          else if (plan.imageAsset != null &&
              plan.imageAsset!.trim().isNotEmpty)
            buildExerciseMediaImage(
              plan.imageAsset!,
              fit: BoxFit.cover,
              fallback: _gradient(scheme),
            )
          else
            _gradient(scheme),
          // Scrim dla czytelności tekstu.
          DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [
                  Colors.black.withValues(alpha: 0.15),
                  Colors.black.withValues(alpha: 0.72),
                ],
              ),
            ),
          ),
          // Pasek nawigacji i treść w JEDNEJ kolumnie — napisy nagłówka nie
          // mogą już nachodzić na strzałkę cofania (wcześniej treść była
          // pozycjonowana niezależnie i przy dłuższych nazwach wjeżdżała
          // pod pasek z przyciskami).
          SafeArea(
            bottom: false,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 4),
                  child: Row(
                    children: [
                      IconButton(
                        onPressed: onBack,
                        icon: const Icon(Icons.arrow_back_rounded,
                            color: Colors.white),
                        tooltip: 'Wstecz',
                      ),
                      const Spacer(),
                      menu,
                    ],
                  ),
                ),
                const Spacer(),
                Padding(
                  padding: const EdgeInsets.fromLTRB(18, 0, 18, 18),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      FittedBox(
                        fit: BoxFit.scaleDown,
                        alignment: Alignment.centerLeft,
                        child: ConstrainedBox(
                          constraints: const BoxConstraints(maxWidth: 480),
                          child: Text(
                            plan.name,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                            style: theme.textTheme.headlineSmall?.copyWith(
                                color: Colors.white,
                                fontWeight: FontWeight.w900,
                                height: 1.05),
                          ),
                        ),
                      ),
                      const SizedBox(height: 8),
                      Wrap(
                        spacing: 8,
                        runSpacing: 8,
                        children: [
                          _HeaderChip(
                              icon: Icons.flag_rounded, label: plan.goal),
                          if (level.isNotEmpty)
                            _HeaderChip(
                                icon: Icons.signal_cellular_alt_rounded,
                                label: level),
                          _HeaderChip(
                              icon: Icons.calendar_month_rounded,
                              label: '${plan.days.length} dni'),
                          if (plan.allowAnyDay)
                            const _HeaderChip(
                                icon: Icons.lock_open_rounded,
                                label: 'Dowolny dzień'),
                        ],
                      ),
                      const SizedBox(height: 14),
                      Row(
                        children: [
                          Text(
                            '${plan.completedCount} / ${plan.days.length}',
                            style: theme.textTheme.titleMedium?.copyWith(
                                color: Colors.white,
                                fontWeight: FontWeight.w900),
                          ),
                          const SizedBox(width: 6),
                          const Text('dni ukończono',
                              style: TextStyle(
                                  color: Colors.white70,
                                  fontWeight: FontWeight.w600)),
                        ],
                      ),
                      const SizedBox(height: 8),
                      ClipRRect(
                        borderRadius: BorderRadius.circular(8),
                        child: LinearProgressIndicator(
                          value: plan.progress,
                          minHeight: 8,
                          backgroundColor: Colors.white24,
                          valueColor:
                              AlwaysStoppedAnimation<Color>(scheme.primary),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _gradient(ColorScheme scheme) => DecoratedBox(
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              scheme.primary,
              scheme.primaryContainer,
              scheme.surfaceContainerHighest
            ],
          ),
        ),
      );
}

