/// Sekcja „Dzisiaj": co jest zaplanowane, ile potrwa, trening czy odpoczynek.
class _ProgramTodayCard extends StatelessWidget {
  const _ProgramTodayCard({required this.plan, required this.onWarnLocked});

  final WorkoutPlan plan;
  final VoidCallback onWarnLocked;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);

    if (plan.isProgramCompleted) {
      return Card(
        color: theme.colorScheme.primaryContainer.withValues(alpha: 0.5),
        child: Padding(
          padding: const EdgeInsets.all(18),
          child: Row(
            children: [
              Icon(Icons.emoji_events_rounded,
                  color: theme.colorScheme.primary, size: 32),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Program ukończony!',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 2),
                    Text('Świetna robota. Zresetuj postęp, aby zacząć od nowa.',
                        style: theme.textTheme.bodySmall?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant)),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
    }

    if (plan.days.isEmpty) return const SizedBox.shrink();

    final index = plan.currentDayIndex.clamp(0, plan.days.length - 1);
    final day = plan.days[index];
    final isRest = plan.isRestDay(day);
    final estimate = estimatePlanDay(
        day, store.customExercises, store.settings.bodyWeightKg);

    return Card(
      color: theme.colorScheme.primaryContainer.withValues(alpha: 0.5),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                  decoration: BoxDecoration(
                      color: theme.colorScheme.primary,
                      borderRadius: BorderRadius.circular(10)),
                  child: Text('DZISIAJ',
                      style: TextStyle(
                          color: theme.colorScheme.onPrimary,
                          fontWeight: FontWeight.w900,
                          fontSize: 11,
                          letterSpacing: 0.5)),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    'Dzień ${index + 1}',
                    style: theme.textTheme.labelLarge?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant,
                        fontWeight: FontWeight.w800),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            Row(
              children: [
                Icon(
                    isRest
                        ? Icons.self_improvement_rounded
                        : Icons.fitness_center_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(
                    isRest ? 'Dzień odpoczynku' : day.title,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.titleLarge
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            if (isRest)
              Text(
                  'Odpocznij i zregeneruj się. Możesz zaliczyć ten dzień, aby przejść dalej.',
                  style: theme.textTheme.bodyMedium
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant))
            else
              Wrap(
                spacing: 14,
                runSpacing: 6,
                children: [
                  _MetaPill(
                      icon: Icons.timer_outlined,
                      text: '~${estimate.minutes} min'),
                  _MetaPill(
                      icon: Icons.format_list_numbered_rounded,
                      text: '${estimate.exerciseCount} ćw.'),
                  _MetaPill(
                      icon: Icons.local_fire_department_outlined,
                      text: '${estimate.kcal} kcal'),
                ],
              ),
            const SizedBox(height: 14),
            if (isRest)
              FilledButton.tonalIcon(
                onPressed: () => store.setPlanDayCompleted(plan.id, index),
                icon: const Icon(Icons.check_rounded),
                label: const Text('Zalicz dzień odpoczynku'),
              )
            else
              FilledButton.icon(
                onPressed: () => openWorkoutDayDetails(context, plan.id, index),
                icon: const Icon(Icons.play_arrow_rounded),
                label: const Text('START'),
              ),
          ],
        ),
      ),
    );
  }
}

class _MetaPill extends StatelessWidget {
  const _MetaPill({required this.icon, required this.text});

  final IconData icon;
  final String text;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(icon, size: 16, color: theme.colorScheme.onSurfaceVariant),
        const SizedBox(width: 4),
        Text(text,
            style: theme.textTheme.bodyMedium
                ?.copyWith(fontWeight: FontWeight.w700)),
      ],
    );
  }
}

/// Karta pojedynczego dnia programu z numerem, czasem, liczbą ćwiczeń, kcal i statusem.
class _ProgramDayCard extends StatelessWidget {
  const _ProgramDayCard(
      {required this.plan, required this.index, required this.onWarnLocked});

  final WorkoutPlan plan;
  final int index;
  final VoidCallback onWarnLocked;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final store = AppScope.of(context);
    final day = plan.days[index];
    final status = plan.statusForDay(index);
    final isLocked = status == WorkoutDayStatus.locked;
    final isCompleted = status == WorkoutDayStatus.completed;
    final isRest =
        status == WorkoutDayStatus.rest || (isCompleted && plan.isRestDay(day));
    final isActive = status == WorkoutDayStatus.active;
    final estimate = estimatePlanDay(
        day, store.customExercises, store.settings.bodyWeightKg);

    final Color borderColor = isActive
        ? scheme.primary
        : scheme.outlineVariant.withValues(alpha: 0.45);
    final Color bgColor = isActive
        ? scheme.primaryContainer.withValues(alpha: 0.35)
        : scheme.surfaceContainerHighest
            .withValues(alpha: isLocked ? 0.3 : 0.5);

    final card = Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: bgColor,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(color: borderColor, width: isActive ? 1.6 : 1),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _DayBadge(index: index, status: status),
              const SizedBox(width: 12),
              Expanded(
                child: Opacity(
                  opacity: isLocked ? 0.65 : 1,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        isRest ? 'Dzień odpoczynku' : day.title,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900),
                      ),
                      const SizedBox(height: 6),
                      if (isRest)
                        Text('Regeneracja',
                            style: theme.textTheme.bodySmall
                                ?.copyWith(color: scheme.onSurfaceVariant))
                      else
                        Wrap(
                          spacing: 12,
                          runSpacing: 4,
                          children: [
                            _MetaPill(
                                icon: Icons.timer_outlined,
                                text: '~${estimate.minutes} min'),
                            _MetaPill(
                                icon: Icons.format_list_numbered_rounded,
                                text: '${estimate.exerciseCount} ćw.'),
                            _MetaPill(
                                icon: Icons.local_fire_department_outlined,
                                text: '${estimate.kcal} kcal'),
                          ],
                        ),
                    ],
                  ),
                ),
              ),
              const SizedBox(width: 8),
              _StatusIcon(status: status),
            ],
          ),
          const SizedBox(height: 12),
          _buildAction(context, store, theme, status, day),
        ],
      ),
    );

    return InkWell(
      borderRadius: BorderRadius.circular(18),
      onTap: isLocked
          ? onWarnLocked
          : () => openWorkoutDayDetails(context, plan.id, index),
      child: card,
    );
  }

  Widget _buildAction(
    BuildContext context,
    AppStore store,
    ThemeData theme,
    WorkoutDayStatus status,
    WorkoutDay day,
  ) {
    switch (status) {
      case WorkoutDayStatus.locked:
        return Row(
          children: [
            Icon(Icons.lock_outline_rounded,
                size: 16, color: theme.colorScheme.onSurfaceVariant),
            const SizedBox(width: 6),
            Expanded(
              child: Text(
                'Zablokowane — ukończ poprzedni dzień',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
            ),
          ],
        );
      case WorkoutDayStatus.completed:
        return Row(
          children: [
            Expanded(
              child: OutlinedButton.icon(
                onPressed: () => openWorkoutDayDetails(context, plan.id, index),
                icon: const Icon(Icons.replay_rounded, size: 18),
                label: const Text('Powtórz'),
              ),
            ),
            const SizedBox(width: 8),
            TextButton(
              onPressed: () =>
                  store.setPlanDayCompleted(plan.id, index, completed: false),
              child: const Text('Cofnij'),
            ),
          ],
        );
      case WorkoutDayStatus.rest:
        return FilledButton.tonalIcon(
          onPressed: () => store.setPlanDayCompleted(plan.id, index),
          icon: const Icon(Icons.check_rounded),
          label: const Text('Zalicz dzień odpoczynku'),
        );
      case WorkoutDayStatus.active:
      case WorkoutDayStatus.available:
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            FilledButton.icon(
              onPressed: () => openWorkoutDayDetails(context, plan.id, index),
              icon: const Icon(Icons.play_arrow_rounded),
              label: Text(status == WorkoutDayStatus.active
                  ? 'START'
                  : 'Rozpocznij trening'),
            ),
            Align(
              alignment: Alignment.centerRight,
              child: TextButton.icon(
                onPressed: () => store.setPlanDayCompleted(plan.id, index),
                icon: const Icon(Icons.check_circle_outline_rounded, size: 18),
                label: const Text('Oznacz jako ukończony'),
              ),
            ),
          ],
        );
    }
  }
}

class _DayBadge extends StatelessWidget {
  const _DayBadge({required this.index, required this.status});

  final int index;
  final WorkoutDayStatus status;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final isActive = status == WorkoutDayStatus.active;
    final isCompleted = status == WorkoutDayStatus.completed;
    final bg = isCompleted
        ? scheme.primary
        : isActive
            ? scheme.primary
            : scheme.surfaceContainerHighest;
    final fg =
        (isCompleted || isActive) ? scheme.onPrimary : scheme.onSurfaceVariant;
    return Container(
      width: 52,
      padding: const EdgeInsets.symmetric(vertical: 8),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(14),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('DZIEŃ',
              style: TextStyle(
                  color: fg,
                  fontSize: 9,
                  fontWeight: FontWeight.w800,
                  letterSpacing: 0.5)),
          const SizedBox(height: 2),
          Text('${index + 1}',
              style: TextStyle(
                  color: fg,
                  fontSize: 20,
                  fontWeight: FontWeight.w900,
                  height: 1)),
        ],
      ),
    );
  }
}

class _StatusIcon extends StatelessWidget {
  const _StatusIcon({required this.status});

  final WorkoutDayStatus status;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;
    switch (status) {
      case WorkoutDayStatus.completed:
        return Icon(Icons.check_circle_rounded, color: scheme.primary);
      case WorkoutDayStatus.locked:
        return Icon(Icons.lock_rounded, color: scheme.onSurfaceVariant);
      case WorkoutDayStatus.rest:
        return Icon(Icons.local_cafe_rounded, color: scheme.onSurfaceVariant);
      case WorkoutDayStatus.active:
        return Icon(Icons.play_circle_fill_rounded, color: scheme.primary);
      case WorkoutDayStatus.available:
        return Icon(Icons.radio_button_unchecked_rounded,
            color: scheme.onSurfaceVariant);
    }
  }
}

