/// Ikona typu ćwiczenia: czasowe / siłowe / powtórzeniowe.
IconData planItemTypeIcon(PlanItem item, Exercise exercise) {
  if (item.suggestedWeightKg > 0) return Icons.fitness_center_rounded;
  if (item.durationSec > 0 ||
      (exercise.defaultDurationSec > 0 && item.reps == 0)) {
    return Icons.timer_outlined;
  }
  return Icons.repeat_rounded;
}

/// Krótki opis parametrów pozycji planu (czas albo serie × powtórzenia [+ ciężar]).
String planItemMetaText(PlanItem item, Exercise exercise) {
  if (item.durationSec > 0) return '${item.sets} × ${item.durationSec}s';
  if (item.reps == 0 && exercise.defaultDurationSec > 0) {
    return '${item.sets} × ${exercise.defaultDurationSec}s';
  }
  final weight = item.suggestedWeightKg > 0
      ? ' · ${_formatPlanWeight(item.suggestedWeightKg)} kg'
      : '';
  return '${item.sets} × ${item.reps} powt.$weight';
}

/// Ostrzeżenia o równowadze dnia — po ręcznej edycji zestaw może stracić sens
/// (np. zostaną same akcesoria albo rozciąganie). Czysta funkcja: łatwa do
/// testów i niezależna od UI.
List<String> planDayBalanceWarnings(WorkoutDay day, List<Exercise> custom) {
  if (day.items.isEmpty) return const [];
  final exercises = [
    for (final item in day.items) ExerciseRepo.byId(item.exerciseId, custom),
  ];
  final working = exercises
      .where((e) => e.category != 'Rozciąganie' && e.category != 'Rozgrzewka')
      .toList();
  // „Seria główna" rozpoznajemy po notatce generatora. Plany własne mają puste
  // notatki — wtedy nie ma czego porównywać i tej reguły NIE stosujemy
  // (inaczej każdy ręcznie zbudowany dzień byłby fałszywie oznaczany).
  final hasNotes = day.items.any((item) => item.note.trim().isNotEmpty);
  final hasMain = day.items.any((item) => item.note.startsWith('Seria główna'));

  final warnings = <String>[];
  if (working.isEmpty) {
    warnings.add(
        'Zostały tylko rozgrzewka i rozciąganie — ten dzień nie ma już części głównej.');
  } else if (hasNotes && !hasMain) {
    warnings.add(
        'Dzień stracił serię główną (ćwiczenie prowadzące) — zostały same ćwiczenia pomocnicze.');
  }
  if (day.items.length > 14) {
    warnings.add(
        'Bardzo dużo pozycji (${day.items.length}) — trening mocno się wydłuży.');
  }
  return warnings;
}

class WorkoutDayDetailsPage extends StatefulWidget {
  const WorkoutDayDetailsPage(
      {super.key, required this.planId, required this.dayIndex});

  final String planId;
  final int dayIndex;

  @override
  State<WorkoutDayDetailsPage> createState() => _WorkoutDayDetailsPageState();
}

class _WorkoutDayDetailsPageState extends State<WorkoutDayDetailsPage> {
  bool _compact = false;
  bool _editing = false;

  WorkoutPlan? _findPlan(AppStore store) {
    for (final plan in store.plans) {
      if (plan.id == widget.planId) return plan;
    }
    return null;
  }

  Future<void> _swapItem(
      AppStore store, WorkoutPlan plan, WorkoutDay day, int itemIndex) async {
    final item = day.items[itemIndex];
    final picked = await pickExerciseFromLibrary(
      context,
      title: 'Zamień ćwiczenie',
      subtitle: 'Parametry serii/powtórzeń zostaną zachowane.',
      excludeIds: day.items.map((entry) => entry.exerciseId).toSet(),
    );
    if (picked == null) return;
    final items = [...day.items];
    items[itemIndex] = item.copyWith(exerciseId: picked.id);
    await store.updatePlanDayItems(plan.id, widget.dayIndex, items);
  }

  Future<void> _removeItem(
      AppStore store, WorkoutPlan plan, WorkoutDay day, int itemIndex) async {
    final items = [...day.items]..removeAt(itemIndex);
    await store.updatePlanDayItems(plan.id, widget.dayIndex, items);
  }

  /// Podmienia ćwiczenie na cięższy albo lżejszy wariant tego samego ruchu,
  /// zachowując parametry serii.
  Future<void> _swapByIntensity(
      AppStore store, WorkoutPlan plan, WorkoutDay day, int itemIndex,
      {required bool harder}) async {
    final item = day.items[itemIndex];
    final picked = await showIntensityVariantPicker(
      context,
      current: item.exerciseFrom(store.customExercises),
      harder: harder,
      excludeIds: day.items.map((entry) => entry.exerciseId).toSet(),
    );
    if (picked == null) return;
    final items = [...day.items];
    items[itemIndex] = item.copyWith(exerciseId: picked.id);
    await store.updatePlanDayItems(plan.id, widget.dayIndex, items);
  }

  Future<void> _reorderItems(AppStore store, WorkoutPlan plan, WorkoutDay day,
      int oldIndex, int newIndex) async {
    if (newIndex > oldIndex) newIndex -= 1;
    if (oldIndex == newIndex) return;
    final items = [...day.items];
    final moved = items.removeAt(oldIndex);
    items.insert(newIndex, moved);
    await store.updatePlanDayItems(plan.id, widget.dayIndex, items);
  }

  /// Ostrzega, że zestaw ułożył Trainer pod użytkownika, i włącza tryb edycji.
  Future<void> _enterEditMode() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        icon: const Icon(Icons.tune_rounded),
        title: const Text('Zmieniasz przemyślany zestaw'),
        content: const Text(
            'Ten zestaw ułożył Trainer pod Ciebie — pod cel, poziom i regenerację '
            'mięśni. Ręczne zmiany (usuwanie, dodawanie, kolejność) mogą naruszyć '
            'ten balans. Chcesz przejść do edycji?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Edytuj')),
        ],
      ),
    );
    if (ok == true && mounted) setState(() => _editing = true);
  }

  void _openTechnique(Exercise exercise) {
    Navigator.of(context).push(
      MaterialPageRoute<void>(
          builder: (_) => ExerciseDetailsPage(exerciseId: exercise.id)),
    );
  }

  Future<void> _openGuide(WorkoutPlan plan, WorkoutDay day) async {
    final store = AppScope.read(context);
    if (day.items.isEmpty) return;
    final exercise = await showModalBottomSheet<Exercise>(
      context: context,
      showDragHandle: true,
      isScrollControlled: true,
      useSafeArea: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 4, 16, 8),
              child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text('Technika ćwiczeń',
                      style: TextStyle(
                          fontWeight: FontWeight.w900, fontSize: 16))),
            ),
            Flexible(
              child: ListView(
                shrinkWrap: true,
                children: [
                  for (final item in day.items)
                    Builder(builder: (context) {
                      final exercise = item.exerciseFrom(store.customExercises);
                      return ListTile(
                        leading: SizedBox(
                            width: 44,
                            height: 44,
                            child: ExerciseVisual(exercise: exercise)),
                        title: Text(exercise.name,
                            maxLines: 1, overflow: TextOverflow.ellipsis),
                        trailing: const Icon(Icons.chevron_right_rounded),
                        onTap: () => Navigator.pop(sheetContext, exercise),
                      );
                    }),
                ],
              ),
            ),
          ],
        ),
      ),
    );
    if (exercise != null && mounted) _openTechnique(exercise);
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final plan = _findPlan(store);
    final theme = Theme.of(context);

    if (plan == null ||
        widget.dayIndex < 0 ||
        widget.dayIndex >= plan.days.length) {
      return Scaffold(
        appBar: AppBar(title: const Text('Szczegóły dnia')),
        body: const _ProgramEmptyState(),
      );
    }

    final rawDay = plan.days[widget.dayIndex];
    // Soczewka deloadu: gdy dziś jest deload i nie edytujemy, pokazujemy
    // (i startujemy) lżejszy wariant dnia. Edycja i akcje kafelków działają na
    // ORYGINALNYM dniu (rawDay) — deload nie może utrwalić się w planie.
    final deloadActive = store.deloadStatusToday.isDeload;
    // Widok/start: ręczna korekta intensywności + ewentualny deload.
    // Edycja pracuje na oryginale, żeby żadna soczewka się nie utrwaliła.
    final day = _editing ? rawDay : store.presentedDay(plan, rawDay);
    final status = plan.statusForDay(widget.dayIndex);
    final isRest = status == WorkoutDayStatus.rest ||
        (plan.isRestDay(day) && status != WorkoutDayStatus.completed);
    final isLocked = status == WorkoutDayStatus.locked;
    final estimate = estimatePlanDay(
        day, store.customExercises, store.settings.bodyWeightKg);

    final equipment = <EquipmentType>{};
    final muscles = <MuscleGroup>{};
    final dayExercises = <Exercise>[];
    for (final item in day.items) {
      final exercise = item.exerciseFrom(store.customExercises);
      dayExercises.add(exercise);
      equipment.addAll(exercise.equipmentTypes);
      muscles.addAll(exercise.muscleGroups);
    }
    final recoveryWarnings =
        recoveryWarningsForExercises(dayExercises, store.muscleRecoveryMap());
    // Równowaga zestawu po ręcznych zmianach (liczona z ORYGINALNEGO dnia).
    final balanceWarnings =
        planDayBalanceWarnings(rawDay, store.customExercises);

    return Scaffold(
      body: ListView(
        padding: EdgeInsets.zero,
        children: [
          _DayDetailsHeader(
            plan: plan,
            dayIndex: widget.dayIndex,
            estimate: estimate,
            status: status,
            isRest: isRest,
            onBack: () => Navigator.of(context).maybePop(),
            menu: _buildMenu(store, plan, day),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _DayGuideCard(
                  hasExercises: day.items.isNotEmpty,
                  onOpen: () => _openGuide(plan, day),
                ),
                const SizedBox(height: 16),
                if (isRest)
                  const _RestDayView()
                else if (day.items.isEmpty)
                  EmptyCard(
                    icon: Icons.fitness_center_rounded,
                    title: 'Brak ćwiczeń w tym dniu',
                    text: 'Dodaj ćwiczenia, aby rozpocząć trening.',
                    buttonLabel: 'Dodaj ćwiczenie',
                    onPressed: () =>
                        showPlanExercisePicker(context, plan: plan, day: day),
                  )
                else ...[
                  if (deloadActive && !_editing) ...[
                    Container(
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: kDeloadColor.withValues(alpha: 0.12),
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                            color: kDeloadColor.withValues(alpha: 0.5)),
                      ),
                      child: Row(
                        children: [
                          const Icon(Icons.self_improvement_rounded,
                              color: kDeloadColor),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Text(
                              'Tydzień deloadu — parametry są zmniejszone (mniej serii, '
                              'lżejszy ciężar, dłuższe przerwy). Potraktuj to jako lżejszy trening.',
                              style: theme.textTheme.bodySmall,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 14),
                  ],
                  // Rampa intensywności bloku: mocno zaraz po deloadzie, łagodniej
                  // ku końcowi (ale nie za mało) — wskazówka, jak dziś przycisnąć.
                  if (!deloadActive &&
                      !_editing &&
                      store.deloadCycle.isConfigured) ...[
                    Builder(builder: (context) {
                      final f = store.deloadStatusToday.intensityFactor;
                      final label = f >= 0.97
                          ? 'Świeżo po deloadzie — wchodź mocno (wysoka intensywność).'
                          : f >= 0.9
                              ? 'Środek bloku — trzymaj solidną intensywność.'
                              : 'Końcówka bloku — mocno, ale zostaw zapas do kolejnego deloadu.';
                      return Row(
                        children: [
                          Icon(Icons.trending_up_rounded,
                              size: 15, color: theme.colorScheme.primary),
                          const SizedBox(width: 6),
                          Expanded(
                            child: Text(label,
                                style: theme.textTheme.bodySmall?.copyWith(
                                    color: theme.colorScheme.onSurfaceVariant)),
                          ),
                        ],
                      );
                    }),
                    const SizedBox(height: 12),
                  ],
                  if (balanceWarnings.isNotEmpty) ...[
                    Container(
                      key: const Key('day_balance_warning'),
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: theme.colorScheme.errorContainer
                            .withValues(alpha: 0.35),
                        borderRadius: BorderRadius.circular(14),
                        border: Border.all(
                            color: theme.colorScheme.error
                                .withValues(alpha: 0.45)),
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Icon(Icons.rule_rounded,
                              color: theme.colorScheme.error, size: 20),
                          const SizedBox(width: 10),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text('Zestaw stracił równowagę',
                                    style: theme.textTheme.labelLarge?.copyWith(
                                        fontWeight: FontWeight.w900)),
                                const SizedBox(height: 2),
                                for (final warning in balanceWarnings)
                                  Text('• $warning',
                                      style: theme.textTheme.bodySmall),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 14),
                  ],
                  if (recoveryWarnings.isNotEmpty) ...[
                    RecoveryWarningBanner(warnings: recoveryWarnings),
                    const SizedBox(height: 14),
                  ],
                  if (equipment.isNotEmpty)
                    _TagSection(
                      icon: Icons.fitness_center_outlined,
                      title: 'Sprzęt potrzebny',
                      labels: equipment.map((type) => type.label).toList(),
                    ),
                  if (muscles.isNotEmpty) ...[
                    const SizedBox(height: 12),
                    _TagSection(
                      icon: Icons.accessibility_new_rounded,
                      title: 'Partie trenowane',
                      labels: muscles.map((group) => group.label).toList(),
                    ),
                  ],
                  const SizedBox(height: 18),
                  Row(
                    children: [
                      Expanded(
                        child: Text('${day.items.length} ćwiczeń',
                            style: theme.textTheme.titleMedium
                                ?.copyWith(fontWeight: FontWeight.w900)),
                      ),
                      if (_editing)
                        FilledButton.tonalIcon(
                          key: const Key('day_edit_done'),
                          onPressed: () => setState(() => _editing = false),
                          icon: const Icon(Icons.check_rounded, size: 18),
                          label: const Text('Gotowe'),
                        )
                      else
                        TextButton.icon(
                          key: const Key('day_edit_start'),
                          onPressed: _enterEditMode,
                          icon: const Icon(Icons.tune_rounded, size: 18),
                          label: const Text('Edytuj'),
                        ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  if (!_editing) ...[
                    _IntensityStepControl(
                        plan: plan, dayIndex: widget.dayIndex),
                    const SizedBox(height: 10),
                    Align(
                      alignment: Alignment.centerLeft,
                      child: SegmentedButton<bool>(
                        showSelectedIcon: false,
                        style: SegmentedButton.styleFrom(
                          visualDensity: VisualDensity.compact,
                          padding: const EdgeInsets.symmetric(
                              horizontal: 10, vertical: 6),
                          tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        ),
                        segments: const [
                          ButtonSegment(
                              value: false,
                              icon: Icon(Icons.view_list_rounded, size: 18),
                              label: Text('Lista')),
                          ButtonSegment(
                              value: true,
                              icon: Icon(Icons.view_agenda_outlined, size: 18),
                              label: Text('Kompakt')),
                        ],
                        selected: {_compact},
                        onSelectionChanged: (selection) =>
                            setState(() => _compact = selection.first),
                      ),
                    ),
                    const SizedBox(height: 12),
                    for (var i = 0; i < day.items.length; i++)
                      _DayExerciseTile(
                        exercise:
                            day.items[i].exerciseFrom(store.customExercises),
                        item: day.items[i],
                        position: i + 1,
                        compact: _compact,
                        onTechnique: () => _openTechnique(
                            day.items[i].exerciseFrom(store.customExercises)),
                        // Akcje utrwalają się w ORYGINALNYM dniu (nie w deloadowanym
                        // widoku) — indeksy się pokrywają, bo deload zachowuje układ.
                        onSwap: () => _swapItem(store, plan, rawDay, i),
                        onRemove: () => _removeItem(store, plan, rawDay, i),
                        onHarder: () => _swapByIntensity(store, plan, rawDay, i,
                            harder: true),
                        onEasier: () => _swapByIntensity(store, plan, rawDay, i,
                            harder: false),
                      ),
                  ] else ...[
                    Text(
                      'Przytrzymaj i przeciągnij kafelek, aby zmienić kolejność. '
                      'Minus usuwa ćwiczenie, plus poniżej dodaje nowe.',
                      style: theme.textTheme.bodySmall
                          ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                    ),
                    const SizedBox(height: 12),
                    ReorderableListView.builder(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      buildDefaultDragHandles: false,
                      itemCount: rawDay.items.length,
                      onReorder: (oldIndex, newIndex) => _reorderItems(
                          store, plan, rawDay, oldIndex, newIndex),
                      itemBuilder: (context, i) {
                        final it = rawDay.items[i];
                        return _EditableDayExerciseTile(
                          key: ValueKey('edit_${it.exerciseId}'),
                          index: i,
                          position: i + 1,
                          exercise: it.exerciseFrom(store.customExercises),
                          item: it,
                          onRemove: () => _removeItem(store, plan, rawDay, i),
                        );
                      },
                    ),
                    const SizedBox(height: 10),
                    Center(
                      child: _RoundAddExerciseButton(
                        onTap: () => showPlanExercisePicker(context,
                            plan: plan, day: rawDay),
                      ),
                    ),
                  ],
                ],
              ],
            ),
          ),
        ],
      ),
      bottomNavigationBar: _DayStartBar(
        plan: plan,
        dayIndex: widget.dayIndex,
        day: day,
        status: status,
        isRest: isRest,
        isLocked: isLocked,
      ),
    );
  }

  Widget _buildMenu(AppStore store, WorkoutPlan plan, WorkoutDay day) {
    return PopupMenuButton<String>(
      icon: const Icon(Icons.more_vert_rounded, color: Colors.white),
      tooltip: 'Opcje dnia',
      onSelected: (value) async {
        switch (value) {
          case 'add':
            await showPlanExercisePicker(context, plan: plan, day: day);
            break;
          case 'editPlan':
            await showWorkoutPlanEditor(context, plan: plan);
            break;
          case 'guide':
            await _openGuide(plan, day);
            break;
        }
      },
      itemBuilder: (context) => const [
        PopupMenuItem(
            value: 'add',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.playlist_add_rounded),
                title: Text('Dodaj ćwiczenie'))),
        PopupMenuItem(
            value: 'guide',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.menu_book_outlined),
                title: Text('Przewodnik / technika'))),
        PopupMenuItem(
            value: 'editPlan',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.edit_calendar_outlined),
                title: Text('Edytuj plan'))),
      ],
    );
  }
}

/// Nagłówek szczegółów dnia: obraz/gradient, powrót, menu, program + poziom,
/// „Dzień X", czas, kcal, liczba ćwiczeń, status.
class _DayDetailsHeader extends StatelessWidget {
  const _DayDetailsHeader({
    required this.plan,
    required this.dayIndex,
    required this.estimate,
    required this.status,
    required this.isRest,
    required this.onBack,
    required this.menu,
  });

  final WorkoutPlan plan;
  final int dayIndex;
  final PlanDayEstimate estimate;
  final WorkoutDayStatus status;
  final bool isRest;
  final VoidCallback onBack;
  final Widget menu;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final level = plan.level.trim();
    final day = plan.days[dayIndex];
    return SizedBox(
      height: 270,
      child: Stack(
        fit: StackFit.expand,
        children: [
          if (plan.imageAsset != null && plan.imageAsset!.trim().isNotEmpty)
            buildExerciseMediaImage(plan.imageAsset!,
                fit: BoxFit.cover, fallback: _gradient(scheme))
          else
            _gradient(scheme),
          DecoratedBox(
            decoration: BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                colors: [
                  Colors.black.withValues(alpha: 0.15),
                  Colors.black.withValues(alpha: 0.74)
                ],
              ),
            ),
          ),
          SafeArea(
            bottom: false,
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 4),
              child: Row(
                children: [
                  IconButton(
                      onPressed: onBack,
                      icon: const Icon(Icons.arrow_back_rounded,
                          color: Colors.white),
                      tooltip: 'Wstecz'),
                  const Spacer(),
                  menu,
                ],
              ),
            ),
          ),
          Positioned(
            left: 18,
            right: 18,
            bottom: 18,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  [plan.name, if (level.isNotEmpty) level].join(' · '),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                      color: Colors.white70, fontWeight: FontWeight.w700),
                ),
                const SizedBox(height: 4),
                Row(
                  crossAxisAlignment: CrossAxisAlignment.center,
                  children: [
                    Expanded(
                      child: Text(
                        'Dzień ${dayIndex + 1}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.headlineMedium?.copyWith(
                            color: Colors.white, fontWeight: FontWeight.w900),
                      ),
                    ),
                    _DayStatusBadge(status: status),
                  ],
                ),
                const SizedBox(height: 4),
                Text(
                  isRest ? 'Dzień odpoczynku' : day.title,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: theme.textTheme.titleMedium?.copyWith(
                      color: Colors.white, fontWeight: FontWeight.w700),
                ),
                const SizedBox(height: 12),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: isRest
                      ? const [
                          _HeaderChip(
                              icon: Icons.self_improvement_rounded,
                              label: 'Regeneracja')
                        ]
                      : [
                          _HeaderChip(
                              icon: Icons.timer_outlined,
                              label: '~${estimate.minutes} min'),
                          _HeaderChip(
                              icon: Icons.local_fire_department_outlined,
                              label: '${estimate.kcal} kcal'),
                          _HeaderChip(
                              icon: Icons.format_list_numbered_rounded,
                              label: '${estimate.exerciseCount} ćw.'),
                        ],
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  Widget _gradient(ColorScheme scheme) => DecoratedBox(
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
            colors: [
              scheme.primary,
              scheme.primaryContainer,
              scheme.surfaceContainerHighest
            ],
          ),
        ),
      );
}

class _DayStatusBadge extends StatelessWidget {
  const _DayStatusBadge({required this.status});

  final WorkoutDayStatus status;

  @override
  Widget build(BuildContext context) {
    late final IconData icon;
    late final String label;
    switch (status) {
      case WorkoutDayStatus.completed:
        icon = Icons.check_circle_rounded;
        label = 'Ukończony';
        break;
      case WorkoutDayStatus.locked:
        icon = Icons.lock_rounded;
        label = 'Zablokowany';
        break;
      case WorkoutDayStatus.rest:
        icon = Icons.local_cafe_rounded;
        label = 'Odpoczynek';
        break;
      case WorkoutDayStatus.active:
        icon = Icons.bolt_rounded;
        label = 'Dostępny';
        break;
      case WorkoutDayStatus.available:
        icon = Icons.check_circle_outline_rounded;
        label = 'Dostępny';
        break;
    }
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.2),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.white30),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 14, color: Colors.white),
          const SizedBox(width: 5),
          Text(label,
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 12,
                  fontWeight: FontWeight.w800)),
        ],
      ),
    );
  }
}

