            break;
          case 'swap':
            onSwap();
            break;
          case 'harder':
            onHarder();
            break;
          case 'easier':
            onEasier();
            break;
          case 'remove':
            onRemove();
            break;
        }
      },
      itemBuilder: (context) => const [
        PopupMenuItem(
            value: 'technique',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.menu_book_outlined),
                title: Text('Zobacz technikę'))),
        PopupMenuItem(
            value: 'harder',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.trending_up_rounded),
                title: Text('Cięższy wariant'))),
        PopupMenuItem(
            value: 'easier',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.trending_down_rounded),
                title: Text('Lżejszy wariant'))),
        PopupMenuItem(
            value: 'swap',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.swap_horiz_rounded),
                title: Text('Zamień ćwiczenie'))),
        PopupMenuItem(
            value: 'remove',
            child: ListTile(
                contentPadding: EdgeInsets.zero,
                leading: Icon(Icons.delete_outline_rounded),
                title: Text('Usuń z tego dnia'))),
      ],
    );

    if (compact) {
      return Container(
        margin: const EdgeInsets.only(bottom: 8),
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
        decoration: BoxDecoration(
          color: mobility
              ? accentColors.background
              : scheme.surfaceContainerHighest.withValues(alpha: 0.5),
          borderRadius: BorderRadius.circular(14),
          border: mobility ? Border.all(color: accentColors.border) : null,
        ),
        child: Row(
          children: [
            _ExerciseListThumb(exercise: exercise, size: 40),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Flexible(
                        child: Text('$position. ${exercise.name}',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: theme.textTheme.bodyMedium
                                ?.copyWith(fontWeight: FontWeight.w800)),
                      ),
                      if (mobility) ...[
                        const SizedBox(width: 4),
                        const MobilityBadge(size: 13),
                      ],
                    ],
                  ),
                  Row(
                    children: [
                      Icon(typeIcon, size: 13, color: scheme.onSurfaceVariant),
                      const SizedBox(width: 4),
                      Expanded(
                          child: Text(meta,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: theme.textTheme.bodySmall
                                  ?.copyWith(color: scheme.onSurfaceVariant))),
                    ],
                  ),
                ],
              ),
            ),
            menu,
          ],
        ),
      );
    }

    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: mobility
            ? accentColors.background
            : scheme.surfaceContainerHighest.withValues(alpha: 0.5),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: mobility
              ? accentColors.border
              : scheme.outlineVariant.withValues(alpha: 0.4),
        ),
      ),
      child: Row(
        children: [
          _ExerciseListThumb(exercise: exercise, size: 60),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    Flexible(
                      child: Text('$position. ${exercise.name}',
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.bodyLarge
                              ?.copyWith(fontWeight: FontWeight.w800)),
                    ),
                    if (mobility) ...[
                      const SizedBox(width: 6),
                      const MobilityBadge(size: 16),
                    ],
                  ],
                ),
                const SizedBox(height: 6),
                Row(
                  children: [
                    Icon(typeIcon, size: 15, color: scheme.primary),
                    const SizedBox(width: 4),
                    Expanded(
                      child: Text(
                        meta,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.bodySmall?.copyWith(
                            color: scheme.onSurfaceVariant,
                            fontWeight: FontWeight.w600),
                      ),
                    ),
                    if (exercise.hasMedia || exercise.hasVideo) ...[
                      const SizedBox(width: 8),
                      Icon(Icons.play_circle_outline_rounded,
                          size: 14, color: scheme.onSurfaceVariant),
                    ],
                  ],
                ),
              ],
            ),
          ),
          menu,
        ],
      ),
    );
  }
}

/// Ręczne podkręcanie / zbijanie intensywności CAŁEGO programu, krok po kroku.
/// Jeden krok to umiarkowana zmiana (≈5% ciężaru, +1 powtórzenie, seria co
/// drugi krok), żeby kilka kliknięć nie wywróciło zestawów.
class _IntensityStepControl extends StatelessWidget {
  const _IntensityStepControl({required this.plan, required this.dayIndex});

  final WorkoutPlan plan;
  final int dayIndex;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final day = plan.days[dayIndex];
    final daySteps = day.intensitySteps;
    final effective = store.effectiveIntensitySteps(plan, day);
    final setDelta = effective ~/ 2;
    final sign = effective > 0 ? '+' : '';

    final detail = effective == 0
        ? 'Zestaw jak zaprojektowany'
        : 'Ciężar ${(intensityStepFactor(effective) * 100).round()}%'
            ' · powtórzenia $sign$effective'
            '${setDelta != 0 ? ' · serie $sign$setDelta' : ''}';
    final fromProgram = plan.intensitySteps != 0
        ? '  (w tym program: ${intensityStepLabel(plan.intensitySteps)})'
        : '';

    return Container(
      key: const Key('intensity_step_control'),
      padding: const EdgeInsets.fromLTRB(10, 4, 4, 4),
      decoration: BoxDecoration(
        color: scheme.surfaceContainerHighest.withValues(alpha: 0.45),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Icon(Icons.speed_rounded, size: 18, color: scheme.onSurfaceVariant),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('Intensywność dnia: ${intensityStepLabel(daySteps)}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(fontWeight: FontWeight.w800)),
                Text('$detail$fromProgram',
                    style: theme.textTheme.labelSmall
                        ?.copyWith(color: scheme.onSurfaceVariant)),
              ],
            ),
          ),
          IconButton(
            key: const Key('intensity_step_down'),
            tooltip: 'Zejdź z intensywności tego dnia',
            visualDensity: VisualDensity.compact,
            onPressed: daySteps <= -kMaxIntensitySteps
                ? null
                : () => store.setPlanDayIntensitySteps(
                    plan.id, dayIndex, daySteps - 1),
            icon: const Icon(Icons.remove_circle_outline_rounded),
          ),
          IconButton(
            key: const Key('intensity_step_up'),
            tooltip: 'Podkręć intensywność tego dnia',
            visualDensity: VisualDensity.compact,
            onPressed: daySteps >= kMaxIntensitySteps
                ? null
                : () => store.setPlanDayIntensitySteps(
                    plan.id, dayIndex, daySteps + 1),
            icon: const Icon(Icons.add_circle_outline_rounded),
          ),
        ],
      ),
    );
  }
}

/// Ręczna korekta intensywności CAŁEGO programu (dodaje się do korekt dni).
class ProgramIntensityControl extends StatelessWidget {
  const ProgramIntensityControl({super.key, required this.plan});

  final WorkoutPlan plan;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final steps = plan.intensitySteps;

    return Container(
      key: const Key('program_intensity_control'),
      padding: const EdgeInsets.fromLTRB(10, 4, 4, 4),
      decoration: BoxDecoration(
        color: scheme.surfaceContainerHighest.withValues(alpha: 0.45),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Icon(Icons.speed_rounded, size: 18, color: scheme.onSurfaceVariant),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('Intensywność programu: ${intensityStepLabel(steps)}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(fontWeight: FontWeight.w800)),
                Text(
                  steps == 0
                      ? 'Dotyczy wszystkich dni — pojedynczy dzień ustawisz w jego szczegółach'
                      : 'Ciężar ${(intensityStepFactor(steps) * 100).round()}% we wszystkich dniach',
                  style: theme.textTheme.labelSmall
                      ?.copyWith(color: scheme.onSurfaceVariant),
                ),
              ],
            ),
          ),
          IconButton(
            key: const Key('program_intensity_down'),
            tooltip: 'Zejdź z intensywności programu',
            visualDensity: VisualDensity.compact,
            onPressed: steps <= -kMaxIntensitySteps
                ? null
                : () => store.setPlanIntensitySteps(plan.id, steps - 1),
            icon: const Icon(Icons.remove_circle_outline_rounded),
          ),
          IconButton(
            key: const Key('program_intensity_up'),
            tooltip: 'Podkręć intensywność programu',
            visualDensity: VisualDensity.compact,
            onPressed: steps >= kMaxIntensitySteps
                ? null
                : () => store.setPlanIntensitySteps(plan.id, steps + 1),
            icon: const Icon(Icons.add_circle_outline_rounded),
          ),
        ],
      ),
    );
  }
}

