}

/// Dolny, „przyklejony" pasek z głównym przyciskiem (START / odpoczynek / zablokowane).
class _DayStartBar extends StatelessWidget {
  const _DayStartBar({
    required this.plan,
    required this.dayIndex,
    required this.day,
    required this.status,
    required this.isRest,
    required this.isLocked,
  });

  final WorkoutPlan plan;
  final int dayIndex;
  final WorkoutDay day;
  final WorkoutDayStatus status;
  final bool isRest;
  final bool isLocked;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final isCompleted = status == WorkoutDayStatus.completed;

    Widget button;
    if (isLocked) {
      button = Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(Icons.lock_outline_rounded,
                  size: 16, color: theme.colorScheme.onSurfaceVariant),
              const SizedBox(width: 6),
              Flexible(
                child: Text(
                  'Odblokuje się po ukończeniu poprzedniego dnia',
                  textAlign: TextAlign.center,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          FilledButton.icon(
            onPressed: null,
            icon: const Icon(Icons.lock_rounded),
            label: const Text('Zablokowane'),
          ),
        ],
      );
    } else if (isRest) {
      button = FilledButton.tonalIcon(
        onPressed: () async {
          await store.setPlanDayCompleted(plan.id, dayIndex);
          if (context.mounted) Navigator.of(context).maybePop();
        },
        icon: const Icon(Icons.check_rounded),
        label: const Text('Zalicz dzień odpoczynku'),
      );
    } else {
      button = FilledButton.icon(
        onPressed: day.items.isEmpty
            ? null
            : () => startWorkoutForDay(context,
                plan: plan, day: day, dayIndex: dayIndex),
        icon:
            Icon(isCompleted ? Icons.replay_rounded : Icons.play_arrow_rounded),
        label: Text(isCompleted ? 'Powtórz trening' : 'START'),
      );
    }

    return Material(
      elevation: 8,
      color: theme.colorScheme.surface,
      child: SafeArea(
        top: false,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(16, 10, 16, 10),
          child: SizedBox(
            width: double.infinity,
            child: button,
          ),
        ),
      ),
    );
  }
}

class _PlanExerciseTile extends StatelessWidget {
  const _PlanExerciseTile(
      {required this.plan,
      required this.day,
      required this.item,
      required this.exercise});

  final WorkoutPlan plan;
  final WorkoutDay day;
  final PlanItem item;
  final Exercise exercise;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final store = AppScope.of(context);
    final weight = item.suggestedWeightKg > 0
        ? '${_formatPlanWeight(item.suggestedWeightKg)} kg'
        : 'bez ciężaru';
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
          color: theme.colorScheme.surface,
          borderRadius: BorderRadius.circular(15)),
      child: Row(
        children: [
          SizedBox(
              width: 48, height: 48, child: ExerciseVisual(exercise: exercise)),
          const SizedBox(width: 10),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(exercise.name,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.bodyLarge
                        ?.copyWith(fontWeight: FontWeight.w800)),
                const SizedBox(height: 3),
                Text(
                    '${item.sets} serie × ${item.reps} powt. · $weight · ${item.restSeconds} s przerwy',
                    maxLines: 3,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
              ],
            ),
          ),
          PopupMenuButton<String>(
            tooltip: 'Opcje ćwiczenia',
            onSelected: (value) async {
              if (value == 'edit') {
                await showPlanItemEditor(context,
                    plan: plan, day: day, exercise: exercise, existing: item);
              } else if (value == 'delete') {
                await store.removePlanItem(
                    planId: plan.id,
                    weekday: day.weekday,
                    exerciseId: item.exerciseId);
              }
            },
            itemBuilder: (context) => const [
              PopupMenuItem(
                  value: 'edit',
                  child: ListTile(
                      contentPadding: EdgeInsets.zero,
                      leading: Icon(Icons.tune_rounded),
                      title: Text('Edytuj parametry'))),
              PopupMenuItem(
                  value: 'delete',
                  child: ListTile(
                      contentPadding: EdgeInsets.zero,
                      leading: Icon(Icons.delete_outline),
                      title: Text('Usuń z dnia'))),
            ],
          ),
        ],
      ),
    );
  }
}

String _formatPlanWeight(double value) => value == value.roundToDouble()
    ? value.toStringAsFixed(0)
    : value.toStringAsFixed(1);

Future<void> showWorkoutPlanEditor(BuildContext context,
    {WorkoutPlan? plan}) async {
  final store = AppScope.read(context);
  var planName = plan?.name ?? '';
  var goal = normalizeWorkoutPlanGoal(plan?.goal ?? store.settings.goal);
  final selectedWeekdays = <int>{
    if (plan != null)
      ...plan.days.map((day) => day.weekday)
    else
      ...store.settings.trainingWeekdays,
  };
  if (selectedWeekdays.isEmpty) selectedWeekdays.addAll(const [1, 3, 5]);

  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) => Padding(
        padding: EdgeInsets.fromLTRB(
            16,
            0,
            16,
            16 +
                MediaQuery.of(context).viewInsets.bottom +
                MediaQuery.of(context).viewPadding.bottom),
        child: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(plan == null ? 'Nowy plan treningowy' : 'Edytuj plan',
                  style: Theme.of(context)
                      .textTheme
                      .titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 14),
              TextFormField(
                initialValue: planName,
                textCapitalization: TextCapitalization.sentences,
                decoration: const InputDecoration(labelText: 'Nazwa planu'),
                onChanged: (value) => planName = value,
              ),
              const SizedBox(height: 12),
              DropdownButtonFormField<String>(
                isExpanded: true,
                initialValue: goal,
                decoration: const InputDecoration(labelText: 'Cel planu'),
                items: workoutPlanGoals
                    .map((value) =>
                        DropdownMenuItem(value: value, child: Text(value)))
                    .toList(),
                onChanged: (value) => setSheetState(() => goal = value ?? goal),
              ),
              const SizedBox(height: 16),
              Text('Dni tygodnia',
                  style: Theme.of(context)
                      .textTheme
                      .titleMedium
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                children: [
                  for (var weekday = 1; weekday <= 7; weekday++)
                    FilterChip(
                      label: Text(weekdayName(weekday)),
                      selected: selectedWeekdays.contains(weekday),
                      onSelected: (selected) {
                        setSheetState(() {
                          if (selected) {
                            selectedWeekdays.add(weekday);
                          } else {
                            selectedWeekdays.remove(weekday);
                          }
                        });
                      },
                    ),
                ],
              ),
              const SizedBox(height: 8),
              Text(
                  'Usunięcie zaznaczenia dnia usunie go z planu razem z przypisanymi ćwiczeniami.',
                  style: Theme.of(context).textTheme.bodySmall?.copyWith(
                      color: Theme.of(context).colorScheme.onSurfaceVariant)),
              const SizedBox(height: 18),
              FilledButton.icon(
                onPressed: () async {
                  final cleanedName = planName.trim();
                  if (cleanedName.isEmpty) {
                    showError(sheetContext, 'Wpisz nazwę planu.');
                    return;
                  }
                  if (selectedWeekdays.isEmpty) {
                    showError(sheetContext,
                        'Wybierz przynajmniej jeden dzień tygodnia.');
                    return;
                  }
                  final weekdays = selectedWeekdays.toList()..sort();
                  final days = <WorkoutDay>[];
                  for (final weekday in weekdays) {
                    WorkoutDay? existingDay;
                    if (plan != null) {
                      for (final day in plan.days) {
                        if (day.weekday == weekday) {
                          existingDay = day;
                          break;
                        }
                      }
                    }
                    days.add(existingDay ??
                        WorkoutDay(
                            weekday: weekday,
                            title: 'Trening',
                            items: const []));
                  }
                  final updated = WorkoutPlan(
                    id: plan?.id ?? 'plan_${idNow()}',
                    name: cleanedName,
                    days: days,
                    note: plan?.note ?? 'Plan utworzony ręcznie.',
                    goal: goal,
                    isActive: plan?.isActive ?? store.plans.isEmpty,
                  );
                  if (plan == null) {
                    await store.addWorkoutPlan(updated);
                  } else {
                    await store.updateWorkoutPlan(updated);
                  }
                  if (sheetContext.mounted) Navigator.pop(sheetContext);
                },
                icon: const Icon(Icons.save_outlined),
                label: Text(plan == null ? 'Utwórz plan' : 'Zapisz zmiany'),
              ),
            ],
          ),
        ),
      ),
    ),
  );
}

