/// Wybór CIĘŻSZEGO albo LŻEJSZEGO wariantu tego samego ruchu.
///
/// Propozycje są posortowane od najbliższego skoku trudności — podmiana ma być
/// krokiem (pompki → pompki na podwyższeniu → wyciskanie hantli → sztanga),
/// a nie przeskokiem z masy ciała prosto na maksymalny bój.
Future<Exercise?> showIntensityVariantPicker(
  BuildContext context, {
  required Exercise current,
  required bool harder,
  Set<String> excludeIds = const {},
}) async {
  final store = AppScope.read(context);
  final pool = ExerciseRepo.combined(store.customExercises)
      .where((e) => !store.isExerciseHidden(e.id) && !excludeIds.contains(e.id))
      .toList();
  final options = alternativesByIntensity(current, pool, harder: harder);
  if (options.isEmpty) {
    showError(
        context,
        harder
            ? 'Brak cięższego wariantu dla tego ćwiczenia.'
            : 'Brak lżejszego wariantu dla tego ćwiczenia.');
    return null;
  }
  return showModalBottomSheet<Exercise>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      final theme = Theme.of(sheetContext);
      return FractionallySizedBox(
        heightFactor: 0.8,
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 10),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(harder ? 'Cięższy wariant' : 'Lżejszy wariant',
                      style: theme.textTheme.titleLarge
                          ?.copyWith(fontWeight: FontWeight.w900)),
                  const SizedBox(height: 4),
                  Text(
                    '${current.name} · teraz: ${exerciseIntensityTier(current).label}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                ],
              ),
            ),
            Expanded(
              child: ListView.builder(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
                itemCount: options.length,
                itemBuilder: (context, index) {
                  final exercise = options[index];
                  return Card(
                    margin: const EdgeInsets.only(bottom: 8),
                    child: ListTile(
                      leading: SizedBox(
                          width: 48,
                          height: 48,
                          child: ExerciseVisual(exercise: exercise)),
                      title: Text(exercise.name,
                          maxLines: 2, overflow: TextOverflow.ellipsis),
                      subtitle: Text(
                          '${exerciseIntensityTier(exercise).label} · ${exercise.equipment}',
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis),
                      trailing: Icon(harder
                          ? Icons.trending_up_rounded
                          : Icons.trending_down_rounded),
                      onTap: () => Navigator.pop(sheetContext, exercise),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      );
    },
  );
}

Future<void> showPlanExercisePicker(BuildContext context,
    {required WorkoutPlan plan, required WorkoutDay day}) async {
  final store = AppScope.read(context);
  // Partie trenowane w tym dniu — ćwiczenia je obejmujące pokazujemy na górze
  // jako „propozycję pod ten dzień".
  final dayMuscles = <MuscleGroup>{
    for (final item in day.items)
      ...ExerciseRepo.byId(item.exerciseId, store.customExercises).muscleGroups,
  };
  bool fitsDay(Exercise e) =>
      dayMuscles.isNotEmpty && e.muscleGroups.any(dayMuscles.contains);

  // Ręczne dodawanie nie może obchodzić reguł, którymi rządzi się generator:
  // poziom użytkownika, posiadany sprzęt i ograniczenia zdrowotne.
  final owned = store.settings.equipmentProfile.resolveOwned();
  final limits = store.settings.limitationProfile;
  final userRank = trainingLevelRank(store.settings.level);
  bool aboveLevel(Exercise e) => trainingLevelRank(e.level) > userRank;
  bool missingGear(Exercise e) => !isExerciseAvailable(e, owned);
  bool risky(Exercise e) => exerciseViolatesLimitation(e, limits);
  String warningFor(Exercise e) {
    final parts = <String>[
      if (risky(e)) 'ostrożnie: Twoje ograniczenia',
      if (aboveLevel(e)) 'powyżej Twojego poziomu',
      if (missingGear(e)) 'brak sprzętu',
    ];
    return parts.join(' · ');
  }

  /// Im niżej, tym lepsza propozycja (0 = idealna pod ten dzień).
  int rankOf(Exercise e) =>
      (fitsDay(e) ? 0 : 1) +
      (missingGear(e) ? 2 : 0) +
      (aboveLevel(e) ? 4 : 0) +
      (risky(e) ? 8 : 0);

  var query = '';
  ExerciseIntensityTier? tierFilter;
  final selected = await showModalBottomSheet<Exercise>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (context, setSheetState) {
        final exercises =
            ExerciseRepo.combined(store.customExercises).where((exercise) {
          if (store.isExerciseHidden(exercise.id)) return false;
          if (tierFilter != null &&
              exerciseIntensityTier(exercise) != tierFilter) {
            return false;
          }
          return query.isEmpty || exercise.name.toLowerCase().contains(query);
        }).toList();
        // Najpierw propozycje pod ten dzień; ćwiczenia ponad poziom, bez
        // sprzętu albo kolidujące z ograniczeniami spadają na koniec listy.
        exercises.sort((a, b) => rankOf(a).compareTo(rankOf(b)));
        return FractionallySizedBox(
          heightFactor: 0.86,
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Dodaj ćwiczenie',
                        style: Theme.of(context)
                            .textTheme
                            .titleLarge
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 4),
                    Text('${plan.name} · ${weekdayName(day.weekday)}',
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                        style: Theme.of(context).textTheme.bodyMedium?.copyWith(
                            color: Theme.of(context)
                                .colorScheme
                                .onSurfaceVariant)),
                    const SizedBox(height: 12),
                    TextField(
                      autofocus: true,
                      decoration: const InputDecoration(
                          prefixIcon: Icon(Icons.search_rounded),
                          labelText: 'Szukaj po nazwie'),
                      onChanged: (value) => setSheetState(
                          () => query = value.trim().toLowerCase()),
                    ),
                    const SizedBox(height: 10),
                    // Filtr intensywności — pozwala dobrać ćwiczenie świadomie
                    // pod to, jak ciężki ma być zestaw.
                    SizedBox(
                      height: 36,
                      child: ListView(
                        scrollDirection: Axis.horizontal,
                        children: [
                          for (final tier in ExerciseIntensityTier.values)
                            Padding(
                              padding: const EdgeInsets.only(right: 8),
                              child: ChoiceChip(
                                label: Text(tier.label),
                                selected: tierFilter == tier,
                                onSelected: (_) => setSheetState(() =>
                                    tierFilter =
                                        tierFilter == tier ? null : tier),
                              ),
                            ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: exercises.isEmpty
                    ? const Center(child: Text('Brak pasujących ćwiczeń'))
                    : ListView.builder(
                        padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
                        itemCount: exercises.length,
                        itemBuilder: (context, index) {
                          final exercise = exercises[index];
                          final alreadyAdded = day.items
                              .any((item) => item.exerciseId == exercise.id);
                          final warning = warningFor(exercise);
                          final suggested = query.isEmpty &&
                              fitsDay(exercise) &&
                              warning.isEmpty;
                          return Card(
                            margin: const EdgeInsets.only(bottom: 8),
                            child: ListTile(
                              leading: SizedBox(
                                  width: 48,
                                  height: 48,
                                  child: ExerciseVisual(exercise: exercise)),
                              title: Row(
                                children: [
                                  Flexible(
                                    child: Text(exercise.name,
                                        maxLines: 2,
                                        overflow: TextOverflow.ellipsis),
                                  ),
                                  if (suggested) ...[
                                    const SizedBox(width: 6),
                                    Icon(Icons.auto_awesome_rounded,
                                        size: 15,
                                        color: Theme.of(context)
                                            .colorScheme
                                            .primary),
                                  ],
                                ],
                              ),
                              subtitle: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                      '${exerciseIntensityTier(exercise).label}'
                                      '${suggested ? ' · Pod ten dzień' : ''}'
                                      ' · ${exercise.primaryMuscle}'
                                      ' · ${exercise.equipment}',
                                      maxLines: 2,
                                      overflow: TextOverflow.ellipsis),
                                  if (warning.isNotEmpty)
                                    Text(
                                      warning,
                                      maxLines: 2,
                                      overflow: TextOverflow.ellipsis,
                                      style: Theme.of(context)
                                          .textTheme
                                          .labelSmall
                                          ?.copyWith(
                                              color: Theme.of(context)
                                                  .colorScheme
                                                  .error,
                                              fontWeight: FontWeight.w700),
                                    ),
                                ],
                              ),
                              trailing: Icon(alreadyAdded
                                  ? Icons.tune_rounded
                                  : Icons.add_circle_outline_rounded),
                              onTap: () =>
                                  Navigator.pop(sheetContext, exercise),
                            ),
                          );
                        },
                      ),
              ),
            ],
          ),
        );
      },
    ),
  );
  if (!context.mounted || selected == null) return;
  PlanItem? existing;
  for (final item in day.items) {
    if (item.exerciseId == selected.id) {
      existing = item;
      break;
    }
  }
  await showPlanItemEditor(context,
      plan: plan, day: day, exercise: selected, existing: existing);
}

Future<void> showPlanItemEditor(
  BuildContext context, {
  required WorkoutPlan plan,
  required WorkoutDay day,
  required Exercise exercise,
  PlanItem? existing,
}) async {
  final store = AppScope.read(context);
  var setsValue = '${existing?.sets ?? exercise.defaultSets}';
  var repsValue =
      '${existing?.reps ?? (exercise.defaultReps > 0 ? exercise.defaultReps : 10)}';
  var weightValue = _formatPlanWeight(existing?.suggestedWeightKg ?? 0);
  var restValue = '${existing?.restSeconds ?? 90}';
  var noteValue = existing?.note ?? '';

  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => Padding(
      padding: EdgeInsets.fromLTRB(
          16,
          0,
          16,
          16 +
              MediaQuery.of(sheetContext).viewInsets.bottom +
              MediaQuery.of(sheetContext).viewPadding.bottom),
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(existing == null ? 'Dodaj do dnia' : 'Edytuj ćwiczenie',
                style: Theme.of(sheetContext)
                    .textTheme
                    .titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 4),
            Text('${exercise.name} · ${weekdayName(day.weekday)}',
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: Theme.of(sheetContext).textTheme.bodyMedium?.copyWith(
                    color:
                        Theme.of(sheetContext).colorScheme.onSurfaceVariant)),
            const SizedBox(height: 14),
            Row(
              children: [
                Expanded(
                  child: TextFormField(
                    initialValue: setsValue,
                    keyboardType: TextInputType.number,
                    decoration:
                        const InputDecoration(labelText: 'Liczba serii'),
                    onChanged: (value) => setsValue = value,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: TextFormField(
                    initialValue: repsValue,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Powtórzenia'),
                    onChanged: (value) => repsValue = value,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            Row(
              children: [
                Expanded(
                  child: TextFormField(
                    initialValue: weightValue,
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    decoration: const InputDecoration(labelText: 'Ciężar (kg)'),
                    onChanged: (value) => weightValue = value,
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: TextFormField(
                    initialValue: restValue,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(labelText: 'Przerwa (s)'),
                    onChanged: (value) => restValue = value,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            TextFormField(
              initialValue: noteValue,
              textCapitalization: TextCapitalization.sentences,
              maxLines: 2,
              decoration:
                  const InputDecoration(labelText: 'Notatka (opcjonalnie)'),
              onChanged: (value) => noteValue = value,
            ),
            const SizedBox(height: 16),
            FilledButton.icon(
              onPressed: () async {
                final parsedSets = int.tryParse(setsValue.trim());
                final parsedReps = int.tryParse(repsValue.trim());
                final parsedWeight =
                    double.tryParse(weightValue.trim().replaceAll(',', '.'));
                final parsedRest = int.tryParse(restValue.trim());
                if (parsedSets == null || parsedSets < 1 || parsedSets > 99) {
                  showError(sheetContext,
                      'Liczba serii musi mieścić się w zakresie 1–99.');
                  return;
                }
                if (parsedReps == null || parsedReps < 1 || parsedReps > 999) {
                  showError(sheetContext,
                      'Liczba powtórzeń musi mieścić się w zakresie 1–999.');
                  return;
                }
                if (parsedWeight == null ||
                    parsedWeight < 0 ||
                    parsedWeight > 9999) {
                  showError(sheetContext, 'Podaj poprawny sugerowany ciężar.');
                  return;
                }
                if (parsedRest == null || parsedRest < 0 || parsedRest > 3600) {
                  showError(sheetContext,
                      'Przerwa musi mieścić się w zakresie 0–3600 sekund.');
                  return;
                }
                await store.upsertPlanItem(
                  planId: plan.id,
                  weekday: day.weekday,
                  item: PlanItem(
                    exerciseId: exercise.id,
                    sets: parsedSets,
                    reps: parsedReps,
                    durationSec:
                        existing?.durationSec ?? exercise.defaultDurationSec,
                    note: noteValue.trim(),
                    suggestedWeightKg: parsedWeight,
                    restSeconds: parsedRest,
                  ),
                );
                if (sheetContext.mounted) Navigator.pop(sheetContext);
              },
              icon: const Icon(Icons.save_outlined),
              label: Text(
                  existing == null ? 'Dodaj ćwiczenie' : 'Zapisz parametry'),
            ),
          ],
        ),
      ),
    ),
  );
}

void showPlanGenerator(BuildContext context) {
  final store = AppScope.read(context);
  final goal = TextEditingController(text: store.settings.goal);
  final equipment = TextEditingController(text: store.settings.equipment);
  final limitations = TextEditingController(text: store.settings.limitations);
  int days = store.settings.trainingWeekdays.length.clamp(2, 6).toInt();
  var level = normalizeLevel(store.settings.level);
  showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) {
      return StatefulBuilder(builder: (context, setSheet) {
        return Padding(
          padding: EdgeInsets.fromLTRB(
            16,
            0,
            16,
            16 +
                MediaQuery.of(context).viewInsets.bottom +
                MediaQuery.of(context).viewPadding.bottom,
          ),
          child: SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              mainAxisSize: MainAxisSize.min,
              children: [
                Text('Generator planu AI',
                    style: Theme.of(context)
                        .textTheme
                        .titleLarge
                        ?.copyWith(fontWeight: FontWeight.w900)),
                const SizedBox(height: 12),
                TextField(
                    controller: goal,
                    decoration: const InputDecoration(labelText: 'Cel')),
                const SizedBox(height: 10),
                TextField(
                    controller: equipment,
                    decoration: const InputDecoration(labelText: 'Sprzęt')),
                const SizedBox(height: 10),
                TextField(
                    controller: limitations,
                    maxLines: 3,
                    decoration: const InputDecoration(
                        labelText: 'Ograniczenia / kontuzje / uwagi')),
                const SizedBox(height: 10),
                DropdownButtonFormField<String>(
                  isExpanded: true,
                  value: level,
                  decoration: const InputDecoration(labelText: 'Poziom planu'),
                  selectedItemBuilder: (context) => kTrainingLevels
                      .map((v) => Align(
                          alignment: Alignment.centerLeft,
                          child: Text(v,
                              maxLines: 1, overflow: TextOverflow.ellipsis)))
                      .toList(),
                  items: kTrainingLevels
                      .map((v) => DropdownMenuItem(
                          value: v,
                          child: Text(v,
                              maxLines: 1, overflow: TextOverflow.ellipsis)))
                      .toList(),
                  onChanged: (v) => setSheet(() => level = v ?? level),
                ),
                const SizedBox(height: 10),
                Row(
                  children: [
                    const Text('Dni w tygodniu'),
                    Expanded(
                        child: Slider(
                            value: days.toDouble(),
                            min: 2,
                            max: 6,
                            divisions: 4,
                            label: '$days',
                            onChanged: (v) =>
                                setSheet(() => days = v.round()))),
                    Text('$days'),
                  ],
                ),
                const SizedBox(height: 12),
                FilledButton.icon(
                  onPressed: store.aiBusy
                      ? null
                      : () async {
                          try {
                            await store.updateSettings(store.settings.copyWith(
                                level: level,
                                equipment: equipment.text.trim(),
                                limitations: limitations.text.trim(),
                                backendUrl: kDefaultBackendUrl));
                            await store.generateAiPlan(
                                goal: goal.text,
                                days: days,
                                equipment: equipment.text,
                                limitations: limitations.text);
                            if (!context.mounted) return;
                            Navigator.pop(sheetContext);
                          } catch (e) {
                            if (!context.mounted) return;
                            showError(context, e.toString());
                          }
                        },
                  icon: store.aiBusy
                      ? const SizedBox(
                          width: 16,
                          height: 16,
                          child: CircularProgressIndicator(strokeWidth: 2))
                      : const Icon(Icons.auto_awesome),
                  label: const Text('Wygeneruj przez backend'),
                ),
              ],
            ),
          ),
        );
      });
    },
  ).whenComplete(() {
    goal.dispose();
    equipment.dispose();
    limitations.dispose();
  });
}

class ProgressPage extends StatelessWidget {
  const ProgressPage({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final now = DateTime.now();
    final weekStart = startOfTrainingWeek(now);
    final monthStart = DateTime(now.year, now.month);
    final weekDays =
        List.generate(7, (index) => weekStart.add(Duration(days: index)));
    final weekLogs = store.logsBetween(weekStart, now);
    final monthLogs = store.logsBetween(monthStart, now);
    final weekTotals = DayTotals.from(weekLogs);
    final monthTotals = DayTotals.from(monthLogs);
    final weekWorkoutCount = workoutEntryCount(weekLogs);
    final monthWorkoutCount = workoutEntryCount(monthLogs);
    final weekVolumeValues =
        weekDays.map((day) => store.totalsForDay(day).volume).toList();
    final weekVolumeLabels =
        weekDays.map((day) => weekdayShortName(day.weekday)).toList();
    final recentWeekStarts = List.generate(
        4, (index) => weekStart.subtract(Duration(days: (3 - index) * 7)));
    final workoutCountValues = recentWeekStarts
        .map(
          (start) => workoutEntryCount(
            store.logsBetween(start, start.add(const Duration(days: 6))),
          ).toDouble(),
        )
        .toList();
    final workoutCountLabels = ['T-3', 'T-2', 'T-1', 'Teraz'];
    // Czat AI Trainer jako pływający dymek w prawym dolnym rogu zakładki.
    return Stack(
      children: [
        PageFrame(
          title: 'Progres',
          subtitle: 'Wykresy, statystyki, historia i dane treningowe',
          // Wykresy i analizy jako leniwa lista sliverów — budowane przy przewijaniu.
          slivers: [
            SliverPadding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 24),
              sliver: SliverList(
                delegate: SliverChildListDelegate.fixed([
                  const MesocycleHistoryCard(),
                  const SizedBox(height: 12),
                  SimpleProgressBarChartCard(
                    title: 'Objętość tygodniowa',
