/// Kafelek „Sylwetka" na Postępie: waga z trendem, ostatnia analiza AI
/// (tłuszcz/mięśnie), docelowy typ sylwetki — wejście do pomiarów i analizy.
class BodySnapshotCard extends StatelessWidget {
  const BodySnapshotCard({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final measurements = store.bodyMeasurements;
    final latestMeasurement = measurements.isEmpty ? null : measurements.first;
    BodyMeasurement? previousWithWeight;
    for (var index = 1; index < measurements.length; index++) {
      if (measurements[index].weightKg > 0) {
        previousWithWeight = measurements[index];
        break;
      }
    }
    final analysis = store.latestBodyAnalysis;
    final target = SilhouetteGoal.fromId(store.settings.targetSilhouette);

    String weightText = 'Brak pomiaru wagi';
    if (latestMeasurement != null && latestMeasurement.weightKg > 0) {
      weightText = '${latestMeasurement.weightKg.toStringAsFixed(1)} kg';
      if (previousWithWeight != null) {
        final diff = latestMeasurement.weightKg - previousWithWeight.weightKg;
        if (diff.abs() >= 0.05) {
          weightText += ' (${diff > 0 ? '+' : ''}${diff.toStringAsFixed(1)})';
        }
      }
    }

    return Card(
      key: const Key('body_snapshot_card'),
      clipBehavior: Clip.antiAlias,
      child: InkWell(
        onTap: () => Navigator.of(context).push(
            MaterialPageRoute(builder: (_) => const BodyMeasurementsPage())),
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Row(
                children: [
                  Icon(Icons.accessibility_new_rounded,
                      color: theme.colorScheme.primary),
                  const SizedBox(width: 8),
                  Expanded(
                      child: Text('Sylwetka',
                          style: theme.textTheme.titleMedium
                              ?.copyWith(fontWeight: FontWeight.w900))),
                  const Icon(Icons.chevron_right_rounded),
                ],
              ),
              const SizedBox(height: 10),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  MiniTag(text: 'Waga: $weightText'),
                  if (analysis != null &&
                      analysis.composition.bodyFatPercent > 0)
                    MiniTag(
                        text:
                            'Tłuszcz ${analysis.composition.bodyFatPercent.toStringAsFixed(1)}%'),
                  if (analysis != null &&
                      analysis.composition.musclePercent > 0)
                    MiniTag(
                        text:
                            'Mięśnie ${analysis.composition.musclePercent.toStringAsFixed(1)}%'),
                  if (target != null) MiniTag(text: 'Cel: ${target.label}'),
                ],
              ),
              const SizedBox(height: 8),
              Text(
                analysis == null
                    ? 'Dodaj zdjęcia progresu (przód/bok/tył) i uruchom analizę sylwetki AI — skład ciała, postawa, wymiary i plan do celu.'
                    : analysis.currentSilhouette.isEmpty
                        ? 'Ostatnia analiza: ${trainerHistoryFullDate(analysis.date)}.'
                        : '${analysis.currentSilhouette} · analiza ${trainerHistoryFullDate(analysis.date)}',
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: theme.textTheme.bodySmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant, height: 1.35),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// Cel wagowy z prognozą: aktualna waga, trend kg/tydzień z pomiarów
/// (regresja liniowa) i szacowana data osiągnięcia celu.
class WeightGoalCard extends StatelessWidget {
  const WeightGoalCard({super.key});

  Future<void> _editGoal(BuildContext context, AppStore store) async {
    final controller = TextEditingController(
      text: store.settings.targetWeightKg > 0
          ? store.settings.targetWeightKg.toStringAsFixed(1)
          : '',
    );
    final saved = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Docelowa masa ciała'),
        content: TextField(
          key: const Key('target_weight_field'),
          controller: controller,
          autofocus: true,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(
              labelText: 'Cel', suffixText: 'kg', hintText: 'np. 90'),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
            key: const Key('save_target_weight'),
            onPressed: () => Navigator.pop(dialogContext, true),
            child: const Text('Zapisz'),
          ),
        ],
      ),
    );
    if (saved != true) return;
    final parsed =
        double.tryParse(controller.text.replaceAll(',', '.').trim()) ?? 0;
    await store.updateSettings(
        store.settings.copyWith(targetWeightKg: parsed.clamp(0, 400)));
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final goal = store.settings.targetWeightKg;
    final trend = computeWeightTrend(store.bodyMeasurements);
    final currentKg = trend?.currentKg ??
        (store.bodyMeasurements.where((m) => m.weightKg > 0).isNotEmpty
            ? store.bodyMeasurements.firstWhere((m) => m.weightKg > 0).weightKg
            : store.settings.bodyWeightKg);

    // --- Prognoza: kiedy przy obecnym tempie osiągniesz cel. ---
    String forecast;
    if (goal <= 0) {
      forecast = 'Ustaw docelową wagę, a policzę tempo i przewidywaną datę.';
    } else if (trend == null) {
      forecast =
          'Dodaj co najmniej dwa pomiary wagi, żeby policzyć trend i prognozę.';
    } else if (trend.kgPerWeek.abs() < 0.05) {
      forecast =
          'Waga stabilna (±0,05 kg/tydz.) — przy tym tempie cel się nie przybliża.';
    } else {
      final remaining = goal - currentKg;
      if (remaining.abs() < 0.3) {
        forecast = 'Cel osiągnięty — utrzymuj obecną wagę!';
      } else if (remaining.sign != trend.kgPerWeek.sign) {
        forecast =
            'Trend (${trend.kgPerWeek > 0 ? '+' : ''}${trend.kgPerWeek.toStringAsFixed(2)} kg/tydz.) idzie w przeciwną stronę niż cel.';
      } else {
        final weeks = remaining / trend.kgPerWeek;
        if (weeks > 104) {
          forecast =
              'Przy obecnym tempie cel za ponad 2 lata — rozważ korektę planu.';
        } else {
          final eta = DateTime.now().add(Duration(days: (weeks * 7).round()));
          forecast =
              'Przy tempie ${trend.kgPerWeek > 0 ? '+' : ''}${trend.kgPerWeek.toStringAsFixed(2)} kg/tydz. '
              'osiągniesz ${goal.toStringAsFixed(1)} kg ok. ${trainerHistoryFullDate(eta)}.';
        }
      }
    }

    final targets = store.goalNutritionTargets;
    return Card(
      key: const Key('weight_goal_card'),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.flag_circle_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Cel wagowy',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
                IconButton(
                  key: const Key('edit_target_weight'),
                  tooltip: 'Ustaw cel wagi',
                  visualDensity: VisualDensity.compact,
                  onPressed: () => _editGoal(context, store),
                  icon: const Icon(Icons.edit_outlined, size: 20),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                MiniTag(text: 'Teraz: ${currentKg.toStringAsFixed(1)} kg'),
                if (goal > 0)
                  MiniTag(text: 'Cel: ${goal.toStringAsFixed(1)} kg'),
                if (trend != null)
                  MiniTag(
                      text:
                          'Trend: ${trend.kgPerWeek > 0 ? '+' : ''}${trend.kgPerWeek.toStringAsFixed(2)} kg/tydz.'),
                if (targets != null)
                  MiniTag(text: 'Faza: ${targets.phaseLabel}'),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              forecast,
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
          ],
        ),
      ),
    );
  }
}

class ProgressSummaryTiles extends StatelessWidget {
  const ProgressSummaryTiles({
    super.key,
    required this.weekWorkoutCount,
    required this.monthWorkoutCount,
    required this.weekVolume,
    required this.monthVolume,
    required this.weekSets,
    required this.monthSets,
  });

  final int weekWorkoutCount;
  final int monthWorkoutCount;
  final double weekVolume;
  final double monthVolume;
  final int weekSets;
  final int monthSets;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final width = constraints.maxWidth >= 720
            ? (constraints.maxWidth - 20) / 3
            : constraints.maxWidth >= 420
                ? (constraints.maxWidth - 10) / 2
                : constraints.maxWidth;
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            SizedBox(
              width: width,
              child: ProgressMetricTile(
                key: const Key('progress_week_workouts'),
                label: 'Treningi tydzień',
                value: '$weekWorkoutCount',
                helper: 'unikalne sesje',
                icon: Icons.calendar_view_week_outlined,
              ),
            ),
            SizedBox(
              width: width,
              child: ProgressMetricTile(
                key: const Key('progress_month_workouts'),
                label: 'Treningi miesiąc',
                value: '$monthWorkoutCount',
                helper: 'unikalne sesje',
                icon: Icons.calendar_month_outlined,
              ),
            ),
            SizedBox(
              width: width,
              child: ProgressMetricTile(
                key: const Key('progress_week_volume'),
                label: 'Objętość tydzień',
