class _ProgressBarColumn extends StatelessWidget {
  const _ProgressBarColumn({
    required this.value,
    required this.max,
    required this.label,
    required this.suffix,
  });

  final double value;
  final double max;
  final String label;
  final String suffix;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final ratio = max <= 0 ? 0.0 : (value / max).clamp(0.0, 1.0);
    return Column(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        SizedBox(
          height: 28,
          child: FittedBox(
            fit: BoxFit.scaleDown,
            child: Text(value == 0 ? '0' : '${value.round()} $suffix',
                style: theme.textTheme.labelSmall
                    ?.copyWith(fontWeight: FontWeight.w900)),
          ),
        ),
        const SizedBox(height: 6),
        Expanded(
          child: Align(
            alignment: Alignment.bottomCenter,
            child: FractionallySizedBox(
              heightFactor: math.max(0.04, ratio),
              widthFactor: 1,
              child: DecoratedBox(
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(14),
                  gradient: LinearGradient(
                    begin: Alignment.bottomCenter,
                    end: Alignment.topCenter,
                    colors: [
                      theme.colorScheme.primary.withValues(alpha: 0.55),
                      theme.colorScheme.primary,
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
        const SizedBox(height: 8),
        Text(label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.labelSmall
                ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
      ],
    );
  }
}

class BasicMuscleFrequencyCard extends StatelessWidget {
  const BasicMuscleFrequencyCard({
    super.key,
    required this.logs,
    required this.customExercises,
  });

  final List<WorkoutLog> logs;
  final List<Exercise> customExercises;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final counts = muscleCounts(logs, customExercises);
    final most = counts.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    final least = counts.entries.toList()
      ..sort((a, b) => a.value.compareTo(b.value));
    final max = most.isEmpty ? 1 : most.first.value;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.pie_chart_outline_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Partie mięśniowe',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
              ],
            ),
            const SizedBox(height: 4),
            Text(
                'Najczęściej i najrzadziej trenowane partie w bieżącym miesiącu.',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            const SizedBox(height: 14),
            if (most.isEmpty)
              Text(
                  'Brak danych. Zakończ trening, a Trainer pokaże rozkład partii.',
                  style: theme.textTheme.bodyMedium
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant))
            else
              LayoutBuilder(
                builder: (context, constraints) {
                  final wide = constraints.maxWidth >= 520;
                  final frequent = _MuscleRankColumn(
                      title: 'Najczęściej trenowane partie',
                      entries: most.take(5).toList(),
                      max: max);
                  final rare = _MuscleRankColumn(
                      title: 'Najrzadziej trenowane partie',
                      entries: least.take(5).toList(),
                      max: max);
                  if (!wide) {
                    return Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        frequent,
                        const SizedBox(height: 14),
                        rare,
                      ],
                    );
                  }
                  return Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(child: frequent),
                      const SizedBox(width: 16),
                      Expanded(child: rare),
                    ],
                  );
                },
              ),
          ],
        ),
      ),
    );
  }
}

