class ProgressLineChart extends StatelessWidget {
  final List<double> values;

  const ProgressLineChart({super.key, required this.values});

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
        painter: ProgressLinePainter(
            values: values, color: Theme.of(context).colorScheme.primary),
        child: const SizedBox.expand());
  }
}

class ProgressLinePainter extends CustomPainter {
  final List<double> values;
  final Color color;

  ProgressLinePainter({required this.values, required this.color});

  @override
  void paint(Canvas canvas, Size size) {
    final grid = Paint()
      ..color = color.withOpacity(0.13)
      ..strokeWidth = 1;
    for (var i = 0; i < 4; i++) {
      final y = size.height * i / 3;
      canvas.drawLine(Offset(0, y), Offset(size.width, y), grid);
    }
    if (values.isEmpty) return;
    final maxValue = math.max(1.0, values.reduce(math.max));
    final step =
        values.length == 1 ? size.width : size.width / (values.length - 1);
    final path = Path();
    for (var i = 0; i < values.length; i++) {
      final x = i * step;
      final y = size.height - (values[i] / maxValue) * (size.height - 12) - 6;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    final fill = Path.from(path)
      ..lineTo(size.width, size.height)
      ..lineTo(0, size.height)
      ..close();
    canvas.drawPath(
        fill,
        Paint()
          ..color = color.withOpacity(0.10)
          ..style = PaintingStyle.fill);
    canvas.drawPath(
        path,
        Paint()
          ..color = color
          ..strokeWidth = 3
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round);
    for (var i = 0; i < values.length; i++) {
      final x = i * step;
      final y = size.height - (values[i] / maxValue) * (size.height - 12) - 6;
      canvas.drawCircle(Offset(x, y), 4, Paint()..color = color);
    }
  }

  @override
  bool shouldRepaint(covariant ProgressLinePainter oldDelegate) =>
      oldDelegate.values != values || oldDelegate.color != color;
}

