class _BodyMeasurementFormCardState extends State<BodyMeasurementFormCard> {
  late DateTime selectedDate;
  late final TextEditingController weight;
  late final TextEditingController waist;
  late final TextEditingController chest;
  late final TextEditingController arm;
  late final TextEditingController thigh;
  late final TextEditingController hips;
  late final TextEditingController calf;
  late final TextEditingController shoulders;
  late final TextEditingController neck;
  late final TextEditingController note;

  @override
  void initState() {
    super.initState();
    selectedDate = DateTime.now();
    weight = TextEditingController();
    waist = TextEditingController();
    chest = TextEditingController();
    arm = TextEditingController();
    thigh = TextEditingController();
    hips = TextEditingController();
    calf = TextEditingController();
    shoulders = TextEditingController();
    neck = TextEditingController();
    note = TextEditingController();
  }

  @override
  void dispose() {
    weight.dispose();
    waist.dispose();
    chest.dispose();
    arm.dispose();
    thigh.dispose();
    hips.dispose();
    calf.dispose();
    shoulders.dispose();
    neck.dispose();
    note.dispose();
    super.dispose();
  }

  Future<void> pickDate() async {
    final picked = await showDatePicker(
      context: context,
      initialDate: selectedDate,
      firstDate: DateTime(2020),
      lastDate: DateTime.now().add(const Duration(days: 1)),
      helpText: 'Data pomiaru',
    );
    if (picked == null || !mounted) return;
    setState(() => selectedDate = picked);
  }

  Future<void> save() async {
    final now = DateTime.now();
    final measurement = BodyMeasurement(
      id: 'measurement_${idNow()}',
      date: DateTime(selectedDate.year, selectedDate.month, selectedDate.day,
          now.hour, now.minute),
      weightKg: parseBodyMeasurementValue(weight.text),
      waistCm: parseBodyMeasurementValue(waist.text),
      chestCm: parseBodyMeasurementValue(chest.text),
      armCm: parseBodyMeasurementValue(arm.text),
      thighCm: parseBodyMeasurementValue(thigh.text),
      hipsCm: parseBodyMeasurementValue(hips.text),
      calfCm: parseBodyMeasurementValue(calf.text),
      shouldersCm: parseBodyMeasurementValue(shoulders.text),
      neckCm: parseBodyMeasurementValue(neck.text),
      note: note.text.trim(),
      // Aktualne zdjęcia progresu (przód/bok/tył) podpinają się do pomiaru.
      progressPhotoPaths: widget.store.progressPhotoDraftPaths,
    );
    if (!measurement.hasAnyMeasurement && measurement.note.isEmpty) {
      showError(context, 'Dodaj przynajmniej jeden pomiar albo notatkę.');
      return;
    }
    await widget.store.addBodyMeasurement(measurement);
    if (!mounted) return;
    weight.clear();
    waist.clear();
    chest.clear();
    arm.clear();
    thigh.clear();
    hips.clear();
    calf.clear();
    shoulders.clear();
    neck.clear();
    note.clear();
    setState(() => selectedDate = DateTime.now());
    showError(context, 'Zapisano pomiar sylwetki.');
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final fields = [
      _BodyMeasurementField(
          controller: weight,
          label: 'Waga',
          unit: 'kg',
          keyValue: 'measurement_weight'),
      _BodyMeasurementField(
          controller: waist,
          label: 'Pas',
          unit: 'cm',
          keyValue: 'measurement_waist'),
      _BodyMeasurementField(
          controller: chest,
          label: 'Klatka',
          unit: 'cm',
          keyValue: 'measurement_chest'),
      _BodyMeasurementField(
          controller: arm,
          label: 'Ramię',
          unit: 'cm',
          keyValue: 'measurement_arm'),
      _BodyMeasurementField(
          controller: thigh,
          label: 'Udo',
          unit: 'cm',
          keyValue: 'measurement_thigh'),
      _BodyMeasurementField(
          controller: hips,
          label: 'Biodra',
          unit: 'cm',
          keyValue: 'measurement_hips'),
      _BodyMeasurementField(
          controller: calf,
          label: 'Łydka',
          unit: 'cm',
          keyValue: 'measurement_calf'),
      _BodyMeasurementField(
          controller: shoulders,
          label: 'Barki',
          unit: 'cm',
          keyValue: 'measurement_shoulders'),
      _BodyMeasurementField(
          controller: neck,
          label: 'Szyja',
          unit: 'cm',
          keyValue: 'measurement_neck'),
    ];
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.straighten_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Dodaj pomiar',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
              ],
            ),
            const SizedBox(height: 12),
            OutlinedButton.icon(
              key: const Key('measurement_date_button'),
              onPressed: pickDate,
              icon: const Icon(Icons.event_rounded),
              label: Text('Data: ${trainerHistoryFullDate(selectedDate)}'),
            ),
            const SizedBox(height: 12),
            // Kolumna pomiarów w stylu tabeli makro z „Dodaj posiłek"
            // w Liczniku Kalorii: wiersz = nazwa + jednostka | zwarte pole.
            Container(
              padding: const EdgeInsets.fromLTRB(14, 6, 14, 6),
              decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: theme.colorScheme.outlineVariant),
              ),
              child: Column(
                children: [
                  for (var index = 0; index < fields.length; index++) ...[
                    if (index > 0)
                      Divider(
                          height: 1,
                          color: theme.colorScheme.outlineVariant
                              .withValues(alpha: 0.5)),
                    fields[index],
                  ],
                ],
              ),
            ),
            const SizedBox(height: 10),
            TextField(
              key: const Key('measurement_note'),
              controller: note,
              minLines: 2,
              maxLines: 4,
              decoration:
                  const InputDecoration(labelText: 'Notatka do pomiaru'),
            ),
            const SizedBox(height: 12),
            FilledButton.icon(
              key: const Key('save_body_measurement'),
              onPressed: save,
