/// Zdjęcia progresu (przód / bok / tył obok siebie) + wybór docelowego typu
/// sylwetki + start analizy AI. Zdjęcia zapisywane są lokalnie w katalogu
/// aplikacji; do AI trafiają wyłącznie przy analizie (klucz użytkownika).
class ProgressPhotosCard extends StatelessWidget {
  const ProgressPhotosCard({super.key, required this.store});

  final AppStore store;

  Future<void> _pickPhoto(BuildContext context, String view) async {
    final hasPhoto = (store.progressPhotoDrafts[view] ?? '').isNotEmpty;
    final action = await showModalBottomSheet<String>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ListTile(
              leading: const Icon(Icons.photo_camera_outlined),
              title: const Text('Zrób zdjęcie'),
              onTap: () => Navigator.pop(sheetContext, 'camera'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_library_outlined),
              title: const Text('Wybierz z galerii'),
              onTap: () => Navigator.pop(sheetContext, 'gallery'),
            ),
            if (hasPhoto)
              ListTile(
                leading: Icon(Icons.delete_outline_rounded,
                    color: Theme.of(sheetContext).colorScheme.error),
                title: const Text('Usuń zdjęcie'),
                onTap: () => Navigator.pop(sheetContext, 'remove'),
              ),
          ],
        ),
      ),
    );
    if (action == null || !context.mounted) return;
    if (action == 'remove') {
      await store.removeProgressPhoto(view);
      return;
    }
    try {
      final picked = await ImagePicker().pickImage(
        source: action == 'camera' ? ImageSource.camera : ImageSource.gallery,
        maxWidth: 1440,
        imageQuality: 88,
      );
