/// Ilustracja typu sylwetki na modelu ciała (tym samym, co mapa regeneracji):
/// partie akcentowane celem świecą kolorem akcentu.
class SilhouetteGoalIllustration extends StatelessWidget {
  const SilhouetteGoalIllustration(
      {super.key, required this.goal, this.height = 190});

  final SilhouetteGoal goal;
  final double height;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final accent = theme.colorScheme.primary;
    final overrideColors = <BodyMuscle, Color>{
      for (final muscle in goal.highlightPrimary)
        muscle: accent.withValues(alpha: 0.85),
      for (final muscle in goal.highlightSecondary)
        if (!goal.highlightPrimary.contains(muscle))
          muscle: accent.withValues(alpha: 0.4),
    };
    return SizedBox(
      height: height,
      child: BodyMuscleMap(
        side: BodyMuscleSide.front,
        dark: theme.brightness == Brightness.dark,
        recovery: const {},
        overrideColors: overrideColors,
      ),
    );
  }
}

/// Picker docelowego typu sylwetki: duża ilustracja na modelu ciała +
/// lista profesjonalnie nazwanych typów z opisami.
Future<void> showSilhouetteGoalPicker(
    BuildContext context, AppStore store) async {
  var selected = SilhouetteGoal.fromId(store.settings.targetSilhouette) ??
      SilhouetteGoal.values.first;
  final confirmed = await showModalBottomSheet<SilhouetteGoal>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => StatefulBuilder(
      builder: (sheetContext, setSheetState) {
        final theme = Theme.of(sheetContext);
        return Padding(
          padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text('Docelowa sylwetka',
                  style: theme.textTheme.titleLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 10),
              SilhouetteGoalIllustration(goal: selected, height: 170),
              const SizedBox(height: 4),
              Text(
                selected.strategy,
                textAlign: TextAlign.center,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
              const SizedBox(height: 10),
              Flexible(
                child: ListView(
                  shrinkWrap: true,
                  children: [
                    for (final goal in SilhouetteGoal.values)
                      Card(
                        margin: const EdgeInsets.only(bottom: 8),
                        color: goal == selected
                            ? theme.colorScheme.primaryContainer
                                .withValues(alpha: 0.45)
                            : null,
                        child: ListTile(
                          key: Key('silhouette_goal_${goal.id}'),
                          leading: Icon(
                            goal == selected
                                ? Icons.radio_button_checked_rounded
                                : Icons.radio_button_off_rounded,
                            color: goal == selected
                                ? theme.colorScheme.primary
                                : theme.colorScheme.onSurfaceVariant,
                          ),
                          title: Text(goal.label,
                              style: theme.textTheme.titleSmall
                                  ?.copyWith(fontWeight: FontWeight.w800)),
                          subtitle: Text(goal.description),
                          onTap: () => setSheetState(() => selected = goal),
                        ),
                      ),
                  ],
                ),
              ),
              const SizedBox(height: 8),
              FilledButton.icon(
                key: const Key('confirm_silhouette_goal'),
                onPressed: () => Navigator.pop(sheetContext, selected),
                icon: const Icon(Icons.flag_rounded),
                label: const Text('Ustaw jako cel'),
              ),
            ],
          ),
        );
      },
    ),
  );
  if (confirmed == null) return;
  await store
      .updateSettings(store.settings.copyWith(targetSilhouette: confirmed.id));
}

/// Profil celu — JEDNO miejsce edycji centralnego systemu celu (sekcje 13–31):
/// docelowa sylwetka (jak chcę wyglądać), aktualna strategia składu ciała
/// (co teraz robię z tłuszczem i mięśniami), priorytet treningowy (jak
/// trenuję), priorytetowe partie, docelowy zakres BF, tempo zmian oraz
/// synchronizacja z Licznikiem Kalorii.
class BodyGoalProfilePage extends StatefulWidget {
  const BodyGoalProfilePage({super.key});

  @override
  State<BodyGoalProfilePage> createState() => _BodyGoalProfilePageState();
}

class _BodyGoalProfilePageState extends State<BodyGoalProfilePage> {
  DesiredPhysique physique = DesiredPhysique.athletic;
  final Set<PhysiquePriority> priorities = {};
  BodyCompositionStrategy strategy = BodyCompositionStrategy.recomposition;
  TrainingFocus focus = TrainingFocus.strengthHypertrophy;
  final Set<TrainingFocus> secondaryFocuses = {};
  late final TextEditingController bfMin;
  late final TextEditingController bfMax;
  late final TextEditingController targetWeight;
  late final TextEditingController targetWaist;
  late final TextEditingController pace;
  bool autoRecommendations = true;
  bool calorieLocked = false;
  bool autoPublish = true;
  bool _initialized = false;

  @override
  void initState() {
    super.initState();
    bfMin = TextEditingController();
    bfMax = TextEditingController();
    targetWeight = TextEditingController();
    targetWaist = TextEditingController();
    pace = TextEditingController();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_initialized) return;
    _initialized = true;
    final store = AppScope.of(context);
    final profile = store.bodyGoalProfile;
    if (profile == null) return;
    physique = profile.desiredPhysique;
    priorities
      ..clear()
      ..addAll(profile.physiquePriorities);
    strategy = profile.bodyCompositionStrategy;
    focus = profile.trainingFocus;
    secondaryFocuses
      ..clear()
      ..addAll(profile.secondaryTrainingFocuses);
    if (profile.targetBodyFatMinPercent != null) {
      bfMin.text = profile.targetBodyFatMinPercent!.toStringAsFixed(0);
    }
    if (profile.targetBodyFatMaxPercent != null) {
      bfMax.text = profile.targetBodyFatMaxPercent!.toStringAsFixed(0);
    }
    if (profile.targetWeightKg != null) {
      targetWeight.text = profile.targetWeightKg!.toStringAsFixed(1);
    }
    if (profile.targetWaistCm != null) {
      targetWaist.text = profile.targetWaistCm!.toStringAsFixed(0);
    }
    if (profile.paceKgPerWeek != null) {
      pace.text = profile.paceKgPerWeek!.toStringAsFixed(2);
    }
    autoRecommendations = profile.automaticRecommendationsEnabled;
    calorieLocked = profile.calorieTargetLocked;
    autoPublish = profile.autoPublishToCalories;
  }

  @override
  void dispose() {
    bfMin.dispose();
    bfMax.dispose();
    targetWeight.dispose();
    targetWaist.dispose();
    pace.dispose();
    super.dispose();
  }

  double? _parse(TextEditingController controller) {
    final value = double.tryParse(controller.text.replaceAll(',', '.').trim());
    return (value != null && value.isFinite && value > 0) ? value : null;
  }

  Future<void> _save(AppStore store) async {
    var minBf = _parse(bfMin);
    var maxBf = _parse(bfMax);
    if (minBf != null && maxBf != null && minBf > maxBf) {
      final swap = minBf;
      minBf = maxBf;
      maxBf = swap;
    }
    final now = DateTime.now();
    final base = store.bodyGoalProfile ??
        UserBodyGoalProfile(
          desiredPhysique: physique,
          bodyCompositionStrategy: strategy,
          trainingFocus: focus,
          goalSource: GoalSource.manual,
          updatedAt: now,
        );
    final clearBf = minBf == null && maxBf == null;
    final next = base.copyWith(
      desiredPhysique: physique,
      physiquePriorities: priorities.toList(),
      bodyCompositionStrategy: strategy,
      trainingFocus: focus,
      secondaryTrainingFocuses: secondaryFocuses.toList(),
      targetBodyFatMinPercent: minBf,
      targetBodyFatMaxPercent: maxBf,
      clearTargetBodyFat: clearBf,
      targetWeightKg: _parse(targetWeight),
      clearTargetWeight: _parse(targetWeight) == null,
      targetWaistCm: _parse(targetWaist),
      clearTargetWaist: _parse(targetWaist) == null,
      paceKgPerWeek: _parse(pace),
      automaticRecommendationsEnabled: autoRecommendations,
      calorieTargetLocked: calorieLocked,
      autoPublishToCalories: autoPublish,
    );
    await store.updateBodyGoalProfile(next,
        phaseChangeReason: 'Zmiana w profilu celu');
    if (!mounted) return;
    showError(context, 'Zapisano profil celu.');
    Navigator.of(context).maybePop();
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final targets = store.goalNutritionTargets;
    final latestAnalysis = store.latestReliableBodyAnalysis;
    final isFemale = store.settings.sex.trim().toLowerCase().startsWith('k');
    final recommendation = (autoRecommendations && latestAnalysis != null)
        ? recommendBodyCompositionStrategy(
            bodyFatPercent: latestAnalysis.composition.bodyFatPercent,
            bodyFatConfidencePercent: latestAnalysis.confidencePercent,
            isFemale: isFemale,
            trainingDaysPerWeek: store.settings.trainingWeekdays.length,
            ffmi: latestAnalysis.composition.ffmi,
          )
        : null;
    final conflicts = detectGoalConflicts(
      strategy: strategy,
      goalKcal: targets?.goalKcal ?? 0,
      tdeeKcal: targets?.tdeeKcal ?? 0,
      priorities: priorities.toList(),
    );

    Widget sectionCard(
        {required String title,
        required String description,
        required List<Widget> children}) {
      return Card(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(title,
                  style: theme.textTheme.titleMedium
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 4),
              Text(description,
                  style: theme.textTheme.bodySmall?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant, height: 1.35)),
              const SizedBox(height: 12),
              ...children,
            ],
          ),
        ),
      );
    }

    return Scaffold(
      appBar: AppBar(title: const Text('Profil celu')),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 28),
        children: [
          // Wyjaśnienie różnicy trzech pojęć (jedna zasada systemu).
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: theme.colorScheme.primaryContainer.withValues(alpha: 0.3),
              borderRadius: BorderRadius.circular(14),
            ),
            child: Text(
              'Sylwetka to miejsce docelowe, strategia to aktualna droga, a typ '
              'treningu to sposób poruszania się po tej drodze. Te trzy pola są '
              'niezależne — np. możesz chcieć mocno umięśnionej sylwetki, a teraz '
              'redukować tkankę tłuszczową.',
              style: theme.textTheme.bodySmall?.copyWith(height: 1.4),
            ),
          ),
          const SizedBox(height: 12),
          sectionCard(
            title: 'Docelowa sylwetka',
            description:
                'Jak chcesz docelowo wyglądać? To długoterminowy kierunek — '
                'NIE decyduje o deficycie ani nadwyżce kalorycznej.',
            children: [
              DropdownButtonFormField<DesiredPhysique>(
                key: const Key('goal_physique_dropdown'),
                isExpanded: true,
                initialValue: physique,
                decoration: const InputDecoration(labelText: 'Typ sylwetki'),
                items: [
                  for (final value in DesiredPhysique.values)
                    DropdownMenuItem(
                        value: value,
                        child: Text(value.label,
                            maxLines: 1, overflow: TextOverflow.ellipsis)),
                ],
                onChanged: (value) =>
                    setState(() => physique = value ?? physique),
              ),
              const SizedBox(height: 6),
              Text(physique.description,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
              const SizedBox(height: 10),
              Text('Priorytety wizualne',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w800)),
              const SizedBox(height: 6),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [
                  for (final priority in PhysiquePriority.values)
                    FilterChip(
                      key: Key('goal_priority_${priority.id}'),
                      label: Text(priority.label),
                      selected: priorities.contains(priority),
                      onSelected: (selected) => setState(() {
                        if (selected) {
                          priorities.add(priority);
                        } else {
                          priorities.remove(priority);
                        }
                      }),
                    ),
                ],
              ),
            ],
          ),
          const SizedBox(height: 12),
          sectionCard(
            title: 'Aktualna strategia składu ciała',
            description:
                'Co chcesz TERAZ robić z tkanką tłuszczową i masą mięśniową? '
                'To z tej strategii (nie z nazwy sylwetki) liczone są kalorie i makra.',
            children: [
              for (final value in BodyCompositionStrategy.values)
                ListTile(
                  key: Key('goal_strategy_${value.id}'),
                  dense: true,
                  contentPadding: EdgeInsets.zero,
                  leading: Icon(
                    strategy == value
                        ? Icons.radio_button_checked_rounded
                        : Icons.radio_button_off_rounded,
                    color: strategy == value
                        ? theme.colorScheme.primary
                        : theme.colorScheme.onSurfaceVariant,
                  ),
                  title: Text(value.label,
                      style: theme.textTheme.titleSmall
                          ?.copyWith(fontWeight: FontWeight.w800)),
                  subtitle:
