/// Historia analiz sylwetki z deltami względem poprzedniej analizy.
class BodyAnalysisHistoryCard extends StatelessWidget {
  const BodyAnalysisHistoryCard({super.key, required this.analyses});

  final List<BodyAnalysisResult> analyses;

  String _delta(double current, double previous) {
    if (current <= 0 || previous <= 0) return '';
    final diff = current - previous;
    if (diff.abs() < 0.05) return ' (=)';
    return ' (${diff > 0 ? '+' : ''}${diff.toStringAsFixed(1)})';
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final sorted = [...analyses]..sort((a, b) => b.date.compareTo(a.date));
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.timeline_rounded, color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Historia analiz sylwetki',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
                MiniTag(text: '${sorted.length}'),
                if (sorted.length >= 2)
                  IconButton(
                    key: const Key('compare_body_analyses'),
                    tooltip: 'Porównaj analizy (zdjęcia + skład ciała)',
                    onPressed: () => Navigator.of(context).push(
                      MaterialPageRoute<void>(
                          builder: (_) => const BodyAnalysisComparePage()),
                    ),
                    icon: const Icon(Icons.compare_rounded),
                  ),
              ],
            ),
            const SizedBox(height: 10),
            for (var index = 0; index < sorted.length && index < 6; index++)
              Padding(
                padding: const EdgeInsets.only(bottom: 8),
                child: InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: () => Navigator.of(context).push(
                    MaterialPageRoute<void>(
                        builder: (_) => BodyAnalysisDetailsPage(
                            analysisId: sorted[index].id)),
                  ),
                  child: Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: theme.colorScheme.surfaceContainerHighest
                          .withValues(alpha: 0.5),
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Row(
                      children: [
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(trainerHistoryFullDate(sorted[index].date),
                                  style: theme.textTheme.labelLarge
                                      ?.copyWith(fontWeight: FontWeight.w800)),
                              const SizedBox(height: 2),
                              Text(
                                [
                                  if (sorted[index].composition.bodyFatPercent >
                                      0)
                                    'Tłuszcz ${sorted[index].composition.bodyFatPercent.toStringAsFixed(1)}%'
                                        '${index + 1 < sorted.length ? _delta(sorted[index].composition.bodyFatPercent, sorted[index + 1].composition.bodyFatPercent) : ''}',
                                  if (sorted[index].composition.musclePercent >
                                      0)
                                    'mięśnie ${sorted[index].composition.musclePercent.toStringAsFixed(1)}%'
                                        '${index + 1 < sorted.length ? _delta(sorted[index].composition.musclePercent, sorted[index + 1].composition.musclePercent) : ''}',
                                ].join(' · '),
                                style: theme.textTheme.bodySmall?.copyWith(
                                    color: theme.colorScheme.onSurfaceVariant),
                              ),
                            ],
                          ),
                        ),
                        MiniTag(
                          text: sorted[index].source == 'local'
                              ? 'lokalnie'
                              : sorted[index].source == 'gemini'
                                  ? 'Gemini'
                                  : 'OpenAI',
                        ),
                        const SizedBox(width: 4),
                        const Icon(Icons.chevron_right_rounded, size: 20),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}

/// Pełny wynik analizy sylwetki: skład ciała, postawa, symetria, wymiary
/// odczytane ze zdjęć, szczegółowa ocena i plan dojścia do wybranego celu.
class BodyAnalysisDetailsPage extends StatelessWidget {
  const BodyAnalysisDetailsPage({super.key, required this.analysisId});

  final String analysisId;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    BodyAnalysisResult? analysis;
    for (final item in store.bodyAnalyses) {
      if (item.id == analysisId) {
        analysis = item;
        break;
      }
    }
    if (analysis == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Analiza sylwetki')),
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text('Ta analiza nie jest już dostępna.'),
          ),
        ),
      );
    }
    final result = analysis;
    final composition = result.composition;
    final target = result.targetGoal;
    final photos = [
      ('Przód', result.photoFrontPath),
      ('Bok', result.photoSidePath),
      ('Tył', result.photoBackPath),
    ].where((photo) => photo.$2.isNotEmpty).toList();
    // Poprzednia analiza (lista jest posortowana malejąco po dacie).
    BodyAnalysisResult? previousAnalysis;
    for (final item in store.bodyAnalyses) {
      if (item.id != result.id && item.date.isBefore(result.date)) {
        previousAnalysis = item;
        break;
      }
    }
    // Masa ciała z dnia analizy — wszystkie kilogramy liczone z tej wartości.
    final weightKg = result.bodyWeightKgAtAnalysis > 0
        ? result.bodyWeightKgAtAnalysis
        : store.weightForAnalysis(result);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Analiza sylwetki'),
        actions: [
          IconButton(
            tooltip: 'Usuń analizę',
            onPressed: () async {
              final confirmed = await showDialog<bool>(
                context: context,
                builder: (dialogContext) => AlertDialog(
                  title: const Text('Usunąć analizę?'),
                  content:
                      const Text('Wynik analizy zostanie usunięty z historii.'),
                  actions: [
                    TextButton(
                        onPressed: () => Navigator.pop(dialogContext, false),
                        child: const Text('Anuluj')),
                    FilledButton(
                        onPressed: () => Navigator.pop(dialogContext, true),
                        child: const Text('Usuń')),
                  ],
                ),
              );
              if (confirmed == true && context.mounted) {
                await store.deleteBodyAnalysis(result.id);
                if (context.mounted) Navigator.of(context).pop();
              }
            },
            icon: const Icon(Icons.delete_outline_rounded),
          ),
        ],
      ),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 8, 16, 28),
        children: [
          // --- Nagłówek: data, źródło, pewność, klasyfikacja sylwetki. ---
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    '${weekdayName(result.date.weekday)} · ${trainerHistoryFullDate(result.date)}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                  const SizedBox(height: 6),
                  if (result.currentSilhouette.isNotEmpty)
                    Text(result.currentSilhouette,
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900)),
                  const SizedBox(height: 8),
                  Wrap(
                    spacing: 6,
                    runSpacing: 6,
                    children: [
                      MiniTag(
                        text: result.source == 'local'
                            ? 'Szacunek lokalny'
                            : result.source == 'gemini'
                                ? 'AI: Gemini'
                                : 'AI: OpenAI',
                      ),
                      if (result.modelVersion.isNotEmpty)
                        MiniTag(text: result.modelVersion),
                      if (result.confidencePercent > 0)
                        MiniTag(
                          text: 'Pewność ${result.confidencePercent.round()}% '
                              '(${confidenceLevelFor(result.confidencePercent).label})',
                        ),
                      if (result.photoCount > 0)
                        MiniTag(text: '${result.photoCount} zdjęć'),
                      if (target != null) MiniTag(text: 'Cel: ${target.label}'),
                      if (result.schemaVersion < 2)
                        const MiniTag(text: 'starsza wersja analizy'),
                    ],
                  ),
                ],
              ),
            ),
          ),
          // --- Walidacja biologiczna: wynik o niskiej wiarygodności. ---
          if (result.lowReliability || result.validationIssues.isNotEmpty) ...[
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: const Color(0xFFE05252).withValues(alpha: 0.10),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                    color: const Color(0xFFE05252).withValues(alpha: 0.4)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      const Icon(Icons.warning_amber_rounded,
                          size: 18, color: Color(0xFFE05252)),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          result.lowReliability
                              ? 'Niska wiarygodność wyniku'
                              : 'Uwagi walidacji',
                          style: theme.textTheme.titleSmall?.copyWith(
                              fontWeight: FontWeight.w900,
                              color: const Color(0xFFE05252)),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  for (final issue in result.validationIssues)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Text('• $issue',
                          style: theme.textTheme.bodySmall
                              ?.copyWith(height: 1.35)),
                    ),
                  Text(
                    'Nie traktuj tych wartości jako pewnego pomiaru. Możesz ponowić analizę '
                    '(najlepiej w lepszych warunkach) albo ręcznie poprawić dane w pomiarach.',
                    style: theme.textTheme.bodySmall?.copyWith(
                        color: theme.colorScheme.onSurfaceVariant,
                        height: 1.35),
                  ),
                ],
              ),
            ),
          ],
          if (photos.isNotEmpty) ...[
            const SizedBox(height: 12),
            Row(
              children: [
                for (var index = 0; index < photos.length; index++) ...[
                  if (index > 0) const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      children: [
                        Text(photos[index].$1,
                            style: theme.textTheme.labelSmall
                                ?.copyWith(fontWeight: FontWeight.w800)),
                        const SizedBox(height: 4),
                        ClipRRect(
                          borderRadius: BorderRadius.circular(14),
                          child: AspectRatio(
                            aspectRatio: 3 / 4,
                            child: Image.file(
                              File(photos[index].$2),
                              fit: BoxFit.cover,
                              errorBuilder: (_, __, ___) => ColoredBox(
                                color:
                                    theme.colorScheme.surfaceContainerHighest,
                                child: Icon(Icons.broken_image_outlined,
                                    color: theme.colorScheme.onSurfaceVariant),
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ],
            ),
          ],
          // --- Sekcja 1: główny skład ciała (rozłączny: tłuszcz + FFM). ---
          if (composition.hasData) ...[
            const SizedBox(height: 12),
            _MainCompositionCard(result: result, weightKg: weightKg),
            // --- Sekcja 2: parametry FFM (nakładają się — bez sumowania). ---
            if (composition.musclePercent > 0 ||
                composition.waterPercent > 0 ||
                composition.bonePercent > 0) ...[
              const SizedBox(height: 12),
              _FfmParametersCard(result: result, weightKg: weightKg),
            ],
            // --- Sekcja 3: wskaźniki pomocnicze (BMI/FFMI/talia/WHtR). ---
            const SizedBox(height: 12),
            _AuxIndicatorsCard(
              result: result,
              weightKg: weightKg,
              heightCm: store.settings.heightCm,
            ),
          ],
          // --- Sekcja 4: analiza wizualna (ostrożny język, bez diagnoz). ---
          if (result.postureNotes.isNotEmpty ||
              result.symmetryNotes.isNotEmpty ||
              result.strengths.isNotEmpty ||
              result.weaknesses.isNotEmpty ||
              result.possibleImbalances.isNotEmpty ||
              result.watchAreas.isNotEmpty ||
              result.developmentPriorities.isNotEmpty) ...[
            const SizedBox(height: 12),
            _VisualAnalysisCard(result: result),
          ],
          // --- Wymiary odczytane z analizy. ---
          if (result.estimatedMeasurementsCm.isNotEmpty) ...[
            const SizedBox(height: 12),
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text('Wymiary z analizy (cm)',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 4),
                    Text(
                      'Obwody oszacowane ze zdjęć — możesz zapisać je jako pomiar zamiast mierzyć ręcznie.',
                      style: theme.textTheme.bodySmall
                          ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                    ),
                    const SizedBox(height: 10),
                    Wrap(
                      spacing: 8,
                      runSpacing: 8,
                      children: [
                        for (final entry in kBodyPartLabels.entries)
                          if ((result.estimatedMeasurementsCm[entry.key] ?? 0) >
                              0)
                            MiniTag(
                                text:
                                    '${entry.value}: ${result.estimatedMeasurementsCm[entry.key]!.toStringAsFixed(1)} cm'),
                      ],
                    ),
                    const SizedBox(height: 12),
                    OutlinedButton.icon(
                      key: const Key('save_analysis_as_measurement'),
                      onPressed: () async {
                        final saved =
                            await store.saveAnalysisAsMeasurement(result);
                        if (context.mounted) {
                          showError(
                              context,
                              saved == null
                                  ? 'Analiza nie zawiera wymiarów do zapisania.'
                                  : 'Zapisano wymiary jako pomiar sylwetki.');
                        }
                      },
                      icon: const Icon(Icons.straighten_rounded),
                      label: const Text('Zapisz jako pomiar sylwetki'),
                    ),
                  ],
                ),
              ),
            ),
          ],
          // --- Szczegółowa ocena. ---
          if (result.summary.isNotEmpty) ...[
            const SizedBox(height: 12),
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Szczegółowa ocena',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900)),
                    const SizedBox(height: 8),
                    Text(result.summary,
                        style:
                            theme.textTheme.bodyMedium?.copyWith(height: 1.45)),
                  ],
                ),
              ),
            ),
          ],
          // --- Sekcja 5: trend względem poprzedniej analizy. ---
          if (previousAnalysis != null) ...[
            const SizedBox(height: 12),
            _AnalysisTrendCard(
              current: result,
              previous: previousAnalysis,
              currentWeightKg: weightKg,
              previousWeightKg: previousAnalysis.bodyWeightKgAtAnalysis > 0
                  ? previousAnalysis.bodyWeightKgAtAnalysis
                  : store.weightForAnalysis(previousAnalysis),
            ),
          ],
          // --- Sekcja 6: cel sylwetkowy (profil celu + plan dojścia). ---
          if (target != null ||
              store.bodyGoalProfile != null ||
              result.trainingRecommendations.isNotEmpty ||
              result.nutritionRecommendations.isNotEmpty) ...[
            const SizedBox(height: 12),
            Card(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      store.bodyGoalProfile != null
                          ? 'Droga do celu: ${store.bodyGoalProfile!.desiredPhysique.label}'
                          : target == null
                              ? 'Zalecenia'
                              : 'Droga do celu: ${target.label}',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900),
                    ),
                    if (store.bodyGoalProfile != null) ...[
                      const SizedBox(height: 10),
                      _GoalProfileSummary(
                          store: store,
                          analysisWeightKg: weightKg,
                          analysis: result),
                    ],
                    if (target != null) ...[
                      const SizedBox(height: 10),
                      SilhouetteGoalIllustration(goal: target, height: 170),
                      const SizedBox(height: 6),
                      Text(
                        target.strategy,
                        textAlign: TextAlign.center,
                        style: theme.textTheme.bodySmall?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant),
                      ),
                    ],
                    if (result.trainingRecommendations.isNotEmpty) ...[
                      const SizedBox(height: 12),
                      Text('Trening',
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 6),
                      for (final item in result.trainingRecommendations)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 6),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Icon(Icons.fitness_center_rounded,
                                  size: 15, color: theme.colorScheme.primary),
                              const SizedBox(width: 8),
                              Expanded(
                                  child: Text(item,
                                      style: theme.textTheme.bodyMedium
                                          ?.copyWith(height: 1.35))),
                            ],
                          ),
                        ),
                    ],
                    if (result.nutritionRecommendations.isNotEmpty) ...[
                      const SizedBox(height: 8),
                      Text('Odżywianie',
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      const SizedBox(height: 6),
                      for (final item in result.nutritionRecommendations)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 6),
                          child: Row(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Icon(Icons.restaurant_rounded,
                                  size: 15, color: theme.colorScheme.primary),
                              const SizedBox(width: 8),
                              Expanded(
                                  child: Text(item,
                                      style: theme.textTheme.bodyMedium
                                          ?.copyWith(height: 1.35))),
                            ],
                          ),
                        ),
                    ],
                  ],
                ),
              ),
            ),
          ],
          // --- Uwagi i stopka. ---
          if (result.risks.isNotEmpty) ...[
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: const Color(0xFFE08600).withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(
                    color: const Color(0xFFE08600).withValues(alpha: 0.4)),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Uwagi',
                      style: theme.textTheme.titleSmall?.copyWith(
                          fontWeight: FontWeight.w900,
                          color: const Color(0xFFE08600))),
                  const SizedBox(height: 6),
                  for (final risk in result.risks)
                    Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Text('• $risk',
                          style: theme.textTheme.bodySmall
                              ?.copyWith(height: 1.35)),
                    ),
                ],
              ),
            ),
          ],
          const SizedBox(height: 12),
          if (result.contextUsed.isNotEmpty) ...[
            Text('Dane uwzględnione w analizie',
                style: theme.textTheme.labelLarge
                    ?.copyWith(fontWeight: FontWeight.w800)),
            const SizedBox(height: 6),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                for (final item in result.contextUsed) MiniTag(text: item)
              ],
            ),
            const SizedBox(height: 12),
          ],
          Text(
            '$kPhotoAnalysisDisclaimer Wynik jest oszacowaniem wizualno-matematycznym '
            'i nie zastępuje porady lekarza.',
            style: theme.textTheme.bodySmall?.copyWith(
                color: theme.colorScheme.onSurfaceVariant,
                fontStyle: FontStyle.italic),
          ),
        ],
      ),
    );
  }
}

/// Mała plakietka źródła wartości (pomiar / obliczenie / szacunek AI / sync).
class _ValueSourceTag extends StatelessWidget {
  const _ValueSourceTag({required this.source});

  final MeasurementSource source;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final icon = switch (source) {
      MeasurementSource.userMeasurement => Icons.straighten_rounded,
      MeasurementSource.deviceMeasurement => Icons.monitor_weight_outlined,
      MeasurementSource.computed => Icons.calculate_outlined,
      MeasurementSource.aiEstimate => Icons.auto_awesome_rounded,
      MeasurementSource.synced => Icons.sync_rounded,
    };
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        Icon(icon, size: 12, color: theme.colorScheme.onSurfaceVariant),
        const SizedBox(width: 3),
        Flexible(
          child: Text(
            source.label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.labelSmall?.copyWith(
              color: theme.colorScheme.onSurfaceVariant,
              fontSize: 10,
            ),
          ),
        ),
      ],
    );
  }
}

/// Sekcja 1 — główny skład ciała: ROZŁĄCZNY podział masa = tłuszcz + FFM.
/// Procenty sumują się dokładnie do 100, kilogramy do masy ciała.
class _MainCompositionCard extends StatelessWidget {
  const _MainCompositionCard({required this.result, required this.weightKg});

  final BodyAnalysisResult result;
  final double weightKg;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final composition = result.composition;
    final breakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: weightKg,
      bodyFatPercent: composition.bodyFatPercent,
    );
    final bfSource = composition.method == 'ai_photo'
        ? MeasurementSource.aiEstimate
        : MeasurementSource.computed;
    var rangeMin = result.bodyFatRangeMinPercent;
    var rangeMax = result.bodyFatRangeMaxPercent;
    if ((rangeMin <= 0 || rangeMax <= 0) && composition.bodyFatPercent > 0) {
      final range = bodyFatRangeForConfidence(
        bodyFatPercent: composition.bodyFatPercent,
        confidencePercent: result.confidencePercent,
      );
      rangeMin = range.min;
      rangeMax = range.max;
    }

    Widget metricRow({
      required String label,
      required String value,
      required MeasurementSource source,
      String helper = '',
    }) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(
              flex: 5,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(label,
                      style: theme.textTheme.bodySmall
                          ?.copyWith(fontWeight: FontWeight.w800)),
                  _ValueSourceTag(source: source),
                ],
              ),
            ),
            Expanded(
              flex: 5,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  Text(value,
                      textAlign: TextAlign.right,
                      style: theme.textTheme.bodyMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                  if (helper.isNotEmpty)
                    Text(
                      helper,
                      textAlign: TextAlign.right,
                      style: theme.textTheme.labelSmall
                          ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                    ),
                ],
              ),
            ),
          ],
        ),
      );
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('Skład ciała (szacunek)',
                style: theme.textTheme.titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 4),
            Text(
              'Główny podział jest rozłączny: masa tłuszczowa + beztłuszczowa masa ciała (FFM) = masa ciała.',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
            const SizedBox(height: 12),
            if (breakdown != null) ...[
              _CompositionBarRow(
                  label: 'Tkanka tłuszczowa',
                  percent: breakdown.bodyFatPercent,
                  color: const Color(0xFFE08600)),
              _CompositionBarRow(
                  label: 'FFM (beztłuszczowa)',
                  percent: breakdown.fatFreeMassPercent,
                  color: theme.colorScheme.primary),
              const SizedBox(height: 4),
              metricRow(
                label: 'Masa ciała',
                value: '${breakdown.bodyWeightKg.toStringAsFixed(1)} kg',
                source: MeasurementSource.userMeasurement,
              ),
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              metricRow(
                label: 'Tkanka tłuszczowa',
                value:
                    '${breakdown.bodyFatPercent.toStringAsFixed(1)}% · ${breakdown.fatMassKg.toStringAsFixed(1)} kg',
                helper: rangeMax > 0
                    ? 'prawdopodobny zakres ${rangeMin.toStringAsFixed(0)}–${rangeMax.toStringAsFixed(0)}%'
                    : '',
                source: bfSource,
              ),
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              metricRow(
                label: 'Beztłuszczowa masa ciała (FFM)',
                value:
                    '${breakdown.fatFreeMassPercent.toStringAsFixed(1)}% · ${breakdown.fatFreeMassKg.toStringAsFixed(1)} kg',
                source: MeasurementSource.computed,
              ),
              const SizedBox(height: 8),
              Text(
                'Suma: ${breakdown.fatMassKg.toStringAsFixed(1)} kg + ${breakdown.fatFreeMassKg.toStringAsFixed(1)} kg '
                '= ${breakdown.bodyWeightKg.toStringAsFixed(1)} kg (100%).',
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
            ] else
              Text(
                'Brak kompletu danych (masa ciała + szacunek tkanki tłuszczowej), '
                'żeby policzyć rozłączny podział masy.',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
            if (result.confidencePercent > 0) ...[
              const SizedBox(height: 6),
              Text(
                'Pewność analizy: ${result.confidencePercent.round()}% '
                '(${confidenceLevelFor(result.confidencePercent).label}).',
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

/// Sekcja 2 — parametry FFM: mięśnie, woda i parametr kostny CZĘŚCIOWO SIĘ
/// POKRYWAJĄ. Bez sumy i bez wspólnego wykresu sugerującego rozłączność.
class _FfmParametersCard extends StatelessWidget {
  const _FfmParametersCard({required this.result, required this.weightKg});

  final BodyAnalysisResult result;
  final double weightKg;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final composition = result.composition;
    final source = composition.method == 'ai_photo'
        ? MeasurementSource.aiEstimate
        : MeasurementSource.computed;
    final boneLabel = boneParameterLabel(bonePercent: composition.bonePercent);
    final bonePlausible = boneParameterPlausible(composition.bonePercent);
    // FFM w % masy — punkt odniesienia dla paska mięśni (mięśnie są CZĘŚCIĄ
    // FFM, więc ich pasek pokazuje udział w FFM, nie w całym ciele).
    final ffmPercent =
        composition.bodyFatPercent > 0 ? 100 - composition.bodyFatPercent : 0.0;

    Widget row(
      String label,
      double percent, {
      bool warning = false,
      double? barFraction,
      Color? barColor,
      String barHint = '',
    }) {
      final kg = weightKg > 0 ? weightKg * percent / 100 : 0.0;
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                if (warning) ...[
                  const Icon(Icons.warning_amber_rounded,
                      size: 14, color: Color(0xFFE08600)),
                  const SizedBox(width: 4),
                ],
                Expanded(
                  flex: 6,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(label,
                          style: theme.textTheme.bodySmall
                              ?.copyWith(fontWeight: FontWeight.w800)),
                      _ValueSourceTag(source: source),
                    ],
                  ),
                ),
                Expanded(
                  flex: 4,
                  child: Text(
                    kg > 0
                        ? '≈ ${percent.toStringAsFixed(1)}% · ${kg.toStringAsFixed(1)} kg'
                        : '≈ ${percent.toStringAsFixed(1)}%',
                    textAlign: TextAlign.right,
                    style: theme.textTheme.bodyMedium
                        ?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
              ],
            ),
            // Wizualizacja wartości: pasek położenia w typowym zakresie
            // (osobny dla każdego wiersza — NIE sumują się do 100%).
            if (barFraction != null) ...[
              const SizedBox(height: 5),
              ClipRRect(
                borderRadius: BorderRadius.circular(6),
                child: LinearProgressIndicator(
                  value: barFraction.clamp(0.0, 1.0),
                  minHeight: 6,
                  backgroundColor: theme.colorScheme.surfaceContainerHighest,
                  valueColor: AlwaysStoppedAnimation<Color>(
                    barColor ?? theme.colorScheme.primary,
                  ),
                ),
              ),
              if (barHint.isNotEmpty) ...[
                const SizedBox(height: 2),
                Text(
                  barHint,
                  style: theme.textTheme.labelSmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                    fontSize: 10,
                  ),
                ),
              ],
            ],
          ],
        ),
      );
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('Parametry beztłuszczowej masy ciała',
                style: theme.textTheme.titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 10),
            if (composition.musclePercent > 0)
              row(
                'Szacowana masa mięśni szkieletowych',
                composition.musclePercent,
                barFraction: ffmPercent > 0
                    ? composition.musclePercent / ffmPercent
                    : null,
                barColor: theme.colorScheme.primary,
                barHint: ffmPercent > 0
                    ? 'udział w FFM: ${(composition.musclePercent / ffmPercent * 100).round()}%'
                    : '',
              ),
            if (composition.waterPercent > 0) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row(
                'Całkowita woda organizmu',
                composition.waterPercent,
                barFraction: (composition.waterPercent - 30) / (75 - 30),
                barColor: const Color(0xFF58A6FF),
                barHint: 'typowy zakres 30–75% masy ciała',
              ),
            ],
            if (composition.bonePercent > 0) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row(
                boneLabel,
                composition.bonePercent,
                warning: !bonePlausible,
                barFraction: composition.bonePercent / 16,
                barColor: bonePlausible
                    ? theme.colorScheme.onSurfaceVariant
                    : const Color(0xFFE08600),
                barHint:
                    'szacunek; powyżej ~16% masy uznajemy za niewiarygodny',
              ),
            ],
            const SizedBox(height: 10),
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: theme.colorScheme.surfaceContainerHighest
                    .withValues(alpha: 0.5),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Icon(Icons.info_outline_rounded,
                      size: 16, color: theme.colorScheme.primary),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      kFfmOverlapExplanation,
                      style: theme.textTheme.bodySmall?.copyWith(height: 1.35),
                    ),
                  ),
                ],
              ),
            ),
            if (!bonePlausible && composition.bonePercent > 0) ...[
              const SizedBox(height: 6),
              Text(
                'Parametr kostny wygląda biologicznie niewiarygodnie — traktuj go '
                'jako niepewny szacunek albo pomiń.',
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: const Color(0xFFE08600)),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

/// Sekcja 3 — wskaźniki pomocnicze: BMI (z zastrzeżeniem), FFMI liczony
/// z FFM i wzrostu, talia, stosunek talii do wzrostu, źródła danych.
class _AuxIndicatorsCard extends StatelessWidget {
  const _AuxIndicatorsCard({
    required this.result,
    required this.weightKg,
    required this.heightCm,
  });

  final BodyAnalysisResult result;
  final double weightKg;
  final double heightCm;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final composition = result.composition;
    final breakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: weightKg,
      bodyFatPercent: composition.bodyFatPercent,
    );
    // FFMI ZAWSZE z FFM i wzrostu (nie z masy mięśni szkieletowych).
    final ffmi = breakdown == null
        ? (composition.ffmi > 0 ? composition.ffmi : null)
        : computeFfmi(
                fatFreeMassKg: breakdown.fatFreeMassKg, heightCm: heightCm) ??
            (composition.ffmi > 0 ? composition.ffmi : null);
    final waist = result.waistCmAtAnalysis;
    final whtr = (waist > 0 && heightCm > 0) ? waist / heightCm : 0.0;
    final confidence = confidenceLevelFor(result.confidencePercent);

    Widget row(
      String label,
      String value,
      MeasurementSource source, {
      String note = '',
      double? barFraction,
      Color? barColor,
      String barHint = '',
    }) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Expanded(
                  flex: 6,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(label,
                          style: theme.textTheme.bodySmall
                              ?.copyWith(fontWeight: FontWeight.w800)),
                      _ValueSourceTag(source: source),
                    ],
                  ),
                ),
                Expanded(
                  flex: 4,
                  child: Text(value,
                      textAlign: TextAlign.right,
                      style: theme.textTheme.bodyMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            // Wizualizacja: położenie wartości na orientacyjnej skali
            // (pasek nie jest diagnozą — skala opisana w podpowiedzi).
            if (barFraction != null) ...[
              const SizedBox(height: 5),
              ClipRRect(
                borderRadius: BorderRadius.circular(6),
                child: LinearProgressIndicator(
                  value: barFraction.clamp(0.0, 1.0),
                  minHeight: 6,
                  backgroundColor: theme.colorScheme.surfaceContainerHighest,
                  valueColor: AlwaysStoppedAnimation<Color>(
                    barColor ?? theme.colorScheme.primary,
                  ),
                ),
              ),
              if (barHint.isNotEmpty) ...[
                const SizedBox(height: 2),
                Text(
                  barHint,
                  style: theme.textTheme.labelSmall?.copyWith(
                    color: theme.colorScheme.onSurfaceVariant,
                    fontSize: 10,
                  ),
                ),
              ],
            ],
            if (note.isNotEmpty)
              Text(note,
                  style: theme.textTheme.labelSmall?.copyWith(
                      color: theme.colorScheme.onSurfaceVariant, height: 1.3)),
          ],
        ),
      );
    }

    // Kolor paska wg orientacyjnych stref (bez języka diagnozy).
    Color zoneColor(double value, double goodMax, double warnMax) {
      if (value <= goodMax) return theme.colorScheme.primary;
      if (value <= warnMax) return const Color(0xFFE08600);
      return const Color(0xFFE05252);
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('Wskaźniki pomocnicze',
                style: theme.textTheme.titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 8),
            if (composition.bmi > 0)
              row(
                'BMI',
                composition.bmi.toStringAsFixed(1),
                MeasurementSource.computed,
                note: kBmiCaveat,
                barFraction: (composition.bmi - 15) / (40 - 15),
                barColor: zoneColor(composition.bmi, 25, 30),
                barHint: 'skala 15–40; orientacyjnie 18,5–25 to środek zakresu',
              ),
            if (ffmi != null) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row(
                'FFMI',
                ffmi.toStringAsFixed(1),
                MeasurementSource.computed,
                note:
                    'Wskaźnik umięśnienia liczony z FFM i wzrostu; pewność zależna '
                    'od pewności szacunku tkanki tłuszczowej (${confidence.label}).',
                barFraction: (ffmi - 14) / (26 - 14),
                barColor: theme.colorScheme.primary,
                barHint: 'skala 14–26; im wyżej, tym większe umięśnienie',
              ),
            ],
            if (waist > 0) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row('Obwód talii', '${waist.toStringAsFixed(1)} cm',
                  MeasurementSource.userMeasurement),
            ],
            if (whtr > 0) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row(
                'Stosunek talii do wzrostu (WHtR)',
                whtr.toStringAsFixed(2),
                MeasurementSource.computed,
                barFraction: (whtr - 0.35) / (0.65 - 0.35),
                barColor: zoneColor(whtr, 0.5, 0.57),
                barHint:
                    'skala 0,35–0,65; wartości poniżej ~0,5 są zwykle korzystne',
              ),
            ],
            if (composition.visceralFatLevel > 0) ...[
              Divider(
                  height: 1,
                  color:
                      theme.colorScheme.outlineVariant.withValues(alpha: 0.5)),
              row(
                'Szacowane ryzyko związane z tłuszczem trzewnym',
                '${composition.visceralFatLevel.toStringAsFixed(0)}/20',
                MeasurementSource.aiEstimate,
                note:
                    'To NIE jest pomiar — wartość wyliczona ze zdjęcia/wzorów. '
                    'Bardziej wiarygodne są obwód talii i stosunek talii do wzrostu.',
                barFraction: composition.visceralFatLevel / 20,
                barColor: zoneColor(composition.visceralFatLevel, 9, 13),
                barHint: 'skala 1–20 (przybliżenie, nie pomiar)',
              ),
            ],
          ],
        ),
      ),
    );
  }
}

