/// Sekcja 5 — trend: porównanie z poprzednią analizą (masa, BF w p.p., FFM,
/// talia). Małe zmiany w granicach błędu pomiaru nie są alarmowane.
class _AnalysisTrendCard extends StatelessWidget {
  const _AnalysisTrendCard({
    required this.current,
    required this.previous,
    required this.currentWeightKg,
    required this.previousWeightKg,
  });

  final BodyAnalysisResult current;
  final BodyAnalysisResult previous;
  final double currentWeightKg;
  final double previousWeightKg;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final currentBreakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: currentWeightKg,
      bodyFatPercent: current.composition.bodyFatPercent,
    );
    final previousBreakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: previousWeightKg,
      bodyFatPercent: previous.composition.bodyFatPercent,
    );
    final bfDelta = (current.composition.bodyFatPercent > 0 &&
            previous.composition.bodyFatPercent > 0)
        ? current.composition.bodyFatPercent -
            previous.composition.bodyFatPercent
        : null;
    final weightDelta = (currentWeightKg > 0 && previousWeightKg > 0)
        ? currentWeightKg - previousWeightKg
        : null;
    final ffmDelta = (currentBreakdown != null && previousBreakdown != null)
        ? currentBreakdown.fatFreeMassKg - previousBreakdown.fatFreeMassKg
        : null;
    final waistDelta =
        (current.waistCmAtAnalysis > 0 && previous.waistCmAtAnalysis > 0)
            ? current.waistCmAtAnalysis - previous.waistCmAtAnalysis
            : null;
    final withinMargin = bfDelta != null &&
        bodyFatChangeWithinErrorMargin(
          deltaPercentPoints: bfDelta,
          olderConfidencePercent: previous.confidencePercent,
          newerConfidencePercent: current.confidencePercent,
        );

    String signed(double value, String unit) =>
        '${value > 0 ? '+' : ''}${value.toStringAsFixed(1)} $unit';

    // Wiersz delty z wizualizacją kierunku: strzałka + kolor mówią, czy
    // zmiana idzie w korzystną stronę ([goodWhenDown] = spadek jest dobry,
    // null = kierunek neutralny, np. masa ciała zależy od strategii).
    Widget deltaRow(String label, String value,
        {double? delta, bool? goodWhenDown}) {
      IconData icon = Icons.remove_rounded;
      Color color = theme.colorScheme.onSurfaceVariant;
      if (delta != null && delta.abs() >= 0.05) {
        icon = delta > 0
            ? Icons.arrow_upward_rounded
            : Icons.arrow_downward_rounded;
        if (goodWhenDown != null) {
          final good = goodWhenDown ? delta < 0 : delta > 0;
          color = good ? theme.colorScheme.primary : const Color(0xFFE08600);
        }
      }
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          children: [
            Icon(icon, size: 15, color: color),
            const SizedBox(width: 6),
            Expanded(
                child: Text(label,
                    style: theme.textTheme.bodySmall
                        ?.copyWith(fontWeight: FontWeight.w800))),
            Text(value,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(fontWeight: FontWeight.w900, color: color)),
          ],
        ),
      );
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('Trend',
                style: theme.textTheme.titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 4),
            Text(
              'Porównanie z analizą z ${trainerHistoryFullDate(previous.date)}.',
              style: theme.textTheme.bodySmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
            const SizedBox(height: 8),
            if (weightDelta != null)
              deltaRow('Masa ciała', signed(weightDelta, 'kg'),
                  delta: weightDelta),
            if (bfDelta != null)
              deltaRow('Tkanka tłuszczowa', signed(bfDelta, 'p.p.'),
                  delta: bfDelta, goodWhenDown: true),
            if (ffmDelta != null)
              deltaRow('FFM', signed(ffmDelta, 'kg'),
                  delta: ffmDelta, goodWhenDown: false),
            if (waistDelta != null)
              deltaRow('Obwód talii', signed(waistDelta, 'cm'),
                  delta: waistDelta, goodWhenDown: true),
            if (withinMargin) ...[
              const SizedBox(height: 8),
              Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: theme.colorScheme.surfaceContainerHighest
                      .withValues(alpha: 0.5),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Text(
                  'Zmiana tkanki tłuszczowej (${signed(bfDelta, 'p.p.')}) mieści się w możliwym '
                  'marginesie błędu pomiaru. Kontynuuj obserwację trendu.',
                  style: theme.textTheme.bodySmall?.copyWith(height: 1.35),
                ),
              ),
            ],
            const SizedBox(height: 8),
            Text(
              'Wykresy masy, talii i obwodów znajdziesz na stronie „Pomiary sylwetki".',
              style: theme.textTheme.labelSmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),
          ],
        ),
      ),
    );
  }
}

/// Sekcja 6 — podsumowanie centralnego profilu celu na ekranie analizy:
/// sylwetka, strategia, priorytet treningowy, priorytetowe partie, docelowy
/// zakres BF, aktualny etap i status synchronizacji z Kaloriami.
class _GoalProfileSummary extends StatelessWidget {
  const _GoalProfileSummary({
    required this.store,
    required this.analysisWeightKg,
    required this.analysis,
  });

  final AppStore store;
  final double analysisWeightKg;
  final BodyAnalysisResult analysis;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final profile = store.bodyGoalProfile;
    if (profile == null) return const SizedBox.shrink();
    final activePhase = store.goalPhases.isEmpty ? null : store.goalPhases.last;
    final breakdown = computeBodyCompositionBreakdown(
      bodyWeightKg: analysisWeightKg,
      bodyFatPercent: analysis.composition.bodyFatPercent,
    );
    ({double min, double max})? weightRange;
    if (breakdown != null &&
        profile.targetBodyFatMinPercent != null &&
        profile.targetBodyFatMaxPercent != null) {
      weightRange = weightRangeForTargetBodyFat(
        fatFreeMassKg: breakdown.fatFreeMassKg,
        targetBodyFatMinPercent: profile.targetBodyFatMinPercent!,
        targetBodyFatMaxPercent: profile.targetBodyFatMaxPercent!,
      );
    }

    Widget row(String label, String value) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
              width: 150,
              child: Text(label,
                  style: theme.textTheme.labelSmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            ),
            Expanded(
              child: Text(value,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(fontWeight: FontWeight.w800)),
            ),
          ],
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        row('Docelowa sylwetka', profile.desiredPhysique.label),
        row('Aktualna strategia', profile.bodyCompositionStrategy.label),
        row('Priorytet treningowy', profile.trainingFocus.label),
        if (profile.secondaryTrainingFocuses.isNotEmpty)
          row('Dodatkowe aktywności',
              profile.secondaryTrainingFocuses.map((f) => f.label).join(', ')),
        if (profile.physiquePriorities.isNotEmpty)
          row('Priorytetowe partie',
              profile.physiquePriorities.map((p) => p.label).join(', ')),
        if (profile.targetBodyFatMinPercent != null &&
            profile.targetBodyFatMaxPercent != null)
          row(
            'Docelowy zakres BF',
            '${profile.targetBodyFatMinPercent!.toStringAsFixed(0)}–${profile.targetBodyFatMaxPercent!.toStringAsFixed(0)}%',
          ),
        if (activePhase != null)
          row('Bieżący etap',
              '${activePhase.strategy.label} (od ${trainerHistoryFullDate(activePhase.startDate)})'),
        row(
          'Synchronizacja z Kaloriami',
          profile.autoPublishToCalories
              ? (store.lastDailyAdjustmentsPublishAt != null
                  ? 'aktywna · rewizja ${profile.revision} · ${trainerHistoryFullDate(store.lastDailyAdjustmentsPublishAt!)}'
                  : 'aktywna · rewizja ${profile.revision}')
              : 'wyłączona',
        ),
        if (weightRange != null) ...[
          const SizedBox(height: 8),
          Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(
              color: theme.colorScheme.surfaceContainerHighest
                  .withValues(alpha: 0.5),
              borderRadius: BorderRadius.circular(12),
            ),
            child: Text(
              'Przy zachowaniu obecnej FFM masa ciała odpowiadająca wybranemu zakresowi BF '
              'może wynosić około ${weightRange.min.toStringAsFixed(0)}–${weightRange.max.toStringAsFixed(0)} kg. '
              'To jedynie szacunek zależny od dokładności analizy i zmian masy mięśniowej.',
              style: theme.textTheme.bodySmall?.copyWith(height: 1.35),
            ),
          ),
        ],
        const SizedBox(height: 8),
        OutlinedButton.icon(
          key: const Key('open_goal_profile_from_analysis'),
          onPressed: () => Navigator.of(context).push(
            MaterialPageRoute<void>(
                builder: (_) => const BodyGoalProfilePage()),
          ),
          icon: const Icon(Icons.flag_rounded, size: 18),
          label: const Text('Ustawienia celu'),
        ),
      ],
    );
  }
}

/// Porównanie dwóch analiz sylwetki: zdjęcia obok siebie, delty składu
/// ciała (% i kg) oraz wykresy historii tłuszczu i mięśni w czasie.
class BodyAnalysisComparePage extends StatefulWidget {
  const BodyAnalysisComparePage({super.key});

  @override
  State<BodyAnalysisComparePage> createState() =>
      _BodyAnalysisComparePageState();
}

class _BodyAnalysisComparePageState extends State<BodyAnalysisComparePage> {
  String? _olderId;
  String? _newerId;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final analyses = [...store.bodyAnalyses]
      ..sort((a, b) => b.date.compareTo(a.date));
    if (analyses.length < 2) {
      return Scaffold(
        appBar: AppBar(title: const Text('Porównanie sylwetki')),
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
                'Potrzebne są co najmniej dwie analizy, żeby porównać progres.'),
          ),
        ),
      );
    }

    BodyAnalysisResult byId(String? id, BodyAnalysisResult fallback) {
      for (final analysis in analyses) {
        if (analysis.id == id) return analysis;
      }
      return fallback;
    }

    final newer = byId(_newerId, analyses.first);
    final older = byId(_olderId, analyses.last);
    final newerWeight = store.weightForAnalysis(newer);
    final olderWeight = store.weightForAnalysis(older);

    // Historia do wykresów (chronologicznie, maks 8 ostatnich analiz).
    final chronological = analyses.reversed.toList();
    final chartAnalyses = chronological.length > 8
        ? chronological.sublist(chronological.length - 8)
        : chronological;
    final chartLabels = [
      for (final analysis in chartAnalyses) shortDate(analysis.date)
    ];

    DropdownButtonFormField<String> picker({
      required String label,
      required String value,
      required ValueChanged<String?> onChanged,
    }) =>
        DropdownButtonFormField<String>(
          initialValue: value,
          decoration: InputDecoration(labelText: label, isDense: true),
          items: [
            for (final analysis in analyses)
              DropdownMenuItem(
                value: analysis.id,
                child: Text(trainerHistoryFullDate(analysis.date),
                    overflow: TextOverflow.ellipsis),
              ),
          ],
          onChanged: onChanged,
        );

    Widget photoPair(String label, String olderPath, String newerPath) {
      if (olderPath.isEmpty && newerPath.isEmpty)
        return const SizedBox.shrink();
      Widget photo(String path, String tag) => Expanded(
            child: Column(
              children: [
                Text(tag,
                    style: theme.textTheme.labelSmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
                const SizedBox(height: 4),
                ClipRRect(
                  borderRadius: BorderRadius.circular(14),
                  child: AspectRatio(
                    aspectRatio: 3 / 4,
                    child: path.isEmpty
                        ? ColoredBox(
                            color: theme.colorScheme.surfaceContainerHighest,
                            child: Icon(Icons.image_not_supported_outlined,
                                color: theme.colorScheme.onSurfaceVariant),
                          )
                        : Image.file(
                            File(path),
                            fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => ColoredBox(
                              color: theme.colorScheme.surfaceContainerHighest,
                              child: Icon(Icons.broken_image_outlined,
                                  color: theme.colorScheme.onSurfaceVariant),
                            ),
                          ),
                  ),
                ),
              ],
            ),
          );
      return Padding(
        padding: const EdgeInsets.only(bottom: 12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(label,
                style: theme.textTheme.titleSmall
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 6),
            Row(
              children: [
                photo(olderPath, trainerHistoryFullDate(older.date)),
                const SizedBox(width: 10),
                photo(newerPath, trainerHistoryFullDate(newer.date)),
              ],
            ),
          ],
        ),
      );
    }

    String deltaText(double olderValue, double newerValue, String unit) {
      if (olderValue <= 0 || newerValue <= 0) return '—';
      final diff = newerValue - olderValue;
      final sign = diff > 0 ? '+' : '';
      return '$sign${diff.toStringAsFixed(1)} $unit';
    }

    Widget deltaRow(String label, double olderPercent, double newerPercent) {
      final olderKg = olderWeight * olderPercent / 100;
      final newerKg = newerWeight * newerPercent / 100;
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          children: [
            Expanded(
                flex: 5,
                child: Text(label,
                    style: theme.textTheme.bodySmall
                        ?.copyWith(fontWeight: FontWeight.w800))),
            Expanded(
              flex: 4,
              child: Text(
                olderPercent > 0
                    ? '${olderPercent.toStringAsFixed(1)}% → ${newerPercent.toStringAsFixed(1)}%'
                    : '—',
                textAlign: TextAlign.center,
                style: theme.textTheme.bodySmall,
              ),
            ),
            Expanded(
              flex: 3,
              child: Text(
                deltaText(olderPercent, newerPercent, 'p.p.'),
                textAlign: TextAlign.right,
                style: theme.textTheme.bodySmall
                    ?.copyWith(fontWeight: FontWeight.w900),
              ),
            ),
            Expanded(
              flex: 3,
              child: Text(
                olderPercent > 0 && newerPercent > 0
                    ? deltaText(olderKg, newerKg, 'kg')
                    : '—',
                textAlign: TextAlign.right,
                style: theme.textTheme.bodySmall
                    ?.copyWith(fontWeight: FontWeight.w900),
              ),
            ),
          ],
        ),
      );
    }

    return Scaffold(
      appBar: AppBar(title: const Text('Porównanie sylwetki')),
      body: ListView(
        padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
        children: [
          Row(
            children: [
              Expanded(
                  child: picker(
                      label: 'Starsza analiza',
                      value: older.id,
                      onChanged: (id) => setState(() => _olderId = id))),
              const SizedBox(width: 10),
              Expanded(
                  child: picker(
                      label: 'Nowsza analiza',
                      value: newer.id,
                      onChanged: (id) => setState(() => _newerId = id))),
            ],
          ),
          const SizedBox(height: 14),
          photoPair('Przód', older.photoFrontPath, newer.photoFrontPath),
          photoPair('Bok', older.photoSidePath, newer.photoSidePath),
          photoPair('Tył', older.photoBackPath, newer.photoBackPath),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text('Zmiana składu ciała',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                  const SizedBox(height: 4),
                  Text(
                    'Masa: ${olderWeight.toStringAsFixed(1)} kg → ${newerWeight.toStringAsFixed(1)} kg'
                    '${olderWeight > 0 && newerWeight > 0 ? ' (${deltaText(olderWeight, newerWeight, 'kg')})' : ''}',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                  ),
                  const SizedBox(height: 8),
                  deltaRow('Tłuszcz', older.composition.bodyFatPercent,
                      newer.composition.bodyFatPercent),
                  deltaRow('Mięśnie', older.composition.musclePercent,
                      newer.composition.musclePercent),
                  deltaRow('Woda', older.composition.waterPercent,
                      newer.composition.waterPercent),
                  if (older.composition.bonePercent > 0 ||
                      newer.composition.bonePercent > 0)
                    deltaRow('Kości', older.composition.bonePercent,
                        newer.composition.bonePercent),
                ],
              ),
            ),
          ),
          const SizedBox(height: 12),
          SimpleProgressBarChartCard(
            title: 'Tkanka tłuszczowa w czasie',
            subtitle: 'Szacunki z kolejnych analiz sylwetki',
            values: [
              for (final analysis in chartAnalyses)
                analysis.composition.bodyFatPercent
            ],
            labels: chartLabels,
            suffix: '%',
            icon: Icons.opacity_rounded,
          ),
          const SizedBox(height: 12),
          SimpleProgressBarChartCard(
            title: 'Mięśnie szkieletowe w czasie',
            subtitle: 'Szacunki z kolejnych analiz sylwetki',
            values: [
              for (final analysis in chartAnalyses)
                analysis.composition.musclePercent
            ],
            labels: chartLabels,
            suffix: '%',
            icon: Icons.fitness_center_rounded,
          ),
        ],
      ),
    );
  }
}

/// Wiersz składu ciała: etykieta + pasek % + wartość.
