/// Samsung Health, co policzono fallbackiem, wykryte sesje, kroki podniesione
/// do kroków sesji, błędy i dane częściowe — z godziną każdego wpisu.
class HealthConnectSyncLogCard extends StatelessWidget {
  const HealthConnectSyncLogCard({super.key, required this.store});

  final AppStore store;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final log = store.healthSyncLog;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.sync_rounded, color: scheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Dziennik synchronizacji',
                        style: theme.textTheme.titleSmall
                            ?.copyWith(fontWeight: FontWeight.w900))),
                IconButton.filledTonal(
                  tooltip: 'Synchronizuj teraz',
                  onPressed: store.healthAutoSyncInProgress
                      ? null
                      : () => store.autoSyncHealthConnect(force: true),
                  icon: const Icon(Icons.refresh_rounded, size: 18),
                ),
              ],
            ),
            if (store.healthSyncStatus.isNotEmpty) ...[
              const SizedBox(height: 8),
              Text(store.healthSyncStatus,
                  style: theme.textTheme.bodySmall?.copyWith(
                      fontWeight: FontWeight.w800, color: scheme.primary)),
