class HealthConnectMetric {
  const HealthConnectMetric(this.label, this.value);

  final String label;
  final String value;
}

String formatHealthConnectDistance(double distanceKm) {
  if (distanceKm <= 0) return '0 km';
  if (distanceKm < 1) return '${(distanceKm * 1000).round()} m';
  return '${distanceKm.toStringAsFixed(2)} km';
}

String formatHealthConnectMinutes(int minutes) {
  if (minutes <= 0) return '—';
  final hours = minutes ~/ 60;
  final rest = minutes % 60;
  if (hours <= 0) return '$minutes min';
  if (rest == 0) return '$hours h';
  return '$hours h $rest min';
}

String formatHealthConnectTimestamp(DateTime date) {
  final local = date.toLocal();
  final hour = local.hour.toString().padLeft(2, '0');
  final minute = local.minute.toString().padLeft(2, '0');
  return '${trainerHistoryFullDate(local)} $hour:$minute';
}

double parseBodyMeasurementValue(String value) {
  return math
      .max(0, double.tryParse(value.replaceAll(',', '.')) ?? 0)
      .toDouble();
}

String formatBodyMeasurementValue(double value, String suffix) {
  if (value <= 0) return '—';
  if (value == value.roundToDouble()) return '${value.round()} $suffix';
  return '${value.toStringAsFixed(1)} $suffix';
}

List<String> bodyMeasurementTags(BodyMeasurement measurement) {
  final tags = <String>[
    if (measurement.weightKg > 0)
      'Waga ${formatBodyMeasurementValue(measurement.weightKg, 'kg')}',
    if (measurement.waistCm > 0)
      'Pas ${formatBodyMeasurementValue(measurement.waistCm, 'cm')}',
    if (measurement.chestCm > 0)
      'Klatka ${formatBodyMeasurementValue(measurement.chestCm, 'cm')}',
    if (measurement.armCm > 0)
      'Ramię ${formatBodyMeasurementValue(measurement.armCm, 'cm')}',
    if (measurement.thighCm > 0)
      'Udo ${formatBodyMeasurementValue(measurement.thighCm, 'cm')}',
    if (measurement.hipsCm > 0)
      'Biodra ${formatBodyMeasurementValue(measurement.hipsCm, 'cm')}',
    if (measurement.calfCm > 0)
      'Łydka ${formatBodyMeasurementValue(measurement.calfCm, 'cm')}',
    if (measurement.shouldersCm > 0)
      'Barki ${formatBodyMeasurementValue(measurement.shouldersCm, 'cm')}',
    if (measurement.neckCm > 0)
      'Szyja ${formatBodyMeasurementValue(measurement.neckCm, 'cm')}',
  ];
  return tags.isEmpty ? ['Brak obwodów'] : tags;
}

