        final width =
            wide ? (constraints.maxWidth - 10) / 2 : constraints.maxWidth;
        return Wrap(
          spacing: 10,
          runSpacing: 10,
          children: [
            SizedBox(
              width: width,
              child: ActivityTypeCreditTile(
                title: 'Kroki',
                subtitle: 'Chód zwykły z kroków liczy się osobno',
                type: TrainerActivityType.ordinaryStepsWalk,
                icon: Icons.directions_walk_rounded,
                decisions: decisions,
              ),
            ),
            SizedBox(
              width: width,
              child: ActivityTypeCreditTile(
                title: 'Chód mierzony',
                subtitle: 'Nie może być jednocześnie biegiem',
                type: TrainerActivityType.measuredWalk,
                icon: Icons.hiking_rounded,
                decisions: decisions,
              ),
            ),
            SizedBox(
              width: width,
              child: ActivityTypeCreditTile(
                title: 'Bieg mierzony',
                subtitle: 'Nie może być liczony jako chód',
                type: TrainerActivityType.run,
                icon: Icons.directions_run_rounded,
                decisions: decisions,
              ),
            ),
            SizedBox(
              width: width,
              child: ActivityTypeCreditTile(
                title: 'Trening siłowy',
                subtitle: 'Sesje z Trainera po zakończeniu treningu',
                type: TrainerActivityType.strengthTraining,
                icon: Icons.fitness_center_rounded,
                decisions: decisions,
              ),
            ),
          ],
        );
      },
    );
  }
}

class ActivityTypeCreditTile extends StatelessWidget {
  const ActivityTypeCreditTile({
    super.key,
    required this.title,
    required this.subtitle,
    required this.type,
    required this.icon,
    required this.decisions,
  });

  final String title;
  final String subtitle;
  final TrainerActivityType type;
  final IconData icon;
  final List<ActivityCreditDecision> decisions;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final visible =
        decisions.where((decision) => decision.entry.type == type).toList();
    final creditedKcal =
        visible.fold<int>(0, (sum, decision) => sum + decision.creditedKcal);
    final duplicates =
        visible.where((decision) => decision.skippedAsDuplicate).length;
    final sources =
        visible.map((decision) => decision.entry.source.label).toSet().toList();
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                CircleAvatar(
                  backgroundColor: theme.colorScheme.primaryContainer,
                  foregroundColor: theme.colorScheme.onPrimaryContainer,
                  child: Icon(icon),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.titleMedium
                              ?.copyWith(fontWeight: FontWeight.w900)),
                      Text(subtitle,
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: theme.textTheme.bodySmall?.copyWith(
                              color: theme.colorScheme.onSurfaceVariant)),
                    ],
                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                MiniTag(text: 'Kcal: $creditedKcal'),
                MiniTag(text: 'Duplikaty: $duplicates'),
                if (sources.isEmpty)
                  const MiniTag(text: 'Brak źródła')
                else
                  ...sources.map((source) => MiniTag(text: source)),
              ],
            ),
            const SizedBox(height: 10),
            if (visible.isEmpty)
              Text('Brak danych wejściowych dla tego typu.',
                  style: theme.textTheme.bodyMedium
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant))
            else
              ...visible.map(
                  (decision) => ActivityDecisionCompactRow(decision: decision)),
          ],
        ),
      ),
    );
  }
}

