class _SuspiciousEntryTile extends StatelessWidget {
  const _SuspiciousEntryTile({required this.entry});
  final TrainerActivityEntry entry;

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    String two(int v) => v.toString().padLeft(2, '0');
    final dateLabel =
        '${entry.date.year}-${two(entry.date.month)}-${two(entry.date.day)}';
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface.withValues(alpha: 0.6),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text('${entry.source.label} · ${entry.type.label}',
                    style: theme.textTheme.bodyMedium
                        ?.copyWith(fontWeight: FontWeight.w700)),
                const SizedBox(height: 2),
                Text(
                  '$dateLabel · ${entry.estimatedKcal} kcal${entry.steps > 0 ? ' · ${entry.steps} kroków' : ''}${entry.distanceKm > 0 ? ' · ${entry.distanceKm.toStringAsFixed(1)} km' : ''}',
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
                ),
              ],
            ),
          ),
          const SizedBox(width: 8),
          IconButton(
            tooltip: 'Usuń wpis',
            icon: Icon(Icons.delete_outline_rounded,
                color: theme.colorScheme.error),
            onPressed: () async {
              final ok = await showDialog<bool>(
                context: context,
                builder: (ctx) => AlertDialog(
                  title: const Text('Usunąć błędny wpis?'),
                  content: Text(
                      'Wpis „${entry.source.label} · ${entry.type.label}" z dnia $dateLabel zostanie trwale usunięty z lokalnych danych.'),
                  actions: [
                    TextButton(
                        onPressed: () => Navigator.pop(ctx, false),
                        child: const Text('Anuluj')),
                    FilledButton(
                        onPressed: () => Navigator.pop(ctx, true),
                        child: const Text('Usuń')),
                  ],
                ),
              );
              if (ok == true && context.mounted) {
                final removed = await store.removeActivityEntry(entry.id);
                if (context.mounted && removed) {
                  ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Usunięto błędny wpis.')));
                }
              }
            },
          ),
        ],
      ),
    );
  }
}

class BackupRestoreCard extends StatelessWidget {
  const BackupRestoreCard({super.key, required this.store});
  final AppStore store;

  Future<void> _showImportDialog(BuildContext context) async {
    final controller = TextEditingController();
    final json = await showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Import danych JSON'),
        content: SizedBox(
          width: 520,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                  'Wklej wcześniej wyeksportowane dane JSON. Obecne dane zostaną zastąpione.',
                  style: Theme.of(ctx).textTheme.bodySmall),
              const SizedBox(height: 10),
              TextField(
                controller: controller,
                maxLines: 6,
                decoration:
                    const InputDecoration(hintText: '{ "settings": ... }'),
              ),
            ],
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx), child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, controller.text.trim()),
              child: const Text('Importuj')),
        ],
      ),
    );
    if (json == null || json.isEmpty || !context.mounted) return;

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Zastąpić obecne dane?'),
        content: const Text(
            'Import nadpisze treningi, plany, ćwiczenia i ustawienia. Warto najpierw zrobić kopię lokalną.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Zastąp')),
        ],
      ),
    );
    if (confirmed != true || !context.mounted) return;

    try {
      final decoded = jsonDecode(json);
      Map<String, dynamic>? data;
      if (decoded is Map && decoded['data'] is Map) {
        data = Map<String, dynamic>.from(decoded['data'] as Map);
      } else if (decoded is Map) {
        data = Map<String, dynamic>.from(decoded);
      }
      if (data == null) {
        if (context.mounted) showError(context, 'Nieprawidłowy format danych.');
        return;
      }
      final ok = await store.importFullData(data);
      if (context.mounted) {
        showError(
            context,
            ok
                ? 'Import zakończony sukcesem.'
                : 'Nie udało się zaimportować danych.');
      }
    } catch (e) {
      if (context.mounted) showError(context, 'Błąd importu: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    String fmt(DateTime? dt) {
      if (dt == null) return 'brak';
      String two(int v) => v.toString().padLeft(2, '0');
      return '${dt.year}-${two(dt.month)}-${two(dt.day)} ${two(dt.hour)}:${two(dt.minute)}';
    }

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.shield_outlined, color: scheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Backup i bezpieczeństwo danych',
                        style: theme.textTheme.titleLarge
                            ?.copyWith(fontWeight: FontWeight.w900))),
              ],
            ),
            const SizedBox(height: 4),
            Text('Ostatnia kopia: ${fmt(store.lastBackupAt)}',
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: scheme.onSurfaceVariant)),
            const SizedBox(height: 14),
            LayoutBuilder(
              builder: (context, constraints) {
                final wide = constraints.maxWidth > 520;
                final width = wide
                    ? (constraints.maxWidth - 10) / 2
                    : constraints.maxWidth;
                return Wrap(
                  spacing: 10,
                  runSpacing: 10,
                  children: [
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.save_outlined,
                        title: 'Kopia lokalna',
                        subtitle: 'Zapisz migawkę danych na urządzeniu',
                        onTap: () async {
                          final at = await store.createLocalBackup();
                          if (context.mounted)
                            showError(context, 'Zapisano kopię (${fmt(at)}).');
                        },
                      ),
                    ),
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.restore_rounded,
                        title: 'Przywróć kopię',
                        subtitle: 'Odtwórz dane z lokalnej migawki',
                        onTap: () async {
                          final has = await store.hasLocalBackup();
                          if (!context.mounted) return;
                          if (!has) {
                            showError(
                                context, 'Brak zapisanej kopii lokalnej.');
                            return;
                          }
                          final ok = await showDialog<bool>(
                            context: context,
                            builder: (ctx) => AlertDialog(
                              title: const Text('Przywrócić kopię?'),
                              content: const Text(
                                  'Obecne dane zostaną zastąpione danymi z ostatniej kopii lokalnej.'),
                              actions: [
                                TextButton(
                                    onPressed: () => Navigator.pop(ctx, false),
                                    child: const Text('Anuluj')),
                                FilledButton(
                                    onPressed: () => Navigator.pop(ctx, true),
                                    child: const Text('Przywróć')),
                              ],
                            ),
                          );
                          if (ok != true || !context.mounted) return;
                          final restored = await store.restoreLocalBackup();
                          if (context.mounted)
                            showError(
                                context,
                                restored
                                    ? 'Przywrócono dane z kopii.'
                                    : 'Nie udało się przywrócić kopii.');
                        },
                      ),
                    ),
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.history_edu_outlined,
                        title: 'Eksport historii CSV',
                        subtitle: 'Wszystkie treningi do arkusza',
                        onTap: () =>
                            showExportDialog(context, buildCsvExport(store)),
                      ),
                    ),
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.insights_outlined,
                        title: 'Eksport progresu CSV',
                        subtitle: 'Rekordy i objętość per ćwiczenie',
                        onTap: () => showExportDialog(
                            context, buildProgressCsvExport(store)),
                      ),
                    ),
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.upload_file_outlined,
                        title: 'Import danych',
                        subtitle: 'Wczytaj dane z eksportu JSON',
                        onTap: () => _showImportDialog(context),
                      ),
                    ),
                    SizedBox(
                      width: width,
                      child: FeatureActionTile(
                        icon: Icons.monitor_heart_outlined,
                        title: 'Diagnostyka',
                        subtitle: 'Stan danych, HC, AI i błędne wpisy',
                        onTap: () => Navigator.of(context).push(
                            MaterialPageRoute(
                                builder: (_) => const DiagnosticsPage())),
                      ),
                    ),
                  ],
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

