/// Etap 25 + Etap wygląd: karta „Wygląd aplikacji" — motywy UI, tryb nocny,
/// kolor akcentu, kształty, styl kart, gęstość, układ kafelków, dolne menu
/// i gradienty. Zmiany zapisują się od razu (store.updateSettings) i działają na żywo.
class AppearanceCard extends StatelessWidget {
  const AppearanceCard({super.key, required this.store});

  final AppStore store;

  void _save(AppSettings next) => store.updateSettings(next);

  /// Wybiera zdjęcie tła z galerii i kopiuje je do katalogu aplikacji (ścieżka
  /// z pickera to cache systemowy, który bywa czyszczony). Stary plik tła jest
  /// usuwany, żeby nie zostawiać śmieci.
  Future<void> _pickBackgroundImage() async {
    final XFile? picked = await ImagePicker().pickImage(
      source: ImageSource.gallery,
      maxWidth: 2200,
      imageQuality: 88,
    );
    if (picked == null) return;
    final settings = store.settings;
    try {
      final dir = await getApplicationDocumentsDirectory();
      final String ext = picked.path.contains('.')
          ? picked.path.split('.').last.toLowerCase()
          : 'jpg';
      final String destPath =
          '${dir.path}/trainer_bg_${DateTime.now().millisecondsSinceEpoch}.$ext';
      await File(picked.path).copy(destPath);
      await _deleteOwnedBackgroundFile(settings.backgroundImagePath);
      _save(settings.copyWith(backgroundImagePath: destPath));
    } catch (error) {
      // Kopiowanie nie wyszło — użyj ścieżki z pickera (działa do czyszczenia
      // cache przez system; wtedy tło wraca do gradientu/koloru).
      debugPrint('[Wygląd] Kopiowanie tła nieudane: $error');
      _save(settings.copyWith(backgroundImagePath: picked.path));
    }
  }

  Future<void> _removeBackgroundImage() async {
    final settings = store.settings;
    await _deleteOwnedBackgroundFile(settings.backgroundImagePath);
    _save(settings.copyWith(backgroundImagePath: ''));
  }

  /// Usuwa poprzedni plik tła, ale tylko nasz własny (skopiowany do katalogu
  /// aplikacji) — nigdy oryginału z galerii użytkownika.
  Future<void> _deleteOwnedBackgroundFile(String path) async {
    if (!path.contains('trainer_bg_')) return;
    try {
      final File file = File(path);
      if (file.existsSync()) await file.delete();
    } catch (_) {}
  }

  Widget _sectionLabel(BuildContext context, IconData icon, String text) {
    final theme = Theme.of(context);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
      child: Row(
        children: [
          Icon(icon, color: theme.colorScheme.primary, size: 20),
          const SizedBox(width: 8),
          Text(text,
              style: theme.textTheme.titleSmall
                  ?.copyWith(fontWeight: FontWeight.w800)),
        ],
      ),
    );
  }

  /// Suwak przezroczystości 55–100% (100% = pełne krycie) z etykietą wartości.
  Widget _opacitySlider(BuildContext context,
      {required double value, required ValueChanged<double> onChanged}) {
    final theme = Theme.of(context);
    final clamped = value.clamp(0.55, 1.0);
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: Row(
        children: [
          Expanded(
            child: Slider(
              value: clamped,
              min: 0.55,
              max: 1.0,
              divisions: 9,
              label: '${(clamped * 100).round()}%',
              onChanged: onChanged,
            ),
          ),
          SizedBox(
            width: 48,
            child: Text(
              '${(clamped * 100).round()}%',
              textAlign: TextAlign.end,
              style: theme.textTheme.labelLarge
                  ?.copyWith(fontWeight: FontWeight.w800),
            ),
          ),
        ],
      ),
    );
  }

  Widget _segmented(BuildContext context,
      {required String value,
      required Map<String, String> options,
      required ValueChanged<String> onChanged}) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: SizedBox(
        width: double.infinity,
        child: SegmentedButton<String>(
          showSelectedIcon: false,
          segments: [
            for (final entry in options.entries)
              ButtonSegment<String>(
                  value: entry.key,
                  label: Text(entry.value,
                      maxLines: 1, overflow: TextOverflow.ellipsis)),
          ],
          selected: {options.containsKey(value) ? value : options.keys.first},
          onSelectionChanged: (selection) {
            if (selection.isNotEmpty) onChanged(selection.first);
          },
        ),
      ),
    );
  }

  /// „Zaskocz mnie" — losowy motyw inny niż obecny (szybka zabawa wyglądem).
  void _surpriseTheme() {
    final current = store.settings.themeStyleId;
    final candidates =
        kTrainerThemeStyles.where((style) => style.id != current).toList();
    if (candidates.isEmpty) return;
    final style = candidates[math.Random().nextInt(candidates.length)];
    _save(store.settings.copyWith(
      themeStyleId: style.id,
      accentColorValue: style.accent,
      darkMode: style.preferDark,
    ));
  }

  /// Pakiety szybkich stylów: jedno dotknięcie ustawia spójny zestaw efektów
  /// (personalizacja szczegółowa niżej dalej działa i nadpisuje pakiet).
  void _applyStyleBundle(String bundle) {
    final settings = store.settings;
    switch (bundle) {
      case 'minimal':
        _save(settings.copyWith(
          useGradients: false,
          backgroundGradient: false,
          glassEffect: false,
          themedBackground: false,
          cardOpacity: 1.0,
          navBarOpacity: 1.0,
          cardStyle: 'flat',
        ));
        break;
      case 'glass':
        _save(settings.copyWith(
          useGradients: true,
          backgroundGradient: false,
          glassEffect: true,
          themedBackground: true,
          cardOpacity: 0.78,
          navBarOpacity: 0.72,
          cardStyle: 'flat',
        ));
        break;
      case 'energy':
        _save(settings.copyWith(
          useGradients: true,
          backgroundGradient: false,
          glassEffect: false,
          themedBackground: true,
          gradientStrength: 'strong',
          cardOpacity: 1.0,
          navBarOpacity: 1.0,
          cardStyle: 'elevated',
        ));
        break;
    }
  }

  /// Karta-sekcja zakładki wyglądu: ikona + tytuł + opcjonalny opis + treść.
  /// Dzięki osobnym kartom ustawienia nie zlewają się w jedną ścianę opcji.
  Widget _settingsSection(
    BuildContext context, {
    required IconData icon,
    required String title,
    String? subtitle,
    required List<Widget> children,
  }) {
    final theme = Theme.of(context);
    return Card(
      margin: const EdgeInsets.only(bottom: 12),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(4, 12, 4, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Row(
                children: [
                  Icon(icon, color: theme.colorScheme.primary, size: 20),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(title,
                            style: theme.textTheme.titleSmall
                                ?.copyWith(fontWeight: FontWeight.w900)),
                        if (subtitle != null)
                          Text(subtitle,
                              style: theme.textTheme.labelSmall?.copyWith(
                                  color: theme.colorScheme.onSurfaceVariant)),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 8),
            ...children,
          ],
        ),
      ),
    );
  }

  /// Chipy motywów dla jednej grupy (ciemne / jasne).
  Widget _themeChips(BuildContext context, {required bool dark}) {
    final settings = store.settings;
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16),
      child: Wrap(
        spacing: 8,
        runSpacing: 8,
        children: kTrainerThemeStyles
            .where((style) => style.preferDark == dark)
            .map((style) {
          final selected = settings.themeStyleId == style.id;
          return ChoiceChip(
            avatar:
                CircleAvatar(backgroundColor: Color(style.accent), radius: 9),
            label: Text(style.name),
            tooltip: style.description,
            selected: selected,
            onSelected: (_) => _save(settings.copyWith(
              themeStyleId: style.id,
              accentColorValue: style.accent,
              darkMode: style.preferDark,
            )),
          );
        }).toList(),
      ),
    );
  }

