/// Podstrona „Deload": włączenie, rytm, długość, adaptacja i data startu.
class DeloadSettingsPage extends StatelessWidget {
  const DeloadSettingsPage({super.key});

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final theme = Theme.of(context);
    final cycle = store.deloadCycle;
    final status = store.deloadStatusToday;
    final weeks = (cycle.trainingDays / 7).round();

    Future<void> save(DeloadCycle next) => store.updateDeloadCycle(next);

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),
      children: [
        Card(
          color: kDeloadColor.withValues(alpha: 0.12),
          child: const ListTile(
            leading: Icon(Icons.self_improvement_rounded, color: kDeloadColor),
            title: Text('Cykliczny deload'),
            subtitle: Text(
                'Zaplanowane tygodnie odciążenia: mniej serii, lżejszy ciężar '
                'i więcej mobilności, żeby mięśnie się zregenerowały. Po deloadzie '
                'wchodzisz mocno, potem intensywność stopniowo maleje aż do kolejnego.'),
          ),
        ),
        const SizedBox(height: 12),
        Card(
          child: SwitchListTile(
            secondary: const Icon(Icons.event_repeat_rounded),
            title: const Text('Deload włączony'),
            subtitle: Text(cycle.enabled
                ? 'Trainer sam planuje tygodnie odciążenia'
                : 'Wyłączony — brak zaplanowanych deloadów'),
            value: cycle.enabled,
            onChanged: (v) => store.setDeloadEnabled(v),
          ),
        ),
        if (cycle.enabled) ...[
          const SizedBox(height: 12),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(14),
              child: Row(
                children: [
                  Icon(
                      status.isDeload
                          ? Icons.self_improvement_rounded
                          : Icons.trending_up_rounded,
                      color: kDeloadColor),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          status.isDeload
                              ? 'Trwa deload — dzień ${status.deloadDayNumber}/${status.deloadTotalDays}'
                              : 'Trening — do deloadu ${status.daysUntilDeload} dni',
                          style: theme.textTheme.titleSmall
                              ?.copyWith(fontWeight: FontWeight.w800),
                        ),
                        if (status.windowStart != null &&
                            status.windowEnd != null)
                          Text(
                            'Najbliższe okno: ${trainerHistoryFullDate(status.windowStart!)} – ${trainerHistoryFullDate(status.windowEnd!)}',
                            style: theme.textTheme.bodySmall?.copyWith(
                                color: theme.colorScheme.onSurfaceVariant),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 18),
          const SectionHeader(title: 'Rytm'),
          const SizedBox(height: 4),
          Text('Co ile tygodni treningu wypada tydzień deloadu.',
              style: theme.textTheme.bodySmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            children: [
              for (final w in [4, 5, 6])
                ChoiceChip(
                  label: Text('$w tyg.'),
                  selected: weeks == w,
                  onSelected: (_) => save(cycle.copyWith(trainingDays: w * 7)),
                ),
            ],
          ),
          const SizedBox(height: 18),
          const SectionHeader(title: 'Długość deloadu'),
          const SizedBox(height: 8),
          Wrap(
            spacing: 8,
            children: [
              for (final d in [5, 7])
                ChoiceChip(
                  label: Text('$d dni'),
                  selected: cycle.deloadDays == d,
                  onSelected: (_) => save(cycle.copyWith(deloadDays: d)),
                ),
            ],
          ),
          const SizedBox(height: 12),
          Card(
            child: SwitchListTile(
              secondary: const Icon(Icons.auto_awesome_rounded),
              title: const Text('Dostrajaj zmęczeniem (adaptacyjnie)'),
              subtitle: const Text(
                  'Przy dużym zmęczeniu Trainer zaproponuje wcześniejszy deload.'),
              value: cycle.adaptive,
              onChanged: (v) => save(cycle.copyWith(adaptive: v)),
            ),
          ),
          const SizedBox(height: 12),
          Card(
            child: ListTile(
              leading: const Icon(Icons.summarize_outlined),
              title: const Text('Podsumowanie cyklu dla trenera'),
              subtitle:
                  const Text('Blok, deload i intensywność — do skopiowania'),
              trailing: const Icon(Icons.chevron_right_rounded),
              onTap: () => openTrainerSubPage(
                  context, const TrainingCycleSummaryPage(),
                  title: 'Podsumowanie cyklu'),
            ),
          ),
          const SizedBox(height: 18),
          const SectionHeader(title: 'Start deloadu'),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                child: OutlinedButton.icon(
                  onPressed: () async {
                    final start = status.windowStart ?? DateTime.now();
                    final picked = await showDatePicker(
                      context: context,
                      initialDate: start,
                      firstDate: DateTime(2020),
                      lastDate: DateTime(2100),
                      helpText: 'Pierwszy dzień deloadu',
                    );
                    if (picked != null) {
                      await save(reanchorDeloadStart(cycle, picked));
                    }
                  },
                  icon: const Icon(Icons.event_rounded, size: 18),
                  label: const Text('Ustaw datę'),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: FilledButton.tonalIcon(
                  onPressed: () => store.startDeloadNow(),
                  icon: const Icon(Icons.play_arrow_rounded, size: 18),
                  label: const Text('Zacznij dziś'),
                ),
              ),
            ],
          ),
        ],
      ],
    );
  }
}

