/// Karta klucza API OpenAI (obrazy AI dla ćwiczeń). Klucz jest przechowywany
/// tylko lokalnie w ustawieniach i wysyłany wyłącznie do api.openai.com.
class OpenAiKeyCard extends StatefulWidget {
  const OpenAiKeyCard({super.key, required this.store});

  final AppStore store;

  @override
  State<OpenAiKeyCard> createState() => _OpenAiKeyCardState();
}

class _OpenAiKeyCardState extends State<OpenAiKeyCard> {
  late final TextEditingController _controller;
  bool _obscure = true;

  @override
  void initState() {
    super.initState();
    _controller =
        TextEditingController(text: widget.store.settings.openAiApiKey);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final key = _controller.text.trim();
    await widget.store
        .updateSettings(widget.store.settings.copyWith(openAiApiKey: key));
    if (!mounted) return;
    showError(
        context, key.isEmpty ? 'Klucz API usunięty.' : 'Klucz API zapisany.');
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final hasKey = widget.store.settings.openAiApiKey.trim().isNotEmpty;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.auto_awesome_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                  child: Text('OpenAI — obrazy AI dla ćwiczeń',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                  decoration: BoxDecoration(
                    color: (hasKey
                            ? theme.colorScheme.primary
                            : theme.colorScheme.outline)
                        .withValues(alpha: 0.14),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Text(
                    hasKey ? 'USTAWIONY' : 'BRAK',
                    style: TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w900,
                      color: hasKey
                          ? theme.colorScheme.primary
                          : theme.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(
              'Klucz API z platform.openai.com służy do generowania ilustracji ćwiczeń '
              '(przycisk „Wygeneruj obraz (AI)" na stronie ćwiczenia). Przechowywany tylko '
              'na tym urządzeniu, wysyłany wyłącznie do OpenAI.',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _controller,
              obscureText: _obscure,
