/// Podstrona „Konto i synchronizacja" (Etap 3).
///
/// Logowanie jest OPCJONALNE — aplikacja działa też w pełni lokalnie. Panel
/// pokazuje status konta, logowanie Google / e-mail, status synchronizacji,
/// ostatni backup, „Synchronizuj teraz", eksport/import oraz informację, czy
/// dane są lokalne czy w chmurze. Dane lokalne nie są kasowane po zalogowaniu,
/// a scalanie z chmurą nie duplikuje historii (łączenie po id).
class AccountSyncPage extends StatefulWidget {
  const AccountSyncPage({super.key});

  @override
  State<AccountSyncPage> createState() => _AccountSyncPageState();
}

class _AccountSyncPageState extends State<AccountSyncPage> {
  final _email = TextEditingController();
  final _password = TextEditingController();
  bool _busy = false;
  bool _registerMode = false;
  DateTime? _cloudUpdatedAt;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _refreshCloudTime());
  }

  @override
  void dispose() {
    _email.dispose();
    _password.dispose();
    super.dispose();
  }

  Future<void> _refreshCloudTime() async {
    final at = await trainerAccountService.cloudUpdatedAt();
    if (mounted) setState(() => _cloudUpdatedAt = at);
  }

  String _formatDateTime(DateTime value) {
    String two(int n) => n.toString().padLeft(2, '0');
    return '${value.year}-${two(value.month)}-${two(value.day)} ${two(value.hour)}:${two(value.minute)}';
  }

  String _friendlyAccountError(Object error) {
    final text = error.toString();
    if (text.contains('network'))
      return 'Brak połączenia z siecią. Spróbuj ponownie.';
    if (text.contains('wrong-password') || text.contains('invalid-credential'))
      return 'Nieprawidłowy e-mail lub hasło.';
    if (text.contains('user-not-found'))
      return 'Nie znaleziono konta dla tego e-maila.';
    if (text.contains('email-already-in-use'))
      return 'Konto z tym e-mailem już istnieje — zaloguj się.';
    if (text.contains('weak-password'))
      return 'Hasło jest za słabe (min. 6 znaków).';
    if (text.contains('invalid-email')) return 'Nieprawidłowy adres e-mail.';
    if (text.contains('operation-not-allowed'))
      return 'Ta metoda logowania jest wyłączona w konsoli Firebase.';
    if (text.contains('too-many-requests'))
      return 'Za dużo prób. Spróbuj później.';
    if (text.contains('canceled') || text.contains('cancelled'))
      return 'Logowanie anulowane.';
    return text.replaceFirst('Exception: ', '');
  }

  Future<void> _guard(Future<void> Function() action, {String? success}) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      await action();
      if (!mounted) return;
      if (success != null) showError(context, success);
    } catch (error) {
      if (!mounted) return;
      showError(context, _friendlyAccountError(error));
    } finally {
      if (mounted) setState(() => _busy = false);
      unawaited(_refreshCloudTime());
    }
  }

  Future<void> _emailAuth() async {
    final email = _email.text.trim();
    final password = _password.text;
    if (email.isEmpty || password.isEmpty) {
      showError(context, 'Podaj e-mail i hasło.');
      return;
    }
    await _guard(
      () => _registerMode
          ? trainerAccountService.registerWithEmail(email, password)
          : trainerAccountService.signInWithEmail(email, password),
      success: _registerMode ? 'Konto utworzone i zalogowane.' : 'Zalogowano.',
    );
    if (mounted) _password.clear();
  }

  Future<void> _syncNow(AppStore store) async {
    if (_busy) return;
    setState(() => _busy = true);
    try {
      final cloud = await trainerAccountService.downloadPayload();
      var addedTotal = 0;
      if (cloud != null) {
        final added = await store.mergeFullData(cloud);
        addedTotal = added.values.fold(0, (a, b) => a + b);
      }
      await trainerAccountService.uploadPayload(buildFullExport(store));
      if (!mounted) return;
      showError(
        context,
        addedTotal > 0
            ? 'Zsynchronizowano. Pobrano $addedTotal nowych wpisów z chmury.'
            : 'Zsynchronizowano z chmurą.',
      );
    } catch (error) {
      if (!mounted) return;
      showError(context, _friendlyAccountError(error));
    } finally {
      if (mounted) setState(() => _busy = false);
      unawaited(_refreshCloudTime());
    }
  }

  Future<void> _restoreFromCloud(AppStore store) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Przywróć z chmury'),
        content: const Text(
          'To zastąpi lokalne treningi, plany, ćwiczenia i ustawienia wersją z chmury. '
          'Użyj na nowym telefonie. Na urządzeniu z danymi zwykle lepszy jest „Synchronizuj teraz".',
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Przywróć')),
        ],
      ),
    );
    if (confirmed != true) return;
    await _guard(() async {
      final cloud = await trainerAccountService.downloadPayload();
      if (cloud == null) throw Exception('Brak kopii w chmurze.');
      final ok = await store.importFullData(cloud);
      if (!ok) throw Exception('Kopia w chmurze jest pusta lub błędna.');
    }, success: 'Przywrócono dane z chmury.');
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    return Scaffold(
      appBar: AppBar(title: const Text('Konto i synchronizacja')),
      body: AnimatedBuilder(
        animation: trainerAccountService,
        builder: (context, _) {
          final account = trainerAccountService.state;
          return ListView(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 28),
            children: [
              _statusCard(context, account, store),
              const SizedBox(height: 12),
              if (!account.firebaseAvailable)
                _setupCard(context)
              else if (!account.signedIn)
                _loginCard(context)
              else ...[
                _accountCard(context, account),
                const SizedBox(height: 12),
                _cloudSyncCard(context, store),
              ],
              const SizedBox(height: 12),
              BackupRestoreCard(store: store),
            ],
          );
        },
      ),
    );
  }

  Widget _statusCard(
      BuildContext context, TrainerAccountState account, AppStore store) {
    final theme = Theme.of(context);
    final synced = account.signedIn;
    final color =
        synced ? theme.colorScheme.primary : theme.colorScheme.onSurfaceVariant;
    final location = synced ? 'Dane lokalne + w chmurze' : 'Dane tylko lokalne';
    final backup = store.lastBackupAt;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(
                    synced
                        ? Icons.cloud_done_rounded
                        : Icons.smartphone_rounded,
                    color: color),
                const SizedBox(width: 10),
                Expanded(
                  child: Text(location,
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              synced
                  ? 'Zalogowano jako ${account.email ?? account.displayName ?? 'konto'} (${account.providerLabel}). '
                      'Twoje dane są zabezpieczone w chmurze i przetrwają reinstalację lub zmianę telefonu.'
                  : 'Aplikacja działa lokalnie. Zaloguj się, aby zabezpieczyć dane w chmurze i mieć je na innym urządzeniu. Logowanie jest opcjonalne.',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.35),
            ),
            const SizedBox(height: 8),
            _infoRow(theme, Icons.backup_outlined, 'Ostatnia kopia lokalna',
                backup == null ? 'Brak' : _formatDateTime(backup)),
            if (account.signedIn)
              _infoRow(
                  theme,
                  Icons.cloud_sync_outlined,
                  'Ostatnia kopia w chmurze',
                  _cloudUpdatedAt == null
                      ? 'Brak / nie sprawdzono'
                      : _formatDateTime(_cloudUpdatedAt!)),
          ],
        ),
      ),
    );
  }

  Widget _infoRow(ThemeData theme, IconData icon, String label, String value) {
    return Padding(
      padding: const EdgeInsets.only(top: 6),
      child: Row(
        children: [
          Icon(icon, size: 16, color: theme.colorScheme.onSurfaceVariant),
          const SizedBox(width: 8),
          Expanded(
              child: Text(label,
                  style: theme.textTheme.bodySmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant))),
          Text(value,
              style: theme.textTheme.bodySmall
                  ?.copyWith(fontWeight: FontWeight.w800)),
        ],
      ),
    );
  }

  Widget _setupCard(BuildContext context) {
    final theme = Theme.of(context);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(Icons.info_outline_rounded,
                    color: theme.colorScheme.primary),
                const SizedBox(width: 8),
                Expanded(
                    child: Text('Chmura nie jest jeszcze skonfigurowana',
                        style: theme.textTheme.titleMedium
                            ?.copyWith(fontWeight: FontWeight.w900))),
              ],
            ),
            const SizedBox(height: 8),
            Text(
              'Logowanie i synchronizacja online wymagają jednorazowej konfiguracji Firebase '
              'w projekcie. Do tego czasu aplikacja działa w pełni lokalnie, a Twoje dane '
              'możesz zabezpieczyć kopią lokalną i eksportem poniżej.',
              style: theme.textTheme.bodySmall?.copyWith(
                  color: theme.colorScheme.onSurfaceVariant, height: 1.4),
            ),
            const SizedBox(height: 10),
            Container(
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: theme.colorScheme.surfaceContainerHighest
                    .withValues(alpha: 0.5),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Text(
                'Jak włączyć chmurę (raz):\n'
                '1. Utwórz projekt na console.firebase.google.com.\n'
                '2. W terminalu projektu: flutterfire configure.\n'
                '3. Włącz w konsoli: Authentication → Email i Google.\n'
                '4. Utwórz bazę Cloud Firestore.\n'
                '5. Dla logowania Google dodaj odcisk SHA-1 aplikacji.',
                style: theme.textTheme.bodySmall?.copyWith(height: 1.5),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _loginCard(BuildContext context) {
    final theme = Theme.of(context);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(_registerMode ? 'Utwórz konto' : 'Zaloguj się',
                style: theme.textTheme.titleMedium
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 12),
            FilledButton.icon(
              onPressed: _busy
                  ? null
                  : () => _guard(trainerAccountService.signInWithGoogle,
                      success: 'Zalogowano przez Google.'),
              icon: const Icon(Icons.login_rounded),
              label: const Text('Kontynuuj z Google'),
            ),
            const SizedBox(height: 14),
            Row(children: [
              const Expanded(child: Divider()),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 8),
                child: Text('albo e-mailem',
                    style: theme.textTheme.bodySmall
                        ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
              ),
              const Expanded(child: Divider()),
            ]),
            const SizedBox(height: 10),
            TextField(
              controller: _email,
              keyboardType: TextInputType.emailAddress,
              autofillHints: const [AutofillHints.email],
              decoration: const InputDecoration(labelText: 'E-mail'),
            ),
            const SizedBox(height: 10),
            TextField(
              controller: _password,
              obscureText: true,
              decoration: const InputDecoration(labelText: 'Hasło'),
            ),
            const SizedBox(height: 12),
            FilledButton.tonalIcon(
              onPressed: _busy ? null : _emailAuth,
              icon: _busy
                  ? const SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(strokeWidth: 2))
                  : Icon(_registerMode
                      ? Icons.person_add_alt_rounded
                      : Icons.login_rounded),
              label: Text(_registerMode ? 'Utwórz konto' : 'Zaloguj się'),
            ),
            const SizedBox(height: 6),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                TextButton(
                  onPressed: _busy
                      ? null
                      : () => setState(() => _registerMode = !_registerMode),
                  child: Text(
                      _registerMode ? 'Mam już konto' : 'Utwórz nowe konto'),
                ),
                TextButton(
                  onPressed: _busy
                      ? null
                      : () {
                          final email = _email.text.trim();
                          if (email.isEmpty) {
                            showError(
                                context, 'Wpisz e-mail, aby zresetować hasło.');
                            return;
                          }
                          _guard(
                              () => trainerAccountService
                                  .sendPasswordReset(email),
                              success: 'Wysłano link do resetu hasła.');
                        },
                  child: const Text('Reset hasła'),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _accountCard(BuildContext context, TrainerAccountState account) {
    final theme = Theme.of(context);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
