    EquipmentType.bench,
    EquipmentType.rack,
    EquipmentType.pullUpBar,
    EquipmentType.kettlebell,
    EquipmentType.resistanceBand,
    EquipmentType.cable,
    EquipmentType.machine,
    EquipmentType.step,
    EquipmentType.cardioMachine,
  ];

  @override
  void initState() {
    super.initState();
    weight = TextEditingController();
    height = TextEditingController();
    age = TextEditingController();
    goal = TextEditingController();
    equipment = TextEditingController();
    limitations = TextEditingController();
    workHours = TextEditingController();
    _fillFrom(widget.settings);
  }

  @override
  void didUpdateWidget(covariant SettingsCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.settings != widget.settings) _fillFrom(widget.settings);
  }

  void _fillFrom(AppSettings s) {
    weight.text = s.bodyWeightKg.toStringAsFixed(0);
    height.text = s.heightCm.toStringAsFixed(0);
    age.text = '${s.age}';
    goal.text = s.goal;
    equipment.text = s.equipment;
    limitations.text = s.limitations;
    workHours.text = s.workHoursPerDay.toStringAsFixed(1);
    level = normalizeLevel(s.level);
    trainingMode = normalizeTrainingMode(s.trainingMode);
    sex = _sexOptions.contains(s.sex) ? s.sex : 'Nie podano';
    workIntensity = _workIntensityLabels.containsKey(s.workIntensity)
        ? s.workIntensity
        : 'none';
    workWeekdays = s.workWeekdays.toSet();
    final eqProfile = s.equipmentProfile;
    equipmentMode = eqProfile.mode;
    ownedEquipment = {...eqProfile.customOwned};
    limitationFlags = {...s.limitationProfile.flags};
    guidanceMode = s.guidanceModeEnum;
  }

  @override
  void dispose() {
    weight.dispose();
    height.dispose();
    age.dispose();
    goal.dispose();
    equipment.dispose();
    limitations.dispose();
    workHours.dispose();
    super.dispose();
  }

  /// Nagłówek sekcji formularza profilu (ikona + tytuł + opis).
  Widget _sectionHeader(
      ThemeData theme, IconData icon, String title, String subtitle) {
    return Row(
      children: [
        Icon(icon, size: 20, color: theme.colorScheme.primary),
        const SizedBox(width: 8),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(title,
                  style: theme.textTheme.titleSmall
                      ?.copyWith(fontWeight: FontWeight.w900)),
              Text(subtitle,
                  style: theme.textTheme.labelSmall
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            ],
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    // Kolor akcentu mieszka w „Wygląd aplikacji" (motywy), a backend AI jest
    // stały (adres widać w Diagnostyce) — profil zawiera tylko dane treningowe.
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // === Twoje dane ===
            _sectionHeader(theme, Icons.person_outline_rounded, 'Twoje dane',
                'Zasilają regenerację, kcal i utratę wody'),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                  child: TextField(
                      controller: weight,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                          labelText: 'Waga (kg)',
                          prefixIcon: Icon(Icons.monitor_weight_outlined)))),
              const SizedBox(width: 10),
              Expanded(
                  child: TextField(
                      controller: height,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                          labelText: 'Wzrost (cm)',
                          prefixIcon: Icon(Icons.height_rounded)))),
            ]),
            const SizedBox(height: 10),
            Row(children: [
              Expanded(
                  child: TextField(
                      controller: age,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(
                          labelText: 'Wiek',
                          prefixIcon: Icon(Icons.cake_outlined)))),
              const SizedBox(width: 10),
              Expanded(
                child: DropdownButtonFormField<String>(
                  key: ValueKey('sex_$sex'),
                  isExpanded: true,
                  initialValue: sex,
                  decoration: const InputDecoration(labelText: 'Płeć'),
                  items: _sexOptions
                      .map((v) => DropdownMenuItem(
                          value: v,
                          child: Text(v,
                              maxLines: 1, overflow: TextOverflow.ellipsis)))
                      .toList(),
                  onChanged: (v) => setState(() => sex = v ?? sex),
                ),
              ),
            ]),

            // === Praca i aktywność ogólna ===
            const SizedBox(height: 18),
            _sectionHeader(
              theme,
              Icons.work_outline_rounded,
              'Praca i aktywność ogólna',
              'Fallback, gdy zegarek nie zarejestruje ruchu w pracy',
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                Expanded(
                  flex: 3,
                  child: DropdownButtonFormField<String>(
                    key: ValueKey('work_intensity_$workIntensity'),
                    isExpanded: true,
                    initialValue: workIntensity,
                    decoration: const InputDecoration(
                      labelText: 'Charakter pracy',
                      prefixIcon: Icon(Icons.badge_outlined),
                    ),
                    items: _workIntensityLabels.entries
                        .map((entry) => DropdownMenuItem<String>(
                              value: entry.key,
                              child: Text(
                                entry.value,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                              ),
                            ))
                        .toList(),
                    onChanged: (value) => setState(
                      () => workIntensity = value ?? workIntensity,
                    ),
                  ),
                ),
                const SizedBox(width: 10),
                Expanded(
                  flex: 2,
                  child: TextField(
                    controller: workHours,
                    keyboardType: const TextInputType.numberWithOptions(
                      decimal: true,
                    ),
                    decoration: const InputDecoration(
                      labelText: 'Godzin/dzień',
                      prefixIcon: Icon(Icons.schedule_outlined),
                    ),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 6,
              runSpacing: 4,
              children: [
                for (final entry in const <int, String>{
                  1: 'Pn',
                  2: 'Wt',
                  3: 'Śr',
                  4: 'Cz',
                  5: 'Pt',
                  6: 'So',
                  7: 'Nd',
                }.entries)
                  FilterChip(
                    label: Text(entry.value),
                    selected: workWeekdays.contains(entry.key),
                    onSelected: (selected) => setState(() {
                      if (selected) {
                        workWeekdays.add(entry.key);
                      } else {
                        workWeekdays.remove(entry.key);
                      }
                    }),
                  ),
              ],
            ),
            const SizedBox(height: 4),
            Text(
              'Praca nie jest dodawana do kroków ani danych zegarka. Trainer '
              'wybiera wyższy, wiarygodniejszy szacunek, aby nie liczyć jej dwa razy.',
              style: theme.textTheme.labelSmall
                  ?.copyWith(color: theme.colorScheme.onSurfaceVariant),
            ),

            // === Poziom i cel ===
            const SizedBox(height: 18),
            _sectionHeader(theme, Icons.flag_outlined, 'Poziom i cel',
                'Dopasowują programy 30-dniowe i progresję'),
            const SizedBox(height: 12),
            DropdownButtonFormField<String>(
              isExpanded: true,
              value: level,
              decoration: const InputDecoration(
                  labelText: 'Poziom zaawansowania',
                  prefixIcon: Icon(Icons.workspace_premium_outlined)),
              selectedItemBuilder: (context) => kTrainingLevels
                  .map((v) => Align(
                      alignment: Alignment.centerLeft,
                      child: Text(v,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              items: kTrainingLevels
                  .map((v) => DropdownMenuItem(
                      value: v,
                      child: Text(v,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              onChanged: (v) => setState(() => level = v ?? level),
            ),
            const SizedBox(height: 10),
            DropdownButtonFormField<String>(
              isExpanded: true,
              value: trainingMode,
              decoration: const InputDecoration(
                labelText: 'Strategia składu ciała',
                helperText:
                    'Redukcja/masa/rekompozycja to strategia, nie typ treningu',
                prefixIcon: Icon(Icons.tune_rounded),
              ),
              selectedItemBuilder: (context) => kTrainingModes
                  .map((v) => Align(
                      alignment: Alignment.centerLeft,
                      child: Text(v,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              items: kTrainingModes
                  .map((v) => DropdownMenuItem(
                      value: v,
                      child: Text(v,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              onChanged: (v) =>
                  setState(() => trainingMode = v ?? trainingMode),
            ),
            const SizedBox(height: 6),
            OutlinedButton.icon(
              key: const Key('open_goal_profile_from_settings'),
              onPressed: () => Navigator.of(context).push(
                MaterialPageRoute<void>(
                    builder: (_) => const BodyGoalProfilePage()),
              ),
              icon: const Icon(Icons.flag_rounded, size: 18),
              label:
                  const Text('Profil celu: sylwetka, strategia, typ treningu'),
            ),
            const SizedBox(height: 10),
            TextField(
                controller: goal,
                maxLines: 2,
                decoration: const InputDecoration(
                    labelText: 'Cel treningowy (np. sylwetka, siła, kondycja)',
                    prefixIcon: Icon(Icons.emoji_events_outlined))),

            // === Tryb prowadzenia treningu (inteligentny trener) ===
            const SizedBox(height: 18),
            _sectionHeader(
                theme,
                Icons.auto_awesome_rounded,
                'Prowadzenie treningu',
                'Ile Trainer ustala za Ciebie podczas serii'),
            const SizedBox(height: 12),
            DropdownButtonFormField<GuidanceMode>(
              key: const Key('guidance_mode_dropdown'),
              isExpanded: true,
              initialValue: guidanceMode,
              decoration: const InputDecoration(
                  labelText: 'Tryb prowadzenia',
                  prefixIcon: Icon(Icons.assistant_direction_outlined)),
              selectedItemBuilder: (context) => GuidanceMode.values
                  .map((m) => Align(
                      alignment: Alignment.centerLeft,
                      child: Text(m.label,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              items: GuidanceMode.values
                  .map((m) => DropdownMenuItem(
                      value: m,
                      child: Text(m.label,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              onChanged: (v) =>
                  setState(() => guidanceMode = v ?? guidanceMode),
            ),
            const SizedBox(height: 4),
            Text(guidanceMode.description,
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),

            // === Sprzęt i ograniczenia (strukturalne — steruje doborem ćwiczeń) ===
            const SizedBox(height: 18),
            _sectionHeader(theme, Icons.build_outlined, 'Sprzęt i ograniczenia',
                'Programy używają tylko ćwiczeń pod Twój sprzęt'),
            const SizedBox(height: 12),
            DropdownButtonFormField<EquipmentMode>(
              key: const Key('equipment_mode_dropdown'),
              isExpanded: true,
              initialValue: equipmentMode,
              decoration: const InputDecoration(
                  labelText: 'Tryb sprzętowy',
                  prefixIcon: Icon(Icons.fitness_center_rounded)),
              selectedItemBuilder: (context) => EquipmentMode.values
                  .map((m) => Align(
                      alignment: Alignment.centerLeft,
                      child: Text(m.label,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              items: EquipmentMode.values
                  .map((m) => DropdownMenuItem(
                      value: m,
                      child: Text(m.label,
                          maxLines: 1, overflow: TextOverflow.ellipsis)))
                  .toList(),
              onChanged: (v) => setState(() {
                if (v == null) return;
                equipmentMode = v;
                // Przy przejściu na tryb wybieralny zasil sensownym startem.
                if (v == EquipmentMode.homeMixed && ownedEquipment.isEmpty) {
                  ownedEquipment = {...kDefaultHomeMixedEquipment};
                } else if (v == EquipmentMode.custom &&
                    ownedEquipment.isEmpty) {
                  ownedEquipment = {
                    ...widget.settings.equipmentProfile.resolveOwned()
                  }..removeAll(kAlwaysAvailableEquipment);
                }
              }),
            ),
            const SizedBox(height: 4),
            Text(equipmentMode.description,
                style: theme.textTheme.labelSmall
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            if (equipmentMode.isUserSelectable) ...[
              const SizedBox(height: 10),
              Wrap(
                spacing: 8,
                runSpacing: 4,
                children: [
                  for (final type in _selectableEquipment)
                    FilterChip(
                      label: Text(type.label),
                      selected: ownedEquipment.contains(type),
                      onSelected: (sel) => setState(() {
                        if (sel) {
                          ownedEquipment.add(type);
                        } else {
                          ownedEquipment.remove(type);
                        }
                      }),
                    ),
                ],
              ),
            ],
            const SizedBox(height: 14),
            Text('Ograniczenia i kontuzje',
                style: theme.textTheme.titleSmall
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 6),
            Wrap(
              spacing: 8,
              runSpacing: 4,
              children: [
                for (final limit in TrainingLimitation.values)
                  FilterChip(
                    label: Text(limit.label),
                    selected: limitationFlags.contains(limit),
                    onSelected: (sel) => setState(() {
                      if (sel) {
                        limitationFlags.add(limit);
                      } else {
                        limitationFlags.remove(limit);
                      }
                    }),
                  ),
              ],
            ),
            const SizedBox(height: 10),
            TextField(
                controller: limitations,
                maxLines: 2,
                decoration: const InputDecoration(
                    labelText: 'Własne ograniczenie (opcjonalnie)',
                    prefixIcon: Icon(Icons.healing_outlined))),

            const SizedBox(height: 16),
            FilledButton.icon(
              onPressed: () async {
                final profile = EquipmentProfile(
                    mode: equipmentMode, customOwned: ownedEquipment);
                // Zapisujemy też czytelny tekst sprzętu (dla AI i zgodności wstecznej).
                final equipmentText = equipmentMode == EquipmentMode.fullGym
                    ? 'pełna siłownia'
                    : profile.ownedSummary;
                final next = widget.settings.copyWith(
                  backendUrl: kDefaultBackendUrl,
                  bodyWeightKg:
                      double.tryParse(weight.text.replaceAll(',', '.')) ??
                          widget.settings.bodyWeightKg,
                  heightCm: double.tryParse(height.text.replaceAll(',', '.')) ??
                      widget.settings.heightCm,
                  age: int.tryParse(age.text) ?? widget.settings.age,
                  sex: sex == 'Nie podano' ? '' : sex,
                  goal: goal.text.trim().isEmpty
                      ? widget.settings.goal
                      : goal.text.trim(),
                  equipment: equipmentText,
                  limitations: limitations.text.trim(),
                  equipmentModeKey: equipmentMode.key,
                  ownedEquipmentKeys: ownedEquipment.map((e) => e.key).toList(),
                  limitationFlagKeys:
                      limitationFlags.map((e) => e.key).toList(),
                  guidanceMode: guidanceMode.key,
                  level: level,
                  trainingMode: trainingMode,
                  workIntensity: workIntensity,
                  workHoursPerDay: (double.tryParse(
                            workHours.text.replaceAll(',', '.'),
                          ) ??
                          widget.settings.workHoursPerDay)
                      .clamp(0.0, 16.0)
                      .toDouble(),
                  workWeekdays: workWeekdays.toList()..sort(),
                );
                await widget.onSave(next);
                if (!context.mounted) return;
                showError(context, 'Zapisano profil Trainer');
                // Po zmianie sprzętu/ograniczeń zaproponuj dostosowanie
                // rozpoczętych programów (postęp zachowany).
                await offerEquipmentReadjustForActivePlans(context);
              },
              icon: const Icon(Icons.save),
              label: const Text('Zapisz profil'),
            ),
          ],
        ),
      ),
    );
  }
}

