class PersonalRecordsCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  final List<Exercise> customExercises;

  const PersonalRecordsCard(
      {super.key, required this.logs, required this.customExercises});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final bestWeight = <String, WorkoutLog>{};
    final bestVolume = <String, WorkoutLog>{};
    for (final log in logs) {
      final w = bestWeight[log.exerciseId];
      if (w == null || log.weightKg > w.weightKg)
        bestWeight[log.exerciseId] = log;
      final v = bestVolume[log.exerciseId];
      if (v == null || log.volume > v.volume) bestVolume[log.exerciseId] = log;
    }
    final weightList = bestWeight.values.toList()
      ..sort((a, b) => b.weightKg.compareTo(a.weightKg));
    final volumeList = bestVolume.values.toList()
      ..sort((a, b) => b.volume.compareTo(a.volume));
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(children: [
              Icon(Icons.emoji_events_outlined,
                  color: theme.colorScheme.primary),
              const SizedBox(width: 8),
              Expanded(
                  child: Text('Rekordy osobiste',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)))
            ]),
            const SizedBox(height: 10),
            if (logs.isEmpty)
              Text(
                  'Dodaj kilka treningów, a Trainer pokaże rekordy ciężaru i objętości.',
                  style: theme.textTheme.bodyMedium
                      ?.copyWith(color: theme.colorScheme.onSurfaceVariant))
            else ...[
              Text('Największy ciężar',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              ...weightList.take(3).map((log) => RecordRow(
                  log: log,
                  customExercises: customExercises,
                  value: '${log.weightKg.toStringAsFixed(1)} kg')),
              const SizedBox(height: 8),
              Text('Największa objętość',
                  style: theme.textTheme.labelLarge
                      ?.copyWith(fontWeight: FontWeight.w900)),
              const SizedBox(height: 6),
              ...volumeList.take(3).map((log) => RecordRow(
                  log: log,
                  customExercises: customExercises,
                  value: '${log.volume.round()} kg')),
            ],
          ],
        ),
      ),
    );
  }
}

class RecordRow extends StatelessWidget {
  final WorkoutLog log;
  final List<Exercise> customExercises;
  final String value;

  const RecordRow(
      {super.key,
      required this.log,
      required this.customExercises,
      required this.value});

  @override
  Widget build(BuildContext context) {
    final e = log.exerciseFrom(customExercises);
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Row(
        children: [
          Expanded(
              child:
                  Text(e.name, maxLines: 1, overflow: TextOverflow.ellipsis)),
          const SizedBox(width: 8),
          Text(value, style: const TextStyle(fontWeight: FontWeight.w900)),
        ],
      ),
    );
  }
}

class WeeklyBalanceCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  final List<Exercise> customExercises;

  const WeeklyBalanceCard(
      {super.key, required this.logs, required this.customExercises});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final counts = muscleCounts(logs, customExercises);
    final entries = counts.entries.toList()
      ..sort((a, b) => b.value.compareTo(a.value));
    final warning =
        entries.isEmpty ? 'Brak danych z tygodnia.' : balanceWarning(entries);
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(children: [
              Icon(Icons.balance_outlined, color: theme.colorScheme.primary),
              const SizedBox(width: 8),
              Expanded(
                  child: Text('Tygodniowy balans partii',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)))
            ]),
            const SizedBox(height: 10),
            Text(warning,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(color: theme.colorScheme.onSurfaceVariant)),
            const SizedBox(height: 10),
            ...entries.take(8).map((e) => ProgressTextBar(
                label: e.key,
                value: e.value.toDouble(),
                max: math.max(1, entries.first.value).toDouble(),
                suffix: '${e.value}×')),
          ],
        ),
      ),
    );
  }
}

class MonthlySummaryCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  final List<Exercise> customExercises;

  const MonthlySummaryCard(
      {super.key, required this.logs, required this.customExercises});

  @override
  Widget build(BuildContext context) {
    final totals = DayTotals.from(logs);
    final theme = Theme.of(context);
    final days = logs
        .map((e) =>
            DateTime(e.date.year, e.date.month, e.date.day).toIso8601String())
        .toSet()
        .length;
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(children: [
              Icon(Icons.calendar_view_month_outlined,
                  color: theme.colorScheme.primary),
              const SizedBox(width: 8),
              Expanded(
                  child: Text('Podsumowanie miesiąca',
                      style: theme.textTheme.titleMedium
                          ?.copyWith(fontWeight: FontWeight.w900)))
            ]),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(child: SmallMetric(label: 'Dni', value: '$days')),
              const SizedBox(width: 8),
              Expanded(
                  child:
                      SmallMetric(label: 'Wpisy', value: '${totals.sessions}')),
            ]),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(
                  child: SmallMetric(
                      label: 'Czas',
                      value: '${(totals.durationSec / 60).round()} min')),
              const SizedBox(width: 8),
              Expanded(
                  child: SmallMetric(
                      label: 'Objętość', value: '${totals.volume.round()} kg')),
            ]),
          ],
        ),
      ),
    );
  }
}

class RecoveryCoachCard extends StatelessWidget {
  final List<WorkoutLog> logs;

  const RecoveryCoachCard({super.key, required this.logs});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final avgRpe = logs.isEmpty
        ? 0.0
        : logs.fold<double>(0, (a, e) => a + e.rpe) / logs.length;
    final minutes = logs.fold<int>(0, (a, e) => a + e.durationSec) ~/ 60;
    final advice = avgRpe >= 8.2 || minutes > 420
        ? 'W tym tygodniu intensywność jest wysoka. Rozważ lżejszą sesję, sen i mobilizację.'
        : avgRpe >= 6.5
            ? 'Obciążenie wygląda sensownie. Pilnuj progresji, ale nie dokładaj wszystkiego naraz.'
            : 'Tydzień wygląda lekko. To dobry moment na technikę, ruchomość albo spokojny progres.';
    return Card(
      child: ListTile(
        leading: Icon(Icons.self_improvement_outlined,
            color: theme.colorScheme.primary),
        title: const Text('Ocena regeneracji'),
        subtitle: Text(
            '$advice\nŚrednie RPE: ${avgRpe.toStringAsFixed(1)} · czas tygodnia: $minutes min'),
        isThreeLine: true,
      ),
    );
  }
}

class StagnationDetectorCard extends StatelessWidget {
  final List<WorkoutLog> logs;

  const StagnationDetectorCard({super.key, required this.logs});

  @override
  Widget build(BuildContext context) {
    final now = DateTime.now();
    final last = DayTotals.from(logs
        .where((e) => !e.date.isBefore(now.subtract(const Duration(days: 6))))
        .toList());
    final prev = DayTotals.from(logs
        .where((e) =>
            e.date.isBefore(now.subtract(const Duration(days: 6))) &&
            !e.date.isBefore(now.subtract(const Duration(days: 13))))
        .toList());
    final theme = Theme.of(context);
    final text = prev.volume <= 0
        ? 'Potrzeba jeszcze danych z minimum dwóch tygodni, żeby ocenić stagnację.'
        : last.volume < prev.volume * 0.8
            ? 'Objętość spadła mocno względem poprzedniego tygodnia. Sprawdź sen, stres i plan.'
            : last.volume > prev.volume * 1.25
                ? 'Objętość mocno wzrosła. Uważaj na regenerację i technikę.'
                : 'Objętość tygodniowa jest stabilna. Możesz progresować małymi krokami.';
    return Card(
      child: ListTile(
        leading:
            Icon(Icons.trending_up_outlined, color: theme.colorScheme.primary),
        title: const Text('Wykrywanie stagnacji'),
        subtitle: Text(text),
      ),
    );
  }
}

