class ProgressTextBar extends StatelessWidget {
  final String label;
  final double value;
  final double max;
  final String suffix;

  const ProgressTextBar(
      {super.key,
      required this.label,
      required this.value,
      required this.max,
      required this.suffix});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final ratio = max <= 0 ? 0.0 : (value / max).clamp(0.0, 1.0);
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Expanded(
              child: Text(label, maxLines: 1, overflow: TextOverflow.ellipsis)),
          Text(suffix, style: const TextStyle(fontWeight: FontWeight.w900))
        ]),
        const SizedBox(height: 5),
        ClipRRect(
          borderRadius: BorderRadius.circular(99),
          child: LinearProgressIndicator(
              value: ratio,
              minHeight: 8,
              backgroundColor: theme.colorScheme.surfaceContainerHighest),
        ),
      ]),
    );
  }
}

Map<String, int> muscleCounts(
    List<WorkoutLog> logs, List<Exercise> customExercises) {
  // Liczymy po KANONICZNYCH partiach ([BodyMuscle]), a nie po surowych
  // etykietach z pola `muscles`. Wcześniej „Triceps (głowa długa)", „triceps"
  // czy fragmenty typu „boczna"/„przyśrodkowa" trafiały jako osobne pozycje
  // (użytkownik widział np. „Triceps (głowa długa)" dwa razy). Kanoniczny enum
  // eliminuje takie duplikaty z definicji.
  final counts = <String, int>{};
  for (final log in logs) {
    final exercise = log.exerciseFrom(customExercises);
    final seen = <BodyMuscle>{};
    for (final impact in exercise.effectiveMuscleImpacts) {
      if (impact.role == MuscleRole.stabilizer) continue;
      if (!seen.add(impact.muscleGroup))
        continue; // ta sama partia raz na ćwiczenie
      counts[impact.muscleGroup.label] =
          (counts[impact.muscleGroup.label] ?? 0) + 1;
      if (seen.length >= 3) break; // jak wcześniej: do 3 głównych partii
    }
  }
  return counts;
}

DateTime startOfTrainingWeek(DateTime date) {
  final day = DateTime(date.year, date.month, date.day);
  return day.subtract(Duration(days: day.weekday - DateTime.monday));
}

String weekdayShortName(int weekday) {
  const names = {
    DateTime.monday: 'Pn',
    DateTime.tuesday: 'Wt',
    DateTime.wednesday: 'Śr',
    DateTime.thursday: 'Cz',
    DateTime.friday: 'Pt',
    DateTime.saturday: 'So',
    DateTime.sunday: 'Nd',
  };
  return names[weekday] ?? 'D';
}

int workoutEntryCount(List<WorkoutLog> logs) {
  final sorted = [...logs]..sort((a, b) => b.date.compareTo(a.date));
  return _groupTrainerWorkoutHistory(sorted).length;
}

int completedWorkoutSetCount(List<WorkoutLog> logs) {
  return logs.fold<int>(
    0,
    (sum, log) =>
        sum +
        (log.workoutSets.isEmpty
            ? log.sets
            : log.workoutSets.where((set) => set.isCompleted).length),
  );
}

String formatProgressVolume(double volume) {
  if (volume >= 10000) return '${(volume / 1000).toStringAsFixed(1)}k kg';
  return '${volume.round()} kg';
}

String balanceWarning(List<MapEntry<String, int>> entries) {
  if (entries.length < 2)
    return 'Tydzień jednostronny albo za mało danych. Dodaj więcej partii do balansu.';
  final top = entries.first;
  final low = entries.last;
  if (top.value >= low.value * 3 && top.value >= 3)
    return 'Dominuje: ${top.key}. Najmniej: ${low.key}. Rozważ wyrównanie planu.';
  return 'Balans wygląda zdrowo. Pilnuj, żeby żadna partia nie znikała z planu na dłużej.';
}

int workoutStreak(List<WorkoutLog> logs) {
  final days = logs
      .map((e) =>
          DateTime(e.date.year, e.date.month, e.date.day).toIso8601String())
      .toSet();
  var streak = 0;
  var d = DateTime.now();
  while (days.contains(DateTime(d.year, d.month, d.day).toIso8601String())) {
    streak++;
    d = d.subtract(const Duration(days: 1));
  }
  return streak;
}

