class BodyHeatMapPainter extends CustomPainter {
  final Map<String, int> counts;
  final int maxValue;
  final Color color;
  BodyHeatMapPainter(
      {required this.counts, required this.maxValue, required this.color});
  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()..color = color.withOpacity(.16);
    canvas.drawRRect(
        RRect.fromRectAndRadius(Offset.zero & size, const Radius.circular(24)),
        p);
    double a(String key) => ((counts.entries
                .where((e) => e.key.toLowerCase().contains(key))
                .fold<int>(0, (a, e) => a + e.value)) /
            math.max(1, maxValue))
        .clamp(.12, 1.0)
        .toDouble();
    void part(Rect r, String key) => canvas.drawRRect(
        RRect.fromRectAndRadius(r, const Radius.circular(30)),
        Paint()..color = color.withOpacity(a(key)));
    final w = size.width, h = size.height;
    part(
        Rect.fromCenter(center: Offset(w * .5, h * .18), width: 42, height: 42),
        '');
    part(
        Rect.fromCenter(center: Offset(w * .5, h * .37), width: 74, height: 92),
        'brzuch');
    part(
        Rect.fromCenter(
            center: Offset(w * .31, h * .34), width: 44, height: 98),
        'bark');
    part(
        Rect.fromCenter(
            center: Offset(w * .69, h * .34), width: 44, height: 98),
        'bark');
    part(
        Rect.fromCenter(
            center: Offset(w * .4, h * .72), width: 48, height: 118),
        'uda');
    part(
        Rect.fromCenter(
            center: Offset(w * .6, h * .72), width: 48, height: 118),
        'uda');
  }

  @override
  bool shouldRepaint(covariant BodyHeatMapPainter oldDelegate) =>
      oldDelegate.counts != counts || oldDelegate.color != color;
}

