class StreakChartCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  const StreakChartCard({super.key, required this.logs});
  @override
  Widget build(BuildContext context) {
    final today = DateTime.now();
    final days = List.generate(
        14,
        (i) => DateTime(today.year, today.month, today.day)
            .subtract(Duration(days: 13 - i)));
    final trained = logs
        .map((e) =>
            DateTime(e.date.year, e.date.month, e.date.day).toIso8601String())
        .toSet();
    final values = days
        .map((d) => trained.contains(d.toIso8601String()) ? 1.0 : 0.0)
        .toList();
    return ChartCard(
        title: 'Wykres streaku treningowego', values: values, suffix: 'dzień');
  }
}

class ProgressByExerciseCard extends StatelessWidget {
  final List<WorkoutLog> logs;
  final List<Exercise> customExercises;
