      {super.key, required this.logs, required this.customExercises});
  @override
  Widget build(BuildContext context) {
    final by = <String, List<WorkoutLog>>{};
    for (final l in logs) {
      by.putIfAbsent(l.exerciseId, () => []).add(l);
    }
    final entries = by.entries.toList()
      ..sort((a, b) => b.value.length.compareTo(a.value.length));
    return Card(
        child: Padding(
            padding: const EdgeInsets.all(16),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Progres ćwiczenia: ciężar, powtórzenia, objętość',
                  style: TextStyle(fontWeight: FontWeight.w900)),
              const SizedBox(height: 10),
              if (entries.isEmpty)
                const Text('Brak danych')
              else
                ...entries.take(5).map((e) {
                  final ex = ExerciseRepo.byId(e.key, customExercises);
                  final best =
                      e.value.reduce((a, b) => a.volume >= b.volume ? a : b);
                  return ListTile(
                      contentPadding: EdgeInsets.zero,
                      title: Text(ex.name),
                      subtitle: Text(
                          'Najlepsza objętość: ${best.volume.round()} kg · ciężar ${best.weightKg.toStringAsFixed(1)} kg · powt. ${best.reps}'));
                })
            ])));
  }
}

