    super.initState();
    final exercise = widget.exercise;
    mediaItems = List<ExerciseMedia>.from(
        exercise?.mediaItems ?? const <ExerciseMedia>[]);
    _mediaExpanded = mediaItems.isNotEmpty;
    _muscleRoles = {
      for (final impact in (exercise?.effectiveMuscleImpacts ??
          const <ExerciseMuscleImpact>[]))
        impact.muscleGroup: impact.role,
    };
    _musclesExpanded = _muscleRoles.isNotEmpty;
    name = TextEditingController(text: exercise?.name ?? '');
    category = TextEditingController(text: exercise?.category ?? 'Inne');
    primaryMuscle = TextEditingController(
      text: exercise?.primaryMuscle ?? 'całe ciało',
    );
    supportingMuscles = TextEditingController(
      text: exercise?.supportingMuscles.join(', ') ?? '',
    );
    equipment = TextEditingController(
      text: exercise?.equipment ?? 'masa ciała',
    );
    description = TextEditingController(text: exercise?.description ?? '');
    tips = TextEditingController(text: exercise?.tips.join('\n') ?? '');
    commonMistakes = TextEditingController(
      text: exercise?.commonMistakes.join('\n') ?? '',
    );
    avoidWhen = TextEditingController(
      text: exercise?.avoidWhen.join('\n') ?? '',
    );
    alternatives = TextEditingController(
      text: exercise?.alternatives.join('\n') ?? '',
    );
    level = normalizeLevel(exercise?.level ?? 'Początkujący');
    selectedGoals.addAll(
      exercise?.typedTrainingGoals ?? const <TrainingGoal>{},
    );
    if (selectedGoals.isEmpty) {
      selectedGoals.addAll({
        TrainingGoal.strength,
        TrainingGoal.muscleGain,
      });
    }
  }

  @override
  void dispose() {
    name.dispose();
    category.dispose();
    primaryMuscle.dispose();
    supportingMuscles.dispose();
    equipment.dispose();
    description.dispose();
    tips.dispose();
    commonMistakes.dispose();
    avoidWhen.dispose();
    alternatives.dispose();
    super.dispose();
  }

  Future<void> save() async {
    if (!(formKey.currentState?.validate() ?? false)) return;
    final original = widget.exercise;
    final supporting = _splitExerciseField(supportingMuscles.text);
    final primary = primaryMuscle.text.trim();
    final parsedTips = _splitExerciseField(tips.text);
    final parsedMistakes = _splitExerciseField(commonMistakes.text);
    final parsedAvoidWhen = _splitExerciseField(avoidWhen.text);
    final parsedAlternatives = _splitExerciseField(alternatives.text);
    final exerciseId = original?.id ?? 'custom_${idNow()}';
    // Etap 27: przypisz multimedia do tego ćwiczenia (spójne exerciseId).
    final savedMedia = mediaItems
        .map((media) => media.copyWith(exerciseId: exerciseId))
        .toList();
    final ex = Exercise(
      id: exerciseId,
      name: name.text.trim(),
      category: category.text.trim().isEmpty ? 'Inne' : category.text.trim(),
      muscles: [
        primary,
        ...supporting.where(
          (muscle) => muscle.toLowerCase() != primary.toLowerCase(),
        ),
      ],
      equipment:
          equipment.text.trim().isEmpty ? 'masa ciała' : equipment.text.trim(),
      level: level,
      illustrationType: original?.illustrationType ?? 'generic',
      description: description.text.trim().isEmpty
          ? 'Własne ćwiczenie użytkownika.'
          : description.text.trim(),
      tips: parsedTips.isEmpty
          ? const [
              'Zacznij od lekkiej wersji.',
              'Kontroluj ruch w całym zakresie.',
            ]
          : parsedTips,
      commonMistakes: parsedMistakes.isEmpty
          ? const [
              'Za szybkie tempo.',
              'Za duży ciężar.',
              'Brak kontroli zakresu.',
            ]
          : parsedMistakes,
      defaultSets: original?.defaultSets ?? 3,
      defaultReps: original?.defaultReps ?? 10,
      defaultDurationSec: original?.defaultDurationSec ?? 0,
      met: original?.met ?? 4.5,
      trainingGoals: selectedGoals.map((goal) => goal.label).toList(),
      avoidWhen: parsedAvoidWhen,
      alternatives: parsedAlternatives,
      executionSteps: original?.executionSteps ?? const [],
      breathing: original?.breathing ?? '',
      tempo: original?.tempo ?? '',
      easierVersion: original?.easierVersion ?? '',
      harderVersion: original?.harderVersion ?? '',
      imageUrl: original?.imageUrl,
      imagePath: original?.imagePath,
      thumbnailPath: original?.thumbnailPath,
      gifPath: original?.gifPath,
      animationAssetPath: original?.animationAssetPath,
      videoPath: original?.videoPath,
      videoUrl: original?.videoUrl,
      mediaItems: savedMedia,
      muscleImpacts: [
        for (final entry in _muscleRoles.entries)
          ExerciseMuscleImpact(muscleGroup: entry.key, role: entry.value),
      ],
      source: original == null
          ? 'custom'
          : original.source == 'local'
              ? 'edited'
              : original.source,
    );
    await widget.store.addCustomExercise(ex);
    if (!mounted) return;
    Navigator.of(context).pop();
  }

  // ===== Etap 2: generowanie opisu ćwiczenia przez Gemini =====

  /// Generuje opis przez Gemini na podstawie nazwy/kategorii/sprzętu, pokazuje
  /// edytowalny podgląd i — po zatwierdzeniu — wypełnia pola formularza.
  /// Nic nie nadpisuje bez podglądu i zgody użytkownika.
  Future<void> _generateWithGemini() async {
    if (_generatingDescription) return;
    final exName = name.text.trim();
    if (exName.isEmpty) {
      showError(context, 'Najpierw wpisz nazwę ćwiczenia.');
      return;
    }
    final store = widget.store;
    final hasKey = await ensureGeminiApiKey(context, store);
    if (!hasKey || !mounted) return;
    setState(() => _generatingDescription = true);
    final probe = Exercise(
      id: widget.exercise?.id ?? 'probe',
      name: exName,
      category: category.text.trim().isEmpty ? 'Inne' : category.text.trim(),
      muscles: const ['całe ciało'],
      equipment:
          equipment.text.trim().isEmpty ? 'masa ciała' : equipment.text.trim(),
      level: level,
      illustrationType: 'generic',
      description: '',
      tips: const [],
      commonMistakes: const [],
      defaultSets: 3,
      defaultReps: 10,
      defaultDurationSec: 0,
      met: 4.5,
    );
    GeneratedExerciseInfo generated;
    try {
      generated = await store.generateExerciseDescriptionWithGemini(probe);
    } catch (error) {
      if (!mounted) return;
      setState(() => _generatingDescription = false);
      showError(context,
          'Nie udało się wygenerować opisu: ${friendlyAiErrorMessage(error)}');
      return;
    }
    if (!mounted) return;
    setState(() => _generatingDescription = false);
    final hasExisting =
        description.text.trim().isNotEmpty || tips.text.trim().isNotEmpty;
    final approved = await showGeminiExercisePreviewSheet(
      context,
      generated: generated,
      exerciseName: exName,
      hasExistingContent: hasExisting,
    );
    if (approved == null || !mounted) return;
    setState(() {
      if (approved.description.trim().isNotEmpty)
        description.text = approved.description.trim();
      if (approved.tips.isNotEmpty) tips.text = approved.tips.join('\n');
      if (approved.commonMistakes.isNotEmpty)
        commonMistakes.text = approved.commonMistakes.join('\n');
      if (approved.primaryMuscles.isNotEmpty)
        primaryMuscle.text = approved.primaryMuscles.first;
      if (approved.secondaryMuscles.isNotEmpty)
        supportingMuscles.text = approved.secondaryMuscles.join(', ');
      if (approved.equipment.trim().isNotEmpty)
        equipment.text = approved.equipment.trim();
      if (approved.level.trim().isNotEmpty)
        level = normalizeLevel(approved.level);
      if (approved.safetyNotes.isNotEmpty)
        avoidWhen.text = approved.safetyNotes.join('\n');
      final roles = <BodyMuscle, MuscleRole>{};
      for (final muscleName in approved.primaryMuscles) {
        final muscle = BodyMuscle.fromText(muscleName);
        if (muscle != null) roles[muscle] = MuscleRole.primary;
      }
      for (final muscleName in approved.secondaryMuscles) {
        final muscle = BodyMuscle.fromText(muscleName);
        if (muscle != null)
          roles.putIfAbsent(muscle, () => MuscleRole.secondary);
      }
      if (roles.isNotEmpty) {
        _muscleRoles = roles;
        _musclesExpanded = true;
      }
    });
  }

  Future<bool> _ensureOpenAiApiKey() async {
    final store = widget.store;
    if (store.settings.openAiApiKey.trim().isNotEmpty) return true;
    final controller = TextEditingController();
    final accepted = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Klucz API OpenAI'),
        content: TextField(
          controller: controller,
          obscureText: true,
          autofocus: true,
          decoration: const InputDecoration(labelText: 'sk-...'),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(dialogContext, false),
              child: const Text('Anuluj')),
          FilledButton(
              onPressed: () => Navigator.pop(dialogContext, true),
              child: const Text('Zapisz klucz')),
        ],
      ),
    );
    final key = controller.text.trim();
    controller.dispose();
    if (accepted != true || key.isEmpty) return false;
    await store.updateSettings(store.settings.copyWith(openAiApiKey: key));
    return true;
  }

  /// Generuje obraz jeszcze przed zapisaniem nowego ćwiczenia i dodaje go do
  /// roboczej galerii formularza. Dzięki temu zapis ćwiczenia i obrazu jest
  /// jedną operacją z perspektywy użytkownika.
  Future<void> _generateImageWithAi() async {
    if (_generatingImage) return;
    final exName = name.text.trim();
    if (exName.isEmpty) {
      showError(context, 'Najpierw wpisz nazwę ćwiczenia.');
      return;
    }
    if (!await _ensureOpenAiApiKey() || !mounted) return;
    setState(() => _generatingImage = true);
    try {
      final muscles = <String>[
        primaryMuscle.text.trim(),
        ..._splitExerciseField(supportingMuscles.text),
      ].where((item) => item.isNotEmpty).toList();
      final probe = Exercise(
        id: widget.exercise?.id ?? 'custom_${idNow()}',
        name: exName,
        category: category.text.trim().isEmpty ? 'Inne' : category.text.trim(),
        muscles: muscles.isEmpty ? const ['całe ciało'] : muscles,
        equipment: equipment.text.trim().isEmpty
            ? 'masa ciała'
            : equipment.text.trim(),
        level: level,
        illustrationType: widget.exercise?.illustrationType ?? 'generic',
        description: description.text.trim(),
        tips: const [],
        commonMistakes: const [],
        defaultSets: 3,
        defaultReps: 10,
        defaultDurationSec: 0,
        met: 4.5,
      );
      final bytes = await OpenAiImageService(widget.store.settings.openAiApiKey)
          .generateExerciseImage(probe);
      final documents = await getApplicationDocumentsDirectory();
      final imagesDir = Directory('${documents.path}/exercise_images');
      await imagesDir.create(recursive: true);
      final file = File('${imagesDir.path}/${probe.id}_${idNow()}.png');
      await file.writeAsBytes(bytes, flush: true);
      if (!mounted) return;
      _appendMedia(
          localPath: file.path,
          type: MediaType.image,
          title: 'Obraz wygenerowany przez AI');
      showError(context, 'Obraz wygenerowany i dodany do ćwiczenia.');
    } catch (error) {
      if (mounted)
        showError(context,
            'Nie udało się wygenerować obrazu: ${friendlyAiErrorMessage(error)}');
    } finally {
      if (mounted) setState(() => _generatingImage = false);
    }
  }

  // ===== Etap 27: zarządzanie multimediami w formularzu =====

  void _showMediaError(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context)
        .showSnackBar(SnackBar(content: Text(message)));
  }

  /// Dodaje nowe medium do listy roboczej. Pierwsze dodane staje się główne.
  void _appendMedia({
    String? localPath,
    String? remoteUrl,
    required MediaType type,
    String title = '',
  }) {
    var resolved = type;
    final lowerLocal = localPath?.toLowerCase() ?? '';
    // Drobne dostrojenie: jeśli „zdjęcie" jest faktycznie GIF-em, oznacz jako animację.
    if (resolved == MediaType.image && lowerLocal.endsWith('.gif')) {
      resolved = MediaType.gif;
    }
    final media = ExerciseMedia(
      id: 'media_${idNow()}_${mediaItems.length}',
      exerciseId: widget.exercise?.id ?? '',
      type: resolved,
      localPath: localPath,
      remoteUrl: remoteUrl,
      title: title,
      isPrimary: mediaItems.isEmpty,
      createdAt: DateTime.now(),
    );
    setState(() {
      mediaItems.add(media);
      _mediaExpanded = true;
    });
  }

  Future<void> _pickImageMedia({
    required ImageSource source,
    required MediaType type,
    required String title,
  }) async {
    try {
      final XFile? file =
          await _mediaPicker.pickImage(source: source, imageQuality: 85);
      if (file == null) return; // Użytkownik anulował wybór — nic nie robimy.
      _appendMedia(localPath: file.path, type: type, title: title);
    } catch (_) {
      _showMediaError('Nie udało się dodać medium. Sprawdź uprawnienia.');
    }
  }

  Future<void> _pickVideoMedia() async {
    try {
      final XFile? file =
          await _mediaPicker.pickVideo(source: ImageSource.gallery);
      if (file == null) return; // anulowano
      _appendMedia(
          localPath: file.path,
          type: MediaType.video,
          title: 'Wideo z galerii');
    } catch (_) {
      _showMediaError('Nie udało się dodać wideo. Sprawdź uprawnienia.');
    }
  }

  Future<void> _addVideoLink() async {
    final controller = TextEditingController();
    final formKey = GlobalKey<FormState>();
    final url = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Link do wideo'),
        content: Form(
          key: formKey,
          child: TextFormField(
            controller: controller,
            autofocus: true,
            keyboardType: TextInputType.url,
            decoration: const InputDecoration(
              labelText: 'Adres URL',
              hintText: 'https://...',
            ),
            validator: (value) {
              final text = value?.trim() ?? '';
              if (text.isEmpty) return 'Podaj link do wideo.';
              if (!text.startsWith('http://') && !text.startsWith('https://')) {
                return 'Link musi zaczynać się od http(s).';
              }
              return null;
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('Anuluj'),
          ),
          FilledButton(
            onPressed: () {
              if (formKey.currentState?.validate() ?? false) {
                Navigator.of(dialogContext).pop(controller.text.trim());
              }
            },
            child: const Text('Dodaj'),
          ),
        ],
      ),
    );
    controller.dispose();
    if (url == null || url.isEmpty) return; // anulowano / puste
    _appendMedia(remoteUrl: url, type: MediaType.url, title: 'Wideo (link)');
  }

  Future<void> _addAssetPlaceholder() async {
    final selected = await showModalBottomSheet<
        ({String path, MediaType type, String title})>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) => SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Padding(
              padding: EdgeInsets.fromLTRB(16, 4, 16, 8),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text('Wbudowane multimedia',
                    style:
                        TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
              ),
            ),
            for (final asset in kBuiltInExerciseMediaAssets)
              ListTile(
                leading: Icon(mediaTypeIcon(asset.type)),
                title: Text(asset.title),
                subtitle: Text(asset.path,
                    maxLines: 1, overflow: TextOverflow.ellipsis),
                onTap: () => Navigator.of(sheetContext).pop(asset),
              ),
          ],
        ),
      ),
    );
    if (selected == null) return; // anulowano
    _appendMedia(
        localPath: selected.path, type: selected.type, title: selected.title);
  }

  void _setPrimaryMedia(String id) {
    setState(() {
      mediaItems = [
        for (final media in mediaItems)
          media.copyWith(isPrimary: media.id == id),
      ];
    });
  }

  void _deleteMedia(String id) {
    setState(() {
      final removed = mediaItems.where((media) => media.id == id).toList();
      final wasPrimary = removed.isNotEmpty && removed.first.isPrimary;
      mediaItems.removeWhere((media) => media.id == id);
      // Jeśli usunęliśmy główne medium — wypromuj pierwsze z pozostałych.
      if (wasPrimary &&
          mediaItems.isNotEmpty &&
          !mediaItems.any((media) => media.isPrimary)) {
        mediaItems[0] = mediaItems[0].copyWith(isPrimary: true);
      }
    });
  }

  Future<void> _openAddMediaSheet() async {
    await showModalBottomSheet<void>(
      context: context,
      showDragHandle: true,
      builder: (sheetContext) {
        Widget option(
            IconData icon, String label, Future<void> Function() action) {
          return ListTile(
            leading: Icon(icon),
            title: Text(label),
            onTap: () async {
              Navigator.of(sheetContext).pop();
              await action();
            },
          );
        }

        return SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Padding(
                padding: EdgeInsets.fromLTRB(16, 4, 16, 8),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text('Dodaj multimedia',
                      style:
                          TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
                ),
              ),
              option(
                  Icons.photo_library_outlined,
                  'Zdjęcie z galerii',
                  () => _pickImageMedia(
                      source: ImageSource.gallery,
                      type: MediaType.image,
                      title: 'Zdjęcie z galerii')),
              option(
                  Icons.photo_camera_outlined,
                  'Zrób zdjęcie aparatem',
                  () => _pickImageMedia(
                      source: ImageSource.camera,
                      type: MediaType.image,
                      title: 'Zdjęcie z aparatu')),
              option(
                  Icons.gif_box_outlined,
                  'GIF z galerii',
                  () => _pickImageMedia(
                      source: ImageSource.gallery,
                      type: MediaType.gif,
                      title: 'GIF z galerii')),
              option(Icons.movie_outlined, 'Wideo z galerii', _pickVideoMedia),
              option(Icons.link_rounded, 'Link do wideo', _addVideoLink),
              option(Icons.collections_bookmark_outlined, 'Asset / placeholder',
                  _addAssetPlaceholder),
            ],
          ),
        );
      },
    );
  }

  Future<void> _openAddMuscleSheet() async {
    final available =
        BodyMuscle.values.where((m) => !_muscleRoles.containsKey(m)).toList();
    final picked = await showModalBottomSheet<BodyMuscle>(
      context: context,
      showDragHandle: true,
      isScrollControlled: true,
      useSafeArea: true,
      builder: (sheetContext) {
        List<BodyMuscle> onSide(BodyMuscleSide side) =>
            available.where((m) => musclesOnSide(side).contains(m)).toList();
        Widget group(String title, List<BodyMuscle> muscles) {
          if (muscles.isEmpty) return const SizedBox.shrink();
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 4),
                child: Text(title,
                    style: const TextStyle(fontWeight: FontWeight.w900)),
              ),
              for (final muscle in muscles)
                ListTile(
                  dense: true,
                  title: Text(muscle.label),
                  onTap: () => Navigator.of(sheetContext).pop(muscle),
                ),
            ],
          );
        }

        return FractionallySizedBox(
          heightFactor: 0.86,
          child: ListView(
            children: [
              const Padding(
                padding: EdgeInsets.fromLTRB(16, 4, 16, 4),
                child: Text('Dodaj partię mięśniową',
                    style:
                        TextStyle(fontWeight: FontWeight.w900, fontSize: 16)),
              ),
              group('Przód', onSide(BodyMuscleSide.front)),
              group('Tył', onSide(BodyMuscleSide.back)),
              if (available.isEmpty)
                const Padding(
                    padding: EdgeInsets.all(24),
                    child: Center(child: Text('Wszystkie partie już dodane.'))),
            ],
          ),
        );
      },
    );
    if (picked != null) {
      setState(() {
        _muscleRoles[picked] = MuscleRole.primary;
        _musclesExpanded = true;
      });
    }
  }

  Widget _buildMuscleRow(ThemeData theme, BodyMuscle muscle, MuscleRole role) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        children: [
          Expanded(
            child: Text(muscle.label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: theme.textTheme.bodyMedium
                    ?.copyWith(fontWeight: FontWeight.w700)),
          ),
          const SizedBox(width: 8),
          DropdownButton<MuscleRole>(
            value: role,
            isDense: true,
            underline: const SizedBox.shrink(),
            onChanged: (value) {
              if (value != null) setState(() => _muscleRoles[muscle] = value);
            },
            items: [
              for (final r in MuscleRole.values)
                DropdownMenuItem(value: r, child: Text(r.label)),
            ],
          ),
          IconButton(
            visualDensity: VisualDensity.compact,
            tooltip: 'Usuń',
            onPressed: () => setState(() => _muscleRoles.remove(muscle)),
            icon: const Icon(Icons.close_rounded),
          ),
        ],
      ),
    );
  }

