List<String> _splitExerciseField(String value) {
  return value
      .split(RegExp(r'[\n,;]+'))
      .map((item) => item.trim())
      .where((item) => item.isNotEmpty)
      .toList();
}

Future<void> showAddWorkoutSheet(BuildContext context,
    {Exercise? exercise, WorkoutLog? existing, PlanItem? fromPlan}) async {
  final store = AppScope.read(context);
  await showModalBottomSheet(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    builder: (sheetContext) => AddWorkoutSheetContent(
        store: store,
        exercise: exercise,
        existing: existing,
        fromPlan: fromPlan),
  );
}

class AddWorkoutSheetContent extends StatefulWidget {
  final AppStore store;
  final Exercise? exercise;
  final WorkoutLog? existing;
  final PlanItem? fromPlan;

  const AddWorkoutSheetContent(
      {super.key,
      required this.store,
      this.exercise,
      this.existing,
      this.fromPlan});

  @override
  State<AddWorkoutSheetContent> createState() => _AddWorkoutSheetContentState();
}

class _AddWorkoutSheetContentState extends State<AddWorkoutSheetContent> {
  late Exercise selectedExercise;
  late final TextEditingController sets;
  late final TextEditingController reps;
  late final TextEditingController weight;
  late final TextEditingController duration;
  late final TextEditingController calories;
  late final TextEditingController note;
  late int rpe;

  AppStore get store => widget.store;

  @override
  void initState() {
    super.initState();
    selectedExercise = widget.exercise ??
        widget.existing?.exerciseFrom(store.customExercises) ??
        ExerciseRepo.all.first;
    sets = TextEditingController(
        text:
            '${widget.existing?.sets ?? widget.fromPlan?.sets ?? selectedExercise.defaultSets}');
    reps = TextEditingController(
        text:
            '${widget.existing?.reps ?? widget.fromPlan?.reps ?? selectedExercise.defaultReps}');
    weight = TextEditingController(
        text: (widget.existing?.weightKg ?? 0).toStringAsFixed(1));
    duration = TextEditingController(
        text:
            '${((widget.existing?.durationSec ?? widget.fromPlan?.durationSec ?? selectedExercise.defaultDurationSec) / 60).round()}');
    calories = TextEditingController(
        text: widget.existing?.calories.toStringAsFixed(0) ?? '');
    note = TextEditingController(
        text: widget.existing?.note ?? widget.fromPlan?.note ?? '');
    rpe = widget.existing?.rpe ?? 7;
  }

  @override
  void dispose() {
    sets.dispose();
    reps.dispose();
    weight.dispose();
    duration.dispose();
    calories.dispose();
    note.dispose();
    super.dispose();
  }

  void recalcCalories() {
    final minutes = double.tryParse(duration.text.replaceAll(',', '.')) ??
        _estimateMinutes(selectedExercise, sets.text, reps.text);
    final kcal = estimateCalories(
        met: selectedExercise.met,
        weightKg: store.settings.bodyWeightKg,
        minutes: minutes);
    setState(() => calories.text = kcal.toStringAsFixed(0));
  }

  Future<void> save() async {
    final minutes = double.tryParse(duration.text.replaceAll(',', '.')) ??
        _estimateMinutes(selectedExercise, sets.text, reps.text);
    final log = WorkoutLog(
      id: widget.existing?.id ?? idNow(),
      exerciseId: selectedExercise.id,
      date: store.selectedDate,
      sets: int.tryParse(sets.text) ?? selectedExercise.defaultSets,
      reps: int.tryParse(reps.text) ?? selectedExercise.defaultReps,
      weightKg: double.tryParse(weight.text.replaceAll(',', '.')) ?? 0,
      durationSec: (minutes * 60).round(),
      rpe: rpe,
      calories: double.tryParse(calories.text.replaceAll(',', '.')) ??
          estimateCalories(
              met: selectedExercise.met,
              weightKg: store.settings.bodyWeightKg,
              minutes: minutes),
      note: note.text.trim(),
      aiConfidence: widget.existing?.aiConfidence ?? 0,
    );
    if (widget.existing == null) {
      await store.addLog(log);
    } else {
      await store.updateLog(log);
    }
    if (!mounted) return;
    Navigator.of(context).pop();
  }

  @override
  Widget build(BuildContext context) {
    final exercises = ExerciseRepo.combined(store.customExercises);
    return Padding(
      padding: EdgeInsets.fromLTRB(
          16,
          0,
          16,
          16 +
              MediaQuery.of(context).viewInsets.bottom +
              MediaQuery.of(context).viewPadding.bottom),
      child: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text(
                widget.existing == null
                    ? 'Dodaj ćwiczenie'
                    : 'Edytuj ćwiczenie',
                style: Theme.of(context)
                    .textTheme
                    .titleLarge
                    ?.copyWith(fontWeight: FontWeight.w900)),
            const SizedBox(height: 12),
            Row(
              children: [
                SizedBox(
                    width: 92,
                    height: 92,
                    child: ExerciseVisual(exercise: selectedExercise)),
                const SizedBox(width: 12),
                Expanded(
                  child: DropdownButtonFormField<String>(
                    isExpanded: true,
                    value: exercises.any((e) => e.id == selectedExercise.id)
                        ? selectedExercise.id
                        : exercises.first.id,
                    decoration: const InputDecoration(labelText: 'Ćwiczenie'),
                    selectedItemBuilder: (context) => exercises
                        .map((x) => Align(
                            alignment: Alignment.centerLeft,
                            child: Text(x.name,
                                maxLines: 1, overflow: TextOverflow.ellipsis)))
                        .toList(),
                    items: exercises
                        .map((x) => DropdownMenuItem(
                            value: x.id,
                            child: Text(x.name,
                                maxLines: 1, overflow: TextOverflow.ellipsis)))
                        .toList(),
                    onChanged: (id) {
                      if (id == null) return;
                      setState(() {
                        selectedExercise =
                            ExerciseRepo.byId(id, store.customExercises);
                        sets.text = '${selectedExercise.defaultSets}';
                        reps.text = '${selectedExercise.defaultReps}';
                        duration.text =
                            '${(selectedExercise.defaultDurationSec / 60).round()}';
                      });
                      recalcCalories();
                    },
                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                  child: TextField(
                      controller: sets,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(labelText: 'Serie'))),
              const SizedBox(width: 10),
              Expanded(
                  child: TextField(
                      controller: reps,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(labelText: 'Powt.'))),
            ]),
            const SizedBox(height: 10),
            Row(children: [
              Expanded(
                  child: TextField(
                      controller: weight,
                      keyboardType: TextInputType.number,
                      decoration:
                          const InputDecoration(labelText: 'Ciężar kg'))),
              const SizedBox(width: 10),
              Expanded(
                  child: TextField(
                      controller: duration,
                      keyboardType: TextInputType.number,
                      decoration:
                          const InputDecoration(labelText: 'Czas min'))),
            ]),
            const SizedBox(height: 10),
            Row(children: [
              Expanded(
                  child: TextField(
                      controller: calories,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(labelText: 'Kalorie'))),
              const SizedBox(width: 10),
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(labelText: 'RPE'),
                  child: DropdownButtonHideUnderline(
                    child: DropdownButton<int>(
                        value: rpe,
                        isExpanded: true,
                        items: List.generate(10, (i) => i + 1)
                            .map((v) => DropdownMenuItem(
                                value: v, child: Text('$v/10')))
                            .toList(),
                        onChanged: (v) => setState(() => rpe = v ?? rpe)),
                  ),
                ),
              ),
            ]),
            const SizedBox(height: 10),
            TextField(
                controller: note,
                maxLines: 3,
                decoration: const InputDecoration(labelText: 'Notatka')),
            const SizedBox(height: 10),
            OutlinedButton.icon(
                onPressed: recalcCalories,
                icon: const Icon(Icons.calculate),
                label: const Text('Przelicz kalorie lokalnie')),
            const SizedBox(height: 10),
            FilledButton.icon(
              onPressed: save,
              icon: const Icon(Icons.save),
              label: Text(widget.existing == null
                  ? 'Dodaj do dziennika'
                  : 'Zapisz zmiany'),
            ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }
}

double _estimateMinutes(Exercise e, String setsText, String repsText) {
  if (e.defaultDurationSec > 0) {
    final sets = int.tryParse(setsText) ?? e.defaultSets;
    return (sets * e.defaultDurationSec) / 60;
  }
  final sets = int.tryParse(setsText) ?? e.defaultSets;
  final reps = int.tryParse(repsText) ?? e.defaultReps;
  return math.max(3.0, sets * reps * 3 / 60 + sets * 1.25);
}

double estimateCalories(
    {required double met, required double weightKg, required double minutes}) {
  if (met <= 1 || weightKg <= 0 || minutes <= 0) return 0;
  // Baza Miffina zawiera już koszt spoczynku (1 MET), dlatego trening,
  // bieg i chód dopisują wyłącznie energię aktywną ponad spoczynek.
  return (met - 1) * 3.5 * weightKg / 200 * minutes;
}

