class HumanExerciseImage extends StatelessWidget {
  final String type;
  final double? size;
  final Color? lineColor;
  final Color? backgroundColor;

  const HumanExerciseImage(
      {super.key,
      required this.type,
      this.size,
      this.lineColor,
      this.backgroundColor});

  @override
  Widget build(BuildContext context) {
    return HumanExerciseFrame(
      type: type,
      size: size,
      progress: 0.55,
      lineColor: lineColor,
      backgroundColor: backgroundColor,
    );
  }
}

class HumanExerciseFrame extends StatelessWidget {
  final String type;
  final double progress;
  final double? size;
  final Color? lineColor;
  final Color? backgroundColor;

  const HumanExerciseFrame(
      {super.key,
      required this.type,
      required this.progress,
      this.size,
      this.lineColor,
      this.backgroundColor});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final child = CustomPaint(
      painter: HumanExercisePainter(
        type: type,
        progress: progress.clamp(0.0, 1.0),
        bodyColor: lineColor ?? theme.colorScheme.primary,
        backgroundColor: backgroundColor ??
            theme.colorScheme.primaryContainer.withOpacity(0.45),
        accentColor: theme.colorScheme.tertiary,
      ),
      child: const SizedBox.expand(),
    );
    if (size != null) return SizedBox(width: size, height: size, child: child);
    return child;
  }
}

class HumanExercisePainter extends CustomPainter {
  final String type;
  final double progress;
  final Color bodyColor;
  final Color backgroundColor;
  final Color accentColor;

  HumanExercisePainter(
      {required this.type,
      required this.progress,
      required this.bodyColor,
      required this.backgroundColor,
      required this.accentColor});

  @override
  void paint(Canvas canvas, Size size) {
    final s = math.min(size.width, size.height);
    final offset = Offset((size.width - s) / 2, (size.height - s) / 2);
    canvas.save();
    canvas.translate(offset.dx, offset.dy);
    canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTWH(0, 0, s, s), Radius.circular(s * 0.22)),
        Paint()..color = backgroundColor);

    final floor = Paint()
      ..color = bodyColor.withOpacity(0.18)
      ..strokeWidth = s * 0.018
      ..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(s * .15, s * .88), Offset(s * .88, s * .88), floor);

    Offset o(double x, double y) => Offset(x * s, y * s);
    void limb(Offset a, Offset b, {double w = 0.075, Color? color}) {
      final p = Paint()
        ..color = color ?? bodyColor
        ..strokeWidth = s * w
        ..strokeCap = StrokeCap.round
        ..strokeJoin = StrokeJoin.round;
      canvas.drawLine(a, b, p);
    }

    void torso(Offset neck, Offset hip) {
      final p = Paint()..color = bodyColor;
      final rect = Rect.fromCenter(
          center: Offset((neck.dx + hip.dx) / 2, (neck.dy + hip.dy) / 2),
          width: s * 0.16,
          height: (hip - neck).distance + s * 0.10);
      canvas.save();
      final angle =
          math.atan2(hip.dy - neck.dy, hip.dx - neck.dx) - math.pi / 2;
      canvas.translate(rect.center.dx, rect.center.dy);
      canvas.rotate(angle);
      canvas.drawRRect(
          RRect.fromRectAndRadius(
              Rect.fromCenter(
                  center: Offset.zero, width: rect.width, height: rect.height),
              Radius.circular(s * 0.08)),
          p);
      canvas.restore();
    }

    void head(Offset c) {
      canvas.drawCircle(c, s * .07, Paint()..color = bodyColor);
      canvas.drawCircle(c.translate(s * .025, -s * .012), s * .012,
          Paint()..color = Colors.white.withOpacity(0.75));
    }

    void dumbbell(Offset c) {
      final p = Paint()
        ..color = accentColor
        ..strokeWidth = s * 0.035
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(c.translate(-s * .05, 0), c.translate(s * .05, 0), p);
      canvas.drawCircle(
          c.translate(-s * .065, 0), s * .025, Paint()..color = accentColor);
      canvas.drawCircle(
          c.translate(s * .065, 0), s * .025, Paint()..color = accentColor);
    }

    final t = progress;
    late Offset h, n, hip, ls, rs, le, re, lh, rh, lk, rk, lf, rf;
    bool bar = false;
    bool db = false;
    bool bike = false;

    final lower = type.toLowerCase();
    if (lower.contains('pushup') ||
        lower.contains('plank') ||
        lower.contains('mountain')) {
      final down = lower.contains('pushup') ? t * .14 : 0.0;
      h = o(.22, .45 + down);
      n = o(.30, .49 + down);
      hip = o(.68, .57 + (lower.contains('mountain') ? 0 : down * .6));
      ls = o(.38, .50 + down);
      rs = o(.42, .53 + down);
      le = o(.33, .74);
      re = o(.45, .74);
      lh = o(.28, .82);
      rh = o(.50, .82);
      lk = lower.contains('mountain') ? o(.55 + .18 * t, .78) : o(.78, .78);
      rk = lower.contains('mountain') ? o(.86 - .22 * t, .80) : o(.86, .80);
      lf = o(.60 + .18 * t, .84);
      rf = o(.90 - .18 * t, .84);
    } else if (lower.contains('lunge')) {
      final down = t * .10;
      h = o(.50, .23 + down);
      n = o(.50, .34 + down);
      hip = o(.50, .56 + down);
      ls = o(.43, .38 + down);
      rs = o(.57, .38 + down);
      le = o(.34, .50 + down);
      re = o(.66, .50 + down);
      lh = o(.30, .60 + down);
      rh = o(.70, .60 + down);
      lk = o(.34, .70 + down);
      rk = o(.70, .70);
      lf = o(.24, .88);
      rf = o(.84, .88);
    } else if (lower.contains('deadlift') || lower.contains('row')) {
      final bend = .18 + t * .16;
      h = o(.45 + bend, .25 + bend * .5);
      n = o(.50 + bend, .36 + bend * .3);
      hip = o(.56 + bend, .58);
      ls = o(.48 + bend, .40);
      rs = o(.60 + bend, .43);
      le = o(.34 + t * .08, .62);
      re = o(.74 - t * .08, .62);
      lh = o(.28 + t * .12, .76);
      rh = o(.80 - t * .12, .76);
      lk = o(.44, .72);
      rk = o(.68, .72);
      lf = o(.38, .88);
      rf = o(.74, .88);
      db = true;
    } else if (lower.contains('pull')) {
      h = o(.50, .38 - t * .13);
      n = o(.50, .48 - t * .12);
      hip = o(.50, .68 - t * .08);
      ls = o(.42, .48 - t * .12);
      rs = o(.58, .48 - t * .12);
      le = o(.35, .28 + t * .03);
      re = o(.65, .28 + t * .03);
      lh = o(.30, .16);
      rh = o(.70, .16);
      lk = o(.44, .80 - t * .05);
      rk = o(.58, .80 - t * .05);
      lf = o(.40, .88);
      rf = o(.62, .88);
      bar = true;
    } else if (lower.contains('bench')) {
      h = o(.30, .62);
      n = o(.38, .64);
      hip = o(.66, .66);
      ls = o(.45, .62);
      rs = o(.57, .62);
      le = o(.42, .48 - t * .18);
      re = o(.64, .48 - t * .18);
      lh = o(.34, .43 - t * .18);
      rh = o(.72, .43 - t * .18);
      lk = o(.75, .72);
      rk = o(.84, .76);
      lf = o(.74, .88);
      rf = o(.88, .88);
      bar = true;
      canvas.drawLine(
          o(.18, .76),
          o(.86, .76),
          Paint()
            ..color = bodyColor.withOpacity(.25)
            ..strokeWidth = s * .035
            ..strokeCap = StrokeCap.round);
    } else if (lower.contains('bike')) {
      bike = true;
      h = o(.52, .30);
      n = o(.51, .39);
      hip = o(.50, .57);
      ls = o(.47, .42);
      rs = o(.56, .42);
      le = o(.58, .48);
      re = o(.64, .50);
      lh = o(.66, .50);
      rh = o(.72, .50);
      lk = o(.44, .73);
      rk = o(.63, .70);
      lf = o(.35, .76);
      rf = o(.68, .76);
    } else if (lower.contains('run') || lower.contains('highknees')) {
      h = o(.50, .22);
      n = o(.50, .32);
      hip = o(.50, .57);
      ls = o(.43, .38);
      rs = o(.57, .38);
      le = o(.36 + .12 * t, .50);
      re = o(.64 - .12 * t, .50);
      lh = o(.30 + .12 * t, .63);
      rh = o(.70 - .12 * t, .63);
      lk = o(.36 + .18 * t, .72 - .18 * t);
      rk = o(.66 - .18 * t, .72 + .05 * t);
      lf = o(.30, .88);
      rf = o(.74 - .16 * t, .88);
    } else if (lower.contains('squat')) {
      final down = t;
      h = o(.50, .24 + down * .08);
      n = o(.50, .34 + down * .08);
      hip = o(.50, .55 + down * .14);
      ls = o(.43, .40 + down * .05);
      rs = o(.57, .40 + down * .05);
      le = o(.34, .50 + down * .04);
      re = o(.66, .50 + down * .04);
      lh = o(.28, .58 + down * .04);
      rh = o(.72, .58 + down * .04);
      lk = o(.36, .70 + down * .02);
      rk = o(.64, .70 + down * .02);
      lf = o(.28, .88);
      rf = o(.72, .88);
    } else {
      final move = (t - .5) * .10;
      h = o(.50, .23);
      n = o(.50, .34);
      hip = o(.50, .58);
      ls = o(.42, .40);
      rs = o(.58, .40);
      le = o(.34 + move, .54 - t * .10);
      re = o(.66 - move, .54 - t * .10);
      lh = o(.30 + move, .68 - t * .14);
      rh = o(.70 - move, .68 - t * .14);
      lk = o(.42 + move, .75);
      rk = o(.58 - move, .75);
      lf = o(.36 + move, .88);
      rf = o(.64 - move, .88);
      db = lower.contains('curl') ||
          lower.contains('raise') ||
          lower.contains('press');
    }

    if (bike) {
      final wheel = Paint()
        ..color = bodyColor.withOpacity(.40)
        ..style = PaintingStyle.stroke
        ..strokeWidth = s * .035;
      canvas.drawCircle(o(.32, .77), s * .13, wheel);
      canvas.drawCircle(o(.72, .77), s * .13, wheel);
      limb(o(.32, .77), o(.50, .57),
          w: .035, color: bodyColor.withOpacity(.45));
      limb(o(.50, .57), o(.72, .77),
          w: .035, color: bodyColor.withOpacity(.45));
      limb(o(.44, .50), o(.62, .50),
          w: .035, color: bodyColor.withOpacity(.45));
    }
    if (bar) limb(o(.22, .16), o(.78, .16), w: .035, color: accentColor);

    limb(ls, le);
    limb(le, lh);
    limb(rs, re);
    limb(re, rh);
    limb(hip, lk);
    limb(lk, lf);
    limb(hip, rk);
    limb(rk, rf);
    torso(n, hip);
    head(h);
    if (db) {
      dumbbell(lh);
      dumbbell(rh);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant HumanExercisePainter oldDelegate) =>
      oldDelegate.type != type ||
      oldDelegate.progress != progress ||
      oldDelegate.bodyColor != bodyColor ||
      oldDelegate.backgroundColor != backgroundColor ||
      oldDelegate.accentColor != accentColor;
}

// ============================================================
// Etap 18: Widget sugestii progresji
// ============================================================

class ProgressionSuggestionCard extends StatelessWidget {
  const ProgressionSuggestionCard({
    super.key,
    required this.exerciseId,
    required this.exerciseName,
    required this.logs,
    required this.plannedReps,
    required this.plannedWeightKg,
    this.planId,
    this.weekday,
    this.onApplied,
  });

  final String exerciseId;
  final String exerciseName;
  final List<WorkoutLog> logs;
  final int plannedReps;
  final double plannedWeightKg;
  final String? planId;
  final int? weekday;
  final VoidCallback? onApplied;

  Color _actionColor(ProgressionAction action, ColorScheme scheme) {
    switch (action) {
      case ProgressionAction.increaseWeight:
      case ProgressionAction.increaseReps:
        return Colors.green;
      case ProgressionAction.maintain:
        return scheme.primary;
      case ProgressionAction.decreaseWeight:
        return Colors.orange;
      case ProgressionAction.deload:
        return Colors.deepOrange;
    }
  }

  @override
  Widget build(BuildContext context) {
    final store = AppScope.of(context);
    final suggestion = progressionSuggestionForExercise(
      exerciseId: exerciseId,
      allLogs: logs,
      plannedReps: plannedReps,
      plannedWeightKg: plannedWeightKg,
      exercise: ExerciseRepo.byId(exerciseId, store.customExercises),
    );
    if (suggestion == null) return const SizedBox.shrink();

    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    final color = _actionColor(suggestion.action, scheme);

    return Card(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Row(
              children: [
                Icon(suggestion.icon, color: color, size: 20),
                const SizedBox(width: 8),
                Expanded(
                  child: Text(
                    suggestion.label,
                    style: theme.textTheme.titleSmall
                        ?.copyWith(fontWeight: FontWeight.w800, color: color),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(suggestion.reason,
                style: theme.textTheme.bodySmall
                    ?.copyWith(color: scheme.onSurfaceVariant, height: 1.4)),
            if (suggestion.hasNewValues &&
                planId != null &&
                weekday != null) ...[
              const SizedBox(height: 10),
              Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Sugerowany ciężar',
                            style: theme.textTheme.labelSmall
                                ?.copyWith(color: scheme.onSurfaceVariant)),
                        Text(
                          suggestion.suggestedWeightKg > 0
                              ? '${_formatPlanWeight(suggestion.suggestedWeightKg)} kg'
                              : 'bez ciężaru',
                          style: theme.textTheme.bodyMedium
                              ?.copyWith(fontWeight: FontWeight.w700),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text('Sugerowane powtórzenia',
                            style: theme.textTheme.labelSmall
                                ?.copyWith(color: scheme.onSurfaceVariant)),
                        Text('${suggestion.suggestedReps}',
                            style: theme.textTheme.bodyMedium
                                ?.copyWith(fontWeight: FontWeight.w700)),
                      ],
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 10),
              OutlinedButton.icon(
                onPressed: () async {
                  final confirmed = await showDialog<bool>(
                    context: context,
                    builder: (ctx) => AlertDialog(
                      title: Text('Zastosować sugestię dla „$exerciseName"?'),
                      content: Text(
                        'Ciężar w planie zmieni się z ${_formatPlanWeight(suggestion.currentWeightKg)} kg'
                        ' na ${_formatPlanWeight(suggestion.suggestedWeightKg)} kg'
                        ', powtórzenia: ${suggestion.currentReps} → ${suggestion.suggestedReps}.',
                      ),
                      actions: [
                        TextButton(
                            onPressed: () => Navigator.pop(ctx, false),
                            child: const Text('Anuluj')),
                        FilledButton(
                            onPressed: () => Navigator.pop(ctx, true),
                            child: const Text('Zastosuj')),
                      ],
                    ),
                  );
                  if (confirmed != true || !context.mounted) return;
                  // Zachowaj istniejące dane planu, zmień tylko ciężar i powtórzenia
                  final activePlan = store.activeWorkoutPlan;
                  final existingItem = activePlan?.days
                      .where((d) => d.weekday == weekday)
                      .expand((d) => d.items)
                      .where((it) => it.exerciseId == exerciseId)
                      .firstOrNull;
                  await store.upsertPlanItem(
                    planId: planId!,
                    weekday: weekday!,
                    item: PlanItem(
                      exerciseId: exerciseId,
                      sets: existingItem?.sets ?? 3,
                      reps: suggestion.suggestedReps,
                      durationSec: existingItem?.durationSec ?? 0,
                      note: existingItem?.note ?? '',
                      suggestedWeightKg: suggestion.suggestedWeightKg,
                      restSeconds: existingItem?.restSeconds ?? 90,
                    ),
                  );
                  if (context.mounted) {
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                          content:
                              Text('Zaktualizowano „$exerciseName" w planie.')),
                    );
                    onApplied?.call();
                  }
                },
                icon: const Icon(Icons.check_circle_outline_rounded, size: 18),
                label: const Text('Zastosuj sugestię'),
              ),
            ],
          ],
        ),
      ),
    );
  }
}
